static void RENAME(extract_odd2avg)(const uint8_t *src0, const uint8_t *src1, uint8_t *dst0, uint8_t *dst1, x86_reg count)

{

    dst0 +=   count;

    dst1 +=   count;

    src0 += 4*count;

    src1 += 4*count;

    count= - count;

#ifdef PAVGB

    if(count <= -8) {

        count += 7;

        __asm__ volatile(

            "pcmpeqw        %%mm7, %%mm7        \n\t"

            "psrlw             $8, %%mm7        \n\t"

            "1:                                \n\t"

            "movq  -28(%1, %0, 4), %%mm0        \n\t"

            "movq  -20(%1, %0, 4), %%mm1        \n\t"

            "movq  -12(%1, %0, 4), %%mm2        \n\t"

            "movq   -4(%1, %0, 4), %%mm3        \n\t"

            PAVGB" -28(%2, %0, 4), %%mm0        \n\t"

            PAVGB" -20(%2, %0, 4), %%mm1        \n\t"

            PAVGB" -12(%2, %0, 4), %%mm2        \n\t"

            PAVGB" - 4(%2, %0, 4), %%mm3        \n\t"

            "psrlw             $8, %%mm0        \n\t"

            "psrlw             $8, %%mm1        \n\t"

            "psrlw             $8, %%mm2        \n\t"

            "psrlw             $8, %%mm3        \n\t"

            "packuswb       %%mm1, %%mm0        \n\t"

            "packuswb       %%mm3, %%mm2        \n\t"

            "movq           %%mm0, %%mm1        \n\t"

            "movq           %%mm2, %%mm3        \n\t"

            "psrlw             $8, %%mm0        \n\t"

            "psrlw             $8, %%mm2        \n\t"

            "pand           %%mm7, %%mm1        \n\t"

            "pand           %%mm7, %%mm3        \n\t"

            "packuswb       %%mm2, %%mm0        \n\t"

            "packuswb       %%mm3, %%mm1        \n\t"

            MOVNTQ"         %%mm0,- 7(%4, %0)   \n\t"

            MOVNTQ"         %%mm1,- 7(%3, %0)   \n\t"

            "add               $8, %0           \n\t"

            " js 1b                            \n\t"

            : "+r"(count)

            : "r"(src0), "r"(src1), "r"(dst0), "r"(dst1)

        );

        count -= 7;

    }

#endif

    src0++;

    src1++;

    while(count<0) {

        dst0[count]= (src0[4*count+0]+src1[4*count+0])>>1;

        dst1[count]= (src0[4*count+2]+src1[4*count+2])>>1;

        count++;

    }

}

static gboolean qio_channel_websock_handshake_send(QIOChannel *ioc,

                                                   GIOCondition condition,

                                                   gpointer user_data)

{

    QIOTask *task = user_data;

    QIOChannelWebsock *wioc = QIO_CHANNEL_WEBSOCK(

        qio_task_get_source(task));

    Error *err = NULL;

    ssize_t ret;



    ret = qio_channel_write(wioc->master,

                            (char *)wioc->encoutput.buffer,

                            wioc->encoutput.offset,

                            &err);



    if (ret < 0) {

        trace_qio_channel_websock_handshake_fail(ioc);

        qio_task_set_error(task, err);

        qio_task_complete(task);

        return FALSE;

    }



    buffer_advance(&wioc->encoutput, ret);

    if (wioc->encoutput.offset == 0) {

        trace_qio_channel_websock_handshake_complete(ioc);

        qio_task_complete(task);

        return FALSE;

    }

    trace_qio_channel_websock_handshake_pending(ioc, G_IO_OUT);

    return TRUE;

}

static int pix_norm1_altivec(uint8_t *pix, int line_size)

{

    int i, s = 0;

    const vector unsigned int zero =

        (const vector unsigned int) vec_splat_u32(0);

    vector unsigned int sv = (vector unsigned int) vec_splat_u32(0);

    vector signed int sum;



    for (i = 0; i < 16; i++) {

        /* Read the potentially unaligned pixels. */

        //vector unsigned char pixl = vec_ld(0,  pix);

        //vector unsigned char pixr = vec_ld(15, pix);

        //vector unsigned char pixv = vec_perm(pixl, pixr, perm);

        vector unsigned char pixv = vec_vsx_ld(0,  pix);



        /* Square the values, and add them to our sum. */

        sv = vec_msum(pixv, pixv, sv);



        pix += line_size;

    }

    /* Sum up the four partial sums, and put the result into s. */

    sum = vec_sums((vector signed int) sv, (vector signed int) zero);

    sum = vec_splat(sum, 3);

    vec_vsx_st(sum, 0, &s);

    return s;

}

