                              PCI_DEVFN(11, 0), 4, TYPE_PCI_BUS);



    sysbus_mmio_map(s, 0, 0xf0800000);

    sysbus_mmio_map(s, 1, 0xf0c00000);



    pci_create_simple(h->bus, 11 << 3, "u3-agp");



    return h->bus;

}

