void hmp_info_block(Monitor *mon, const QDict *qdict)

{

    BlockInfoList *block_list, *info;

    ImageInfo *image_info;

    const char *device = qdict_get_try_str(qdict, "device");

    bool verbose = qdict_get_try_bool(qdict, "verbose", 0);



    block_list = qmp_query_block(NULL);



    for (info = block_list; info; info = info->next) {

        if (device && strcmp(device, info->value->device)) {

            continue;

        }



        if (info != block_list) {

            monitor_printf(mon, "\n");

        }



        monitor_printf(mon, "%s", info->value->device);

        if (info->value->has_inserted) {

            monitor_printf(mon, ": %s (%s%s%s)\n",

                           info->value->inserted->file,

                           info->value->inserted->drv,

                           info->value->inserted->ro ? ", read-only" : "",

                           info->value->inserted->encrypted ? ", encrypted" : "");

        } else {

            monitor_printf(mon, ": [not inserted]\n");

        }



        if (info->value->has_io_status && info->value->io_status != BLOCK_DEVICE_IO_STATUS_OK) {

            monitor_printf(mon, "    I/O status:       %s\n",

                           BlockDeviceIoStatus_lookup[info->value->io_status]);

        }



        if (info->value->removable) {

            monitor_printf(mon, "    Removable device: %slocked, tray %s\n",

                           info->value->locked ? "" : "not ",

                           info->value->tray_open ? "open" : "closed");

        }





        if (!info->value->has_inserted) {

            continue;

        }



        if (info->value->inserted->has_backing_file) {

            monitor_printf(mon,

                           "    Backing file:     %s "

                           "(chain depth: %" PRId64 ")\n",

                           info->value->inserted->backing_file,

                           info->value->inserted->backing_file_depth);

        }



        if (info->value->inserted->bps

            || info->value->inserted->bps_rd

            || info->value->inserted->bps_wr

            || info->value->inserted->iops

            || info->value->inserted->iops_rd

            || info->value->inserted->iops_wr)

        {

            monitor_printf(mon, "    I/O throttling:   bps=%" PRId64

                            " bps_rd=%" PRId64  " bps_wr=%" PRId64

                            " iops=%" PRId64 " iops_rd=%" PRId64

                            " iops_wr=%" PRId64 "\n",

                            info->value->inserted->bps,

                            info->value->inserted->bps_rd,

                            info->value->inserted->bps_wr,

                            info->value->inserted->iops,

                            info->value->inserted->iops_rd,

                            info->value->inserted->iops_wr);

        }



        if (verbose) {

            monitor_printf(mon, "\nImages:\n");

            image_info = info->value->inserted->image;

            while (1) {

                    bdrv_image_info_dump((fprintf_function)monitor_printf,

                                         mon, image_info);

                if (image_info->has_backing_image) {

                    image_info = image_info->backing_image;

                } else {

                    break;

                }

            }

        }

    }



    qapi_free_BlockInfoList(block_list);

}

static inline int decode_residual_inter(AVSContext *h) {

    int block;



    /* get coded block pattern */

    int cbp= get_ue_golomb(&h->s.gb);

    if(cbp > 63){

        av_log(h->s.avctx, AV_LOG_ERROR, "illegal inter cbp\n");

        return -1;

    }

    h->cbp = cbp_tab[cbp][1];



    /* get quantizer */

    if(h->cbp && !h->qp_fixed)

        h->qp = (h->qp + get_se_golomb(&h->s.gb)) & 63;

    for(block=0;block<4;block++)

        if(h->cbp & (1<<block))

            decode_residual_block(h,&h->s.gb,ff_cavs_inter_dec,0,h->qp,

                                  h->cy + h->luma_scan[block], h->l_stride);

    decode_residual_chroma(h);



    return 0;

}

static void fw_cfg_write(FWCfgState *s, uint8_t value)

{

    int arch = !!(s->cur_entry & FW_CFG_ARCH_LOCAL);

    FWCfgEntry *e = &s->entries[arch][s->cur_entry & FW_CFG_ENTRY_MASK];



    FW_CFG_DPRINTF("write %d\n", value);



    if (s->cur_entry & FW_CFG_WRITE_CHANNEL && s->cur_offset < e->len) {

        e->data[s->cur_offset++] = value;

        if (s->cur_offset == e->len) {

            e->callback(e->callback_opaque, e->data);

            s->cur_offset = 0;

        }

    }

}

int qemu_peek_buffer(QEMUFile *f, uint8_t *buf, int size, size_t offset)

{

    int pending;

    int index;



    assert(!qemu_file_is_writable(f));



    index = f->buf_index + offset;

    pending = f->buf_size - index;

    if (pending < size) {

        qemu_fill_buffer(f);

        index = f->buf_index + offset;

        pending = f->buf_size - index;

    }



    if (pending <= 0) {

        return 0;

    }

    if (size > pending) {

        size = pending;

    }



    memcpy(buf, f->buf + index, size);

    return size;

}

static int ahci_dma_rw_buf(IDEDMA *dma, int is_write)

{

    AHCIDevice *ad = DO_UPCAST(AHCIDevice, dma, dma);

    IDEState *s = &ad->port.ifs[0];

    uint8_t *p = s->io_buffer + s->io_buffer_index;

    int l = s->io_buffer_size - s->io_buffer_index;



    if (ahci_populate_sglist(ad, &s->sg)) {

        return 0;

    }



    if (is_write) {

        dma_buf_read(p, l, &s->sg);

    } else {

        dma_buf_write(p, l, &s->sg);

    }



    /* update number of transferred bytes */

    ad->cur_cmd->status = cpu_to_le32(le32_to_cpu(ad->cur_cmd->status) + l);

    s->io_buffer_index += l;



    DPRINTF(ad->port_no, "len=%#x\n", l);



    return 1;

}

void cpu_save(QEMUFile *f, void *opaque)

{

    CPUState *env = (CPUState *)opaque;

    unsigned int i, j;



    cpu_synchronize_state(env);



    for (i = 0; i < 32; i++)

        qemu_put_betls(f, &env->gpr[i]);

#if !defined(TARGET_PPC64)

    for (i = 0; i < 32; i++)

        qemu_put_betls(f, &env->gprh[i]);

#endif

    qemu_put_betls(f, &env->lr);

    qemu_put_betls(f, &env->ctr);

    for (i = 0; i < 8; i++)

        qemu_put_be32s(f, &env->crf[i]);

    qemu_put_betls(f, &env->xer);

