        return 0;



    tab_mvf = ref->tab_mvf;

    colPic  = ref->poc;



    //bottom right collocated motion vector

    x = x0 + nPbW;

    y = y0 + nPbH;



    if (tab_mvf &&

        (y0 >> s->sps->log2_ctb_size) == (y >> s->sps->log2_ctb_size) &&

        y < s->sps->height &&

        x < s->sps->width) {

        x                 &= ~15;

        y                 &= ~15;

        ff_thread_await_progress(&ref->tf, y, 0);

        x_pu               = x >> s->sps->log2_min_pu_size;

        y_pu               = y >> s->sps->log2_min_pu_size;

        temp_col           = TAB_MVF(x_pu, y_pu);

        availableFlagLXCol = DERIVE_TEMPORAL_COLOCATED_MVS;

    }



    // derive center collocated motion vector

    if (tab_mvf && !availableFlagLXCol) {

        x                  = x0 + (nPbW >> 1);

        y                  = y0 + (nPbH >> 1);

        x                 &= ~15;

        y                 &= ~15;

        ff_thread_await_progress(&ref->tf, y, 0);

        x_pu               = x >> s->sps->log2_min_pu_size;

        y_pu               = y >> s->sps->log2_min_pu_size;

        temp_col           = TAB_MVF(x_pu, y_pu);

        availableFlagLXCol = DERIVE_TEMPORAL_COLOCATED_MVS;

    }

    return availableFlagLXCol;

}

static int decode_audio_specific_config(AACContext *ac,

                                        AVCodecContext *avctx,

                                        MPEG4AudioConfig *m4ac,

                                        const uint8_t *data, int bit_size,

                                        int sync_extension)

{

    GetBitContext gb;

    int i, ret;



    ff_dlog(avctx, "audio specific config size %d\n", bit_size >> 3);

    for (i = 0; i < bit_size >> 3; i++)

        ff_dlog(avctx, "%02x ", data[i]);

    ff_dlog(avctx, "\n");



    if ((ret = init_get_bits(&gb, data, bit_size)) < 0)

        return ret;



    if ((i = avpriv_mpeg4audio_get_config(m4ac, data, bit_size,

                                          sync_extension)) < 0)

        return AVERROR_INVALIDDATA;

    if (m4ac->sampling_index > 12) {

        av_log(avctx, AV_LOG_ERROR,

               "invalid sampling rate index %d\n",

               m4ac->sampling_index);

        return AVERROR_INVALIDDATA;

    }

    if (m4ac->object_type == AOT_ER_AAC_LD &&

        (m4ac->sampling_index < 3 || m4ac->sampling_index > 7)) {

        av_log(avctx, AV_LOG_ERROR,

               "invalid low delay sampling rate index %d\n",

               m4ac->sampling_index);

        return AVERROR_INVALIDDATA;

    }



    skip_bits_long(&gb, i);



    switch (m4ac->object_type) {

    case AOT_AAC_MAIN:

    case AOT_AAC_LC:

    case AOT_AAC_LTP:

    case AOT_ER_AAC_LC:

    case AOT_ER_AAC_LD:

        if ((ret = decode_ga_specific_config(ac, avctx, &gb,

                                            m4ac, m4ac->chan_config)) < 0)

            return ret;

        break;

    case AOT_ER_AAC_ELD:

        if ((ret = decode_eld_specific_config(ac, avctx, &gb,

                                              m4ac, m4ac->chan_config)) < 0)

            return ret;

        break;

    default:

        avpriv_report_missing_feature(avctx,

                                      "Audio object type %s%d",

                                      m4ac->sbr == 1 ? "SBR+" : "",

                                      m4ac->object_type);

        return AVERROR(ENOSYS);

    }



    ff_dlog(avctx,

            "AOT %d chan config %d sampling index %d (%d) SBR %d PS %d\n",

            m4ac->object_type, m4ac->chan_config, m4ac->sampling_index,

            m4ac->sample_rate, m4ac->sbr,

            m4ac->ps);



    return get_bits_count(&gb);

}

long do_sigreturn(CPUS390XState *env)

{

    sigframe *frame;

    abi_ulong frame_addr = env->regs[15];

    target_sigset_t target_set;

    sigset_t set;



    trace_user_do_sigreturn(env, frame_addr);

    if (!lock_user_struct(VERIFY_READ, frame, frame_addr, 1)) {

        goto badframe;

    }

    __get_user(target_set.sig[0], &frame->sc.oldmask[0]);



    target_to_host_sigset_internal(&set, &target_set);

    set_sigmask(&set); /* ~_BLOCKABLE? */



    if (restore_sigregs(env, &frame->sregs)) {

        goto badframe;

    }



    unlock_user_struct(frame, frame_addr, 0);

    return -TARGET_QEMU_ESIGRETURN;



badframe:

    force_sig(TARGET_SIGSEGV);

    return 0;

}

static inline int get_symbol_inline(RangeCoder *c, uint8_t *state, int is_signed){

    if(get_rac(c, state+0))

        return 0;

    else{

        int i, e, a;

        e= 0;

        while(get_rac(c, state+1 + e) && e<9){ //1..10

            e++;

        }



        a= 1;

        for(i=e-1; i>=0; i--){

            a += a + get_rac(c, state+22 + i); //22..31

        }



        e= -(is_signed && get_rac(c, state+11 + e)); //11..21

        return (a^e)-e;

    }

}

