static int init_processing_chain(AVFilterContext *ctx, int in_width, int in_height,

                                 int out_width, int out_height)

{

    NPPScaleContext *s = ctx->priv;



    AVHWFramesContext *in_frames_ctx;



    enum AVPixelFormat in_format;

    enum AVPixelFormat out_format;

    enum AVPixelFormat in_deinterleaved_format;

    enum AVPixelFormat out_deinterleaved_format;



    int i, ret, last_stage = -1;



    /* check that we have a hw context */

    if (!ctx->inputs[0]->hw_frames_ctx) {

        av_log(ctx, AV_LOG_ERROR, "No hw context provided on input\n");

        return AVERROR(EINVAL);

    }

    in_frames_ctx = (AVHWFramesContext*)ctx->inputs[0]->hw_frames_ctx->data;

    in_format     = in_frames_ctx->sw_format;

    out_format    = (s->format == AV_PIX_FMT_NONE) ? in_format : s->format;



    if (!format_is_supported(in_format)) {

        av_log(ctx, AV_LOG_ERROR, "Unsupported input format: %s\n",

               av_get_pix_fmt_name(in_format));

        return AVERROR(ENOSYS);

    }

    if (!format_is_supported(out_format)) {

        av_log(ctx, AV_LOG_ERROR, "Unsupported output format: %s\n",

               av_get_pix_fmt_name(out_format));

        return AVERROR(ENOSYS);

    }



    in_deinterleaved_format  = get_deinterleaved_format(in_format);

    out_deinterleaved_format = get_deinterleaved_format(out_format);

    if (in_deinterleaved_format  == AV_PIX_FMT_NONE ||

        out_deinterleaved_format == AV_PIX_FMT_NONE)

        return AVERROR_BUG;



    /* figure out which stages need to be done */

    if (in_width != out_width || in_height != out_height ||

        in_deinterleaved_format != out_deinterleaved_format) {

        s->stages[STAGE_RESIZE].stage_needed = 1;



        if (s->interp_algo == NPPI_INTER_SUPER &&

            (out_width > in_width && out_height > in_height)) {

            s->interp_algo = NPPI_INTER_LANCZOS;

            av_log(ctx, AV_LOG_WARNING, "super-sampling not supported for output dimensions, using lanczos instead.\n");

        }

        if (s->interp_algo == NPPI_INTER_SUPER &&

            !(out_width < in_width && out_height < in_height)) {

            s->interp_algo = NPPI_INTER_CUBIC;

            av_log(ctx, AV_LOG_WARNING, "super-sampling not supported for output dimensions, using cubic instead.\n");

        }

    }



    if (!s->stages[STAGE_RESIZE].stage_needed && in_format == out_format)

        s->passthrough = 1;



    if (!s->passthrough) {

        if (in_format != in_deinterleaved_format)

            s->stages[STAGE_DEINTERLEAVE].stage_needed = 1;

        if (out_format != out_deinterleaved_format)

            s->stages[STAGE_INTERLEAVE].stage_needed = 1;

    }



    s->stages[STAGE_DEINTERLEAVE].in_fmt              = in_format;

    s->stages[STAGE_DEINTERLEAVE].out_fmt             = in_deinterleaved_format;

    s->stages[STAGE_DEINTERLEAVE].planes_in[0].width  = in_width;

    s->stages[STAGE_DEINTERLEAVE].planes_in[0].height = in_height;



    s->stages[STAGE_RESIZE].in_fmt               = in_deinterleaved_format;

    s->stages[STAGE_RESIZE].out_fmt              = out_deinterleaved_format;

    s->stages[STAGE_RESIZE].planes_in[0].width   = in_width;

    s->stages[STAGE_RESIZE].planes_in[0].height  = in_height;

    s->stages[STAGE_RESIZE].planes_out[0].width  = out_width;

    s->stages[STAGE_RESIZE].planes_out[0].height = out_height;



    s->stages[STAGE_INTERLEAVE].in_fmt              = out_deinterleaved_format;

    s->stages[STAGE_INTERLEAVE].out_fmt             = out_format;

    s->stages[STAGE_INTERLEAVE].planes_in[0].width  = out_width;

    s->stages[STAGE_INTERLEAVE].planes_in[0].height = out_height;



    /* init the hardware contexts */

    for (i = 0; i < FF_ARRAY_ELEMS(s->stages); i++) {

        if (!s->stages[i].stage_needed)

            continue;



        ret = init_stage(&s->stages[i], in_frames_ctx->device_ref);

        if (ret < 0)

            return ret;



        last_stage = i;

    }



    if (last_stage < 0)

    {

        ctx->outputs[0]->hw_frames_ctx = av_buffer_ref(ctx->inputs[0]->hw_frames_ctx);

        return 0;

    }



    ctx->outputs[0]->hw_frames_ctx = av_buffer_ref(s->stages[last_stage].frames_ctx);

    if (!ctx->outputs[0]->hw_frames_ctx)

        return AVERROR(ENOMEM);



    return 0;

}

static int read_uncompressed_sgi(unsigned char* out_buf, uint8_t* out_end,

                const uint8_t *in_buf, const uint8_t *in_end, SgiState* s)

{

    int x, y, z;

    const uint8_t *ptr;

    unsigned int offset = s->height * s->width * s->bytes_per_channel;



    /* Test buffer size. */

    if (offset * s->depth > in_end - in_buf) {

       return -1;

    }



    for (y = s->height - 1; y >= 0; y--) {

        out_end = out_buf + (y * s->linesize);

        for (x = s->width; x > 0; x--) {

            ptr = in_buf += s->bytes_per_channel;

            for(z = 0; z < s->depth; z ++) {

                memcpy(out_end, ptr, s->bytes_per_channel);

                out_end += s->bytes_per_channel;

                ptr += offset;

            }

        }

    }

    return 0;

}

int ff_mov_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    MOVMuxContext *mov = s->priv_data;

    AVIOContext *pb = s->pb;

    MOVTrack *trk = &mov->tracks[pkt->stream_index];

    AVCodecContext *enc = trk->enc;

    unsigned int samples_in_chunk = 0;

    int size = pkt->size;

    uint8_t *reformatted_data = NULL;



    if (mov->flags & FF_MOV_FLAG_FRAGMENT) {

        int ret;

        if (mov->fragments > 0) {

            if (!trk->mdat_buf) {

                if ((ret = avio_open_dyn_buf(&trk->mdat_buf)) < 0)

                    return ret;

            }

            pb = trk->mdat_buf;

        } else {

            if (!mov->mdat_buf) {

                if ((ret = avio_open_dyn_buf(&mov->mdat_buf)) < 0)

                    return ret;

            }

            pb = mov->mdat_buf;

        }

    }



    if (enc->codec_id == AV_CODEC_ID_AMR_NB) {

        /* We must find out how many AMR blocks there are in one packet */

        static uint16_t packed_size[16] =

            {13, 14, 16, 18, 20, 21, 27, 32, 6, 0, 0, 0, 0, 0, 0, 1};

        int len = 0;



        while (len < size && samples_in_chunk < 100) {

            len += packed_size[(pkt->data[len] >> 3) & 0x0F];

            samples_in_chunk++;

        }

        if (samples_in_chunk > 1) {

            av_log(s, AV_LOG_ERROR, "fatal error, input is not a single packet, implement a AVParser for it\n");

            return -1;

        }

    } else if (trk->sample_size)

        samples_in_chunk = size / trk->sample_size;

    else

        samples_in_chunk = 1;



    /* copy extradata if it exists */

    if (trk->vos_len == 0 && enc->extradata_size > 0) {

        trk->vos_len  = enc->extradata_size;

        trk->vos_data = av_malloc(trk->vos_len);

        memcpy(trk->vos_data, enc->extradata, trk->vos_len);

    }



    if (enc->codec_id == AV_CODEC_ID_H264 && trk->vos_len > 0 && *(uint8_t *)trk->vos_data != 1) {

        /* from x264 or from bytestream h264 */

        /* nal reformating needed */

        if (trk->hint_track >= 0 && trk->hint_track < mov->nb_streams) {

            ff_avc_parse_nal_units_buf(pkt->data, &reformatted_data,

                                       &size);

            avio_write(pb, reformatted_data, size);

        } else {

            size = ff_avc_parse_nal_units(pb, pkt->data, pkt->size);

        }

    } else if (enc->codec_id == AV_CODEC_ID_HEVC && trk->vos_len > 6 &&

               (AV_RB24(trk->vos_data) == 1 || AV_RB32(trk->vos_data) == 1)) {

        /* extradata is Annex B, assume the bitstream is too and convert it */

        if (trk->hint_track >= 0 && trk->hint_track < mov->nb_streams) {

            ff_hevc_annexb2mp4_buf(pkt->data, &reformatted_data, &size, 0, NULL);

            avio_write(pb, reformatted_data, size);

        } else {

            size = ff_hevc_annexb2mp4(pb, pkt->data, pkt->size, 0, NULL);

        }

    } else {

        avio_write(pb, pkt->data, size);

    }



    if ((enc->codec_id == AV_CODEC_ID_DNXHD ||

         enc->codec_id == AV_CODEC_ID_AC3) && !trk->vos_len) {

        /* copy frame to create needed atoms */

        trk->vos_len  = size;

        trk->vos_data = av_malloc(size);

        if (!trk->vos_data)

            return AVERROR(ENOMEM);

        memcpy(trk->vos_data, pkt->data, size);

    }



    if (trk->entry >= trk->cluster_capacity) {

        unsigned new_capacity = 2 * (trk->entry + MOV_INDEX_CLUSTER_SIZE);

        if (av_reallocp_array(&trk->cluster, new_capacity,

                              sizeof(*trk->cluster)))

            return AVERROR(ENOMEM);

        trk->cluster_capacity = new_capacity;

    }



    trk->cluster[trk->entry].pos              = avio_tell(pb) - size;

    trk->cluster[trk->entry].samples_in_chunk = samples_in_chunk;

    trk->cluster[trk->entry].size             = size;

    trk->cluster[trk->entry].entries          = samples_in_chunk;

    trk->cluster[trk->entry].dts              = pkt->dts;

    if (!trk->entry && trk->start_dts != AV_NOPTS_VALUE) {

        /* First packet of a new fragment. We already wrote the duration

         * of the last packet of the previous fragment based on track_duration,

         * which might not exactly match our dts. Therefore adjust the dts

         * of this packet to be what the previous packets duration implies. */

        trk->cluster[trk->entry].dts = trk->start_dts + trk->track_duration;

    }

    if (!trk->entry && trk->start_dts == AV_NOPTS_VALUE && !mov->use_editlist &&

        s->avoid_negative_ts == AVFMT_AVOID_NEG_TS_MAKE_ZERO) {

        /* Not using edit lists and shifting the first track to start from zero.

         * If the other streams start from a later timestamp, we won't be able

         * to signal the difference in starting time without an edit list.

         * Thus move the timestamp for this first sample to 0, increasing

         * its duration instead. */

        trk->cluster[trk->entry].dts = trk->start_dts = 0;

    }

    if (trk->start_dts == AV_NOPTS_VALUE) {

        trk->start_dts = pkt->dts;

        if (pkt->dts && mov->flags & FF_MOV_FLAG_EMPTY_MOOV)

            av_log(s, AV_LOG_WARNING,

                   "Track %d starts with a nonzero dts %"PRId64". This "

                   "currently isn't handled correctly in combination with "

                   "empty_moov.\n", pkt->stream_index, pkt->dts);

    }

    trk->track_duration = pkt->dts - trk->start_dts + pkt->duration;



    if (pkt->pts == AV_NOPTS_VALUE) {

        av_log(s, AV_LOG_WARNING, "pts has no value\n");

        pkt->pts = pkt->dts;

    }

    if (pkt->dts != pkt->pts)

        trk->flags |= MOV_TRACK_CTTS;

    trk->cluster[trk->entry].cts   = pkt->pts - pkt->dts;

    trk->cluster[trk->entry].flags = 0;

    if (enc->codec_id == AV_CODEC_ID_VC1) {

        mov_parse_vc1_frame(pkt, trk, mov->fragments);

    } else if (pkt->flags & AV_PKT_FLAG_KEY) {

        if (mov->mode == MODE_MOV && enc->codec_id == AV_CODEC_ID_MPEG2VIDEO &&

            trk->entry > 0) { // force sync sample for the first key frame

            mov_parse_mpeg2_frame(pkt, &trk->cluster[trk->entry].flags);

            if (trk->cluster[trk->entry].flags & MOV_PARTIAL_SYNC_SAMPLE)

                trk->flags |= MOV_TRACK_STPS;

        } else {

            trk->cluster[trk->entry].flags = MOV_SYNC_SAMPLE;

        }

        if (trk->cluster[trk->entry].flags & MOV_SYNC_SAMPLE)

            trk->has_keyframes++;

    }

    trk->entry++;

    trk->sample_count += samples_in_chunk;

    mov->mdat_size    += size;



    if (trk->hint_track >= 0 && trk->hint_track < mov->nb_streams)

        ff_mov_add_hinted_packet(s, pkt, trk->hint_track, trk->entry,

                                 reformatted_data, size);

    av_free(reformatted_data);

    return 0;

}

static CURLState *curl_init_state(BDRVCURLState *s)

{

    CURLState *state = NULL;

    int i, j;



    do {

        for (i=0; i<CURL_NUM_STATES; i++) {

            for (j=0; j<CURL_NUM_ACB; j++)

                if (s->states[i].acb[j])

                    continue;

            if (s->states[i].in_use)

                continue;



            state = &s->states[i];

            state->in_use = 1;

            break;

        }

        if (!state) {

            g_usleep(100);

            curl_multi_do(s);

        }

    } while(!state);



    if (state->curl)

        goto has_curl;



    state->curl = curl_easy_init();

    if (!state->curl)

        return NULL;

    curl_easy_setopt(state->curl, CURLOPT_URL, s->url);

    curl_easy_setopt(state->curl, CURLOPT_TIMEOUT, 5);

    curl_easy_setopt(state->curl, CURLOPT_WRITEFUNCTION, (void *)curl_read_cb);

    curl_easy_setopt(state->curl, CURLOPT_WRITEDATA, (void *)state);

    curl_easy_setopt(state->curl, CURLOPT_PRIVATE, (void *)state);

    curl_easy_setopt(state->curl, CURLOPT_AUTOREFERER, 1);

    curl_easy_setopt(state->curl, CURLOPT_FOLLOWLOCATION, 1);

    curl_easy_setopt(state->curl, CURLOPT_NOSIGNAL, 1);

    curl_easy_setopt(state->curl, CURLOPT_ERRORBUFFER, state->errmsg);

    curl_easy_setopt(state->curl, CURLOPT_FAILONERROR, 1);



    /* Restrict supported protocols to avoid security issues in the more

     * obscure protocols.  For example, do not allow POP3/SMTP/IMAP see

     * CVE-2013-0249.



     */


    curl_easy_setopt(state->curl, CURLOPT_PROTOCOLS, PROTOCOLS);

    curl_easy_setopt(state->curl, CURLOPT_REDIR_PROTOCOLS, PROTOCOLS);




#ifdef DEBUG_VERBOSE

    curl_easy_setopt(state->curl, CURLOPT_VERBOSE, 1);




has_curl:



    state->s = s;



    return state;

}

static int send_mono_rect(VncState *vs, int w, int h, uint32_t bg, uint32_t fg)

{

    size_t bytes;

    int stream = 1;

    int level = tight_conf[vs->tight_compression].mono_zlib_level;



    bytes = ((w + 7) / 8) * h;



    vnc_write_u8(vs, (stream | VNC_TIGHT_EXPLICIT_FILTER) << 4);

    vnc_write_u8(vs, VNC_TIGHT_FILTER_PALETTE);

    vnc_write_u8(vs, 1);



    switch(vs->clientds.pf.bytes_per_pixel) {

    case 4:

    {

        uint32_t buf[2] = {bg, fg};

        size_t ret = sizeof (buf);



        if (vs->tight_pixel24) {

            tight_pack24(vs, (unsigned char*)buf, 2, &ret);

        }

        vnc_write(vs, buf, ret);



        tight_encode_mono_rect32(vs->tight.buffer, w, h, bg, fg);

        break;

    }

    case 2:

        vnc_write(vs, &bg, 2);

        vnc_write(vs, &fg, 2);

        tight_encode_mono_rect16(vs->tight.buffer, w, h, bg, fg);

        break;

    default:

        vnc_write_u8(vs, bg);

        vnc_write_u8(vs, fg);

        tight_encode_mono_rect8(vs->tight.buffer, w, h, bg, fg);

        break;

    }

    vs->tight.offset = bytes;



    bytes = tight_compress_data(vs, stream, bytes, level, Z_DEFAULT_STRATEGY);

    return (bytes >= 0);

}

static void do_video_out(AVFormatContext *s,

                         OutputStream *ost,

                         AVFrame *in_picture,

                         int *frame_size)

{

    int ret, format_video_sync;

    AVPacket pkt;

    AVCodecContext *enc = ost->enc_ctx;



    *frame_size = 0;



    format_video_sync = video_sync_method;

    if (format_video_sync == VSYNC_AUTO)

        format_video_sync = (s->oformat->flags & AVFMT_NOTIMESTAMPS) ? VSYNC_PASSTHROUGH :

                            (s->oformat->flags & AVFMT_VARIABLE_FPS) ? VSYNC_VFR : VSYNC_CFR;

    if (format_video_sync != VSYNC_PASSTHROUGH &&

        ost->frame_number &&

        in_picture->pts != AV_NOPTS_VALUE &&

        in_picture->pts < ost->sync_opts) {

        nb_frames_drop++;

        av_log(NULL, AV_LOG_WARNING,

               "*** dropping frame %d from stream %d at ts %"PRId64"\n",

               ost->frame_number, ost->st->index, in_picture->pts);

        return;

    }



    if (in_picture->pts == AV_NOPTS_VALUE)

        in_picture->pts = ost->sync_opts;

    ost->sync_opts = in_picture->pts;





    if (!ost->frame_number)

        ost->first_pts = in_picture->pts;



    av_init_packet(&pkt);

    pkt.data = NULL;

    pkt.size = 0;



    if (ost->frame_number >= ost->max_frames)

        return;



    if (enc->flags & (AV_CODEC_FLAG_INTERLACED_DCT | AV_CODEC_FLAG_INTERLACED_ME) &&

        ost->top_field_first >= 0)

        in_picture->top_field_first = !!ost->top_field_first;



    in_picture->quality = enc->global_quality;

    in_picture->pict_type = 0;

    if (ost->forced_kf_index < ost->forced_kf_count &&

        in_picture->pts >= ost->forced_kf_pts[ost->forced_kf_index]) {

        in_picture->pict_type = AV_PICTURE_TYPE_I;

        ost->forced_kf_index++;

    }



    ost->frames_encoded++;



    ret = avcodec_send_frame(enc, in_picture);

    if (ret < 0)

        goto error;



    /*

     * For video, there may be reordering, so we can't throw away frames on

     * encoder flush, we need to limit them here, before they go into encoder.

     */

    ost->frame_number++;



    while (1) {

        ret = avcodec_receive_packet(enc, &pkt);

        if (ret == AVERROR(EAGAIN))

            break;

        if (ret < 0)

            goto error;



        av_packet_rescale_ts(&pkt, enc->time_base, ost->st->time_base);

        output_packet(s, &pkt, ost);

        *frame_size = pkt.size;



        /* if two pass, output log */

        if (ost->logfile && enc->stats_out) {

            fprintf(ost->logfile, "%s", enc->stats_out);

        }



        ost->sync_opts++;

    }



    return;

error:

    av_assert0(ret != AVERROR(EAGAIN) && ret != AVERROR_EOF);

    av_log(NULL, AV_LOG_FATAL, "Video encoding failed\n");

    exit_program(1);

}

void qmp_screendump(const char *filename, Error **errp)

{

    QemuConsole *previous_active_console;

    bool cswitch;



    previous_active_console = active_console;

    cswitch = previous_active_console && previous_active_console->index != 0;



    /* There is currently no way of specifying which screen we want to dump,

       so always dump the first one.  */

    if (cswitch) {

        console_select(0);

    }

    if (consoles[0] && consoles[0]->hw_screen_dump) {

        consoles[0]->hw_screen_dump(consoles[0]->hw, filename, cswitch, errp);

    } else {

        error_setg(errp, "device doesn't support screendump");

    }



    if (cswitch) {

        console_select(previous_active_console->index);

    }

}

static int decode_frame_mp3on4(AVCodecContext * avctx,

                        void *data, int *data_size,

                        AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    MP3On4DecodeContext *s = avctx->priv_data;

    MPADecodeContext *m;

    int fsize, len = buf_size, out_size = 0;

    uint32_t header;

    OUT_INT *out_samples = data;

    OUT_INT *outptr, *bp;

    int fr, j, n;



    if(*data_size < MPA_FRAME_SIZE * MPA_MAX_CHANNELS * s->frames * sizeof(OUT_INT))

        return -1;



    *data_size = 0;

    // Discard too short frames

    if (buf_size < HEADER_SIZE)

        return -1;



    // If only one decoder interleave is not needed

    outptr = s->frames == 1 ? out_samples : s->decoded_buf;



    avctx->bit_rate = 0;



    for (fr = 0; fr < s->frames; fr++) {

        fsize = AV_RB16(buf) >> 4;

        fsize = FFMIN3(fsize, len, MPA_MAX_CODED_FRAME_SIZE);

        m = s->mp3decctx[fr];

        assert (m != NULL);



        header = (AV_RB32(buf) & 0x000fffff) | s->syncword; // patch header



        if (ff_mpa_check_header(header) < 0) // Bad header, discard block

            break;



        avpriv_mpegaudio_decode_header((MPADecodeHeader *)m, header);

        out_size += mp_decode_frame(m, outptr, buf, fsize);

        buf += fsize;

        len -= fsize;



        if(s->frames > 1) {

            n = m->avctx->frame_size*m->nb_channels;

            /* interleave output data */

            bp = out_samples + s->coff[fr];

            if(m->nb_channels == 1) {

                for(j = 0; j < n; j++) {

                    *bp = s->decoded_buf[j];

                    bp += avctx->channels;

                }

            } else {

                for(j = 0; j < n; j++) {

                    bp[0] = s->decoded_buf[j++];

                    bp[1] = s->decoded_buf[j];

                    bp += avctx->channels;

                }

            }

        }

        avctx->bit_rate += m->bit_rate;

    }



    /* update codec info */

    avctx->sample_rate = s->mp3decctx[0]->sample_rate;



    *data_size = out_size;

    return buf_size;

}

DISAS_INSN(cas2l)

{

    uint16_t ext1, ext2;

    TCGv addr1, addr2, regs;



    /* cas2 Dc1:Dc2,Du1:Du2,(Rn1):(Rn2) */



    ext1 = read_im16(env, s);



    if (ext1 & 0x8000) {

        /* Address Register */

        addr1 = AREG(ext1, 12);

    } else {

        /* Data Register */

        addr1 = DREG(ext1, 12);

    }



    ext2 = read_im16(env, s);

    if (ext2 & 0x8000) {

        /* Address Register */

        addr2 = AREG(ext2, 12);

    } else {

        /* Data Register */

        addr2 = DREG(ext2, 12);

    }



    /* if (R1) == Dc1 && (R2) == Dc2 then

     *     (R1) = Du1

     *     (R2) = Du2

     * else

     *     Dc1 = (R1)

     *     Dc2 = (R2)

     */



    regs = tcg_const_i32(REG(ext2, 6) |

                         (REG(ext1, 6) << 3) |

                         (REG(ext2, 0) << 6) |

                         (REG(ext1, 0) << 9));

    gen_helper_cas2l(cpu_env, regs, addr1, addr2);

    tcg_temp_free(regs);



    /* Note that cas2l also assigned to env->cc_op.  */

    s->cc_op = CC_OP_CMPL;

    s->cc_op_synced = 1;

}

