static void tcg_out_tlb_read(TCGContext *s, TCGReg addr_reg, TCGMemOp opc,

                             tcg_insn_unit **label_ptr, int mem_index,

                             bool is_read)

{

    int tlb_offset = is_read ?

        offsetof(CPUArchState, tlb_table[mem_index][0].addr_read)

        : offsetof(CPUArchState, tlb_table[mem_index][0].addr_write);

    int s_mask = (1 << (opc & MO_SIZE)) - 1;

    TCGReg base = TCG_AREG0, x3;

    uint64_t tlb_mask;



    /* For aligned accesses, we check the first byte and include the alignment

       bits within the address.  For unaligned access, we check that we don't

       cross pages using the address of the last byte of the access.  */

    if ((opc & MO_AMASK) == MO_ALIGN || s_mask == 0) {

        tlb_mask = TARGET_PAGE_MASK | s_mask;

        x3 = addr_reg;

    } else {

        tcg_out_insn(s, 3401, ADDI, TARGET_LONG_BITS == 64,

                     TCG_REG_X3, addr_reg, s_mask);

        tlb_mask = TARGET_PAGE_MASK;

        x3 = TCG_REG_X3;

    }



    /* Extract the TLB index from the address into X0.

       X0<CPU_TLB_BITS:0> =

       addr_reg<TARGET_PAGE_BITS+CPU_TLB_BITS:TARGET_PAGE_BITS> */

    tcg_out_ubfm(s, TARGET_LONG_BITS == 64, TCG_REG_X0, addr_reg,

                 TARGET_PAGE_BITS, TARGET_PAGE_BITS + CPU_TLB_BITS);



    /* Store the page mask part of the address into X3.  */

    tcg_out_logicali(s, I3404_ANDI, TARGET_LONG_BITS == 64,

                     TCG_REG_X3, x3, tlb_mask);



    /* Add any "high bits" from the tlb offset to the env address into X2,

       to take advantage of the LSL12 form of the ADDI instruction.

       X2 = env + (tlb_offset & 0xfff000) */

    if (tlb_offset & 0xfff000) {

        tcg_out_insn(s, 3401, ADDI, TCG_TYPE_I64, TCG_REG_X2, base,

                     tlb_offset & 0xfff000);

        base = TCG_REG_X2;

    }



    /* Merge the tlb index contribution into X2.

       X2 = X2 + (X0 << CPU_TLB_ENTRY_BITS) */

    tcg_out_insn(s, 3502S, ADD_LSL, TCG_TYPE_I64, TCG_REG_X2, base,

                 TCG_REG_X0, CPU_TLB_ENTRY_BITS);



    /* Merge "low bits" from tlb offset, load the tlb comparator into X0.

       X0 = load [X2 + (tlb_offset & 0x000fff)] */

    tcg_out_ldst(s, TARGET_LONG_BITS == 32 ? I3312_LDRW : I3312_LDRX,

                 TCG_REG_X0, TCG_REG_X2, tlb_offset & 0xfff);



    /* Load the tlb addend. Do that early to avoid stalling.

       X1 = load [X2 + (tlb_offset & 0xfff) + offsetof(addend)] */

    tcg_out_ldst(s, I3312_LDRX, TCG_REG_X1, TCG_REG_X2,

                 (tlb_offset & 0xfff) + (offsetof(CPUTLBEntry, addend)) -

                 (is_read ? offsetof(CPUTLBEntry, addr_read)

                  : offsetof(CPUTLBEntry, addr_write)));



    /* Perform the address comparison. */

    tcg_out_cmp(s, (TARGET_LONG_BITS == 64), TCG_REG_X0, TCG_REG_X3, 0);



    /* If not equal, we jump to the slow path. */

    *label_ptr = s->code_ptr;

    tcg_out_goto_cond_noaddr(s, TCG_COND_NE);

}

static int usb_host_scan_sys(void *opaque, USBScanFunc *func)

{

    DIR *dir = 0;

    char line[1024];

    int bus_num, addr, speed, class_id, product_id, vendor_id;

    int ret = 0;

    char product_name[512];

    struct dirent *de;



    dir = opendir(USBSYSBUS_PATH "/devices");

    if (!dir) {

        perror("husb: cannot open devices directory");

        goto the_end;

    }



    while ((de = readdir(dir))) {

        if (de->d_name[0] != '.' && !strchr(de->d_name, ':')) {

            char *tmpstr = de->d_name;

            if (!strncmp(de->d_name, "usb", 3))

                tmpstr += 3;

            bus_num = atoi(tmpstr);



            if (!usb_host_read_file(line, sizeof(line), USBSYSBUS_PATH "/devices/%s/devnum", de->d_name))

                goto the_end;

            if (sscanf(line, "%d", &addr) != 1)

                goto the_end;



            if (!usb_host_read_file(line, sizeof(line), USBSYSBUS_PATH "/devices/%s/bDeviceClass", de->d_name))

                goto the_end;

            if (sscanf(line, "%x", &class_id) != 1)

                goto the_end;



            if (!usb_host_read_file(line, sizeof(line), USBSYSBUS_PATH "/devices/%s/idVendor", de->d_name))

                goto the_end;

            if (sscanf(line, "%x", &vendor_id) != 1)

                goto the_end;



            if (!usb_host_read_file(line, sizeof(line), USBSYSBUS_PATH "/devices/%s/idProduct", de->d_name))

                goto the_end;

            if (sscanf(line, "%x", &product_id) != 1)

                goto the_end;



            if (!usb_host_read_file(line, sizeof(line), USBSYSBUS_PATH "/devices/%s/product", de->d_name)) {

                *product_name = 0;

            } else {

                if (strlen(line) > 0)

                    line[strlen(line) - 1] = '\0';

                pstrcpy(product_name, sizeof(product_name), line);

            }



            if (!usb_host_read_file(line, sizeof(line), USBSYSBUS_PATH "/devices/%s/speed", de->d_name))

                goto the_end;

            if (!strcmp(line, "480\n"))

                speed = USB_SPEED_HIGH;

            else if (!strcmp(line, "1.5\n"))

                speed = USB_SPEED_LOW;

            else

                speed = USB_SPEED_FULL;



            ret = func(opaque, bus_num, addr, class_id, vendor_id,

                       product_id, product_name, speed);

            if (ret)

                goto the_end;

        }

    }

 the_end:

    if (dir)

        closedir(dir);

    return ret;

}

int svm_check_intercept_param(uint32_t type, uint64_t param)

{

    switch(type) {

    case SVM_EXIT_READ_CR0 ... SVM_EXIT_READ_CR0 + 8:

        if (INTERCEPTEDw(_cr_read, (1 << (type - SVM_EXIT_READ_CR0)))) {

            vmexit(type, param);

            return 1;

        }

        break;

    case SVM_EXIT_READ_DR0 ... SVM_EXIT_READ_DR0 + 8:

        if (INTERCEPTEDw(_dr_read, (1 << (type - SVM_EXIT_READ_DR0)))) {

            vmexit(type, param);

            return 1;

        }

        break;

    case SVM_EXIT_WRITE_CR0 ... SVM_EXIT_WRITE_CR0 + 8:

        if (INTERCEPTEDw(_cr_write, (1 << (type - SVM_EXIT_WRITE_CR0)))) {

            vmexit(type, param);

            return 1;

        }

        break;

    case SVM_EXIT_WRITE_DR0 ... SVM_EXIT_WRITE_DR0 + 8:

        if (INTERCEPTEDw(_dr_write, (1 << (type - SVM_EXIT_WRITE_DR0)))) {

            vmexit(type, param);

            return 1;

        }

        break;

    case SVM_EXIT_EXCP_BASE ... SVM_EXIT_EXCP_BASE + 16:

        if (INTERCEPTEDl(_exceptions, (1 << (type - SVM_EXIT_EXCP_BASE)))) {

            vmexit(type, param);

            return 1;

        }

        break;

    case SVM_EXIT_IOIO:

        if (INTERCEPTED(1ULL << INTERCEPT_IOIO_PROT)) {

            /* FIXME: this should be read in at vmrun (faster this way?) */

            uint64_t addr = ldq_phys(env->vm_vmcb + offsetof(struct vmcb, control.iopm_base_pa));

            uint16_t port = (uint16_t) (param >> 16);



            if(ldub_phys(addr + port / 8) & (1 << (port % 8)))

                vmexit(type, param);

        }

        break;



    case SVM_EXIT_MSR:

        if (INTERCEPTED(1ULL << INTERCEPT_MSR_PROT)) {

            /* FIXME: this should be read in at vmrun (faster this way?) */

            uint64_t addr = ldq_phys(env->vm_vmcb + offsetof(struct vmcb, control.msrpm_base_pa));

            switch((uint32_t)ECX) {

            case 0 ... 0x1fff:

                T0 = (ECX * 2) % 8;

                T1 = ECX / 8;

                break;

            case 0xc0000000 ... 0xc0001fff:

                T0 = (8192 + ECX - 0xc0000000) * 2;

                T1 = (T0 / 8);

                T0 %= 8;

                break;

            case 0xc0010000 ... 0xc0011fff:

                T0 = (16384 + ECX - 0xc0010000) * 2;

                T1 = (T0 / 8);

                T0 %= 8;

                break;

            default:

                vmexit(type, param);

                return 1;

            }

            if (ldub_phys(addr + T1) & ((1 << param) << T0))

                vmexit(type, param);

            return 1;

        }

        break;

    default:

        if (INTERCEPTED((1ULL << ((type - SVM_EXIT_INTR) + INTERCEPT_INTR)))) {

            vmexit(type, param);

            return 1;

        }

        break;

    }

    return 0;

}

int kvm_arch_get_registers(CPUState *env)

{

    struct kvm_regs regs;

    struct kvm_sregs sregs;

    int i, ret;



    ret = kvm_vcpu_ioctl(env, KVM_GET_REGS, &regs);

    if (ret < 0)

        return ret;



    ret = kvm_vcpu_ioctl(env, KVM_GET_SREGS, &sregs);

    if (ret < 0)

        return ret;



    env->ctr = regs.ctr;

    env->lr = regs.lr;

    env->xer = regs.xer;

    env->msr = regs.msr;

    env->nip = regs.pc;



    env->spr[SPR_SRR0] = regs.srr0;

    env->spr[SPR_SRR1] = regs.srr1;



    env->spr[SPR_SPRG0] = regs.sprg0;

    env->spr[SPR_SPRG1] = regs.sprg1;

    env->spr[SPR_SPRG2] = regs.sprg2;

    env->spr[SPR_SPRG3] = regs.sprg3;

    env->spr[SPR_SPRG4] = regs.sprg4;

    env->spr[SPR_SPRG5] = regs.sprg5;

    env->spr[SPR_SPRG6] = regs.sprg6;

    env->spr[SPR_SPRG7] = regs.sprg7;



    for (i = 0;i < 32; i++)

        env->gpr[i] = regs.gpr[i];



#ifdef KVM_CAP_PPC_SEGSTATE

    if (kvm_check_extension(env->kvm_state, KVM_CAP_PPC_SEGSTATE)) {

        env->sdr1 = sregs.u.s.sdr1;



        /* Sync SLB */

#ifdef TARGET_PPC64

        for (i = 0; i < 64; i++) {

            ppc_store_slb(env, sregs.u.s.ppc64.slb[i].slbe,

                               sregs.u.s.ppc64.slb[i].slbv);

        }

#endif



        /* Sync SRs */

        for (i = 0; i < 16; i++) {

            env->sr[i] = sregs.u.s.ppc32.sr[i];

        }



        /* Sync BATs */

        for (i = 0; i < 8; i++) {

            env->DBAT[0][i] = sregs.u.s.ppc32.dbat[i] & 0xffffffff;

            env->DBAT[1][i] = sregs.u.s.ppc32.dbat[i] >> 32;

            env->IBAT[0][i] = sregs.u.s.ppc32.ibat[i] & 0xffffffff;

            env->IBAT[1][i] = sregs.u.s.ppc32.ibat[i] >> 32;

        }

    }

#endif



    return 0;

}

void qemu_cond_wait(QemuCond *cond, QemuMutex *mutex)

{

    /*

     * This access is protected under the mutex.

     */

    cond->waiters++;



    /*

     * Unlock external mutex and wait for signal.

     * NOTE: we've held mutex locked long enough to increment

     * waiters count above, so there's no problem with

     * leaving mutex unlocked before we wait on semaphore.

     */

    qemu_mutex_unlock(mutex);

    WaitForSingleObject(cond->sema, INFINITE);



    /* Now waiters must rendez-vous with the signaling thread and

     * let it continue.  For cond_broadcast this has heavy contention

     * and triggers thundering herd.  So goes life.

     *

     * Decrease waiters count.  The mutex is not taken, so we have

     * to do this atomically.

     *

     * All waiters contend for the mutex at the end of this function

     * until the signaling thread relinquishes it.  To ensure

     * each waiter consumes exactly one slice of the semaphore,

     * the signaling thread stops until it is told by the last

     * waiter that it can go on.

     */

    if (InterlockedDecrement(&cond->waiters) == cond->target) {

        SetEvent(cond->continue_event);

    }



    qemu_mutex_lock(mutex);

}

static void gen_wsr(DisasContext *dc, uint32_t sr, TCGv_i32 s)

{

