static void pchip_write(void *opaque, target_phys_addr_t addr,

                        uint64_t v32, unsigned size)

{

    TyphoonState *s = opaque;

    uint64_t val, oldval;



    if (addr & 4) {

        val = v32 << 32 | s->latch_tmp;

        addr ^= 4;

    } else {

        s->latch_tmp = v32;

        return;

    }



    switch (addr) {

    case 0x0000:

        /* WSBA0: Window Space Base Address Register.  */

        s->pchip.win[0].base_addr = val;

        break;

    case 0x0040:

        /* WSBA1 */

        s->pchip.win[1].base_addr = val;

        break;

    case 0x0080:

        /* WSBA2 */

        s->pchip.win[2].base_addr = val;

        break;

    case 0x00c0:

        /* WSBA3 */

        s->pchip.win[3].base_addr = val;

        break;



    case 0x0100:

        /* WSM0: Window Space Mask Register.  */

        s->pchip.win[0].mask = val;

        break;

    case 0x0140:

        /* WSM1 */

        s->pchip.win[1].mask = val;

        break;

    case 0x0180:

        /* WSM2 */

        s->pchip.win[2].mask = val;

        break;

    case 0x01c0:

        /* WSM3 */

        s->pchip.win[3].mask = val;

        break;



    case 0x0200:

        /* TBA0: Translated Base Address Register.  */

        s->pchip.win[0].translated_base_pfn = val >> 10;

        break;

    case 0x0240:

        /* TBA1 */

        s->pchip.win[1].translated_base_pfn = val >> 10;

        break;

    case 0x0280:

        /* TBA2 */

        s->pchip.win[2].translated_base_pfn = val >> 10;

        break;

    case 0x02c0:

        /* TBA3 */

        s->pchip.win[3].translated_base_pfn = val >> 10;

        break;



    case 0x0300:

        /* PCTL: Pchip Control Register.  */

        oldval = s->pchip.ctl;

        oldval &= ~0x00001cff0fc7ffull;       /* RW fields */

        oldval |= val & 0x00001cff0fc7ffull;



        s->pchip.ctl = oldval;

        break;



    case 0x0340:

        /* PLAT: Pchip Master Latency Register.  */

        break;

    case 0x03c0:

        /* PERROR: Pchip Error Register.  */

        break;

    case 0x0400:

        /* PERRMASK: Pchip Error Mask Register.  */

        break;

    case 0x0440:

        /* PERRSET: Pchip Error Set Register.  */

        break;



    case 0x0480:

        /* TLBIV: Translation Buffer Invalidate Virtual Register.  */

        break;



    case 0x04c0:

        /* TLBIA: Translation Buffer Invalidate All Register (WO).  */

        break;



    case 0x0500:

        /* PMONCTL */

    case 0x0540:

        /* PMONCNT */

    case 0x0800:

        /* SPRST */

        break;



    default:

        cpu_unassigned_access(cpu_single_env, addr, 1, 0, 0, size);

        return;

    }

}

static int usb_host_handle_data(USBDevice *dev, USBPacket *p)

{

    USBHostDevice *s = (USBHostDevice *)dev;

    int ret, fd, mode;

    int one = 1, shortpacket = 0, timeout = 50;

    sigset_t new_mask, old_mask;

    uint8_t devep = p->devep;



    /* protect data transfers from SIGALRM signal */

    sigemptyset(&new_mask);

    sigaddset(&new_mask, SIGALRM);

    sigprocmask(SIG_BLOCK, &new_mask, &old_mask);



    if (p->pid == USB_TOKEN_IN) {

        devep |= 0x80;

        mode = O_RDONLY;

        shortpacket = 1;

    } else {

        mode = O_WRONLY;

    }



    fd = ensure_ep_open(s, devep, mode);

    if (fd < 0) {

        sigprocmask(SIG_SETMASK, &old_mask, NULL);

        return USB_RET_NODEV;

    }



    if (ioctl(fd, USB_SET_TIMEOUT, &timeout) < 0) {

#ifdef DEBUG

        printf("handle_data: failed to set timeout - %s\n",

               strerror(errno));

#endif

    }



    if (shortpacket) {

        if (ioctl(fd, USB_SET_SHORT_XFER, &one) < 0) {

#ifdef DEBUG

            printf("handle_data: failed to set short xfer mode - %s\n",

                   strerror(errno));

#endif

            sigprocmask(SIG_SETMASK, &old_mask, NULL);

        }

    }



    if (p->pid == USB_TOKEN_IN)

        ret = read(fd, p->data, p->len);

    else

        ret = write(fd, p->data, p->len);



    sigprocmask(SIG_SETMASK, &old_mask, NULL);



    if (ret < 0) {

#ifdef DEBUG

        printf("handle_data: error after %s data - %s\n",

               pid == USB_TOKEN_IN ? "reading" : "writing", strerror(errno));

#endif

        switch(errno) {

        case ETIMEDOUT:

        case EINTR:

            return USB_RET_NAK;

        default:

            return USB_RET_STALL;

        }

    } else {

        return ret;

    }

}

int ff_mpv_common_frame_size_change(MpegEncContext *s)

{

    int i, err = 0;



    if (!s->context_initialized)

        return AVERROR(EINVAL);



    if (s->slice_context_count > 1) {

        for (i = 0; i < s->slice_context_count; i++) {

            free_duplicate_context(s->thread_context[i]);

        }

        for (i = 1; i < s->slice_context_count; i++) {

            av_freep(&s->thread_context[i]);

        }

    } else

        free_duplicate_context(s);



    free_context_frame(s);



    if (s->picture)

        for (i = 0; i < MAX_PICTURE_COUNT; i++) {

                s->picture[i].needs_realloc = 1;

        }



    s->last_picture_ptr         =

    s->next_picture_ptr         =

    s->current_picture_ptr      = NULL;



    // init

    if (s->codec_id == AV_CODEC_ID_MPEG2VIDEO && !s->progressive_sequence)

        s->mb_height = (s->height + 31) / 32 * 2;

    else

        s->mb_height = (s->height + 15) / 16;



    if ((s->width || s->height) &&

        (err = av_image_check_size(s->width, s->height, 0, s->avctx)) < 0)

        goto fail;



    if ((err = init_context_frame(s)))

        goto fail;



    memset(s->thread_context, 0, sizeof(s->thread_context));

    s->thread_context[0]   = s;



    if (s->width && s->height) {

        int nb_slices = s->slice_context_count;

        if (nb_slices > 1) {

            for (i = 0; i < nb_slices; i++) {

                if (i) {

                    s->thread_context[i] = av_malloc(sizeof(MpegEncContext));

                    memcpy(s->thread_context[i], s, sizeof(MpegEncContext));

                }

                if ((err = init_duplicate_context(s->thread_context[i])) < 0)

                    goto fail;

                    s->thread_context[i]->start_mb_y =

                        (s->mb_height * (i) + nb_slices / 2) / nb_slices;

                    s->thread_context[i]->end_mb_y   =

                        (s->mb_height * (i + 1) + nb_slices / 2) / nb_slices;

            }

        } else {

            err = init_duplicate_context(s);

            if (err < 0)

                goto fail;

            s->start_mb_y = 0;

            s->end_mb_y   = s->mb_height;

        }

        s->slice_context_count = nb_slices;

    }



    return 0;

 fail:

    ff_mpv_common_end(s);

    return err;

}

static uint32_t virtio_ioport_read(VirtIOPCIProxy *proxy, uint32_t addr)

{

    VirtIODevice *vdev = proxy->vdev;

    uint32_t ret = 0xFFFFFFFF;



    switch (addr) {

    case VIRTIO_PCI_HOST_FEATURES:

        ret = vdev->get_features(vdev);

        ret |= (1 << VIRTIO_F_NOTIFY_ON_EMPTY);

        ret |= (1 << VIRTIO_RING_F_INDIRECT_DESC);

        ret |= (1 << VIRTIO_F_BAD_FEATURE);

        break;

    case VIRTIO_PCI_GUEST_FEATURES:

        ret = vdev->features;

        break;

    case VIRTIO_PCI_QUEUE_PFN:

        ret = virtio_queue_get_addr(vdev, vdev->queue_sel)

              >> VIRTIO_PCI_QUEUE_ADDR_SHIFT;

        break;

    case VIRTIO_PCI_QUEUE_NUM:

        ret = virtio_queue_get_num(vdev, vdev->queue_sel);

        break;

    case VIRTIO_PCI_QUEUE_SEL:

        ret = vdev->queue_sel;

        break;

    case VIRTIO_PCI_STATUS:

        ret = vdev->status;

        break;

    case VIRTIO_PCI_ISR:

        /* reading from the ISR also clears it. */

        ret = vdev->isr;

        vdev->isr = 0;

        qemu_set_irq(proxy->pci_dev.irq[0], 0);

        break;

    case VIRTIO_MSI_CONFIG_VECTOR:

        ret = vdev->config_vector;

        break;

    case VIRTIO_MSI_QUEUE_VECTOR:

        ret = virtio_queue_vector(vdev, vdev->queue_sel);

        break;

    default:

        break;

    }



    return ret;

}

static int dvbsub_parse_display_definition_segment(AVCodecContext *avctx,

                                                   const uint8_t *buf,

                                                   int buf_size)

{

    DVBSubContext *ctx = avctx->priv_data;

    DVBSubDisplayDefinition *display_def = ctx->display_definition;

    int dds_version, info_byte;



    if (buf_size < 5)

        return AVERROR_INVALIDDATA;



    info_byte   = bytestream_get_byte(&buf);

    dds_version = info_byte >> 4;

    if (display_def && display_def->version == dds_version)

        return 0; // already have this display definition version



    if (!display_def) {

        display_def             = av_mallocz(sizeof(*display_def));

        if (!display_def)

            return AVERROR(ENOMEM);

        ctx->display_definition = display_def;

    }



    display_def->version = dds_version;

    display_def->x       = 0;

    display_def->y       = 0;

    display_def->width   = bytestream_get_be16(&buf) + 1;

    display_def->height  = bytestream_get_be16(&buf) + 1;

    if (!avctx->width || !avctx->height) {

        avctx->width  = display_def->width;

        avctx->height = display_def->height;

    }



    if (buf_size < 13)

        return AVERROR_INVALIDDATA;



    if (info_byte & 1<<3) { // display_window_flag

        display_def->x = bytestream_get_be16(&buf);

        display_def->width  = bytestream_get_be16(&buf) - display_def->x + 1;

        display_def->y = bytestream_get_be16(&buf);

        display_def->height = bytestream_get_be16(&buf) - display_def->y + 1;

    }



    return 0;

}

