static void test_validate_fail_struct_missing(TestInputVisitorData *data,

                                              const void *unused)

{

    Error *err = NULL;

    Visitor *v;

    QObject *any;

    GenericAlternate *alt;

    bool present;

    int en;

    int64_t i64;

    uint32_t u32;

