static void init_scan_tables(H264Context *h)

{

    int i;

    for (i = 0; i < 16; i++) {

#define TRANSPOSE(x) (x >> 2) | ((x << 2) & 0xF)

        h->zigzag_scan[i] = TRANSPOSE(ff_zigzag_scan[i]);

        h->field_scan[i]  = TRANSPOSE(field_scan[i]);

#undef TRANSPOSE

    }

    for (i = 0; i < 64; i++) {

#define TRANSPOSE(x) (x >> 3) | ((x & 7) << 3)

        h->zigzag_scan8x8[i]       = TRANSPOSE(ff_zigzag_direct[i]);

        h->zigzag_scan8x8_cavlc[i] = TRANSPOSE(zigzag_scan8x8_cavlc[i]);

        h->field_scan8x8[i]        = TRANSPOSE(field_scan8x8[i]);

        h->field_scan8x8_cavlc[i]  = TRANSPOSE(field_scan8x8_cavlc[i]);

#undef TRANSPOSE

    }

    if (h->sps.transform_bypass) { // FIXME same ugly

        h->zigzag_scan_q0          = ff_zigzag_scan;

        h->zigzag_scan8x8_q0       = ff_zigzag_direct;

        h->zigzag_scan8x8_cavlc_q0 = zigzag_scan8x8_cavlc;

        h->field_scan_q0           = field_scan;

        h->field_scan8x8_q0        = field_scan8x8;

        h->field_scan8x8_cavlc_q0  = field_scan8x8_cavlc;

    } else {

        h->zigzag_scan_q0          = h->zigzag_scan;

        h->zigzag_scan8x8_q0       = h->zigzag_scan8x8;

        h->zigzag_scan8x8_cavlc_q0 = h->zigzag_scan8x8_cavlc;

        h->field_scan_q0           = h->field_scan;

        h->field_scan8x8_q0        = h->field_scan8x8;

        h->field_scan8x8_cavlc_q0  = h->field_scan8x8_cavlc;

    }

}

void avg_pixels8_altivec(uint8_t * block, const uint8_t * pixels, int line_size, int h)

{

POWERPC_TBL_DECLARE(altivec_avg_pixels8_num, 1);

#ifdef ALTIVEC_USE_REFERENCE_C_CODE

    int i;

POWERPC_TBL_START_COUNT(altivec_avg_pixels8_num, 1);

    for (i = 0; i < h; i++) {

        *((uint32_t *) (block)) =

            (((*((uint32_t *) (block))) |

              ((((const struct unaligned_32 *) (pixels))->l))) -

             ((((*((uint32_t *) (block))) ^

                ((((const struct unaligned_32 *) (pixels))->

                  l))) & 0xFEFEFEFEUL) >> 1));

        *((uint32_t *) (block + 4)) =

            (((*((uint32_t *) (block + 4))) |

              ((((const struct unaligned_32 *) (pixels + 4))->l))) -

             ((((*((uint32_t *) (block + 4))) ^

                ((((const struct unaligned_32 *) (pixels +

                                                  4))->

                  l))) & 0xFEFEFEFEUL) >> 1));

        pixels += line_size;

        block += line_size;

    }

POWERPC_TBL_STOP_COUNT(altivec_avg_pixels8_num, 1);



#else /* ALTIVEC_USE_REFERENCE_C_CODE */

    register vector unsigned char pixelsv1, pixelsv2, pixelsv, blockv;

    int i;



POWERPC_TBL_START_COUNT(altivec_avg_pixels8_num, 1);



   for (i = 0; i < h; i++) {

     /*

       block is 8 bytes-aligned, so we're either in the

       left block (16 bytes-aligned) or in the right block (not)

     */

     int rightside = ((unsigned long)block & 0x0000000F);



     blockv = vec_ld(0, block);

     pixelsv1 = vec_ld(0, (unsigned char*)pixels);

     pixelsv2 = vec_ld(16, (unsigned char*)pixels);

     pixelsv = vec_perm(pixelsv1, pixelsv2, vec_lvsl(0, pixels));



     if (rightside)

     {

       pixelsv = vec_perm(blockv, pixelsv, vcprm(0,1,s0,s1));

     }

     else

     {

       pixelsv = vec_perm(blockv, pixelsv, vcprm(s0,s1,2,3));

     }



     blockv = vec_avg(blockv, pixelsv);



     vec_st(blockv, 0, block);



     pixels += line_size;

     block += line_size;

   }



POWERPC_TBL_STOP_COUNT(altivec_avg_pixels8_num, 1);



#endif /* ALTIVEC_USE_REFERENCE_C_CODE */

}

int avformat_open_input(AVFormatContext **ps, const char *filename,

                        AVInputFormat *fmt, AVDictionary **options)

{

    AVFormatContext *s = *ps;

    int ret = 0;

    AVDictionary *tmp = NULL;

    ID3v2ExtraMeta *id3v2_extra_meta = NULL;



    if (!s && !(s = avformat_alloc_context()))

        return AVERROR(ENOMEM);

    if (!s->av_class) {

        av_log(NULL, AV_LOG_ERROR, "Input context has not been properly allocated by avformat_alloc_context() and is not NULL either\n");

        return AVERROR(EINVAL);

    }

    if (fmt)

        s->iformat = fmt;



    if (options)

        av_dict_copy(&tmp, *options, 0);



    if ((ret = av_opt_set_dict(s, &tmp)) < 0)

        goto fail;



    if ((ret = init_input(s, filename, &tmp)) < 0)

        goto fail;

    s->probe_score = ret;

    avio_skip(s->pb, s->skip_initial_bytes);



    /* Check filename in case an image number is expected. */

    if (s->iformat->flags & AVFMT_NEEDNUMBER) {

        if (!av_filename_number_test(filename)) {

            ret = AVERROR(EINVAL);

            goto fail;

        }

    }



    s->duration = s->start_time = AV_NOPTS_VALUE;

    av_strlcpy(s->filename, filename ? filename : "", sizeof(s->filename));



    /* Allocate private data. */

    if (s->iformat->priv_data_size > 0) {

        if (!(s->priv_data = av_mallocz(s->iformat->priv_data_size))) {

            ret = AVERROR(ENOMEM);

            goto fail;

        }

        if (s->iformat->priv_class) {

            *(const AVClass **) s->priv_data = s->iformat->priv_class;

            av_opt_set_defaults(s->priv_data);

            if ((ret = av_opt_set_dict(s->priv_data, &tmp)) < 0)

                goto fail;

        }

    }



    /* e.g. AVFMT_NOFILE formats will not have a AVIOContext */

    if (s->pb)

        ff_id3v2_read(s, ID3v2_DEFAULT_MAGIC, &id3v2_extra_meta);



    if (!(s->flags&AVFMT_FLAG_PRIV_OPT) && s->iformat->read_header)

        if ((ret = s->iformat->read_header(s)) < 0)

            goto fail;



    if (id3v2_extra_meta) {

        if (!strcmp(s->iformat->name, "mp3") || !strcmp(s->iformat->name, "aac") ||

            !strcmp(s->iformat->name, "tta")) {

            if ((ret = ff_id3v2_parse_apic(s, &id3v2_extra_meta)) < 0)

                goto fail;

        } else

            av_log(s, AV_LOG_DEBUG, "demuxer does not support additional id3 data, skipping\n");

    }

    ff_id3v2_free_extra_meta(&id3v2_extra_meta);



    if ((ret = avformat_queue_attached_pictures(s)) < 0)

        goto fail;



    if (!(s->flags&AVFMT_FLAG_PRIV_OPT) && s->pb && !s->data_offset)

        s->data_offset = avio_tell(s->pb);



    s->raw_packet_buffer_remaining_size = RAW_PACKET_BUFFER_SIZE;



    if (options) {

        av_dict_free(options);

        *options = tmp;

    }

    *ps = s;

    return 0;



fail:

    ff_id3v2_free_extra_meta(&id3v2_extra_meta);

    av_dict_free(&tmp);

    if (s->pb && !(s->flags & AVFMT_FLAG_CUSTOM_IO))

        avio_close(s->pb);

    avformat_free_context(s);

    *ps = NULL;

    return ret;

}

static av_always_inline void hl_decode_mb_predict_luma(const H264Context *h,

                                                       H264SliceContext *sl,

                                                       int mb_type, int simple,

                                                       int transform_bypass,

                                                       int pixel_shift,

                                                       const int *block_offset,

                                                       int linesize,

                                                       uint8_t *dest_y, int p)

{

    void (*idct_add)(uint8_t *dst, int16_t *block, int stride);

    void (*idct_dc_add)(uint8_t *dst, int16_t *block, int stride);

    int i;

    int qscale = p == 0 ? sl->qscale : sl->chroma_qp[p - 1];

    block_offset += 16 * p;

    if (IS_INTRA4x4(mb_type)) {

        if (IS_8x8DCT(mb_type)) {

            if (transform_bypass) {

                idct_dc_add =

                idct_add    = h->h264dsp.h264_add_pixels8_clear;

            } else {

                idct_dc_add = h->h264dsp.h264_idct8_dc_add;

                idct_add    = h->h264dsp.h264_idct8_add;

            }

            for (i = 0; i < 16; i += 4) {

                uint8_t *const ptr = dest_y + block_offset[i];

                const int dir      = sl->intra4x4_pred_mode_cache[scan8[i]];

                if (transform_bypass && h->sps.profile_idc == 244 && dir <= 1) {

                    h->hpc.pred8x8l_add[dir](ptr, sl->mb + (i * 16 + p * 256 << pixel_shift), linesize);

                } else {

                    const int nnz = sl->non_zero_count_cache[scan8[i + p * 16]];

                    h->hpc.pred8x8l[dir](ptr, (sl->topleft_samples_available << i) & 0x8000,

                                         (sl->topright_samples_available << i) & 0x4000, linesize);

                    if (nnz) {

                        if (nnz == 1 && dctcoef_get(sl->mb, pixel_shift, i * 16 + p * 256))

                            idct_dc_add(ptr, sl->mb + (i * 16 + p * 256 << pixel_shift), linesize);

                        else

                            idct_add(ptr, sl->mb + (i * 16 + p * 256 << pixel_shift), linesize);

                    }

                }

            }

        } else {

            if (transform_bypass) {

                idct_dc_add  =

                idct_add     = h->h264dsp.h264_add_pixels4_clear;

            } else {

                idct_dc_add = h->h264dsp.h264_idct_dc_add;

                idct_add    = h->h264dsp.h264_idct_add;

            }

            for (i = 0; i < 16; i++) {

                uint8_t *const ptr = dest_y + block_offset[i];

                const int dir      = sl->intra4x4_pred_mode_cache[scan8[i]];



                if (transform_bypass && h->sps.profile_idc == 244 && dir <= 1) {

                    h->hpc.pred4x4_add[dir](ptr, sl->mb + (i * 16 + p * 256 << pixel_shift), linesize);

                } else {

                    uint8_t *topright;

                    int nnz, tr;

                    uint64_t tr_high;

                    if (dir == DIAG_DOWN_LEFT_PRED || dir == VERT_LEFT_PRED) {

                        const int topright_avail = (sl->topright_samples_available << i) & 0x8000;

                        assert(sl->mb_y || linesize <= block_offset[i]);

                        if (!topright_avail) {

                            if (pixel_shift) {

                                tr_high  = ((uint16_t *)ptr)[3 - linesize / 2] * 0x0001000100010001ULL;

                                topright = (uint8_t *)&tr_high;

                            } else {

                                tr       = ptr[3 - linesize] * 0x01010101u;

                                topright = (uint8_t *)&tr;

                            }

                        } else

                            topright = ptr + (4 << pixel_shift) - linesize;

                    } else

                        topright = NULL;



                    h->hpc.pred4x4[dir](ptr, topright, linesize);

                    nnz = sl->non_zero_count_cache[scan8[i + p * 16]];

                    if (nnz) {

                        if (nnz == 1 && dctcoef_get(sl->mb, pixel_shift, i * 16 + p * 256))

                            idct_dc_add(ptr, sl->mb + (i * 16 + p * 256 << pixel_shift), linesize);

                        else

                            idct_add(ptr, sl->mb + (i * 16 + p * 256 << pixel_shift), linesize);

                    }

                }

            }

        }

    } else {

        h->hpc.pred16x16[sl->intra16x16_pred_mode](dest_y, linesize);

        if (sl->non_zero_count_cache[scan8[LUMA_DC_BLOCK_INDEX + p]]) {

            if (!transform_bypass)

                h->h264dsp.h264_luma_dc_dequant_idct(sl->mb + (p * 256 << pixel_shift),

                                                     sl->mb_luma_dc[p],

                                                     h->dequant4_coeff[p][qscale][0]);

            else {

                static const uint8_t dc_mapping[16] = {

                     0 * 16,  1 * 16,  4 * 16,  5 * 16,

                     2 * 16,  3 * 16,  6 * 16,  7 * 16,

                     8 * 16,  9 * 16, 12 * 16, 13 * 16,

                    10 * 16, 11 * 16, 14 * 16, 15 * 16

                };

                for (i = 0; i < 16; i++)

                    dctcoef_set(sl->mb + (p * 256 << pixel_shift),

                                pixel_shift, dc_mapping[i],

                                dctcoef_get(sl->mb_luma_dc[p],

                                            pixel_shift, i));

            }

        }

    }

}

static void peak_write_chunk(AVFormatContext *s)

{

    WAVMuxContext *wav = s->priv_data;

    AVIOContext *pb = s->pb;

    AVCodecContext *enc = s->streams[0]->codec;

    int64_t peak = ff_start_tag(s->pb, "levl");

    int64_t now0;

    time_t now_secs;

    char timestamp[28];



    /* Peak frame of incomplete block at end */

    if (wav->peak_block_pos)

        peak_write_frame(s);



    memset(timestamp, 0, sizeof(timestamp));

    if (!(s->flags & AVFMT_FLAG_BITEXACT)) {

        struct tm tmpbuf;

        av_log(s, AV_LOG_INFO, "Writing local time and date to Peak Envelope Chunk\n");

        now0 = av_gettime();

        now_secs = now0 / 1000000;

        strftime(timestamp, sizeof(timestamp), "%Y:%m:%d:%H:%M:%S:", localtime_r(&now_secs, &tmpbuf));

        av_strlcatf(timestamp, sizeof(timestamp), "%03d", (int)((now0 / 1000) % 1000));

    }



    avio_wl32(pb, 1);                           /* version */

    avio_wl32(pb, wav->peak_format);            /* 8 or 16 bit */

    avio_wl32(pb, wav->peak_ppv);               /* positive and negative */

    avio_wl32(pb, wav->peak_block_size);        /* frames per value */

    avio_wl32(pb, enc->channels);               /* number of channels */

    avio_wl32(pb, wav->peak_num_frames);        /* number of peak frames */

    avio_wl32(pb, wav->peak_pos_pop);           /* audio sample frame index */

    avio_wl32(pb, 128);                         /* equal to size of header */

    avio_write(pb, timestamp, 28);              /* ASCII time stamp */

    ffio_fill(pb, 0, 60);



    avio_write(pb, wav->peak_output, wav->peak_outbuf_bytes);



    ff_end_tag(pb, peak);



    if (!wav->data)

        wav->data = peak;

}

