static void audio_capture(void *opaque, void *buf, int size)

{

    VncState *vs = opaque;



    vnc_lock_output(vs);

    vnc_write_u8(vs, VNC_MSG_SERVER_QEMU);

    vnc_write_u8(vs, VNC_MSG_SERVER_QEMU_AUDIO);

    vnc_write_u16(vs, VNC_MSG_SERVER_QEMU_AUDIO_DATA);

    vnc_write_u32(vs, size);

    vnc_write(vs, buf, size);

    vnc_unlock_output(vs);

    vnc_flush(vs);

}

void ff_aac_search_for_ltp(AACEncContext *s, SingleChannelElement *sce,

                           int common_window)

{

    int w, g, w2, i, start = 0, count = 0;

    int saved_bits = -(15 + FFMIN(sce->ics.max_sfb, MAX_LTP_LONG_SFB));

    float *C34 = &s->scoefs[128*0], *PCD = &s->scoefs[128*1];

    float *PCD34 = &s->scoefs[128*2];

    const int max_ltp = FFMIN(sce->ics.max_sfb, MAX_LTP_LONG_SFB);



    if (sce->ics.window_sequence[0] == EIGHT_SHORT_SEQUENCE ||

        !sce->ics.ltp.lag)

        return;



    for (w = 0; w < sce->ics.num_windows; w += sce->ics.group_len[w]) {

        start = 0;

        for (g = 0;  g < sce->ics.num_swb; g++) {

            int bits1 = 0, bits2 = 0;

            float dist1 = 0.0f, dist2 = 0.0f;

            if (w*16+g > max_ltp) {

                start += sce->ics.swb_sizes[g];

                continue;

            }

            for (w2 = 0; w2 < sce->ics.group_len[w]; w2++) {

                int bits_tmp1, bits_tmp2;

                FFPsyBand *band = &s->psy.ch[s->cur_channel].psy_bands[(w+w2)*16+g];

                for (i = 0; i < sce->ics.swb_sizes[g]; i++)

                    PCD[i] = sce->coeffs[start+(w+w2)*128+i] - sce->lcoeffs[start+(w+w2)*128+i];

                abs_pow34_v(C34,  &sce->coeffs[start+(w+w2)*128],  sce->ics.swb_sizes[g]);

                abs_pow34_v(PCD34, PCD, sce->ics.swb_sizes[g]);

                dist1 += quantize_band_cost(s, &sce->coeffs[start+(w+w2)*128], C34, sce->ics.swb_sizes[g],

                                            sce->sf_idx[(w+w2)*16+g], sce->band_type[(w+w2)*16+g],

                                            s->lambda/band->threshold, INFINITY, &bits_tmp1, NULL, 0);

                dist2 += quantize_band_cost(s, PCD, PCD34, sce->ics.swb_sizes[g],

                                            sce->sf_idx[(w+w2)*16+g],

                                            sce->band_type[(w+w2)*16+g],

                                            s->lambda/band->threshold, INFINITY, &bits_tmp2, NULL, 0);

                bits1 += bits_tmp1;

                bits2 += bits_tmp2;

            }

            if (dist2 < dist1 && bits2 < bits1) {

                for (w2 = 0; w2 < sce->ics.group_len[w]; w2++)

                    for (i = 0; i < sce->ics.swb_sizes[g]; i++)

                        sce->coeffs[start+(w+w2)*128+i] -= sce->lcoeffs[start+(w+w2)*128+i];

                sce->ics.ltp.used[w*16+g] = 1;

                saved_bits += bits1 - bits2;

                count++;

            }

            start += sce->ics.swb_sizes[g];

        }

    }



    sce->ics.ltp.present = !!count && (saved_bits >= 0);

    sce->ics.predictor_present = !!sce->ics.ltp.present;



    /* Reset any marked sfbs */

    if (!sce->ics.ltp.present && !!count) {

        for (w = 0; w < sce->ics.num_windows; w += sce->ics.group_len[w]) {

            start = 0;

            for (g = 0;  g < sce->ics.num_swb; g++) {

                if (sce->ics.ltp.used[w*16+g]) {

                    for (w2 = 0; w2 < sce->ics.group_len[w]; w2++) {

                        for (i = 0; i < sce->ics.swb_sizes[g]; i++) {

                            sce->coeffs[start+(w+w2)*128+i] += sce->lcoeffs[start+(w+w2)*128+i];

                        }

                    }

                }

                start += sce->ics.swb_sizes[g];

            }

        }

    }

}

void av_opencl_buffer_release(cl_mem *cl_buf)

{

    cl_int status = 0;

    if (!cl_buf)

        return;

    status = clReleaseMemObject(*cl_buf);

    if (status != CL_SUCCESS) {

        av_log(&openclutils, AV_LOG_ERROR, "Could not release OpenCL buffer: %s\n", opencl_errstr(status));

    }

    memset(cl_buf, 0, sizeof(*cl_buf));

}

int inet_connect_opts(QemuOpts *opts, bool *in_progress, Error **errp)

{

    struct addrinfo ai,*res,*e;

    const char *addr;

    const char *port;

    char uaddr[INET6_ADDRSTRLEN+1];

    char uport[33];

    int sock,rc;

    bool block;



    memset(&ai,0, sizeof(ai));

    ai.ai_flags = AI_CANONNAME | AI_ADDRCONFIG;

    ai.ai_family = PF_UNSPEC;

    ai.ai_socktype = SOCK_STREAM;



    if (in_progress) {

        *in_progress = false;

    }



    addr = qemu_opt_get(opts, "host");

    port = qemu_opt_get(opts, "port");

    block = qemu_opt_get_bool(opts, "block", 0);

    if (addr == NULL || port == NULL) {

        fprintf(stderr, "inet_connect: host and/or port not specified\n");

        error_set(errp, QERR_SOCKET_CREATE_FAILED);

        return -1;

    }



    if (qemu_opt_get_bool(opts, "ipv4", 0))

        ai.ai_family = PF_INET;

    if (qemu_opt_get_bool(opts, "ipv6", 0))

        ai.ai_family = PF_INET6;



    /* lookup */

    if (0 != (rc = getaddrinfo(addr, port, &ai, &res))) {

        fprintf(stderr,"getaddrinfo(%s,%s): %s\n", addr, port,

                gai_strerror(rc));

        error_set(errp, QERR_SOCKET_CREATE_FAILED);

	return -1;

    }



    for (e = res; e != NULL; e = e->ai_next) {

        if (getnameinfo((struct sockaddr*)e->ai_addr,e->ai_addrlen,

                            uaddr,INET6_ADDRSTRLEN,uport,32,

                            NI_NUMERICHOST | NI_NUMERICSERV) != 0) {

            fprintf(stderr,"%s: getnameinfo: oops\n", __FUNCTION__);

            continue;

        }

        sock = qemu_socket(e->ai_family, e->ai_socktype, e->ai_protocol);

        if (sock < 0) {

            fprintf(stderr,"%s: socket(%s): %s\n", __FUNCTION__,

            inet_strfamily(e->ai_family), strerror(errno));

            continue;

        }

        setsockopt(sock,SOL_SOCKET,SO_REUSEADDR,(void*)&on,sizeof(on));

        if (!block) {

            socket_set_nonblock(sock);

        }

        /* connect to peer */

        do {

            rc = 0;

            if (connect(sock, e->ai_addr, e->ai_addrlen) < 0) {

                rc = -socket_error();

            }

        } while (rc == -EINTR);



  #ifdef _WIN32

        if (!block && (rc == -EINPROGRESS || rc == -EWOULDBLOCK

                       || rc == -WSAEALREADY)) {

  #else

        if (!block && (rc == -EINPROGRESS)) {

  #endif

            if (in_progress) {

                *in_progress = true;

            }



            error_set(errp, QERR_SOCKET_CONNECT_IN_PROGRESS);

        } else if (rc < 0) {

            if (NULL == e->ai_next)

                fprintf(stderr, "%s: connect(%s,%s,%s,%s): %s\n", __FUNCTION__,

                        inet_strfamily(e->ai_family),

                        e->ai_canonname, uaddr, uport, strerror(errno));

            closesocket(sock);

            continue;

        }

        freeaddrinfo(res);

        return sock;

    }

    error_set(errp, QERR_SOCKET_CONNECT_FAILED);

    freeaddrinfo(res);

    return -1;

}

int ff_rv34_decode_frame(AVCodecContext *avctx,

                            void *data, int *got_picture_ptr,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    RV34DecContext *r = avctx->priv_data;

    MpegEncContext *s = &r->s;

    AVFrame *pict = data;

    SliceInfo si;

    int i, ret;

    int slice_count;

    const uint8_t *slices_hdr = NULL;

    int last = 0;



    /* no supplementary picture */

    if (buf_size == 0) {

        /* special case for last picture */

        if (s->low_delay==0 && s->next_picture_ptr) {

            if ((ret = av_frame_ref(pict, &s->next_picture_ptr->f)) < 0)

                return ret;

            s->next_picture_ptr = NULL;



            *got_picture_ptr = 1;

        }

        return 0;

    }



    if(!avctx->slice_count){

        slice_count = (*buf++) + 1;

        slices_hdr = buf + 4;

        buf += 8 * slice_count;

        buf_size -= 1 + 8 * slice_count;

    }else

        slice_count = avctx->slice_count;



    //parse first slice header to check whether this frame can be decoded

    if(get_slice_offset(avctx, slices_hdr, 0) < 0 ||

       get_slice_offset(avctx, slices_hdr, 0) > buf_size){

        av_log(avctx, AV_LOG_ERROR, "Slice offset is invalid\n");

        return AVERROR_INVALIDDATA;

    }

    init_get_bits(&s->gb, buf+get_slice_offset(avctx, slices_hdr, 0), (buf_size-get_slice_offset(avctx, slices_hdr, 0))*8);

    if(r->parse_slice_header(r, &r->s.gb, &si) < 0 || si.start){

        av_log(avctx, AV_LOG_ERROR, "First slice header is incorrect\n");

        return AVERROR_INVALIDDATA;

    }

    if ((!s->last_picture_ptr || !s->last_picture_ptr->f.data[0]) &&

        si.type == AV_PICTURE_TYPE_B) {

        av_log(avctx, AV_LOG_ERROR, "Invalid decoder state: B-frame without "

               "reference data.\n");

        return AVERROR_INVALIDDATA;

    }

    if(   (avctx->skip_frame >= AVDISCARD_NONREF && si.type==AV_PICTURE_TYPE_B)

       || (avctx->skip_frame >= AVDISCARD_NONKEY && si.type!=AV_PICTURE_TYPE_I)

       ||  avctx->skip_frame >= AVDISCARD_ALL)

        return avpkt->size;



    /* first slice */

    if (si.start == 0) {

        if (s->mb_num_left > 0) {

            av_log(avctx, AV_LOG_ERROR, "New frame but still %d MB left.",

                   s->mb_num_left);

            ff_er_frame_end(&s->er);

            ff_MPV_frame_end(s);

        }



        if (s->width != si.width || s->height != si.height) {

            int err;



            av_log(s->avctx, AV_LOG_WARNING, "Changing dimensions to %dx%d\n",

                   si.width, si.height);



            s->width  = si.width;

            s->height = si.height;



            err = ff_set_dimensions(s->avctx, s->width, s->height);

            if (err < 0)

                return err;



            if ((err = ff_MPV_common_frame_size_change(s)) < 0)

                return err;

            if ((err = rv34_decoder_realloc(r)) < 0)

                return err;

        }

        s->pict_type = si.type ? si.type : AV_PICTURE_TYPE_I;

        if (ff_MPV_frame_start(s, s->avctx) < 0)

            return -1;

        ff_mpeg_er_frame_start(s);

        if (!r->tmp_b_block_base) {

            int i;



            r->tmp_b_block_base = av_malloc(s->linesize * 48);

            for (i = 0; i < 2; i++)

                r->tmp_b_block_y[i] = r->tmp_b_block_base

                                      + i * 16 * s->linesize;

            for (i = 0; i < 4; i++)

                r->tmp_b_block_uv[i] = r->tmp_b_block_base + 32 * s->linesize

                                       + (i >> 1) * 8 * s->uvlinesize

                                       + (i &  1) * 16;

        }

        r->cur_pts = si.pts;

        if (s->pict_type != AV_PICTURE_TYPE_B) {

            r->last_pts = r->next_pts;

            r->next_pts = r->cur_pts;

        } else {

            int refdist = GET_PTS_DIFF(r->next_pts, r->last_pts);

            int dist0   = GET_PTS_DIFF(r->cur_pts,  r->last_pts);

            int dist1   = GET_PTS_DIFF(r->next_pts, r->cur_pts);



            if(!refdist){

                r->mv_weight1 = r->mv_weight2 = r->weight1 = r->weight2 = 8192;

                r->scaled_weight = 0;

            }else{

                r->mv_weight1 = (dist0 << 14) / refdist;

                r->mv_weight2 = (dist1 << 14) / refdist;

                if((r->mv_weight1|r->mv_weight2) & 511){

                    r->weight1 = r->mv_weight1;

                    r->weight2 = r->mv_weight2;

                    r->scaled_weight = 0;

                }else{

                    r->weight1 = r->mv_weight1 >> 9;

                    r->weight2 = r->mv_weight2 >> 9;

                    r->scaled_weight = 1;

                }

            }

        }

        s->mb_x = s->mb_y = 0;

        ff_thread_finish_setup(s->avctx);

    } else if (HAVE_THREADS &&

               (s->avctx->active_thread_type & FF_THREAD_FRAME)) {

        av_log(s->avctx, AV_LOG_ERROR, "Decoder needs full frames in frame "

               "multithreading mode (start MB is %d).\n", si.start);

        return AVERROR_INVALIDDATA;

    }



    for(i = 0; i < slice_count; i++){

        int offset = get_slice_offset(avctx, slices_hdr, i);

        int size;

        if(i+1 == slice_count)

            size = buf_size - offset;

        else

            size = get_slice_offset(avctx, slices_hdr, i+1) - offset;



        if(offset < 0 || offset > buf_size){

            av_log(avctx, AV_LOG_ERROR, "Slice offset is invalid\n");

            break;

        }



        r->si.end = s->mb_width * s->mb_height;

        s->mb_num_left = r->s.mb_x + r->s.mb_y*r->s.mb_width - r->si.start;



        if(i+1 < slice_count){

            if (get_slice_offset(avctx, slices_hdr, i+1) < 0 ||

                get_slice_offset(avctx, slices_hdr, i+1) > buf_size) {

                av_log(avctx, AV_LOG_ERROR, "Slice offset is invalid\n");

                break;

            }

            init_get_bits(&s->gb, buf+get_slice_offset(avctx, slices_hdr, i+1), (buf_size-get_slice_offset(avctx, slices_hdr, i+1))*8);

            if(r->parse_slice_header(r, &r->s.gb, &si) < 0){

                if(i+2 < slice_count)

                    size = get_slice_offset(avctx, slices_hdr, i+2) - offset;

                else

                    size = buf_size - offset;

            }else

                r->si.end = si.start;

        }

        if (size < 0 || size > buf_size - offset) {

            av_log(avctx, AV_LOG_ERROR, "Slice size is invalid\n");

            break;

        }

        last = rv34_decode_slice(r, r->si.end, buf + offset, size);

        if(last)

            break;

    }



    if (s->current_picture_ptr) {

        if (last) {

            if(r->loop_filter)

                r->loop_filter(r, s->mb_height - 1);



            ret = finish_frame(avctx, pict);

            if (ret < 0)

                return ret;

            *got_picture_ptr = ret;

        } else if (HAVE_THREADS &&

                   (s->avctx->active_thread_type & FF_THREAD_FRAME)) {

            av_log(avctx, AV_LOG_INFO, "marking unfished frame as finished\n");

            /* always mark the current frame as finished, frame-mt supports

             * only complete frames */

            ff_er_frame_end(&s->er);

            ff_MPV_frame_end(s);

            s->mb_num_left = 0;

            ff_thread_report_progress(&s->current_picture_ptr->tf, INT_MAX, 0);

            return AVERROR_INVALIDDATA;

        }

    }



    return avpkt->size;

}

static int get_preset_file_2(const char *preset_name, const char *codec_name, AVIOContext **s)

{

    int i, ret = 1;

    char filename[1000];

    const char *base[3] = { getenv("AVCONV_DATADIR"),

                            getenv("HOME"),

                            AVCONV_DATADIR,

                            };



    for (i = 0; i < FF_ARRAY_ELEMS(base) && ret; i++) {

        if (!base[i])

            continue;

        if (codec_name) {

            snprintf(filename, sizeof(filename), "%s%s/%s-%s.avpreset", base[i],

                     i != 1 ? "" : "/.avconv", codec_name, preset_name);

            ret = avio_open2(s, filename, AVIO_FLAG_READ, &int_cb, NULL);

        }

        if (ret) {

            snprintf(filename, sizeof(filename), "%s%s/%s.avpreset", base[i],

                     i != 1 ? "" : "/.avconv", preset_name);

            ret = avio_open2(s, filename, AVIO_FLAG_READ, &int_cb, NULL);

        }

    }

    return ret;

}

static int mov_write_mvhd_tag(ByteIOContext *pb, MOVContext *mov)

{

    int maxTrackID = 1, i;

    int64_t maxTrackLenTemp, maxTrackLen = 0;

    int version;



    for (i=0; i<MAX_STREAMS; i++) {

        if(mov->tracks[i].entry > 0) {

            maxTrackLenTemp = av_rescale_rnd(mov->tracks[i].trackDuration, globalTimescale, mov->tracks[i].timescale, AV_ROUND_UP);

            if(maxTrackLen < maxTrackLenTemp)

                maxTrackLen = maxTrackLenTemp;

            if(maxTrackID < mov->tracks[i].trackID)

                maxTrackID = mov->tracks[i].trackID;

        }

    }



    version = maxTrackLen < UINT32_MAX ? 0 : 1;

    (version == 1) ? put_be32(pb, 120) : put_be32(pb, 108); /* size */

    put_tag(pb, "mvhd");

    put_byte(pb, version);

    put_be24(pb, 0); /* flags */

    if (version == 1) {

        put_be64(pb, mov->time);

        put_be64(pb, mov->time);

    } else {

        put_be32(pb, mov->time); /* creation time */

        put_be32(pb, mov->time); /* modification time */

    }

    put_be32(pb, mov->timescale); /* timescale */

    (version == 1) ? put_be64(pb, maxTrackLen) : put_be32(pb, maxTrackLen); /* duration of longest track */



    put_be32(pb, 0x00010000); /* reserved (preferred rate) 1.0 = normal */

    put_be16(pb, 0x0100); /* reserved (preferred volume) 1.0 = normal */

    put_be16(pb, 0); /* reserved */

    put_be32(pb, 0); /* reserved */

    put_be32(pb, 0); /* reserved */



    /* Matrix structure */

    put_be32(pb, 0x00010000); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x00010000); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x0); /* reserved */

    put_be32(pb, 0x40000000); /* reserved */



    put_be32(pb, 0); /* reserved (preview time) */

    put_be32(pb, 0); /* reserved (preview duration) */

    put_be32(pb, 0); /* reserved (poster time) */

    put_be32(pb, 0); /* reserved (selection time) */

    put_be32(pb, 0); /* reserved (selection duration) */

    put_be32(pb, 0); /* reserved (current time) */

    put_be32(pb, maxTrackID+1); /* Next track id */

    return 0x6c;

}

static int g2m_init_buffers(G2MContext *c)

{

    int aligned_height;



    if (!c->framebuf || c->old_width < c->width || c->old_height < c->height) {

        c->framebuf_stride = FFALIGN(c->width * 3, 16);

        aligned_height     = FFALIGN(c->height,    16);

        av_free(c->framebuf);

        c->framebuf = av_mallocz(c->framebuf_stride * aligned_height);

        if (!c->framebuf)

            return AVERROR(ENOMEM);

    }

    if (!c->synth_tile || !c->jpeg_tile ||

        c->old_tile_w < c->tile_width ||

        c->old_tile_h < c->tile_height) {

        c->tile_stride = FFALIGN(c->tile_width * 3, 16);

        aligned_height = FFALIGN(c->tile_height,    16);

        av_free(c->synth_tile);

        av_free(c->jpeg_tile);

        av_free(c->kempf_buf);

        av_free(c->kempf_flags);

        c->synth_tile  = av_mallocz(c->tile_stride      * aligned_height);

        c->jpeg_tile   = av_mallocz(c->tile_stride      * aligned_height);

        c->kempf_buf   = av_mallocz((c->tile_width + 1) * aligned_height

                                    + FF_INPUT_BUFFER_PADDING_SIZE);

        c->kempf_flags = av_mallocz( c->tile_width      * aligned_height);

        if (!c->synth_tile || !c->jpeg_tile ||

            !c->kempf_buf || !c->kempf_flags)

            return AVERROR(ENOMEM);

    }



    return 0;

}

static uint32_t rtl8139_io_readb(void *opaque, uint8_t addr)

{

    RTL8139State *s = opaque;

    int ret;



    addr &= 0xff;



    switch (addr)

    {

        case MAC0 ... MAC0+5:

            ret = s->phys[addr - MAC0];

            break;

        case MAC0+6 ... MAC0+7:

            ret = 0;

            break;

        case MAR0 ... MAR0+7:

            ret = s->mult[addr - MAR0];

            break;

        case ChipCmd:

            ret = rtl8139_ChipCmd_read(s);

            break;

        case Cfg9346:

            ret = rtl8139_Cfg9346_read(s);

            break;

        case Config0:

            ret = rtl8139_Config0_read(s);

            break;

        case Config1:

            ret = rtl8139_Config1_read(s);

            break;

        case Config3:

            ret = rtl8139_Config3_read(s);

            break;

        case Config4:

            ret = rtl8139_Config4_read(s);

            break;

        case Config5:

            ret = rtl8139_Config5_read(s);

            break;



        case MediaStatus:

            ret = 0xd0;

            DPRINTF("MediaStatus read 0x%x\n", ret);

            break;



        case HltClk:

            ret = s->clock_enabled;

            DPRINTF("HltClk read 0x%x\n", ret);

            break;



        case PCIRevisionID:

            ret = RTL8139_PCI_REVID;

            DPRINTF("PCI Revision ID read 0x%x\n", ret);

            break;



        case TxThresh:

            ret = s->TxThresh;

            DPRINTF("C+ TxThresh read(b) val=0x%02x\n", ret);

            break;



        case 0x43: /* Part of TxConfig register. Windows driver tries to read it */

            ret = s->TxConfig >> 24;

            DPRINTF("RTL8139C TxConfig at 0x43 read(b) val=0x%02x\n", ret);

            break;



        default:

            DPRINTF("not implemented read(b) addr=0x%x\n", addr);

            ret = 0;

            break;

    }



    return ret;

}

int ff_mpv_common_frame_size_change(MpegEncContext *s)

{

    int i, err = 0;



    if (!s->context_initialized)

        return AVERROR(EINVAL);



    if (s->slice_context_count > 1) {

        for (i = 0; i < s->slice_context_count; i++) {

            free_duplicate_context(s->thread_context[i]);

        }

        for (i = 1; i < s->slice_context_count; i++) {

            av_freep(&s->thread_context[i]);

        }

    } else

        free_duplicate_context(s);



    free_context_frame(s);



    if (s->picture)

        for (i = 0; i < MAX_PICTURE_COUNT; i++) {

                s->picture[i].needs_realloc = 1;

        }



    s->last_picture_ptr         =

    s->next_picture_ptr         =

    s->current_picture_ptr      = NULL;



    // init

    if (s->codec_id == AV_CODEC_ID_MPEG2VIDEO && !s->progressive_sequence)

        s->mb_height = (s->height + 31) / 32 * 2;

    else

        s->mb_height = (s->height + 15) / 16;



    if ((s->width || s->height) &&

        (err = av_image_check_size(s->width, s->height, 0, s->avctx)) < 0)

        goto fail;



    if ((err = init_context_frame(s)))

        goto fail;



    s->thread_context[0]   = s;



    if (s->width && s->height) {

        int nb_slices = s->slice_context_count;

        if (nb_slices > 1) {

            for (i = 1; i < nb_slices; i++) {

                s->thread_context[i] = av_malloc(sizeof(MpegEncContext));

                memcpy(s->thread_context[i], s, sizeof(MpegEncContext));

            }



            for (i = 0; i < nb_slices; i++) {

                if ((err = init_duplicate_context(s->thread_context[i])) < 0)

                    goto fail;

                    s->thread_context[i]->start_mb_y =

                        (s->mb_height * (i) + nb_slices / 2) / nb_slices;

                    s->thread_context[i]->end_mb_y   =

                        (s->mb_height * (i + 1) + nb_slices / 2) / nb_slices;

            }

        } else {

            err = init_duplicate_context(s);

            if (err < 0)

                goto fail;

            s->start_mb_y = 0;

            s->end_mb_y   = s->mb_height;

        }

        s->slice_context_count = nb_slices;

    }



    return 0;

 fail:

    ff_mpv_common_end(s);

    return err;

}

void ff_snow_horizontal_compose97i_mmx(DWTELEM *b, int width){

    const int w2= (width+1)>>1;

    DWTELEM temp[width >> 1];

    const int w_l= (width>>1);

    const int w_r= w2 - 1;

    int i;



    { // Lift 0

        DWTELEM * const ref = b + w2 - 1;



        i = 1;

        b[0] = b[0] - ((W_DM * 2 * ref[1]+W_DO)>>W_DS);

        asm volatile(

            "pcmpeqd    %%mm7, %%mm7         \n\t"

            "pslld        $31, %%mm7         \n\t"

            "psrld        $29, %%mm7         \n\t"

           ::);

        for(; i<w_l-3; i+=4){

            asm volatile(

                "movq     (%1), %%mm2        \n\t"

                "movq    8(%1), %%mm6        \n\t"

                "paddd   4(%1), %%mm2        \n\t"

                "paddd  12(%1), %%mm6        \n\t"

                "movq    %%mm2, %%mm0        \n\t"

                "movq    %%mm6, %%mm4        \n\t"

                "paddd   %%mm2, %%mm2        \n\t"

                "paddd   %%mm6, %%mm6        \n\t"

                "paddd   %%mm0, %%mm2        \n\t"

                "paddd   %%mm4, %%mm6        \n\t"

                "paddd   %%mm7, %%mm2        \n\t"

                "paddd   %%mm7, %%mm6        \n\t"

                "psrad      $3, %%mm2        \n\t"

                "psrad      $3, %%mm6        \n\t"

                "movq     (%0), %%mm0        \n\t"

                "movq    8(%0), %%mm4        \n\t"

                "psubd   %%mm2, %%mm0        \n\t"

                "psubd   %%mm6, %%mm4        \n\t"

                "movq    %%mm0, (%0)         \n\t"

                "movq    %%mm4, 8(%0)        \n\t"

                :: "r"(&b[i]), "r"(&ref[i])

                 : "memory"

               );

        }

        snow_horizontal_compose_lift_lead_out(i, b, b, ref, width, w_l, 0, W_DM, W_DO, W_DS);

    }



    { // Lift 1

        DWTELEM * const dst = b+w2;



        i = 0;

        for(; i<w_r-3; i+=4){

            asm volatile(

                "movq     (%1), %%mm2        \n\t"

                "movq    8(%1), %%mm6        \n\t"

                "paddd   4(%1), %%mm2        \n\t"

                "paddd  12(%1), %%mm6        \n\t"

                "movq     (%0), %%mm0        \n\t"

                "movq    8(%0), %%mm4        \n\t"

                "psubd   %%mm2, %%mm0        \n\t"

                "psubd   %%mm6, %%mm4        \n\t"

                "movq    %%mm0, (%0)         \n\t"

                "movq    %%mm4, 8(%0)        \n\t"

                :: "r"(&dst[i]), "r"(&b[i])

                 : "memory"

               );

        }

        snow_horizontal_compose_lift_lead_out(i, dst, dst, b, width, w_r, 1, W_CM, W_CO, W_CS);

    }



    { // Lift 2

        DWTELEM * const ref = b+w2 - 1;



        i = 1;

        b[0] = b[0] + (((2 * ref[1] + W_BO) + 4 * b[0]) >> W_BS);

        asm volatile(

            "pslld          $1, %%mm7        \n\t"

           ::);

        for(; i<w_l-3; i+=4){

            asm volatile(

                "movq     (%1), %%mm0        \n\t"

                "movq    8(%1), %%mm4        \n\t"

                "paddd   4(%1), %%mm0        \n\t"

                "paddd  12(%1), %%mm4        \n\t"

                "paddd   %%mm7, %%mm0        \n\t"

                "paddd   %%mm7, %%mm4        \n\t"

                "psrad      $2, %%mm0        \n\t"

                "psrad      $2, %%mm4        \n\t"

                "movq     (%0), %%mm1        \n\t"

                "movq    8(%0), %%mm5        \n\t"

                "paddd   %%mm1, %%mm0        \n\t"

                "paddd   %%mm5, %%mm4        \n\t"

                "psrad      $2, %%mm0        \n\t"

                "psrad      $2, %%mm4        \n\t"

                "paddd   %%mm1, %%mm0        \n\t"

                "paddd   %%mm5, %%mm4        \n\t"

                "movq    %%mm0, (%0)         \n\t"

                "movq    %%mm4, 8(%0)        \n\t"

                :: "r"(&b[i]), "r"(&ref[i])

                 : "memory"

               );

        }

        snow_horizontal_compose_liftS_lead_out(i, b, b, ref, width, w_l);

    }



    { // Lift 3

        DWTELEM * const src = b+w2;

        i = 0;



        for(; i<w_r-3; i+=4){

            asm volatile(

                "movq    4(%1), %%mm2        \n\t"

                "movq   12(%1), %%mm6        \n\t"

                "paddd    (%1), %%mm2        \n\t"

                "paddd   8(%1), %%mm6        \n\t"

                "movq     (%0), %%mm0        \n\t"

                "movq    8(%0), %%mm4        \n\t"

                "paddd   %%mm2, %%mm0        \n\t"

                "paddd   %%mm6, %%mm4        \n\t"

                "psrad      $1, %%mm2        \n\t"

                "psrad      $1, %%mm6        \n\t"

                "paddd   %%mm0, %%mm2        \n\t"

                "paddd   %%mm4, %%mm6        \n\t"

                "movq    %%mm2, (%2)         \n\t"

                "movq    %%mm6, 8(%2)        \n\t"

                :: "r"(&src[i]), "r"(&b[i]), "r"(&temp[i])

                 : "memory"

               );

        }

        snow_horizontal_compose_lift_lead_out(i, temp, src, b, width, w_r, 1, -W_AM, W_AO+1, W_AS);

    }



    {

        snow_interleave_line_header(&i, width, b, temp);



        for (; (i & 0xE) != 0xE; i-=2){

            b[i+1] = temp[i>>1];

            b[i] = b[i>>1];

        }

        for (i-=14; i>=0; i-=16){

            asm volatile(

                "movq        (%1), %%mm0       \n\t"

                "movq       8(%1), %%mm2       \n\t"

                "movq      16(%1), %%mm4       \n\t"

                "movq      24(%1), %%mm6       \n\t"

                "movq        (%1), %%mm1       \n\t"

                "movq       8(%1), %%mm3       \n\t"

                "movq      16(%1), %%mm5       \n\t"

                "movq      24(%1), %%mm7       \n\t"

                "punpckldq   (%2), %%mm0       \n\t"

                "punpckldq  8(%2), %%mm2       \n\t"

                "punpckldq 16(%2), %%mm4       \n\t"

                "punpckldq 24(%2), %%mm6       \n\t"

                "movq       %%mm0, (%0)        \n\t"

                "movq       %%mm2, 16(%0)      \n\t"

                "movq       %%mm4, 32(%0)      \n\t"

                "movq       %%mm6, 48(%0)      \n\t"

                "punpckhdq   (%2), %%mm1       \n\t"

                "punpckhdq  8(%2), %%mm3       \n\t"

                "punpckhdq 16(%2), %%mm5       \n\t"

                "punpckhdq 24(%2), %%mm7       \n\t"

                "movq       %%mm1, 8(%0)       \n\t"

                "movq       %%mm3, 24(%0)      \n\t"

                "movq       %%mm5, 40(%0)      \n\t"

                "movq       %%mm7, 56(%0)      \n\t"

                :: "r"(&b[i]), "r"(&b[i>>1]), "r"(&temp[i>>1])

                 : "memory"

               );

        }

    }

}

static int oma_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    OMAContext *oc = s->priv_data;

    int packet_size = s->streams[0]->codec->block_align;

    int ret = av_get_packet(s->pb, pkt, packet_size);



    if (ret <= 0)

        return AVERROR(EIO);



    pkt->stream_index = 0;



    if (oc->encrypted) {

        /* previous unencrypted block saved in IV for

         * the next packet (CBC mode) */

        av_des_crypt(&oc->av_des, pkt->data, pkt->data,

                     (packet_size >> 3), oc->iv, 1);

    }



    return ret;

}

static int rtsp_fetch_packet(AVFormatContext *s, AVPacket *pkt)

{

    RTSPState *rt = s->priv_data;

    int ret, len;

    uint8_t buf[10 * RTP_MAX_PACKET_LENGTH];

    RTSPStream *rtsp_st;



    /* get next frames from the same RTP packet */

    if (rt->cur_transport_priv) {

        if (rt->transport == RTSP_TRANSPORT_RDT)

            ret = ff_rdt_parse_packet(rt->cur_transport_priv, pkt, NULL, 0);

        else

            ret = rtp_parse_packet(rt->cur_transport_priv, pkt, NULL, 0);

        if (ret == 0) {

            rt->cur_transport_priv = NULL;

            return 0;

        } else if (ret == 1) {

            return 0;

        } else {

            rt->cur_transport_priv = NULL;

        }

    }



    /* read next RTP packet */

 redo:

    switch(rt->lower_transport) {

    default:

#if CONFIG_RTSP_DEMUXER

    case RTSP_LOWER_TRANSPORT_TCP:

        len = tcp_read_packet(s, &rtsp_st, buf, sizeof(buf));

        break;

#endif

    case RTSP_LOWER_TRANSPORT_UDP:

    case RTSP_LOWER_TRANSPORT_UDP_MULTICAST:

        len = udp_read_packet(s, &rtsp_st, buf, sizeof(buf));

        if (len >=0 && rtsp_st->transport_priv && rt->transport == RTSP_TRANSPORT_RTP)

            rtp_check_and_send_back_rr(rtsp_st->transport_priv, len);

        break;

    }

    if (len < 0)

        return len;

    if (len == 0)

        return AVERROR_EOF;

    if (rt->transport == RTSP_TRANSPORT_RDT)

        ret = ff_rdt_parse_packet(rtsp_st->transport_priv, pkt, buf, len);

    else

        ret = rtp_parse_packet(rtsp_st->transport_priv, pkt, buf, len);

    if (ret < 0)

        goto redo;

    if (ret == 1) {

        /* more packets may follow, so we save the RTP context */

        rt->cur_transport_priv = rtsp_st->transport_priv;

    }



    return ret;

}

rtsp_open_transport_ctx(AVFormatContext *s, RTSPStream *rtsp_st)

{

    RTSPState *rt = s->priv_data;

    AVStream *st = NULL;



    /* open the RTP context */

    if (rtsp_st->stream_index >= 0)

        st = s->streams[rtsp_st->stream_index];

    if (!st)

        s->ctx_flags |= AVFMTCTX_NOHEADER;



    if (rt->transport == RTSP_TRANSPORT_RDT)

        rtsp_st->transport_priv = ff_rdt_parse_open(s, st->index,

                                            rtsp_st->dynamic_protocol_context,

                                            rtsp_st->dynamic_handler);

    else

        rtsp_st->transport_priv = rtp_parse_open(s, st, rtsp_st->rtp_handle,

                                         rtsp_st->sdp_payload_type,

                                         &rtsp_st->rtp_payload_data);



    if (!rtsp_st->transport_priv) {

         return AVERROR(ENOMEM);

    } else if (rt->transport != RTSP_TRANSPORT_RDT) {

        if(rtsp_st->dynamic_handler) {

            rtp_parse_set_dynamic_protocol(rtsp_st->transport_priv,

                                           rtsp_st->dynamic_protocol_context,

                                           rtsp_st->dynamic_handler);

        }

    }



    return 0;

}

void net_tx_pkt_update_ip_checksums(struct NetTxPkt *pkt)

{

    uint16_t csum;

    uint32_t ph_raw_csum;

    assert(pkt);

    uint8_t gso_type = pkt->virt_hdr.gso_type & ~VIRTIO_NET_HDR_GSO_ECN;

    struct ip_header *ip_hdr;



    if (VIRTIO_NET_HDR_GSO_TCPV4 != gso_type &&

        VIRTIO_NET_HDR_GSO_UDP != gso_type) {

        return;

    }



    ip_hdr = pkt->vec[NET_TX_PKT_L3HDR_FRAG].iov_base;



    if (pkt->payload_len + pkt->vec[NET_TX_PKT_L3HDR_FRAG].iov_len >

        ETH_MAX_IP_DGRAM_LEN) {

        return;

    }



    ip_hdr->ip_len = cpu_to_be16(pkt->payload_len +

        pkt->vec[NET_TX_PKT_L3HDR_FRAG].iov_len);



    /* Calculate IP header checksum                    */

    ip_hdr->ip_sum = 0;

    csum = net_raw_checksum((uint8_t *)ip_hdr,

        pkt->vec[NET_TX_PKT_L3HDR_FRAG].iov_len);

    ip_hdr->ip_sum = cpu_to_be16(csum);



    /* Calculate IP pseudo header checksum             */

    ph_raw_csum = eth_calc_pseudo_hdr_csum(ip_hdr, pkt->payload_len);

    csum = cpu_to_be16(~net_checksum_finish(ph_raw_csum));

    iov_from_buf(&pkt->vec[NET_TX_PKT_PL_START_FRAG], pkt->payload_frags,

                 pkt->virt_hdr.csum_offset, &csum, sizeof(csum));

}

void ff_print_debug_info2(AVCodecContext *avctx, AVFrame *pict, uint8_t *mbskip_table,

                         uint32_t *mbtype_table, int8_t *qscale_table, int16_t (*motion_val[2])[2],

                         int *low_delay,

                         int mb_width, int mb_height, int mb_stride, int quarter_sample)

{

    if ((avctx->flags2 & AV_CODEC_FLAG2_EXPORT_MVS) && mbtype_table && motion_val[0]) {

        const int shift = 1 + quarter_sample;

        const int mv_sample_log2 = avctx->codec_id == AV_CODEC_ID_H264 || avctx->codec_id == AV_CODEC_ID_SVQ3 ? 2 : 1;

        const int mv_stride      = (mb_width << mv_sample_log2) +

                                   (avctx->codec->id == AV_CODEC_ID_H264 ? 0 : 1);

        int mb_x, mb_y, mbcount = 0;



        /* size is width * height * 2 * 4 where 2 is for directions and 4 is

         * for the maximum number of MB (4 MB in case of IS_8x8) */

        AVMotionVector *mvs = av_malloc_array(mb_width * mb_height, 2 * 4 * sizeof(AVMotionVector));

        if (!mvs)

            return;



        for (mb_y = 0; mb_y < mb_height; mb_y++) {

            for (mb_x = 0; mb_x < mb_width; mb_x++) {

                int i, direction, mb_type = mbtype_table[mb_x + mb_y * mb_stride];

                for (direction = 0; direction < 2; direction++) {

                    if (!USES_LIST(mb_type, direction))

                        continue;

                    if (IS_8X8(mb_type)) {

                        for (i = 0; i < 4; i++) {

                            int sx = mb_x * 16 + 4 + 8 * (i & 1);

                            int sy = mb_y * 16 + 4 + 8 * (i >> 1);

                            int xy = (mb_x * 2 + (i & 1) +

                                      (mb_y * 2 + (i >> 1)) * mv_stride) << (mv_sample_log2 - 1);

                            int mx = (motion_val[direction][xy][0] >> shift) + sx;

                            int my = (motion_val[direction][xy][1] >> shift) + sy;

                            mbcount += add_mb(mvs + mbcount, mb_type, sx, sy, mx, my, direction);

                        }

                    } else if (IS_16X8(mb_type)) {

                        for (i = 0; i < 2; i++) {

                            int sx = mb_x * 16 + 8;

                            int sy = mb_y * 16 + 4 + 8 * i;

                            int xy = (mb_x * 2 + (mb_y * 2 + i) * mv_stride) << (mv_sample_log2 - 1);

                            int mx = (motion_val[direction][xy][0] >> shift);

                            int my = (motion_val[direction][xy][1] >> shift);



                            if (IS_INTERLACED(mb_type))

                                my *= 2;



                            mbcount += add_mb(mvs + mbcount, mb_type, sx, sy, mx + sx, my + sy, direction);

                        }

                    } else if (IS_8X16(mb_type)) {

                        for (i = 0; i < 2; i++) {

                            int sx = mb_x * 16 + 4 + 8 * i;

                            int sy = mb_y * 16 + 8;

                            int xy = (mb_x * 2 + i + mb_y * 2 * mv_stride) << (mv_sample_log2 - 1);

                            int mx = motion_val[direction][xy][0] >> shift;

                            int my = motion_val[direction][xy][1] >> shift;



                            if (IS_INTERLACED(mb_type))

                                my *= 2;



                            mbcount += add_mb(mvs + mbcount, mb_type, sx, sy, mx + sx, my + sy, direction);

                        }

                    } else {

                          int sx = mb_x * 16 + 8;

                          int sy = mb_y * 16 + 8;

                          int xy = (mb_x + mb_y * mv_stride) << mv_sample_log2;

                          int mx = (motion_val[direction][xy][0]>>shift) + sx;

                          int my = (motion_val[direction][xy][1]>>shift) + sy;

                          mbcount += add_mb(mvs + mbcount, mb_type, sx, sy, mx, my, direction);

                    }

                }

            }

        }



        if (mbcount) {

            AVFrameSideData *sd;



            av_log(avctx, AV_LOG_DEBUG, "Adding %d MVs info to frame %d\n", mbcount, avctx->frame_number);

            sd = av_frame_new_side_data(pict, AV_FRAME_DATA_MOTION_VECTORS, mbcount * sizeof(AVMotionVector));

            if (!sd) {

                av_freep(&mvs);

                return;

            }

            memcpy(sd->data, mvs, mbcount * sizeof(AVMotionVector));

        }



        av_freep(&mvs);

    }



    /* TODO: export all the following to make them accessible for users (and filters) */

    if (avctx->hwaccel || !mbtype_table

#if FF_API_CAP_VDPAU

        || (avctx->codec->capabilities&AV_CODEC_CAP_HWACCEL_VDPAU)

#endif

        )

        return;





    if (avctx->debug & (FF_DEBUG_SKIP | FF_DEBUG_QP | FF_DEBUG_MB_TYPE)) {

        int x,y;



        av_log(avctx, AV_LOG_DEBUG, "New frame, type: %c\n",

               av_get_picture_type_char(pict->pict_type));

        for (y = 0; y < mb_height; y++) {

            for (x = 0; x < mb_width; x++) {

                if (avctx->debug & FF_DEBUG_SKIP) {

                    int count = mbskip_table ? mbskip_table[x + y * mb_stride] : 0;

                    if (count > 9)

                        count = 9;

                    av_log(avctx, AV_LOG_DEBUG, "%1d", count);

                }

                if (avctx->debug & FF_DEBUG_QP) {

                    av_log(avctx, AV_LOG_DEBUG, "%2d",

                           qscale_table[x + y * mb_stride]);

                }

                if (avctx->debug & FF_DEBUG_MB_TYPE) {

                    int mb_type = mbtype_table[x + y * mb_stride];

                    // Type & MV direction

                    if (IS_PCM(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "P");

                    else if (IS_INTRA(mb_type) && IS_ACPRED(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "A");

                    else if (IS_INTRA4x4(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "i");

                    else if (IS_INTRA16x16(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "I");

                    else if (IS_DIRECT(mb_type) && IS_SKIP(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "d");

                    else if (IS_DIRECT(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "D");

                    else if (IS_GMC(mb_type) && IS_SKIP(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "g");

                    else if (IS_GMC(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "G");

                    else if (IS_SKIP(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "S");

                    else if (!USES_LIST(mb_type, 1))

                        av_log(avctx, AV_LOG_DEBUG, ">");

                    else if (!USES_LIST(mb_type, 0))

                        av_log(avctx, AV_LOG_DEBUG, "<");

                    else {

                        av_assert2(USES_LIST(mb_type, 0) && USES_LIST(mb_type, 1));

                        av_log(avctx, AV_LOG_DEBUG, "X");

                    }



                    // segmentation

                    if (IS_8X8(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "+");

                    else if (IS_16X8(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "-");

                    else if (IS_8X16(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "|");

                    else if (IS_INTRA(mb_type) || IS_16X16(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, " ");

                    else

                        av_log(avctx, AV_LOG_DEBUG, "?");





                    if (IS_INTERLACED(mb_type))

                        av_log(avctx, AV_LOG_DEBUG, "=");

                    else

                        av_log(avctx, AV_LOG_DEBUG, " ");

                }

            }

            av_log(avctx, AV_LOG_DEBUG, "\n");

        }

    }



    if ((avctx->debug & (FF_DEBUG_VIS_QP | FF_DEBUG_VIS_MB_TYPE)) ||

        (avctx->debug_mv)) {

        int mb_y;

        int i;

        int h_chroma_shift, v_chroma_shift, block_height;

#if FF_API_VISMV

        const int shift = 1 + quarter_sample;

        uint8_t *ptr;

        const int width          = avctx->width;

        const int height         = avctx->height;

#endif

        const int mv_sample_log2 = avctx->codec_id == AV_CODEC_ID_H264 || avctx->codec_id == AV_CODEC_ID_SVQ3 ? 2 : 1;

        const int mv_stride      = (mb_width << mv_sample_log2) +

                                   (avctx->codec->id == AV_CODEC_ID_H264 ? 0 : 1);



        *low_delay = 0; // needed to see the vectors without trashing the buffers



        avcodec_get_chroma_sub_sample(avctx->pix_fmt, &h_chroma_shift, &v_chroma_shift);



        av_frame_make_writable(pict);



        pict->opaque = NULL;

#if FF_API_VISMV

        ptr          = pict->data[0];

#endif

        block_height = 16 >> v_chroma_shift;



        for (mb_y = 0; mb_y < mb_height; mb_y++) {

            int mb_x;

            for (mb_x = 0; mb_x < mb_width; mb_x++) {

                const int mb_index = mb_x + mb_y * mb_stride;

#if FF_API_VISMV

                if ((avctx->debug_mv) && motion_val[0]) {

                    int type;

                    for (type = 0; type < 3; type++) {

                        int direction = 0;

                        switch (type) {

                        case 0:

                            if ((!(avctx->debug_mv & FF_DEBUG_VIS_MV_P_FOR)) ||

                                (pict->pict_type!= AV_PICTURE_TYPE_P))

                                continue;

                            direction = 0;

                            break;

                        case 1:

                            if ((!(avctx->debug_mv & FF_DEBUG_VIS_MV_B_FOR)) ||

                                (pict->pict_type!= AV_PICTURE_TYPE_B))

                                continue;

                            direction = 0;

                            break;

                        case 2:

                            if ((!(avctx->debug_mv & FF_DEBUG_VIS_MV_B_BACK)) ||

                                (pict->pict_type!= AV_PICTURE_TYPE_B))

                                continue;

                            direction = 1;

                            break;

                        }

                        if (!USES_LIST(mbtype_table[mb_index], direction))

                            continue;



                        if (IS_8X8(mbtype_table[mb_index])) {

                            int i;

                            for (i = 0; i < 4; i++) {

                                int sx = mb_x * 16 + 4 + 8 * (i & 1);

                                int sy = mb_y * 16 + 4 + 8 * (i >> 1);

                                int xy = (mb_x * 2 + (i & 1) +

                                          (mb_y * 2 + (i >> 1)) * mv_stride) << (mv_sample_log2 - 1);

                                int mx = (motion_val[direction][xy][0] >> shift) + sx;

                                int my = (motion_val[direction][xy][1] >> shift) + sy;

                                draw_arrow(ptr, sx, sy, mx, my, width,

                                           height, pict->linesize[0], 100, 0, direction);

                            }

                        } else if (IS_16X8(mbtype_table[mb_index])) {

                            int i;

                            for (i = 0; i < 2; i++) {

                                int sx = mb_x * 16 + 8;

                                int sy = mb_y * 16 + 4 + 8 * i;

                                int xy = (mb_x * 2 + (mb_y * 2 + i) * mv_stride) << (mv_sample_log2 - 1);

                                int mx = (motion_val[direction][xy][0] >> shift);

                                int my = (motion_val[direction][xy][1] >> shift);



                                if (IS_INTERLACED(mbtype_table[mb_index]))

                                    my *= 2;



                                draw_arrow(ptr, sx, sy, mx + sx, my + sy, width,

                                           height, pict->linesize[0], 100, 0, direction);

                            }

                        } else if (IS_8X16(mbtype_table[mb_index])) {

                            int i;

                            for (i = 0; i < 2; i++) {

                                int sx = mb_x * 16 + 4 + 8 * i;

                                int sy = mb_y * 16 + 8;

                                int xy = (mb_x * 2 + i + mb_y * 2 * mv_stride) << (mv_sample_log2 - 1);

                                int mx = motion_val[direction][xy][0] >> shift;

                                int my = motion_val[direction][xy][1] >> shift;



                                if (IS_INTERLACED(mbtype_table[mb_index]))

                                    my *= 2;



                                draw_arrow(ptr, sx, sy, mx + sx, my + sy, width,

                                           height, pict->linesize[0], 100, 0, direction);

                            }

                        } else {

                              int sx= mb_x * 16 + 8;

                              int sy= mb_y * 16 + 8;

                              int xy= (mb_x + mb_y * mv_stride) << mv_sample_log2;

                              int mx= (motion_val[direction][xy][0]>>shift) + sx;

                              int my= (motion_val[direction][xy][1]>>shift) + sy;

                              draw_arrow(ptr, sx, sy, mx, my, width, height, pict->linesize[0], 100, 0, direction);

                        }

                    }

                }

#endif

                if ((avctx->debug & FF_DEBUG_VIS_QP)) {

                    uint64_t c = (qscale_table[mb_index] * 128 / 31) *

                                 0x0101010101010101ULL;

                    int y;

                    for (y = 0; y < block_height; y++) {

                        *(uint64_t *)(pict->data[1] + 8 * mb_x +

                                      (block_height * mb_y + y) *

                                      pict->linesize[1]) = c;

                        *(uint64_t *)(pict->data[2] + 8 * mb_x +

                                      (block_height * mb_y + y) *

                                      pict->linesize[2]) = c;

                    }

                }

                if ((avctx->debug & FF_DEBUG_VIS_MB_TYPE) &&

                    motion_val[0]) {

                    int mb_type = mbtype_table[mb_index];

                    uint64_t u,v;

                    int y;

#define COLOR(theta, r) \

    u = (int)(128 + r * cos(theta * 3.141592 / 180)); \

    v = (int)(128 + r * sin(theta * 3.141592 / 180));





                    u = v = 128;

                    if (IS_PCM(mb_type)) {

                        COLOR(120, 48)

                    } else if ((IS_INTRA(mb_type) && IS_ACPRED(mb_type)) ||

                               IS_INTRA16x16(mb_type)) {

                        COLOR(30, 48)

                    } else if (IS_INTRA4x4(mb_type)) {

                        COLOR(90, 48)

                    } else if (IS_DIRECT(mb_type) && IS_SKIP(mb_type)) {

                        // COLOR(120, 48)

                    } else if (IS_DIRECT(mb_type)) {

                        COLOR(150, 48)

                    } else if (IS_GMC(mb_type) && IS_SKIP(mb_type)) {

                        COLOR(170, 48)

                    } else if (IS_GMC(mb_type)) {

                        COLOR(190, 48)

                    } else if (IS_SKIP(mb_type)) {

                        // COLOR(180, 48)

                    } else if (!USES_LIST(mb_type, 1)) {

                        COLOR(240, 48)

                    } else if (!USES_LIST(mb_type, 0)) {

                        COLOR(0, 48)

                    } else {

                        av_assert2(USES_LIST(mb_type, 0) && USES_LIST(mb_type, 1));

                        COLOR(300,48)

                    }



                    u *= 0x0101010101010101ULL;

                    v *= 0x0101010101010101ULL;

                    for (y = 0; y < block_height; y++) {

                        *(uint64_t *)(pict->data[1] + 8 * mb_x +

                                      (block_height * mb_y + y) * pict->linesize[1]) = u;

                        *(uint64_t *)(pict->data[2] + 8 * mb_x +

                                      (block_height * mb_y + y) * pict->linesize[2]) = v;

                    }



                    // segmentation

                    if (IS_8X8(mb_type) || IS_16X8(mb_type)) {

                        *(uint64_t *)(pict->data[0] + 16 * mb_x + 0 +

                                      (16 * mb_y + 8) * pict->linesize[0]) ^= 0x8080808080808080ULL;

                        *(uint64_t *)(pict->data[0] + 16 * mb_x + 8 +

                                      (16 * mb_y + 8) * pict->linesize[0]) ^= 0x8080808080808080ULL;

                    }

                    if (IS_8X8(mb_type) || IS_8X16(mb_type)) {

                        for (y = 0; y < 16; y++)

                            pict->data[0][16 * mb_x + 8 + (16 * mb_y + y) *

                                          pict->linesize[0]] ^= 0x80;

                    }

                    if (IS_8X8(mb_type) && mv_sample_log2 >= 2) {

                        int dm = 1 << (mv_sample_log2 - 2);

                        for (i = 0; i < 4; i++) {

                            int sx = mb_x * 16 + 8 * (i & 1);

                            int sy = mb_y * 16 + 8 * (i >> 1);

                            int xy = (mb_x * 2 + (i & 1) +

                                     (mb_y * 2 + (i >> 1)) * mv_stride) << (mv_sample_log2 - 1);

                            // FIXME bidir

                            int32_t *mv = (int32_t *) &motion_val[0][xy];

                            if (mv[0] != mv[dm] ||

                                mv[dm * mv_stride] != mv[dm * (mv_stride + 1)])

                                for (y = 0; y < 8; y++)

                                    pict->data[0][sx + 4 + (sy + y) * pict->linesize[0]] ^= 0x80;

                            if (mv[0] != mv[dm * mv_stride] || mv[dm] != mv[dm * (mv_stride + 1)])

                                *(uint64_t *)(pict->data[0] + sx + (sy + 4) *

                                              pict->linesize[0]) ^= 0x8080808080808080ULL;

                        }

                    }



                    if (IS_INTERLACED(mb_type) &&

                        avctx->codec->id == AV_CODEC_ID_H264) {

                        // hmm

                    }

                }

                if (mbskip_table)

                    mbskip_table[mb_index] = 0;

            }

        }

    }

}

static void alloc_picture(void *opaque)

{

    VideoState *is = opaque;

    VideoPicture *vp;



    vp = &is->pictq[is->pictq_windex];



    if (vp->bmp)

        SDL_FreeYUVOverlay(vp->bmp);



#if CONFIG_AVFILTER

    if (vp->picref)

        avfilter_unref_buffer(vp->picref);

    vp->picref = NULL;



    vp->width   = is->out_video_filter->inputs[0]->w;

    vp->height  = is->out_video_filter->inputs[0]->h;

    vp->pix_fmt = is->out_video_filter->inputs[0]->format;

#else

    vp->width   = is->video_st->codec->width;

    vp->height  = is->video_st->codec->height;

    vp->pix_fmt = is->video_st->codec->pix_fmt;

#endif



    vp->bmp = SDL_CreateYUVOverlay(vp->width, vp->height,

                                   SDL_YV12_OVERLAY,

                                   screen);











    SDL_LockMutex(is->pictq_mutex);

    vp->allocated = 1;

    SDL_CondSignal(is->pictq_cond);

    SDL_UnlockMutex(is->pictq_mutex);

int css_create_css_image(uint8_t cssid, bool default_image)

{

    trace_css_new_image(cssid, default_image ? "(default)" : "");

    if (cssid > MAX_CSSID) {

        return -EINVAL;

    }

    if (channel_subsys.css[cssid]) {

        return -EBUSY;

    }

    channel_subsys.css[cssid] = g_malloc0(sizeof(CssImage));

    if (default_image) {

        channel_subsys.default_cssid = cssid;

    }

    return 0;

}

static int decode_nal_unit(HEVCContext *s, const HEVCNAL *nal)

{

    HEVCLocalContext *lc = &s->HEVClc;

    GetBitContext *gb    = &lc->gb;

    int ctb_addr_ts, ret;



    ret = init_get_bits8(gb, nal->data, nal->size);

    if (ret < 0)

        return ret;



    ret = hls_nal_unit(s);

    if (ret < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "Invalid NAL unit %d, skipping.\n",

               s->nal_unit_type);

        goto fail;

    } else if (!ret)

        return 0;



    switch (s->nal_unit_type) {

    case NAL_VPS:

        ret = ff_hevc_decode_nal_vps(gb, s->avctx, &s->ps);

        if (ret < 0)

            goto fail;

        break;

    case NAL_SPS:

        ret = ff_hevc_decode_nal_sps(gb, s->avctx, &s->ps,

                                     s->apply_defdispwin);

        if (ret < 0)

            goto fail;

        break;

    case NAL_PPS:

        ret = ff_hevc_decode_nal_pps(gb, s->avctx, &s->ps);

        if (ret < 0)

            goto fail;

        break;

    case NAL_SEI_PREFIX:

    case NAL_SEI_SUFFIX:

        ret = ff_hevc_decode_nal_sei(s);

        if (ret < 0)

            goto fail;

        break;

    case NAL_TRAIL_R:

    case NAL_TRAIL_N:

    case NAL_TSA_N:

    case NAL_TSA_R:

    case NAL_STSA_N:

    case NAL_STSA_R:

    case NAL_BLA_W_LP:

    case NAL_BLA_W_RADL:

    case NAL_BLA_N_LP:

    case NAL_IDR_W_RADL:

    case NAL_IDR_N_LP:

    case NAL_CRA_NUT:

    case NAL_RADL_N:

    case NAL_RADL_R:

    case NAL_RASL_N:

    case NAL_RASL_R:

        ret = hls_slice_header(s);

        if (ret < 0)

            return ret;



        if (s->max_ra == INT_MAX) {

            if (s->nal_unit_type == NAL_CRA_NUT || IS_BLA(s)) {

                s->max_ra = s->poc;

            } else {

                if (IS_IDR(s))

                    s->max_ra = INT_MIN;

            }

        }



        if ((s->nal_unit_type == NAL_RASL_R || s->nal_unit_type == NAL_RASL_N) &&

            s->poc <= s->max_ra) {

            s->is_decoded = 0;

            break;

        } else {

            if (s->nal_unit_type == NAL_RASL_R && s->poc > s->max_ra)

                s->max_ra = INT_MIN;

        }



        if (s->sh.first_slice_in_pic_flag) {

            ret = hevc_frame_start(s);

            if (ret < 0)

                return ret;

        } else if (!s->ref) {

            av_log(s->avctx, AV_LOG_ERROR, "First slice in a frame missing.\n");

            goto fail;

        }



        if (s->nal_unit_type != s->first_nal_type) {

            av_log(s->avctx, AV_LOG_ERROR,

                   "Non-matching NAL types of the VCL NALUs: %d %d\n",

                   s->first_nal_type, s->nal_unit_type);

            return AVERROR_INVALIDDATA;

        }



        if (!s->sh.dependent_slice_segment_flag &&

            s->sh.slice_type != I_SLICE) {

            ret = ff_hevc_slice_rpl(s);

            if (ret < 0) {

                av_log(s->avctx, AV_LOG_WARNING,

                       "Error constructing the reference lists for the current slice.\n");

                goto fail;

            }

        }



        if (s->sh.first_slice_in_pic_flag && s->avctx->hwaccel) {

            ret = s->avctx->hwaccel->start_frame(s->avctx, NULL, 0);

            if (ret < 0)

                goto fail;

        }



        if (s->avctx->hwaccel) {

            ret = s->avctx->hwaccel->decode_slice(s->avctx, nal->raw_data, nal->raw_size);

            if (ret < 0)

                goto fail;

        } else {

            ctb_addr_ts = hls_slice_data(s);

            if (ctb_addr_ts >= (s->ps.sps->ctb_width * s->ps.sps->ctb_height)) {

                s->is_decoded = 1;

                if ((s->ps.pps->transquant_bypass_enable_flag ||

                     (s->ps.sps->pcm.loop_filter_disable_flag && s->ps.sps->pcm_enabled_flag)) &&

                    s->ps.sps->sao_enabled)

                    restore_tqb_pixels(s);

            }



            if (ctb_addr_ts < 0) {

                ret = ctb_addr_ts;

                goto fail;

            }

        }

        break;

    case NAL_EOS_NUT:

    case NAL_EOB_NUT:

        s->seq_decode = (s->seq_decode + 1) & 0xff;

        s->max_ra     = INT_MAX;

        break;

    case NAL_AUD:

    case NAL_FD_NUT:

        break;

    default:

        av_log(s->avctx, AV_LOG_INFO,

               "Skipping NAL unit %d\n", s->nal_unit_type);

    }



    return 0;

fail:

    if (s->avctx->err_recognition & AV_EF_EXPLODE)

        return ret;

    return 0;

}

