int object_property_get_enum(Object *obj, const char *name,

                             const char *typename, Error **errp)

{

    Error *err = NULL;

    StringOutputVisitor *sov;

    Visitor *v;

    char *str;

    int ret;

    ObjectProperty *prop = object_property_find(obj, name, errp);

    EnumProperty *enumprop;



    if (prop == NULL) {

        return 0;

    }



    if (!g_str_equal(prop->type, typename)) {

        error_setg(errp, "Property %s on %s is not '%s' enum type",

                   name, object_class_get_name(

                       object_get_class(obj)), typename);

        return 0;

    }



    enumprop = prop->opaque;



    sov = string_output_visitor_new(false);

    object_property_get(obj, string_output_get_visitor(sov), name, &err);

    if (err) {

        error_propagate(errp, err);

        string_output_visitor_cleanup(sov);

        return 0;

    }

    str = string_output_get_string(sov);

    string_output_visitor_cleanup(sov);

    v = string_input_visitor_new(str);

    visit_type_enum(v, name, &ret, enumprop->strings, errp);



    g_free(str);

    visit_free(v);



    return ret;

}

static uint64_t omap_sti_read(void *opaque, target_phys_addr_t addr,

                              unsigned size)

{

    struct omap_sti_s *s = (struct omap_sti_s *) opaque;



    if (size != 4) {

        return omap_badwidth_read32(opaque, addr);

    }



    switch (addr) {

    case 0x00:	/* STI_REVISION */

        return 0x10;



    case 0x10:	/* STI_SYSCONFIG */

        return s->sysconfig;



    case 0x14:	/* STI_SYSSTATUS / STI_RX_STATUS / XTI_SYSSTATUS */

        return 0x00;



    case 0x18:	/* STI_IRQSTATUS */

        return s->irqst;



    case 0x1c:	/* STI_IRQSETEN / STI_IRQCLREN */

        return s->irqen;



    case 0x24:	/* STI_ER / STI_DR / XTI_TRACESELECT */

    case 0x28:	/* STI_RX_DR / XTI_RXDATA */

        /* TODO */

        return 0;



    case 0x2c:	/* STI_CLK_CTRL / XTI_SCLKCRTL */

        return s->clkcontrol;



    case 0x30:	/* STI_SERIAL_CFG / XTI_SCONFIG */

        return s->serial_config;

    }



    OMAP_BAD_REG(addr);

    return 0;

}

static int pollfds_fill(GArray *pollfds, fd_set *rfds, fd_set *wfds,

                        fd_set *xfds)

{

    int nfds = -1;

    int i;



    for (i = 0; i < pollfds->len; i++) {

        GPollFD *pfd = &g_array_index(pollfds, GPollFD, i);

        int fd = pfd->fd;

        int events = pfd->events;

        if (events & G_IO_IN) {

            FD_SET(fd, rfds);

            nfds = MAX(nfds, fd);

        }

        if (events & G_IO_OUT) {

            FD_SET(fd, wfds);

            nfds = MAX(nfds, fd);

        }

        if (events & G_IO_PRI) {

            FD_SET(fd, xfds);

            nfds = MAX(nfds, fd);

        }

    }

    return nfds;

}

