char *get_boot_devices_list(uint32_t *size)

{

    FWBootEntry *i;

    uint32_t total = 0;

    char *list = NULL;



    QTAILQ_FOREACH(i, &fw_boot_order, link) {

        char *devpath = NULL, *bootpath;

        int len;



        if (i->dev) {

            devpath = qdev_get_fw_dev_path(i->dev);

            assert(devpath);

        }



        if (i->suffix && devpath) {

            bootpath = qemu_malloc(strlen(devpath) + strlen(i->suffix) + 1);

            sprintf(bootpath, "%s%s", devpath, i->suffix);

            qemu_free(devpath);

        } else if (devpath) {

            bootpath = devpath;

        } else {

            bootpath = strdup(i->suffix);

            assert(bootpath);

        }



        if (total) {

            list[total-1] = '\n';

        }

        len = strlen(bootpath) + 1;

        list = qemu_realloc(list, total + len);

        memcpy(&list[total], bootpath, len);

        total += len;

        qemu_free(bootpath);

    }



    *size = total;



    return list;

}

void rgb24toyv12_c(const uint8_t *src, uint8_t *ydst, uint8_t *udst,

                   uint8_t *vdst, int width, int height, int lumStride,

                   int chromStride, int srcStride)

{

    int y;

    const int chromWidth = width >> 1;



    for (y = 0; y < height; y += 2) {

        int i;

        for (i = 0; i < chromWidth; i++) {

            unsigned int b = src[6 * i + 0];

            unsigned int g = src[6 * i + 1];

            unsigned int r = src[6 * i + 2];



            unsigned int Y = ((RY * r + GY * g + BY * b) >> RGB2YUV_SHIFT) +  16;

            unsigned int V = ((RV * r + GV * g + BV * b) >> RGB2YUV_SHIFT) + 128;

            unsigned int U = ((RU * r + GU * g + BU * b) >> RGB2YUV_SHIFT) + 128;



            udst[i]     = U;

            vdst[i]     = V;

            ydst[2 * i] = Y;



            b = src[6 * i + 3];

            g = src[6 * i + 4];

            r = src[6 * i + 5];



            Y = ((RY * r + GY * g + BY * b) >> RGB2YUV_SHIFT) + 16;

            ydst[2 * i + 1] = Y;

        }

        ydst += lumStride;

        src  += srcStride;



        if (y+1 == height)

            break;



        for (i = 0; i < chromWidth; i++) {

            unsigned int b = src[6 * i + 0];

            unsigned int g = src[6 * i + 1];

            unsigned int r = src[6 * i + 2];



            unsigned int Y = ((RY * r + GY * g + BY * b) >> RGB2YUV_SHIFT) + 16;



            ydst[2 * i] = Y;



            b = src[6 * i + 3];

            g = src[6 * i + 4];

            r = src[6 * i + 5];



            Y = ((RY * r + GY * g + BY * b) >> RGB2YUV_SHIFT) + 16;

            ydst[2 * i + 1] = Y;

        }

        udst += chromStride;

        vdst += chromStride;

        ydst += lumStride;

        src  += srcStride;

    }

}

static void framebuffer_update_request(VncState *vs, int incremental,

                                       int x_position, int y_position,

                                       int w, int h)

{

    int i;

    const size_t width = surface_width(vs->vd->ds) / VNC_DIRTY_PIXELS_PER_BIT;

    const size_t height = surface_height(vs->vd->ds);



    if (y_position > height) {

        y_position = height;

    }

    if (y_position + h >= height) {

        h = height - y_position;

    }



    vs->need_update = 1;

    if (!incremental) {

        vs->force_update = 1;

        for (i = 0; i < h; i++) {

            bitmap_set(vs->dirty[y_position + i], 0, width);

            bitmap_clear(vs->dirty[y_position + i], width,

                         VNC_DIRTY_BITS - width);

        }

    }

}

static void sdp_parse_fmtp_config(AVCodecContext *codec, char *attr, char *value)

{

    switch (codec->codec_id) {

        case CODEC_ID_MPEG4:

        case CODEC_ID_AAC:

            if (!strcmp(attr, "config")) {

                /* decode the hexa encoded parameter */

                int len = hex_to_data(NULL, value);



                codec->extradata = av_mallocz(len + FF_INPUT_BUFFER_PADDING_SIZE);

                if (!codec->extradata)

                    return;

                codec->extradata_size = len;

                hex_to_data(codec->extradata, value);

            }

            break;

        default:

            break;

    }

    return;

}

static int tpm_passthrough_unix_write(int fd, const uint8_t *buf, uint32_t len)

{

    int ret, remain;



    remain = len;

    while (len > 0) {

        ret = write(fd, buf, remain);

        if (ret < 0) {

            if (errno != EINTR && errno != EAGAIN) {

                return -1;

            }

        } else if (ret == 0) {

            break;

        } else {

            buf += ret;

            remain -= ret;

        }

    }

    return len - remain;

}

static int mp3_header_decompress(AVBitStreamFilterContext *bsfc, AVCodecContext *avctx, const char *args,

                     uint8_t **poutbuf, int *poutbuf_size,

                     const uint8_t *buf, int buf_size, int keyframe){

    uint32_t header;

    int sample_rate= avctx->sample_rate;

    int sample_rate_index=0;

    int lsf, mpeg25, bitrate_index, frame_size;



    header = (buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3];

    if(ff_mpa_check_header(header) >= 0){

        *poutbuf= (uint8_t *) buf;

        *poutbuf_size= buf_size;



        return 0;

    }



    header= 0xFFE00000 | ((4-3)<<17) | (1<<16); //FIXME simplify



    lsf     = sample_rate < (24000+32000)/2;

    mpeg25  = sample_rate < (12000+16000)/2;

    header |= (!mpeg25)<<20;

    header |= (!lsf   )<<19;

    if(sample_rate<<(lsf+mpeg25) < (44100+32000)/2)

        sample_rate_index |= 2;

    else if(sample_rate<<(lsf+mpeg25) > (44100+48000)/2)

        sample_rate_index |= 1;



    header |= sample_rate_index<<10;

    sample_rate= mpa_freq_tab[sample_rate_index] >> (lsf + mpeg25); //in case sample rate is a little off



    for(bitrate_index=2; bitrate_index<30; bitrate_index++){

        frame_size = mpa_bitrate_tab[lsf][2][bitrate_index>>1];

        frame_size = (frame_size * 144000) / (sample_rate << lsf) + (bitrate_index&1);

        if(frame_size == buf_size + 4)

            break;

    }

    if(bitrate_index == 30){

        av_log(avctx, AV_LOG_ERROR, "couldnt find bitrate_index\n");

        return -1;

    }



    header |= (bitrate_index&1)<<9;

    header |= (bitrate_index>>1)<<12;

    header |= (avctx->channels==1 ? MPA_MONO : MPA_JSTEREO)<<6;



    *poutbuf_size= buf_size + 4;

    *poutbuf= av_malloc(buf_size + 4 + FF_INPUT_BUFFER_PADDING_SIZE);

    memcpy(*poutbuf + 4, buf, buf_size + FF_INPUT_BUFFER_PADDING_SIZE);



    if(avctx->channels==2){

        if(lsf){

            FFSWAP(int, (*poutbuf)[5], (*poutbuf)[6]);

            header |= ((*poutbuf)[5] & 0xC0)>>2;

        }else{

            header |= (*poutbuf)[5] & 0x30;

        }

    }



    (*poutbuf)[0]= header>>24;

    (*poutbuf)[1]= header>>16;

    (*poutbuf)[2]= header>> 8;

    (*poutbuf)[3]= header    ;



    return 1;

}

static struct iovec *lock_iovec(int type, abi_ulong target_addr,

                                int count, int copy)

{

    struct target_iovec *target_vec;

    struct iovec *vec;

    abi_ulong total_len, max_len;

    int i;

    int err = 0;

    bool bad_address = false;



    if (count == 0) {

        errno = 0;

        return NULL;


    if (count < 0 || count > IOV_MAX) {

        errno = EINVAL;

        return NULL;




    vec = calloc(count, sizeof(struct iovec));

    if (vec == NULL) {

        errno = ENOMEM;

        return NULL;




    target_vec = lock_user(VERIFY_READ, target_addr,

                           count * sizeof(struct target_iovec), 1);

    if (target_vec == NULL) {

        err = EFAULT;

        goto fail2;




    /* ??? If host page size > target page size, this will result in a

       value larger than what we can actually support.  */

    max_len = 0x7fffffff & TARGET_PAGE_MASK;

    total_len = 0;



    for (i = 0; i < count; i++) {

        abi_ulong base = tswapal(target_vec[i].iov_base);

        abi_long len = tswapal(target_vec[i].iov_len);



        if (len < 0) {

            err = EINVAL;

            goto fail;

        } else if (len == 0) {

            /* Zero length pointer is ignored.  */

            vec[i].iov_base = 0;

        } else {

            vec[i].iov_base = lock_user(type, base, len, copy);

            /* If the first buffer pointer is bad, this is a fault.  But

             * subsequent bad buffers will result in a partial write; this

             * is realized by filling the vector with null pointers and

             * zero lengths. */

            if (!vec[i].iov_base) {

                if (i == 0) {

                    err = EFAULT;

                    goto fail;

                } else {

                    bad_address = true;



            if (bad_address) {

                len = 0;


            if (len > max_len - total_len) {

                len = max_len - total_len;



        vec[i].iov_len = len;

        total_len += len;




    unlock_user(target_vec, target_addr, 0);

    return vec;



 fail:






    unlock_user(target_vec, target_addr, 0);

 fail2:

    free(vec);

    errno = err;

    return NULL;

