static int avi_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    AVIContext *avi = s->priv_data;

    ByteIOContext *pb = &s->pb;

    uint32_t tag, tag1, handler;

    int codec_type, stream_index, frame_period, bit_rate;

    unsigned int size, nb_frames;

    int i, n;

    AVStream *st;

    AVIStream *ast = NULL;

    int xan_video = 0;  /* hack to support Xan A/V */

    char str_track[4];



    avi->stream_index= -1;



    if (get_riff(avi, pb) < 0)

        return -1;



    /* first list tag */

    stream_index = -1;

    codec_type = -1;

    frame_period = 0;

    for(;;) {

        if (url_feof(pb))

            goto fail;

        tag = get_le32(pb);

        size = get_le32(pb);

#ifdef DEBUG

        print_tag("tag", tag, size);

#endif



        switch(tag) {

        case MKTAG('L', 'I', 'S', 'T'):

            /* ignored, except when start of video packets */

            tag1 = get_le32(pb);

#ifdef DEBUG

            print_tag("list", tag1, 0);

#endif

            if (tag1 == MKTAG('m', 'o', 'v', 'i')) {

                avi->movi_list = url_ftell(pb) - 4;

                if(size) avi->movi_end = avi->movi_list + size + (size & 1);

                else     avi->movi_end = url_fsize(pb);

#ifdef DEBUG

                printf("movi end=%"PRIx64"\n", avi->movi_end);

#endif

                goto end_of_header;

            }

            break;

        case MKTAG('d', 'm', 'l', 'h'):

            avi->is_odml = 1;

            url_fskip(pb, size + (size & 1));

            break;

        case MKTAG('a', 'v', 'i', 'h'):

            /* avi header */

            /* using frame_period is bad idea */

            frame_period = get_le32(pb);

            bit_rate = get_le32(pb) * 8;

            get_le32(pb);

            avi->non_interleaved |= get_le32(pb) & AVIF_MUSTUSEINDEX;



            url_fskip(pb, 2 * 4);

            n = get_le32(pb);

            for(i=0;i<n;i++) {

                AVIStream *ast;

                st = av_new_stream(s, i);

                if (!st)

                    goto fail;



                ast = av_mallocz(sizeof(AVIStream));

                if (!ast)

                    goto fail;

                st->priv_data = ast;

            }

            url_fskip(pb, size - 7 * 4);

            break;

        case MKTAG('s', 't', 'r', 'h'):

            /* stream header */

            stream_index++;

            tag1 = get_le32(pb);

            handler = get_le32(pb); /* codec tag */

#ifdef DEBUG

            print_tag("strh", tag1, -1);

#endif

            if(tag1 == MKTAG('i', 'a', 'v', 's') || tag1 == MKTAG('i', 'v', 'a', 's')){

                /*

                 * After some consideration -- I don't think we

                 * have to support anything but DV in a type1 AVIs.

                 */

                if (s->nb_streams != 1)

                    goto fail;



                if (handler != MKTAG('d', 'v', 's', 'd') &&

                    handler != MKTAG('d', 'v', 'h', 'd') &&

                    handler != MKTAG('d', 'v', 's', 'l'))

                   goto fail;



                ast = s->streams[0]->priv_data;

                av_freep(&s->streams[0]->codec->extradata);

                av_freep(&s->streams[0]);

                s->nb_streams = 0;

                if (ENABLE_DV_DEMUXER) {

                    avi->dv_demux = dv_init_demux(s);

                    if (!avi->dv_demux)

                        goto fail;

                }

                s->streams[0]->priv_data = ast;

                url_fskip(pb, 3 * 4);

                ast->scale = get_le32(pb);

                ast->rate = get_le32(pb);

                stream_index = s->nb_streams - 1;

                url_fskip(pb, size - 7*4);

                break;

            }



            if (stream_index >= s->nb_streams) {

                url_fskip(pb, size - 8);

                /* ignore padding stream */

                if (tag1 == MKTAG('p', 'a', 'd', 's'))

                    stream_index--;

                break;

            }

            st = s->streams[stream_index];

            ast = st->priv_data;

            st->codec->stream_codec_tag= handler;



            get_le32(pb); /* flags */

            get_le16(pb); /* priority */

            get_le16(pb); /* language */

            get_le32(pb); /* initial frame */

            ast->scale = get_le32(pb);

            ast->rate = get_le32(pb);

            if(ast->scale && ast->rate){

            }else if(frame_period){

                ast->rate = 1000000;

                ast->scale = frame_period;

            }else{

                ast->rate = 25;

                ast->scale = 1;

            }

            av_set_pts_info(st, 64, ast->scale, ast->rate);



            ast->cum_len=get_le32(pb); /* start */

            nb_frames = get_le32(pb);



            st->start_time = 0;

            st->duration = nb_frames;

            get_le32(pb); /* buffer size */

            get_le32(pb); /* quality */

            ast->sample_size = get_le32(pb); /* sample ssize */

            ast->cum_len *= FFMAX(1, ast->sample_size);

//            av_log(NULL, AV_LOG_DEBUG, "%d %d %d %d\n", ast->rate, ast->scale, ast->start, ast->sample_size);



            switch(tag1) {

            case MKTAG('v', 'i', 'd', 's'):

                codec_type = CODEC_TYPE_VIDEO;



                ast->sample_size = 0;

                break;

            case MKTAG('a', 'u', 'd', 's'):

                codec_type = CODEC_TYPE_AUDIO;

                break;

            case MKTAG('t', 'x', 't', 's'):

                //FIXME

                codec_type = CODEC_TYPE_DATA; //CODEC_TYPE_SUB ?  FIXME

                break;

            case MKTAG('p', 'a', 'd', 's'):

                codec_type = CODEC_TYPE_UNKNOWN;

                stream_index--;

                break;

            default:

                av_log(s, AV_LOG_ERROR, "unknown stream type %X\n", tag1);

                goto fail;

            }

            ast->frame_offset= ast->cum_len;

            url_fskip(pb, size - 12 * 4);

            break;

        case MKTAG('s', 't', 'r', 'f'):

            /* stream header */

            if (stream_index >= s->nb_streams || avi->dv_demux) {

                url_fskip(pb, size);

            } else {

                st = s->streams[stream_index];

                switch(codec_type) {

                case CODEC_TYPE_VIDEO:

                    get_le32(pb); /* size */

                    st->codec->width = get_le32(pb);

                    st->codec->height = get_le32(pb);

                    get_le16(pb); /* panes */

                    st->codec->bits_per_sample= get_le16(pb); /* depth */

                    tag1 = get_le32(pb);

                    get_le32(pb); /* ImageSize */

                    get_le32(pb); /* XPelsPerMeter */

                    get_le32(pb); /* YPelsPerMeter */

                    get_le32(pb); /* ClrUsed */

                    get_le32(pb); /* ClrImportant */



                    if(size > 10*4 && size<(1<<30)){

                        st->codec->extradata_size= size - 10*4;

                        st->codec->extradata= av_malloc(st->codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

                        get_buffer(pb, st->codec->extradata, st->codec->extradata_size);

                    }



                    if(st->codec->extradata_size & 1) //FIXME check if the encoder really did this correctly

                        get_byte(pb);



                    /* Extract palette from extradata if bpp <= 8 */

                    /* This code assumes that extradata contains only palette */

                    /* This is true for all paletted codecs implemented in ffmpeg */

                    if (st->codec->extradata_size && (st->codec->bits_per_sample <= 8)) {

                        st->codec->palctrl = av_mallocz(sizeof(AVPaletteControl));

#ifdef WORDS_BIGENDIAN

                        for (i = 0; i < FFMIN(st->codec->extradata_size, AVPALETTE_SIZE)/4; i++)

                            st->codec->palctrl->palette[i] = bswap_32(((uint32_t*)st->codec->extradata)[i]);

#else

                        memcpy(st->codec->palctrl->palette, st->codec->extradata,

                               FFMIN(st->codec->extradata_size, AVPALETTE_SIZE));

#endif

                        st->codec->palctrl->palette_changed = 1;

                    }



#ifdef DEBUG

                    print_tag("video", tag1, 0);

#endif

                    st->codec->codec_type = CODEC_TYPE_VIDEO;

                    st->codec->codec_tag = tag1;

                    st->codec->codec_id = codec_get_id(codec_bmp_tags, tag1);

                    if (st->codec->codec_id == CODEC_ID_XAN_WC4)

                        xan_video = 1;

                    st->need_parsing = 2; //only parse headers dont do slower repacketization, this is needed to get the pict type which is needed for generating correct pts

//                    url_fskip(pb, size - 5 * 4);

                    break;

                case CODEC_TYPE_AUDIO:

                    get_wav_header(pb, st->codec, size);

                    if(ast->sample_size && st->codec->block_align && ast->sample_size % st->codec->block_align)

                        av_log(s, AV_LOG_DEBUG, "invalid sample size or block align detected\n");

                    if (size%2) /* 2-aligned (fix for Stargate SG-1 - 3x18 - Shades of Grey.avi) */

                        url_fskip(pb, 1);

                    /* special case time: To support Xan DPCM, hardcode

                     * the format if Xxan is the video codec */

                    st->need_parsing = 1;

                    /* ADTS header is in extradata, AAC without header must be stored as exact frames, parser not needed and it will fail */

                    if (st->codec->codec_id == CODEC_ID_AAC && st->codec->extradata_size)

                        st->need_parsing = 0;

                    /* force parsing as several audio frames can be in

                       one packet */

                    if (xan_video)

                        st->codec->codec_id = CODEC_ID_XAN_DPCM;

                    break;

                default:

                    st->codec->codec_type = CODEC_TYPE_DATA;

                    st->codec->codec_id= CODEC_ID_NONE;

                    st->codec->codec_tag= 0;

                    url_fskip(pb, size);

                    break;

                }

            }

            break;

        case MKTAG('i', 'n', 'd', 'x'):

            i= url_ftell(pb);

            if(!url_is_streamed(pb) && !(s->flags & AVFMT_FLAG_IGNIDX)){

                read_braindead_odml_indx(s, 0);

            }

            url_fseek(pb, i+size, SEEK_SET);

            break;

        case MKTAG('I', 'N', 'A', 'M'):

            avi_read_tag(pb, s->title, sizeof(s->title), size);

            break;

        case MKTAG('I', 'A', 'R', 'T'):

            avi_read_tag(pb, s->author, sizeof(s->author), size);

            break;

        case MKTAG('I', 'C', 'O', 'P'):

            avi_read_tag(pb, s->copyright, sizeof(s->copyright), size);

            break;

        case MKTAG('I', 'C', 'M', 'T'):

            avi_read_tag(pb, s->comment, sizeof(s->comment), size);

            break;

        case MKTAG('I', 'G', 'N', 'R'):

            avi_read_tag(pb, s->genre, sizeof(s->genre), size);

            break;

        case MKTAG('I', 'P', 'R', 'D'):

            avi_read_tag(pb, s->album, sizeof(s->album), size);

            break;

        case MKTAG('I', 'P', 'R', 'T'):

            avi_read_tag(pb, str_track, sizeof(str_track), size);

            sscanf(str_track, "%d", &s->track);

            break;

        default:

            /* skip tag */

            size += (size & 1);

            url_fskip(pb, size);

            break;

        }

    }

 end_of_header:

    /* check stream number */

    if (stream_index != s->nb_streams - 1) {

    fail:

        for(i=0;i<s->nb_streams;i++) {

            av_freep(&s->streams[i]->codec->extradata);

            av_freep(&s->streams[i]);

        }

        return -1;

    }



    if(!avi->index_loaded && !url_is_streamed(pb))

        avi_load_index(s);

    avi->index_loaded = 1;

    avi->non_interleaved |= guess_ni_flag(s);

    if(avi->non_interleaved)

        clean_index(s);



    return 0;

}

static int ffserver_parse_config_feed(FFServerConfig *config, const char *cmd, const char **p,

                                      FFServerStream **pfeed)

{

    FFServerStream *feed;

    char arg[1024];

    av_assert0(pfeed);

    feed = *pfeed;

    if (!av_strcasecmp(cmd, "<Feed")) {

        char *q;

        FFServerStream *s;

        feed = av_mallocz(sizeof(FFServerStream));

        if (!feed)

            return AVERROR(ENOMEM);

        ffserver_get_arg(feed->filename, sizeof(feed->filename), p);

        q = strrchr(feed->filename, '>');

        if (*q)

            *q = '\0';



        for (s = config->first_feed; s; s = s->next) {

            if (!strcmp(feed->filename, s->filename))

                ERROR("Feed '%s' already registered\n", s->filename);

        }



        feed->fmt = av_guess_format("ffm", NULL, NULL);

        /* default feed file */

        snprintf(feed->feed_filename, sizeof(feed->feed_filename),

                 "/tmp/%s.ffm", feed->filename);

        feed->feed_max_size = 5 * 1024 * 1024;

        feed->is_feed = 1;

        feed->feed = feed; /* self feeding :-) */

        *pfeed = feed;

        return 0;

    }

    av_assert0(feed);

    if (!av_strcasecmp(cmd, "Launch")) {

        int i;



        feed->child_argv = av_mallocz(64 * sizeof(char *));

        if (!feed->child_argv)

            return AVERROR(ENOMEM);

        for (i = 0; i < 62; i++) {

            ffserver_get_arg(arg, sizeof(arg), p);

            if (!arg[0])

                break;



            feed->child_argv[i] = av_strdup(arg);

            if (!feed->child_argv[i])

                return AVERROR(ENOMEM);

        }



        feed->child_argv[i] =

            av_asprintf("http://%s:%d/%s",

                        (config->http_addr.sin_addr.s_addr == INADDR_ANY) ? "127.0.0.1" :

                        inet_ntoa(config->http_addr.sin_addr), ntohs(config->http_addr.sin_port),

                        feed->filename);

        if (!feed->child_argv[i])

            return AVERROR(ENOMEM);

    } else if (!av_strcasecmp(cmd, "ACL")) {

        ffserver_parse_acl_row(NULL, feed, NULL, *p, config->filename,

                config->line_num);

    } else if (!av_strcasecmp(cmd, "File") || !av_strcasecmp(cmd, "ReadOnlyFile")) {

        ffserver_get_arg(feed->feed_filename, sizeof(feed->feed_filename), p);

        feed->readonly = !av_strcasecmp(cmd, "ReadOnlyFile");

    } else if (!av_strcasecmp(cmd, "Truncate")) {

        ffserver_get_arg(arg, sizeof(arg), p);

        /* assume Truncate is true in case no argument is specified */

        if (!arg[0]) {

            feed->truncate = 1;

        } else {

            WARNING("Truncate N syntax in configuration file is deprecated, "

                    "use Truncate alone with no arguments\n");

            feed->truncate = strtod(arg, NULL);

        }

    } else if (!av_strcasecmp(cmd, "FileMaxSize")) {

        char *p1;

        double fsize;



        ffserver_get_arg(arg, sizeof(arg), p);

        p1 = arg;

        fsize = strtod(p1, &p1);

        switch(av_toupper(*p1)) {

        case 'K':

            fsize *= 1024;

            break;

        case 'M':

            fsize *= 1024 * 1024;

            break;

        case 'G':

            fsize *= 1024 * 1024 * 1024;

            break;

        default:

            ERROR("Invalid file size: %s\n", arg);

            break;

        }

        feed->feed_max_size = (int64_t)fsize;

        if (feed->feed_max_size < FFM_PACKET_SIZE*4)

            ERROR("Feed max file size is too small, must be at least %d\n",

                    FFM_PACKET_SIZE*4);

    } else if (!av_strcasecmp(cmd, "</Feed>")) {

        *pfeed = NULL;

    } else {

        ERROR("Invalid entry '%s' inside <Feed></Feed>\n", cmd);

    }

    return 0;

}

static void build_feed_streams(void)

{

    FFServerStream *stream, *feed;

    int i;



    /* gather all streams */

    for(stream = config.first_stream; stream; stream = stream->next) {

        feed = stream->feed;

        if (feed) {

            if (stream->is_feed) {

                for(i=0;i<stream->nb_streams;i++)

                    stream->feed_streams[i] = i;

            } else {

                /* we handle a stream coming from a feed */

                for(i=0;i<stream->nb_streams;i++)

                    stream->feed_streams[i] = add_av_stream(feed,

                                                            stream->streams[i]);

            }

        }

    }



    /* create feed files if needed */

    for(feed = config.first_feed; feed; feed = feed->next_feed) {

        int fd;



        if (avio_check(feed->feed_filename, AVIO_FLAG_READ) > 0) {

            /* See if it matches */

            AVFormatContext *s = NULL;

            int matches = 0;



            if (avformat_open_input(&s, feed->feed_filename, NULL, NULL) >= 0) {

                /* set buffer size */

                ffio_set_buf_size(s->pb, FFM_PACKET_SIZE);

                /* Now see if it matches */

                if (s->nb_streams == feed->nb_streams) {

                    matches = 1;

                    for(i=0;i<s->nb_streams;i++) {

                        AVStream *sf, *ss;

                        sf = feed->streams[i];

                        ss = s->streams[i];



                        if (sf->index != ss->index ||

                            sf->id != ss->id) {

                            http_log("Index & Id do not match for stream %d (%s)\n",

                                   i, feed->feed_filename);

                            matches = 0;

                        } else {

                            AVCodecContext *ccf, *ccs;



                            ccf = sf->codec;

                            ccs = ss->codec;

#define CHECK_CODEC(x)  (ccf->x != ccs->x)



                            if (CHECK_CODEC(codec_id) || CHECK_CODEC(codec_type)) {

                                http_log("Codecs do not match for stream %d\n", i);

                                matches = 0;

                            } else if (CHECK_CODEC(bit_rate) || CHECK_CODEC(flags)) {

                                http_log("Codec bitrates do not match for stream %d\n", i);

                                matches = 0;

                            } else if (ccf->codec_type == AVMEDIA_TYPE_VIDEO) {

                                if (CHECK_CODEC(time_base.den) ||

                                    CHECK_CODEC(time_base.num) ||

                                    CHECK_CODEC(width) ||

                                    CHECK_CODEC(height)) {

                                    http_log("Codec width, height and framerate do not match for stream %d\n", i);

                                    matches = 0;

                                }

                            } else if (ccf->codec_type == AVMEDIA_TYPE_AUDIO) {

                                if (CHECK_CODEC(sample_rate) ||

                                    CHECK_CODEC(channels) ||

                                    CHECK_CODEC(frame_size)) {

                                    http_log("Codec sample_rate, channels, frame_size do not match for stream %d\n", i);

                                    matches = 0;

                                }

                            } else {

                                http_log("Unknown codec type\n");

                                matches = 0;

                            }

                        }

                        if (!matches)

                            break;

                    }

                } else

                    http_log("Deleting feed file '%s' as stream counts differ (%d != %d)\n",

                        feed->feed_filename, s->nb_streams, feed->nb_streams);



                avformat_close_input(&s);

            } else

                http_log("Deleting feed file '%s' as it appears to be corrupt\n",

                        feed->feed_filename);



            if (!matches) {

                if (feed->readonly) {

                    http_log("Unable to delete feed file '%s' as it is marked readonly\n",

                        feed->feed_filename);

                    exit(1);

                }

                unlink(feed->feed_filename);

            }

        }

        if (avio_check(feed->feed_filename, AVIO_FLAG_WRITE) <= 0) {

            AVFormatContext *s = avformat_alloc_context();



            if (!s) {

                http_log("Failed to allocate context\n");

                exit(1);

            }



            if (feed->readonly) {

                http_log("Unable to create feed file '%s' as it is marked readonly\n",

                    feed->feed_filename);

                exit(1);

            }



            /* only write the header of the ffm file */

            if (avio_open(&s->pb, feed->feed_filename, AVIO_FLAG_WRITE) < 0) {

                http_log("Could not open output feed file '%s'\n",

                         feed->feed_filename);

                exit(1);

            }

            s->oformat = feed->fmt;

            s->nb_streams = feed->nb_streams;

            s->streams = feed->streams;

            if (avformat_write_header(s, NULL) < 0) {

                http_log("Container doesn't support the required parameters\n");

                exit(1);

            }

            /* XXX: need better API */

            av_freep(&s->priv_data);

            avio_closep(&s->pb);

            s->streams = NULL;

            s->nb_streams = 0;

            avformat_free_context(s);

        }

        /* get feed size and write index */

        fd = open(feed->feed_filename, O_RDONLY);

        if (fd < 0) {

            http_log("Could not open output feed file '%s'\n",

                    feed->feed_filename);

            exit(1);

        }



        feed->feed_write_index = FFMAX(ffm_read_write_index(fd), FFM_PACKET_SIZE);

        feed->feed_size = lseek(fd, 0, SEEK_END);

        /* ensure that we do not wrap before the end of file */

        if (feed->feed_max_size && feed->feed_max_size < feed->feed_size)

            feed->feed_max_size = feed->feed_size;



        close(fd);

    }

}

static void virtio_balloon_device_realize(DeviceState *dev, Error **errp)

{

    VirtIODevice *vdev = VIRTIO_DEVICE(dev);

    VirtIOBalloon *s = VIRTIO_BALLOON(dev);

    int ret;



    virtio_init(vdev, "virtio-balloon", VIRTIO_ID_BALLOON,

                sizeof(struct virtio_balloon_config));



    ret = qemu_add_balloon_handler(virtio_balloon_to_target,

                                   virtio_balloon_stat, s);



    if (ret < 0) {

        error_setg(errp, "Adding balloon handler failed");

        virtio_cleanup(vdev);

        return;

    }



    s->ivq = virtio_add_queue(vdev, 128, virtio_balloon_handle_output);

    s->dvq = virtio_add_queue(vdev, 128, virtio_balloon_handle_output);

    s->svq = virtio_add_queue(vdev, 128, virtio_balloon_receive_stats);



    reset_stats(s);



    register_savevm(dev, "virtio-balloon", -1, 1,

                    virtio_balloon_save, virtio_balloon_load, s);



    object_property_add(OBJECT(dev), "guest-stats", "guest statistics",

                        balloon_stats_get_all, NULL, NULL, s, NULL);



    object_property_add(OBJECT(dev), "guest-stats-polling-interval", "int",

                        balloon_stats_get_poll_interval,

