static void float64_maddsub_update_excp(CPUPPCState *env, float64 arg1,

                                        float64 arg2, float64 arg3,

                                        unsigned int madd_flags)

{

    if (unlikely((float64_is_infinity(arg1) && float64_is_zero(arg2)) ||

                 (float64_is_zero(arg1) && float64_is_infinity(arg2)))) {

        /* Multiplication of zero by infinity */

        arg1 = float_invalid_op_excp(env, POWERPC_EXCP_FP_VXIMZ, 1);

    } else if (unlikely(float64_is_signaling_nan(arg1, &env->fp_status) ||

                        float64_is_signaling_nan(arg2, &env->fp_status) ||

                        float64_is_signaling_nan(arg3, &env->fp_status))) {

        /* sNaN operation */

        float_invalid_op_excp(env, POWERPC_EXCP_FP_VXSNAN, 1);

    } else if ((float64_is_infinity(arg1) || float64_is_infinity(arg2)) &&

               float64_is_infinity(arg3)) {

        uint8_t aSign, bSign, cSign;



        aSign = float64_is_neg(arg1);

        bSign = float64_is_neg(arg2);

        cSign = float64_is_neg(arg3);

        if (madd_flags & float_muladd_negate_c) {

            cSign ^= 1;

        }

        if (aSign ^ bSign ^ cSign) {

            float_invalid_op_excp(env, POWERPC_EXCP_FP_VXISI, 1);

        }

    }

}

static uint32_t check_alarm(RTCState *s)

{

    uint8_t alarm_hour, alarm_min, alarm_sec;

    uint8_t cur_hour, cur_min, cur_sec;



    alarm_sec = rtc_from_bcd(s, s->cmos_data[RTC_SECONDS_ALARM]);

    alarm_min = rtc_from_bcd(s, s->cmos_data[RTC_MINUTES_ALARM]);

    alarm_hour = rtc_from_bcd(s, s->cmos_data[RTC_HOURS_ALARM]);

    alarm_hour = convert_hour(s, alarm_hour);



    cur_sec = rtc_from_bcd(s, s->cmos_data[RTC_SECONDS]);

    cur_min = rtc_from_bcd(s, s->cmos_data[RTC_MINUTES]);

    cur_hour = rtc_from_bcd(s, s->cmos_data[RTC_HOURS]);

    cur_hour = convert_hour(s, cur_hour);



    if (((s->cmos_data[RTC_SECONDS_ALARM] & 0xc0) == 0xc0

                || alarm_sec == cur_sec) &&

            ((s->cmos_data[RTC_MINUTES_ALARM] & 0xc0) == 0xc0

             || alarm_min == cur_min) &&

            ((s->cmos_data[RTC_HOURS_ALARM] & 0xc0) == 0xc0

             || alarm_hour == cur_hour)) {

        return 1;

    }

    return 0;



}

static int get_dns_addr(struct in_addr *pdns_addr)

{

    char buff[512];

    char buff2[257];

    FILE *f;

    int found = 0;

    struct in_addr tmp_addr;



    f = fopen("/etc/resolv.conf", "r");

    if (!f)

        return -1;



#ifdef DEBUG

    lprint("IP address of your DNS(s): ");

#endif

    while (fgets(buff, 512, f) != NULL) {

        if (sscanf(buff, "nameserver%*[ \t]%256s", buff2) == 1) {

            if (!inet_aton(buff2, &tmp_addr))

                continue;

            if (tmp_addr.s_addr == loopback_addr.s_addr)

                tmp_addr = our_addr;

            /* If it's the first one, set it to dns_addr */

            if (!found)

                *pdns_addr = tmp_addr;

#ifdef DEBUG

            else

                lprint(", ");

#endif

            if (++found > 3) {

#ifdef DEBUG

                lprint("(more)");

#endif

                break;

            }

#ifdef DEBUG

            else

                lprint("%s", inet_ntoa(tmp_addr));

#endif

        }

    }

    fclose(f);

    if (!found)

        return -1;

    return 0;

}

static bool aio_epoll_try_enable(AioContext *ctx)

{

    AioHandler *node;

    struct epoll_event event;



    QLIST_FOREACH(node, &ctx->aio_handlers, node) {

        int r;

        if (node->deleted || !node->pfd.events) {

            continue;

        }

        event.events = epoll_events_from_pfd(node->pfd.events);

        event.data.ptr = node;

        r = epoll_ctl(ctx->epollfd, EPOLL_CTL_ADD, node->pfd.fd, &event);

        if (r) {

            return false;

        }

    }

    ctx->epoll_enabled = true;

    return true;

}

static int bt_parse(const char *opt)

{

    const char *endp, *p;

    int vlan;



    if (strstart(opt, "hci", &endp)) {

        if (!*endp || *endp == ',') {

            if (*endp)

                if (!strstart(endp, ",vlan=", 0))

                    opt = endp + 1;



            return bt_hci_parse(opt);

       }

    } else if (strstart(opt, "vhci", &endp)) {

        if (!*endp || *endp == ',') {

            if (*endp) {

                if (strstart(endp, ",vlan=", &p)) {

                    vlan = strtol(p, (char **) &endp, 0);

                    if (*endp) {

                        fprintf(stderr, "qemu: bad scatternet '%s'\n", p);

                        return 1;

                    }

                } else {

                    fprintf(stderr, "qemu: bad parameter '%s'\n", endp + 1);

                    return 1;

                }

            } else

                vlan = 0;



            bt_vhci_add(vlan);

            return 0;

        }

    } else if (strstart(opt, "device:", &endp))

        return !bt_device_add(endp);



    fprintf(stderr, "qemu: bad bluetooth parameter '%s'\n", opt);

    return 1;

}

