static void av_always_inline filter_mb_dir(H264Context *h, int mb_x, int mb_y, uint8_t *img_y, uint8_t *img_cb, uint8_t *img_cr, unsigned int linesize, unsigned int uvlinesize, int mb_xy, int mb_type, int mvy_limit, int first_vertical_edge_done, int dir) {

    MpegEncContext * const s = &h->s;

    int edge;

    const int mbm_xy = dir == 0 ? mb_xy -1 : h->top_mb_xy;

    const int mbm_type = s->current_picture.mb_type[mbm_xy];

    int (*ref2frm) [64] = h->ref2frm[ h->slice_num          &(MAX_SLICES-1) ][0] + (MB_MBAFF ? 20 : 2);

    int (*ref2frmm)[64] = h->ref2frm[ h->slice_table[mbm_xy]&(MAX_SLICES-1) ][0] + (MB_MBAFF ? 20 : 2);

    int start = h->slice_table[mbm_xy] == 0xFFFF ? 1 : 0;



    const int edges = (mb_type & (MB_TYPE_16x16|MB_TYPE_SKIP))

                              == (MB_TYPE_16x16|MB_TYPE_SKIP) ? 1 : 4;

    // how often to recheck mv-based bS when iterating between edges

    const int mask_edge = (mb_type & (MB_TYPE_16x16 | (MB_TYPE_16x8 << dir))) ? 3 :

                          (mb_type & (MB_TYPE_8x16 >> dir)) ? 1 : 0;

    // how often to recheck mv-based bS when iterating along each edge

    const int mask_par0 = mb_type & (MB_TYPE_16x16 | (MB_TYPE_8x16 >> dir));



    if (first_vertical_edge_done) {

        start = 1;

    }



    if (h->deblocking_filter==2 && h->slice_table[mbm_xy] != h->slice_table[mb_xy])

        start = 1;



    if (FRAME_MBAFF && (dir == 1) && ((mb_y&1) == 0) && start == 0

        && !IS_INTERLACED(mb_type)

        && IS_INTERLACED(mbm_type)

        ) {

        // This is a special case in the norm where the filtering must

        // be done twice (one each of the field) even if we are in a

        // frame macroblock.

        //

        static const int nnz_idx[4] = {4,5,6,3};

        unsigned int tmp_linesize   = 2 *   linesize;

        unsigned int tmp_uvlinesize = 2 * uvlinesize;

        int mbn_xy = mb_xy - 2 * s->mb_stride;

        int qp;

        int i, j;

        int16_t bS[4];



        for(j=0; j<2; j++, mbn_xy += s->mb_stride){

            if( IS_INTRA(mb_type) ||

                IS_INTRA(s->current_picture.mb_type[mbn_xy]) ) {

                bS[0] = bS[1] = bS[2] = bS[3] = 3;

            } else {

                const uint8_t *mbn_nnz = h->non_zero_count[mbn_xy];

                for( i = 0; i < 4; i++ ) {

                    if( h->non_zero_count_cache[scan8[0]+i] != 0 ||

                        mbn_nnz[nnz_idx[i]] != 0 )

                        bS[i] = 2;

                    else

                        bS[i] = 1;

                }

            }

            // Do not use s->qscale as luma quantizer because it has not the same

            // value in IPCM macroblocks.

            qp = ( s->current_picture.qscale_table[mb_xy] + s->current_picture.qscale_table[mbn_xy] + 1 ) >> 1;

            tprintf(s->avctx, "filter mb:%d/%d dir:%d edge:%d, QPy:%d ls:%d uvls:%d", mb_x, mb_y, dir, edge, qp, tmp_linesize, tmp_uvlinesize);

            { int i; for (i = 0; i < 4; i++) tprintf(s->avctx, " bS[%d]:%d", i, bS[i]); tprintf(s->avctx, "\n"); }

            filter_mb_edgeh( h, &img_y[j*linesize], tmp_linesize, bS, qp );

            filter_mb_edgech( h, &img_cb[j*uvlinesize], tmp_uvlinesize, bS,

                              ( h->chroma_qp[0] + get_chroma_qp( h, 0, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

            filter_mb_edgech( h, &img_cr[j*uvlinesize], tmp_uvlinesize, bS,

                              ( h->chroma_qp[1] + get_chroma_qp( h, 1, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

        }



        start = 1;

    }



    /* Calculate bS */

    for( edge = start; edge < edges; edge++ ) {

        /* mbn_xy: neighbor macroblock */

        const int mbn_xy = edge > 0 ? mb_xy : mbm_xy;

        const int mbn_type = s->current_picture.mb_type[mbn_xy];

        int (*ref2frmn)[64] = edge > 0 ? ref2frm : ref2frmm;

        int16_t bS[4];

        int qp;



        if( (edge&1) && IS_8x8DCT(mb_type) )

            continue;



        if( IS_INTRA(mb_type) ||

            IS_INTRA(mbn_type) ) {

            int value;

            if (edge == 0) {

                if (   (!IS_INTERLACED(mb_type) && !IS_INTERLACED(mbm_type))

                    || ((FRAME_MBAFF || (s->picture_structure != PICT_FRAME)) && (dir == 0))

                ) {

                    value = 4;

                } else {

                    value = 3;

                }

            } else {

                value = 3;

            }

            bS[0] = bS[1] = bS[2] = bS[3] = value;

        } else {

            int i, l;

            int mv_done;



            if( edge & mask_edge ) {

                bS[0] = bS[1] = bS[2] = bS[3] = 0;

                mv_done = 1;

            }

            else if( FRAME_MBAFF && IS_INTERLACED(mb_type ^ mbn_type)) {

                bS[0] = bS[1] = bS[2] = bS[3] = 1;

                mv_done = 1;

            }

            else if( mask_par0 && (edge || (mbn_type & (MB_TYPE_16x16 | (MB_TYPE_8x16 >> dir)))) ) {

                int b_idx= 8 + 4 + edge * (dir ? 8:1);

                int bn_idx= b_idx - (dir ? 8:1);

                int v = 0;



                for( l = 0; !v && l < 1 + (h->slice_type_nos == FF_B_TYPE); l++ ) {

                    v |= ref2frm[l][h->ref_cache[l][b_idx]] != ref2frmn[l][h->ref_cache[l][bn_idx]] ||

                         FFABS( h->mv_cache[l][b_idx][0] - h->mv_cache[l][bn_idx][0] ) >= 4 ||

                         FFABS( h->mv_cache[l][b_idx][1] - h->mv_cache[l][bn_idx][1] ) >= mvy_limit;

                }



                if(h->slice_type_nos == FF_B_TYPE && v){

                    v=0;

                    for( l = 0; !v && l < 2; l++ ) {

                        int ln= 1-l;

                        v |= ref2frm[l][h->ref_cache[l][b_idx]] != ref2frmn[ln][h->ref_cache[ln][bn_idx]] ||

                            FFABS( h->mv_cache[l][b_idx][0] - h->mv_cache[ln][bn_idx][0] ) >= 4 ||

                            FFABS( h->mv_cache[l][b_idx][1] - h->mv_cache[ln][bn_idx][1] ) >= mvy_limit;

                    }

                }



                bS[0] = bS[1] = bS[2] = bS[3] = v;

                mv_done = 1;

            }

            else

                mv_done = 0;



            for( i = 0; i < 4; i++ ) {

                int x = dir == 0 ? edge : i;

                int y = dir == 0 ? i    : edge;

                int b_idx= 8 + 4 + x + 8*y;

                int bn_idx= b_idx - (dir ? 8:1);



                if( h->non_zero_count_cache[b_idx] != 0 ||

                    h->non_zero_count_cache[bn_idx] != 0 ) {

                    bS[i] = 2;

                }

                else if(!mv_done)

                {

                    bS[i] = 0;

                    for( l = 0; l < 1 + (h->slice_type_nos == FF_B_TYPE); l++ ) {

                        if( ref2frm[l][h->ref_cache[l][b_idx]] != ref2frmn[l][h->ref_cache[l][bn_idx]] ||

                            FFABS( h->mv_cache[l][b_idx][0] - h->mv_cache[l][bn_idx][0] ) >= 4 ||

                            FFABS( h->mv_cache[l][b_idx][1] - h->mv_cache[l][bn_idx][1] ) >= mvy_limit ) {

                            bS[i] = 1;

                            break;

                        }

                    }



                    if(h->slice_type_nos == FF_B_TYPE && bS[i]){

                        bS[i] = 0;

                        for( l = 0; l < 2; l++ ) {

                            int ln= 1-l;

                            if( ref2frm[l][h->ref_cache[l][b_idx]] != ref2frmn[ln][h->ref_cache[ln][bn_idx]] ||

                                FFABS( h->mv_cache[l][b_idx][0] - h->mv_cache[ln][bn_idx][0] ) >= 4 ||

                                FFABS( h->mv_cache[l][b_idx][1] - h->mv_cache[ln][bn_idx][1] ) >= mvy_limit ) {

                                bS[i] = 1;

                                break;

                            }

                        }

                    }

                }

            }



            if(bS[0]+bS[1]+bS[2]+bS[3] == 0)

                continue;

        }



        /* Filter edge */

        // Do not use s->qscale as luma quantizer because it has not the same

        // value in IPCM macroblocks.

        qp = ( s->current_picture.qscale_table[mb_xy] + s->current_picture.qscale_table[mbn_xy] + 1 ) >> 1;

        //tprintf(s->avctx, "filter mb:%d/%d dir:%d edge:%d, QPy:%d, QPc:%d, QPcn:%d\n", mb_x, mb_y, dir, edge, qp, h->chroma_qp, s->current_picture.qscale_table[mbn_xy]);

        tprintf(s->avctx, "filter mb:%d/%d dir:%d edge:%d, QPy:%d ls:%d uvls:%d", mb_x, mb_y, dir, edge, qp, linesize, uvlinesize);

        { int i; for (i = 0; i < 4; i++) tprintf(s->avctx, " bS[%d]:%d", i, bS[i]); tprintf(s->avctx, "\n"); }

        if( dir == 0 ) {

            filter_mb_edgev( h, &img_y[4*edge], linesize, bS, qp );

            if( (edge&1) == 0 ) {

                filter_mb_edgecv( h, &img_cb[2*edge], uvlinesize, bS,

                                  ( h->chroma_qp[0] + get_chroma_qp( h, 0, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

                filter_mb_edgecv( h, &img_cr[2*edge], uvlinesize, bS,

                                  ( h->chroma_qp[1] + get_chroma_qp( h, 1, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

            }

        } else {

            filter_mb_edgeh( h, &img_y[4*edge*linesize], linesize, bS, qp );

            if( (edge&1) == 0 ) {

                filter_mb_edgech( h, &img_cb[2*edge*uvlinesize], uvlinesize, bS,

                                  ( h->chroma_qp[0] + get_chroma_qp( h, 0, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

                filter_mb_edgech( h, &img_cr[2*edge*uvlinesize], uvlinesize, bS,

                                  ( h->chroma_qp[1] + get_chroma_qp( h, 1, s->current_picture.qscale_table[mbn_xy] ) + 1 ) >> 1);

            }

        }

    }

}

static int ehci_state_executing(EHCIQueue *q)

{

    EHCIPacket *p = QTAILQ_FIRST(&q->packets);

    int again = 0;



    assert(p != NULL);

    assert(p->qtdaddr == q->qtdaddr);



    ehci_execute_complete(q);

    if (p->usb_status == USB_RET_ASYNC) {

        goto out;

    }

    if (p->usb_status == USB_RET_PROCERR) {

        again = -1;

        goto out;

    }



    // 4.10.3

    if (!q->async) {

        int transactCtr = get_field(q->qh.epcap, QH_EPCAP_MULT);

        transactCtr--;

        set_field(&q->qh.epcap, transactCtr, QH_EPCAP_MULT);

        // 4.10.3, bottom of page 82, should exit this state when transaction

        // counter decrements to 0

    }



    /* 4.10.5 */

    if (p->usb_status == USB_RET_NAK) {

        ehci_set_state(q->ehci, q->async, EST_HORIZONTALQH);

    } else {

        ehci_set_state(q->ehci, q->async, EST_WRITEBACK);

    }



    again = 1;



out:

    ehci_flush_qh(q);

    return again;

}

static void qemu_spice_create_update(SimpleSpiceDisplay *ssd)

{

    static const int blksize = 32;

    int blocks = (surface_width(ssd->ds) + blksize - 1) / blksize;

    int dirty_top[blocks];

    int y, yoff, x, xoff, blk, bw;

    int bpp = surface_bytes_per_pixel(ssd->ds);

    uint8_t *guest, *mirror;



    if (qemu_spice_rect_is_empty(&ssd->dirty)) {

        return;

    };



    for (blk = 0; blk < blocks; blk++) {

        dirty_top[blk] = -1;

    }



    guest = surface_data(ssd->ds);

    mirror = (void *)pixman_image_get_data(ssd->mirror);

    for (y = ssd->dirty.top; y < ssd->dirty.bottom; y++) {

        yoff = y * surface_stride(ssd->ds);

        for (x = ssd->dirty.left; x < ssd->dirty.right; x += blksize) {

            xoff = x * bpp;

            blk = x / blksize;

            bw = MIN(blksize, ssd->dirty.right - x);

            if (memcmp(guest + yoff + xoff,

                       mirror + yoff + xoff,

                       bw * bpp) == 0) {

                if (dirty_top[blk] != -1) {

                    QXLRect update = {

                        .top    = dirty_top[blk],

                        .bottom = y,

                        .left   = x,

                        .right  = x + bw,

                    };

                    qemu_spice_create_one_update(ssd, &update);

                    dirty_top[blk] = -1;

                }

            } else {

                if (dirty_top[blk] == -1) {

                    dirty_top[blk] = y;

                }

            }

        }

    }



    for (x = ssd->dirty.left; x < ssd->dirty.right; x += blksize) {

        blk = x / blksize;

        bw = MIN(blksize, ssd->dirty.right - x);

        if (dirty_top[blk] != -1) {

            QXLRect update = {

                .top    = dirty_top[blk],

                .bottom = ssd->dirty.bottom,

                .left   = x,

                .right  = x + bw,

            };

            qemu_spice_create_one_update(ssd, &update);

            dirty_top[blk] = -1;

        }

    }



    memset(&ssd->dirty, 0, sizeof(ssd->dirty));

}

void tcp_connect(struct socket *inso)

{

    Slirp *slirp = inso->slirp;

    struct socket *so;

    struct sockaddr_in addr;

    socklen_t addrlen = sizeof(struct sockaddr_in);

    struct tcpcb *tp;

    int s, opt;



    DEBUG_CALL("tcp_connect");

    DEBUG_ARG("inso = %p", inso);



    /*

     * If it's an SS_ACCEPTONCE socket, no need to socreate()

     * another socket, just use the accept() socket.

     */

    if (inso->so_state & SS_FACCEPTONCE) {

        /* FACCEPTONCE already have a tcpcb */

        so = inso;

    } else {

        so = socreate(slirp);

        if (so == NULL) {

            /* If it failed, get rid of the pending connection */

            closesocket(accept(inso->s, (struct sockaddr *)&addr, &addrlen));

            return;

        }

        if (tcp_attach(so) < 0) {

            free(so); /* NOT sofree */

            return;

        }

        so->so_lfamily = AF_INET;

        so->so_laddr = inso->so_laddr;

        so->so_lport = inso->so_lport;

    }



    tcp_mss(sototcpcb(so), 0);



    s = accept(inso->s, (struct sockaddr *)&addr, &addrlen);

    if (s < 0) {

        tcp_close(sototcpcb(so)); /* This will sofree() as well */

        return;

    }

    qemu_set_nonblock(s);

    socket_set_fast_reuse(s);

    opt = 1;

    qemu_setsockopt(s, SOL_SOCKET, SO_OOBINLINE, &opt, sizeof(int));

    socket_set_nodelay(s);



    so->so_ffamily = AF_INET;

    so->so_fport = addr.sin_port;

    so->so_faddr = addr.sin_addr;

    /* Translate connections from localhost to the real hostname */

    if (so->so_faddr.s_addr == 0 ||

        (so->so_faddr.s_addr & loopback_mask) ==

        (loopback_addr.s_addr & loopback_mask)) {

        so->so_faddr = slirp->vhost_addr;

    }



    /* Close the accept() socket, set right state */

    if (inso->so_state & SS_FACCEPTONCE) {

        /* If we only accept once, close the accept() socket */

        closesocket(so->s);



        /* Don't select it yet, even though we have an FD */

        /* if it's not FACCEPTONCE, it's already NOFDREF */

        so->so_state = SS_NOFDREF;

    }

    so->s = s;

    so->so_state |= SS_INCOMING;



    so->so_iptos = tcp_tos(so);

    tp = sototcpcb(so);



    tcp_template(tp);



    tp->t_state = TCPS_SYN_SENT;

    tp->t_timer[TCPT_KEEP] = TCPTV_KEEP_INIT;

    tp->iss = slirp->tcp_iss;

    slirp->tcp_iss += TCP_ISSINCR/2;

    tcp_sendseqinit(tp);

    tcp_output(tp);

}

static int vorbis_parse_setup_hdr_modes(vorbis_context *vc) {

    GetBitContext *gb=&vc->gb;

    uint_fast8_t i;



    vc->mode_count=get_bits(gb, 6)+1;

    vc->modes=(vorbis_mode *)av_mallocz(vc->mode_count * sizeof(vorbis_mode));



    AV_DEBUG(" There are %d modes.\n", vc->mode_count);



    for(i=0;i<vc->mode_count;++i) {

        vorbis_mode *mode_setup=&vc->modes[i];



        mode_setup->blockflag=get_bits1(gb);

        mode_setup->windowtype=get_bits(gb, 16); //FIXME check

        mode_setup->transformtype=get_bits(gb, 16); //FIXME check

        mode_setup->mapping=get_bits(gb, 8); //FIXME check



        AV_DEBUG(" %d mode: blockflag %d, windowtype %d, transformtype %d, mapping %d \n", i, mode_setup->blockflag, mode_setup->windowtype, mode_setup->transformtype, mode_setup->mapping);

    }

    return 0;

}

static void check_exception(sPAPREnvironment *spapr,

                            uint32_t token, uint32_t nargs,

                            target_ulong args,

                            uint32_t nret, target_ulong rets)

{

    uint32_t mask, buf, len;

    uint64_t xinfo;



    if ((nargs < 6) || (nargs > 7) || nret != 1) {

        rtas_st(rets, 0, -3);

        return;

    }



    xinfo = rtas_ld(args, 1);

    mask = rtas_ld(args, 2);

    buf = rtas_ld(args, 4);

    len = rtas_ld(args, 5);

    if (nargs == 7) {

        xinfo |= (uint64_t)rtas_ld(args, 6) << 32;

    }



    if ((mask & EVENT_MASK_EPOW) && pending_epow) {

        if (sizeof(*pending_epow) < len) {

            len = sizeof(*pending_epow);

        }



        cpu_physical_memory_write(buf, pending_epow, len);

        g_free(pending_epow);

        pending_epow = NULL;

        rtas_st(rets, 0, 0);

    } else {

        rtas_st(rets, 0, 1);

    }

}

static void nvdimm_build_nfit(GSList *device_list, GArray *table_offsets,

                              GArray *table_data, BIOSLinker *linker)

{

    GArray *structures = nvdimm_build_device_structure(device_list);

    unsigned int header;



    acpi_add_table(table_offsets, table_data);



    /* NFIT header. */

    header = table_data->len;

    acpi_data_push(table_data, sizeof(NvdimmNfitHeader));

    /* NVDIMM device structures. */

    g_array_append_vals(table_data, structures->data, structures->len);



    build_header(linker, table_data,

                 (void *)(table_data->data + header), "NFIT",

                 sizeof(NvdimmNfitHeader) + structures->len, 1, NULL, NULL);

    g_array_free(structures, true);

}

const uint8_t *ff_h264_decode_nal(H264Context *h, const uint8_t *src,

                                  int *dst_length, int *consumed, int length)

{

    int i, si, di;

    uint8_t *dst;

    int bufidx;



    // src[0]&0x80; // forbidden bit

    h->nal_ref_idc   = src[0] >> 5;

    h->nal_unit_type = src[0] & 0x1F;



    src++;

    length--;



#define STARTCODE_TEST                                                  \

    if (i + 2 < length && src[i + 1] == 0 && src[i + 2] <= 3) {         \

        if (src[i + 2] != 3) {                                          \

            /* startcode, so we must be past the end */                 \

            length = i;                                                 \

        }                                                               \

        break;                                                          \

    }



#if HAVE_FAST_UNALIGNED

#define FIND_FIRST_ZERO                                                 \

    if (i > 0 && !src[i])                                               \

        i--;                                                            \

    while (src[i])                                                      \

        i++



#if HAVE_FAST_64BIT

    for (i = 0; i + 1 < length; i += 9) {

        if (!((~AV_RN64A(src + i) &

               (AV_RN64A(src + i) - 0x0100010001000101ULL)) &

              0x8000800080008080ULL))

            continue;

        FIND_FIRST_ZERO;

        STARTCODE_TEST;

        i -= 7;

    }

#else

    for (i = 0; i + 1 < length; i += 5) {

        if (!((~AV_RN32A(src + i) &

               (AV_RN32A(src + i) - 0x01000101U)) &

              0x80008080U))

            continue;

        FIND_FIRST_ZERO;

        STARTCODE_TEST;

        i -= 3;

    }

#endif

#else

    for (i = 0; i + 1 < length; i += 2) {

        if (src[i])

            continue;

        if (i > 0 && src[i - 1] == 0)

            i--;

        STARTCODE_TEST;

    }

#endif



    if (i >= length - 1) { // no escaped 0

        *dst_length = length;

        *consumed   = length + 1; // +1 for the header

        return src;

    }



    // use second escape buffer for inter data

    bufidx = h->nal_unit_type == NAL_DPC ? 1 : 0;

    av_fast_malloc(&h->rbsp_buffer[bufidx], &h->rbsp_buffer_size[bufidx],

                   length + FF_INPUT_BUFFER_PADDING_SIZE);

    dst = h->rbsp_buffer[bufidx];



    if (dst == NULL)

        return NULL;



    memcpy(dst, src, i);

    si = di = i;

    while (si + 2 < length) {

        // remove escapes (very rare 1:2^22)

        if (src[si + 2] > 3) {

            dst[di++] = src[si++];

            dst[di++] = src[si++];

        } else if (src[si] == 0 && src[si + 1] == 0) {

            if (src[si + 2] == 3) { // escape

                dst[di++]  = 0;

                dst[di++]  = 0;

                si        += 3;

                continue;

            } else // next start code

                goto nsc;

        }



        dst[di++] = src[si++];

    }

    while (si < length)

        dst[di++] = src[si++];



nsc:

    memset(dst + di, 0, FF_INPUT_BUFFER_PADDING_SIZE);



    *dst_length = di;

    *consumed   = si + 1; // +1 for the header

    /* FIXME store exact number of bits in the getbitcontext

     * (it is needed for decoding) */

    return dst;

}

static coroutine_fn int qcow2_co_writev(BlockDriverState *bs,

                           int64_t sector_num,

                           int remaining_sectors,

                           QEMUIOVector *qiov)

{

    BDRVQcowState *s = bs->opaque;

    int index_in_cluster;

    int ret;

    int cur_nr_sectors; /* number of sectors in current iteration */

    uint64_t cluster_offset;

    QEMUIOVector hd_qiov;

    uint64_t bytes_done = 0;

    uint8_t *cluster_data = NULL;

    QCowL2Meta *l2meta = NULL;



    trace_qcow2_writev_start_req(qemu_coroutine_self(), sector_num,

                                 remaining_sectors);



    qemu_iovec_init(&hd_qiov, qiov->niov);



    s->cluster_cache_offset = -1; /* disable compressed cache */



    qemu_co_mutex_lock(&s->lock);



    while (remaining_sectors != 0) {



        l2meta = NULL;



        trace_qcow2_writev_start_part(qemu_coroutine_self());

        index_in_cluster = sector_num & (s->cluster_sectors - 1);

        cur_nr_sectors = remaining_sectors;

        if (s->crypt_method &&

            cur_nr_sectors >

            QCOW_MAX_CRYPT_CLUSTERS * s->cluster_sectors - index_in_cluster) {

            cur_nr_sectors =

                QCOW_MAX_CRYPT_CLUSTERS * s->cluster_sectors - index_in_cluster;

        }



        ret = qcow2_alloc_cluster_offset(bs, sector_num << 9,

            &cur_nr_sectors, &cluster_offset, &l2meta);

        if (ret < 0) {

            goto fail;

        }



        assert((cluster_offset & 511) == 0);



        qemu_iovec_reset(&hd_qiov);

        qemu_iovec_concat(&hd_qiov, qiov, bytes_done,

            cur_nr_sectors * 512);



        if (s->crypt_method) {

            if (!cluster_data) {

                cluster_data = qemu_blockalign(bs, QCOW_MAX_CRYPT_CLUSTERS *

                                                 s->cluster_size);

            }



            assert(hd_qiov.size <=

                   QCOW_MAX_CRYPT_CLUSTERS * s->cluster_size);

            qemu_iovec_to_buf(&hd_qiov, 0, cluster_data, hd_qiov.size);



            qcow2_encrypt_sectors(s, sector_num, cluster_data,

                cluster_data, cur_nr_sectors, 1, &s->aes_encrypt_key);



            qemu_iovec_reset(&hd_qiov);

            qemu_iovec_add(&hd_qiov, cluster_data,

                cur_nr_sectors * 512);

        }



        ret = qcow2_pre_write_overlap_check(bs, 0,

                cluster_offset + index_in_cluster * BDRV_SECTOR_SIZE,

                cur_nr_sectors * BDRV_SECTOR_SIZE);

        if (ret < 0) {

            goto fail;

        }



        qemu_co_mutex_unlock(&s->lock);

        BLKDBG_EVENT(bs->file, BLKDBG_WRITE_AIO);

        trace_qcow2_writev_data(qemu_coroutine_self(),

                                (cluster_offset >> 9) + index_in_cluster);

        ret = bdrv_co_writev(bs->file,

                             (cluster_offset >> 9) + index_in_cluster,

                             cur_nr_sectors, &hd_qiov);

        qemu_co_mutex_lock(&s->lock);

        if (ret < 0) {

            goto fail;

        }



        while (l2meta != NULL) {

            QCowL2Meta *next;



            ret = qcow2_alloc_cluster_link_l2(bs, l2meta);

            if (ret < 0) {

                goto fail;

            }



            /* Take the request off the list of running requests */

            if (l2meta->nb_clusters != 0) {

                QLIST_REMOVE(l2meta, next_in_flight);

            }



            qemu_co_queue_restart_all(&l2meta->dependent_requests);



            next = l2meta->next;

            g_free(l2meta);

            l2meta = next;

        }



        remaining_sectors -= cur_nr_sectors;

        sector_num += cur_nr_sectors;

        bytes_done += cur_nr_sectors * 512;

        trace_qcow2_writev_done_part(qemu_coroutine_self(), cur_nr_sectors);

    }

    ret = 0;



fail:

    qemu_co_mutex_unlock(&s->lock);



    while (l2meta != NULL) {

        QCowL2Meta *next;



        if (l2meta->nb_clusters != 0) {

            QLIST_REMOVE(l2meta, next_in_flight);

        }

        qemu_co_queue_restart_all(&l2meta->dependent_requests);



        next = l2meta->next;

        g_free(l2meta);

        l2meta = next;

    }



    qemu_iovec_destroy(&hd_qiov);

    qemu_vfree(cluster_data);

    trace_qcow2_writev_done_req(qemu_coroutine_self(), ret);



    return ret;

}

do_send_recv(int sockfd, struct iovec *iov, unsigned iov_cnt, bool do_send)

{

#if defined CONFIG_IOVEC && defined CONFIG_POSIX

    ssize_t ret;

    struct msghdr msg;

    memset(&msg, 0, sizeof(msg));

    msg.msg_iov = iov;

    msg.msg_iovlen = iov_cnt;

    do {

        ret = do_send

            ? sendmsg(sockfd, &msg, 0)

            : recvmsg(sockfd, &msg, 0);

    } while (ret < 0 && errno == EINTR);

    return ret;

#else

    /* else send piece-by-piece */

    /*XXX Note: windows has WSASend() and WSARecv() */

    unsigned i = 0;

    ssize_t ret = 0;

    while (i < iov_cnt) {

        ssize_t r = do_send

            ? send(sockfd, iov[i].iov_base, iov[i].iov_len, 0)

            : recv(sockfd, iov[i].iov_base, iov[i].iov_len, 0);

        if (r > 0) {

            ret += r;

        } else if (!r) {

            break;

        } else if (errno == EINTR) {

            continue;

        } else {

            /* else it is some "other" error,

             * only return if there was no data processed. */

            if (ret == 0) {

                ret = -1;

            }

            break;

        }

        i++;

    }

    return ret;

#endif

}

