static void mov_text_style_cb(void *priv, const char style, int close)

{

    MovTextContext *s = priv;

    if (!close) {

        if (!(s->box_flags & STYL_BOX)) {   //first style entry



            s->style_attributes_temp = av_malloc(sizeof(*s->style_attributes_temp));



            if (!s->style_attributes_temp) {

                av_bprint_clear(&s->buffer);

                s->box_flags &= ~STYL_BOX;


            }



            s->style_attributes_temp->style_flag = 0;

            s->style_attributes_temp->style_start = AV_RB16(&s->text_pos);

        } else {

            if (s->style_attributes_temp->style_flag) { //break the style record here and start a new one

                s->style_attributes_temp->style_end = AV_RB16(&s->text_pos);

                av_dynarray_add(&s->style_attributes, &s->count, s->style_attributes_temp);

                s->style_attributes_temp = av_malloc(sizeof(*s->style_attributes_temp));

                if (!s->style_attributes_temp) {

                    mov_text_cleanup(s);

                    av_bprint_clear(&s->buffer);

                    s->box_flags &= ~STYL_BOX;


                }



                s->style_attributes_temp->style_flag = s->style_attributes[s->count - 1]->style_flag;

                s->style_attributes_temp->style_start = AV_RB16(&s->text_pos);

            } else {

                s->style_attributes_temp->style_flag = 0;

                s->style_attributes_temp->style_start = AV_RB16(&s->text_pos);

            }

        }

        switch (style){

        case 'b':

            s->style_attributes_temp->style_flag |= STYLE_FLAG_BOLD;

            break;

        case 'i':

            s->style_attributes_temp->style_flag |= STYLE_FLAG_ITALIC;

            break;

        case 'u':

            s->style_attributes_temp->style_flag |= STYLE_FLAG_UNDERLINE;

            break;

        }




    } else {

        s->style_attributes_temp->style_end = AV_RB16(&s->text_pos);

        av_dynarray_add(&s->style_attributes, &s->count, s->style_attributes_temp);



        s->style_attributes_temp = av_malloc(sizeof(*s->style_attributes_temp));



        if (!s->style_attributes_temp) {

            mov_text_cleanup(s);

            av_bprint_clear(&s->buffer);

            s->box_flags &= ~STYL_BOX;


        }



        s->style_attributes_temp->style_flag = s->style_attributes[s->count - 1]->style_flag;

        switch (style){

        case 'b':

            s->style_attributes_temp->style_flag &= ~STYLE_FLAG_BOLD;

            break;

        case 'i':

            s->style_attributes_temp->style_flag &= ~STYLE_FLAG_ITALIC;

            break;

        case 'u':

            s->style_attributes_temp->style_flag &= ~STYLE_FLAG_UNDERLINE;

            break;

        }

        if (s->style_attributes_temp->style_flag) { //start of new style record

            s->style_attributes_temp->style_start = AV_RB16(&s->text_pos);

        }

    }

    s->box_flags |= STYL_BOX;

}

int qcow2_check_metadata_overlap(BlockDriverState *bs, int chk, int64_t offset,

                                 int64_t size)

{

    BDRVQcowState *s = bs->opaque;

    int i, j;



    if (!size) {

        return 0;

    }



    if (chk & QCOW2_OL_MAIN_HEADER) {

        if (offset < s->cluster_size) {

            return QCOW2_OL_MAIN_HEADER;

        }

    }



    /* align range to test to cluster boundaries */

    size = align_offset(offset_into_cluster(s, offset) + size, s->cluster_size);

    offset = start_of_cluster(s, offset);



    if ((chk & QCOW2_OL_ACTIVE_L1) && s->l1_size) {

        if (overlaps_with(s->l1_table_offset, s->l1_size * sizeof(uint64_t))) {

            return QCOW2_OL_ACTIVE_L1;

        }

    }



    if ((chk & QCOW2_OL_REFCOUNT_TABLE) && s->refcount_table_size) {

        if (overlaps_with(s->refcount_table_offset,

            s->refcount_table_size * sizeof(uint64_t))) {

            return QCOW2_OL_REFCOUNT_TABLE;

        }

    }



    if ((chk & QCOW2_OL_SNAPSHOT_TABLE) && s->snapshots_size) {

        if (overlaps_with(s->snapshots_offset, s->snapshots_size)) {

            return QCOW2_OL_SNAPSHOT_TABLE;

        }

    }



    if ((chk & QCOW2_OL_INACTIVE_L1) && s->snapshots) {

        for (i = 0; i < s->nb_snapshots; i++) {

            if (s->snapshots[i].l1_size &&

                overlaps_with(s->snapshots[i].l1_table_offset,

                s->snapshots[i].l1_size * sizeof(uint64_t))) {

                return QCOW2_OL_INACTIVE_L1;

            }

        }

    }



    if ((chk & QCOW2_OL_ACTIVE_L2) && s->l1_table) {

        for (i = 0; i < s->l1_size; i++) {

            if ((s->l1_table[i] & L1E_OFFSET_MASK) &&

                overlaps_with(s->l1_table[i] & L1E_OFFSET_MASK,

                s->cluster_size)) {

                return QCOW2_OL_ACTIVE_L2;

            }

        }

    }



    if ((chk & QCOW2_OL_REFCOUNT_BLOCK) && s->refcount_table) {

        for (i = 0; i < s->refcount_table_size; i++) {

            if ((s->refcount_table[i] & REFT_OFFSET_MASK) &&

                overlaps_with(s->refcount_table[i] & REFT_OFFSET_MASK,

                s->cluster_size)) {

                return QCOW2_OL_REFCOUNT_BLOCK;

            }

        }

    }



    if ((chk & QCOW2_OL_INACTIVE_L2) && s->snapshots) {

        for (i = 0; i < s->nb_snapshots; i++) {

            uint64_t l1_ofs = s->snapshots[i].l1_table_offset;

            uint32_t l1_sz  = s->snapshots[i].l1_size;

            uint64_t l1_sz2 = l1_sz * sizeof(uint64_t);

            uint64_t *l1 = g_malloc(l1_sz2);

            int ret;



            ret = bdrv_pread(bs->file, l1_ofs, l1, l1_sz2);

            if (ret < 0) {

                g_free(l1);

                return ret;

            }



            for (j = 0; j < l1_sz; j++) {

                uint64_t l2_ofs = be64_to_cpu(l1[j]) & L1E_OFFSET_MASK;

                if (l2_ofs && overlaps_with(l2_ofs, s->cluster_size)) {

                    g_free(l1);

                    return QCOW2_OL_INACTIVE_L2;

                }

            }



            g_free(l1);

        }

    }



    return 0;

}

static int compute_pkt_fields2(AVStream *st, AVPacket *pkt){

    int delay = FFMAX(st->codec->has_b_frames, !!st->codec->max_b_frames);

    int num, den, frame_size, i;



//    av_log(st->codec, AV_LOG_DEBUG, "av_write_frame: pts:%"PRId64" dts:%"PRId64" cur_dts:%"PRId64" b:%d size:%d st:%d\n", pkt->pts, pkt->dts, st->cur_dts, delay, pkt->size, pkt->stream_index);



/*    if(pkt->pts == AV_NOPTS_VALUE && pkt->dts == AV_NOPTS_VALUE)

        return -1;*/



    /* duration field */

    if (pkt->duration == 0) {

        compute_frame_duration(&num, &den, st, NULL, pkt);

        if (den && num) {

            pkt->duration = av_rescale(1, num * (int64_t)st->time_base.den, den * (int64_t)st->time_base.num);

        }

    }



    if(pkt->pts == AV_NOPTS_VALUE && pkt->dts != AV_NOPTS_VALUE && delay==0)

        pkt->pts= pkt->dts;



    //XXX/FIXME this is a temporary hack until all encoders output pts

    if((pkt->pts == 0 || pkt->pts == AV_NOPTS_VALUE) && pkt->dts == AV_NOPTS_VALUE && !delay){

        pkt->dts=

//        pkt->pts= st->cur_dts;

        pkt->pts= st->pts.val;

    }



    //calculate dts from pts

    if(pkt->pts != AV_NOPTS_VALUE && pkt->dts == AV_NOPTS_VALUE){

        st->pts_buffer[0]= pkt->pts;

        for(i=1; i<delay+1 && st->pts_buffer[i] == AV_NOPTS_VALUE; i++)

            st->pts_buffer[i]= (i-delay-1) * pkt->duration;

        for(i=0; i<delay && st->pts_buffer[i] > st->pts_buffer[i+1]; i++)

            FFSWAP(int64_t, st->pts_buffer[i], st->pts_buffer[i+1]);



        pkt->dts= st->pts_buffer[0];

    }



    if(st->cur_dts && st->cur_dts != AV_NOPTS_VALUE && st->cur_dts >= pkt->dts){

        av_log(st->codec, AV_LOG_ERROR, "error, non monotone timestamps %"PRId64" >= %"PRId64"\n", st->cur_dts, pkt->dts);

        return -1;

    }

    if(pkt->dts != AV_NOPTS_VALUE && pkt->pts != AV_NOPTS_VALUE && pkt->pts < pkt->dts){

        av_log(st->codec, AV_LOG_ERROR, "error, pts < dts\n");

        return -1;

    }



//    av_log(NULL, AV_LOG_DEBUG, "av_write_frame: pts2:%"PRId64" dts2:%"PRId64"\n", pkt->pts, pkt->dts);

    st->cur_dts= pkt->dts;

    st->pts.val= pkt->dts;



    /* update pts */

    switch (st->codec->codec_type) {

    case CODEC_TYPE_AUDIO:

        frame_size = get_audio_frame_size(st->codec, pkt->size);



        /* HACK/FIXME, we skip the initial 0 size packets as they are most

           likely equal to the encoder delay, but it would be better if we

           had the real timestamps from the encoder */

        if (frame_size >= 0 && (pkt->size || st->pts.num!=st->pts.den>>1 || st->pts.val)) {

            av_frac_add(&st->pts, (int64_t)st->time_base.den * frame_size);

        }

        break;

    case CODEC_TYPE_VIDEO:

        av_frac_add(&st->pts, (int64_t)st->time_base.den * st->codec->time_base.num);

        break;

    default:

        break;

    }

    return 0;

}

static int dnxhd_encode_fast(AVCodecContext *avctx, DNXHDEncContext *ctx)

{

    int max_bits = 0;

    int ret, x, y;

    if ((ret = dnxhd_find_qscale(ctx)) < 0)

        return ret;

    for (y = 0; y < ctx->m.mb_height; y++) {

        for (x = 0; x < ctx->m.mb_width; x++) {

            int mb = y * ctx->m.mb_width + x;

            int rc = (ctx->qscale * ctx->m.mb_num ) + mb;

            int delta_bits;

            ctx->mb_qscale[mb] = ctx->qscale;

            ctx->mb_bits[mb] = ctx->mb_rc[rc].bits;

            max_bits += ctx->mb_rc[rc].bits;

            if (!RC_VARIANCE) {

                delta_bits = ctx->mb_rc[rc].bits -

                             ctx->mb_rc[rc + ctx->m.mb_num].bits;

                ctx->mb_cmp[mb].mb = mb;

                ctx->mb_cmp[mb].value =

                    delta_bits ? ((ctx->mb_rc[rc].ssd -

                                   ctx->mb_rc[rc + ctx->m.mb_num].ssd) * 100) /

                                  delta_bits

                               : INT_MIN; // avoid increasing qscale

            }

        }

        max_bits += 31; // worst padding

    }

    if (!ret) {

        if (RC_VARIANCE)

            avctx->execute2(avctx, dnxhd_mb_var_thread,

                            NULL, NULL, ctx->m.mb_height);

        radix_sort(ctx->mb_cmp, ctx->m.mb_num);

        for (x = 0; x < ctx->m.mb_num && max_bits > ctx->frame_bits; x++) {

            int mb = ctx->mb_cmp[x].mb;

            int rc = (ctx->qscale * ctx->m.mb_num ) + mb;

            max_bits -= ctx->mb_rc[rc].bits -

                        ctx->mb_rc[rc + ctx->m.mb_num].bits;

            ctx->mb_qscale[mb] = ctx->qscale + 1;

            ctx->mb_bits[mb]   = ctx->mb_rc[rc + ctx->m.mb_num].bits;

        }

    }

    return 0;

}

static int img_read_header(AVFormatContext *s1, AVFormatParameters *ap)

{

    VideoData *s = s1->priv_data;

    int ret, first_index, last_index;

    char buf[1024];

    ByteIOContext pb1, *f = &pb1;

    AVStream *st;



    st = av_new_stream(s1, 0);

    if (!st) {

        av_free(s);

        return -ENOMEM;

    }



    if (ap && ap->image_format)

        s->img_fmt = ap->image_format;



    strcpy(s->path, s1->filename);

    s->img_number = 0;



    /* find format */

    if (s1->iformat->flags & AVFMT_NOFILE)

        s->is_pipe = 0;

    else

        s->is_pipe = 1;



    if (!ap || !ap->frame_rate) {

        st->codec.frame_rate      = 25;

        st->codec.frame_rate_base = 1;

    } else {

        st->codec.frame_rate      = ap->frame_rate;

        st->codec.frame_rate_base = ap->frame_rate_base;

    }



    if (!s->is_pipe) {

        if (find_image_range(&first_index, &last_index, s->path) < 0)

            goto fail;

        s->img_number = first_index;

        /* compute duration */

        st->start_time = 0;

        st->duration = ((int64_t)AV_TIME_BASE * 

                        (last_index - first_index + 1) * 

                        st->codec.frame_rate_base) / st->codec.frame_rate;

        if (get_frame_filename(buf, sizeof(buf), s->path, s->img_number) < 0)

            goto fail;

        if (url_fopen(f, buf, URL_RDONLY) < 0)

            goto fail;

    } else {

        f = &s1->pb;

    }



    ret = av_read_image(f, s1->filename, s->img_fmt, read_header_alloc_cb, s);

    if (ret < 0)

        goto fail1;



    if (!s->is_pipe) {

        url_fclose(f);

    } else {

        url_fseek(f, 0, SEEK_SET);

    }



    st->codec.codec_type = CODEC_TYPE_VIDEO;

    st->codec.codec_id = CODEC_ID_RAWVIDEO;

    st->codec.width = s->width;

    st->codec.height = s->height;

    st->codec.pix_fmt = s->pix_fmt;

    s->img_size = avpicture_get_size(s->pix_fmt, s->width, s->height);



    return 0;

 fail1:

    if (!s->is_pipe)

        url_fclose(f);

 fail:

    av_free(s);

    return -EIO;

}

