static int pci_rocker_init(PCIDevice *dev)

{

    Rocker *r = to_rocker(dev);

    const MACAddr zero = { .a = { 0, 0, 0, 0, 0, 0 } };

    const MACAddr dflt = { .a = { 0x52, 0x54, 0x00, 0x12, 0x35, 0x01 } };

    static int sw_index;

    int i, err = 0;



    /* allocate worlds */



    r->worlds[ROCKER_WORLD_TYPE_OF_DPA] = of_dpa_world_alloc(r);



    if (!r->world_name) {

        r->world_name = g_strdup(world_name(r->worlds[ROCKER_WORLD_TYPE_OF_DPA]));

    }



    r->world_dflt = rocker_world_type_by_name(r, r->world_name);

    if (!r->world_dflt) {

        fprintf(stderr,

                "rocker: requested world \"%s\" does not exist\n",

                r->world_name);

        err = -EINVAL;

        goto err_world_type_by_name;

    }



    /* set up memory-mapped region at BAR0 */



    memory_region_init_io(&r->mmio, OBJECT(r), &rocker_mmio_ops, r,

                          "rocker-mmio", ROCKER_PCI_BAR0_SIZE);

    pci_register_bar(dev, ROCKER_PCI_BAR0_IDX,

                     PCI_BASE_ADDRESS_SPACE_MEMORY, &r->mmio);



    /* set up memory-mapped region for MSI-X */



    memory_region_init(&r->msix_bar, OBJECT(r), "rocker-msix-bar",

                       ROCKER_PCI_MSIX_BAR_SIZE);

    pci_register_bar(dev, ROCKER_PCI_MSIX_BAR_IDX,

                     PCI_BASE_ADDRESS_SPACE_MEMORY, &r->msix_bar);



    /* MSI-X init */



    err = rocker_msix_init(r);

    if (err) {

        goto err_msix_init;

    }



    /* validate switch properties */



    if (!r->name) {

        r->name = g_strdup(ROCKER);

    }



    if (rocker_find(r->name)) {

        err = -EEXIST;

        goto err_duplicate;

    }



    /* Rocker name is passed in port name requests to OS with the intention

     * that the name is used in interface names. Limit the length of the

     * rocker name to avoid naming problems in the OS. Also, adding the

     * port number as p# and unganged breakout b#, where # is at most 2

     * digits, so leave room for it too (-1 for string terminator, -3 for

     * p# and -3 for b#)

     */

#define ROCKER_IFNAMSIZ 16

#define MAX_ROCKER_NAME_LEN  (ROCKER_IFNAMSIZ - 1 - 3 - 3)

    if (strlen(r->name) > MAX_ROCKER_NAME_LEN) {

        fprintf(stderr,

                "rocker: name too long; please shorten to at most %d chars\n",

                MAX_ROCKER_NAME_LEN);

        return -EINVAL;

    }



    if (memcmp(&r->fp_start_macaddr, &zero, sizeof(zero)) == 0) {

        memcpy(&r->fp_start_macaddr, &dflt, sizeof(dflt));

        r->fp_start_macaddr.a[4] += (sw_index++);

    }



    if (!r->switch_id) {

        memcpy(&r->switch_id, &r->fp_start_macaddr,

               sizeof(r->fp_start_macaddr));

    }



    if (r->fp_ports > ROCKER_FP_PORTS_MAX) {

        r->fp_ports = ROCKER_FP_PORTS_MAX;

    }



    r->rings = g_new(DescRing *, rocker_pci_ring_count(r));



    /* Rings are ordered like this:

     * - command ring

     * - event ring

     * - port0 tx ring

     * - port0 rx ring

     * - port1 tx ring

     * - port1 rx ring

     * .....

     */



    for (i = 0; i < rocker_pci_ring_count(r); i++) {

        DescRing *ring = desc_ring_alloc(r, i);



        if (i == ROCKER_RING_CMD) {

            desc_ring_set_consume(ring, cmd_consume, ROCKER_MSIX_VEC_CMD);

        } else if (i == ROCKER_RING_EVENT) {

            desc_ring_set_consume(ring, NULL, ROCKER_MSIX_VEC_EVENT);

        } else if (i % 2 == 0) {

            desc_ring_set_consume(ring, tx_consume,

                                  ROCKER_MSIX_VEC_TX((i - 2) / 2));

        } else if (i % 2 == 1) {

            desc_ring_set_consume(ring, NULL, ROCKER_MSIX_VEC_RX((i - 3) / 2));

        }



        r->rings[i] = ring;

    }



    for (i = 0; i < r->fp_ports; i++) {

        FpPort *port =

            fp_port_alloc(r, r->name, &r->fp_start_macaddr,

                          i, &r->fp_ports_peers[i]);



        r->fp_port[i] = port;

        fp_port_set_world(port, r->world_dflt);

    }



    QLIST_INSERT_HEAD(&rockers, r, next);



    return 0;



err_duplicate:

    rocker_msix_uninit(r);

err_msix_init:

    object_unparent(OBJECT(&r->msix_bar));

    object_unparent(OBJECT(&r->mmio));

err_world_type_by_name:

    for (i = 0; i < ROCKER_WORLD_TYPE_MAX; i++) {

        if (r->worlds[i]) {

            world_free(r->worlds[i]);

        }

    }

    return err;

}

static int cow_test_bit(int64_t bitnum, const uint8_t *bitmap)

{

    return (bitmap[bitnum / 8] & (1 << (bitnum & 7))) != 0;

}

static void create_gic(VirtBoardInfo *vbi, qemu_irq *pic)

{

    /* We create a standalone GIC v2 */

    DeviceState *gicdev;

    SysBusDevice *gicbusdev;

    const char *gictype;

    int i;



    gictype = gic_class_name();



    gicdev = qdev_create(NULL, gictype);

    qdev_prop_set_uint32(gicdev, "revision", 2);

    qdev_prop_set_uint32(gicdev, "num-cpu", smp_cpus);

    /* Note that the num-irq property counts both internal and external

     * interrupts; there are always 32 of the former (mandated by GIC spec).

     */

    qdev_prop_set_uint32(gicdev, "num-irq", NUM_IRQS + 32);

    qdev_init_nofail(gicdev);

    gicbusdev = SYS_BUS_DEVICE(gicdev);

    sysbus_mmio_map(gicbusdev, 0, vbi->memmap[VIRT_GIC_DIST].base);

    sysbus_mmio_map(gicbusdev, 1, vbi->memmap[VIRT_GIC_CPU].base);



    /* Wire the outputs from each CPU's generic timer to the

     * appropriate GIC PPI inputs, and the GIC's IRQ output to

     * the CPU's IRQ input.

     */

    for (i = 0; i < smp_cpus; i++) {

        DeviceState *cpudev = DEVICE(qemu_get_cpu(i));

        int ppibase = NUM_IRQS + i * GIC_INTERNAL + GIC_NR_SGIS;

        /* physical timer; we wire it up to the non-secure timer's ID,

         * since a real A15 always has TrustZone but QEMU doesn't.

         */

        qdev_connect_gpio_out(cpudev, 0,

                              qdev_get_gpio_in(gicdev,

                                             ppibase + ARCH_TIMER_NS_EL1_IRQ));

        /* virtual timer */

        qdev_connect_gpio_out(cpudev, 1,

                              qdev_get_gpio_in(gicdev,

                                               ppibase + ARCH_TIMER_VIRT_IRQ));

        /* Hypervisor timer.  */

        qdev_connect_gpio_out(cpudev, 2,

                              qdev_get_gpio_in(gicdev,

                                             ppibase + ARCH_TIMER_NS_EL2_IRQ));



        sysbus_connect_irq(gicbusdev, i, qdev_get_gpio_in(cpudev, ARM_CPU_IRQ));

        sysbus_connect_irq(gicbusdev, i + smp_cpus,

                           qdev_get_gpio_in(cpudev, ARM_CPU_FIQ));

    }



    for (i = 0; i < NUM_IRQS; i++) {

        pic[i] = qdev_get_gpio_in(gicdev, i);

    }



    fdt_add_gic_node(vbi);



    create_v2m(vbi, pic);

}

static void kvmppc_host_cpu_class_init(ObjectClass *oc, void *data)

{

    DeviceClass *dc = DEVICE_CLASS(oc);

    PowerPCCPUClass *pcc = POWERPC_CPU_CLASS(oc);

    uint32_t vmx = kvmppc_get_vmx();

    uint32_t dfp = kvmppc_get_dfp();

    uint32_t dcache_size = kvmppc_read_int_cpu_dt("d-cache-size");

    uint32_t icache_size = kvmppc_read_int_cpu_dt("i-cache-size");



    /* Now fix up the class with information we can query from the host */

    pcc->pvr = mfpvr();



    if (vmx != -1) {

        /* Only override when we know what the host supports */

        alter_insns(&pcc->insns_flags, PPC_ALTIVEC, vmx > 0);

        alter_insns(&pcc->insns_flags2, PPC2_VSX, vmx > 1);

    }

    if (dfp != -1) {

        /* Only override when we know what the host supports */

        alter_insns(&pcc->insns_flags2, PPC2_DFP, dfp);

    }



    if (dcache_size != -1) {

        pcc->l1_dcache_size = dcache_size;

    }



    if (icache_size != -1) {

        pcc->l1_icache_size = icache_size;

    }



    /* Reason: kvmppc_host_cpu_initfn() dies when !kvm_enabled() */

    dc->cannot_destroy_with_object_finalize_yet = true;

}

static float128 addFloat128Sigs( float128 a, float128 b, flag zSign STATUS_PARAM)

{

    int32 aExp, bExp, zExp;

    uint64_t aSig0, aSig1, bSig0, bSig1, zSig0, zSig1, zSig2;

    int32 expDiff;



    aSig1 = extractFloat128Frac1( a );

    aSig0 = extractFloat128Frac0( a );

    aExp = extractFloat128Exp( a );

    bSig1 = extractFloat128Frac1( b );

    bSig0 = extractFloat128Frac0( b );

    bExp = extractFloat128Exp( b );

    expDiff = aExp - bExp;

    if ( 0 < expDiff ) {

        if ( aExp == 0x7FFF ) {

            if ( aSig0 | aSig1 ) return propagateFloat128NaN( a, b STATUS_VAR );

            return a;

        }

        if ( bExp == 0 ) {

            --expDiff;

        }

        else {

            bSig0 |= LIT64( 0x0001000000000000 );

        }

        shift128ExtraRightJamming(

            bSig0, bSig1, 0, expDiff, &bSig0, &bSig1, &zSig2 );

        zExp = aExp;

    }

    else if ( expDiff < 0 ) {

        if ( bExp == 0x7FFF ) {

            if ( bSig0 | bSig1 ) return propagateFloat128NaN( a, b STATUS_VAR );

            return packFloat128( zSign, 0x7FFF, 0, 0 );

        }

        if ( aExp == 0 ) {

            ++expDiff;

        }

        else {

            aSig0 |= LIT64( 0x0001000000000000 );

        }

        shift128ExtraRightJamming(

            aSig0, aSig1, 0, - expDiff, &aSig0, &aSig1, &zSig2 );

        zExp = bExp;

    }

    else {

        if ( aExp == 0x7FFF ) {

            if ( aSig0 | aSig1 | bSig0 | bSig1 ) {

                return propagateFloat128NaN( a, b STATUS_VAR );

            }

            return a;

        }

        add128( aSig0, aSig1, bSig0, bSig1, &zSig0, &zSig1 );

        if ( aExp == 0 ) {

            if ( STATUS(flush_to_zero) ) return packFloat128( zSign, 0, 0, 0 );

            return packFloat128( zSign, 0, zSig0, zSig1 );

        }

        zSig2 = 0;

        zSig0 |= LIT64( 0x0002000000000000 );

        zExp = aExp;

        goto shiftRight1;

    }

    aSig0 |= LIT64( 0x0001000000000000 );

    add128( aSig0, aSig1, bSig0, bSig1, &zSig0, &zSig1 );

    --zExp;

    if ( zSig0 < LIT64( 0x0002000000000000 ) ) goto roundAndPack;

    ++zExp;

 shiftRight1:

    shift128ExtraRightJamming(

        zSig0, zSig1, zSig2, 1, &zSig0, &zSig1, &zSig2 );

 roundAndPack:

    return roundAndPackFloat128( zSign, zExp, zSig0, zSig1, zSig2 STATUS_VAR );



}

static void test_acpi_one(const char *params)

{

    char *args;

    uint8_t signature_low;

    uint8_t signature_high;

    uint16_t signature;

    int i;

    uint32_t off;





    args = g_strdup_printf("-net none -display none %s %s",

                           params ? params : "", disk);

    qtest_start(args);



   /* Wait at most 1 minute */

#define TEST_DELAY (1 * G_USEC_PER_SEC / 10)

#define TEST_CYCLES MAX((60 * G_USEC_PER_SEC / TEST_DELAY), 1)



    /* Poll until code has run and modified memory.  Once it has we know BIOS

     * initialization is done.  TODO: check that IP reached the halt

     * instruction.

     */

    for (i = 0; i < TEST_CYCLES; ++i) {

        signature_low = readb(BOOT_SECTOR_ADDRESS + SIGNATURE_OFFSET);

        signature_high = readb(BOOT_SECTOR_ADDRESS + SIGNATURE_OFFSET + 1);

        signature = (signature_high << 8) | signature_low;

        if (signature == SIGNATURE) {

            break;

        }

        g_usleep(TEST_DELAY);

    }

    g_assert_cmphex(signature, ==, SIGNATURE);



    /* OK, now find RSDP */

    for (off = 0xf0000; off < 0x100000; off += 0x10)

    {

        uint8_t sig[] = "RSD PTR ";

        int i;



        for (i = 0; i < sizeof sig - 1; ++i) {

            sig[i] = readb(off + i);

        }



        if (!memcmp(sig, "RSD PTR ", sizeof sig)) {

            break;

        }

    }



    g_assert_cmphex(off, <, 0x100000);



    qtest_quit(global_qtest);

    g_free(args);

}

static FFPsyWindowInfo psy_3gpp_window(FFPsyContext *ctx,

                                       const int16_t *audio, const int16_t *la,

                                       int channel, int prev_type)

{

    int i, j;

    int br               = ctx->avctx->bit_rate / ctx->avctx->channels;

    int attack_ratio     = br <= 16000 ? 18 : 10;

    Psy3gppContext *pctx = (Psy3gppContext*) ctx->model_priv_data;

    Psy3gppChannel *pch  = &pctx->ch[channel];

    uint8_t grouping     = 0;

    FFPsyWindowInfo wi;



    memset(&wi, 0, sizeof(wi));

    if (la) {

        float s[8], v;

        int switch_to_eight = 0;

        float sum = 0.0, sum2 = 0.0;

        int attack_n = 0;

        for (i = 0; i < 8; i++) {

            for (j = 0; j < 128; j++) {

                v = iir_filter(la[(i*128+j)*ctx->avctx->channels], pch->iir_state);

                sum += v*v;

            }

            s[i]  = sum;

            sum2 += sum;

        }

        for (i = 0; i < 8; i++) {

            if (s[i] > pch->win_energy * attack_ratio) {

                attack_n        = i + 1;

                switch_to_eight = 1;

                break;

            }

        }

        pch->win_energy = pch->win_energy*7/8 + sum2/64;



        wi.window_type[1] = prev_type;

        switch (prev_type) {

        case ONLY_LONG_SEQUENCE:

            wi.window_type[0] = switch_to_eight ? LONG_START_SEQUENCE : ONLY_LONG_SEQUENCE;

            break;

        case LONG_START_SEQUENCE:

            wi.window_type[0] = EIGHT_SHORT_SEQUENCE;

            grouping = pch->next_grouping;

            break;

        case LONG_STOP_SEQUENCE:

            wi.window_type[0] = ONLY_LONG_SEQUENCE;

            break;

        case EIGHT_SHORT_SEQUENCE:

            wi.window_type[0] = switch_to_eight ? EIGHT_SHORT_SEQUENCE : LONG_STOP_SEQUENCE;

            grouping = switch_to_eight ? pch->next_grouping : 0;

            break;

        }

        pch->next_grouping = window_grouping[attack_n];

    } else {

        for (i = 0; i < 3; i++)

            wi.window_type[i] = prev_type;

        grouping = (prev_type == EIGHT_SHORT_SEQUENCE) ? window_grouping[0] : 0;

    }



    wi.window_shape   = 1;

    if (wi.window_type[0] != EIGHT_SHORT_SEQUENCE) {

        wi.num_windows = 1;

        wi.grouping[0] = 1;

    } else {

        int lastgrp = 0;

        wi.num_windows = 8;

        for (i = 0; i < 8; i++) {

            if (!((grouping >> i) & 1))

                lastgrp = i;

            wi.grouping[lastgrp]++;

        }

    }



    return wi;

}

void kqemu_set_phys_mem(uint64_t start_addr, ram_addr_t size, 

                        ram_addr_t phys_offset)

{

    struct kqemu_phys_mem kphys_mem1, *kphys_mem = &kphys_mem1;

    uint64_t end;

    int ret, io_index;



    end = (start_addr + size + TARGET_PAGE_SIZE - 1) & TARGET_PAGE_MASK;

    start_addr &= TARGET_PAGE_MASK;

    kphys_mem->phys_addr = start_addr;

    kphys_mem->size = end - start_addr;

    kphys_mem->ram_addr = phys_offset & TARGET_PAGE_MASK;

    io_index = phys_offset & ~TARGET_PAGE_MASK;

    switch(io_index) {

    case IO_MEM_RAM:

        kphys_mem->io_index = KQEMU_IO_MEM_RAM;

        break;

    case IO_MEM_ROM:

        kphys_mem->io_index = KQEMU_IO_MEM_ROM;

        break;

    default:

        if (qpi_io_memory == io_index) {

            kphys_mem->io_index = KQEMU_IO_MEM_COMM;

        } else {

            kphys_mem->io_index = KQEMU_IO_MEM_UNASSIGNED;

        }

        break;

    }

#ifdef _WIN32

    {

        DWORD temp;

        ret = DeviceIoControl(kqemu_fd, KQEMU_SET_PHYS_MEM, 

                              kphys_mem, sizeof(*kphys_mem),

                              NULL, 0, &temp, NULL) == TRUE ? 0 : -1;

    }

#else

    ret = ioctl(kqemu_fd, KQEMU_SET_PHYS_MEM, kphys_mem);

#endif

    if (ret < 0) {

        fprintf(stderr, "kqemu: KQEMU_SET_PHYS_PAGE error=%d: start_addr=0x%016" PRIx64 " size=0x%08lx phys_offset=0x%08lx\n",

                ret, start_addr, 

                (unsigned long)size, (unsigned long)phys_offset);

    }

}

static void omap_dpll_write(void *opaque, target_phys_addr_t addr,

                            uint64_t value, unsigned size)

{

    struct dpll_ctl_s *s = (struct dpll_ctl_s *) opaque;

    uint16_t diff;

    static const int bypass_div[4] = { 1, 2, 4, 4 };

    int div, mult;



    if (size != 2) {

        return omap_badwidth_write16(opaque, addr, value);

    }



    if (addr == 0x00) {	/* CTL_REG */

        /* See omap_ulpd_pm_write() too */

        diff = s->mode & value;

        s->mode = value & 0x2fff;

        if (diff & (0x3ff << 2)) {

            if (value & (1 << 4)) {			/* PLL_ENABLE */

                div = ((value >> 5) & 3) + 1;		/* PLL_DIV */

                mult = MIN((value >> 7) & 0x1f, 1);	/* PLL_MULT */

            } else {

                div = bypass_div[((value >> 2) & 3)];	/* BYPASS_DIV */

                mult = 1;

            }

            omap_clk_setrate(s->dpll, div, mult);

        }



        /* Enter the desired mode.  */

        s->mode = (s->mode & 0xfffe) | ((s->mode >> 4) & 1);



        /* Act as if the lock is restored.  */

        s->mode |= 2;

    } else {

        OMAP_BAD_REG(addr);

    }

}

