static int amr_read_packet(AVFormatContext *s,

                          AVPacket *pkt)

{

    AVCodecContext *enc = s->streams[0]->codec;

    int read, size, toc, mode;



    if (url_feof(&s->pb))

    {

        return AVERROR_IO;

    }



//FIXME this is wrong, this should rather be in a AVParset

    toc=get_byte(&s->pb);

    mode = (toc >> 3) & 0x0F;



    if (enc->codec_id == CODEC_ID_AMR_NB)

    {

        static const uint8_t packed_size[16] = {12, 13, 15, 17, 19, 20, 26, 31, 5, 0, 0, 0, 0, 0, 0, 0};



        size=packed_size[mode]+1;

    }

    else if(enc->codec_id == CODEC_ID_AMR_WB)

    {

        static uint8_t packed_size[16] = {18, 24, 33, 37, 41, 47, 51, 59, 61, 6, 6, 0, 0, 0, 1, 1};



        size=packed_size[mode];

    }

    else

    {

        assert(0);

    }



    if ( (size==0) || av_new_packet(pkt, size))

    {

        return AVERROR_IO;

    }



    pkt->stream_index = 0;

    pkt->pos= url_ftell(&s->pb);

    pkt->data[0]=toc;

    pkt->duration= enc->codec_id == CODEC_ID_AMR_NB ? 160 : 320;

    read = get_buffer(&s->pb, pkt->data+1, size-1);



    if (read != size-1)

    {

        av_free_packet(pkt);

        return AVERROR_IO;

    }



    return 0;

}

static void park_frame_worker_threads(FrameThreadContext *fctx, int thread_count)

{

    int i;



    for (i = 0; i < thread_count; i++) {

        PerThreadContext *p = &fctx->threads[i];



        if (p->state != STATE_INPUT_READY) {

            pthread_mutex_lock(&p->progress_mutex);

            while (p->state != STATE_INPUT_READY)

                pthread_cond_wait(&p->output_cond, &p->progress_mutex);

            pthread_mutex_unlock(&p->progress_mutex);

        }


    }

}

static int nut_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    NUTContext *nut = s->priv_data;

    ByteIOContext *bc = &s->pb;

    int i, frame_code=0, ret, skip;

    int64_t ts, back_ptr;



    for(;;){

        int64_t pos= url_ftell(bc);

        uint64_t tmp= nut->next_startcode;

        nut->next_startcode=0;



        if (url_feof(bc))

            return -1;



        if(tmp){

            pos-=8;

        }else{

            frame_code = get_byte(bc);

            if(frame_code == 'N'){

                tmp= frame_code;

                for(i=1; i<8; i++)

                    tmp = (tmp<<8) + get_byte(bc);

            }

        }

        switch(tmp){

        case MAIN_STARTCODE:

        case STREAM_STARTCODE:

        case INDEX_STARTCODE:

            skip= get_packetheader(nut, bc, 0);

            url_fseek(bc, skip, SEEK_CUR);

            break;

        case INFO_STARTCODE:

            if(decode_info_header(nut)<0)

                goto resync;

            break;

        case SYNCPOINT_STARTCODE:

            if(decode_syncpoint(nut, &ts, &back_ptr)<0)

                goto resync;

            frame_code = get_byte(bc);

        case 0:

            ret= decode_frame(nut, pkt, frame_code);

            if(ret==0)

                return 0;

            else if(ret==1) //ok but discard packet

                break;

        default:

resync:

av_log(s, AV_LOG_DEBUG, "syncing from %"PRId64"\n", pos);

            tmp= find_any_startcode(bc, nut->last_syncpoint_pos+1);

            if(tmp==0)

                return -1;

av_log(s, AV_LOG_DEBUG, "sync\n");

            nut->next_startcode= tmp;

        }

    }

}

void rgb8tobgr8(const uint8_t *src, uint8_t *dst, long src_size)

{

	long i;

	long num_pixels = src_size;

	for(i=0; i<num_pixels; i++)

	{

	    unsigned b,g,r;

	    register uint8_t rgb;

	    rgb = src[i];

	    r = (rgb&0x07);

	    g = (rgb&0x38)>>3;

	    b = (rgb&0xC0)>>6;

	    dst[i] = ((b<<1)&0x07) | ((g&0x07)<<3) | ((r&0x03)<<6);

	}

}

static av_always_inline void hl_decode_mb_internal(H264Context *h, int simple){

    MpegEncContext * const s = &h->s;

    const int mb_x= s->mb_x;

    const int mb_y= s->mb_y;

    const int mb_xy= h->mb_xy;

    const int mb_type= s->current_picture.mb_type[mb_xy];

    uint8_t  *dest_y, *dest_cb, *dest_cr;

    int linesize, uvlinesize /*dct_offset*/;

    int i;

    int *block_offset = &h->block_offset[0];

    const int transform_bypass = !simple && (s->qscale == 0 && h->sps.transform_bypass);

    const int is_h264 = simple || s->codec_id == CODEC_ID_H264;

    void (*idct_add)(uint8_t *dst, DCTELEM *block, int stride);

    void (*idct_dc_add)(uint8_t *dst, DCTELEM *block, int stride);



    dest_y  = s->current_picture.data[0] + (mb_x + mb_y * s->linesize  ) * 16;

    dest_cb = s->current_picture.data[1] + (mb_x + mb_y * s->uvlinesize) * 8;

    dest_cr = s->current_picture.data[2] + (mb_x + mb_y * s->uvlinesize) * 8;



    s->dsp.prefetch(dest_y + (s->mb_x&3)*4*s->linesize + 64, s->linesize, 4);

    s->dsp.prefetch(dest_cb + (s->mb_x&7)*s->uvlinesize + 64, dest_cr - dest_cb, 2);



    if (!simple && MB_FIELD) {

        linesize   = h->mb_linesize   = s->linesize * 2;

        uvlinesize = h->mb_uvlinesize = s->uvlinesize * 2;

        block_offset = &h->block_offset[24];

        if(mb_y&1){ //FIXME move out of this function?

            dest_y -= s->linesize*15;

            dest_cb-= s->uvlinesize*7;

            dest_cr-= s->uvlinesize*7;

        }

        if(FRAME_MBAFF) {

            int list;

            for(list=0; list<h->list_count; list++){

                if(!USES_LIST(mb_type, list))

                    continue;

                if(IS_16X16(mb_type)){

                    int8_t *ref = &h->ref_cache[list][scan8[0]];

                    fill_rectangle(ref, 4, 4, 8, (16+*ref)^(s->mb_y&1), 1);

                }else{

                    for(i=0; i<16; i+=4){

                        int ref = h->ref_cache[list][scan8[i]];

                        if(ref >= 0)

                            fill_rectangle(&h->ref_cache[list][scan8[i]], 2, 2, 8, (16+ref)^(s->mb_y&1), 1);

                    }

                }

            }

        }

    } else {

        linesize   = h->mb_linesize   = s->linesize;

        uvlinesize = h->mb_uvlinesize = s->uvlinesize;

//        dct_offset = s->linesize * 16;

    }



    if (!simple && IS_INTRA_PCM(mb_type)) {

        for (i=0; i<16; i++) {

            memcpy(dest_y + i*  linesize, h->mb       + i*8, 16);

        }

        for (i=0; i<8; i++) {

            memcpy(dest_cb+ i*uvlinesize, h->mb + 128 + i*4,  8);

            memcpy(dest_cr+ i*uvlinesize, h->mb + 160 + i*4,  8);

        }

    } else {

        if(IS_INTRA(mb_type)){

            if(h->deblocking_filter)

                xchg_mb_border(h, dest_y, dest_cb, dest_cr, linesize, uvlinesize, 1, simple);



            if(simple || !ENABLE_GRAY || !(s->flags&CODEC_FLAG_GRAY)){

                h->hpc.pred8x8[ h->chroma_pred_mode ](dest_cb, uvlinesize);

                h->hpc.pred8x8[ h->chroma_pred_mode ](dest_cr, uvlinesize);

            }



            if(IS_INTRA4x4(mb_type)){

                if(simple || !s->encoding){

                    if(IS_8x8DCT(mb_type)){

                        if(transform_bypass){

                            idct_dc_add =

                            idct_add    = s->dsp.add_pixels8;

                        }else if(IS_8x8DCT(mb_type)){

                            idct_dc_add = s->dsp.h264_idct8_dc_add;

                            idct_add    = s->dsp.h264_idct8_add;

                        }

                        for(i=0; i<16; i+=4){

                            uint8_t * const ptr= dest_y + block_offset[i];

                            const int dir= h->intra4x4_pred_mode_cache[ scan8[i] ];

                            if(transform_bypass && h->sps.profile_idc==244 && dir<=1){

                                h->hpc.pred8x8l_add[dir](ptr, h->mb + i*16, linesize);

                            }else{

                                const int nnz = h->non_zero_count_cache[ scan8[i] ];

                                h->hpc.pred8x8l[ dir ](ptr, (h->topleft_samples_available<<i)&0x8000,

                                                            (h->topright_samples_available<<i)&0x4000, linesize);

                                if(nnz){

                                    if(nnz == 1 && h->mb[i*16])

                                        idct_dc_add(ptr, h->mb + i*16, linesize);

                                    else

                                        idct_add   (ptr, h->mb + i*16, linesize);

                                }

                            }

                        }

                    }else{

                        if(transform_bypass){

                            idct_dc_add =

                            idct_add    = s->dsp.add_pixels4;

                        }else{

                            idct_dc_add = s->dsp.h264_idct_dc_add;

                            idct_add    = s->dsp.h264_idct_add;

                        }

                    for(i=0; i<16; i++){

                        uint8_t * const ptr= dest_y + block_offset[i];

                        const int dir= h->intra4x4_pred_mode_cache[ scan8[i] ];



                        if(transform_bypass && h->sps.profile_idc==244 && dir<=1){

                            h->hpc.pred4x4_add[dir](ptr, h->mb + i*16, linesize);

                        }else{

                            uint8_t *topright;

                            int nnz, tr;

                            if(dir == DIAG_DOWN_LEFT_PRED || dir == VERT_LEFT_PRED){

                                const int topright_avail= (h->topright_samples_available<<i)&0x8000;

                                assert(mb_y || linesize <= block_offset[i]);

                                if(!topright_avail){

                                    tr= ptr[3 - linesize]*0x01010101;

                                    topright= (uint8_t*) &tr;

                                }else

                                    topright= ptr + 4 - linesize;

                            }else

                                topright= NULL;



                            h->hpc.pred4x4[ dir ](ptr, topright, linesize);

                            nnz = h->non_zero_count_cache[ scan8[i] ];

                            if(nnz){

                                if(is_h264){

                                    if(nnz == 1 && h->mb[i*16])

                                        idct_dc_add(ptr, h->mb + i*16, linesize);

                                    else

                                        idct_add   (ptr, h->mb + i*16, linesize);

                                }else

                                    svq3_add_idct_c(ptr, h->mb + i*16, linesize, s->qscale, 0);

                            }

                        }

                    }

                    }

                }

            }else{

                h->hpc.pred16x16[ h->intra16x16_pred_mode ](dest_y , linesize);

                if(is_h264){

                    if(!transform_bypass)

                        h264_luma_dc_dequant_idct_c(h->mb, s->qscale, h->dequant4_coeff[0][s->qscale][0]);

                }else

                    svq3_luma_dc_dequant_idct_c(h->mb, s->qscale);

            }

            if(h->deblocking_filter)

                xchg_mb_border(h, dest_y, dest_cb, dest_cr, linesize, uvlinesize, 0, simple);

        }else if(is_h264){

            hl_motion(h, dest_y, dest_cb, dest_cr,

                      s->me.qpel_put, s->dsp.put_h264_chroma_pixels_tab,

                      s->me.qpel_avg, s->dsp.avg_h264_chroma_pixels_tab,

                      s->dsp.weight_h264_pixels_tab, s->dsp.biweight_h264_pixels_tab);

        }





        if(!IS_INTRA4x4(mb_type)){

            if(is_h264){

                if(IS_INTRA16x16(mb_type)){

                    if(transform_bypass){

                        if(h->sps.profile_idc==244 && (h->intra16x16_pred_mode==VERT_PRED8x8 || h->intra16x16_pred_mode==HOR_PRED8x8)){

                            h->hpc.pred16x16_add[h->intra16x16_pred_mode](dest_y, block_offset, h->mb, linesize);

                        }else{

                            for(i=0; i<16; i++){

                                if(h->non_zero_count_cache[ scan8[i] ] || h->mb[i*16])

                                    s->dsp.add_pixels4(dest_y + block_offset[i], h->mb + i*16, linesize);

                            }

                        }

                    }else{

                         s->dsp.h264_idct_add16intra(dest_y, block_offset, h->mb, linesize, h->non_zero_count_cache);

                    }

                }else if(h->cbp&15){

                    if(transform_bypass){

                        const int di = IS_8x8DCT(mb_type) ? 4 : 1;

                        idct_add= IS_8x8DCT(mb_type) ? s->dsp.add_pixels8 : s->dsp.add_pixels4;

                        for(i=0; i<16; i+=di){

                            if(h->non_zero_count_cache[ scan8[i] ]){

                                idct_add(dest_y + block_offset[i], h->mb + i*16, linesize);

                            }

                        }

                    }else{

                        if(IS_8x8DCT(mb_type)){

                            s->dsp.h264_idct8_add4(dest_y, block_offset, h->mb, linesize, h->non_zero_count_cache);

                        }else{

                            s->dsp.h264_idct_add16(dest_y, block_offset, h->mb, linesize, h->non_zero_count_cache);

                        }

                    }

                }

            }else{

                for(i=0; i<16; i++){

                    if(h->non_zero_count_cache[ scan8[i] ] || h->mb[i*16]){ //FIXME benchmark weird rule, & below

                        uint8_t * const ptr= dest_y + block_offset[i];

                        svq3_add_idct_c(ptr, h->mb + i*16, linesize, s->qscale, IS_INTRA(mb_type) ? 1 : 0);

                    }

                }

            }

        }



        if((simple || !ENABLE_GRAY || !(s->flags&CODEC_FLAG_GRAY)) && (h->cbp&0x30)){

            uint8_t *dest[2] = {dest_cb, dest_cr};

            if(transform_bypass){

                idct_add = idct_dc_add = s->dsp.add_pixels4;

            }else{

                idct_add = s->dsp.h264_idct_add;

                idct_dc_add = s->dsp.h264_idct_dc_add;

                chroma_dc_dequant_idct_c(h->mb + 16*16, h->chroma_qp[0], h->dequant4_coeff[IS_INTRA(mb_type) ? 1:4][h->chroma_qp[0]][0]);

                chroma_dc_dequant_idct_c(h->mb + 16*16+4*16, h->chroma_qp[1], h->dequant4_coeff[IS_INTRA(mb_type) ? 2:5][h->chroma_qp[1]][0]);

            }

            if(is_h264){

                if(transform_bypass && IS_INTRA(mb_type) && h->sps.profile_idc==244 && (h->chroma_pred_mode==VERT_PRED8x8 || h->chroma_pred_mode==HOR_PRED8x8)){

                    h->hpc.pred8x8_add[h->chroma_pred_mode](dest[0], block_offset + 16, h->mb + 16*16, uvlinesize);

                    h->hpc.pred8x8_add[h->chroma_pred_mode](dest[1], block_offset + 20, h->mb + 20*16, uvlinesize);

                }else{

                    for(i=16; i<16+8; i++){

                        if(h->non_zero_count_cache[ scan8[i] ])

                            idct_add   (dest[(i&4)>>2] + block_offset[i], h->mb + i*16, uvlinesize);

                        else if(h->mb[i*16])

                            idct_dc_add(dest[(i&4)>>2] + block_offset[i], h->mb + i*16, uvlinesize);

                    }

                }

            }else{

                for(i=16; i<16+8; i++){

                    if(h->non_zero_count_cache[ scan8[i] ] || h->mb[i*16]){

                        uint8_t * const ptr= dest[(i&4)>>2] + block_offset[i];

                        svq3_add_idct_c(ptr, h->mb + i*16, uvlinesize, chroma_qp[s->qscale + 12] - 12, 2);

                    }

                }

            }

        }

    }

    if(h->deblocking_filter) {

        backup_mb_border(h, dest_y, dest_cb, dest_cr, linesize, uvlinesize, simple);

        fill_caches(h, mb_type, 1); //FIXME don't fill stuff which isn't used by filter_mb

        h->chroma_qp[0] = get_chroma_qp(h, 0, s->current_picture.qscale_table[mb_xy]);

        h->chroma_qp[1] = get_chroma_qp(h, 1, s->current_picture.qscale_table[mb_xy]);

        if (!simple && FRAME_MBAFF) {

            filter_mb     (h, mb_x, mb_y, dest_y, dest_cb, dest_cr, linesize, uvlinesize);

        } else {

            filter_mb_fast(h, mb_x, mb_y, dest_y, dest_cb, dest_cr, linesize, uvlinesize);

        }

    }

}

static void vmstate_subsection_save(QEMUFile *f, const VMStateDescription *vmsd,

                                    void *opaque)

{

    const VMStateSubsection *sub = vmsd->subsections;



    while (sub && sub->needed) {

        if (sub->needed(opaque)) {

            const VMStateDescription *vmsd = sub->vmsd;

            uint8_t len;



            qemu_put_byte(f, QEMU_VM_SUBSECTION);

            len = strlen(vmsd->name);

            qemu_put_byte(f, len);

            qemu_put_buffer(f, (uint8_t *)vmsd->name, len);

            qemu_put_be32(f, vmsd->version_id);

            assert(!vmsd->subsections);

            vmstate_save_state(f, vmsd, opaque);

        }

        sub++;

    }

}

static void sbr_hf_g_filt_c(int (*Y)[2], const int (*X_high)[40][2],

                          const SoftFloat *g_filt, int m_max, intptr_t ixh)

{

    int m;

    int64_t accu;



    for (m = 0; m < m_max; m++) {

        int64_t r = 1LL << (22-g_filt[m].exp);

        accu = (int64_t)X_high[m][ixh][0] * ((g_filt[m].mant + 0x40)>>7);

        Y[m][0] = (int)((accu + r) >> (23-g_filt[m].exp));



        accu = (int64_t)X_high[m][ixh][1] * ((g_filt[m].mant + 0x40)>>7);

        Y[m][1] = (int)((accu + r) >> (23-g_filt[m].exp));

    }

}

static int output_frame(AVFilterLink *outlink, int need_request)

{

    AVFilterContext *ctx = outlink->src;

    MixContext      *s = ctx->priv;

    AVFrame *out_buf, *in_buf;

    int nb_samples, ns, ret, i;



    ret = calc_active_inputs(s);

    if (ret < 0)

        return ret;



    if (s->input_state[0] & INPUT_ON) {

        /* first input live: use the corresponding frame size */

        nb_samples = frame_list_next_frame_size(s->frame_list);

        for (i = 1; i < s->nb_inputs; i++) {

            if (s->input_state[i] & INPUT_ON) {

                ns = av_audio_fifo_size(s->fifos[i]);

                if (ns < nb_samples) {

                    if (!(s->input_state[i] & INPUT_EOF))

                        /* unclosed input with not enough samples */

                        return need_request ? ff_request_frame(ctx->inputs[i]) : 0;

                    /* closed input to drain */

                    nb_samples = ns;

                }

            }

        }

    } else {

        /* first input closed: use the available samples */

        nb_samples = INT_MAX;

        for (i = 1; i < s->nb_inputs; i++) {

            if (s->input_state[i] & INPUT_ON) {

                ns = av_audio_fifo_size(s->fifos[i]);

                nb_samples = FFMIN(nb_samples, ns);

            }

        }

        if (nb_samples == INT_MAX)

            return AVERROR_EOF;

    }



    s->next_pts = frame_list_next_pts(s->frame_list);

    frame_list_remove_samples(s->frame_list, nb_samples);



    calculate_scales(s, nb_samples);



    if (nb_samples == 0)

        return 0;



    out_buf = ff_get_audio_buffer(outlink, nb_samples);

    if (!out_buf)

        return AVERROR(ENOMEM);



    in_buf = ff_get_audio_buffer(outlink, nb_samples);

    if (!in_buf) {

        av_frame_free(&out_buf);

        return AVERROR(ENOMEM);

    }



    for (i = 0; i < s->nb_inputs; i++) {

        if (s->input_state[i] & INPUT_ON) {

            int planes, plane_size, p;



            av_audio_fifo_read(s->fifos[i], (void **)in_buf->extended_data,

                               nb_samples);



            planes     = s->planar ? s->nb_channels : 1;

            plane_size = nb_samples * (s->planar ? 1 : s->nb_channels);

            plane_size = FFALIGN(plane_size, 16);



            if (out_buf->format == AV_SAMPLE_FMT_FLT ||

                out_buf->format == AV_SAMPLE_FMT_FLTP) {

                for (p = 0; p < planes; p++) {

                    s->fdsp->vector_fmac_scalar((float *)out_buf->extended_data[p],

                                                (float *) in_buf->extended_data[p],

                                                s->input_scale[i], plane_size);

                }

            } else {

                for (p = 0; p < planes; p++) {

                    s->fdsp->vector_dmac_scalar((double *)out_buf->extended_data[p],

                                                (double *) in_buf->extended_data[p],

                                                s->input_scale[i], plane_size);

                }

            }

        }

    }

    av_frame_free(&in_buf);



    out_buf->pts = s->next_pts;

    if (s->next_pts != AV_NOPTS_VALUE)

        s->next_pts += nb_samples;



    return ff_filter_frame(outlink, out_buf);

}

