static int qemu_gluster_open(BlockDriverState *bs,  QDict *options,

                             int bdrv_flags, Error **errp)

{

    BDRVGlusterState *s = bs->opaque;

    int open_flags = 0;

    int ret = 0;

    BlockdevOptionsGluster *gconf = NULL;

    QemuOpts *opts;

    Error *local_err = NULL;

    const char *filename;



    opts = qemu_opts_create(&runtime_opts, NULL, 0, &error_abort);

    qemu_opts_absorb_qdict(opts, options, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        ret = -EINVAL;

        goto out;

    }



    filename = qemu_opt_get(opts, GLUSTER_OPT_FILENAME);



    s->debug_level = qemu_opt_get_number(opts, GLUSTER_OPT_DEBUG,

                                         GLUSTER_DEBUG_DEFAULT);

    if (s->debug_level < 0) {

        s->debug_level = 0;

    } else if (s->debug_level > GLUSTER_DEBUG_MAX) {

        s->debug_level = GLUSTER_DEBUG_MAX;

    }



    gconf = g_new0(BlockdevOptionsGluster, 1);

    gconf->debug_level = s->debug_level;

    gconf->has_debug_level = true;

    s->glfs = qemu_gluster_init(gconf, filename, options, errp);

    if (!s->glfs) {

        ret = -errno;

        goto out;

    }



#ifdef CONFIG_GLUSTERFS_XLATOR_OPT

    /* Without this, if fsync fails for a recoverable reason (for instance,

     * ENOSPC), gluster will dump its cache, preventing retries.  This means

     * almost certain data loss.  Not all gluster versions support the

     * 'resync-failed-syncs-after-fsync' key value, but there is no way to

     * discover during runtime if it is supported (this api returns success for

     * unknown key/value pairs) */

    ret = glfs_set_xlator_option(s->glfs, "*-write-behind",

                                          "resync-failed-syncs-after-fsync",

                                          "on");

    if (ret < 0) {

        error_setg_errno(errp, errno, "Unable to set xlator key/value pair");

        ret = -errno;

        goto out;

    }

#endif



    qemu_gluster_parse_flags(bdrv_flags, &open_flags);



    s->fd = glfs_open(s->glfs, gconf->path, open_flags);

    if (!s->fd) {

        ret = -errno;

    }



    s->supports_seek_data = qemu_gluster_test_seek(s->fd);



out:

    qemu_opts_del(opts);

    qapi_free_BlockdevOptionsGluster(gconf);

    if (!ret) {

        return ret;

    }

    if (s->fd) {

        glfs_close(s->fd);

    }

    if (s->glfs) {

        glfs_fini(s->glfs);

    }

    return ret;

}

static int kmvc_decode_intra_8x8(KmvcContext * ctx, int w, int h)

{

    BitBuf bb;

    int res, val;

    int i, j;

    int bx, by;

    int l0x, l1x, l0y, l1y;

    int mx, my;



    kmvc_init_getbits(bb, &ctx->g);



    for (by = 0; by < h; by += 8)

        for (bx = 0; bx < w; bx += 8) {

            if (!bytestream2_get_bytes_left(&ctx->g)) {

                av_log(ctx->avctx, AV_LOG_ERROR, "Data overrun\n");

                return AVERROR_INVALIDDATA;

            }

            kmvc_getbit(bb, &ctx->g, res);

            if (!res) {         // fill whole 8x8 block

                val = bytestream2_get_byte(&ctx->g);

                for (i = 0; i < 64; i++)

                    BLK(ctx->cur, bx + (i & 0x7), by + (i >> 3)) = val;

            } else {            // handle four 4x4 subblocks

                for (i = 0; i < 4; i++) {

                    l0x = bx + (i & 1) * 4;

                    l0y = by + (i & 2) * 2;

                    kmvc_getbit(bb, &ctx->g, res);

                    if (!res) {

                        kmvc_getbit(bb, &ctx->g, res);

                        if (!res) {     // fill whole 4x4 block

                            val = bytestream2_get_byte(&ctx->g);

                            for (j = 0; j < 16; j++)

                                BLK(ctx->cur, l0x + (j & 3), l0y + (j >> 2)) = val;

                        } else {        // copy block from already decoded place

                            val = bytestream2_get_byte(&ctx->g);

                            mx = val & 0xF;

                            my = val >> 4;

                            if ((l0x-mx) + 320*(l0y-my) < 0 || (l0x-mx) + 320*(l0y-my) > 316*196) {

                                av_log(ctx->avctx, AV_LOG_ERROR, "Invalid MV\n");

                                return AVERROR_INVALIDDATA;

                            }

                            for (j = 0; j < 16; j++)

                                BLK(ctx->cur, l0x + (j & 3), l0y + (j >> 2)) =

                                    BLK(ctx->cur, l0x + (j & 3) - mx, l0y + (j >> 2) - my);

                        }

                    } else {    // descend to 2x2 sub-sub-blocks

                        for (j = 0; j < 4; j++) {

                            l1x = l0x + (j & 1) * 2;

                            l1y = l0y + (j & 2);

                            kmvc_getbit(bb, &ctx->g, res);

                            if (!res) {

                                kmvc_getbit(bb, &ctx->g, res);

                                if (!res) {     // fill whole 2x2 block

                                    val = bytestream2_get_byte(&ctx->g);

                                    BLK(ctx->cur, l1x, l1y) = val;

                                    BLK(ctx->cur, l1x + 1, l1y) = val;

                                    BLK(ctx->cur, l1x, l1y + 1) = val;

                                    BLK(ctx->cur, l1x + 1, l1y + 1) = val;

                                } else {        // copy block from already decoded place

                                    val = bytestream2_get_byte(&ctx->g);

                                    mx = val & 0xF;

                                    my = val >> 4;

                                    if ((l1x-mx) + 320*(l1y-my) < 0 || (l1x-mx) + 320*(l1y-my) > 318*198) {

                                        av_log(ctx->avctx, AV_LOG_ERROR, "Invalid MV\n");

                                        return AVERROR_INVALIDDATA;

                                    }

                                    BLK(ctx->cur, l1x, l1y) = BLK(ctx->cur, l1x - mx, l1y - my);

                                    BLK(ctx->cur, l1x + 1, l1y) =

                                        BLK(ctx->cur, l1x + 1 - mx, l1y - my);

                                    BLK(ctx->cur, l1x, l1y + 1) =

                                        BLK(ctx->cur, l1x - mx, l1y + 1 - my);

                                    BLK(ctx->cur, l1x + 1, l1y + 1) =

                                        BLK(ctx->cur, l1x + 1 - mx, l1y + 1 - my);

                                }

                            } else {    // read values for block

                                BLK(ctx->cur, l1x, l1y) = bytestream2_get_byte(&ctx->g);

                                BLK(ctx->cur, l1x + 1, l1y) = bytestream2_get_byte(&ctx->g);

                                BLK(ctx->cur, l1x, l1y + 1) = bytestream2_get_byte(&ctx->g);

                                BLK(ctx->cur, l1x + 1, l1y + 1) = bytestream2_get_byte(&ctx->g);

                            }

                        }

                    }

                }

            }

        }



    return 0;

}

