static int ram_save_init_globals(void)

{

    int64_t ram_bitmap_pages; /* Size of bitmap in pages, including gaps */



    dirty_rate_high_cnt = 0;

    bitmap_sync_count = 0;

    migration_bitmap_sync_init();

    qemu_mutex_init(&migration_bitmap_mutex);



    if (migrate_use_xbzrle()) {

        XBZRLE_cache_lock();

        ZERO_TARGET_PAGE = g_malloc0(TARGET_PAGE_SIZE);

        XBZRLE.cache = cache_init(migrate_xbzrle_cache_size() /

                                  TARGET_PAGE_SIZE,

                                  TARGET_PAGE_SIZE);

        if (!XBZRLE.cache) {

            XBZRLE_cache_unlock();

            error_report("Error creating cache");

            return -1;

        }

        XBZRLE_cache_unlock();



        /* We prefer not to abort if there is no memory */

        XBZRLE.encoded_buf = g_try_malloc0(TARGET_PAGE_SIZE);

        if (!XBZRLE.encoded_buf) {

            error_report("Error allocating encoded_buf");

            return -1;

        }



        XBZRLE.current_buf = g_try_malloc(TARGET_PAGE_SIZE);

        if (!XBZRLE.current_buf) {

            error_report("Error allocating current_buf");

            g_free(XBZRLE.encoded_buf);

            XBZRLE.encoded_buf = NULL;

            return -1;

        }



        acct_clear();

    }



    /* For memory_global_dirty_log_start below.  */

    qemu_mutex_lock_iothread();



    qemu_mutex_lock_ramlist();

    rcu_read_lock();

    bytes_transferred = 0;

    reset_ram_globals();



    ram_bitmap_pages = last_ram_offset() >> TARGET_PAGE_BITS;

    migration_bitmap_rcu = g_new0(struct BitmapRcu, 1);

    migration_bitmap_rcu->bmap = bitmap_new(ram_bitmap_pages);

    bitmap_set(migration_bitmap_rcu->bmap, 0, ram_bitmap_pages);



    if (migrate_postcopy_ram()) {

        migration_bitmap_rcu->unsentmap = bitmap_new(ram_bitmap_pages);

        bitmap_set(migration_bitmap_rcu->unsentmap, 0, ram_bitmap_pages);

    }



    /*

     * Count the total number of pages used by ram blocks not including any

     * gaps due to alignment or unplugs.

     */

    migration_dirty_pages = ram_bytes_total() >> TARGET_PAGE_BITS;



    memory_global_dirty_log_start();

    migration_bitmap_sync();

    qemu_mutex_unlock_ramlist();

    qemu_mutex_unlock_iothread();

    rcu_read_unlock();



    return 0;

}

static uint16_t nvme_dma_read_prp(NvmeCtrl *n, uint8_t *ptr, uint32_t len,

    uint64_t prp1, uint64_t prp2)

{

    QEMUSGList qsg;

    QEMUIOVector iov;

    uint16_t status = NVME_SUCCESS;



    if (nvme_map_prp(&qsg, &iov, prp1, prp2, len, n)) {

        return NVME_INVALID_FIELD | NVME_DNR;

    }

    if (qsg.nsg > 0) {

        if (dma_buf_read(ptr, len, &qsg)) {

            status = NVME_INVALID_FIELD | NVME_DNR;

        }

        qemu_sglist_destroy(&qsg);

    } else {

        if (qemu_iovec_to_buf(&iov, 0, ptr, len) != len) {

            status = NVME_INVALID_FIELD | NVME_DNR;

        }

        qemu_iovec_destroy(&iov);

    }

    return status;

}

static int asf_read_metadata_obj(AVFormatContext *s, const GUIDParseTable *g)

{

    ASFContext *asf   = s->priv_data;

    AVIOContext *pb   = s->pb;

    uint64_t size     = avio_rl64(pb);

    uint16_t nb_recs  = avio_rl16(pb); // number of records in the Description Records list

    int i, ret;



    for (i = 0; i < nb_recs; i++) {

        uint16_t name_len, buflen, type, val_len, st_num;

        uint8_t *name = NULL;



        avio_skip(pb, 2); // skip reserved field

        st_num   = avio_rl16(pb);

        name_len = avio_rl16(pb);

        buflen   = 2 * name_len + 1;

        if (!name_len)

            break;

        type     = avio_rl16(pb);

        val_len  = avio_rl32(pb);

        name     = av_malloc(name_len);

        if (!name)

            return AVERROR(ENOMEM);

        avio_get_str16le(pb, name_len, name,

                         buflen);



        if (!strcmp(name, "AspectRatioX") || !strcmp(name, "AspectRatioY")) {

            asf_store_aspect_ratio(s, st_num, name);

        } else {

            if (st_num < ASF_MAX_STREAMS) {

                if ((ret = process_metadata(s, name, name_len, val_len, type,

                                            &asf->asf_sd[st_num].asf_met)) < 0)

                    break;

            } else

                av_freep(&name);

        }

    }



    align_position(pb, asf->offset, size);

    return 0;

}

static int check_refcounts_l1(BlockDriverState *bs,

                              BdrvCheckResult *res,

                              uint16_t *refcount_table,

                              int64_t refcount_table_size,

                              int64_t l1_table_offset, int l1_size,

                              int flags)

{

    BDRVQcowState *s = bs->opaque;

    uint64_t *l1_table, l2_offset, l1_size2;

    int i, ret;



    l1_size2 = l1_size * sizeof(uint64_t);



    /* Mark L1 table as used */

    inc_refcounts(bs, res, refcount_table, refcount_table_size,

        l1_table_offset, l1_size2);



    /* Read L1 table entries from disk */

    if (l1_size2 == 0) {

        l1_table = NULL;

    } else {

        l1_table = g_try_malloc(l1_size2);

        if (l1_table == NULL) {

            ret = -ENOMEM;

            goto fail;

        }

        if (bdrv_pread(bs->file, l1_table_offset,

                       l1_table, l1_size2) != l1_size2)

            goto fail;

        for(i = 0;i < l1_size; i++)

            be64_to_cpus(&l1_table[i]);

    }



    /* Do the actual checks */

    for(i = 0; i < l1_size; i++) {

        l2_offset = l1_table[i];

        if (l2_offset) {

            /* Mark L2 table as used */

            l2_offset &= L1E_OFFSET_MASK;

            inc_refcounts(bs, res, refcount_table, refcount_table_size,

                l2_offset, s->cluster_size);



            /* L2 tables are cluster aligned */

            if (offset_into_cluster(s, l2_offset)) {

                fprintf(stderr, "ERROR l2_offset=%" PRIx64 ": Table is not "

                    "cluster aligned; L1 entry corrupted\n", l2_offset);

                res->corruptions++;

            }



            /* Process and check L2 entries */

            ret = check_refcounts_l2(bs, res, refcount_table,

                                     refcount_table_size, l2_offset, flags);

            if (ret < 0) {

                goto fail;

            }

        }

    }

    g_free(l1_table);

    return 0;



fail:

    fprintf(stderr, "ERROR: I/O error in check_refcounts_l1\n");

    res->check_errors++;

    g_free(l1_table);

    return -EIO;

}

