static void strongarm_gpio_write(void *opaque, hwaddr offset,

                                 uint64_t value, unsigned size)

{

    StrongARMGPIOInfo *s = opaque;



    switch (offset) {

    case GPDR:        /* GPIO Pin-Direction registers */

        s->dir = value;

        strongarm_gpio_handler_update(s);

        break;



    case GPSR:        /* GPIO Pin-Output Set registers */

        s->olevel |= value;

        strongarm_gpio_handler_update(s);

        s->gpsr = value;

        break;



    case GPCR:        /* GPIO Pin-Output Clear registers */

        s->olevel &= ~value;

        strongarm_gpio_handler_update(s);

        break;



    case GRER:        /* GPIO Rising-Edge Detect Enable registers */

        s->rising = value;

        break;



    case GFER:        /* GPIO Falling-Edge Detect Enable registers */

        s->falling = value;

        break;



    case GAFR:        /* GPIO Alternate Function registers */

        s->gafr = value;

        break;



    case GEDR:        /* GPIO Edge Detect Status registers */

        s->status &= ~value;

        strongarm_gpio_irq_update(s);

        break;



    default:

        printf("%s: Bad offset 0x" TARGET_FMT_plx "\n", __func__, offset);

    }

}

static void gen_bitops (DisasContext *ctx, uint32_t opc, int rt,

                        int rs, int lsb, int msb)

{

    TCGv t0 = tcg_temp_new();

    TCGv t1 = tcg_temp_new();



    gen_load_gpr(t1, rs);

    switch (opc) {

    case OPC_EXT:

        if (lsb + msb > 31)

            goto fail;

        tcg_gen_shri_tl(t0, t1, lsb);

        if (msb != 31) {

            tcg_gen_andi_tl(t0, t0, (1 << (msb + 1)) - 1);

        } else {

            tcg_gen_ext32s_tl(t0, t0);

        }

        break;

#if defined(TARGET_MIPS64)

    case OPC_DEXTM:

        tcg_gen_shri_tl(t0, t1, lsb);

        if (msb != 31) {

            tcg_gen_andi_tl(t0, t0, (1ULL << (msb + 1 + 32)) - 1);

        }

        break;

    case OPC_DEXTU:

        tcg_gen_shri_tl(t0, t1, lsb + 32);

        tcg_gen_andi_tl(t0, t0, (1ULL << (msb + 1)) - 1);

        break;

    case OPC_DEXT:

        tcg_gen_shri_tl(t0, t1, lsb);

        tcg_gen_andi_tl(t0, t0, (1ULL << (msb + 1)) - 1);

        break;

#endif

    case OPC_INS:

        if (lsb > msb)

            goto fail;

        gen_load_gpr(t0, rt);

        tcg_gen_deposit_tl(t0, t0, t1, lsb, msb - lsb + 1);

        tcg_gen_ext32s_tl(t0, t0);

        break;

#if defined(TARGET_MIPS64)

    case OPC_DINSM:

        gen_load_gpr(t0, rt);

        tcg_gen_deposit_tl(t0, t0, t1, lsb, msb + 32 - lsb + 1);

        break;

    case OPC_DINSU:

        gen_load_gpr(t0, rt);

        tcg_gen_deposit_tl(t0, t0, t1, lsb + 32, msb - lsb + 1);

        break;

    case OPC_DINS:

        gen_load_gpr(t0, rt);

        tcg_gen_deposit_tl(t0, t0, t1, lsb, msb - lsb + 1);

        break;

#endif

    default:

fail:

        MIPS_INVAL("bitops");

        generate_exception(ctx, EXCP_RI);

        tcg_temp_free(t0);

        tcg_temp_free(t1);

        return;

    }

    gen_store_gpr(t0, rt);

    tcg_temp_free(t0);

    tcg_temp_free(t1);

}

static int vhost_scsi_exit(DeviceState *qdev)

{

    VirtIODevice *vdev = VIRTIO_DEVICE(qdev);

    VHostSCSI *s = VHOST_SCSI(qdev);

    VirtIOSCSICommon *vs = VIRTIO_SCSI_COMMON(qdev);



    migrate_del_blocker(s->migration_blocker);

    error_free(s->migration_blocker);



    /* This will stop vhost backend. */

    vhost_scsi_set_status(vdev, 0);



    g_free(s->dev.vqs);

    return virtio_scsi_common_exit(vs);

}

static void dec_wcsr(DisasContext *dc)

{

    int no;



    LOG_DIS("wcsr r%d, %d\n", dc->r1, dc->csr);



    switch (dc->csr) {

    case CSR_IE:

        tcg_gen_mov_tl(cpu_ie, cpu_R[dc->r1]);

        tcg_gen_movi_tl(cpu_pc, dc->pc + 4);

        dc->is_jmp = DISAS_UPDATE;

        break;

    case CSR_IM:

        /* mark as an io operation because it could cause an interrupt */

        if (use_icount) {

            gen_io_start();

        }

        gen_helper_wcsr_im(cpu_env, cpu_R[dc->r1]);

        tcg_gen_movi_tl(cpu_pc, dc->pc + 4);

        if (use_icount) {

            gen_io_end();

        }

        dc->is_jmp = DISAS_UPDATE;

        break;

    case CSR_IP:

        /* mark as an io operation because it could cause an interrupt */

        if (use_icount) {

            gen_io_start();

        }

        gen_helper_wcsr_ip(cpu_env, cpu_R[dc->r1]);

        tcg_gen_movi_tl(cpu_pc, dc->pc + 4);

        if (use_icount) {

            gen_io_end();

        }

        dc->is_jmp = DISAS_UPDATE;

        break;

    case CSR_ICC:

        /* TODO */

        break;

    case CSR_DCC:

        /* TODO */

        break;

    case CSR_EBA:

        tcg_gen_mov_tl(cpu_eba, cpu_R[dc->r1]);

        break;

    case CSR_DEBA:

        tcg_gen_mov_tl(cpu_deba, cpu_R[dc->r1]);

        break;

    case CSR_JTX:

        gen_helper_wcsr_jtx(cpu_env, cpu_R[dc->r1]);

        break;

    case CSR_JRX:

        gen_helper_wcsr_jrx(cpu_env, cpu_R[dc->r1]);

        break;

    case CSR_DC:

        tcg_gen_mov_tl(cpu_dc, cpu_R[dc->r1]);

        break;

    case CSR_BP0:

    case CSR_BP1:

    case CSR_BP2:

    case CSR_BP3:

        no = dc->csr - CSR_BP0;

        if (dc->env->num_bps <= no) {

            cpu_abort(dc->env, "breakpoint #%i is not available\n", no);

        }

        tcg_gen_mov_tl(cpu_bp[no], cpu_R[dc->r1]);

        break;

    case CSR_WP0:

    case CSR_WP1:

    case CSR_WP2:

    case CSR_WP3:

        no = dc->csr - CSR_WP0;

        if (dc->env->num_wps <= no) {

            cpu_abort(dc->env, "watchpoint #%i is not available\n", no);

        }

        tcg_gen_mov_tl(cpu_wp[no], cpu_R[dc->r1]);

        break;

    case CSR_CC:

    case CSR_CFG:

        cpu_abort(dc->env, "invalid write access csr=%x\n", dc->csr);

        break;

    default:

        cpu_abort(dc->env, "write_csr unknown csr=%x\n", dc->csr);

        break;

    }

}

void pmac_format_nvram_partition (MacIONVRAMState *nvr, int len)

{

    unsigned int i;

    uint32_t start = 0, end;

    struct OpenBIOS_nvpart_v1 *part_header;



    // OpenBIOS nvram variables

    // Variable partition

    part_header = (struct OpenBIOS_nvpart_v1 *)nvr->data;

    part_header->signature = OPENBIOS_PART_SYSTEM;

    pstrcpy(part_header->name, sizeof(part_header->name), "system");



    end = start + sizeof(struct OpenBIOS_nvpart_v1);

    for (i = 0; i < nb_prom_envs; i++)

        end = OpenBIOS_set_var(nvr->data, end, prom_envs[i]);



    // End marker

    nvr->data[end++] = '\0';



    end = start + ((end - start + 15) & ~15);

    /* XXX: OpenBIOS is not able to grow up a partition. Leave some space for

       new variables. */

    if (end < DEF_SYSTEM_SIZE)

        end = DEF_SYSTEM_SIZE;

    OpenBIOS_finish_partition(part_header, end - start);



    // free partition

    start = end;

    part_header = (struct OpenBIOS_nvpart_v1 *)&nvr->data[start];

    part_header->signature = OPENBIOS_PART_FREE;

    pstrcpy(part_header->name, sizeof(part_header->name), "free");



    end = len;

    OpenBIOS_finish_partition(part_header, end - start);

}

static void gen_slq(DisasContext *ctx)

{

    int l1 = gen_new_label();

    TCGv t0 = tcg_temp_new();

    TCGv t1 = tcg_temp_new();

    tcg_gen_andi_tl(t1, cpu_gpr[rB(ctx->opcode)], 0x1F);

    tcg_gen_shl_tl(t0, cpu_gpr[rS(ctx->opcode)], t1);

    tcg_gen_subfi_tl(t1, 32, t1);

    tcg_gen_shr_tl(t1, cpu_gpr[rS(ctx->opcode)], t1);

    tcg_gen_or_tl(t1, t0, t1);

    gen_store_spr(SPR_MQ, t1);

    tcg_gen_andi_tl(t1, cpu_gpr[rB(ctx->opcode)], 0x20);

    tcg_gen_mov_tl(cpu_gpr[rA(ctx->opcode)], t0);

    tcg_gen_brcondi_tl(TCG_COND_EQ, t1, 0, l1);

    tcg_gen_movi_tl(cpu_gpr[rA(ctx->opcode)], 0);

    gen_set_label(l1);

    tcg_temp_free(t0);

    tcg_temp_free(t1);

    if (unlikely(Rc(ctx->opcode) != 0))

        gen_set_Rc0(ctx, cpu_gpr[rA(ctx->opcode)]);

}

vmxnet3_pop_rxc_descr(VMXNET3State *s, int qidx, uint32_t *descr_gen)

{

    uint8_t ring_gen;

    struct Vmxnet3_RxCompDesc rxcd;



    hwaddr daddr =

        vmxnet3_ring_curr_cell_pa(&s->rxq_descr[qidx].comp_ring);



    pci_dma_read(PCI_DEVICE(s), daddr,

                 &rxcd, sizeof(struct Vmxnet3_RxCompDesc));



    ring_gen = vmxnet3_ring_curr_gen(&s->rxq_descr[qidx].comp_ring);



    if (rxcd.gen != ring_gen) {

        *descr_gen = ring_gen;

        vmxnet3_inc_rx_completion_counter(s, qidx);

        return daddr;

    }



    return 0;

}

build_madt(GArray *table_data, GArray *linker, AcpiCpuInfo *cpu)

{

    PCMachineState *pcms = PC_MACHINE(qdev_get_machine());

    int madt_start = table_data->len;



    AcpiMultipleApicTable *madt;

    AcpiMadtIoApic *io_apic;

    AcpiMadtIntsrcovr *intsrcovr;

    AcpiMadtLocalNmi *local_nmi;

    int i;



    madt = acpi_data_push(table_data, sizeof *madt);

    madt->local_apic_address = cpu_to_le32(APIC_DEFAULT_ADDRESS);

    madt->flags = cpu_to_le32(1);



    for (i = 0; i < pcms->apic_id_limit; i++) {

        AcpiMadtProcessorApic *apic = acpi_data_push(table_data, sizeof *apic);

        apic->type = ACPI_APIC_PROCESSOR;

        apic->length = sizeof(*apic);

        apic->processor_id = i;

        apic->local_apic_id = i;

        if (test_bit(i, cpu->found_cpus)) {

            apic->flags = cpu_to_le32(1);

        } else {

            apic->flags = cpu_to_le32(0);

        }

    }

    io_apic = acpi_data_push(table_data, sizeof *io_apic);

    io_apic->type = ACPI_APIC_IO;

    io_apic->length = sizeof(*io_apic);

#define ACPI_BUILD_IOAPIC_ID 0x0

    io_apic->io_apic_id = ACPI_BUILD_IOAPIC_ID;

    io_apic->address = cpu_to_le32(IO_APIC_DEFAULT_ADDRESS);

    io_apic->interrupt = cpu_to_le32(0);



    if (pcms->apic_xrupt_override) {

        intsrcovr = acpi_data_push(table_data, sizeof *intsrcovr);

        intsrcovr->type   = ACPI_APIC_XRUPT_OVERRIDE;

        intsrcovr->length = sizeof(*intsrcovr);

        intsrcovr->source = 0;

        intsrcovr->gsi    = cpu_to_le32(2);

        intsrcovr->flags  = cpu_to_le16(0); /* conforms to bus specifications */

    }

    for (i = 1; i < 16; i++) {

#define ACPI_BUILD_PCI_IRQS ((1<<5) | (1<<9) | (1<<10) | (1<<11))

        if (!(ACPI_BUILD_PCI_IRQS & (1 << i))) {

            /* No need for a INT source override structure. */

            continue;

        }

        intsrcovr = acpi_data_push(table_data, sizeof *intsrcovr);

        intsrcovr->type   = ACPI_APIC_XRUPT_OVERRIDE;

        intsrcovr->length = sizeof(*intsrcovr);

        intsrcovr->source = i;

        intsrcovr->gsi    = cpu_to_le32(i);

        intsrcovr->flags  = cpu_to_le16(0xd); /* active high, level triggered */

    }



    local_nmi = acpi_data_push(table_data, sizeof *local_nmi);

    local_nmi->type         = ACPI_APIC_LOCAL_NMI;

    local_nmi->length       = sizeof(*local_nmi);

    local_nmi->processor_id = 0xff; /* all processors */

    local_nmi->flags        = cpu_to_le16(0);

    local_nmi->lint         = 1; /* ACPI_LINT1 */



    build_header(linker, table_data,

                 (void *)(table_data->data + madt_start), "APIC",

                 table_data->len - madt_start, 1, NULL);

}

matroska_parse_blockgroup (MatroskaDemuxContext *matroska,

                           uint64_t              cluster_time)

{

    int res = 0;

    uint32_t id;

    AVPacket *pkt = NULL;

    int is_keyframe = PKT_FLAG_KEY, last_num_packets = matroska->num_packets;

    uint64_t duration = AV_NOPTS_VALUE;

    int track = -1;

    uint8_t *data;

    int size = 0;

    int64_t pos = 0;



    av_log(matroska->ctx, AV_LOG_DEBUG, "parsing blockgroup...\n");



    while (res == 0) {

        if (!(id = ebml_peek_id(matroska, &matroska->level_up))) {

            res = AVERROR_IO;

            break;

        } else if (matroska->level_up) {

            matroska->level_up--;

            break;

        }



        switch (id) {

            /* one block inside the group. Note, block parsing is one

             * of the harder things, so this code is a bit complicated.

             * See http://www.matroska.org/ for documentation. */

            case MATROSKA_ID_BLOCK: {

                pos = url_ftell(&matroska->ctx->pb);

                res = ebml_read_binary(matroska, &id, &data, &size);

                break;

            }



            case MATROSKA_ID_BLOCKDURATION: {

                if ((res = ebml_read_uint(matroska, &id, &duration)) < 0)

                    break;

                break;

            }



            case MATROSKA_ID_BLOCKREFERENCE:

                /* We've found a reference, so not even the first frame in

                 * the lace is a key frame. */

                is_keyframe = 0;

                if (last_num_packets != matroska->num_packets)

                    matroska->packets[last_num_packets]->flags = 0;

                res = ebml_read_skip(matroska);

                break;



            default:

                av_log(matroska->ctx, AV_LOG_INFO,

                       "Unknown entry 0x%x in blockgroup data\n", id);

                /* fall-through */



            case EBML_ID_VOID:

                res = ebml_read_skip(matroska);

                break;

        }



        if (matroska->level_up) {

            matroska->level_up--;

            break;

        }

    }



    if (res)

        return res;



    if (size > 0)

        res = matroska_parse_block(matroska, data, size, pos, cluster_time,

                                   is_keyframe, &track, &pkt);



    if (pkt)

    {

        if (duration != AV_NOPTS_VALUE)

            pkt->duration = duration;

        else if (track >= 0 && track < matroska->num_tracks)

            pkt->duration = matroska->tracks[track]->default_duration / matroska->time_scale;

    }



    return res;

}

void vncws_tls_handshake_peek(void *opaque)

{

    VncState *vs = opaque;

    long ret;



    if (!vs->ws_tls.session) {

        char peek[4];

        ret = qemu_recv(vs->csock, peek, sizeof(peek), MSG_PEEK);

        if (ret && (strncmp(peek, "\x16", 1) == 0

                    || strncmp(peek, "\x80", 1) == 0)) {

            VNC_DEBUG("TLS Websocket connection recognized");

            vnc_tls_client_setup(vs, 1);

            vncws_start_tls_handshake(vs);

        } else {

            vncws_handshake_read(vs);

        }

    } else {

        qemu_set_fd_handler2(vs->csock, NULL, vncws_handshake_read, NULL, vs);

    }

}

bool check_hw_breakpoints(CPUX86State *env, bool force_dr6_update)

{

    target_ulong dr6;

    int reg;

    bool hit_enabled = false;



    dr6 = env->dr[6] & ~0xf;

    for (reg = 0; reg < DR7_MAX_BP; reg++) {

        bool bp_match = false;

        bool wp_match = false;



        switch (hw_breakpoint_type(env->dr[7], reg)) {

        case DR7_TYPE_BP_INST:

            if (env->dr[reg] == env->eip) {

                bp_match = true;

            }

            break;

        case DR7_TYPE_DATA_WR:

        case DR7_TYPE_DATA_RW:

            if (env->cpu_watchpoint[reg] &&

                env->cpu_watchpoint[reg]->flags & BP_WATCHPOINT_HIT) {

                wp_match = true;

            }

            break;

        case DR7_TYPE_IO_RW:

            break;

        }

        if (bp_match || wp_match) {

            dr6 |= 1 << reg;

            if (hw_breakpoint_enabled(env->dr[7], reg)) {

                hit_enabled = true;

            }

        }

    }



    if (hit_enabled || force_dr6_update) {

        env->dr[6] = dr6;

    }



    return hit_enabled;

}

static int ipvideo_decode_block_opcode_0x7(IpvideoContext *s)

{

    int x, y;

    unsigned char P[2];

    unsigned int flags;



    /* 2-color encoding */

    CHECK_STREAM_PTR(2);



    P[0] = *s->stream_ptr++;

    P[1] = *s->stream_ptr++;



    if (P[0] <= P[1]) {



        /* need 8 more bytes from the stream */

        CHECK_STREAM_PTR(8);



        for (y = 0; y < 8; y++) {

            flags = *s->stream_ptr++ | 0x100;

            for (; flags != 1; flags >>= 1)

                *s->pixel_ptr++ = P[flags & 1];

            s->pixel_ptr += s->line_inc;

        }



    } else {



        /* need 2 more bytes from the stream */

        CHECK_STREAM_PTR(2);



        flags = bytestream_get_le16(&s->stream_ptr);

        for (y = 0; y < 8; y += 2) {

            for (x = 0; x < 8; x += 2, flags >>= 1) {

                s->pixel_ptr[x                ] =

                s->pixel_ptr[x + 1            ] =

                s->pixel_ptr[x +     s->stride] =

                s->pixel_ptr[x + 1 + s->stride] = P[flags & 1];

            }

            s->pixel_ptr += s->stride * 2;

        }

    }



    /* report success */

    return 0;

}

