static void hb_synthesis(AMRWBContext *ctx, int subframe, float *samples,

                         const float *exc, const float *isf, const float *isf_past)

{

    float hb_lpc[LP_ORDER_16k];

    enum Mode mode = ctx->fr_cur_mode;



    if (mode == MODE_6k60) {

        float e_isf[LP_ORDER_16k]; // ISF vector for extrapolation

        double e_isp[LP_ORDER_16k];



        ff_weighted_vector_sumf(e_isf, isf_past, isf, isfp_inter[subframe],

                                1.0 - isfp_inter[subframe], LP_ORDER);



        extrapolate_isf(e_isf, e_isf);



        e_isf[LP_ORDER_16k - 1] *= 2.0;

        ff_acelp_lsf2lspd(e_isp, e_isf, LP_ORDER_16k);

        ff_amrwb_lsp2lpc(e_isp, hb_lpc, LP_ORDER_16k);



        lpc_weighting(hb_lpc, hb_lpc, 0.9, LP_ORDER_16k);

    } else {

        lpc_weighting(hb_lpc, ctx->lp_coef[subframe], 0.6, LP_ORDER);

    }



    ff_celp_lp_synthesis_filterf(samples, hb_lpc, exc, AMRWB_SFR_SIZE_16k,

                                 (mode == MODE_6k60) ? LP_ORDER_16k : LP_ORDER);

}

static int qemu_savevm_state(QEMUFile *f, Error **errp)

{

    int ret;

    MigrationParams params = {

        .blk = 0,

        .shared = 0

    };

    MigrationState *ms = migrate_init(&params);

    ms->to_dst_file = f;



    if (qemu_savevm_state_blocked(errp)) {

        return -EINVAL;

    }



    qemu_mutex_unlock_iothread();

    qemu_savevm_state_header(f);

    qemu_savevm_state_begin(f, &params);

    qemu_mutex_lock_iothread();



    while (qemu_file_get_error(f) == 0) {

        if (qemu_savevm_state_iterate(f, false) > 0) {

            break;

        }

    }



    ret = qemu_file_get_error(f);

    if (ret == 0) {

        qemu_savevm_state_complete_precopy(f, false);

        ret = qemu_file_get_error(f);

    }

    qemu_savevm_state_cleanup();

    if (ret != 0) {

        error_setg_errno(errp, -ret, "Error while writing VM state");

    }

    return ret;

}

static always_inline void dv_set_class_number(DCTELEM* blk, EncBlockInfo* bi, 

                                              const uint8_t* zigzag_scan, int bias)

{

    int i, area;

    int run;

    int classes[] = {12, 24, 36, 0xffff};



    run = 0;

    bi->mb[0] = blk[0]; 

    bi->cno = 0;

    for (area = 0; area < 4; area++) {

       bi->prev_run[area] = run;

       bi->bit_size[area] = 0;

       for (i=mb_area_start[area]; i<mb_area_start[area+1]; i++) {

          bi->mb[i] = (blk[zigzag_scan[i]] / 16);

          while ((bi->mb[i] ^ (bi->mb[i] >> 8)) > classes[bi->cno])

              bi->cno++;



          if (bi->mb[i]) {

              bi->bit_size[area] += dv_rl2vlc_size(run, bi->mb[i]);

	      run = 0;

          } else

              ++run;

       }

    }

    bi->bit_size[3] += 4; /* EOB marker */

    bi->cno += bias;



    if (bi->cno >= 3) { /* FIXME: we have to recreate bit_size[], prev_run[] */

        bi->cno = 3;

	for (i=1; i<64; i++)

	   bi->mb[i] /= 2;

    }

}

static void t_gen_lsl(TCGv d, TCGv a, TCGv b)

{

	TCGv t0, t_31;



	t0 = tcg_temp_new(TCG_TYPE_TL);

	t_31 = tcg_temp_new(TCG_TYPE_TL);

	tcg_gen_shl_tl(d, a, b);



	tcg_gen_movi_tl(t_31, 31);

	tcg_gen_sub_tl(t0, t_31, b);

	tcg_gen_sar_tl(t0, t0, t_31);

	tcg_gen_and_tl(t0, t0, d);

	tcg_gen_xor_tl(d, d, t0);

	tcg_temp_free(t0);

	tcg_temp_free(t_31);

}

bool virtio_scsi_handle_ctrl_vq(VirtIOSCSI *s, VirtQueue *vq)

{

    VirtIOSCSIReq *req;

    bool progress = false;



    virtio_scsi_acquire(s);

    while ((req = virtio_scsi_pop_req(s, vq))) {

        progress = true;

        virtio_scsi_handle_ctrl_req(s, req);

    }

    virtio_scsi_release(s);

    return progress;

}

static void gus_realizefn (DeviceState *dev, Error **errp)

{

    ISADevice *d = ISA_DEVICE(dev);

    GUSState *s = GUS (dev);

    IsaDmaClass *k;

    struct audsettings as;



    AUD_register_card ("gus", &s->card);



    as.freq = s->freq;

    as.nchannels = 2;

    as.fmt = AUD_FMT_S16;

    as.endianness = GUS_ENDIANNESS;



    s->voice = AUD_open_out (

        &s->card,

        NULL,

        "gus",

        s,

        GUS_callback,

        &as

        );



    if (!s->voice) {

        AUD_remove_card (&s->card);

        error_setg(errp, "No voice");

        return;

    }



    s->shift = 2;

    s->samples = AUD_get_buffer_size_out (s->voice) >> s->shift;

    s->mixbuf = g_malloc0 (s->samples << s->shift);



    isa_register_portio_list (d, s->port, gus_portio_list1, s, "gus");

    isa_register_portio_list (d, (s->port + 0x100) & 0xf00,

                              gus_portio_list2, s, "gus");



    s->isa_dma = isa_get_dma(isa_bus_from_device(d), s->emu.gusdma);

    k = ISADMA_GET_CLASS(s->isa_dma);

    k->register_channel(s->isa_dma, s->emu.gusdma, GUS_read_DMA, s);

    s->emu.himemaddr = s->himem;

    s->emu.gusdatapos = s->emu.himemaddr + 1024 * 1024 + 32;

    s->emu.opaque = s;

    isa_init_irq (d, &s->pic, s->emu.gusirq);



    AUD_set_active_out (s->voice, 1);

}

static inline bool migration_bitmap_clear_dirty(RAMState *rs, ram_addr_t addr)

{

    bool ret;

    int nr = addr >> TARGET_PAGE_BITS;

    unsigned long *bitmap = atomic_rcu_read(&rs->ram_bitmap)->bmap;



    ret = test_and_clear_bit(nr, bitmap);



