uint64_t qcow2_alloc_compressed_cluster_offset(BlockDriverState *bs,

                                               uint64_t offset,

                                               int compressed_size)

{

    BDRVQcowState *s = bs->opaque;

    int l2_index, ret;

    uint64_t *l2_table;

    int64_t cluster_offset;

    int nb_csectors;



    ret = get_cluster_table(bs, offset, &l2_table, &l2_index);

    if (ret < 0) {

        return 0;

    }



    cluster_offset = be64_to_cpu(l2_table[l2_index]);

    if (cluster_offset & QCOW_OFLAG_COPIED) {

        qcow2_cache_put(bs, s->l2_table_cache, (void**) &l2_table);

        return 0;

    }



    if (cluster_offset)

        qcow2_free_any_clusters(bs, cluster_offset, 1);



    cluster_offset = qcow2_alloc_bytes(bs, compressed_size);

    if (cluster_offset < 0) {

        qcow2_cache_put(bs, s->l2_table_cache, (void**) &l2_table);

        return 0;

    }



    nb_csectors = ((cluster_offset + compressed_size - 1) >> 9) -

                  (cluster_offset >> 9);



    cluster_offset |= QCOW_OFLAG_COMPRESSED |

                      ((uint64_t)nb_csectors << s->csize_shift);



    /* update L2 table */



    /* compressed clusters never have the copied flag */



    BLKDBG_EVENT(bs->file, BLKDBG_L2_UPDATE_COMPRESSED);

    qcow2_cache_entry_mark_dirty(s->l2_table_cache, l2_table);

    l2_table[l2_index] = cpu_to_be64(cluster_offset);

    ret = qcow2_cache_put(bs, s->l2_table_cache, (void**) &l2_table);

    if (ret < 0) {

        return 0;

    }



    return cluster_offset;

}

static int ac3_eac3_probe(AVProbeData *p, enum AVCodecID expected_codec_id)

{

    int max_frames, first_frames = 0, frames;

    uint8_t *buf, *buf2, *end;

    AC3HeaderInfo hdr;

    GetBitContext gbc;

    enum AVCodecID codec_id = AV_CODEC_ID_AC3;



    max_frames = 0;

    buf = p->buf;

    end = buf + p->buf_size;



    for(; buf < end; buf++) {

        if(buf > p->buf && !(buf[0] == 0x0B && buf[1] == 0x77)

                        && !(buf[0] == 0x77 && buf[1] == 0x0B) )

            continue;

        buf2 = buf;



        for(frames = 0; buf2 < end; frames++) {

            uint8_t buf3[4096];

            int i;

            if(!memcmp(buf2, "\x1\x10\0\0\0\0\0\0", 8))

                buf2+=16;

            if (buf[0] == 0x77 && buf[1] == 0x0B) {

                for(i=0; i<8; i+=2) {

                    buf3[i  ] = buf[i+1];

                    buf3[i+1] = buf[i  ];

                }

                init_get_bits(&gbc, buf3, 54);

            }else

                init_get_bits(&gbc, buf2, 54);

            if(avpriv_ac3_parse_header(&gbc, &hdr) < 0)

                break;

            if(buf2 + hdr.frame_size > end)

                break;

            if (buf[0] == 0x77 && buf[1] == 0x0B) {

                av_assert0(hdr.frame_size <= sizeof(buf3));

                for(; i<hdr.frame_size; i+=2) {

                    buf3[i  ] = buf[i+1];

                    buf3[i+1] = buf[i  ];

                }

            }

            if(av_crc(av_crc_get_table(AV_CRC_16_ANSI), 0, gbc.buffer + 2, hdr.frame_size - 2))

                break;

            if (hdr.bitstream_id > 10)

                codec_id = AV_CODEC_ID_EAC3;

            buf2 += hdr.frame_size;

        }

        max_frames = FFMAX(max_frames, frames);

        if(buf == p->buf)

            first_frames = frames;

    }

    if(codec_id != expected_codec_id) return 0;

    // keep this in sync with mp3 probe, both need to avoid

    // issues with MPEG-files!

    if   (first_frames>=4) return AVPROBE_SCORE_MAX/2+1;

    else if(max_frames>200)return AVPROBE_SCORE_MAX/2;

    else if(max_frames>=4) return AVPROBE_SCORE_MAX/4;

    else if(max_frames>=1) return 1;

    else                   return 0;

}

static int asf_read_frame_header(AVFormatContext *s, AVIOContext *pb){

    ASFContext *asf = s->priv_data;

    int rsize = 1;

    int num = avio_r8(pb);

    int64_t ts0, ts1;



    asf->packet_segments--;

    asf->packet_key_frame = num >> 7;

    asf->stream_index = asf->asfid2avid[num & 0x7f];

    // sequence should be ignored!

    DO_2BITS(asf->packet_property >> 4, asf->packet_seq, 0);

    DO_2BITS(asf->packet_property >> 2, asf->packet_frag_offset, 0);

    DO_2BITS(asf->packet_property, asf->packet_replic_size, 0);

