static int qxl_init_common(PCIQXLDevice *qxl)

{

    uint8_t* config = qxl->pci.config;

    uint32_t pci_device_id;

    uint32_t pci_device_rev;

    uint32_t io_size;



    qxl->mode = QXL_MODE_UNDEFINED;

    qxl->generation = 1;

    qxl->num_memslots = NUM_MEMSLOTS;

    qxl->num_surfaces = NUM_SURFACES;



    switch (qxl->revision) {

    case 1: /* spice 0.4 -- qxl-1 */

        pci_device_id  = QXL_DEVICE_ID_STABLE;

        pci_device_rev = QXL_REVISION_STABLE_V04;

        break;

    case 2: /* spice 0.6 -- qxl-2 */

        pci_device_id  = QXL_DEVICE_ID_STABLE;

        pci_device_rev = QXL_REVISION_STABLE_V06;

        break;

    default: /* experimental */

        pci_device_id  = QXL_DEVICE_ID_DEVEL;

        pci_device_rev = 1;

        break;

    }



    pci_config_set_vendor_id(config, REDHAT_PCI_VENDOR_ID);

    pci_config_set_device_id(config, pci_device_id);

    pci_set_byte(&config[PCI_REVISION_ID], pci_device_rev);

    pci_set_byte(&config[PCI_INTERRUPT_PIN], 1);



    qxl->rom_size = qxl_rom_size();

    qxl->rom_offset = qemu_ram_alloc(&qxl->pci.qdev, "qxl.vrom", qxl->rom_size);

    init_qxl_rom(qxl);

    init_qxl_ram(qxl);



    if (qxl->vram_size < 16 * 1024 * 1024) {

        qxl->vram_size = 16 * 1024 * 1024;

    }

    if (qxl->revision == 1) {

        qxl->vram_size = 4096;

    }

    qxl->vram_size = msb_mask(qxl->vram_size * 2 - 1);

    qxl->vram_offset = qemu_ram_alloc(&qxl->pci.qdev, "qxl.vram", qxl->vram_size);



    io_size = msb_mask(QXL_IO_RANGE_SIZE * 2 - 1);

    if (qxl->revision == 1) {

        io_size = 8;

    }



    pci_register_bar(&qxl->pci, QXL_IO_RANGE_INDEX,

                     io_size, PCI_BASE_ADDRESS_SPACE_IO, qxl_map);



    pci_register_bar(&qxl->pci, QXL_ROM_RANGE_INDEX,

                     qxl->rom_size, PCI_BASE_ADDRESS_SPACE_MEMORY,

                     qxl_map);



    pci_register_bar(&qxl->pci, QXL_RAM_RANGE_INDEX,

                     qxl->vga.vram_size, PCI_BASE_ADDRESS_SPACE_MEMORY,

                     qxl_map);



    pci_register_bar(&qxl->pci, QXL_VRAM_RANGE_INDEX, qxl->vram_size,

                     PCI_BASE_ADDRESS_SPACE_MEMORY, qxl_map);



    qxl->ssd.qxl.base.sif = &qxl_interface.base;

    qxl->ssd.qxl.id = qxl->id;

    qemu_spice_add_interface(&qxl->ssd.qxl.base);

    qemu_add_vm_change_state_handler(qxl_vm_change_state_handler, qxl);



    init_pipe_signaling(qxl);

    qxl_reset_state(qxl);



    return 0;

}

static TCGReg tcg_out_tlb_read(TCGContext* s, TCGReg addr_reg, TCGMemOp opc,

                               int mem_index, bool is_ld)

{

    int s_mask = (1 << (opc & MO_SIZE)) - 1;

    int ofs, a_off;

    uint64_t tlb_mask;



    /* For aligned accesses, we check the first byte and include the alignment

       bits within the address.  For unaligned access, we check that we don't

       cross pages using the address of the last byte of the access.  */

    if ((opc & MO_AMASK) == MO_ALIGN || s_mask == 0) {

        a_off = 0;

        tlb_mask = TARGET_PAGE_MASK | s_mask;

    } else {

        a_off = s_mask;

        tlb_mask = TARGET_PAGE_MASK;

    }



    if (facilities & FACILITY_GEN_INST_EXT) {

        tcg_out_risbg(s, TCG_REG_R2, addr_reg,

                      64 - CPU_TLB_BITS - CPU_TLB_ENTRY_BITS,

                      63 - CPU_TLB_ENTRY_BITS,

                      64 + CPU_TLB_ENTRY_BITS - TARGET_PAGE_BITS, 1);

        if (a_off) {

            tcg_out_insn(s, RX, LA, TCG_REG_R3, addr_reg, TCG_REG_NONE, a_off);

            tgen_andi(s, TCG_TYPE_TL, TCG_REG_R3, tlb_mask);

        } else {

            tgen_andi_risbg(s, TCG_REG_R3, addr_reg, tlb_mask);

        }

    } else {

        tcg_out_sh64(s, RSY_SRLG, TCG_REG_R2, addr_reg, TCG_REG_NONE,

                     TARGET_PAGE_BITS - CPU_TLB_ENTRY_BITS);

        tcg_out_insn(s, RX, LA, TCG_REG_R3, addr_reg, TCG_REG_NONE, a_off);

        tgen_andi(s, TCG_TYPE_I64, TCG_REG_R2,

                  (CPU_TLB_SIZE - 1) << CPU_TLB_ENTRY_BITS);

        tgen_andi(s, TCG_TYPE_TL, TCG_REG_R3, tlb_mask);

    }



    if (is_ld) {

        ofs = offsetof(CPUArchState, tlb_table[mem_index][0].addr_read);

    } else {

        ofs = offsetof(CPUArchState, tlb_table[mem_index][0].addr_write);

    }

    if (TARGET_LONG_BITS == 32) {

        tcg_out_mem(s, RX_C, RXY_CY, TCG_REG_R3, TCG_REG_R2, TCG_AREG0, ofs);

    } else {

        tcg_out_mem(s, 0, RXY_CG, TCG_REG_R3, TCG_REG_R2, TCG_AREG0, ofs);

    }



    ofs = offsetof(CPUArchState, tlb_table[mem_index][0].addend);

    tcg_out_mem(s, 0, RXY_LG, TCG_REG_R2, TCG_REG_R2, TCG_AREG0, ofs);



    if (TARGET_LONG_BITS == 32) {

        tgen_ext32u(s, TCG_REG_R3, addr_reg);

        return TCG_REG_R3;

    }

    return addr_reg;

}

