static int mov_read_header(AVFormatContext *s)

{

    MOVContext *mov = s->priv_data;

    AVIOContext *pb = s->pb;

    int j, err;

    MOVAtom atom = { AV_RL32("root") };

    int i;



    if (mov->decryption_key_len != 0 && mov->decryption_key_len != AES_CTR_KEY_SIZE) {

        av_log(s, AV_LOG_ERROR, "Invalid decryption key len %d expected %d\n",

            mov->decryption_key_len, AES_CTR_KEY_SIZE);

        return AVERROR(EINVAL);

    }



    mov->fc = s;

    mov->trak_index = -1;

    /* .mov and .mp4 aren't streamable anyway (only progressive download if moov is before mdat) */

    if (pb->seekable)

        atom.size = avio_size(pb);

    else

        atom.size = INT64_MAX;



    /* check MOV header */

    do {

    if (mov->moov_retry)

        avio_seek(pb, 0, SEEK_SET);

    if ((err = mov_read_default(mov, pb, atom)) < 0) {

        av_log(s, AV_LOG_ERROR, "error reading header\n");

        mov_read_close(s);

        return err;

    }

    } while (pb->seekable && !mov->found_moov && !mov->moov_retry++);

    if (!mov->found_moov) {

        av_log(s, AV_LOG_ERROR, "moov atom not found\n");

        mov_read_close(s);

        return AVERROR_INVALIDDATA;

    }

    av_log(mov->fc, AV_LOG_TRACE, "on_parse_exit_offset=%"PRId64"\n", avio_tell(pb));



    if (pb->seekable) {

        if (mov->nb_chapter_tracks > 0 && !mov->ignore_chapters)

            mov_read_chapters(s);

        for (i = 0; i < s->nb_streams; i++)

            if (s->streams[i]->codecpar->codec_tag == AV_RL32("tmcd")) {

                mov_read_timecode_track(s, s->streams[i]);

            } else if (s->streams[i]->codecpar->codec_tag == AV_RL32("rtmd")) {

                mov_read_rtmd_track(s, s->streams[i]);

            }

    }



    /* copy timecode metadata from tmcd tracks to the related video streams */

    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        MOVStreamContext *sc = st->priv_data;

        if (sc->timecode_track > 0) {

            AVDictionaryEntry *tcr;

            int tmcd_st_id = -1;



            for (j = 0; j < s->nb_streams; j++)

                if (s->streams[j]->id == sc->timecode_track)

                    tmcd_st_id = j;



            if (tmcd_st_id < 0 || tmcd_st_id == i)

                continue;

            tcr = av_dict_get(s->streams[tmcd_st_id]->metadata, "timecode", NULL, 0);

            if (tcr)

                av_dict_set(&st->metadata, "timecode", tcr->value, 0);

        }

    }

    export_orphan_timecode(s);



    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        MOVStreamContext *sc = st->priv_data;

        fix_timescale(mov, sc);

        if(st->codecpar->codec_type == AVMEDIA_TYPE_AUDIO && st->codecpar->codec_id == AV_CODEC_ID_AAC) {

            st->skip_samples = sc->start_pad;

        }

        if (st->codecpar->codec_type == AVMEDIA_TYPE_VIDEO && sc->nb_frames_for_fps > 0 && sc->duration_for_fps > 0)

            av_reduce(&st->avg_frame_rate.num, &st->avg_frame_rate.den,

                      sc->time_scale*(int64_t)sc->nb_frames_for_fps, sc->duration_for_fps, INT_MAX);

        if (st->codecpar->codec_type == AVMEDIA_TYPE_SUBTITLE) {

            if (st->codecpar->width <= 0 || st->codecpar->height <= 0) {

                st->codecpar->width  = sc->width;

                st->codecpar->height = sc->height;

            }

            if (st->codecpar->codec_id == AV_CODEC_ID_DVD_SUBTITLE) {

                if ((err = mov_rewrite_dvd_sub_extradata(st)) < 0)

                    return err;

            }

        }

        if (mov->handbrake_version &&

            mov->handbrake_version <= 1000000*0 + 1000*10 + 2 &&  // 0.10.2

            st->codecpar->codec_id == AV_CODEC_ID_MP3

        ) {

            av_log(s, AV_LOG_VERBOSE, "Forcing full parsing for mp3 stream\n");

            st->need_parsing = AVSTREAM_PARSE_FULL;

        }

    }



    if (mov->trex_data) {

        for (i = 0; i < s->nb_streams; i++) {

            AVStream *st = s->streams[i];

            MOVStreamContext *sc = st->priv_data;

            if (st->duration > 0)

                st->codecpar->bit_rate = sc->data_size * 8 * sc->time_scale / st->duration;

        }

    }



    if (mov->use_mfra_for > 0) {

        for (i = 0; i < s->nb_streams; i++) {

            AVStream *st = s->streams[i];

            MOVStreamContext *sc = st->priv_data;

            if (sc->duration_for_fps > 0) {

                st->codecpar->bit_rate = sc->data_size * 8 * sc->time_scale /

                    sc->duration_for_fps;

            }

        }

    }



    for (i = 0; i < mov->bitrates_count && i < s->nb_streams; i++) {

        if (mov->bitrates[i]) {

            s->streams[i]->codecpar->bit_rate = mov->bitrates[i];

        }

    }



    ff_rfps_calculate(s);



    for (i = 0; i < s->nb_streams; i++) {

        AVStream *st = s->streams[i];

        MOVStreamContext *sc = st->priv_data;



        switch (st->codecpar->codec_type) {

        case AVMEDIA_TYPE_AUDIO:

            err = ff_replaygain_export(st, s->metadata);

            if (err < 0) {

                mov_read_close(s);

                return err;

            }

            break;

        case AVMEDIA_TYPE_VIDEO:

            if (sc->display_matrix) {

                err = av_stream_add_side_data(st, AV_PKT_DATA_DISPLAYMATRIX, (uint8_t*)sc->display_matrix,

                                              sizeof(int32_t) * 9);

                if (err < 0)

                    return err;



                sc->display_matrix = NULL;

            }

            if (sc->stereo3d) {

                err = av_stream_add_side_data(st, AV_PKT_DATA_STEREO3D,

                                              (uint8_t *)sc->stereo3d,

                                              sizeof(*sc->stereo3d));

                if (err < 0)

                    return err;



                sc->stereo3d = NULL;

            }

            if (sc->spherical) {

                err = av_stream_add_side_data(st, AV_PKT_DATA_SPHERICAL,

                                              (uint8_t *)sc->spherical,

                                              sc->spherical_size);

                if (err < 0)

                    return err;



                sc->spherical = NULL;

            }

            break;

        }

    }

    ff_configure_buffers_for_index(s, AV_TIME_BASE);



    return 0;

}

static int thread_execute(AVCodecContext *avctx, action_func* func, void *arg, int *ret, int job_count, int job_size)

{

    SliceThreadContext *c = avctx->internal->thread_ctx;



    if (!(avctx->active_thread_type&FF_THREAD_SLICE) || avctx->thread_count <= 1)

        return avcodec_default_execute(avctx, func, arg, ret, job_count, job_size);



    if (job_count <= 0)

        return 0;



    pthread_mutex_lock(&c->current_job_lock);



    c->current_job = avctx->thread_count;

    c->job_count = job_count;

    c->job_size = job_size;

    c->args = arg;

    c->func = func;

    c->rets = ret;

    c->current_execute++;

    pthread_cond_broadcast(&c->current_job_cond);



    thread_park_workers(c, avctx->thread_count);



    return 0;

}

static void gain_compensate(COOKContext *q, cook_gains *gains_ptr,

                            float* previous_buffer)

{

    const float fc = q->pow2tab[gains_ptr->previous[0] + 63];

    float *buffer = q->mono_mdct_output;

    int i;



    /* Overlap with the previous block. */

    for(i=0 ; i<q->samples_per_channel ; i++) {

        buffer[i] *= fc;

        buffer[i] += previous_buffer[i];

    }



    /* Apply gain profile */

    for (i = 0; i < 8; i++) {

        if (gains_ptr->now[i] || gains_ptr->now[i + 1])

            interpolate(q, &buffer[q->gain_size_factor * i],

                        gains_ptr->now[i], gains_ptr->now[i + 1]);

    }



    /* Save away the current to be previous block. */

    memcpy(previous_buffer, buffer+q->samples_per_channel,

           sizeof(float)*q->samples_per_channel);

}

int ff_mov_init_hinting(AVFormatContext *s, int index, int src_index)

{

    MOVMuxContext *mov  = s->priv_data;

    MOVTrack *track     = &mov->tracks[index];

    MOVTrack *src_track = &mov->tracks[src_index];

    AVStream *src_st    = s->streams[src_index];

    int ret = AVERROR(ENOMEM);

    AVOutputFormat *rtp_format = av_guess_format("rtp", NULL, NULL);



    track->tag = MKTAG('r','t','p',' ');

    track->src_track = src_index;



    if (!rtp_format) {

        ret = AVERROR(ENOENT);

        goto fail;

    }



    track->enc = avcodec_alloc_context();

    if (!track->enc)

        goto fail;

    track->enc->codec_type = AVMEDIA_TYPE_DATA;

    track->enc->codec_tag  = track->tag;



    track->rtp_ctx = avformat_alloc_context();

    if (!track->rtp_ctx)

        goto fail;

    track->rtp_ctx->oformat = rtp_format;

    if (!av_new_stream(track->rtp_ctx, 0))

        goto fail;



    /* Copy stream parameters */

    track->rtp_ctx->streams[0]->sample_aspect_ratio =

                        src_st->sample_aspect_ratio;



    /* Remove the allocated codec context, link to the original one

     * instead, to give the rtp muxer access to codec parameters. */

    av_free(track->rtp_ctx->streams[0]->codec);

    track->rtp_ctx->streams[0]->codec = src_st->codec;



    if ((ret = url_open_dyn_packet_buf(&track->rtp_ctx->pb,

                                       RTP_MAX_PACKET_SIZE)) < 0)

        goto fail;

    ret = av_write_header(track->rtp_ctx);

    if (ret)

        goto fail;



    /* Copy the RTP AVStream timebase back to the hint AVStream */

    track->timescale = track->rtp_ctx->streams[0]->time_base.den;



    /* Mark the hinted track that packets written to it should be

     * sent to this track for hinting. */

    src_track->hint_track = index;

    return 0;

fail:

    av_log(s, AV_LOG_WARNING,

           "Unable to initialize hinting of stream %d\n", src_index);

    if (track->rtp_ctx && track->rtp_ctx->pb) {

        uint8_t *buf;

        url_close_dyn_buf(track->rtp_ctx->pb, &buf);

        av_free(buf);

    }

    if (track->rtp_ctx && track->rtp_ctx->streams[0]) {

        av_metadata_free(&track->rtp_ctx->streams[0]->metadata);


        av_free(track->rtp_ctx->streams[0]);

    }

    if (track->rtp_ctx) {

        av_metadata_free(&track->rtp_ctx->metadata);

        av_free(track->rtp_ctx->priv_data);

        av_freep(&track->rtp_ctx);

    }

    av_freep(&track->enc);

    /* Set a default timescale, to avoid crashes in dump_format */

    track->timescale = 90000;

    return ret;

}

static inline int l3_unscale(int value, int exponent)

{

    unsigned int m;

    int e;



    e  = table_4_3_exp  [4 * value + (exponent & 3)];

    m  = table_4_3_value[4 * value + (exponent & 3)];

    e -= exponent >> 2;

#ifdef DEBUG

    if(e < 1)

        av_log(NULL, AV_LOG_WARNING, "l3_unscale: e is %d\n", e);

#endif

    if (e > (SUINT)31)

        return 0;

    m = (m + (1 << (e - 1))) >> e;



    return m;

}

static int l2_allocate(BlockDriverState *bs, int l1_index, uint64_t **table)
{
    BDRVQcow2State *s = bs->opaque;
    uint64_t old_l2_offset;
    uint64_t *l2_table = NULL;
    int64_t l2_offset;
    int ret;
    old_l2_offset = s->l1_table[l1_index];
    trace_qcow2_l2_allocate(bs, l1_index);
    /* allocate a new l2 entry */
    l2_offset = qcow2_alloc_clusters(bs, s->l2_size * sizeof(uint64_t));
    if (l2_offset < 0) {
        ret = l2_offset;
    ret = qcow2_cache_flush(bs, s->refcount_block_cache);
    if (ret < 0) {
    /* allocate a new entry in the l2 cache */
    trace_qcow2_l2_allocate_get_empty(bs, l1_index);
    ret = qcow2_cache_get_empty(bs, s->l2_table_cache, l2_offset, (void**) table);
    if (ret < 0) {
    l2_table = *table;
    if ((old_l2_offset & L1E_OFFSET_MASK) == 0) {
        /* if there was no old l2 table, clear the new table */
        memset(l2_table, 0, s->l2_size * sizeof(uint64_t));
    } else {
        uint64_t* old_table;
        /* if there was an old l2 table, read it from the disk */
        BLKDBG_EVENT(bs->file, BLKDBG_L2_ALLOC_COW_READ);
        ret = qcow2_cache_get(bs, s->l2_table_cache,
            old_l2_offset & L1E_OFFSET_MASK,
            (void**) &old_table);
        if (ret < 0) {
        memcpy(l2_table, old_table, s->cluster_size);
        qcow2_cache_put(bs, s->l2_table_cache, (void **) &old_table);
    /* write the l2 table to the file */
    BLKDBG_EVENT(bs->file, BLKDBG_L2_ALLOC_WRITE);
    trace_qcow2_l2_allocate_write_l2(bs, l1_index);
    qcow2_cache_entry_mark_dirty(bs, s->l2_table_cache, l2_table);
    ret = qcow2_cache_flush(bs, s->l2_table_cache);
    if (ret < 0) {
    /* update the L1 entry */
    trace_qcow2_l2_allocate_write_l1(bs, l1_index);
    s->l1_table[l1_index] = l2_offset | QCOW_OFLAG_COPIED;
    ret = qcow2_write_l1_entry(bs, l1_index);
    if (ret < 0) {
    *table = l2_table;
    trace_qcow2_l2_allocate_done(bs, l1_index, 0);
    return 0;
fail:
    trace_qcow2_l2_allocate_done(bs, l1_index, ret);
    if (l2_table != NULL) {
        qcow2_cache_put(bs, s->l2_table_cache, (void**) table);
    s->l1_table[l1_index] = old_l2_offset;
    if (l2_offset > 0) {
        qcow2_free_clusters(bs, l2_offset, s->l2_size * sizeof(uint64_t),
                            QCOW2_DISCARD_ALWAYS);
    return ret;

