}

static int mov_read_tkhd(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    int i;

    int width;

    int height;

    int64_t disp_transform[2];

    int display_matrix[3][3];

    AVStream *st;

    MOVStreamContext *sc;

    int version;

    int flags;



    if (c->fc->nb_streams < 1)

        return 0;

    st = c->fc->streams[c->fc->nb_streams-1];

    sc = st->priv_data;



    version = avio_r8(pb);

    flags = avio_rb24(pb);

    st->disposition |= (flags & MOV_TKHD_FLAG_ENABLED) ? AV_DISPOSITION_DEFAULT : 0;



    if (version == 1) {

        avio_rb64(pb);

        avio_rb64(pb);

    } else {

        avio_rb32(pb); /* creation time */

        avio_rb32(pb); /* modification time */

    }

    st->id = (int)avio_rb32(pb); /* track id (NOT 0 !)*/

    avio_rb32(pb); /* reserved */



    /* highlevel (considering edits) duration in movie timebase */

    (version == 1) ? avio_rb64(pb) : avio_rb32(pb);

    avio_rb32(pb); /* reserved */

    avio_rb32(pb); /* reserved */



    avio_rb16(pb); /* layer */

    avio_rb16(pb); /* alternate group */

    avio_rb16(pb); /* volume */

    avio_rb16(pb); /* reserved */



    //read in the display matrix (outlined in ISO 14496-12, Section 6.2.2)

    // they're kept in fixed point format through all calculations

    // save u,v,z to store the whole matrix in the AV_PKT_DATA_DISPLAYMATRIX

    // side data, but the scale factor is not needed to calculate aspect ratio

    for (i = 0; i < 3; i++) {

        display_matrix[i][0] = avio_rb32(pb);   // 16.16 fixed point

        display_matrix[i][1] = avio_rb32(pb);   // 16.16 fixed point

        display_matrix[i][2] = avio_rb32(pb);   //  2.30 fixed point

    }



    width = avio_rb32(pb);       // 16.16 fixed point track width

    height = avio_rb32(pb);      // 16.16 fixed point track height

    sc->width = width >> 16;

    sc->height = height >> 16;



    // save the matrix when it is not the default identity

    if (display_matrix[0][0] != (1 << 16) ||

        display_matrix[1][1] != (1 << 16) ||

        display_matrix[2][2] != (1 << 30) ||

        display_matrix[0][1] || display_matrix[0][2] ||

        display_matrix[1][0] || display_matrix[1][2] ||

        display_matrix[2][0] || display_matrix[2][1]) {

        int i, j;



        av_freep(&sc->display_matrix);

        sc->display_matrix = av_malloc(sizeof(int32_t) * 9);

        if (!sc->display_matrix)

            return AVERROR(ENOMEM);



        for (i = 0; i < 3; i++)

            for (j = 0; j < 3; j++)

                sc->display_matrix[i * 3 + j] = display_matrix[j][i];

    }



    // transform the display width/height according to the matrix

    // skip this if the rotation angle is 0 degrees

    // to keep the same scale, use [width height 1<<16]

    if (width && height && sc->display_matrix &&

        av_display_rotation_get(sc->display_matrix) != 0.0f) {

        for (i = 0; i < 2; i++)

            disp_transform[i] =

                (int64_t)  width  * display_matrix[0][i] +

                (int64_t)  height * display_matrix[1][i] +

                ((int64_t) display_matrix[2][i] << 16);



        //sample aspect ratio is new width/height divided by old width/height

        st->sample_aspect_ratio = av_d2q(

            ((double) disp_transform[0] * height) /

            ((double) disp_transform[1] * width), INT_MAX);

    }

    return 0;

}

uint8_t *av_packet_new_side_data(AVPacket *pkt, enum AVPacketSideDataType type,

                                 int size)

{

    int elems = pkt->side_data_elems;



    if ((unsigned)elems + 1 > INT_MAX / sizeof(*pkt->side_data))

        return NULL;

    if ((unsigned)size > INT_MAX - FF_INPUT_BUFFER_PADDING_SIZE)

        return NULL;



    pkt->side_data = av_realloc(pkt->side_data,

                                (elems + 1) * sizeof(*pkt->side_data));

    if (!pkt->side_data)

        return NULL;



    pkt->side_data[elems].data = av_malloc(size + FF_INPUT_BUFFER_PADDING_SIZE);

    if (!pkt->side_data[elems].data)

        return NULL;

    pkt->side_data[elems].size = size;

    pkt->side_data[elems].type = type;

    pkt->side_data_elems++;



    return pkt->side_data[elems].data;

}

static void pointer_event(VncState *vs, int button_mask, int x, int y)

{

    static uint32_t bmap[INPUT_BUTTON_MAX] = {

        [INPUT_BUTTON_LEFT]       = 0x01,

        [INPUT_BUTTON_MIDDLE]     = 0x02,

        [INPUT_BUTTON_RIGHT]      = 0x04,

        [INPUT_BUTTON_WHEEL_UP]   = 0x08,

        [INPUT_BUTTON_WHEEL_DOWN] = 0x10,

    };

    QemuConsole *con = vs->vd->dcl.con;

    int width = surface_width(vs->vd->ds);

    int height = surface_height(vs->vd->ds);



    if (vs->last_bmask != button_mask) {

        qemu_input_update_buttons(con, bmap, vs->last_bmask, button_mask);

        vs->last_bmask = button_mask;

    }



    if (vs->absolute) {

        qemu_input_queue_abs(con, INPUT_AXIS_X, x, width);

        qemu_input_queue_abs(con, INPUT_AXIS_Y, y, height);

    } else if (vnc_has_feature(vs, VNC_FEATURE_POINTER_TYPE_CHANGE)) {

        qemu_input_queue_rel(con, INPUT_AXIS_X, x - 0x7FFF);

        qemu_input_queue_rel(con, INPUT_AXIS_Y, y - 0x7FFF);

    } else {

        if (vs->last_x != -1) {

            qemu_input_queue_rel(con, INPUT_AXIS_X, x - vs->last_x);

            qemu_input_queue_rel(con, INPUT_AXIS_Y, y - vs->last_y);

        }

        vs->last_x = x;

        vs->last_y = y;

    }

    qemu_input_event_sync();

}

void visit_type_uint16(Visitor *v, uint16_t *obj, const char *name, Error **errp)

{

    int64_t value;

    if (!error_is_set(errp)) {

        if (v->type_uint16) {

            v->type_uint16(v, obj, name, errp);

        } else {

            value = *obj;

            v->type_int(v, &value, name, errp);

            if (value < 0 || value > UINT16_MAX) {

                error_set(errp, QERR_INVALID_PARAMETER_VALUE, name ? name : "null",

                          "uint16_t");

                return;

            }

            *obj = value;

        }

    }

}

static void rtsp_parse_transport(RTSPMessageHeader *reply, const char *p)

{

    char transport_protocol[16];

    char profile[16];

    char lower_transport[16];

    char parameter[16];

    RTSPTransportField *th;

    char buf[256];



    reply->nb_transports = 0;



    for(;;) {

        skip_spaces(&p);

        if (*p == '\0')

            break;



        th = &reply->transports[reply->nb_transports];



        get_word_sep(transport_protocol, sizeof(transport_protocol),

                     "/", &p);

        if (!strcasecmp (transport_protocol, "rtp")) {

            get_word_sep(profile, sizeof(profile), "/;,", &p);

            lower_transport[0] = '\0';

            /* rtp/avp/<protocol> */

            if (*p == '/') {

                get_word_sep(lower_transport, sizeof(lower_transport),

                             ";,", &p);

            }

            th->transport = RTSP_TRANSPORT_RTP;

        } else if (!strcasecmp (transport_protocol, "x-pn-tng") ||

                   !strcasecmp (transport_protocol, "x-real-rdt")) {

            /* x-pn-tng/<protocol> */

            get_word_sep(lower_transport, sizeof(lower_transport), "/;,", &p);

            profile[0] = '\0';

            th->transport = RTSP_TRANSPORT_RDT;

        }

        if (!strcasecmp(lower_transport, "TCP"))

            th->lower_transport = RTSP_LOWER_TRANSPORT_TCP;

        else

            th->lower_transport = RTSP_LOWER_TRANSPORT_UDP;



        if (*p == ';')

            p++;

        /* get each parameter */

        while (*p != '\0' && *p != ',') {

            get_word_sep(parameter, sizeof(parameter), "=;,", &p);

            if (!strcmp(parameter, "port")) {

                if (*p == '=') {

                    p++;

                    rtsp_parse_range(&th->port_min, &th->port_max, &p);

                }

            } else if (!strcmp(parameter, "client_port")) {

                if (*p == '=') {

                    p++;

                    rtsp_parse_range(&th->client_port_min,

                                     &th->client_port_max, &p);

                }

            } else if (!strcmp(parameter, "server_port")) {

                if (*p == '=') {

                    p++;

                    rtsp_parse_range(&th->server_port_min,

                                     &th->server_port_max, &p);

                }

            } else if (!strcmp(parameter, "interleaved")) {

                if (*p == '=') {

                    p++;

                    rtsp_parse_range(&th->interleaved_min,

                                     &th->interleaved_max, &p);

                }

            } else if (!strcmp(parameter, "multicast")) {

                if (th->lower_transport == RTSP_LOWER_TRANSPORT_UDP)

                    th->lower_transport = RTSP_LOWER_TRANSPORT_UDP_MULTICAST;

            } else if (!strcmp(parameter, "ttl")) {

                if (*p == '=') {

                    p++;

                    th->ttl = strtol(p, (char **)&p, 10);

                }

            } else if (!strcmp(parameter, "destination")) {

                struct in_addr ipaddr;



                if (*p == '=') {

                    p++;

                    get_word_sep(buf, sizeof(buf), ";,", &p);

                    if (inet_aton(buf, &ipaddr))

                        th->destination = ntohl(ipaddr.s_addr);

                }

            }

            while (*p != ';' && *p != '\0' && *p != ',')

                p++;

            if (*p == ';')

                p++;

        }

        if (*p == ',')

            p++;



        reply->nb_transports++;

    }

}

static int mov_write_avcc_tag(ByteIOContext *pb, MOVTrack *track)

{

    offset_t pos = url_ftell(pb);



    put_be32(pb, 0);

    put_tag(pb, "avcC");

    if (track->vosLen > 6) {

        /* check for h264 start code */

        if (AV_RB32(track->vosData) == 0x00000001) {

            uint8_t *buf, *end;

            uint32_t sps_size=0, pps_size=0;

            uint8_t *sps=0, *pps=0;



            avc_parse_nal_units(&track->vosData, &track->vosLen);

            buf = track->vosData;

            end = track->vosData + track->vosLen;



            /* look for sps and pps */

            while (buf < end) {

                unsigned int size;

                uint8_t nal_type;

                size = AV_RB32(buf);

                nal_type = buf[4] & 0x1f;

                if (nal_type == 7) { /* SPS */

                    sps = buf + 4;

                    sps_size = size;

                } else if (nal_type == 8) { /* PPS */

                    pps = buf + 4;

                    pps_size = size;

                }

                buf += size + 4;

            }

            assert(sps);

            assert(pps);



            put_byte(pb, 1); /* version */

            put_byte(pb, sps[1]); /* profile */

            put_byte(pb, sps[2]); /* profile compat */

            put_byte(pb, sps[3]); /* level */

            put_byte(pb, 0xff); /* 6 bits reserved (111111) + 2 bits nal size length - 1 (11) */

            put_byte(pb, 0xe1); /* 3 bits reserved (111) + 5 bits number of sps (00001) */



            put_be16(pb, sps_size);

            put_buffer(pb, sps, sps_size);

            put_byte(pb, 1); /* number of pps */

            put_be16(pb, pps_size);

            put_buffer(pb, pps, pps_size);

        } else {

            put_buffer(pb, track->vosData, track->vosLen);

        }

    }

    return updateSize(pb, pos);

}

static inline int compress_coeffs(int *coef, int order, int c_bits)

{

    int i, res = 0;

    const int low_idx   = c_bits ?  4 : 2;

    const int shift_val = c_bits ?  8 : 4;

    const int high_idx  = c_bits ? 11 : 5;

    for (i = 0; i < order; i++)

        if (coef[i] < low_idx || coef[i] > high_idx)

            res++;

    if (res == order)

        for (i = 0; i < order; i++)

            coef[i] -= (coef[i] > high_idx) ? shift_val : 0;

    return res == order;

}

