static void float_number(void)

{

    int i;

    struct {

        const char *encoded;

        double decoded;

        int skip;

    } test_cases[] = {

        { "32.43", 32.43 },

        { "0.222", 0.222 },

        { "-32.12313", -32.12313 },

        { "-32.20e-10", -32.20e-10, .skip = 1 },

        { },

    };



    for (i = 0; test_cases[i].encoded; i++) {

        QObject *obj;

        QFloat *qfloat;



        obj = qobject_from_json(test_cases[i].encoded);

        g_assert(obj != NULL);

        g_assert(qobject_type(obj) == QTYPE_QFLOAT);



        qfloat = qobject_to_qfloat(obj);

        g_assert(qfloat_get_double(qfloat) == test_cases[i].decoded);



        if (test_cases[i].skip == 0) {

            QString *str;



            str = qobject_to_json(obj);

            g_assert(strcmp(qstring_get_str(str), test_cases[i].encoded) == 0);

            QDECREF(str);

        }



        QDECREF(qfloat);

    }

}

static void colo_process_checkpoint(MigrationState *s)

{

    QIOChannelBuffer *bioc;

    QEMUFile *fb = NULL;

    int64_t current_time, checkpoint_time = qemu_clock_get_ms(QEMU_CLOCK_HOST);

    Error *local_err = NULL;

    int ret;



    failover_init_state();



    s->rp_state.from_dst_file = qemu_file_get_return_path(s->to_dst_file);

    if (!s->rp_state.from_dst_file) {

        error_report("Open QEMUFile from_dst_file failed");

        goto out;

    }



    /*

     * Wait for Secondary finish loading VM states and enter COLO

     * restore.

     */

    colo_receive_check_message(s->rp_state.from_dst_file,

                       COLO_MESSAGE_CHECKPOINT_READY, &local_err);

    if (local_err) {

        goto out;

    }

    bioc = qio_channel_buffer_new(COLO_BUFFER_BASE_SIZE);

    fb = qemu_fopen_channel_output(QIO_CHANNEL(bioc));

    object_unref(OBJECT(bioc));



    qemu_mutex_lock_iothread();

    vm_start();

    qemu_mutex_unlock_iothread();

    trace_colo_vm_state_change("stop", "run");



    while (s->state == MIGRATION_STATUS_COLO) {

        if (failover_get_state() != FAILOVER_STATUS_NONE) {

            error_report("failover request");

            goto out;

        }



        current_time = qemu_clock_get_ms(QEMU_CLOCK_HOST);

        if (current_time - checkpoint_time <

            s->parameters.x_checkpoint_delay) {

            int64_t delay_ms;



            delay_ms = s->parameters.x_checkpoint_delay -

                       (current_time - checkpoint_time);

            g_usleep(delay_ms * 1000);

        }

        ret = colo_do_checkpoint_transaction(s, bioc, fb);

        if (ret < 0) {

            goto out;

        }

        checkpoint_time = qemu_clock_get_ms(QEMU_CLOCK_HOST);

    }



out:

    /* Throw the unreported error message after exited from loop */

    if (local_err) {

        error_report_err(local_err);

    }



    if (fb) {

        qemu_fclose(fb);

    }



    if (s->rp_state.from_dst_file) {

        qemu_fclose(s->rp_state.from_dst_file);

    }

}

static void ecc_mem_write(void *opaque, target_phys_addr_t addr, uint64_t val,

                          unsigned size)

{

    ECCState *s = opaque;



    switch (addr >> 2) {

    case ECC_MER:

        if (s->version == ECC_MCC)

            s->regs[ECC_MER] = (val & ECC_MER_MASK_0);

        else if (s->version == ECC_EMC)

            s->regs[ECC_MER] = s->version | (val & ECC_MER_MASK_1);

        else if (s->version == ECC_SMC)

            s->regs[ECC_MER] = s->version | (val & ECC_MER_MASK_2);

        trace_ecc_mem_writel_mer(val);

        break;

    case ECC_MDR:

        s->regs[ECC_MDR] =  val & ECC_MDR_MASK;

        trace_ecc_mem_writel_mdr(val);

        break;

    case ECC_MFSR:

        s->regs[ECC_MFSR] =  val;

        qemu_irq_lower(s->irq);

        trace_ecc_mem_writel_mfsr(val);

        break;

    case ECC_VCR:

        s->regs[ECC_VCR] =  val;

        trace_ecc_mem_writel_vcr(val);

        break;

    case ECC_DR:

        s->regs[ECC_DR] =  val;

        trace_ecc_mem_writel_dr(val);

        break;

    case ECC_ECR0:

        s->regs[ECC_ECR0] =  val;

        trace_ecc_mem_writel_ecr0(val);

        break;

    case ECC_ECR1:

        s->regs[ECC_ECR0] =  val;

        trace_ecc_mem_writel_ecr1(val);

        break;

    }

}

