static int get_stats(AVCodecContext *avctx, int eos)

{

#ifdef TH_ENCCTL_2PASS_OUT

    TheoraContext *h = avctx->priv_data;

    uint8_t *buf;

    int bytes;



    bytes = th_encode_ctl(h->t_state, TH_ENCCTL_2PASS_OUT, &buf, sizeof(buf));

    if (bytes < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error getting first pass stats\n");

        return AVERROR_EXTERNAL;

    }

    if (!eos) {

        void *tmp = av_fast_realloc(h->stats, &h->stats_size,

                                   h->stats_offset + bytes);

        if (!tmp)


        h->stats = tmp;

        memcpy(h->stats + h->stats_offset, buf, bytes);

        h->stats_offset += bytes;

    } else {

        int b64_size = AV_BASE64_SIZE(h->stats_offset);

        // libtheora generates a summary header at the end

        memcpy(h->stats, buf, bytes);

        avctx->stats_out = av_malloc(b64_size);



        av_base64_encode(avctx->stats_out, b64_size, h->stats, h->stats_offset);

    }

    return 0;

#else

    av_log(avctx, AV_LOG_ERROR, "libtheora too old to support 2pass\n");

    return AVERROR(ENOSUP);

#endif

}

static int allocate_buffers(ALACContext *alac)

{

    int ch;

    int buf_size = alac->max_samples_per_frame * sizeof(int32_t);



    for (ch = 0; ch < FFMIN(alac->channels, 2); ch++) {

        FF_ALLOC_OR_GOTO(alac->avctx, alac->predict_error_buffer[ch],

                         buf_size, buf_alloc_fail);



        alac->direct_output = alac->sample_size > 16 && av_sample_fmt_is_planar(alac->avctx->sample_fmt);

        if (!alac->direct_output) {

            FF_ALLOC_OR_GOTO(alac->avctx, alac->output_samples_buffer[ch],

                             buf_size, buf_alloc_fail);

        }



        FF_ALLOC_OR_GOTO(alac->avctx, alac->extra_bits_buffer[ch],

                         buf_size, buf_alloc_fail);

    }

    return 0;

buf_alloc_fail:

    alac_decode_close(alac->avctx);

    return AVERROR(ENOMEM);

}

static av_cold int iss_read_header(AVFormatContext *s)

{

    IssDemuxContext *iss = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st;

    char token[MAX_TOKEN_SIZE];

    int stereo, rate_divisor;



    get_token(pb, token, sizeof(token)); //"IMA_ADPCM_Sound"

    get_token(pb, token, sizeof(token)); //packet size

    sscanf(token, "%d", &iss->packet_size);

    get_token(pb, token, sizeof(token)); //File ID

    get_token(pb, token, sizeof(token)); //out size

    get_token(pb, token, sizeof(token)); //stereo

    sscanf(token, "%d", &stereo);

    get_token(pb, token, sizeof(token)); //Unknown1

    get_token(pb, token, sizeof(token)); //RateDivisor

    sscanf(token, "%d", &rate_divisor);

    get_token(pb, token, sizeof(token)); //Unknown2

    get_token(pb, token, sizeof(token)); //Version ID

    get_token(pb, token, sizeof(token)); //Size



    if (iss->packet_size <= 0) {

        av_log(s, AV_LOG_ERROR, "packet_size %d is invalid\n", iss->packet_size);

        return AVERROR_INVALIDDATA;

    }



    iss->sample_start_pos = avio_tell(pb);



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);

    st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

    st->codec->codec_id = AV_CODEC_ID_ADPCM_IMA_ISS;

    if (stereo) {

        st->codec->channels       = 2;

        st->codec->channel_layout = AV_CH_LAYOUT_STEREO;

    } else {

        st->codec->channels       = 1;

        st->codec->channel_layout = AV_CH_LAYOUT_MONO;

    }

    st->codec->sample_rate = 44100;

    if(rate_divisor > 0)

         st->codec->sample_rate /= rate_divisor;

    st->codec->bits_per_coded_sample = 4;

    st->codec->bit_rate = st->codec->channels * st->codec->sample_rate

                                      * st->codec->bits_per_coded_sample;

    st->codec->block_align = iss->packet_size;

    avpriv_set_pts_info(st, 32, 1, st->codec->sample_rate);



    return 0;

}

void do_subfco (void)

{

    T2 = T0;

    T0 = T1 - T0;

    if (likely(T0 > T1)) {

        xer_ca = 0;

    } else {

        xer_ca = 1;

    }

    if (likely(!(((~T2) ^ T1 ^ (-1)) & ((~T2) ^ T0) & (1 << 31)))) {

        xer_ov = 0;

    } else {

        xer_so = 1;

        xer_ov = 1;

    }

}

static uint16_t nvme_del_sq(NvmeCtrl *n, NvmeCmd *cmd)

{

    NvmeDeleteQ *c = (NvmeDeleteQ *)cmd;

    NvmeRequest *req, *next;

    NvmeSQueue *sq;

    NvmeCQueue *cq;

    uint16_t qid = le16_to_cpu(c->qid);



    if (!qid || nvme_check_sqid(n, qid)) {

        return NVME_INVALID_QID | NVME_DNR;

    }



    sq = n->sq[qid];

    while (!QTAILQ_EMPTY(&sq->out_req_list)) {

        req = QTAILQ_FIRST(&sq->out_req_list);

        assert(req->aiocb);

        blk_aio_cancel(req->aiocb);

    }

    if (!nvme_check_cqid(n, sq->cqid)) {

        cq = n->cq[sq->cqid];

        QTAILQ_REMOVE(&cq->sq_list, sq, entry);



        nvme_post_cqes(cq);

        QTAILQ_FOREACH_SAFE(req, &cq->req_list, entry, next) {

            if (req->sq == sq) {

                QTAILQ_REMOVE(&cq->req_list, req, entry);

                QTAILQ_INSERT_TAIL(&sq->req_list, req, entry);

            }

        }

    }



    nvme_free_sq(sq, n);

    return NVME_SUCCESS;

}

static void virtio_scsi_locate_device(VDev *vdev)

{

    const uint16_t channel = 0; /* again, it's what QEMU does */

    uint16_t target;

    static uint8_t data[16 + 8 * 63];

    ScsiLunReport *r = (void *) data;

    ScsiDevice *sdev = vdev->scsi_device;

    int i, luns;



    /* QEMU has hardcoded channel #0 in many places.

     * If this hardcoded value is ever changed, we'll need to add code for

     * vdev->config.scsi.max_channel != 0 here.

     */

    debug_print_int("config.scsi.max_channel", vdev->config.scsi.max_channel);

    debug_print_int("config.scsi.max_target ", vdev->config.scsi.max_target);

    debug_print_int("config.scsi.max_lun    ", vdev->config.scsi.max_lun);

    debug_print_int("config.scsi.max_sectors", vdev->config.scsi.max_sectors);



    if (vdev->scsi_device_selected) {

        sdev->channel = vdev->selected_scsi_device.channel;

        sdev->target = vdev->selected_scsi_device.target;

        sdev->lun = vdev->selected_scsi_device.lun;



        IPL_check(sdev->channel == 0, "non-zero channel requested");

        IPL_check(sdev->target <= vdev->config.scsi.max_target, "target# high");

        IPL_check(sdev->lun <= vdev->config.scsi.max_lun, "LUN# high");

        return;

    }



    for (target = 0; target <= vdev->config.scsi.max_target; target++) {

        sdev->channel = channel;

        sdev->target = target; /* sdev->lun will be 0 here */

        if (!scsi_report_luns(vdev, data, sizeof(data))) {

            if (resp.response == VIRTIO_SCSI_S_BAD_TARGET) {

                continue;

            }

            print_int("target", target);

            virtio_scsi_verify_response(&resp, "SCSI cannot report LUNs");

        }

        if (r->lun_list_len == 0) {

            print_int("no LUNs for target", target);

            continue;

        }

        luns = r->lun_list_len / 8;

        debug_print_int("LUNs reported", luns);

        if (luns == 1) {

            /* There is no ",lun=#" arg for -device or ",lun=0" given.

             * Hence, the only LUN reported.

             * Usually, it's 0.

             */

            sdev->lun = r->lun[0].v16[0]; /* it's returned this way */

            debug_print_int("Have to use LUN", sdev->lun);

            return; /* we have to use this device */

        }

        for (i = 0; i < luns; i++) {

            if (r->lun[i].v64) {

                /* Look for non-zero LUN - we have where to choose from */

                sdev->lun = r->lun[i].v16[0];

                debug_print_int("Will use LUN", sdev->lun);

                return; /* we have found a device */

            }

        }

    }

    panic("\n! Cannot locate virtio-scsi device !\n");

}

static void qcow2_aio_read_cb(void *opaque, int ret)

{

    QCowAIOCB *acb = opaque;

    BlockDriverState *bs = acb->common.bs;

    BDRVQcowState *s = bs->opaque;

    int index_in_cluster, n1;



    acb->hd_aiocb = NULL;

    if (ret < 0)

        goto done;



    /* post process the read buffer */

    if (!acb->cluster_offset) {

        /* nothing to do */

    } else if (acb->cluster_offset & QCOW_OFLAG_COMPRESSED) {

        /* nothing to do */

    } else {

        if (s->crypt_method) {

            qcow2_encrypt_sectors(s, acb->sector_num,  acb->cluster_data,

                acb->cluster_data, acb->cur_nr_sectors, 0, &s->aes_decrypt_key);

            qemu_iovec_reset(&acb->hd_qiov);

            qemu_iovec_copy(&acb->hd_qiov, acb->qiov, acb->bytes_done,

                acb->cur_nr_sectors * 512);

            qemu_iovec_from_buffer(&acb->hd_qiov, acb->cluster_data,

                512 * acb->cur_nr_sectors);

        }

    }



    acb->remaining_sectors -= acb->cur_nr_sectors;

    acb->sector_num += acb->cur_nr_sectors;

    acb->bytes_done += acb->cur_nr_sectors * 512;



    if (acb->remaining_sectors == 0) {

        /* request completed */

        ret = 0;

        goto done;

    }



    /* prepare next AIO request */

    acb->cur_nr_sectors = acb->remaining_sectors;

    if (s->crypt_method) {

        acb->cur_nr_sectors = MIN(acb->cur_nr_sectors,

            QCOW_MAX_CRYPT_CLUSTERS * s->cluster_sectors);

    }



    ret = qcow2_get_cluster_offset(bs, acb->sector_num << 9,

        &acb->cur_nr_sectors, &acb->cluster_offset);

    if (ret < 0) {

        goto done;

    }



    index_in_cluster = acb->sector_num & (s->cluster_sectors - 1);



    qemu_iovec_reset(&acb->hd_qiov);

    qemu_iovec_copy(&acb->hd_qiov, acb->qiov, acb->bytes_done,

        acb->cur_nr_sectors * 512);



    if (!acb->cluster_offset) {



        if (bs->backing_hd) {

            /* read from the base image */

            n1 = qcow2_backing_read1(bs->backing_hd, &acb->hd_qiov,

                acb->sector_num, acb->cur_nr_sectors);

            if (n1 > 0) {

                BLKDBG_EVENT(bs->file, BLKDBG_READ_BACKING_AIO);

                acb->hd_aiocb = bdrv_aio_readv(bs->backing_hd, acb->sector_num,

                                    &acb->hd_qiov, acb->cur_nr_sectors,

				    qcow2_aio_read_cb, acb);

                if (acb->hd_aiocb == NULL)

                    goto done;

            } else {

                ret = qcow2_schedule_bh(qcow2_aio_read_bh, acb);

                if (ret < 0)

                    goto done;

            }

        } else {

            /* Note: in this case, no need to wait */

            qemu_iovec_memset(&acb->hd_qiov, 0, 512 * acb->cur_nr_sectors);

            ret = qcow2_schedule_bh(qcow2_aio_read_bh, acb);

            if (ret < 0)

                goto done;

        }

    } else if (acb->cluster_offset & QCOW_OFLAG_COMPRESSED) {

        /* add AIO support for compressed blocks ? */

        if (qcow2_decompress_cluster(bs, acb->cluster_offset) < 0)

            goto done;



        qemu_iovec_from_buffer(&acb->hd_qiov,

            s->cluster_cache + index_in_cluster * 512,

            512 * acb->cur_nr_sectors);



        ret = qcow2_schedule_bh(qcow2_aio_read_bh, acb);

        if (ret < 0)

            goto done;

    } else {

        if ((acb->cluster_offset & 511) != 0) {

            ret = -EIO;

            goto done;

        }



        if (s->crypt_method) {

            /*

             * For encrypted images, read everything into a temporary

             * contiguous buffer on which the AES functions can work.

             */

            if (!acb->cluster_data) {

                acb->cluster_data =

                    qemu_mallocz(QCOW_MAX_CRYPT_CLUSTERS * s->cluster_size);

            }



            assert(acb->cur_nr_sectors <=

                QCOW_MAX_CRYPT_CLUSTERS * s->cluster_sectors);

            qemu_iovec_reset(&acb->hd_qiov);

            qemu_iovec_add(&acb->hd_qiov, acb->cluster_data,

                512 * acb->cur_nr_sectors);

        }



        BLKDBG_EVENT(bs->file, BLKDBG_READ_AIO);

        acb->hd_aiocb = bdrv_aio_readv(bs->file,

                            (acb->cluster_offset >> 9) + index_in_cluster,

                            &acb->hd_qiov, acb->cur_nr_sectors,

                            qcow2_aio_read_cb, acb);

        if (acb->hd_aiocb == NULL) {

            ret = -EIO;

            goto done;

        }

    }



    return;

done:

    acb->common.cb(acb->common.opaque, ret);

    qemu_iovec_destroy(&acb->hd_qiov);

    qemu_aio_release(acb);

}

static int mmsh_open(URLContext *h, const char *uri, int flags)

{

    int i, port, err;

    char httpname[256], path[256], host[128], location[1024];

    char *stream_selection;

    char headers[1024];

    MMSHContext *mmsh;

    MMSContext *mms;



    mmsh = h->priv_data = av_mallocz(sizeof(MMSHContext));

    if (!h->priv_data)

        return AVERROR(ENOMEM);

    mmsh->request_seq = h->is_streamed = 1;

    mms = &mmsh->mms;

    av_strlcpy(location, uri, sizeof(location));



    av_url_split(NULL, 0, NULL, 0,

        host, sizeof(host), &port, path, sizeof(path), location);

    if (port<0)

        port = 80; // default mmsh protocol port

    ff_url_join(httpname, sizeof(httpname), "http", NULL, host, port, path);



    if (url_alloc(&mms->mms_hd, httpname, URL_RDONLY) < 0) {

        return AVERROR(EIO);

    }



    snprintf(headers, sizeof(headers),

             "Accept: */*\r\n"

             USERAGENT

             "Host: %s:%d\r\n"

             "Pragma: no-cache,rate=1.000000,stream-time=0,"

             "stream-offset=0:0,request-context=%u,max-duration=0\r\n"

             CLIENTGUID

             "Connection: Close\r\n\r\n",

             host, port, mmsh->request_seq++);

    ff_http_set_headers(mms->mms_hd, headers);



    err = url_connect(mms->mms_hd);

    if (err) {

        goto fail;

    }

    err = get_http_header_data(mmsh);

    if (err) {

        av_log(NULL, AV_LOG_ERROR, "Get http header data failed!\n");

        goto fail;

    }



    // close the socket and then reopen it for sending the second play request.

    url_close(mms->mms_hd);

    memset(headers, 0, sizeof(headers));

    if (url_alloc(&mms->mms_hd, httpname, URL_RDONLY) < 0) {

        return AVERROR(EIO);

    }

    stream_selection = av_mallocz(mms->stream_num * 19 + 1);

    if (!stream_selection)

        return AVERROR(ENOMEM);

    for (i = 0; i < mms->stream_num; i++) {

        char tmp[20];

        err = snprintf(tmp, sizeof(tmp), "ffff:%d:0 ", mms->streams[i].id);

        if (err < 0)

            goto fail;

        av_strlcat(stream_selection, tmp, mms->stream_num * 19 + 1);

    }

    // send play request

    err = snprintf(headers, sizeof(headers),

                   "Accept: */*\r\n"

                   USERAGENT

                   "Host: %s:%d\r\n"

                   "Pragma: no-cache,rate=1.000000,request-context=%u\r\n"

                   "Pragma: xPlayStrm=1\r\n"

                   CLIENTGUID

                   "Pragma: stream-switch-count=%d\r\n"

                   "Pragma: stream-switch-entry=%s\r\n"

                   "Connection: Close\r\n\r\n",

                   host, port, mmsh->request_seq++, mms->stream_num, stream_selection);

    av_freep(&stream_selection);

    if (err < 0) {

        av_log(NULL, AV_LOG_ERROR, "Build play request failed!\n");

        goto fail;

    }

    dprintf(NULL, "out_buffer is %s", headers);

    ff_http_set_headers(mms->mms_hd, headers);



    err = url_connect(mms->mms_hd);

    if (err) {

          goto fail;

    }



    err = get_http_header_data(mmsh);

    if (err) {

        av_log(NULL, AV_LOG_ERROR, "Get http header data failed!\n");

        goto fail;

    }



    dprintf(NULL, "Connection successfully open\n");

    return 0;

fail:

    av_freep(&stream_selection);

    mmsh_close(h);

    dprintf(NULL, "Connection failed with error %d\n", err);

    return err;

}

static void t_gen_btst(TCGv d, TCGv a, TCGv b)

{

        TCGv sbit;

        TCGv bset;

        TCGv t0;

	int l1;



        /* des ref:

           The N flag is set according to the selected bit in the dest reg.

           The Z flag is set if the selected bit and all bits to the right are

           zero.

           The X flag is cleared.

           Other flags are left untouched.

           The destination reg is not affected.



        unsigned int fz, sbit, bset, mask, masked_t0;



        sbit = T1 & 31;

        bset = !!(T0 & (1 << sbit));

        mask = sbit == 31 ? -1 : (1 << (sbit + 1)) - 1;

        masked_t0 = T0 & mask;

        fz = !(masked_t0 | bset);



        // Clear the X, N and Z flags.

        T0 = env->pregs[PR_CCS] & ~(X_FLAG | N_FLAG | Z_FLAG);

        // Set the N and Z flags accordingly.

        T0 |= (bset << 3) | (fz << 2);

        */



	l1 = gen_new_label();

        sbit = tcg_temp_new(TCG_TYPE_TL);

        bset = tcg_temp_new(TCG_TYPE_TL);

        t0 = tcg_temp_new(TCG_TYPE_TL);



        /* Compute bset and sbit.  */

        tcg_gen_andi_tl(sbit, b, 31);

        tcg_gen_shl_tl(t0, tcg_const_tl(1), sbit);

        tcg_gen_and_tl(bset, a, t0);

        tcg_gen_shr_tl(bset, bset, sbit);

	/* Displace to N_FLAG.  */

        tcg_gen_shli_tl(bset, bset, 3);



        tcg_gen_shl_tl(sbit, tcg_const_tl(2), sbit);

        tcg_gen_subi_tl(sbit, sbit, 1);

        tcg_gen_and_tl(sbit, a, sbit);



        tcg_gen_andi_tl(d, cpu_PR[PR_CCS], ~(X_FLAG | N_FLAG | Z_FLAG));

	/* or in the N_FLAG.  */

        tcg_gen_or_tl(d, d, bset);

	tcg_gen_brcondi_tl(TCG_COND_NE, sbit, 0, l1);

	/* or in the Z_FLAG.  */

	tcg_gen_ori_tl(d, d, Z_FLAG);

	gen_set_label(l1);



        tcg_temp_free(sbit);

        tcg_temp_free(bset);

}

read_f(int argc, char **argv)

{

	struct timeval t1, t2;

	int Cflag = 0, pflag = 0, qflag = 0, vflag = 0;

	int Pflag = 0, sflag = 0, lflag = 0, bflag = 0;

	int c, cnt;

	char *buf;

	int64_t offset;

	int count;

        /* Some compilers get confused and warn if this is not initialized.  */

        int total = 0;

	int pattern = 0, pattern_offset = 0, pattern_count = 0;



	while ((c = getopt(argc, argv, "bCl:pP:qs:v")) != EOF) {

		switch (c) {

		case 'b':

			bflag = 1;

			break;

		case 'C':

			Cflag = 1;

			break;

		case 'l':

			lflag = 1;

			pattern_count = cvtnum(optarg);

			if (pattern_count < 0) {

				printf("non-numeric length argument -- %s\n", optarg);

				return 0;

			}

			break;

		case 'p':

			pflag = 1;

			break;

		case 'P':

			Pflag = 1;

			pattern = atoi(optarg);

			break;

		case 'q':

			qflag = 1;

			break;

		case 's':

			sflag = 1;

			pattern_offset = cvtnum(optarg);

			if (pattern_offset < 0) {

				printf("non-numeric length argument -- %s\n", optarg);

				return 0;

			}

			break;

		case 'v':

			vflag = 1;

			break;

		default:

			return command_usage(&read_cmd);

		}

	}



	if (optind != argc - 2)

		return command_usage(&read_cmd);



	if (bflag && pflag) {

		printf("-b and -p cannot be specified at the same time\n");

		return 0;

	}



	offset = cvtnum(argv[optind]);

	if (offset < 0) {

		printf("non-numeric length argument -- %s\n", argv[optind]);

		return 0;

	}



	optind++;

	count = cvtnum(argv[optind]);

	if (count < 0) {

		printf("non-numeric length argument -- %s\n", argv[optind]);

		return 0;

	}



    if (!Pflag && (lflag || sflag)) {

        return command_usage(&read_cmd);

    }



    if (!lflag) {

        pattern_count = count - pattern_offset;

    }



    if ((pattern_count < 0) || (pattern_count + pattern_offset > count))  {

        printf("pattern verfication range exceeds end of read data\n");

        return 0;

    }



	if (!pflag)

		if (offset & 0x1ff) {

			printf("offset %lld is not sector aligned\n",

				(long long)offset);

			return 0;



		if (count & 0x1ff) {

			printf("count %d is not sector aligned\n",

				count);

			return 0;

		}

	}



	buf = qemu_io_alloc(count, 0xab);



	gettimeofday(&t1, NULL);

	if (pflag)

		cnt = do_pread(buf, offset, count, &total);

	else if (bflag)

		cnt = do_load_vmstate(buf, offset, count, &total);

	else

		cnt = do_read(buf, offset, count, &total);

	gettimeofday(&t2, NULL);



	if (cnt < 0) {

		printf("read failed: %s\n", strerror(-cnt));

		goto out;

	}



	if (Pflag) {

		void* cmp_buf = malloc(pattern_count);

		memset(cmp_buf, pattern, pattern_count);

		if (memcmp(buf + pattern_offset, cmp_buf, pattern_count)) {

			printf("Pattern verification failed at offset %lld, "

				"%d bytes\n",

				(long long) offset + pattern_offset, pattern_count);

		}

		free(cmp_buf);

	}



	if (qflag)

		goto out;



        if (vflag)

		dump_buffer(buf, offset, count);



	/* Finally, report back -- -C gives a parsable format */

	t2 = tsub(t2, t1);

	print_report("read", &t2, offset, count, total, cnt, Cflag);



out:

	qemu_io_free(buf);



	return 0;

}

