static void jpeg_put_comments(MpegEncContext *s)

{

    PutBitContext *p = &s->pb;

    int size;

    uint8_t *ptr;



    if (s->aspect_ratio_info /* && !lossless */)

    {

    /* JFIF header */

    put_marker(p, APP0);

    put_bits(p, 16, 16);

    put_string(p, "JFIF"); /* this puts the trailing zero-byte too */

    put_bits(p, 16, 0x0201); /* v 1.02 */

    put_bits(p, 8, 0); /* units type: 0 - aspect ratio */

    put_bits(p, 16, s->avctx->sample_aspect_ratio.num);

    put_bits(p, 16, s->avctx->sample_aspect_ratio.den);

    put_bits(p, 8, 0); /* thumbnail width */

    put_bits(p, 8, 0); /* thumbnail height */

    }



    /* comment */

    if(!(s->flags & CODEC_FLAG_BITEXACT)){

        put_marker(p, COM);

        flush_put_bits(p);

        ptr = pbBufPtr(p);

        put_bits(p, 16, 0); /* patched later */

        put_string(p, LIBAVCODEC_IDENT);

        size = strlen(LIBAVCODEC_IDENT)+3;

        ptr[0] = size >> 8;

        ptr[1] = size;

    }

}

static av_always_inline int vorbis_residue_decode_internal(vorbis_context *vc,

                                                           vorbis_residue *vr,

                                                           unsigned ch,

                                                           uint8_t *do_not_decode,

                                                           float *vec,

                                                           unsigned vlen,

                                                           unsigned ch_left,

                                                           int vr_type)

{

    GetBitContext *gb = &vc->gb;

    unsigned c_p_c        = vc->codebooks[vr->classbook].dimensions;

    uint8_t *classifs = vr->classifs;

    unsigned pass, ch_used, i, j, k, l;

    unsigned max_output = (ch - 1) * vlen;

    int ptns_to_read = vr->ptns_to_read;

    int libvorbis_bug = 0;



    if (vr_type == 2) {

        for (j = 1; j < ch; ++j)

            do_not_decode[0] &= do_not_decode[j];  // FIXME - clobbering input

        if (do_not_decode[0])

            return 0;

        ch_used = 1;

        max_output += vr->end / ch;

    } else {

        ch_used = ch;

        max_output += vr->end;

    }



    if (max_output > ch_left * vlen) {

        if (max_output <= ch_left * vlen + vr->partition_size*ch_used/ch) {

            ptns_to_read--;

            libvorbis_bug = 1;

        } else {

            av_log(vc->avctx, AV_LOG_ERROR, "Insufficient output buffer\n");

            return AVERROR_INVALIDDATA;

        }

    }



    av_dlog(NULL, " residue type 0/1/2 decode begin, ch: %d  cpc %d  \n", ch, c_p_c);



    for (pass = 0; pass <= vr->maxpass; ++pass) { // FIXME OPTIMIZE?

        int voffset, partition_count, j_times_ptns_to_read;



        voffset = vr->begin;

        for (partition_count = 0; partition_count < ptns_to_read;) {  // SPEC        error

            if (!pass) {

                int ret;

                if ((ret = setup_classifs(vc, vr, do_not_decode, ch_used, partition_count)) < 0)

                    return ret;

            }

            for (i = 0; (i < c_p_c) && (partition_count < ptns_to_read); ++i) {

                for (j_times_ptns_to_read = 0, j = 0; j < ch_used; ++j) {

                    unsigned voffs;



                    if (!do_not_decode[j]) {

                        unsigned vqclass = classifs[j_times_ptns_to_read + partition_count];

                        int vqbook  = vr->books[vqclass][pass];



                        if (vqbook >= 0 && vc->codebooks[vqbook].codevectors) {

                            unsigned coffs;

                            unsigned dim  = vc->codebooks[vqbook].dimensions;

                            unsigned step = FASTDIV(vr->partition_size << 1, dim << 1);

                            vorbis_codebook codebook = vc->codebooks[vqbook];



                            if (vr_type == 0) {



                                voffs = voffset+j*vlen;

                                for (k = 0; k < step; ++k) {

                                    coffs = get_vlc2(gb, codebook.vlc.table, codebook.nb_bits, 3) * dim;

                                    for (l = 0; l < dim; ++l)

                                        vec[voffs + k + l * step] += codebook.codevectors[coffs + l];

                                }

                            } else if (vr_type == 1) {

                                voffs = voffset + j * vlen;

                                for (k = 0; k < step; ++k) {

                                    coffs = get_vlc2(gb, codebook.vlc.table, codebook.nb_bits, 3) * dim;

                                    for (l = 0; l < dim; ++l, ++voffs) {

                                        vec[voffs]+=codebook.codevectors[coffs+l];



                                        av_dlog(NULL, " pass %d offs: %d curr: %f change: %f cv offs.: %d  \n",

                                                pass, voffs, vec[voffs], codebook.codevectors[coffs+l], coffs);

                                    }

                                }

                            } else if (vr_type == 2 && ch == 2 && (voffset & 1) == 0 && (dim & 1) == 0) { // most frequent case optimized

                                voffs = voffset >> 1;



                                if (dim == 2) {

                                    for (k = 0; k < step; ++k) {

                                        coffs = get_vlc2(gb, codebook.vlc.table, codebook.nb_bits, 3) * 2;

                                        vec[voffs + k       ] += codebook.codevectors[coffs    ];

                                        vec[voffs + k + vlen] += codebook.codevectors[coffs + 1];

                                    }

                                } else if (dim == 4) {

                                    for (k = 0; k < step; ++k, voffs += 2) {

                                        coffs = get_vlc2(gb, codebook.vlc.table, codebook.nb_bits, 3) * 4;

                                        vec[voffs           ] += codebook.codevectors[coffs    ];

                                        vec[voffs + 1       ] += codebook.codevectors[coffs + 2];

                                        vec[voffs + vlen    ] += codebook.codevectors[coffs + 1];

                                        vec[voffs + vlen + 1] += codebook.codevectors[coffs + 3];

                                    }

                                } else

                                for (k = 0; k < step; ++k) {

                                    coffs = get_vlc2(gb, codebook.vlc.table, codebook.nb_bits, 3) * dim;

                                    for (l = 0; l < dim; l += 2, voffs++) {

                                        vec[voffs       ] += codebook.codevectors[coffs + l    ];

                                        vec[voffs + vlen] += codebook.codevectors[coffs + l + 1];



                                        av_dlog(NULL, " pass %d offs: %d curr: %f change: %f cv offs.: %d+%d  \n",

                                                pass, voffset / ch + (voffs % ch) * vlen,

                                                vec[voffset / ch + (voffs % ch) * vlen],

                                                codebook.codevectors[coffs + l], coffs, l);

                                    }

                                }



                            } else if (vr_type == 2) {

                                unsigned voffs_div = FASTDIV(voffset << 1, ch <<1);

                                unsigned voffs_mod = voffset - voffs_div * ch;



                                for (k = 0; k < step; ++k) {

                                    coffs = get_vlc2(gb, codebook.vlc.table, codebook.nb_bits, 3) * dim;

                                    for (l = 0; l < dim; ++l) {

                                        vec[voffs_div + voffs_mod * vlen] +=

                                            codebook.codevectors[coffs + l];



                                        av_dlog(NULL, " pass %d offs: %d curr: %f change: %f cv offs.: %d+%d  \n",

                                                pass, voffs_div + voffs_mod * vlen,

                                                vec[voffs_div + voffs_mod * vlen],

                                                codebook.codevectors[coffs + l], coffs, l);



                                        if (++voffs_mod == ch) {

                                            voffs_div++;

                                            voffs_mod = 0;

                                        }

                                    }

                                }

                            }

                        }

                    }

                    j_times_ptns_to_read += ptns_to_read;

                }

                ++partition_count;

                voffset += vr->partition_size;

            }

        }

        if (libvorbis_bug && !pass) {

            for (j = 0; j < ch_used; ++j) {

                if (!do_not_decode[j]) {

                    get_vlc2(&vc->gb, vc->codebooks[vr->classbook].vlc.table,

                                vc->codebooks[vr->classbook].nb_bits, 3);

                }

            }

        }

    }

    return 0;

}

static int asf_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    ASFContext *asf = s->priv_data;

    GUID g;

    ByteIOContext *pb = &s->pb;

    AVStream *st;

    ASFStream *asf_st;

    int size, i, bps;

    INT64 gsize;



    get_guid(pb, &g);

    if (memcmp(&g, &asf_header, sizeof(GUID)))

        goto fail;

    get_le64(pb);

    get_le32(pb);

    get_byte(pb);

    get_byte(pb);

    memset(&asf->asfid2avid, -1, sizeof(asf->asfid2avid));

    for(;;) {

        get_guid(pb, &g);

        gsize = get_le64(pb);

#ifdef DEBUG

        printf("%08Lx: ", url_ftell(pb) - 24);

        print_guid(&g);

        printf("  size=0x%Lx\n", gsize);

#endif

        if (gsize < 24)

            goto fail;

        if (!memcmp(&g, &file_header, sizeof(GUID))) {

            get_guid(pb, &asf->hdr.guid);

	    asf->hdr.file_size		= get_le64(pb);

	    asf->hdr.create_time	= get_le64(pb);

	    asf->hdr.packets_count	= get_le64(pb);

	    asf->hdr.play_time		= get_le64(pb);

	    asf->hdr.send_time		= get_le64(pb);

	    asf->hdr.preroll		= get_le32(pb);

	    asf->hdr.ignore		= get_le32(pb);

	    asf->hdr.flags		= get_le32(pb);

	    asf->hdr.min_pktsize	= get_le32(pb);

	    asf->hdr.max_pktsize	= get_le32(pb);

	    asf->hdr.max_bitrate	= get_le32(pb);

	    asf->packet_size = asf->hdr.max_pktsize;

            asf->nb_packets = asf->hdr.packets_count;

        } else if (!memcmp(&g, &stream_header, sizeof(GUID))) {

            int type, id, total_size;

            unsigned int tag1;

            INT64 pos1, pos2;



            pos1 = url_ftell(pb);



            st = av_mallocz(sizeof(AVStream));

            if (!st)

                goto fail;

            s->streams[s->nb_streams] = st;

            asf_st = av_mallocz(sizeof(ASFStream));

            if (!asf_st)

                goto fail;

            st->priv_data = asf_st;

	    st->time_length = (asf->hdr.send_time - asf->hdr.preroll) / 10000;

            get_guid(pb, &g);

            if (!memcmp(&g, &audio_stream, sizeof(GUID))) {

                type = CODEC_TYPE_AUDIO;

            } else if (!memcmp(&g, &video_stream, sizeof(GUID))) {

                type = CODEC_TYPE_VIDEO;

            } else {

                goto fail;

            }

            get_guid(pb, &g);

            total_size = get_le64(pb);

            get_le32(pb);

            get_le32(pb);

	    st->id = get_le16(pb) & 0x7f; /* stream id */

            // mapping of asf ID to AV stream ID;

            asf->asfid2avid[st->id] = s->nb_streams++;



            get_le32(pb);

	    st->codec.codec_type = type;

            st->codec.frame_rate = 1000; // in packet ticks

            if (type == CODEC_TYPE_AUDIO) {

                id = get_le16(pb);

                st->codec.codec_tag = id;

                st->codec.channels = get_le16(pb);

		st->codec.sample_rate = get_le32(pb);

                st->codec.bit_rate = get_le32(pb) * 8;

		st->codec.block_align = get_le16(pb); /* block align */

                bps = get_le16(pb); /* bits per sample */

                st->codec.codec_id = wav_codec_get_id(id, bps);

		size = get_le16(pb);

		if (size > 0) {

		    st->extra_data = av_mallocz(size);

		    get_buffer(pb, st->extra_data, size);

		    st->extra_data_size = size;

		}

		/* We have to init the frame size at some point .... */

		pos2 = url_ftell(pb);

		if (gsize > (pos2 + 8 - pos1 + 24)) {

		    asf_st->ds_span = get_byte(pb);

		    asf_st->ds_packet_size = get_le16(pb);

		    asf_st->ds_chunk_size = get_le16(pb);

		    asf_st->ds_data_size = get_le16(pb);

		    asf_st->ds_silence_data = get_byte(pb);

		}

		//printf("Descrambling: ps:%d cs:%d ds:%d s:%d  sd:%d\n",

		//       asf_st->ds_packet_size, asf_st->ds_chunk_size,

		//       asf_st->ds_data_size, asf_st->ds_span, asf_st->ds_silence_data);

		if (asf_st->ds_span > 1) {

		    if (!asf_st->ds_chunk_size

			|| (asf_st->ds_packet_size/asf_st->ds_chunk_size <= 1))

			asf_st->ds_span = 0; // disable descrambling

		}

                switch (st->codec.codec_id) {

                case CODEC_ID_MP3LAME:

                    st->codec.frame_size = MPA_FRAME_SIZE;

                    break;

                case CODEC_ID_PCM_S16LE:

                case CODEC_ID_PCM_S16BE:

                case CODEC_ID_PCM_U16LE:

                case CODEC_ID_PCM_U16BE:

                case CODEC_ID_PCM_S8:

                case CODEC_ID_PCM_U8:

                case CODEC_ID_PCM_ALAW:

                case CODEC_ID_PCM_MULAW:

                    st->codec.frame_size = 1;

                    break;

                default:

                    /* This is probably wrong, but it prevents a crash later */

                    st->codec.frame_size = 1;

                    break;

                }

            } else {

		get_le32(pb);

                get_le32(pb);

                get_byte(pb);

                size = get_le16(pb); /* size */

                get_le32(pb); /* size */

                st->codec.width = get_le32(pb);

		st->codec.height = get_le32(pb);

                /* not available for asf */

                get_le16(pb); /* panes */

                get_le16(pb); /* depth */

                tag1 = get_le32(pb);

		url_fskip(pb, 20);

		if (size > 40) {

		    st->extra_data_size = size - 40;

		    st->extra_data = av_mallocz(st->extra_data_size);

		    get_buffer(pb, st->extra_data, st->extra_data_size);

		}

                st->codec.codec_tag = tag1;

		st->codec.codec_id = codec_get_id(codec_asf_bmp_tags, tag1);

            }

            pos2 = url_ftell(pb);

            url_fskip(pb, gsize - (pos2 - pos1 + 24));

        } else if (!memcmp(&g, &data_header, sizeof(GUID))) {

            break;

        } else if (!memcmp(&g, &comment_header, sizeof(GUID))) {

            int len1, len2, len3, len4, len5;



            len1 = get_le16(pb);

            len2 = get_le16(pb);

            len3 = get_le16(pb);

            len4 = get_le16(pb);

            len5 = get_le16(pb);

            get_str16_nolen(pb, len1, s->title, sizeof(s->title));

            get_str16_nolen(pb, len2, s->author, sizeof(s->author));

            get_str16_nolen(pb, len3, s->copyright, sizeof(s->copyright));

            get_str16_nolen(pb, len4, s->comment, sizeof(s->comment));

	    url_fskip(pb, len5);

#if 0

        } else if (!memcmp(&g, &head1_guid, sizeof(GUID))) {

            int v1, v2;

            get_guid(pb, &g);

            v1 = get_le32(pb);

            v2 = get_le16(pb);

        } else if (!memcmp(&g, &codec_comment_header, sizeof(GUID))) {

            int len, v1, n, num;

            char str[256], *q;

            char tag[16];



            get_guid(pb, &g);

            print_guid(&g);



            n = get_le32(pb);

            for(i=0;i<n;i++) {

                num = get_le16(pb); /* stream number */

                get_str16(pb, str, sizeof(str));

                get_str16(pb, str, sizeof(str));

                len = get_le16(pb);

                q = tag;

                while (len > 0) {

                    v1 = get_byte(pb);

                    if ((q - tag) < sizeof(tag) - 1)

                        *q++ = v1;

                    len--;

                }

                *q = '\0';

            }

#endif

        } else if (url_feof(pb)) {

            goto fail;

        } else {

            url_fseek(pb, gsize - 24, SEEK_CUR);

        }

    }

    get_guid(pb, &g);

    get_le64(pb);

    get_byte(pb);

    get_byte(pb);

    if (url_feof(pb))

        goto fail;

    asf->data_offset = url_ftell(pb);

    asf->packet_size_left = 0;



    return 0;



 fail:

    for(i=0;i<s->nb_streams;i++) {

        AVStream *st = s->streams[i];

	if (st) {

	    av_free(st->priv_data);

	    av_free(st->extra_data);

	}

        av_free(st);

    }

    //av_free(asf);

    return -1;

}

static void guess_mv(ERContext *s)

{

    uint8_t *fixed = s->er_temp_buffer;

#define MV_FROZEN    3

#define MV_CHANGED   2

#define MV_UNCHANGED 1

    const int mb_stride = s->mb_stride;

    const int mb_width  = s->mb_width;

    int mb_height = s->mb_height;

    int i, depth, num_avail;

    int mb_x, mb_y, mot_step, mot_stride;



    if (s->last_pic.f && s->last_pic.f->data[0])

        mb_height = FFMIN(mb_height, (s->last_pic.f->height+15)>>4);

    if (s->next_pic.f && s->next_pic.f->data[0])

        mb_height = FFMIN(mb_height, (s->next_pic.f->height+15)>>4);



    set_mv_strides(s, &mot_step, &mot_stride);



    num_avail = 0;

    if (s->last_pic.motion_val[0])

        ff_thread_await_progress(s->last_pic.tf, mb_height-1, 0);

    for (i = 0; i < mb_width * mb_height; i++) {

        const int mb_xy = s->mb_index2xy[i];

        int f = 0;

        int error = s->error_status_table[mb_xy];



        if (IS_INTRA(s->cur_pic.mb_type[mb_xy]))

            f = MV_FROZEN; // intra // FIXME check

        if (!(error & ER_MV_ERROR))

            f = MV_FROZEN; // inter with undamaged MV



        fixed[mb_xy] = f;

        if (f == MV_FROZEN)

            num_avail++;

        else if(s->last_pic.f->data[0] && s->last_pic.motion_val[0]){

            const int mb_y= mb_xy / s->mb_stride;

            const int mb_x= mb_xy % s->mb_stride;

            const int mot_index= (mb_x + mb_y*mot_stride) * mot_step;

            s->cur_pic.motion_val[0][mot_index][0]= s->last_pic.motion_val[0][mot_index][0];

            s->cur_pic.motion_val[0][mot_index][1]= s->last_pic.motion_val[0][mot_index][1];

            s->cur_pic.ref_index[0][4*mb_xy]      = s->last_pic.ref_index[0][4*mb_xy];

        }

    }



    if ((!(s->avctx->error_concealment&FF_EC_GUESS_MVS)) ||

        num_avail <= mb_width / 2) {

        for (mb_y = 0; mb_y < mb_height; mb_y++) {

            for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

                const int mb_xy = mb_x + mb_y * s->mb_stride;

                int mv_dir = (s->last_pic.f && s->last_pic.f->data[0]) ? MV_DIR_FORWARD : MV_DIR_BACKWARD;



                if (IS_INTRA(s->cur_pic.mb_type[mb_xy]))

                    continue;

                if (!(s->error_status_table[mb_xy] & ER_MV_ERROR))

                    continue;



                s->mv[0][0][0] = 0;

                s->mv[0][0][1] = 0;

                s->decode_mb(s->opaque, 0, mv_dir, MV_TYPE_16X16, &s->mv,

                             mb_x, mb_y, 0, 0);

            }

        }

        return;

    }



    for (depth = 0; ; depth++) {

        int changed, pass, none_left;



        none_left = 1;

        changed   = 1;

        for (pass = 0; (changed || pass < 2) && pass < 10; pass++) {

            int mb_x, mb_y;

            int score_sum = 0;



            changed = 0;

            for (mb_y = 0; mb_y < mb_height; mb_y++) {

                for (mb_x = (mb_y ^ pass) & 1; mb_x < s->mb_width; mb_x+=2) {

                    const int mb_xy        = mb_x + mb_y * s->mb_stride;

                    int mv_predictor[8][2] = { { 0 } };

                    int ref[8]             = { 0 };

                    int pred_count         = 0;

                    int j;

                    int best_score         = 256 * 256 * 256 * 64;

                    int best_pred          = 0;

                    const int mot_index    = (mb_x + mb_y * mot_stride) * mot_step;

                    int prev_x = 0, prev_y = 0, prev_ref = 0;



                    if (fixed[mb_xy] == MV_FROZEN)

                        continue;

                    av_assert1(!IS_INTRA(s->cur_pic.mb_type[mb_xy]));

                    av_assert1(s->last_pic.f && s->last_pic.f->data[0]);



                    j = 0;

                    if (mb_x > 0             && fixed[mb_xy - 1]         == MV_FROZEN)

                        j = 1;

                    if (mb_x + 1 < mb_width  && fixed[mb_xy + 1]         == MV_FROZEN)

                        j = 1;

                    if (mb_y > 0             && fixed[mb_xy - mb_stride] == MV_FROZEN)

                        j = 1;

                    if (mb_y + 1 < mb_height && fixed[mb_xy + mb_stride] == MV_FROZEN)

                        j = 1;

                    if (j == 0)

                        continue;



                    j = 0;

                    if (mb_x > 0             && fixed[mb_xy - 1        ] == MV_CHANGED)

                        j = 1;

                    if (mb_x + 1 < mb_width  && fixed[mb_xy + 1        ] == MV_CHANGED)

                        j = 1;

                    if (mb_y > 0             && fixed[mb_xy - mb_stride] == MV_CHANGED)

                        j = 1;

                    if (mb_y + 1 < mb_height && fixed[mb_xy + mb_stride] == MV_CHANGED)

                        j = 1;

                    if (j == 0 && pass > 1)

                        continue;



                    none_left = 0;



                    if (mb_x > 0 && fixed[mb_xy - 1]) {

                        mv_predictor[pred_count][0] =

                            s->cur_pic.motion_val[0][mot_index - mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->cur_pic.motion_val[0][mot_index - mot_step][1];

                        ref[pred_count] =

                            s->cur_pic.ref_index[0][4 * (mb_xy - 1)];

                        pred_count++;

                    }

                    if (mb_x + 1 < mb_width && fixed[mb_xy + 1]) {

                        mv_predictor[pred_count][0] =

                            s->cur_pic.motion_val[0][mot_index + mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->cur_pic.motion_val[0][mot_index + mot_step][1];

                        ref[pred_count] =

                            s->cur_pic.ref_index[0][4 * (mb_xy + 1)];

                        pred_count++;

                    }

                    if (mb_y > 0 && fixed[mb_xy - mb_stride]) {

                        mv_predictor[pred_count][0] =

                            s->cur_pic.motion_val[0][mot_index - mot_stride * mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->cur_pic.motion_val[0][mot_index - mot_stride * mot_step][1];

                        ref[pred_count] =

                            s->cur_pic.ref_index[0][4 * (mb_xy - s->mb_stride)];

                        pred_count++;

                    }

                    if (mb_y + 1<mb_height && fixed[mb_xy + mb_stride]) {

                        mv_predictor[pred_count][0] =

                            s->cur_pic.motion_val[0][mot_index + mot_stride * mot_step][0];

                        mv_predictor[pred_count][1] =

                            s->cur_pic.motion_val[0][mot_index + mot_stride * mot_step][1];

                        ref[pred_count] =

                            s->cur_pic.ref_index[0][4 * (mb_xy + s->mb_stride)];

                        pred_count++;

                    }

                    if (pred_count == 0)

                        continue;



                    if (pred_count > 1) {

                        int sum_x = 0, sum_y = 0, sum_r = 0;

                        int max_x, max_y, min_x, min_y, max_r, min_r;



                        for (j = 0; j < pred_count; j++) {

                            sum_x += mv_predictor[j][0];

                            sum_y += mv_predictor[j][1];

                            sum_r += ref[j];

                            if (j && ref[j] != ref[j - 1])

                                goto skip_mean_and_median;

                        }



                        /* mean */

                        mv_predictor[pred_count][0] = sum_x / j;

                        mv_predictor[pred_count][1] = sum_y / j;

                                 ref[pred_count]    = sum_r / j;



                        /* median */

                        if (pred_count >= 3) {

                            min_y = min_x = min_r =  99999;

                            max_y = max_x = max_r = -99999;

                        } else {

                            min_x = min_y = max_x = max_y = min_r = max_r = 0;

                        }

                        for (j = 0; j < pred_count; j++) {

                            max_x = FFMAX(max_x, mv_predictor[j][0]);

                            max_y = FFMAX(max_y, mv_predictor[j][1]);

                            max_r = FFMAX(max_r, ref[j]);

                            min_x = FFMIN(min_x, mv_predictor[j][0]);

                            min_y = FFMIN(min_y, mv_predictor[j][1]);

                            min_r = FFMIN(min_r, ref[j]);

                        }

                        mv_predictor[pred_count + 1][0] = sum_x - max_x - min_x;

                        mv_predictor[pred_count + 1][1] = sum_y - max_y - min_y;

                                 ref[pred_count + 1]    = sum_r - max_r - min_r;



                        if (pred_count == 4) {

                            mv_predictor[pred_count + 1][0] /= 2;

                            mv_predictor[pred_count + 1][1] /= 2;

                                     ref[pred_count + 1]    /= 2;

                        }

                        pred_count += 2;

                    }



skip_mean_and_median:

                    /* zero MV */

                    pred_count++;



                    prev_x   = s->cur_pic.motion_val[0][mot_index][0];

                    prev_y   = s->cur_pic.motion_val[0][mot_index][1];

                    prev_ref = s->cur_pic.ref_index[0][4 * mb_xy];



                    /* last MV */

                    mv_predictor[pred_count][0] = prev_x;

                    mv_predictor[pred_count][1] = prev_y;

                             ref[pred_count]    = prev_ref;

                    pred_count++;



                    for (j = 0; j < pred_count; j++) {

                        int *linesize = s->cur_pic.f->linesize;

                        int score = 0;

                        uint8_t *src = s->cur_pic.f->data[0] +

                                       mb_x * 16 + mb_y * 16 * linesize[0];



                        s->cur_pic.motion_val[0][mot_index][0] =

                            s->mv[0][0][0] = mv_predictor[j][0];

                        s->cur_pic.motion_val[0][mot_index][1] =

                            s->mv[0][0][1] = mv_predictor[j][1];



                        // predictor intra or otherwise not available

                        if (ref[j] < 0)

                            continue;



                        s->decode_mb(s->opaque, ref[j], MV_DIR_FORWARD,

                                     MV_TYPE_16X16, &s->mv, mb_x, mb_y, 0, 0);



                        if (mb_x > 0 && fixed[mb_xy - 1]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k * linesize[0] - 1] -

                                               src[k * linesize[0]]);

                        }

                        if (mb_x + 1 < mb_width && fixed[mb_xy + 1]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k * linesize[0] + 15] -

                                               src[k * linesize[0] + 16]);

                        }

                        if (mb_y > 0 && fixed[mb_xy - mb_stride]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k - linesize[0]] - src[k]);

                        }

                        if (mb_y + 1 < mb_height && fixed[mb_xy + mb_stride]) {

                            int k;

                            for (k = 0; k < 16; k++)

                                score += FFABS(src[k + linesize[0] * 15] -

                                               src[k + linesize[0] * 16]);

                        }



                        if (score <= best_score) { // <= will favor the last MV

                            best_score = score;

                            best_pred  = j;

                        }

                    }

                    score_sum += best_score;

                    s->mv[0][0][0] = mv_predictor[best_pred][0];

                    s->mv[0][0][1] = mv_predictor[best_pred][1];



                    for (i = 0; i < mot_step; i++)

                        for (j = 0; j < mot_step; j++) {

                            s->cur_pic.motion_val[0][mot_index + i + j * mot_stride][0] = s->mv[0][0][0];

                            s->cur_pic.motion_val[0][mot_index + i + j * mot_stride][1] = s->mv[0][0][1];

                        }



                    s->decode_mb(s->opaque, ref[best_pred], MV_DIR_FORWARD,

                                 MV_TYPE_16X16, &s->mv, mb_x, mb_y, 0, 0);





                    if (s->mv[0][0][0] != prev_x || s->mv[0][0][1] != prev_y) {

                        fixed[mb_xy] = MV_CHANGED;

                        changed++;

                    } else

                        fixed[mb_xy] = MV_UNCHANGED;

                }

            }

        }



        if (none_left)

            return;



        for (i = 0; i < mb_width * mb_height; i++) {

            int mb_xy = s->mb_index2xy[i];

            if (fixed[mb_xy])

                fixed[mb_xy] = MV_FROZEN;

        }

    }

}

static inline void gen_neon_narrow(int size, TCGv dest, TCGv src)

{

    switch (size) {

    case 0: gen_helper_neon_narrow_u8(dest, src); break;

    case 1: gen_helper_neon_narrow_u16(dest, src); break;

    case 2: tcg_gen_trunc_i64_i32(dest, src); break;

