                    ctx->vol_sprite_usage == GMC_SPRITE) {

                    s->current_picture.mb_type[xy] = MB_TYPE_SKIP  |

                                                     MB_TYPE_GMC   |

                                                     MB_TYPE_16x16 |

                                                     MB_TYPE_L0;

                    s->mcsel       = 1;

                    s->mv[0][0][0] = get_amv(ctx, 0);

                    s->mv[0][0][1] = get_amv(ctx, 1);

                    s->mb_skipped  = 0;

                } else {

                    s->current_picture.mb_type[xy] = MB_TYPE_SKIP  |

                                                     MB_TYPE_16x16 |

                                                     MB_TYPE_L0;

