void ppc_set_compat(PowerPCCPU *cpu, uint32_t compat_pvr, Error **errp)

{

    int ret = 0;

    CPUPPCState *env = &cpu->env;

    PowerPCCPUClass *host_pcc;



    cpu->compat_pvr = compat_pvr;



    switch (compat_pvr) {

    case CPU_POWERPC_LOGICAL_2_05:

        env->spr[SPR_PCR] = PCR_TM_DIS | PCR_VSX_DIS | PCR_COMPAT_2_07 |

                            PCR_COMPAT_2_06 | PCR_COMPAT_2_05;

        break;

    case CPU_POWERPC_LOGICAL_2_06:

    case CPU_POWERPC_LOGICAL_2_06_PLUS:

        env->spr[SPR_PCR] = PCR_TM_DIS | PCR_COMPAT_2_07 | PCR_COMPAT_2_06;

        break;

    case CPU_POWERPC_LOGICAL_2_07:

        env->spr[SPR_PCR] = PCR_COMPAT_2_07;

        break;

    default:

        env->spr[SPR_PCR] = 0;

        break;

    }



    host_pcc = kvm_ppc_get_host_cpu_class();

    if (host_pcc) {

        env->spr[SPR_PCR] &= host_pcc->pcr_mask;

    }



    if (kvm_enabled()) {

        ret = kvmppc_set_compat(cpu, cpu->compat_pvr);

        if (ret < 0) {

            error_setg_errno(errp, -ret,

                             "Unable to set CPU compatibility mode in KVM");

        }

    }

}

static coroutine_fn int sd_co_pdiscard(BlockDriverState *bs, int64_t offset,

                                      int count)

{

    SheepdogAIOCB acb;

    BDRVSheepdogState *s = bs->opaque;

    QEMUIOVector discard_iov;

    struct iovec iov;

    uint32_t zero = 0;



    if (!s->discard_supported) {

        return 0;

    }



    memset(&discard_iov, 0, sizeof(discard_iov));

    memset(&iov, 0, sizeof(iov));

    iov.iov_base = &zero;

    iov.iov_len = sizeof(zero);

    discard_iov.iov = &iov;

    discard_iov.niov = 1;

    if (!QEMU_IS_ALIGNED(offset | count, BDRV_SECTOR_SIZE)) {

        return -ENOTSUP;

    }

    sd_aio_setup(&acb, s, &discard_iov, offset >> BDRV_SECTOR_BITS,

                 count >> BDRV_SECTOR_BITS, AIOCB_DISCARD_OBJ);



retry:

    if (check_overlapping_aiocb(s, &acb)) {

        qemu_co_queue_wait(&s->overlapping_queue);

        goto retry;

    }



    sd_co_rw_vector(&acb);



    QLIST_REMOVE(&acb, aiocb_siblings);

    qemu_co_queue_restart_all(&s->overlapping_queue);

    return acb.ret;

}

static void gdb_vm_stopped(void *opaque, int reason)

{

    GDBState *s = opaque;

    char buf[256];

    const char *type;

    int ret;



    if (s->state == RS_SYSCALL)

        return;



    /* disable single step if it was enable */

    cpu_single_step(s->env, 0);



    if (reason == EXCP_DEBUG) {

        if (s->env->watchpoint_hit) {

            switch (s->env->watchpoint_hit->flags & BP_MEM_ACCESS) {

            case BP_MEM_READ:

                type = "r";

                break;

            case BP_MEM_ACCESS:

                type = "a";

                break;

            default:

                type = "";

                break;

            }

            snprintf(buf, sizeof(buf), "T%02x%swatch:" TARGET_FMT_lx ";",

                     SIGTRAP, type, s->env->watchpoint_hit->vaddr);

            put_packet(s, buf);

            s->env->watchpoint_hit = NULL;

            return;

        }

	tb_flush(s->env);

        ret = SIGTRAP;

    } else if (reason == EXCP_INTERRUPT) {

        ret = SIGINT;

    } else {

        ret = 0;

    }

    snprintf(buf, sizeof(buf), "S%02x", ret);

    put_packet(s, buf);

}

