static coroutine_fn int qcow2_co_pwrite_zeroes(BlockDriverState *bs,

    int64_t offset, int count, BdrvRequestFlags flags)

{

    int ret;

    BDRVQcow2State *s = bs->opaque;



    uint32_t head = offset % s->cluster_size;

    uint32_t tail = (offset + count) % s->cluster_size;



    trace_qcow2_pwrite_zeroes_start_req(qemu_coroutine_self(), offset, count);

    if (offset + count == bs->total_sectors * BDRV_SECTOR_SIZE) {

        tail = 0;

    }



    if (head || tail) {

        int64_t cl_start = (offset - head) >> BDRV_SECTOR_BITS;

        uint64_t off;

        unsigned int nr;



        assert(head + count <= s->cluster_size);



        /* check whether remainder of cluster already reads as zero */

        if (!(is_zero_sectors(bs, cl_start,

                              DIV_ROUND_UP(head, BDRV_SECTOR_SIZE)) &&

              is_zero_sectors(bs, (offset + count) >> BDRV_SECTOR_BITS,

                              DIV_ROUND_UP(-tail & (s->cluster_size - 1),

                                           BDRV_SECTOR_SIZE)))) {

            return -ENOTSUP;

        }



        qemu_co_mutex_lock(&s->lock);

        /* We can have new write after previous check */

        offset = cl_start << BDRV_SECTOR_BITS;

        count = s->cluster_size;

        nr = s->cluster_size;

        ret = qcow2_get_cluster_offset(bs, offset, &nr, &off);

        if (ret != QCOW2_CLUSTER_UNALLOCATED &&

            ret != QCOW2_CLUSTER_ZERO_PLAIN &&

            ret != QCOW2_CLUSTER_ZERO_ALLOC) {

            qemu_co_mutex_unlock(&s->lock);

            return -ENOTSUP;

        }

    } else {

        qemu_co_mutex_lock(&s->lock);

    }



    trace_qcow2_pwrite_zeroes(qemu_coroutine_self(), offset, count);



    /* Whatever is left can use real zero clusters */

    ret = qcow2_zero_clusters(bs, offset, count >> BDRV_SECTOR_BITS, flags);

    qemu_co_mutex_unlock(&s->lock);



    return ret;

}

static void gen_abso(DisasContext *ctx)

{

    int l1 = gen_new_label();

    int l2 = gen_new_label();

    int l3 = gen_new_label();

    /* Start with XER OV disabled, the most likely case */

    tcg_gen_movi_tl(cpu_ov, 0);

    tcg_gen_brcondi_tl(TCG_COND_GE, cpu_gpr[rA(ctx->opcode)], 0, l2);

    tcg_gen_brcondi_tl(TCG_COND_NE, cpu_gpr[rA(ctx->opcode)], 0x80000000, l1);

    tcg_gen_movi_tl(cpu_ov, 1);

    tcg_gen_movi_tl(cpu_so, 1);

    tcg_gen_br(l2);

    gen_set_label(l1);

    tcg_gen_neg_tl(cpu_gpr[rD(ctx->opcode)], cpu_gpr[rA(ctx->opcode)]);

    tcg_gen_br(l3);

    gen_set_label(l2);

    tcg_gen_mov_tl(cpu_gpr[rD(ctx->opcode)], cpu_gpr[rA(ctx->opcode)]);

    gen_set_label(l3);

    if (unlikely(Rc(ctx->opcode) != 0))

        gen_set_Rc0(ctx, cpu_gpr[rD(ctx->opcode)]);

}

DeviceState *sysbus_create_varargs(const char *name,

                                   target_phys_addr_t addr, ...)

{

    DeviceState *dev;

    SysBusDevice *s;

    va_list va;

    qemu_irq irq;

    int n;



    dev = qdev_create(NULL, name);

    s = sysbus_from_qdev(dev);

    qdev_init(dev);

    if (addr != (target_phys_addr_t)-1) {

        sysbus_mmio_map(s, 0, addr);

    }

    va_start(va, addr);

    n = 0;

    while (1) {

        irq = va_arg(va, qemu_irq);

        if (!irq) {

            break;

        }

        sysbus_connect_irq(s, n, irq);

        n++;

    }

    return dev;

}

static int dca_decode_frame(AVCodecContext * avctx,

                            void *data, int *data_size,

                            AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;



    int lfe_samples;

    int num_core_channels = 0;

    int i;

    float   *samples_flt = data;

    int16_t *samples_s16 = data;

    int out_size;

    DCAContext *s = avctx->priv_data;

    int channels;

    int core_ss_end;





    s->xch_present = 0;



    s->dca_buffer_size = dca_convert_bitstream(buf, buf_size, s->dca_buffer,

                                               DCA_MAX_FRAME_SIZE + DCA_MAX_EXSS_HEADER_SIZE);

    if (s->dca_buffer_size == AVERROR_INVALIDDATA) {

        av_log(avctx, AV_LOG_ERROR, "Not a valid DCA frame\n");

        return AVERROR_INVALIDDATA;

    }



    init_get_bits(&s->gb, s->dca_buffer, s->dca_buffer_size * 8);

    if (dca_parse_frame_header(s) < 0) {

        //seems like the frame is corrupt, try with the next one

        *data_size=0;

        return buf_size;

    }

    //set AVCodec values with parsed data

    avctx->sample_rate = s->sample_rate;

    avctx->bit_rate = s->bit_rate;

    avctx->frame_size = s->sample_blocks * 32;



    s->profile = FF_PROFILE_DTS;



    for (i = 0; i < (s->sample_blocks / 8); i++) {

        dca_decode_block(s, 0, i);

    }



    /* record number of core channels incase less than max channels are requested */

    num_core_channels = s->prim_channels;



    if (s->ext_coding)

        s->core_ext_mask = dca_ext_audio_descr_mask[s->ext_descr];

    else

        s->core_ext_mask = 0;



    core_ss_end = FFMIN(s->frame_size, s->dca_buffer_size) * 8;



    /* only scan for extensions if ext_descr was unknown or indicated a

     * supported XCh extension */

    if (s->core_ext_mask < 0 || s->core_ext_mask & DCA_EXT_XCH) {



        /* if ext_descr was unknown, clear s->core_ext_mask so that the

         * extensions scan can fill it up */

        s->core_ext_mask = FFMAX(s->core_ext_mask, 0);



        /* extensions start at 32-bit boundaries into bitstream */

        skip_bits_long(&s->gb, (-get_bits_count(&s->gb)) & 31);



    while(core_ss_end - get_bits_count(&s->gb) >= 32) {

        uint32_t bits = get_bits_long(&s->gb, 32);



        switch(bits) {

        case 0x5a5a5a5a: {

            int ext_amode, xch_fsize;



            s->xch_base_channel = s->prim_channels;



            /* validate sync word using XCHFSIZE field */

            xch_fsize = show_bits(&s->gb, 10);

            if((s->frame_size != (get_bits_count(&s->gb) >> 3) - 4 + xch_fsize) &&

               (s->frame_size != (get_bits_count(&s->gb) >> 3) - 4 + xch_fsize + 1))

                continue;



            /* skip length-to-end-of-frame field for the moment */

            skip_bits(&s->gb, 10);



            s->core_ext_mask |= DCA_EXT_XCH;



            /* extension amode should == 1, number of channels in extension */

            /* AFAIK XCh is not used for more channels */

            if ((ext_amode = get_bits(&s->gb, 4)) != 1) {

                av_log(avctx, AV_LOG_ERROR, "XCh extension amode %d not"

                       " supported!\n",ext_amode);

                continue;

            }



            /* much like core primary audio coding header */

            dca_parse_audio_coding_header(s, s->xch_base_channel);



            for (i = 0; i < (s->sample_blocks / 8); i++) {

                dca_decode_block(s, s->xch_base_channel, i);

            }



            s->xch_present = 1;

            break;

        }

        case 0x47004a03:

            /* XXCh: extended channels */

            /* usually found either in core or HD part in DTS-HD HRA streams,

             * but not in DTS-ES which contains XCh extensions instead */

            s->core_ext_mask |= DCA_EXT_XXCH;

            break;



        case 0x1d95f262: {

            int fsize96 = show_bits(&s->gb, 12) + 1;

            if (s->frame_size != (get_bits_count(&s->gb) >> 3) - 4 + fsize96)

                continue;



            av_log(avctx, AV_LOG_DEBUG, "X96 extension found at %d bits\n", get_bits_count(&s->gb));

            skip_bits(&s->gb, 12);

            av_log(avctx, AV_LOG_DEBUG, "FSIZE96 = %d bytes\n", fsize96);

            av_log(avctx, AV_LOG_DEBUG, "REVNO = %d\n", get_bits(&s->gb, 4));



            s->core_ext_mask |= DCA_EXT_X96;

            break;

        }

        }



        skip_bits_long(&s->gb, (-get_bits_count(&s->gb)) & 31);

    }



    } else {

        /* no supported extensions, skip the rest of the core substream */

        skip_bits_long(&s->gb, core_ss_end - get_bits_count(&s->gb));

    }



    if (s->core_ext_mask & DCA_EXT_X96)

        s->profile = FF_PROFILE_DTS_96_24;

    else if (s->core_ext_mask & (DCA_EXT_XCH | DCA_EXT_XXCH))

        s->profile = FF_PROFILE_DTS_ES;



    /* check for ExSS (HD part) */

    if (s->dca_buffer_size - s->frame_size > 32

        && get_bits_long(&s->gb, 32) == DCA_HD_MARKER)

        dca_exss_parse_header(s);



    avctx->profile = s->profile;



    channels = s->prim_channels + !!s->lfe;



    if (s->amode<16) {

        avctx->channel_layout = dca_core_channel_layout[s->amode];



        if (s->xch_present && (!avctx->request_channels ||

                               avctx->request_channels > num_core_channels + !!s->lfe)) {

            avctx->channel_layout |= AV_CH_BACK_CENTER;

            if (s->lfe) {

                avctx->channel_layout |= AV_CH_LOW_FREQUENCY;

                s->channel_order_tab = dca_channel_reorder_lfe_xch[s->amode];

            } else {

                s->channel_order_tab = dca_channel_reorder_nolfe_xch[s->amode];

            }

        } else {

            channels = num_core_channels + !!s->lfe;

            s->xch_present = 0; /* disable further xch processing */

            if (s->lfe) {

                avctx->channel_layout |= AV_CH_LOW_FREQUENCY;

                s->channel_order_tab = dca_channel_reorder_lfe[s->amode];

            } else

                s->channel_order_tab = dca_channel_reorder_nolfe[s->amode];

        }



        if (channels > !!s->lfe &&

            s->channel_order_tab[channels - 1 - !!s->lfe] < 0)

            return AVERROR_INVALIDDATA;



        if (avctx->request_channels == 2 && s->prim_channels > 2) {

            channels = 2;

            s->output = DCA_STEREO;

            avctx->channel_layout = AV_CH_LAYOUT_STEREO;

        }

    } else {

        av_log(avctx, AV_LOG_ERROR, "Non standard configuration %d !\n",s->amode);

        return AVERROR_INVALIDDATA;

    }





    /* There is nothing that prevents a dts frame to change channel configuration

       but Libav doesn't support that so only set the channels if it is previously

       unset. Ideally during the first probe for channels the crc should be checked

       and only set avctx->channels when the crc is ok. Right now the decoder could

       set the channels based on a broken first frame.*/

    if (s->is_channels_set == 0) {

        s->is_channels_set = 1;

        avctx->channels = channels;

    }

    if (avctx->channels != channels) {

        av_log(avctx, AV_LOG_ERROR, "DCA decoder does not support number of "

               "channels changing in stream. Skipping frame.\n");

        return AVERROR_PATCHWELCOME;

    }



    out_size = 256 / 8 * s->sample_blocks * channels *

               av_get_bytes_per_sample(avctx->sample_fmt);

    if (*data_size < out_size)

        return AVERROR(EINVAL);

    *data_size = out_size;



    /* filter to get final output */

    for (i = 0; i < (s->sample_blocks / 8); i++) {

        dca_filter_channels(s, i);



        /* If this was marked as a DTS-ES stream we need to subtract back- */

        /* channel from SL & SR to remove matrixed back-channel signal */

        if((s->source_pcm_res & 1) && s->xch_present) {

            float* back_chan = s->samples + s->channel_order_tab[s->xch_base_channel] * 256;

            float* lt_chan   = s->samples + s->channel_order_tab[s->xch_base_channel - 2] * 256;

            float* rt_chan   = s->samples + s->channel_order_tab[s->xch_base_channel - 1] * 256;

            s->dsp.vector_fmac_scalar(lt_chan, back_chan, -M_SQRT1_2, 256);

            s->dsp.vector_fmac_scalar(rt_chan, back_chan, -M_SQRT1_2, 256);

        }



        if (avctx->sample_fmt == AV_SAMPLE_FMT_FLT) {

            s->fmt_conv.float_interleave(samples_flt, s->samples_chanptr, 256,

                                         channels);

            samples_flt += 256 * channels;

        } else {

            s->fmt_conv.float_to_int16_interleave(samples_s16,

                                                  s->samples_chanptr, 256,

                                                  channels);

            samples_s16 += 256 * channels;

        }

    }



    /* update lfe history */

    lfe_samples = 2 * s->lfe * (s->sample_blocks / 8);

    for (i = 0; i < 2 * s->lfe * 4; i++) {

        s->lfe_data[i] = s->lfe_data[i + lfe_samples];

    }



    return buf_size;

}

int spapr_populate_pci_dt(sPAPRPHBState *phb,

                          uint32_t xics_phandle,

                          void *fdt)

{

    int bus_off, i, j;

    char nodename[256];

    uint32_t bus_range[] = { cpu_to_be32(0), cpu_to_be32(0xff) };

    struct {

        uint32_t hi;

        uint64_t child;

        uint64_t parent;

        uint64_t size;

    } QEMU_PACKED ranges[] = {

        {

            cpu_to_be32(b_ss(1)), cpu_to_be64(0),

            cpu_to_be64(phb->io_win_addr),

            cpu_to_be64(memory_region_size(&phb->iospace)),

        },

        {

            cpu_to_be32(b_ss(2)), cpu_to_be64(SPAPR_PCI_MEM_WIN_BUS_OFFSET),

            cpu_to_be64(phb->mem_win_addr),

            cpu_to_be64(memory_region_size(&phb->memwindow)),

        },

    };

    uint64_t bus_reg[] = { cpu_to_be64(phb->buid), 0 };

    uint32_t interrupt_map_mask[] = {

        cpu_to_be32(b_ddddd(-1)|b_fff(0)), 0x0, 0x0, cpu_to_be32(-1)};

    uint32_t interrupt_map[PCI_SLOT_MAX * PCI_NUM_PINS][7];



    /* Start populating the FDT */

    sprintf(nodename, "pci@%" PRIx64, phb->buid);

    bus_off = fdt_add_subnode(fdt, 0, nodename);

    if (bus_off < 0) {

        return bus_off;

    }



#define _FDT(exp) \

    do { \

        int ret = (exp);                                           \

        if (ret < 0) {                                             \

            return ret;                                            \

        }                                                          \

    } while (0)



    /* Write PHB properties */

    _FDT(fdt_setprop_string(fdt, bus_off, "device_type", "pci"));

    _FDT(fdt_setprop_string(fdt, bus_off, "compatible", "IBM,Logical_PHB"));

    _FDT(fdt_setprop_cell(fdt, bus_off, "#address-cells", 0x3));

    _FDT(fdt_setprop_cell(fdt, bus_off, "#size-cells", 0x2));

    _FDT(fdt_setprop_cell(fdt, bus_off, "#interrupt-cells", 0x1));

    _FDT(fdt_setprop(fdt, bus_off, "used-by-rtas", NULL, 0));

    _FDT(fdt_setprop(fdt, bus_off, "bus-range", &bus_range, sizeof(bus_range)));

    _FDT(fdt_setprop(fdt, bus_off, "ranges", &ranges, sizeof(ranges)));

    _FDT(fdt_setprop(fdt, bus_off, "reg", &bus_reg, sizeof(bus_reg)));

    _FDT(fdt_setprop_cell(fdt, bus_off, "ibm,pci-config-space-type", 0x1));




    /* Build the interrupt-map, this must matches what is done

     * in pci_spapr_map_irq

     */

    _FDT(fdt_setprop(fdt, bus_off, "interrupt-map-mask",

                     &interrupt_map_mask, sizeof(interrupt_map_mask)));

    for (i = 0; i < PCI_SLOT_MAX; i++) {

        for (j = 0; j < PCI_NUM_PINS; j++) {

            uint32_t *irqmap = interrupt_map[i*PCI_NUM_PINS + j];

            int lsi_num = pci_spapr_swizzle(i, j);



            irqmap[0] = cpu_to_be32(b_ddddd(i)|b_fff(0));

            irqmap[1] = 0;

            irqmap[2] = 0;

            irqmap[3] = cpu_to_be32(j+1);

            irqmap[4] = cpu_to_be32(xics_phandle);

            irqmap[5] = cpu_to_be32(phb->lsi_table[lsi_num].irq);

            irqmap[6] = cpu_to_be32(0x8);

        }

    }

    /* Write interrupt map */

    _FDT(fdt_setprop(fdt, bus_off, "interrupt-map", &interrupt_map,

                     sizeof(interrupt_map)));



    object_child_foreach(OBJECT(phb), spapr_phb_children_dt,

                         &((sPAPRTCEDT){ .fdt = fdt, .node_off = bus_off }));



    return 0;

}

