static void pm_update_sci(PIIX4PMState *s)

{

    int sci_level, pmsts;

    int64_t expire_time;



    pmsts = get_pmsts(s);

    sci_level = (((pmsts & s->pmen) &

                  (RTC_EN | PWRBTN_EN | GBL_EN | TMROF_EN)) != 0);

    qemu_set_irq(s->irq, sci_level);

    /* schedule a timer interruption if needed */

    if ((s->pmen & TMROF_EN) && !(pmsts & TMROF_EN)) {

        expire_time = muldiv64(s->tmr_overflow_time, ticks_per_sec, PM_FREQ);

        qemu_mod_timer(s->tmr_timer, expire_time);

        s->tmr_overflow_time += 0x800000;

    } else {

        qemu_del_timer(s->tmr_timer);

    }

}

static int find_slice_quant(AVCodecContext *avctx, const AVFrame *pic,

                            int trellis_node, int x, int y, int mbs_per_slice)

{

    ProresContext *ctx = avctx->priv_data;

    int i, q, pq, xp, yp;

    const uint16_t *src;

    int slice_width_factor = av_log2(mbs_per_slice);

    int num_cblocks[MAX_PLANES], pwidth;

    int plane_factor[MAX_PLANES], is_chroma[MAX_PLANES];

    const int min_quant = ctx->profile_info->min_quant;

    const int max_quant = ctx->profile_info->max_quant;

    int error, bits, bits_limit;

    int mbs, prev, cur, new_score;

    int slice_bits[TRELLIS_WIDTH], slice_score[TRELLIS_WIDTH];



    mbs = x + mbs_per_slice;



    for (i = 0; i < ctx->num_planes; i++) {

        is_chroma[i]    = (i == 1 || i == 2);

        plane_factor[i] = slice_width_factor + 2;

        if (is_chroma[i])

            plane_factor[i] += ctx->chroma_factor - 3;

        if (!is_chroma[i] || ctx->chroma_factor == CFACTOR_Y444) {

            xp             = x << 4;

            yp             = y << 4;

            num_cblocks[i] = 4;

            pwidth         = avctx->width;

        } else {

            xp             = x << 3;

            yp             = y << 4;

            num_cblocks[i] = 2;

            pwidth         = avctx->width >> 1;

        }

        src = (const uint16_t*)(pic->data[i] + yp * pic->linesize[i]) + xp;



        get_slice_data(ctx, src, pic->linesize[i], xp, yp,

                       pwidth, avctx->height, ctx->blocks[i],

                       mbs_per_slice, num_cblocks[i]);

    }



    for (q = min_quant; q <= max_quant; q++) {

        ctx->nodes[trellis_node + q].prev_node = -1;

        ctx->nodes[trellis_node + q].quant     = q;

    }



    // todo: maybe perform coarser quantising to fit into frame size when needed

    for (q = min_quant; q <= max_quant; q++) {

        bits  = 0;

        error = 0;

        for (i = 0; i < ctx->num_planes; i++) {

            bits += estimate_slice_plane(ctx, &error, i,

                                         src, pic->linesize[i],

                                         mbs_per_slice,

                                         num_cblocks[i], plane_factor[i],

                                         ctx->quants[q]);

        }

        if (bits > 65000 * 8) {

            error = SCORE_LIMIT;

            break;

        }

        slice_bits[q]  = bits;

        slice_score[q] = error;

    }



    bits_limit = mbs * ctx->bits_per_mb;

    for (pq = min_quant; pq <= max_quant; pq++) {

        prev = trellis_node - TRELLIS_WIDTH + pq;



        for (q = min_quant; q <= max_quant; q++) {

            cur = trellis_node + q;



            bits  = ctx->nodes[prev].bits + slice_bits[q];

            error = slice_score[q];

            if (bits > bits_limit)

                error = SCORE_LIMIT;



            if (ctx->nodes[prev].score < SCORE_LIMIT && error < SCORE_LIMIT)

                new_score = ctx->nodes[prev].score + error;

            else

                new_score = SCORE_LIMIT;

            if (ctx->nodes[cur].prev_node == -1 ||

                ctx->nodes[cur].score >= new_score) {



                ctx->nodes[cur].bits      = bits;

                ctx->nodes[cur].score     = new_score;

                ctx->nodes[cur].prev_node = prev;

            }

        }

    }



    error = ctx->nodes[trellis_node + min_quant].score;

    pq    = trellis_node + min_quant;

    for (q = min_quant + 1; q <= max_quant; q++) {

        if (ctx->nodes[trellis_node + q].score <= error) {

            error = ctx->nodes[trellis_node + q].score;

            pq    = trellis_node + q;

        }

    }



    return pq;

}

static int discard_single_l2(BlockDriverState *bs, uint64_t offset,

                             uint64_t nb_clusters, enum qcow2_discard_type type,

                             bool full_discard)

{

    BDRVQcow2State *s = bs->opaque;

    uint64_t *l2_table;

    int l2_index;

    int ret;

    int i;



    ret = get_cluster_table(bs, offset, &l2_table, &l2_index);

    if (ret < 0) {

        return ret;

    }



    /* Limit nb_clusters to one L2 table */

    nb_clusters = MIN(nb_clusters, s->l2_size - l2_index);

    assert(nb_clusters <= INT_MAX);



    for (i = 0; i < nb_clusters; i++) {

        uint64_t old_l2_entry;



        old_l2_entry = be64_to_cpu(l2_table[l2_index + i]);



        /*

         * If full_discard is false, make sure that a discarded area reads back

         * as zeroes for v3 images (we cannot do it for v2 without actually

         * writing a zero-filled buffer). We can skip the operation if the

         * cluster is already marked as zero, or if it's unallocated and we

         * don't have a backing file.

         *

         * TODO We might want to use bdrv_get_block_status(bs) here, but we're

         * holding s->lock, so that doesn't work today.

         *

         * If full_discard is true, the sector should not read back as zeroes,

         * but rather fall through to the backing file.

         */

        switch (qcow2_get_cluster_type(old_l2_entry)) {

        case QCOW2_CLUSTER_UNALLOCATED:

            if (full_discard || !bs->backing) {

                continue;

            }

            break;



        case QCOW2_CLUSTER_ZERO_PLAIN:

            if (!full_discard) {

                continue;

            }

            break;



        case QCOW2_CLUSTER_ZERO_ALLOC:

        case QCOW2_CLUSTER_NORMAL:

        case QCOW2_CLUSTER_COMPRESSED:

            break;



        default:

            abort();

        }



        /* First remove L2 entries */

        qcow2_cache_entry_mark_dirty(bs, s->l2_table_cache, l2_table);

        if (!full_discard && s->qcow_version >= 3) {

            l2_table[l2_index + i] = cpu_to_be64(QCOW_OFLAG_ZERO);

        } else {

            l2_table[l2_index + i] = cpu_to_be64(0);

        }



        /* Then decrease the refcount */

        qcow2_free_any_clusters(bs, old_l2_entry, 1, type);

    }



    qcow2_cache_put(bs, s->l2_table_cache, (void **) &l2_table);



    return nb_clusters;

}

static int alac_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame_ptr, AVPacket *avpkt)

{

    ALACContext *alac = avctx->priv_data;

    enum RawDataBlockType element;

    int channels;

    int ch, ret, got_end;



    init_get_bits(&alac->gb, avpkt->data, avpkt->size * 8);



    got_end = 0;

    alac->nb_samples = 0;

    ch = 0;

    while (get_bits_left(&alac->gb) >= 3) {

        element = get_bits(&alac->gb, 3);

        if (element == TYPE_END) {

            got_end = 1;

            break;

        }

        if (element > TYPE_CPE && element != TYPE_LFE) {

            av_log(avctx, AV_LOG_ERROR, "syntax element unsupported: %d\n", element);

            return AVERROR_PATCHWELCOME;

        }



        channels = (element == TYPE_CPE) ? 2 : 1;

        if (ch + channels > alac->channels) {

            av_log(avctx, AV_LOG_ERROR, "invalid element channel count\n");

            return AVERROR_INVALIDDATA;

        }



        ret = decode_element(avctx, data,

                             alac_channel_layout_offsets[alac->channels - 1][ch],

                             channels);

        if (ret < 0 && get_bits_left(&alac->gb))

            return ret;



        ch += channels;

    }

    if (!got_end) {

        av_log(avctx, AV_LOG_ERROR, "no end tag found. incomplete packet.\n");

        return AVERROR_INVALIDDATA;

    }



    if (avpkt->size * 8 - get_bits_count(&alac->gb) > 8) {

        av_log(avctx, AV_LOG_ERROR, "Error : %d bits left\n",

               avpkt->size * 8 - get_bits_count(&alac->gb));

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = alac->frame;



    return avpkt->size;

}

