static bool liveness_pass_2(TCGContext *s)

{

    int nb_globals = s->nb_globals;

    int nb_temps, i, oi, oi_next;

    bool changes = false;



    /* Create a temporary for each indirect global.  */

    for (i = 0; i < nb_globals; ++i) {

        TCGTemp *its = &s->temps[i];

        if (its->indirect_reg) {

            TCGTemp *dts = tcg_temp_alloc(s);

            dts->type = its->type;

            dts->base_type = its->base_type;

            its->state_ptr = dts;

        } else {

            its->state_ptr = NULL;

        }

        /* All globals begin dead.  */

        its->state = TS_DEAD;

    }

    for (nb_temps = s->nb_temps; i < nb_temps; ++i) {

        TCGTemp *its = &s->temps[i];

        its->state_ptr = NULL;

        its->state = TS_DEAD;

    }



    for (oi = s->gen_op_buf[0].next; oi != 0; oi = oi_next) {

        TCGOp *op = &s->gen_op_buf[oi];

        TCGOpcode opc = op->opc;

        const TCGOpDef *def = &tcg_op_defs[opc];

        TCGLifeData arg_life = op->life;

        int nb_iargs, nb_oargs, call_flags;

        TCGTemp *arg_ts, *dir_ts;



        oi_next = op->next;



        if (opc == INDEX_op_call) {

            nb_oargs = op->callo;

            nb_iargs = op->calli;

            call_flags = op->args[nb_oargs + nb_iargs + 1];

        } else {

            nb_iargs = def->nb_iargs;

            nb_oargs = def->nb_oargs;



            /* Set flags similar to how calls require.  */

            if (def->flags & TCG_OPF_BB_END) {

                /* Like writing globals: save_globals */

                call_flags = 0;

            } else if (def->flags & TCG_OPF_SIDE_EFFECTS) {

                /* Like reading globals: sync_globals */

                call_flags = TCG_CALL_NO_WRITE_GLOBALS;

            } else {

                /* No effect on globals.  */

                call_flags = (TCG_CALL_NO_READ_GLOBALS |

                              TCG_CALL_NO_WRITE_GLOBALS);

            }

        }



        /* Make sure that input arguments are available.  */

        for (i = nb_oargs; i < nb_iargs + nb_oargs; i++) {

            arg_ts = arg_temp(op->args[i]);

            if (arg_ts) {

                dir_ts = arg_ts->state_ptr;

                if (dir_ts && arg_ts->state == TS_DEAD) {

                    TCGOpcode lopc = (arg_ts->type == TCG_TYPE_I32

                                      ? INDEX_op_ld_i32

                                      : INDEX_op_ld_i64);

                    TCGOp *lop = tcg_op_insert_before(s, op, lopc, 3);



                    lop->args[0] = temp_arg(dir_ts);

                    lop->args[1] = temp_arg(arg_ts->mem_base);

                    lop->args[2] = arg_ts->mem_offset;



                    /* Loaded, but synced with memory.  */

                    arg_ts->state = TS_MEM;

                }

            }

        }



        /* Perform input replacement, and mark inputs that became dead.

           No action is required except keeping temp_state up to date

           so that we reload when needed.  */

        for (i = nb_oargs; i < nb_iargs + nb_oargs; i++) {

            arg_ts = arg_temp(op->args[i]);

            if (arg_ts) {

                dir_ts = arg_ts->state_ptr;

                if (dir_ts) {

                    op->args[i] = temp_arg(dir_ts);

                    changes = true;

                    if (IS_DEAD_ARG(i)) {

                        arg_ts->state = TS_DEAD;

                    }

                }

            }

        }



        /* Liveness analysis should ensure that the following are

           all correct, for call sites and basic block end points.  */

        if (call_flags & TCG_CALL_NO_READ_GLOBALS) {

            /* Nothing to do */

        } else if (call_flags & TCG_CALL_NO_WRITE_GLOBALS) {

            for (i = 0; i < nb_globals; ++i) {

                /* Liveness should see that globals are synced back,

                   that is, either TS_DEAD or TS_MEM.  */

                arg_ts = &s->temps[i];

                tcg_debug_assert(arg_ts->state_ptr == 0

                                 || arg_ts->state != 0);

            }

        } else {

            for (i = 0; i < nb_globals; ++i) {

                /* Liveness should see that globals are saved back,

                   that is, TS_DEAD, waiting to be reloaded.  */

                arg_ts = &s->temps[i];

                tcg_debug_assert(arg_ts->state_ptr == 0

                                 || arg_ts->state == TS_DEAD);

            }

        }



        /* Outputs become available.  */

        for (i = 0; i < nb_oargs; i++) {

            arg_ts = arg_temp(op->args[i]);

            dir_ts = arg_ts->state_ptr;

            if (!dir_ts) {

                continue;

            }

            op->args[i] = temp_arg(dir_ts);

            changes = true;



            /* The output is now live and modified.  */

            arg_ts->state = 0;



            /* Sync outputs upon their last write.  */

            if (NEED_SYNC_ARG(i)) {

                TCGOpcode sopc = (arg_ts->type == TCG_TYPE_I32

                                  ? INDEX_op_st_i32

                                  : INDEX_op_st_i64);

                TCGOp *sop = tcg_op_insert_after(s, op, sopc, 3);



                sop->args[0] = temp_arg(dir_ts);

                sop->args[1] = temp_arg(arg_ts->mem_base);

                sop->args[2] = arg_ts->mem_offset;



                arg_ts->state = TS_MEM;

            }

            /* Drop outputs that are dead.  */

            if (IS_DEAD_ARG(i)) {

                arg_ts->state = TS_DEAD;

            }

        }

    }



    return changes;

}

static void update_stream_timings(AVFormatContext *ic)

{

    int64_t start_time, start_time1, start_time_text, end_time, end_time1;

    int64_t duration, duration1, filesize;

    int i;

    AVStream *st;

    AVProgram *p;



    start_time = INT64_MAX;

    start_time_text = INT64_MAX;

    end_time   = INT64_MIN;

    duration   = INT64_MIN;

    for (i = 0; i < ic->nb_streams; i++) {

        st = ic->streams[i];

        if (st->start_time != AV_NOPTS_VALUE && st->time_base.den) {

            start_time1 = av_rescale_q(st->start_time, st->time_base,

                                       AV_TIME_BASE_Q);

            if (st->codec->codec_type == AVMEDIA_TYPE_SUBTITLE || st->codec->codec_type == AVMEDIA_TYPE_DATA) {

                if (start_time1 < start_time_text)

                    start_time_text = start_time1;

            } else

                start_time = FFMIN(start_time, start_time1);

            end_time1   = AV_NOPTS_VALUE;

            if (st->duration != AV_NOPTS_VALUE) {

                end_time1 = start_time1 +

                            av_rescale_q(st->duration, st->time_base,

                                         AV_TIME_BASE_Q);

                end_time = FFMAX(end_time, end_time1);

            }

            for (p = NULL; (p = av_find_program_from_stream(ic, p, i)); ) {

                if (p->start_time == AV_NOPTS_VALUE || p->start_time > start_time1)

                    p->start_time = start_time1;

                if (p->end_time < end_time1)

                    p->end_time = end_time1;

            }

        }

        if (st->duration != AV_NOPTS_VALUE) {

            duration1 = av_rescale_q(st->duration, st->time_base,

                                     AV_TIME_BASE_Q);

            duration  = FFMAX(duration, duration1);

        }

    }

    if (start_time == INT64_MAX || (start_time > start_time_text && start_time - start_time_text < AV_TIME_BASE))

        start_time = start_time_text;

    else if (start_time > start_time_text)

        av_log(ic, AV_LOG_VERBOSE, "Ignoring outlier non primary stream starttime %f\n", start_time_text / (float)AV_TIME_BASE);



    if (start_time != INT64_MAX) {

        ic->start_time = start_time;

        if (end_time != INT64_MIN) {

            if (ic->nb_programs) {

                for (i = 0; i < ic->nb_programs; i++) {

                    p = ic->programs[i];

                    if (p->start_time != AV_NOPTS_VALUE && p->end_time > p->start_time)

                        duration = FFMAX(duration, p->end_time - p->start_time);

                }

            } else

                duration = FFMAX(duration, end_time - start_time);

        }

    }

    if (duration != INT64_MIN && duration > 0 && ic->duration == AV_NOPTS_VALUE) {

        ic->duration = duration;

    }

    if (ic->pb && (filesize = avio_size(ic->pb)) > 0 && ic->duration != AV_NOPTS_VALUE) {

        /* compute the bitrate */

        double bitrate = (double) filesize * 8.0 * AV_TIME_BASE /

                         (double) ic->duration;

        if (bitrate >= 0 && (!AV_HAVE_INCOMPATIBLE_LIBAV_ABI || bitrate <= INT_MAX))

            ic->bit_rate = bitrate;

    }

}

GuestMemoryBlockInfo *qmp_guest_get_memory_block_info(Error **errp)

{

    Error *local_err = NULL;

    char *dirpath;

    int dirfd;

    char *buf;

    GuestMemoryBlockInfo *info;



    dirpath = g_strdup_printf("/sys/devices/system/memory/");

    dirfd = open(dirpath, O_RDONLY | O_DIRECTORY);

    if (dirfd == -1) {

        error_setg_errno(errp, errno, "open(\"%s\")", dirpath);

        g_free(dirpath);

        return NULL;

    }

    g_free(dirpath);



    buf = g_malloc0(20);

    ga_read_sysfs_file(dirfd, "block_size_bytes", buf, 20, &local_err);


    if (local_err) {

        g_free(buf);

        error_propagate(errp, local_err);

        return NULL;

    }



    info = g_new0(GuestMemoryBlockInfo, 1);

    info->size = strtol(buf, NULL, 16); /* the unit is bytes */



    g_free(buf);



    return info;

}

AVInputFormat *av_probe_input_format3(AVProbeData *pd, int is_opened,

                                      int *score_ret)

{

    AVProbeData lpd = *pd;

    AVInputFormat *fmt1 = NULL, *fmt;

    int score, nodat = 0, score_max = 0;

    const static uint8_t zerobuffer[AVPROBE_PADDING_SIZE];



    if (!lpd.buf)

        lpd.buf = zerobuffer;



    if (lpd.buf_size > 10 && ff_id3v2_match(lpd.buf, ID3v2_DEFAULT_MAGIC)) {

        int id3len = ff_id3v2_tag_len(lpd.buf);

        if (lpd.buf_size > id3len + 16) {

            lpd.buf      += id3len;

            lpd.buf_size -= id3len;

        } else

            nodat = 1;

    }



    fmt = NULL;

    while ((fmt1 = av_iformat_next(fmt1))) {

        if (!is_opened == !(fmt1->flags & AVFMT_NOFILE))

            continue;

        score = 0;

        if (fmt1->read_probe) {

            score = fmt1->read_probe(&lpd);

            if (fmt1->extensions && av_match_ext(lpd.filename, fmt1->extensions))

                score = FFMAX(score, nodat ? AVPROBE_SCORE_EXTENSION / 2 - 1 : 1);

        } else if (fmt1->extensions) {

            if (av_match_ext(lpd.filename, fmt1->extensions))

                score = AVPROBE_SCORE_EXTENSION;

        }

        if (score > score_max) {

            score_max = score;

            fmt       = fmt1;

        } else if (score == score_max)

            fmt = NULL;

    }

    if (nodat)

        score_max = FFMIN(AVPROBE_SCORE_EXTENSION / 2 - 1, score_max);

    *score_ret = score_max;



    return fmt;

}

