static int parse_keyframes_index(AVFormatContext *s, AVIOContext *ioc, AVStream *vstream, int64_t max_pos) {

    unsigned int timeslen = 0, fileposlen = 0, i;

    char str_val[256];

    int64_t *times = NULL;

    int64_t *filepositions = NULL;

    int ret = AVERROR(ENOSYS);

    int64_t initial_pos = avio_tell(ioc);

    AVDictionaryEntry *creator = av_dict_get(s->metadata, "metadatacreator",

                                             NULL, 0);



    if (creator && !strcmp(creator->value, "MEGA")) {

        /* Files with this metadatacreator tag seem to have filepositions

         * pointing at the 4 trailer bytes of the previous packet,

         * which isn't the norm (nor what we expect here, nor what

         * jwplayer + lighttpd expect, nor what flvtool2 produces).

         * Just ignore the index in this case, instead of risking trying

         * to adjust it to something that might or might not work. */

        return 0;

    }



    if(vstream->nb_index_entries>0){

        av_log(s, AV_LOG_WARNING, "Skiping duplicate index\n");

        return 0;

    }



    while (avio_tell(ioc) < max_pos - 2 && amf_get_string(ioc, str_val, sizeof(str_val)) > 0) {

        int64_t** current_array;

        unsigned int arraylen;



        // Expect array object in context

        if (avio_r8(ioc) != AMF_DATA_TYPE_ARRAY)

            break;



        arraylen = avio_rb32(ioc);

        if(arraylen>>28)

            break;



        if       (!strcmp(KEYFRAMES_TIMESTAMP_TAG , str_val) && !times){

            current_array= &times;

            timeslen= arraylen;

        }else if (!strcmp(KEYFRAMES_BYTEOFFSET_TAG, str_val) && !filepositions){

            current_array= &filepositions;

            fileposlen= arraylen;

        }else // unexpected metatag inside keyframes, will not use such metadata for indexing

            break;



        if (!(*current_array = av_mallocz(sizeof(**current_array) * arraylen))) {

            ret = AVERROR(ENOMEM);

            goto finish;

        }



        for (i = 0; i < arraylen && avio_tell(ioc) < max_pos - 1; i++) {

            if (avio_r8(ioc) != AMF_DATA_TYPE_NUMBER)

                goto finish;

            current_array[0][i] = av_int2dbl(avio_rb64(ioc));

        }

        if (times && filepositions) {

            // All done, exiting at a position allowing amf_parse_object

            // to finish parsing the object

            ret = 0;

            break;

        }

    }



    if (timeslen == fileposlen) {

         for(i = 0; i < timeslen; i++)

             av_add_index_entry(vstream, filepositions[i], times[i]*1000, 0, 0, AVINDEX_KEYFRAME);

    } else

        av_log(s, AV_LOG_WARNING, "Invalid keyframes object, skipping.\n");



finish:

    av_freep(&times);

    av_freep(&filepositions);

    avio_seek(ioc, initial_pos, SEEK_SET);

    return ret;

}

void avcodec_default_release_buffer(AVCodecContext *s, AVFrame *pic){

    int i;

    InternalBuffer *buf, *last;

    AVCodecInternal *avci = s->internal;



    assert(s->codec_type == AVMEDIA_TYPE_VIDEO);



    assert(pic->type==FF_BUFFER_TYPE_INTERNAL);

    assert(avci->buffer_count);



    if (avci->buffer) {

        buf = NULL; /* avoids warning */

        for (i = 0; i < avci->buffer_count; i++) { //just 3-5 checks so is not worth to optimize

            buf = &avci->buffer[i];

            if (buf->data[0] == pic->data[0])

                break;

        }

        assert(i < avci->buffer_count);

        avci->buffer_count--;

        last = &avci->buffer[avci->buffer_count];



        FFSWAP(InternalBuffer, *buf, *last);

    }



    for (i = 0; i < AV_NUM_DATA_POINTERS; i++) {

        pic->data[i]=NULL;

//        pic->base[i]=NULL;

    }

//printf("R%X\n", pic->opaque);



    if(s->debug&FF_DEBUG_BUFFERS)

        av_log(s, AV_LOG_DEBUG, "default_release_buffer called on pic %p, %d "

               "buffers used\n", pic, avci->buffer_count);

}

static void iv_Decode_Chunk(Indeo3DecodeContext *s,

        uint8_t *cur, uint8_t *ref, int width, int height,

        const uint8_t *buf1, int cb_offset, const uint8_t *hdr,

        const uint8_t *buf2, int min_width_160)

{

    uint8_t bit_buf;

    unsigned int bit_pos, lv, lv1, lv2;

    int *width_tbl, width_tbl_arr[10];

    const signed char *ref_vectors;

    uint8_t *cur_frm_pos, *ref_frm_pos, *cp, *cp2;


    uint32_t *cur_lp, *ref_lp;

    const uint32_t *correction_lp[2], *correctionloworder_lp[2], *correctionhighorder_lp[2];

    uint8_t *correction_type_sp[2];

    struct ustr strip_tbl[20], *strip;

    int i, j, k, lp1, lp2, flag1, cmd, blks_width, blks_height, region_160_width,

        rle_v1, rle_v2, rle_v3;

    unsigned short res;



    bit_buf = 0;

    ref_vectors = NULL;



    width_tbl = width_tbl_arr + 1;

    i = (width < 0 ? width + 3 : width)/4;

    for(j = -1; j < 8; j++)

        width_tbl[j] = i * j;



    strip = strip_tbl;



    for(region_160_width = 0; region_160_width < (width - min_width_160); region_160_width += min_width_160);



    strip->ypos = strip->xpos = 0;

    for(strip->width = min_width_160; width > strip->width; strip->width *= 2);

    strip->height = height;

    strip->split_direction = 0;

    strip->split_flag = 0;

    strip->usl7 = 0;



    bit_pos = 0;



    rle_v1 = rle_v2 = rle_v3 = 0;



    while(strip >= strip_tbl) {

        if(bit_pos <= 0) {

            bit_pos = 8;

            bit_buf = *buf1++;

        }



        bit_pos -= 2;

        cmd = (bit_buf >> bit_pos) & 0x03;



        if(cmd == 0) {

            strip++;

            if(strip >= strip_tbl + FF_ARRAY_ELEMS(strip_tbl)) {

                av_log(s->avctx, AV_LOG_WARNING, "out of range strip\n");

                break;

            }

            memcpy(strip, strip-1, sizeof(*strip));

            strip->split_flag = 1;

            strip->split_direction = 0;

            strip->height = (strip->height > 8 ? ((strip->height+8)>>4)<<3 : 4);

            continue;

        } else if(cmd == 1) {

            strip++;

            if(strip >= strip_tbl + FF_ARRAY_ELEMS(strip_tbl)) {

                av_log(s->avctx, AV_LOG_WARNING, "out of range strip\n");

                break;

            }

            memcpy(strip, strip-1, sizeof(*strip));

            strip->split_flag = 1;

            strip->split_direction = 1;

            strip->width = (strip->width > 8 ? ((strip->width+8)>>4)<<3 : 4);

            continue;

        } else if(cmd == 2) {

            if(strip->usl7 == 0) {

                strip->usl7 = 1;

                ref_vectors = NULL;

                continue;

            }

        } else if(cmd == 3) {

            if(strip->usl7 == 0) {

                strip->usl7 = 1;

                ref_vectors = (const signed char*)buf2 + (*buf1 * 2);

                buf1++;

                continue;

            }

        }



        cur_frm_pos = cur + width * strip->ypos + strip->xpos;



        if((blks_width = strip->width) < 0)

            blks_width += 3;

        blks_width >>= 2;

        blks_height = strip->height;



        if(ref_vectors != NULL) {

            ref_frm_pos = ref + (ref_vectors[0] + strip->ypos) * width +

