yuv2rgb48_1_c_template(SwsContext *c, const uint16_t *buf0,

                       const uint16_t *ubuf0, const uint16_t *ubuf1,

                       const uint16_t *vbuf0, const uint16_t *vbuf1,

                       const uint16_t *abuf0, uint8_t *dest, int dstW,

                       int uvalpha, enum PixelFormat dstFormat,

                       int flags, int y, enum PixelFormat target)

{

    int i;



    if (uvalpha < 2048) {

        for (i = 0; i < (dstW >> 1); i++) {

            int Y1 = buf0[i * 2]     >> 7;

            int Y2 = buf0[i * 2 + 1] >> 7;

            int U  = ubuf1[i]        >> 7;

            int V  = vbuf1[i]        >> 7;

            const uint8_t *r = (const uint8_t *) c->table_rV[V],

                          *g = (const uint8_t *)(c->table_gU[U] + c->table_gV[V]),

                          *b = (const uint8_t *) c->table_bU[U];



            dest[ 0] = dest[ 1] = r_b[Y1];

            dest[ 2] = dest[ 3] =   g[Y1];

            dest[ 4] = dest[ 5] = b_r[Y1];

            dest[ 6] = dest[ 7] = r_b[Y2];

            dest[ 8] = dest[ 9] =   g[Y2];

            dest[10] = dest[11] = b_r[Y2];

            dest += 12;

        }

    } else {

        for (i = 0; i < (dstW >> 1); i++) {

            int Y1 =  buf0[i * 2]          >> 7;

            int Y2 =  buf0[i * 2 + 1]      >> 7;

            int U  = (ubuf0[i] + ubuf1[i]) >> 8;

            int V  = (vbuf0[i] + vbuf1[i]) >> 8;

            const uint8_t *r = (const uint8_t *) c->table_rV[V],

                          *g = (const uint8_t *)(c->table_gU[U] + c->table_gV[V]),

                          *b = (const uint8_t *) c->table_bU[U];



            dest[ 0] = dest[ 1] = r_b[Y1];

            dest[ 2] = dest[ 3] =   g[Y1];

            dest[ 4] = dest[ 5] = b_r[Y1];

            dest[ 6] = dest[ 7] = r_b[Y2];

            dest[ 8] = dest[ 9] =   g[Y2];

            dest[10] = dest[11] = b_r[Y2];

            dest += 12;

        }

    }

}

int net_init_tap(QemuOpts *opts, Monitor *mon, const char *name, VLANState *vlan)

{

    TAPState *s;

    int fd, vnet_hdr = 0;



    if (qemu_opt_get(opts, "fd")) {

        if (qemu_opt_get(opts, "ifname") ||

            qemu_opt_get(opts, "script") ||

            qemu_opt_get(opts, "downscript") ||

            qemu_opt_get(opts, "vnet_hdr")) {

            error_report("ifname=, script=, downscript= and vnet_hdr= is invalid with fd=");

            return -1;

        }



        fd = net_handle_fd_param(mon, qemu_opt_get(opts, "fd"));

        if (fd == -1) {

            return -1;

        }



        fcntl(fd, F_SETFL, O_NONBLOCK);



        vnet_hdr = tap_probe_vnet_hdr(fd);

    } else {

        if (!qemu_opt_get(opts, "script")) {

            qemu_opt_set(opts, "script", DEFAULT_NETWORK_SCRIPT);

        }



        if (!qemu_opt_get(opts, "downscript")) {

            qemu_opt_set(opts, "downscript", DEFAULT_NETWORK_DOWN_SCRIPT);

        }



        fd = net_tap_init(opts, &vnet_hdr);

        if (fd == -1) {

            return -1;

        }

    }



    s = net_tap_fd_init(vlan, "tap", name, fd, vnet_hdr);

    if (!s) {

        close(fd);

        return -1;

    }



    if (tap_set_sndbuf(s->fd, opts) < 0) {

        return -1;

    }



    if (qemu_opt_get(opts, "fd")) {

        snprintf(s->nc.info_str, sizeof(s->nc.info_str), "fd=%d", fd);

    } else {

        const char *ifname, *script, *downscript;



        ifname     = qemu_opt_get(opts, "ifname");

        script     = qemu_opt_get(opts, "script");

        downscript = qemu_opt_get(opts, "downscript");



        snprintf(s->nc.info_str, sizeof(s->nc.info_str),

                 "ifname=%s,script=%s,downscript=%s",

                 ifname, script, downscript);



        if (strcmp(downscript, "no") != 0) {

            snprintf(s->down_script, sizeof(s->down_script), "%s", downscript);

            snprintf(s->down_script_arg, sizeof(s->down_script_arg), "%s", ifname);

        }

    }



    if (qemu_opt_get_bool(opts, "vhost", !!qemu_opt_get(opts, "vhostfd") ||

                          qemu_opt_get_bool(opts, "vhostforce", false))) {

        int vhostfd, r;

        bool force = qemu_opt_get_bool(opts, "vhostforce", false);

        if (qemu_opt_get(opts, "vhostfd")) {

            r = net_handle_fd_param(mon, qemu_opt_get(opts, "vhostfd"));

            if (r == -1) {

                return -1;

            }

            vhostfd = r;

        } else {

            vhostfd = -1;

        }

        s->vhost_net = vhost_net_init(&s->nc, vhostfd, force);

        if (!s->vhost_net) {

            error_report("vhost-net requested but could not be initialized");

            return -1;

        }

    } else if (qemu_opt_get(opts, "vhostfd")) {

        error_report("vhostfd= is not valid without vhost");

        return -1;

    }



    return 0;

}

