        drc->awaiting_release = true;

        trace_spapr_drc_awaiting_allocation(spapr_drc_index(drc));

        return;

    }



    spapr_drc_release(drc);

}

static int vhost_user_set_log_base(struct vhost_dev *dev, uint64_t base,

                                   struct vhost_log *log)

{

    int fds[VHOST_MEMORY_MAX_NREGIONS];

    size_t fd_num = 0;

    bool shmfd = virtio_has_feature(dev->protocol_features,

                                    VHOST_USER_PROTOCOL_F_LOG_SHMFD);

    VhostUserMsg msg = {

        .request = VHOST_USER_SET_LOG_BASE,

        .flags = VHOST_USER_VERSION,

        .u64 = base,

        .size = sizeof(m.u64),

    };



    if (shmfd && log->fd != -1) {

        fds[fd_num++] = log->fd;

    }



    vhost_user_write(dev, &msg, fds, fd_num);



    if (shmfd) {

        msg.size = 0;

        if (vhost_user_read(dev, &msg) < 0) {

            return 0;

        }



        if (msg.request != VHOST_USER_SET_LOG_BASE) {

            error_report("Received unexpected msg type. "

                         "Expected %d received %d",

                         VHOST_USER_SET_LOG_BASE, msg.request);

            return -1;

        }

    }



    return 0;

}

static void *vmstate_base_addr(void *opaque, VMStateField *field, bool alloc)

{

    void *base_addr = opaque + field->offset;



    if (field->flags & VMS_POINTER) {

        if (alloc && (field->flags & VMS_ALLOC)) {

            gsize size = 0;

            if (field->flags & VMS_VBUFFER) {

                size = vmstate_size(opaque, field);

            } else {

                int n_elems = vmstate_n_elems(opaque, field);

                if (n_elems) {

                    size = n_elems * field->size;

                }

            }

            if (size) {

                *((void **)base_addr + field->start) = g_malloc(size);

            }

        }

        base_addr = *(void **)base_addr + field->start;

    }



    return base_addr;

}

static void add_pixels_clamped_c(const int16_t *block, uint8_t *av_restrict pixels,

                                 ptrdiff_t line_size)

{

    int i;



    /* read the pixels */

    for (i = 0; i < 8; i++) {

        pixels[0] = av_clip_uint8(pixels[0] + block[0]);

        pixels[1] = av_clip_uint8(pixels[1] + block[1]);

        pixels[2] = av_clip_uint8(pixels[2] + block[2]);

        pixels[3] = av_clip_uint8(pixels[3] + block[3]);

        pixels[4] = av_clip_uint8(pixels[4] + block[4]);

        pixels[5] = av_clip_uint8(pixels[5] + block[5]);

        pixels[6] = av_clip_uint8(pixels[6] + block[6]);

        pixels[7] = av_clip_uint8(pixels[7] + block[7]);

        pixels   += line_size;

        block    += 8;

    }

}

const char *avio_enum_protocols(void **opaque, int output)

{

    URLProtocol *p;

    *opaque = ffurl_protocol_next(*opaque);

    if (!(p = *opaque))

        return NULL;

    if ((output && p->url_write) || (!output && p->url_read))

        return p->name;

    return avio_enum_protocols(opaque, output);

}

static int read_highpass(AVCodecContext *avctx, uint8_t *ptr, int plane, AVFrame *frame)
{
    PixletContext *ctx = avctx->priv_data;
    ptrdiff_t stride = frame->linesize[plane] / 2;
    int i, ret;
    for (i = 0; i < ctx->levels * 3; i++) {
        int32_t a = bytestream2_get_be32(&ctx->gb);
        int32_t b = bytestream2_get_be32(&ctx->gb);
        int32_t c = bytestream2_get_be32(&ctx->gb);
        int32_t d = bytestream2_get_be32(&ctx->gb);
        int16_t *dest = (int16_t *)frame->data[plane] + ctx->band[plane][i + 1].x +
                                               stride * ctx->band[plane][i + 1].y;
        unsigned size = ctx->band[plane][i + 1].size;
        uint32_t magic;
        magic = bytestream2_get_be32(&ctx->gb);
        if (magic != 0xDEADBEEF) {
            av_log(avctx, AV_LOG_ERROR, "wrong magic number: 0x%08"PRIX32
                   " for plane %d, band %d\n", magic, plane, i);
        }
        ret = read_high_coeffs(avctx, ptr + bytestream2_tell(&ctx->gb), dest, size,
                               c, (b >= FFABS(a)) ? b : a, d,
                               ctx->band[plane][i + 1].width, stride);
        if (ret < 0) {
            av_log(avctx, AV_LOG_ERROR, "error in highpass coefficients for plane %d, band %d\n", plane, i);
            return ret;
        }
        bytestream2_skip(&ctx->gb, ret);
    }
    return 0;
}

static int vp9_superframe_split_filter(AVBSFContext *ctx, AVPacket *out)

{

    VP9SFSplitContext *s = ctx->priv_data;

    AVPacket *in;

    int i, j, ret, marker;

    int is_superframe = !!s->buffer_pkt;



    if (!s->buffer_pkt) {

        ret = ff_bsf_get_packet(ctx, &s->buffer_pkt);

        if (ret < 0)

            return ret;

        in = s->buffer_pkt;



        marker = in->data[in->size - 1];

        if ((marker & 0xe0) == 0xc0) {

            int length_size = 1 + ((marker >> 3) & 0x3);

            int   nb_frames = 1 + (marker & 0x7);

            int    idx_size = 2 + nb_frames * length_size;



            if (in->size >= idx_size && in->data[in->size - idx_size] == marker) {

                GetByteContext bc;

                int total_size = 0;



                bytestream2_init(&bc, in->data + in->size + 1 - idx_size,

                                 nb_frames * length_size);



                for (i = 0; i < nb_frames; i++) {

                    int frame_size = 0;

                    for (j = 0; j < length_size; j++)

                        frame_size |= bytestream2_get_byte(&bc) << (j * 8);



                    total_size += frame_size;

                    if (total_size > in->size - idx_size) {

                        av_log(ctx, AV_LOG_ERROR,

                               "Invalid frame size in a superframe: %d\n", frame_size);

                        ret = AVERROR(EINVAL);

                        goto fail;

                    }

                    s->sizes[i] = frame_size;

                }

                s->nb_frames         = nb_frames;

                s->next_frame        = 0;

                s->next_frame_offset = 0;

                is_superframe        = 1;

            }

        }

    }



    if (is_superframe) {

        GetBitContext gb;

        int profile, invisible = 0;



        ret = av_packet_ref(out, s->buffer_pkt);

        if (ret < 0)

            goto fail;



        out->data += s->next_frame_offset;

        out->size  = s->sizes[s->next_frame];



        s->next_frame_offset += out->size;

        s->next_frame++;



        if (s->next_frame >= s->nb_frames)

            av_packet_free(&s->buffer_pkt);



        ret = init_get_bits8(&gb, out->data, out->size);

        if (ret < 0)

            goto fail;



        get_bits(&gb, 2); // frame_marker

        profile  = get_bits1(&gb);

        profile |= get_bits1(&gb) << 1;

        if (profile == 3)

            get_bits1(&gb);

        if (!get_bits1(&gb)) {

            get_bits1(&gb);

            invisible = !get_bits1(&gb);

        }



        if (invisible)

            out->pts = AV_NOPTS_VALUE;



    } else {

        av_packet_move_ref(out, s->buffer_pkt);

        av_packet_free(&s->buffer_pkt);

    }



    return 0;

fail:

    av_packet_free(&s->buffer_pkt);

    return ret;

}

static int coroutine_fn v9fs_complete_renameat(V9fsPDU *pdu, int32_t olddirfid,

                                               V9fsString *old_name,

                                               int32_t newdirfid,

                                               V9fsString *new_name)

{

    int err = 0;

    V9fsState *s = pdu->s;

    V9fsFidState *newdirfidp = NULL, *olddirfidp = NULL;



    olddirfidp = get_fid(pdu, olddirfid);

    if (olddirfidp == NULL) {

        err = -ENOENT;

        goto out;

    }

    if (newdirfid != -1) {

        newdirfidp = get_fid(pdu, newdirfid);

        if (newdirfidp == NULL) {

            err = -ENOENT;

            goto out;

        }

    } else {

        newdirfidp = get_fid(pdu, olddirfid);

    }



    err = v9fs_co_renameat(pdu, &olddirfidp->path, old_name,

                           &newdirfidp->path, new_name);

    if (err < 0) {

        goto out;

    }

    if (s->ctx.export_flags & V9FS_PATHNAME_FSCONTEXT) {

        /* Only for path based fid  we need to do the below fixup */

        v9fs_fix_fid_paths(pdu, &olddirfidp->path, old_name,

                           &newdirfidp->path, new_name);

    }

out:

    if (olddirfidp) {

        put_fid(pdu, olddirfidp);

    }

    if (newdirfidp) {

        put_fid(pdu, newdirfidp);

    }

    return err;

}

static int decode_bytes(const uint8_t *input, uint8_t *out, int bytes)

{

    int i, off;

    uint32_t c;

    const uint32_t *buf;

    uint32_t *output = (uint32_t *)out;



    off = (intptr_t)input & 3;

    buf = (const uint32_t *)(input - off);

    c   = av_be2ne32((0x537F6103 >> (off * 8)) | (0x537F6103 << (32 - (off * 8))));

    bytes += 3 + off;

    for (i = 0; i < bytes / 4; i++)

        output[i] = c ^ buf[i];



    if (off)

        avpriv_request_sample(NULL, "Offset of %d", off);



    return off;

}

static int encode_frame(AVCodecContext *avctx, unsigned char *buf, int buf_size, void *data){

    SnowContext *s = avctx->priv_data;

    CABACContext * const c= &s->c;

    AVFrame *pict = data;

    const int width= s->avctx->width;

    const int height= s->avctx->height;

    int used_count= 0;

    int log2_threshold, level, orientation, plane_index, i;



    ff_init_cabac_encoder(c, buf, buf_size);

    ff_init_cabac_states(c, ff_h264_lps_range, ff_h264_mps_state, ff_h264_lps_state, 64);



    s->input_picture = *pict;



    memset(s->header_state, 0, sizeof(s->header_state));



    s->keyframe=avctx->gop_size==0 || avctx->frame_number % avctx->gop_size == 0;

    pict->pict_type= s->keyframe ? FF_I_TYPE : FF_P_TYPE;



    if(pict->quality){

        s->qlog= rint(QROOT*log(pict->quality / (float)FF_QP2LAMBDA)/log(2));

        //<64 >60

        s->qlog += 61;

    }else{

        s->qlog= LOSSLESS_QLOG;

    }



    for(i=0; i<s->mb_band.stride * s->mb_band.height; i++){

        s->mb_band.buf[i]= s->keyframe;

    }



    frame_start(s);



    if(pict->pict_type == P_TYPE){

        int block_width = (width +15)>>4;

        int block_height= (height+15)>>4;

        int stride= s->current_picture.linesize[0];

        uint8_t *src_plane= s->input_picture.data[0];

        int src_stride= s->input_picture.linesize[0];

        int x,y;



        assert(s->current_picture.data[0]);

        assert(s->last_picture.data[0]);



        s->m.avctx= s->avctx;

        s->m.current_picture.data[0]= s->current_picture.data[0];

        s->m.   last_picture.data[0]= s->   last_picture.data[0];

        s->m.    new_picture.data[0]= s->  input_picture.data[0];

        s->m.current_picture_ptr= &s->m.current_picture;

        s->m.   last_picture_ptr= &s->m.   last_picture;

        s->m.linesize=

        s->m.   last_picture.linesize[0]=

        s->m.    new_picture.linesize[0]=

        s->m.current_picture.linesize[0]= stride;

        s->m.width = width;

        s->m.height= height;

        s->m.mb_width = block_width;

        s->m.mb_height= block_height;

        s->m.mb_stride=   s->m.mb_width+1;

        s->m.b8_stride= 2*s->m.mb_width+1;

        s->m.f_code=1;

        s->m.pict_type= pict->pict_type;

        s->m.me_method= s->avctx->me_method;

        s->m.me.scene_change_score=0;

        s->m.flags= s->avctx->flags;

        s->m.quarter_sample= (s->avctx->flags & CODEC_FLAG_QPEL)!=0;

        s->m.out_format= FMT_H263;

        s->m.unrestricted_mv= 1;



        s->m.lambda= pict->quality * 3/2; //FIXME bug somewhere else

        s->m.qscale= (s->m.lambda*139 + FF_LAMBDA_SCALE*64) >> (FF_LAMBDA_SHIFT + 7);

        s->m.lambda2= (s->m.lambda*s->m.lambda + FF_LAMBDA_SCALE/2) >> FF_LAMBDA_SHIFT;



        if(!s->motion_val8){

            s->motion_val8 = av_mallocz(s->m.b8_stride*block_height*2*2*sizeof(int16_t));

            s->motion_val16= av_mallocz(s->m.mb_stride*block_height*2*sizeof(int16_t));

        }



        s->m.mb_type= s->mb_type;



        //dummies, to avoid segfaults

        s->m.current_picture.mb_mean  = s->mb_mean;

        s->m.current_picture.mb_var   = (int16_t*)s->dummy;

        s->m.current_picture.mc_mb_var= (int16_t*)s->dummy;

        s->m.current_picture.mb_type  = s->dummy;



        s->m.current_picture.motion_val[0]= s->motion_val8;

        s->m.p_mv_table= s->motion_val16;

        s->m.dsp= s->dsp; //move

        ff_init_me(&s->m);





        s->m.me.pre_pass=1;

        s->m.me.dia_size= s->avctx->pre_dia_size;

        s->m.first_slice_line=1;

        for(y= block_height-1; y >= 0; y--) {

            uint8_t src[stride*16];



            s->m.new_picture.data[0]= src - y*16*stride; //ugly

            s->m.mb_y= y;

            for(i=0; i<16 && i + 16*y<height; i++){

                memcpy(&src[i*stride], &src_plane[(i+16*y)*src_stride], width);

                for(x=width; x<16*block_width; x++)

                    src[i*stride+x]= src[i*stride+x-1];

            }

            for(; i<16 && i + 16*y<16*block_height; i++)

                memcpy(&src[i*stride], &src[(i-1)*stride], 16*block_width);



            for(x=block_width-1; x >=0 ;x--) {

                s->m.mb_x= x;

                ff_init_block_index(&s->m);

                ff_update_block_index(&s->m);

                ff_pre_estimate_p_frame_motion(&s->m, x, y);

            }

            s->m.first_slice_line=0;

        }        

        s->m.me.pre_pass=0;





        s->m.me.dia_size= s->avctx->dia_size;

        s->m.first_slice_line=1;

        for (y = 0; y < block_height; y++) {

            uint8_t src[stride*16];



            s->m.new_picture.data[0]= src - y*16*stride; //ugly

            s->m.mb_y= y;



            assert(width <= stride);

            assert(width <= 16*block_width);



            for(i=0; i<16 && i + 16*y<height; i++){

                memcpy(&src[i*stride], &src_plane[(i+16*y)*src_stride], width);

                for(x=width; x<16*block_width; x++)

                    src[i*stride+x]= src[i*stride+x-1];

            }

            for(; i<16 && i + 16*y<16*block_height; i++)

                memcpy(&src[i*stride], &src[(i-1)*stride], 16*block_width);



            for (x = 0; x < block_width; x++) {

                int mb_xy= x + y*(s->mb_band.stride);

                s->m.mb_x= x;

                ff_init_block_index(&s->m);

                ff_update_block_index(&s->m);



                ff_estimate_p_frame_motion(&s->m, x, y);



                s->mb_band   .buf[mb_xy]= (s->m.mb_type[x + y*s->m.mb_stride]&CANDIDATE_MB_TYPE_INTER)

                 ? 0 : 2;

                s->mv_band[0].buf[mb_xy]= s->motion_val16[x + y*s->m.mb_stride][0];

                s->mv_band[1].buf[mb_xy]= s->motion_val16[x + y*s->m.mb_stride][1];



                if(s->mb_band   .buf[x + y*(s->mb_band.stride)]==2 && 0){

                    int dc0=128, dc1=128, dc, dc2, dir;

                    int offset= (s->avctx->flags & CODEC_FLAG_QPEL) ? 64 : 32;



                    dc       =s->mb_mean[x +  y   *s->m.mb_stride    ];

                    if(x) dc0=s->mb_mean[x +  y   *s->m.mb_stride - 1];

                    if(y) dc1=s->mb_mean[x + (y-1)*s->m.mb_stride    ];

                    dc2= (dc0+dc1)>>1;

#if 0

                    if     (ABS(dc0 - dc) < ABS(dc1 - dc) && ABS(dc0 - dc) < ABS(dc2 - dc))

                        dir= 1;

                    else if(ABS(dc0 - dc) >=ABS(dc1 - dc) && ABS(dc1 - dc) < ABS(dc2 - dc))

                        dir=-1;

                    else

                        dir=0;

#endif                    

                    if(ABS(dc0 - dc) < ABS(dc1 - dc) && x){

                        s->mv_band[0].buf[mb_xy]= s->mv_band[0].buf[x + y*(s->mb_band.stride)-1] - offset;

                        s->mv_band[1].buf[mb_xy]= s->mv_band[1].buf[x + y*(s->mb_band.stride)-1];

                        s->mb_mean[x +  y   *s->m.mb_stride    ]= dc0;

                    }else if(y){

                        s->mv_band[0].buf[mb_xy]= s->mv_band[0].buf[x + (y-1)*(s->mb_band.stride)];

                        s->mv_band[1].buf[mb_xy]= s->mv_band[1].buf[x + (y-1)*(s->mb_band.stride)] - offset;

                        s->mb_mean[x +  y   *s->m.mb_stride    ]= dc1;

                    }

                }

//                s->mb_band   .buf[x + y*(s->mb_band.stride)]=1; //FIXME intra only test

            }

            s->m.first_slice_line=0;

        }

        assert(s->m.pict_type == P_TYPE);

        if(s->m.me.scene_change_score > s->avctx->scenechange_threshold){

            s->m.pict_type= 

            pict->pict_type =I_TYPE;

            for(i=0; i<s->mb_band.stride * s->mb_band.height; i++){

                s->mb_band.buf[i]= 1;

                s->mv_band[0].buf[i]=

                s->mv_band[1].buf[i]= 0;

            }

    //printf("Scene change detected, encoding as I Frame %d %d\n", s->current_picture.mb_var_sum, s->current_picture.mc_mb_var_sum);

        }        

    }



    s->m.first_slice_line=1;



    s->qbias= pict->pict_type == P_TYPE ? 2 : 0;



    encode_header(s);



    decorrelate(s, &s->mb_band   , s->mb_band   .buf, s->mb_band   .stride, 0, 1);

    decorrelate(s, &s->mv_band[0], s->mv_band[0].buf, s->mv_band[0].stride, 0, 1);

    decorrelate(s, &s->mv_band[1], s->mv_band[1].buf, s->mv_band[1].stride, 0 ,1);

    encode_subband(s, &s->mb_band   , s->mb_band   .buf, NULL, s->mb_band   .stride, 0);

    encode_subband(s, &s->mv_band[0], s->mv_band[0].buf, NULL, s->mv_band[0].stride, 0);

    encode_subband(s, &s->mv_band[1], s->mv_band[1].buf, NULL, s->mv_band[1].stride, 0);



//FIXME avoid this

    correlate(s, &s->mb_band   , s->mb_band   .buf, s->mb_band   .stride, 1, 1);

    correlate(s, &s->mv_band[0], s->mv_band[0].buf, s->mv_band[0].stride, 1, 1);

    correlate(s, &s->mv_band[1], s->mv_band[1].buf, s->mv_band[1].stride, 1, 1);



    for(plane_index=0; plane_index<3; plane_index++){

        Plane *p= &s->plane[plane_index];

        int w= p->width;

        int h= p->height;

        int x, y;

        int bits= put_bits_count(&s->c.pb);



        //FIXME optimize

     if(pict->data[plane_index]) //FIXME gray hack

        for(y=0; y<h; y++){

            for(x=0; x<w; x++){

                s->spatial_dwt_buffer[y*w + x]= pict->data[plane_index][y*pict->linesize[plane_index] + x]<<8;

            }

        }

        predict_plane(s, s->spatial_dwt_buffer, plane_index, 0);

        if(s->qlog == LOSSLESS_QLOG){

            for(y=0; y<h; y++){

                for(x=0; x<w; x++){

                    s->spatial_dwt_buffer[y*w + x]= (s->spatial_dwt_buffer[y*w + x] + 127)>>8;

                }

            }

        }



        ff_spatial_dwt(s->spatial_dwt_buffer, w, h, w, s->spatial_decomposition_type, s->spatial_decomposition_count);



        for(level=0; level<s->spatial_decomposition_count; level++){

            for(orientation=level ? 1 : 0; orientation<4; orientation++){

                SubBand *b= &p->band[level][orientation];



                quantize(s, b, b->buf, b->stride, s->qbias);

                if(orientation==0)

                    decorrelate(s, b, b->buf, b->stride, pict->pict_type == P_TYPE, 0);

                encode_subband(s, b, b->buf, b->parent ? b->parent->buf : NULL, b->stride, orientation);

                assert(b->parent==NULL || b->parent->stride == b->stride*2);

                if(orientation==0)

                    correlate(s, b, b->buf, b->stride, 1, 0);

            }

        }

//        av_log(NULL, AV_LOG_DEBUG, "plane:%d bits:%d\n", plane_index, put_bits_count(&s->c.pb) - bits);



        for(level=0; level<s->spatial_decomposition_count; level++){

            for(orientation=level ? 1 : 0; orientation<4; orientation++){

                SubBand *b= &p->band[level][orientation];



                dequantize(s, b, b->buf, b->stride);

            }

        }



        ff_spatial_idwt(s->spatial_dwt_buffer, w, h, w, s->spatial_decomposition_type, s->spatial_decomposition_count);

        if(s->qlog == LOSSLESS_QLOG){

            for(y=0; y<h; y++){

                for(x=0; x<w; x++){

                    s->spatial_dwt_buffer[y*w + x]<<=8;

                }

            }

        }

        predict_plane(s, s->spatial_dwt_buffer, plane_index, 1);

        //FIXME optimize

        for(y=0; y<h; y++){

            for(x=0; x<w; x++){

                int v= (s->spatial_dwt_buffer[y*w + x]+128)>>8;

                if(v&(~255)) v= ~(v>>31);

                s->current_picture.data[plane_index][y*s->current_picture.linesize[plane_index] + x]= v;

            }

        }

        if(s->avctx->flags&CODEC_FLAG_PSNR){

            int64_t error= 0;



    if(pict->data[plane_index]) //FIXME gray hack

            for(y=0; y<h; y++){

                for(x=0; x<w; x++){

                    int d= s->current_picture.data[plane_index][y*s->current_picture.linesize[plane_index] + x] - pict->data[plane_index][y*pict->linesize[plane_index] + x];

                    error += d*d;

                }

            }

            s->avctx->error[plane_index] += error;

            s->avctx->error[3] += error;

        }

    }



    if(s->last_picture.data[0])

        avctx->release_buffer(avctx, &s->last_picture);



    emms_c();



    return put_cabac_terminate(c, 1);

}

static void rtas_ibm_set_eeh_option(PowerPCCPU *cpu,

                                    sPAPREnvironment *spapr,

                                    uint32_t token, uint32_t nargs,

                                    target_ulong args, uint32_t nret,

                                    target_ulong rets)

{

    sPAPRPHBState *sphb;

    sPAPRPHBClass *spc;

    uint32_t addr, option;

    uint64_t buid;

    int ret;



    if ((nargs != 4) || (nret != 1)) {

        goto param_error_exit;

    }



    buid = ((uint64_t)rtas_ld(args, 1) << 32) | rtas_ld(args, 2);

    addr = rtas_ld(args, 0);

    option = rtas_ld(args, 3);



    sphb = find_phb(spapr, buid);

    if (!sphb) {

        goto param_error_exit;

    }



    spc = SPAPR_PCI_HOST_BRIDGE_GET_CLASS(sphb);

    if (!spc->eeh_set_option) {

        goto param_error_exit;

    }



    ret = spc->eeh_set_option(sphb, addr, option);

    rtas_st(rets, 0, ret);

    return;



param_error_exit:

    rtas_st(rets, 0, RTAS_OUT_PARAM_ERROR);

}

static bool nvic_user_access_ok(NVICState *s, hwaddr offset)

{

    /* Return true if unprivileged access to this register is permitted. */

    switch (offset) {

    case 0xf00: /* STIR: accessible only if CCR.USERSETMPEND permits */

        return s->cpu->env.v7m.ccr & R_V7M_CCR_USERSETMPEND_MASK;

    default:

        /* All other user accesses cause a BusFault unconditionally */

        return false;

    }

}

static void kvm_arm_gic_realize(DeviceState *dev, Error **errp)
{
    int i;
    GICState *s = KVM_ARM_GIC(dev);
    SysBusDevice *sbd = SYS_BUS_DEVICE(dev);
    KVMARMGICClass *kgc = KVM_ARM_GIC_GET_CLASS(s);
    Error *local_err = NULL;
    int ret;
    kgc->parent_realize(dev, &local_err);
    if (local_err) {
        error_propagate(errp, local_err);
    i = s->num_irq - GIC_INTERNAL;
    /* For the GIC, also expose incoming GPIO lines for PPIs for each CPU.
     * GPIO array layout is thus:
     *  [0..N-1] SPIs
     *  [N..N+31] PPIs for CPU 0
     *  [N+32..N+63] PPIs for CPU 1
     *   ...
     */
    i += (GIC_INTERNAL * s->num_cpu);
    qdev_init_gpio_in(dev, kvm_arm_gic_set_irq, i);
    /* We never use our outbound IRQ/FIQ lines but provide them so that
     * we maintain the same interface as the non-KVM GIC.
     */
    for (i = 0; i < s->num_cpu; i++) {
        sysbus_init_irq(sbd, &s->parent_irq[i]);
    for (i = 0; i < s->num_cpu; i++) {
        sysbus_init_irq(sbd, &s->parent_fiq[i]);
    /* Try to create the device via the device control API */
    s->dev_fd = -1;
    ret = kvm_create_device(kvm_state, KVM_DEV_TYPE_ARM_VGIC_V2, false);
    if (ret >= 0) {
        s->dev_fd = ret;
    } else if (ret != -ENODEV && ret != -ENOTSUP) {
        error_setg_errno(errp, -ret, "error creating in-kernel VGIC");
    if (kvm_gic_supports_attr(s, KVM_DEV_ARM_VGIC_GRP_NR_IRQS, 0)) {
        uint32_t numirqs = s->num_irq;
        kvm_gic_access(s, KVM_DEV_ARM_VGIC_GRP_NR_IRQS, 0, 0, &numirqs, 1);
    /* Tell the kernel to complete VGIC initialization now */
    if (kvm_gic_supports_attr(s, KVM_DEV_ARM_VGIC_GRP_CTRL,
                              KVM_DEV_ARM_VGIC_CTRL_INIT)) {
        kvm_gic_access(s, KVM_DEV_ARM_VGIC_GRP_CTRL,
                          KVM_DEV_ARM_VGIC_CTRL_INIT, 0, 0, 1);
    /* Distributor */
    memory_region_init_reservation(&s->iomem, OBJECT(s),
                                   "kvm-gic_dist", 0x1000);
    sysbus_init_mmio(sbd, &s->iomem);
    kvm_arm_register_device(&s->iomem,
                            (KVM_ARM_DEVICE_VGIC_V2 << KVM_ARM_DEVICE_ID_SHIFT)
                            | KVM_VGIC_V2_ADDR_TYPE_DIST,
                            KVM_DEV_ARM_VGIC_GRP_ADDR,
                            KVM_VGIC_V2_ADDR_TYPE_DIST,
                            s->dev_fd);
    /* CPU interface for current core. Unlike arm_gic, we don't
     * provide the "interface for core #N" memory regions, because
     * cores with a VGIC don't have those.
     */
    memory_region_init_reservation(&s->cpuiomem[0], OBJECT(s),
                                   "kvm-gic_cpu", 0x1000);
    sysbus_init_mmio(sbd, &s->cpuiomem[0]);
    kvm_arm_register_device(&s->cpuiomem[0],
                            (KVM_ARM_DEVICE_VGIC_V2 << KVM_ARM_DEVICE_ID_SHIFT)
                            | KVM_VGIC_V2_ADDR_TYPE_CPU,
                            KVM_DEV_ARM_VGIC_GRP_ADDR,
                            KVM_VGIC_V2_ADDR_TYPE_CPU,
                            s->dev_fd);

void inter_predict(VP8Context *s, uint8_t *dst[3], VP8Macroblock *mb,

                   int mb_x, int mb_y)

{

    int x_off = mb_x << 4, y_off = mb_y << 4;

    int width = 16*s->mb_width, height = 16*s->mb_height;

    AVFrame *ref = s->framep[mb->ref_frame];

    VP56mv *bmv = mb->bmv;



    switch (mb->partitioning) {

    case VP8_SPLITMVMODE_NONE:

        vp8_mc_part(s, dst, ref, x_off, y_off,

                    0, 0, 16, 16, width, height, &mb->mv);

        break;

    case VP8_SPLITMVMODE_4x4: {

        int x, y;

        VP56mv uvmv;



        /* Y */

        for (y = 0; y < 4; y++) {

            for (x = 0; x < 4; x++) {

                vp8_mc(s, 1, dst[0] + 4*y*s->linesize + x*4,

                       ref->data[0], &bmv[4*y + x],

                       4*x + x_off, 4*y + y_off, 4, 4,

                       width, height, s->linesize,

                       s->put_pixels_tab[2]);

            }

        }



        /* U/V */

        x_off >>= 1; y_off >>= 1; width >>= 1; height >>= 1;

        for (y = 0; y < 2; y++) {

            for (x = 0; x < 2; x++) {

                uvmv.x = mb->bmv[ 2*y    * 4 + 2*x  ].x +

                         mb->bmv[ 2*y    * 4 + 2*x+1].x +

                         mb->bmv[(2*y+1) * 4 + 2*x  ].x +

                         mb->bmv[(2*y+1) * 4 + 2*x+1].x;

                uvmv.y = mb->bmv[ 2*y    * 4 + 2*x  ].y +

                         mb->bmv[ 2*y    * 4 + 2*x+1].y +

                         mb->bmv[(2*y+1) * 4 + 2*x  ].y +

                         mb->bmv[(2*y+1) * 4 + 2*x+1].y;

                uvmv.x = (uvmv.x + 2 + (uvmv.x >> (INT_BIT-1))) >> 2;

                uvmv.y = (uvmv.y + 2 + (uvmv.y >> (INT_BIT-1))) >> 2;

                if (s->profile == 3) {

                    uvmv.x &= ~7;

                    uvmv.y &= ~7;

                }

                vp8_mc(s, 0, dst[1] + 4*y*s->uvlinesize + x*4,

                       ref->data[1], &uvmv,

                       4*x + x_off, 4*y + y_off, 4, 4,

                       width, height, s->uvlinesize,

                       s->put_pixels_tab[2]);

                vp8_mc(s, 0, dst[2] + 4*y*s->uvlinesize + x*4,

                       ref->data[2], &uvmv,

                       4*x + x_off, 4*y + y_off, 4, 4,

                       width, height, s->uvlinesize,

                       s->put_pixels_tab[2]);

            }

        }

        break;

    }

    case VP8_SPLITMVMODE_16x8:

        vp8_mc_part(s, dst, ref, x_off, y_off,

                    0, 0, 16, 8, width, height, &bmv[0]);

        vp8_mc_part(s, dst, ref, x_off, y_off,

                    0, 8, 16, 8, width, height, &bmv[1]);

        break;

    case VP8_SPLITMVMODE_8x16:

        vp8_mc_part(s, dst, ref, x_off, y_off,

                    0, 0, 8, 16, width, height, &bmv[0]);

        vp8_mc_part(s, dst, ref, x_off, y_off,

                    8, 0, 8, 16, width, height, &bmv[1]);

        break;

    case VP8_SPLITMVMODE_8x8:

        vp8_mc_part(s, dst, ref, x_off, y_off,

                    0, 0, 8, 8, width, height, &bmv[0]);

        vp8_mc_part(s, dst, ref, x_off, y_off,

                    8, 0, 8, 8, width, height, &bmv[1]);

        vp8_mc_part(s, dst, ref, x_off, y_off,

                    0, 8, 8, 8, width, height, &bmv[2]);

        vp8_mc_part(s, dst, ref, x_off, y_off,

                    8, 8, 8, 8, width, height, &bmv[3]);

        break;

    }

}

static int64_t cpu_get_icount_locked(void)

{

    int64_t icount;

    CPUState *cpu = current_cpu;



    icount = timers_state.qemu_icount;

    if (cpu) {

        if (!cpu_can_do_io(cpu)) {

            fprintf(stderr, "Bad clock read\n");

        }

        icount -= (cpu->icount_decr.u16.low + cpu->icount_extra);

    }

    return timers_state.qemu_icount_bias + cpu_icount_to_ns(icount);

}

static void sigp_start(CPUState *cs, run_on_cpu_data arg)

{

    S390CPU *cpu = S390_CPU(cs);

    SigpInfo *si = arg.host_ptr;



    if (s390_cpu_get_state(cpu) != CPU_STATE_STOPPED) {

        si->cc = SIGP_CC_ORDER_CODE_ACCEPTED;

        return;

    }



    s390_cpu_set_state(CPU_STATE_OPERATING, cpu);

    si->cc = SIGP_CC_ORDER_CODE_ACCEPTED;

}

static void pchip_write(void *opaque, hwaddr addr,

                        uint64_t v32, unsigned size)

{

    TyphoonState *s = opaque;

    uint64_t val, oldval;



    if (addr & 4) {

        val = v32 << 32 | s->latch_tmp;

        addr ^= 4;

    } else {

        s->latch_tmp = v32;

        return;

    }



    switch (addr) {

    case 0x0000:

        /* WSBA0: Window Space Base Address Register.  */

        s->pchip.win[0].base_addr = val;

        break;

    case 0x0040:

        /* WSBA1 */

        s->pchip.win[1].base_addr = val;

        break;

    case 0x0080:

        /* WSBA2 */

        s->pchip.win[2].base_addr = val;

        break;

    case 0x00c0:

        /* WSBA3 */

        s->pchip.win[3].base_addr = val;

        break;



    case 0x0100:

        /* WSM0: Window Space Mask Register.  */

        s->pchip.win[0].mask = val;

        break;

    case 0x0140:

        /* WSM1 */

        s->pchip.win[1].mask = val;

        break;

    case 0x0180:

        /* WSM2 */

        s->pchip.win[2].mask = val;

        break;

    case 0x01c0:

        /* WSM3 */

        s->pchip.win[3].mask = val;

        break;



    case 0x0200:

        /* TBA0: Translated Base Address Register.  */

        s->pchip.win[0].translated_base_pfn = val >> 10;

        break;

    case 0x0240:

        /* TBA1 */

        s->pchip.win[1].translated_base_pfn = val >> 10;

        break;

    case 0x0280:

        /* TBA2 */

        s->pchip.win[2].translated_base_pfn = val >> 10;

        break;

    case 0x02c0:

        /* TBA3 */

        s->pchip.win[3].translated_base_pfn = val >> 10;

        break;



    case 0x0300:

        /* PCTL: Pchip Control Register.  */

        oldval = s->pchip.ctl;

        oldval &= ~0x00001cff0fc7ffull;       /* RW fields */

        oldval |= val & 0x00001cff0fc7ffull;



        s->pchip.ctl = oldval;

        break;



    case 0x0340:

        /* PLAT: Pchip Master Latency Register.  */

        break;

    case 0x03c0:

        /* PERROR: Pchip Error Register.  */

        break;

    case 0x0400:

        /* PERRMASK: Pchip Error Mask Register.  */

        break;

    case 0x0440:

        /* PERRSET: Pchip Error Set Register.  */

        break;



    case 0x0480:

        /* TLBIV: Translation Buffer Invalidate Virtual Register.  */

        break;



    case 0x04c0:

        /* TLBIA: Translation Buffer Invalidate All Register (WO).  */

        break;



    case 0x0500:

        /* PMONCTL */

    case 0x0540:

        /* PMONCNT */

    case 0x0800:

        /* SPRST */

        break;



    default:

        cpu_unassigned_access(current_cpu, addr, true, false, 0, size);

        return;

    }

}

static void vga_precise_update_retrace_info(VGAState *s)

{

    int htotal_chars;

    int hretr_start_char;

    int hretr_skew_chars;

    int hretr_end_char;



    int vtotal_lines;

    int vretr_start_line;

    int vretr_end_line;



    int div2, sldiv2, dots;

    int clocking_mode;

    int clock_sel;

    const int hz[] = {25175000, 28322000, 25175000, 25175000};

    int64_t chars_per_sec;

    struct vga_precise_retrace *r = &s->retrace_info.precise;



    htotal_chars = s->cr[0x00] + 5;

    hretr_start_char = s->cr[0x04];

    hretr_skew_chars = (s->cr[0x05] >> 5) & 3;

    hretr_end_char = s->cr[0x05] & 0x1f;



    vtotal_lines = (s->cr[0x06]

                    | (((s->cr[0x07] & 1) | ((s->cr[0x07] >> 4) & 2)) << 8)) + 2

        ;

    vretr_start_line = s->cr[0x10]

        | ((((s->cr[0x07] >> 2) & 1) | ((s->cr[0x07] >> 6) & 2)) << 8)

        ;

    vretr_end_line = s->cr[0x11] & 0xf;





    div2 = (s->cr[0x17] >> 2) & 1;

    sldiv2 = (s->cr[0x17] >> 3) & 1;



    clocking_mode = (s->sr[0x01] >> 3) & 1;

    clock_sel = (s->msr >> 2) & 3;

    dots = (s->msr & 1) ? 8 : 9;



    chars_per_sec = hz[clock_sel] / dots;



    htotal_chars <<= clocking_mode;



    r->total_chars = vtotal_lines * htotal_chars;

    if (r->freq) {

        r->ticks_per_char = ticks_per_sec / (r->total_chars * r->freq);

    } else {

        r->ticks_per_char = ticks_per_sec / chars_per_sec;

    }



    r->vstart = vretr_start_line;

    r->vend = r->vstart + vretr_end_line + 1;



    r->hstart = hretr_start_char + hretr_skew_chars;

    r->hend = r->hstart + hretr_end_char + 1;

    r->htotal = htotal_chars;



#if 0

    printf (

        "hz=%f\n"

        "htotal = %d\n"

        "hretr_start = %d\n"

        "hretr_skew = %d\n"

        "hretr_end = %d\n"

        "vtotal = %d\n"

        "vretr_start = %d\n"

        "vretr_end = %d\n"

        "div2 = %d sldiv2 = %d\n"

        "clocking_mode = %d\n"

        "clock_sel = %d %d\n"

        "dots = %d\n"

        "ticks/char = %lld\n"

        "\n",

        (double) ticks_per_sec / (r->ticks_per_char * r->total_chars),

        htotal_chars,

        hretr_start_char,

        hretr_skew_chars,

        hretr_end_char,

        vtotal_lines,

        vretr_start_line,

        vretr_end_line,

        div2, sldiv2,

        clocking_mode,

        clock_sel,

        hz[clock_sel],

        dots,

        r->ticks_per_char

        );

#endif

}

int av_probe_input_buffer2(AVIOContext *pb, AVInputFormat **fmt,

                          const char *filename, void *logctx,

                          unsigned int offset, unsigned int max_probe_size)

{

    AVProbeData pd = { filename ? filename : "", NULL, -offset };

    uint8_t *buf = NULL;

    uint8_t *mime_type;

    int ret = 0, probe_size, buf_offset = 0;

    int score = 0;



    if (!max_probe_size) {

        max_probe_size = PROBE_BUF_MAX;

    } else if (max_probe_size > PROBE_BUF_MAX) {

        max_probe_size = PROBE_BUF_MAX;

    } else if (max_probe_size < PROBE_BUF_MIN) {

        av_log(logctx, AV_LOG_ERROR,

               "Specified probe size value %u cannot be < %u\n", max_probe_size, PROBE_BUF_MIN);

        return AVERROR(EINVAL);

    }



    if (offset >= max_probe_size) {

        return AVERROR(EINVAL);

    }



    if (!*fmt && pb->av_class && av_opt_get(pb, "mime_type", AV_OPT_SEARCH_CHILDREN, &mime_type) >= 0 && mime_type) {

        if (!av_strcasecmp(mime_type, "audio/aacp")) {

            *fmt = av_find_input_format("aac");

        }

        av_freep(&mime_type);

    }



    for(probe_size= PROBE_BUF_MIN; probe_size<=max_probe_size && !*fmt;

        probe_size = FFMIN(probe_size<<1, FFMAX(max_probe_size, probe_size+1))) {



        if (probe_size < offset) {

            continue;

        }

        score = probe_size < max_probe_size ? AVPROBE_SCORE_RETRY : 0;



        /* read probe data */

        if ((ret = av_reallocp(&buf, probe_size + AVPROBE_PADDING_SIZE)) < 0)

            return ret;

        if ((ret = avio_read(pb, buf + buf_offset, probe_size - buf_offset)) < 0) {

            /* fail if error was not end of file, otherwise, lower score */

            if (ret != AVERROR_EOF) {

                av_free(buf);

                return ret;

            }

            score = 0;

            ret = 0;            /* error was end of file, nothing read */

        }

        buf_offset += ret;

        pd.buf_size = buf_offset - offset;

        pd.buf = &buf[offset];



        memset(pd.buf + pd.buf_size, 0, AVPROBE_PADDING_SIZE);



        /* guess file format */

        *fmt = av_probe_input_format2(&pd, 1, &score);

        if(*fmt){

            if(score <= AVPROBE_SCORE_RETRY){ //this can only be true in the last iteration

                av_log(logctx, AV_LOG_WARNING, "Format %s detected only with low score of %d, misdetection possible!\n", (*fmt)->name, score);

            }else

                av_log(logctx, AV_LOG_DEBUG, "Format %s probed with size=%d and score=%d\n", (*fmt)->name, probe_size, score);

#if 0

            FILE *f = fopen("probestat.tmp", "ab");

            fprintf(f, "probe_size:%d format:%s score:%d filename:%s\n", probe_size, (*fmt)->name, score, filename);

            fclose(f);

#endif

        }

    }



    if (!*fmt) {

        av_free(buf);

        return AVERROR_INVALIDDATA;

    }



    /* rewind. reuse probe buffer to avoid seeking */

    ret = ffio_rewind_with_probe_data(pb, &buf, pd.buf_size);



    return ret < 0 ? ret : score;

}

static ssize_t drop_sync(QIOChannel *ioc, size_t size)

{

    ssize_t ret = 0;

    char small[1024];

    char *buffer;



    buffer = sizeof(small) < size ? small : g_malloc(MIN(65536, size));

    while (size > 0) {

        ssize_t count = read_sync(ioc, buffer, MIN(65536, size));



        if (count <= 0) {

            goto cleanup;

        }

        assert(count <= size);

        size -= count;

        ret += count;

    }



 cleanup:

    if (buffer != small) {

        g_free(buffer);

    }

    return ret;

}

void *qemu_get_virtqueue_element(VirtIODevice *vdev, QEMUFile *f, size_t sz)

{

    VirtQueueElement *elem;

    VirtQueueElementOld data;

    int i;



    qemu_get_buffer(f, (uint8_t *)&data, sizeof(VirtQueueElementOld));



    /* TODO: teach all callers that this can fail, and return failure instead

     * of asserting here.

     * When we do, we might be able to re-enable NDEBUG below.

     */

#ifdef NDEBUG

#error building with NDEBUG is not supported

#endif

    assert(ARRAY_SIZE(data.in_addr) >= data.in_num);

    assert(ARRAY_SIZE(data.out_addr) >= data.out_num);



    elem = virtqueue_alloc_element(sz, data.out_num, data.in_num);

    elem->index = data.index;



    for (i = 0; i < elem->in_num; i++) {

        elem->in_addr[i] = data.in_addr[i];

    }



    for (i = 0; i < elem->out_num; i++) {

        elem->out_addr[i] = data.out_addr[i];

    }



    for (i = 0; i < elem->in_num; i++) {

        /* Base is overwritten by virtqueue_map.  */

        elem->in_sg[i].iov_base = 0;

        elem->in_sg[i].iov_len = data.in_sg[i].iov_len;

    }



    for (i = 0; i < elem->out_num; i++) {

        /* Base is overwritten by virtqueue_map.  */

        elem->out_sg[i].iov_base = 0;

        elem->out_sg[i].iov_len = data.out_sg[i].iov_len;

    }



    virtqueue_map(vdev, elem);

    return elem;

}

static void mirror_read_complete(void *opaque, int ret)

{

    MirrorOp *op = opaque;

    MirrorBlockJob *s = op->s;

    if (ret < 0) {

        BlockDriverState *source = s->common.bs;

        BlockErrorAction action;



        bdrv_set_dirty(source, op->sector_num, op->nb_sectors);

        action = mirror_error_action(s, true, -ret);

        if (action == BLOCK_ERROR_ACTION_REPORT && s->ret >= 0) {

            s->ret = ret;

        }



        mirror_iteration_done(op, ret);

        return;

    }

    bdrv_aio_writev(s->target, op->sector_num, &op->qiov, op->nb_sectors,

                    mirror_write_complete, op);

}

static BlockDriverAIOCB *qcow_aio_writev(BlockDriverState *bs,

        int64_t sector_num, QEMUIOVector *qiov, int nb_sectors,

        BlockDriverCompletionFunc *cb, void *opaque)

{

    BDRVQcowState *s = bs->opaque;

    QCowAIOCB *acb;



    s->cluster_cache_offset = -1; /* disable compressed cache */



    acb = qemu_aio_get(bs, cb, opaque);

    if (!acb)

        return NULL;

    acb->hd_aiocb = NULL;

    acb->sector_num = sector_num;

    acb->qiov = qiov;

    if (qiov->niov > 1) {

        acb->buf = acb->orig_buf = qemu_memalign(512, qiov->size);

        qemu_iovec_to_buffer(qiov, acb->buf);

    } else {

        acb->buf = (uint8_t *)qiov->iov->iov_base;

    }

    acb->nb_sectors = nb_sectors;

    acb->n = 0;



    qcow_aio_write_cb(acb, 0);

    return &acb->common;

}

