static int dma_buf_prepare(BMDMAState *bm, int is_write)

{

    IDEState *s = bmdma_active_if(bm);

    struct {

        uint32_t addr;

        uint32_t size;

    } prd;

    int l, len;



    qemu_sglist_init(&s->sg, s->nsector / (TARGET_PAGE_SIZE/512) + 1);

    s->io_buffer_size = 0;

    for(;;) {

        if (bm->cur_prd_len == 0) {

            /* end of table (with a fail safe of one page) */

            if (bm->cur_prd_last ||

                (bm->cur_addr - bm->addr) >= 4096)

                return s->io_buffer_size != 0;

            cpu_physical_memory_read(bm->cur_addr, (uint8_t *)&prd, 8);

            bm->cur_addr += 8;

            prd.addr = le32_to_cpu(prd.addr);

            prd.size = le32_to_cpu(prd.size);

            len = prd.size & 0xfffe;

            if (len == 0)

                len = 0x10000;

            bm->cur_prd_len = len;

            bm->cur_prd_addr = prd.addr;

            bm->cur_prd_last = (prd.size & 0x80000000);

        }

        l = bm->cur_prd_len;

        if (l > 0) {

            qemu_sglist_add(&s->sg, bm->cur_prd_addr, l);

            bm->cur_prd_addr += l;

            bm->cur_prd_len -= l;

            s->io_buffer_size += l;

        }

    }

    return 1;

}

static int usb_host_claim_interfaces(USBHostDevice *s, int configuration)

{

    USBDevice *udev = USB_DEVICE(s);

    struct libusb_config_descriptor *conf;

    int rc, i;



    for (i = 0; i < USB_MAX_INTERFACES; i++) {

        udev->altsetting[i] = 0;

    }

    udev->ninterfaces   = 0;

    udev->configuration = 0;



    if (configuration == 0) {

        /* address state - ignore */

        return USB_RET_SUCCESS;

    }



    usb_host_detach_kernel(s);



    rc = libusb_get_active_config_descriptor(s->dev, &conf);

    if (rc != 0) {

        return USB_RET_STALL;

    }



    for (i = 0; i < conf->bNumInterfaces; i++) {

        trace_usb_host_claim_interface(s->bus_num, s->addr, configuration, i);

        rc = libusb_claim_interface(s->dh, i);

        usb_host_libusb_error("libusb_claim_interface", rc);

        if (rc != 0) {

            return USB_RET_STALL;

        }

        s->ifs[i].claimed = true;

    }



    udev->ninterfaces   = conf->bNumInterfaces;

    udev->configuration = configuration;



    libusb_free_config_descriptor(conf);

    return USB_RET_SUCCESS;

}

static void term_completion(void)

{

    int len, i, j, max_width, nb_cols;

    char *cmdline;



    nb_completions = 0;



    cmdline = qemu_malloc(term_cmd_buf_index + 1);

    if (!cmdline)

        return;

    memcpy(cmdline, term_cmd_buf, term_cmd_buf_index);

    cmdline[term_cmd_buf_index] = '\0';

    find_completion(cmdline);

    qemu_free(cmdline);



    /* no completion found */

    if (nb_completions <= 0)

        return;

    if (nb_completions == 1) {

        len = strlen(completions[0]);

        for(i = completion_index; i < len; i++) {

            term_insert_char(completions[0][i]);

        }

        /* extra space for next argument. XXX: make it more generic */

        if (len > 0 && completions[0][len - 1] != '/')

            term_insert_char(' ');

    } else {

        term_printf("\n");

        max_width = 0;

        for(i = 0; i < nb_completions; i++) {

            len = strlen(completions[i]);

            if (len > max_width)

                max_width = len;

        }

        max_width += 2;

        if (max_width < 10)

            max_width = 10;

        else if (max_width > 80)

            max_width = 80;

        nb_cols = 80 / max_width;

        j = 0;

        for(i = 0; i < nb_completions; i++) {

            term_printf("%-*s", max_width, completions[i]);

            if (++j == nb_cols || i == (nb_completions - 1)) {

                term_printf("\n");

                j = 0;

            }

        }

        term_show_prompt2();

    }

}

static int parse_vdiname(BDRVSheepdogState *s, const char *filename,

                         char *vdi, uint32_t *snapid, char *tag)

{

    char *p, *q, *uri;

    const char *host_spec, *vdi_spec;

    int nr_sep, ret;



    strstart(filename, "sheepdog:", &filename);

    p = q = g_strdup(filename);



    /* count the number of separators */

    nr_sep = 0;

    while (*p) {

        if (*p == ':') {

            nr_sep++;

        }

        p++;

    }

    p = q;



    /* use the first two tokens as host_spec. */

    if (nr_sep >= 2) {

        host_spec = p;

        p = strchr(p, ':');

        p++;

        p = strchr(p, ':');

        *p++ = '\0';

    } else {

        host_spec = "";

    }



    vdi_spec = p;



    p = strchr(vdi_spec, ':');

    if (p) {

        *p++ = '#';

    }



    uri = g_strdup_printf("sheepdog://%s/%s", host_spec, vdi_spec);



    ret = sd_parse_uri(s, uri, vdi, snapid, tag);



    g_free(q);

    g_free(uri);



    return ret;

}

static int decode_i2_frame(FourXContext *f, const uint8_t *buf, int length){

    int x, y, x2, y2;

    const int width= f->avctx->width;

    const int height= f->avctx->height;

    uint16_t *dst= (uint16_t*)f->current_picture.data[0];

    const int stride= f->current_picture.linesize[0]>>1;



    for(y=0; y<height; y+=16){

        for(x=0; x<width; x+=16){

            unsigned int color[4], bits;

            memset(color, 0, sizeof(color));

//warning following is purely guessed ...

            color[0]= bytestream_get_le16(&buf);

            color[1]= bytestream_get_le16(&buf);



            if(color[0]&0x8000) av_log(NULL, AV_LOG_ERROR, "unk bit 1\n");

            if(color[1]&0x8000) av_log(NULL, AV_LOG_ERROR, "unk bit 2\n");



            color[2]= mix(color[0], color[1]);

            color[3]= mix(color[1], color[0]);



            bits= bytestream_get_le32(&buf);

            for(y2=0; y2<16; y2++){

                for(x2=0; x2<16; x2++){

                    int index= 2*(x2>>2) + 8*(y2>>2);

                    dst[y2*stride+x2]= color[(bits>>index)&3];

                }

            }

            dst+=16;

        }

        dst += 16 * stride - x;

    }



    return 0;

}

static int apc_read_header(AVFormatContext *s)

{

    AVIOContext *pb = s->pb;

    AVStream *st;



    avio_rl32(pb); /* CRYO */

    avio_rl32(pb); /* _APC */

    avio_rl32(pb); /* 1.20 */



    st = avformat_new_stream(s, NULL);

    if (!st)

        return AVERROR(ENOMEM);



    st->codecpar->codec_type = AVMEDIA_TYPE_AUDIO;

    st->codecpar->codec_id = AV_CODEC_ID_ADPCM_IMA_APC;



    avio_rl32(pb); /* number of samples */

    st->codecpar->sample_rate = avio_rl32(pb);



    /* initial predictor values for adpcm decoder */

    if (ff_get_extradata(s, st->codecpar, pb, 2 * 4) < 0)

        return AVERROR(ENOMEM);



    if (avio_rl32(pb)) {

        st->codecpar->channels       = 2;

        st->codecpar->channel_layout = AV_CH_LAYOUT_STEREO;

    } else {

        st->codecpar->channels       = 1;

        st->codecpar->channel_layout = AV_CH_LAYOUT_MONO;

    }



    st->codecpar->bits_per_coded_sample = 4;

    st->codecpar->bit_rate = st->codecpar->bits_per_coded_sample * st->codecpar->channels

                          * st->codecpar->sample_rate;

    st->codecpar->block_align = 1;



    return 0;

}

