static void gpio_write(void *opaque, target_phys_addr_t addr, uint64_t value,

                       unsigned size)

{

    struct gpio_state_t *s = opaque;

    D(printf("%s %x=%x\n", __func__, addr, (unsigned)value));



    addr >>= 2;

    switch (addr)

    {

        case RW_PA_DOUT:

            /* Decode nand pins.  */

            s->nand->ale = !!(value & (1 << 6));

            s->nand->cle = !!(value & (1 << 5));

            s->nand->ce  = !!(value & (1 << 4));



            s->regs[addr] = value;

            break;



        case RW_PD_DOUT:

            /* Temp sensor clk.  */

            if ((s->regs[addr] ^ value) & 2)

                tempsensor_clkedge(&s->tempsensor, !!(value & 2),

                                   !!(value & 16));

            s->regs[addr] = value;

            break;



        default:

            s->regs[addr] = value;

            break;

    }

}

static ssize_t eth_rx(NetClientState *nc, const uint8_t *buf, size_t size)

{

    XilinxAXIEnet *s = qemu_get_nic_opaque(nc);

    static const unsigned char sa_bcast[6] = {0xff, 0xff, 0xff,

                                              0xff, 0xff, 0xff};

    static const unsigned char sa_ipmcast[3] = {0x01, 0x00, 0x52};

    uint32_t app[6] = {0};

    int promisc = s->fmi & (1 << 31);

    int unicast, broadcast, multicast, ip_multicast = 0;

    uint32_t csum32;

    uint16_t csum16;

    int i;



    DENET(qemu_log("%s: %zd bytes\n", __func__, size));



    unicast = ~buf[0] & 0x1;

    broadcast = memcmp(buf, sa_bcast, 6) == 0;

    multicast = !unicast && !broadcast;

    if (multicast && (memcmp(sa_ipmcast, buf, sizeof sa_ipmcast) == 0)) {

        ip_multicast = 1;

    }



    /* Jumbo or vlan sizes ?  */

    if (!(s->rcw[1] & RCW1_JUM)) {

        if (size > 1518 && size <= 1522 && !(s->rcw[1] & RCW1_VLAN)) {

            return size;

        }

    }



    /* Basic Address filters.  If you want to use the extended filters

       you'll generally have to place the ethernet mac into promiscuous mode

       to avoid the basic filtering from dropping most frames.  */

    if (!promisc) {

        if (unicast) {

            if (!enet_match_addr(buf, s->uaw[0], s->uaw[1])) {

                return size;

            }

        } else {

            if (broadcast) {

                /* Broadcast.  */

                if (s->regs[R_RAF] & RAF_BCAST_REJ) {

                    return size;

                }

            } else {

                int drop = 1;



                /* Multicast.  */

                if (s->regs[R_RAF] & RAF_MCAST_REJ) {

                    return size;

                }



                for (i = 0; i < 4; i++) {

                    if (enet_match_addr(buf, s->maddr[i][0], s->maddr[i][1])) {

                        drop = 0;

                        break;

                    }

                }



                if (drop) {

                    return size;

                }

            }

        }

    }



    /* Extended mcast filtering enabled?  */

    if (axienet_newfunc_enabled(s) && axienet_extmcf_enabled(s)) {

        if (unicast) {

            if (!enet_match_addr(buf, s->ext_uaw[0], s->ext_uaw[1])) {

                return size;

            }

        } else {

            if (broadcast) {

                /* Broadcast. ???  */

                if (s->regs[R_RAF] & RAF_BCAST_REJ) {

                    return size;

                }

            } else {

                int idx, bit;



                /* Multicast.  */

                if (!memcmp(buf, sa_ipmcast, 3)) {

                    return size;

                }



                idx  = (buf[4] & 0x7f) << 8;

                idx |= buf[5];



                bit = 1 << (idx & 0x1f);

                idx >>= 5;



                if (!(s->ext_mtable[idx] & bit)) {

                    return size;

                }

            }

        }

    }



    if (size < 12) {

        s->regs[R_IS] |= IS_RX_REJECT;

        enet_update_irq(s);

        return -1;

    }



    if (size > (s->c_rxmem - 4)) {

        size = s->c_rxmem - 4;

    }



    memcpy(s->rxmem, buf, size);

    memset(s->rxmem + size, 0, 4); /* Clear the FCS.  */



    if (s->rcw[1] & RCW1_FCS) {

        size += 4; /* fcs is inband.  */

    }



    app[0] = 5 << 28;

    csum32 = net_checksum_add(size - 14, (uint8_t *)s->rxmem + 14);

    /* Fold it once.  */

    csum32 = (csum32 & 0xffff) + (csum32 >> 16);

    /* And twice to get rid of possible carries.  */

    csum16 = (csum32 & 0xffff) + (csum32 >> 16);

    app[3] = csum16;

    app[4] = size & 0xffff;



    s->stats.rx_bytes += size;

    s->stats.rx++;

    if (multicast) {

        s->stats.rx_mcast++;

        app[2] |= 1 | (ip_multicast << 1);

    } else if (broadcast) {

        s->stats.rx_bcast++;

        app[2] |= 1 << 3;

    }



    /* Good frame.  */

    app[2] |= 1 << 6;



    s->rxsize = size;

    s->rxpos = 0;

    s->rxapp = g_memdup(app, sizeof(app));

    axienet_eth_rx_notify(s);



    enet_update_irq(s);

    return size;

}

static int get_physical_address_code(CPUState *env,

                                     target_phys_addr_t *physical, int *prot,

                                     target_ulong address, int mmu_idx)

{

    unsigned int i;

    uint64_t context;



    int is_user = (mmu_idx == MMU_USER_IDX ||

                   mmu_idx == MMU_USER_SECONDARY_IDX);



    if ((env->lsu & IMMU_E) == 0 || (env->pstate & PS_RED) != 0) {

        /* IMMU disabled */

        *physical = ultrasparc_truncate_physical(address);

        *prot = PAGE_EXEC;

        return 0;

    }



    if (env->tl == 0) {

        /* PRIMARY context */

        context = env->dmmu.mmu_primary_context & 0x1fff;

    } else {

        /* NUCLEUS context */

        context = 0;

    }



    for (i = 0; i < 64; i++) {

        // ctx match, vaddr match, valid?

        if (ultrasparc_tag_match(&env->itlb[i],

                                 address, context, physical)) {

            // access ok?

            if ((env->itlb[i].tte & 0x4) && is_user) {

                if (env->immu.sfsr) /* Fault status register */

                    env->immu.sfsr = 2; /* overflow (not read before

                                             another fault) */

                env->immu.sfsr |= (is_user << 3) | 1;

                env->exception_index = TT_TFAULT;

#ifdef DEBUG_MMU

                printf("TFAULT at 0x%" PRIx64 "\n", address);

#endif

                return 1;

            }

            *prot = PAGE_EXEC;

            TTE_SET_USED(env->itlb[i].tte);

            return 0;

        }

    }

#ifdef DEBUG_MMU

    printf("TMISS at 0x%" PRIx64 "\n", address);

#endif

    /* Context is stored in DMMU (dmmuregs[1]) also for IMMU */

    env->immu.tag_access = (address & ~0x1fffULL) | context;

    env->exception_index = TT_TMISS;

    return 1;

}

static inline void RENAME(yuv2packedX)(SwsContext *c, int16_t *lumFilter, int16_t **lumSrc, int lumFilterSize,

				    int16_t *chrFilter, int16_t **chrSrc, int chrFilterSize,

			    uint8_t *dest, long dstW, long dstY)

{

	long dummy=0;

	switch(c->dstFormat)

	{

#ifdef HAVE_MMX

	case IMGFMT_BGR32:

		{

			asm volatile(

				YSCALEYUV2RGBX

				WRITEBGR32(%4, %5, %%REGa)



			:: "r" (&c->redDither), 

			   "m" (dummy), "m" (dummy), "m" (dummy),

			   "r" (dest), "m" (dstW)

			: "%"REG_a, "%"REG_d, "%"REG_S

			);

		}

		break;

	case IMGFMT_BGR24:

		{

			asm volatile(

				YSCALEYUV2RGBX

				"lea (%%"REG_a", %%"REG_a", 2), %%"REG_b"\n\t" //FIXME optimize

				"add %4, %%"REG_b"			\n\t"

				WRITEBGR24(%%REGb, %5, %%REGa)



			:: "r" (&c->redDither), 

			   "m" (dummy), "m" (dummy), "m" (dummy),

			   "r" (dest), "m" (dstW)

			: "%"REG_a, "%"REG_b, "%"REG_d, "%"REG_S //FIXME ebx

			);

		}

		break;

	case IMGFMT_BGR15:

		{

			asm volatile(

				YSCALEYUV2RGBX

		/* mm2=B, %%mm4=G, %%mm5=R, %%mm7=0 */

#ifdef DITHER1XBPP

				"paddusb "MANGLE(b5Dither)", %%mm2\n\t"

				"paddusb "MANGLE(g5Dither)", %%mm4\n\t"

				"paddusb "MANGLE(r5Dither)", %%mm5\n\t"

#endif



				WRITEBGR15(%4, %5, %%REGa)



			:: "r" (&c->redDither), 

			   "m" (dummy), "m" (dummy), "m" (dummy),

			   "r" (dest), "m" (dstW)

			: "%"REG_a, "%"REG_d, "%"REG_S

			);

		}

		break;

	case IMGFMT_BGR16:

		{

			asm volatile(

				YSCALEYUV2RGBX

		/* mm2=B, %%mm4=G, %%mm5=R, %%mm7=0 */

#ifdef DITHER1XBPP

				"paddusb "MANGLE(b5Dither)", %%mm2\n\t"

				"paddusb "MANGLE(g6Dither)", %%mm4\n\t"

				"paddusb "MANGLE(r5Dither)", %%mm5\n\t"

#endif



				WRITEBGR16(%4, %5, %%REGa)



			:: "r" (&c->redDither), 

			   "m" (dummy), "m" (dummy), "m" (dummy),

			   "r" (dest), "m" (dstW)

			: "%"REG_a, "%"REG_d, "%"REG_S

			);

		}

		break;

	case IMGFMT_YUY2:

		{

			asm volatile(

				YSCALEYUV2PACKEDX

		/* mm2=B, %%mm4=G, %%mm5=R, %%mm7=0 */



				"psraw $3, %%mm3		\n\t"

				"psraw $3, %%mm4		\n\t"

				"psraw $3, %%mm1		\n\t"

				"psraw $3, %%mm7		\n\t"

				WRITEYUY2(%4, %5, %%REGa)



			:: "r" (&c->redDither), 

			   "m" (dummy), "m" (dummy), "m" (dummy),

			   "r" (dest), "m" (dstW)

			: "%"REG_a, "%"REG_d, "%"REG_S

			);

		}

		break;

#endif

	default:

#ifdef HAVE_ALTIVEC

		/* The following list of supported dstFormat values should

		   match what's found in the body of altivec_yuv2packedX() */

		if(c->dstFormat==IMGFMT_ABGR  || c->dstFormat==IMGFMT_BGRA  ||

		   c->dstFormat==IMGFMT_BGR24 || c->dstFormat==IMGFMT_RGB24 ||

		   c->dstFormat==IMGFMT_RGBA  || c->dstFormat==IMGFMT_ARGB)

			altivec_yuv2packedX (c, lumFilter, lumSrc, lumFilterSize,

				    chrFilter, chrSrc, chrFilterSize,

				    dest, dstW, dstY);

		else

#endif

			yuv2packedXinC(c, lumFilter, lumSrc, lumFilterSize,

				    chrFilter, chrSrc, chrFilterSize,

				    dest, dstW, dstY);

		break;

	}

}

int avfilter_parse_graph(AVFilterGraph *graph, const char *filters,

                         AVFilterInOut *openLinks, AVClass *log_ctx)

{

    int index = 0;

    char chr = 0;

    int pad = 0;



    AVFilterInOut *currInputs = NULL;



    do {

        AVFilterContext *filter;

        filters += consume_whitespace(filters);



        pad = parse_inputs(&filters, &currInputs, &openLinks, log_ctx);



        if(pad < 0)

            goto fail;



        if(!(filter = parse_filter(&filters, graph, index, log_ctx)))

            goto fail;



        if(filter->input_count == 1 && !currInputs && !index) {

            // First input can be ommitted if it is "[in]"

            const char *tmp = "[in]";

            pad = parse_inputs(&tmp, &currInputs, &openLinks, log_ctx);

            if(pad < 0)

                goto fail;

        }



        if(link_filter_inouts(filter, &currInputs, &openLinks, log_ctx) < 0)

            goto fail;



        pad = parse_outputs(&filters, &currInputs, &openLinks, log_ctx);



        if(pad < 0)

            goto fail;



        filters += consume_whitespace(filters);

        chr = *filters++;



        if(chr == ';' && currInputs) {

            av_log(log_ctx, AV_LOG_ERROR,

                   "Could not find a output to link when parsing \"%s\"\n",

                   filters - 1);

            goto fail;

        }

        index++;

    } while(chr == ',' || chr == ';');



    if(openLinks && !strcmp(openLinks->name, "out") && currInputs) {

        // Last output can be ommitted if it is "[out]"

        const char *tmp = "[out]";

        if(parse_outputs(&tmp, &currInputs, &openLinks, log_ctx) < 0)

            goto fail;

    }



    return 0;



 fail:

    avfilter_destroy_graph(graph);

    free_inout(openLinks);

    free_inout(currInputs);

    return -1;

}

static av_cold int qtrle_encode_init(AVCodecContext *avctx)

{

    QtrleEncContext *s = avctx->priv_data;



    if (av_image_check_size(avctx->width, avctx->height, 0, avctx) < 0) {

        return -1;

    }

    s->avctx=avctx;



    switch (avctx->pix_fmt) {

    case AV_PIX_FMT_RGB555BE:

        s->pixel_size = 2;

        break;

    case AV_PIX_FMT_RGB24:

        s->pixel_size = 3;

        break;

    case AV_PIX_FMT_ARGB:

        s->pixel_size = 4;

        break;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unsupported colorspace.\n");

        break;

    }

    avctx->bits_per_coded_sample = s->pixel_size*8;



    s->rlecode_table = av_mallocz(s->avctx->width);

    s->skip_table    = av_mallocz(s->avctx->width);

    s->length_table  = av_mallocz((s->avctx->width + 1)*sizeof(int));

    if (!s->skip_table || !s->length_table || !s->rlecode_table) {

        av_log(avctx, AV_LOG_ERROR, "Error allocating memory.\n");

        return -1;

    }

    if (avpicture_alloc(&s->previous_frame, avctx->pix_fmt, avctx->width, avctx->height) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error allocating picture\n");

        return -1;

    }



    s->max_buf_size = s->avctx->width*s->avctx->height*s->pixel_size*2 /* image base material */

                      + 15                                           /* header + footer */

                      + s->avctx->height*2                           /* skip code+rle end */

                      + s->avctx->width/MAX_RLE_BULK + 1             /* rle codes */;



    avctx->coded_frame = av_frame_alloc();

    if (!avctx->coded_frame) {

        qtrle_encode_end(avctx);

        return AVERROR(ENOMEM);

    }



    return 0;

}

static inline void check_for_slice(AVSContext *h) {

    GetBitContext *gb = &h->s.gb;

    int align;



    if(h->mbx)

        return;

    align = (-get_bits_count(gb)) & 7;

    if((show_bits_long(gb,24+align) & 0xFFFFFF) == 0x000001) {

        skip_bits_long(gb,24+align);

        h->stc = get_bits(gb,8);

        decode_slice_header(h,gb);

    }

}

