static int sls_flags_filename_process(struct AVFormatContext *s, HLSContext *hls,

                                      VariantStream *vs, HLSSegment *en,

                                      double duration, int64_t pos, int64_t size)

{

    if ((hls->flags & (HLS_SECOND_LEVEL_SEGMENT_SIZE | HLS_SECOND_LEVEL_SEGMENT_DURATION)) &&

        strlen(vs->current_segment_final_filename_fmt)) {

        av_strlcpy(vs->avf->filename, vs->current_segment_final_filename_fmt, sizeof(vs->avf->filename));

        if (hls->flags & HLS_SECOND_LEVEL_SEGMENT_SIZE) {

            char * filename = av_strdup(vs->avf->filename);  // %%s will be %s after strftime

            if (!filename) {

                av_free(en);

                return AVERROR(ENOMEM);

            }

            if (replace_int_data_in_filename(vs->avf->filename, sizeof(vs->avf->filename),

                filename, 's', pos + size) < 1) {

                av_log(hls, AV_LOG_ERROR,

                       "Invalid second level segment filename template '%s', "

                        "you can try to remove second_level_segment_size flag\n",

                       filename);

                av_free(filename);

                av_free(en);

                return AVERROR(EINVAL);

            }

            av_free(filename);

        }

        if (hls->flags & HLS_SECOND_LEVEL_SEGMENT_DURATION) {

            char * filename = av_strdup(vs->avf->filename);  // %%t will be %t after strftime

            if (!filename) {

                av_free(en);

                return AVERROR(ENOMEM);

            }

            if (replace_int_data_in_filename(vs->avf->filename, sizeof(vs->avf->filename),

                filename, 't',  (int64_t)round(duration * HLS_MICROSECOND_UNIT)) < 1) {

                av_log(hls, AV_LOG_ERROR,

                       "Invalid second level segment filename template '%s', "

                        "you can try to remove second_level_segment_time flag\n",

                       filename);

                av_free(filename);

                av_free(en);

                return AVERROR(EINVAL);

            }

            av_free(filename);

        }

    }

    return 0;

}

static void spapr_core_pre_plug(HotplugHandler *hotplug_dev, DeviceState *dev,

                                Error **errp)

{

    MachineState *machine = MACHINE(OBJECT(hotplug_dev));

    MachineClass *mc = MACHINE_GET_CLASS(hotplug_dev);

    Error *local_err = NULL;

    CPUCore *cc = CPU_CORE(dev);

    sPAPRCPUCore *sc = SPAPR_CPU_CORE(dev);

    char *base_core_type = spapr_get_cpu_core_type(machine->cpu_model);

    const char *type = object_get_typename(OBJECT(dev));

    CPUArchId *core_slot;

    int node_id;

    int index;



    if (dev->hotplugged && !mc->has_hotpluggable_cpus) {

        error_setg(&local_err, "CPU hotplug not supported for this machine");

        goto out;

    }



    if (strcmp(base_core_type, type)) {

        error_setg(&local_err, "CPU core type should be %s", base_core_type);

        goto out;

    }



    if (cc->core_id % smp_threads) {

        error_setg(&local_err, "invalid core id %d", cc->core_id);

        goto out;

    }



    if (cc->nr_threads != smp_threads) {

        error_setg(errp, "invalid nr-threads %d, must be %d",

                   cc->nr_threads, smp_threads);

        return;

    }



    core_slot = spapr_find_cpu_slot(MACHINE(hotplug_dev), cc->core_id, &index);

    if (!core_slot) {

        error_setg(&local_err, "core id %d out of range", cc->core_id);

        goto out;

    }



    if (core_slot->cpu) {

        error_setg(&local_err, "core %d already populated", cc->core_id);

        goto out;

    }



    node_id = numa_get_node_for_cpu(cc->core_id);

    if (node_id == nb_numa_nodes) {

        /* by default CPUState::numa_node was 0 if it's not set via CLI

         * keep it this way for now but in future we probably should

         * refuse to start up with incomplete numa mapping */

        node_id = 0;

    }

    if (sc->node_id == CPU_UNSET_NUMA_NODE_ID) {

        sc->node_id = node_id;

    } else if (sc->node_id != node_id) {

        error_setg(&local_err, "node-id %d must match numa node specified"

            "with -numa option for cpu-index %d", sc->node_id, cc->core_id);

        goto out;

    }



out:

    g_free(base_core_type);

    error_propagate(errp, local_err);

}

void sparc_iommu_memory_rw(void *opaque, target_phys_addr_t addr,

                           uint8_t *buf, int len, int is_write)

{

    int l;

    uint32_t flags;

    target_phys_addr_t page, phys_addr;



    while (len > 0) {

        page = addr & TARGET_PAGE_MASK;

        l = (page + TARGET_PAGE_SIZE) - addr;

        if (l > len)

            l = len;

        flags = iommu_page_get_flags(opaque, page);

        if (!(flags & IOPTE_VALID))

            return;

        phys_addr = iommu_translate_pa(opaque, addr, flags);

        if (is_write) {

            if (!(flags & IOPTE_WRITE))

                return;

            cpu_physical_memory_write(phys_addr, buf, len);

        } else {

            cpu_physical_memory_read(phys_addr, buf, len);

        }

        len -= l;

        buf += l;

        addr += l;

    }

}

