static void do_downmix(AC3DecodeContext *ctx)

{

    int from = ctx->bsi.acmod;

    int to = ctx->output;



    switch (from) {

        case AC3_INPUT_DUALMONO:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    mix_dualmono_to_mono(ctx);

                    break;

                case AC3_OUTPUT_STEREO: /* We Assume that sum of both mono channels is requested */

                    mix_dualmono_to_stereo(ctx);

                    break;

            }

            break;

        case AC3_INPUT_MONO:

            switch (to) {

                case AC3_OUTPUT_STEREO:

                    upmix_mono_to_stereo(ctx);

                    break;

            }

            break;

        case AC3_INPUT_STEREO:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    mix_stereo_to_mono(ctx);

                    break;

            }

            break;

        case AC3_INPUT_3F:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    mix_3f_to_mono(ctx);

                    break;

                case AC3_OUTPUT_STEREO:

                    mix_3f_to_stereo(ctx);

                    break;

            }

            break;

        case AC3_INPUT_2F_1R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    mix_2f_1r_to_mono(ctx);

                    break;

                case AC3_OUTPUT_STEREO:

                    mix_2f_1r_to_stereo(ctx);

                    break;

                case AC3_OUTPUT_DOLBY:

                    mix_2f_1r_to_dolby(ctx);

                    break;

            }

            break;

        case AC3_INPUT_3F_1R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    mix_3f_1r_to_mono(ctx);

                    break;

                case AC3_OUTPUT_STEREO:

                    mix_3f_1r_to_stereo(ctx);

                    break;

                case AC3_OUTPUT_DOLBY:

                    mix_3f_1r_to_dolby(ctx);

                    break;

            }

            break;

        case AC3_INPUT_2F_2R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    mix_2f_2r_to_mono(ctx);

                    break;

                case AC3_OUTPUT_STEREO:

                    mix_2f_2r_to_stereo(ctx);

                    break;

                case AC3_OUTPUT_DOLBY:

                    mix_2f_2r_to_dolby(ctx);

                    break;

            }

            break;

        case AC3_INPUT_3F_2R:

            switch (to) {

                case AC3_OUTPUT_MONO:

                    mix_3f_2r_to_mono(ctx);

                    break;

                case AC3_OUTPUT_STEREO:

                    mix_3f_2r_to_stereo(ctx);

                    break;

                case AC3_OUTPUT_DOLBY:

                    mix_3f_2r_to_dolby(ctx);

                    break;

            }

            break;

    }

}

static int get_avc_nalsize(H264Context *h, const uint8_t *buf,

                           int buf_size, int *buf_index)

{

    int i, nalsize = 0;



    if (*buf_index >= buf_size - h->nal_length_size)

        return -1;



    for (i = 0; i < h->nal_length_size; i++)

        nalsize = (nalsize << 8) | buf[(*buf_index)++];

    if (nalsize <= 0 || nalsize > buf_size - *buf_index) {

        av_log(h->avctx, AV_LOG_ERROR,

               "AVC: nal size %d\n", nalsize);

        return -1;

    }

    return nalsize;

}

static int decode_13(AVCodecContext *avctx, DxaDecContext *c, uint8_t* dst,

                     int stride, uint8_t *src, uint8_t *ref)

{

    uint8_t *code, *data, *mv, *msk, *tmp, *tmp2;

    int i, j, k;

    int type, x, y, d, d2;

    uint32_t mask;



    code = src  + 12;

    data = code + ((avctx->width * avctx->height) >> 4);

    mv   = data + AV_RB32(src + 0);

    msk  = mv   + AV_RB32(src + 4);



    for(j = 0; j < avctx->height; j += 4){

        for(i = 0; i < avctx->width; i += 4){

            tmp  = dst + i;

            tmp2 = ref + i;

            type = *code++;

            switch(type){

            case 4: // motion compensation

                x = (*mv) >> 4;    if(x & 8) x = 8 - x;

                y = (*mv++) & 0xF; if(y & 8) y = 8 - y;

                if (i < -x || avctx->width  - i - 4 < x ||

                    j < -y || avctx->height - j - 4 < y) {

                    av_log(avctx, AV_LOG_ERROR, "MV %d %d out of bounds\n", x,y);

                    return AVERROR_INVALIDDATA;

                }

                tmp2 += x + y*stride;

            case 0: // skip

            case 5: // skip in method 12

                for(y = 0; y < 4; y++){

                    memcpy(tmp, tmp2, 4);

                    tmp  += stride;

                    tmp2 += stride;

                }

                break;

            case 1:  // masked change

            case 10: // masked change with only half of pixels changed

            case 11: // cases 10-15 are for method 12 only

            case 12:

            case 13:

            case 14:

            case 15:

                if(type == 1){

                    mask = AV_RB16(msk);

                    msk += 2;

                }else{

                    type -= 10;

                    mask = ((msk[0] & 0xF0) << shift1[type]) | ((msk[0] & 0xF) << shift2[type]);

                    msk++;

                }

                for(y = 0; y < 4; y++){

                    for(x = 0; x < 4; x++){

                        tmp[x] = (mask & 0x8000) ? *data++ : tmp2[x];

                        mask <<= 1;

                    }

                    tmp  += stride;

                    tmp2 += stride;

                }

                break;

            case 2: // fill block

                for(y = 0; y < 4; y++){

                    memset(tmp, data[0], 4);

                    tmp += stride;

                }

                data++;

                break;

            case 3: // raw block

                for(y = 0; y < 4; y++){

                    memcpy(tmp, data, 4);

                    data += 4;

                    tmp  += stride;

                }

                break;

            case 8: // subblocks - method 13 only

                mask = *msk++;

                for(k = 0; k < 4; k++){

                    d  = ((k & 1) << 1) + ((k & 2) * stride);

                    d2 = ((k & 1) << 1) + ((k & 2) * stride);

                    tmp2 = ref + i + d2;

                    switch(mask & 0xC0){

                    case 0x80: // motion compensation

                        x = (*mv) >> 4;    if(x & 8) x = 8 - x;

                        y = (*mv++) & 0xF; if(y & 8) y = 8 - y;

                        if (i + 2*(k & 1) < -x || avctx->width  - i - 2*(k & 1) - 2 < x ||

                            j +   (k & 2) < -y || avctx->height - j -   (k & 2) - 2 < y) {

                            av_log(avctx, AV_LOG_ERROR, "MV %d %d out of bounds\n", x,y);

                            return AVERROR_INVALIDDATA;

                        }

                        tmp2 += x + y*stride;

                    case 0x00: // skip

                        tmp[d + 0         ] = tmp2[0];

                        tmp[d + 1         ] = tmp2[1];

                        tmp[d + 0 + stride] = tmp2[0 + stride];

                        tmp[d + 1 + stride] = tmp2[1 + stride];

                        break;

                    case 0x40: // fill

                        tmp[d + 0         ] = data[0];

                        tmp[d + 1         ] = data[0];

                        tmp[d + 0 + stride] = data[0];

                        tmp[d + 1 + stride] = data[0];

                        data++;

                        break;

                    case 0xC0: // raw

                        tmp[d + 0         ] = *data++;

                        tmp[d + 1         ] = *data++;

                        tmp[d + 0 + stride] = *data++;

                        tmp[d + 1 + stride] = *data++;

                        break;

                    }

                    mask <<= 2;

                }

                break;

            case 32: // vector quantization - 2 colors

                mask = AV_RB16(msk);

                msk += 2;

                for(y = 0; y < 4; y++){

                    for(x = 0; x < 4; x++){

                        tmp[x] = data[mask & 1];

                        mask >>= 1;

                    }

                    tmp  += stride;

                    tmp2 += stride;

                }

                data += 2;

                break;

            case 33: // vector quantization - 3 or 4 colors

            case 34:

                mask = AV_RB32(msk);

                msk += 4;

                for(y = 0; y < 4; y++){

                    for(x = 0; x < 4; x++){

                        tmp[x] = data[mask & 3];

                        mask >>= 2;

                    }

                    tmp  += stride;

                    tmp2 += stride;

                }

                data += type - 30;

                break;

            default:

                av_log(avctx, AV_LOG_ERROR, "Unknown opcode %d\n", type);

                return AVERROR_INVALIDDATA;

            }

        }

        dst += stride * 4;

        ref += stride * 4;

    }

    return 0;

}

void palette8tobgr32(const uint8_t *src, uint8_t *dst, long num_pixels, const uint8_t *palette)

{

	long i;

	for(i=0; i<num_pixels; i++)

	{

		#ifdef WORDS_BIGENDIAN

			dst[3]= palette[ src[i]*4+0 ];

			dst[2]= palette[ src[i]*4+1 ];

			dst[1]= palette[ src[i]*4+2 ];

		#else

			//FIXME slow?

			dst[0]= palette[ src[i]*4+0 ];

			dst[1]= palette[ src[i]*4+1 ];

			dst[2]= palette[ src[i]*4+2 ];

			//dst[3]= 0; /* do we need this cleansing? */

		#endif



		dst+= 4;

	}

}

