static int load_multiboot(void *fw_cfg,

                          FILE *f,

                          const char *kernel_filename,

                          const char *initrd_filename,

                          const char *kernel_cmdline,

                          uint8_t *header)

{

    int i, t, is_multiboot = 0;

    uint32_t flags = 0;

    uint32_t mh_entry_addr;

    uint32_t mh_load_addr;

    uint32_t mb_kernel_size;

    uint32_t mmap_addr = MULTIBOOT_STRUCT_ADDR;

    uint32_t mb_bootinfo = MULTIBOOT_STRUCT_ADDR + 0x500;

    uint32_t mb_cmdline = mb_bootinfo + 0x200;

    uint32_t mb_mod_end;



    /* Ok, let's see if it is a multiboot image.

       The header is 12x32bit long, so the latest entry may be 8192 - 48. */

    for (i = 0; i < (8192 - 48); i += 4) {

        if (ldl_p(header+i) == 0x1BADB002) {

            uint32_t checksum = ldl_p(header+i+8);

            flags = ldl_p(header+i+4);

            checksum += flags;

            checksum += (uint32_t)0x1BADB002;

            if (!checksum) {

                is_multiboot = 1;

                break;

            }

        }

    }



    if (!is_multiboot)

        return 0; /* no multiboot */



#ifdef DEBUG_MULTIBOOT

    fprintf(stderr, "qemu: I believe we found a multiboot image!\n");

#endif



    if (flags & 0x00000004) { /* MULTIBOOT_HEADER_HAS_VBE */

        fprintf(stderr, "qemu: multiboot knows VBE. we don't.\n");

    }

    if (!(flags & 0x00010000)) { /* MULTIBOOT_HEADER_HAS_ADDR */

        uint64_t elf_entry;

        int kernel_size;

        fclose(f);

        kernel_size = load_elf(kernel_filename, 0, &elf_entry, NULL, NULL,

                               0, ELF_MACHINE, 0);

        if (kernel_size < 0) {

            fprintf(stderr, "Error while loading elf kernel\n");

            exit(1);

        }

        mh_load_addr = mh_entry_addr = elf_entry;

        mb_kernel_size = kernel_size;



#ifdef DEBUG_MULTIBOOT

        fprintf(stderr, "qemu: loading multiboot-elf kernel (%#x bytes) with entry %#zx\n",

                mb_kernel_size, (size_t)mh_entry_addr);

#endif

    } else {

        /* Valid if mh_flags sets MULTIBOOT_HEADER_HAS_ADDR. */

        uint32_t mh_header_addr = ldl_p(header+i+12);

        mh_load_addr = ldl_p(header+i+16);

#ifdef DEBUG_MULTIBOOT

        uint32_t mh_load_end_addr = ldl_p(header+i+20);

        uint32_t mh_bss_end_addr = ldl_p(header+i+24);

#endif

        uint32_t mb_kernel_text_offset = i - (mh_header_addr - mh_load_addr);



        mh_entry_addr = ldl_p(header+i+28);

        mb_kernel_size = get_file_size(f) - mb_kernel_text_offset;



        /* Valid if mh_flags sets MULTIBOOT_HEADER_HAS_VBE.

        uint32_t mh_mode_type = ldl_p(header+i+32);

        uint32_t mh_width = ldl_p(header+i+36);

        uint32_t mh_height = ldl_p(header+i+40);

        uint32_t mh_depth = ldl_p(header+i+44); */



#ifdef DEBUG_MULTIBOOT

        fprintf(stderr, "multiboot: mh_header_addr = %#x\n", mh_header_addr);

        fprintf(stderr, "multiboot: mh_load_addr = %#x\n", mh_load_addr);

        fprintf(stderr, "multiboot: mh_load_end_addr = %#x\n", mh_load_end_addr);

        fprintf(stderr, "multiboot: mh_bss_end_addr = %#x\n", mh_bss_end_addr);

#endif



        fseek(f, mb_kernel_text_offset, SEEK_SET);



#ifdef DEBUG_MULTIBOOT

        fprintf(stderr, "qemu: loading multiboot kernel (%#x bytes) at %#x\n",

                mb_kernel_size, mh_load_addr);

#endif



        if (!fread_targphys_ok(mh_load_addr, mb_kernel_size, f)) {

            fprintf(stderr, "qemu: read error on multiboot kernel '%s' (%#x)\n",

                    kernel_filename, mb_kernel_size);

            exit(1);

        }

        fclose(f);

    }



    /* blob size is only the kernel for now */

    mb_mod_end = mh_load_addr + mb_kernel_size;



    /* load modules */

    stl_phys(mb_bootinfo + 20, 0x0); /* mods_count */

    if (initrd_filename) {

        uint32_t mb_mod_info = mb_bootinfo + 0x100;

        uint32_t mb_mod_cmdline = mb_bootinfo + 0x300;

        uint32_t mb_mod_start = mh_load_addr;

        uint32_t mb_mod_length = mb_kernel_size;

        char *next_initrd;

        char *next_space;

        int mb_mod_count = 0;



        do {

            next_initrd = strchr(initrd_filename, ',');

            if (next_initrd)

                *next_initrd = '\0';

            /* if a space comes after the module filename, treat everything

               after that as parameters */

            cpu_physical_memory_write(mb_mod_cmdline, (uint8_t*)initrd_filename,

                                      strlen(initrd_filename) + 1);

            stl_phys(mb_mod_info + 8, mb_mod_cmdline); /* string */

            mb_mod_cmdline += strlen(initrd_filename) + 1;

            if ((next_space = strchr(initrd_filename, ' ')))

                *next_space = '\0';

#ifdef DEBUG_MULTIBOOT

            printf("multiboot loading module: %s\n", initrd_filename);

#endif

            f = fopen(initrd_filename, "rb");

            if (f) {

                mb_mod_start = (mb_mod_start + mb_mod_length + (TARGET_PAGE_SIZE - 1))

                             & (TARGET_PAGE_MASK);

                mb_mod_length = get_file_size(f);

                mb_mod_end = mb_mod_start + mb_mod_length;



                if (!fread_targphys_ok(mb_mod_start, mb_mod_length, f)) {

                    fprintf(stderr, "qemu: read error on multiboot module '%s' (%#x)\n",

                            initrd_filename, mb_mod_length);

                    exit(1);

                }



                mb_mod_count++;

                stl_phys(mb_mod_info + 0, mb_mod_start);

                stl_phys(mb_mod_info + 4, mb_mod_start + mb_mod_length);

#ifdef DEBUG_MULTIBOOT

                printf("mod_start: %#x\nmod_end:   %#x\n", mb_mod_start,

                       mb_mod_start + mb_mod_length);

#endif

                stl_phys(mb_mod_info + 12, 0x0); /* reserved */

            }

            initrd_filename = next_initrd+1;

            mb_mod_info += 16;

        } while (next_initrd);

        stl_phys(mb_bootinfo + 20, mb_mod_count); /* mods_count */

        stl_phys(mb_bootinfo + 24, mb_bootinfo + 0x100); /* mods_addr */

    }



    /* Make sure we're getting kernel + modules back after reset */

    option_rom_setup_reset(mh_load_addr, mb_mod_end - mh_load_addr);



    /* Commandline support */

    stl_phys(mb_bootinfo + 16, mb_cmdline);

    t = strlen(kernel_filename);

    cpu_physical_memory_write(mb_cmdline, (uint8_t*)kernel_filename, t);

    mb_cmdline += t;

    stb_phys(mb_cmdline++, ' ');

    t = strlen(kernel_cmdline) + 1;

    cpu_physical_memory_write(mb_cmdline, (uint8_t*)kernel_cmdline, t);



    /* the kernel is where we want it to be now */



#define MULTIBOOT_FLAGS_MEMORY (1 << 0)

#define MULTIBOOT_FLAGS_BOOT_DEVICE (1 << 1)

#define MULTIBOOT_FLAGS_CMDLINE (1 << 2)

#define MULTIBOOT_FLAGS_MODULES (1 << 3)

#define MULTIBOOT_FLAGS_MMAP (1 << 6)

    stl_phys(mb_bootinfo, MULTIBOOT_FLAGS_MEMORY

                        | MULTIBOOT_FLAGS_BOOT_DEVICE

                        | MULTIBOOT_FLAGS_CMDLINE

                        | MULTIBOOT_FLAGS_MODULES

                        | MULTIBOOT_FLAGS_MMAP);

    stl_phys(mb_bootinfo + 4, 640); /* mem_lower */

    stl_phys(mb_bootinfo + 8, ram_size / 1024); /* mem_upper */

    stl_phys(mb_bootinfo + 12, 0x8001ffff); /* XXX: use the -boot switch? */

    stl_phys(mb_bootinfo + 48, mmap_addr); /* mmap_addr */



#ifdef DEBUG_MULTIBOOT

    fprintf(stderr, "multiboot: mh_entry_addr = %#x\n", mh_entry_addr);

#endif



    /* Pass variables to option rom */

    fw_cfg_add_i32(fw_cfg, FW_CFG_KERNEL_ADDR, mh_entry_addr);

    fw_cfg_add_i32(fw_cfg, FW_CFG_INITRD_ADDR, mb_bootinfo);

    fw_cfg_add_i32(fw_cfg, FW_CFG_INITRD_SIZE, mmap_addr);



    /* Make sure we're getting the config space back after reset */

    option_rom_setup_reset(mb_bootinfo, 0x500);



    option_rom[nb_option_roms] = "multiboot.bin";

    nb_option_roms++;



    return 1; /* yes, we are multiboot */

}

iscsi_aio_writev(BlockDriverState *bs, int64_t sector_num,

                 QEMUIOVector *qiov, int nb_sectors,

                 BlockDriverCompletionFunc *cb,

                 void *opaque)

{

    IscsiLun *iscsilun = bs->opaque;

    struct iscsi_context *iscsi = iscsilun->iscsi;

    IscsiAIOCB *acb;

    size_t size;

    uint32_t num_sectors;

    uint64_t lba;

    struct iscsi_data data;



    acb = qemu_aio_get(&iscsi_aiocb_info, bs, cb, opaque);

    trace_iscsi_aio_writev(iscsi, sector_num, nb_sectors, opaque, acb);



    acb->iscsilun = iscsilun;

    acb->qiov     = qiov;



    acb->canceled   = 0;

    acb->bh         = NULL;

    acb->status     = -EINPROGRESS;



    /* XXX we should pass the iovec to write16 to avoid the extra copy */

    /* this will allow us to get rid of 'buf' completely */

    size = nb_sectors * BDRV_SECTOR_SIZE;

    data.size = MIN(size, acb->qiov->size);



    /* if the iovec only contains one buffer we can pass it directly */

    if (acb->qiov->niov == 1) {

        acb->buf = NULL;

        data.data = acb->qiov->iov[0].iov_base;

    } else {

        acb->buf = g_malloc(data.size);

        qemu_iovec_to_buf(acb->qiov, 0, acb->buf, data.size);

        data.data = acb->buf;

    }



    acb->task = malloc(sizeof(struct scsi_task));

    if (acb->task == NULL) {

        error_report("iSCSI: Failed to allocate task for scsi WRITE16 "

                     "command. %s", iscsi_get_error(iscsi));

        qemu_aio_release(acb);

        return NULL;

    }

    memset(acb->task, 0, sizeof(struct scsi_task));



    acb->task->xfer_dir = SCSI_XFER_WRITE;

    acb->task->cdb_size = 16;

    acb->task->cdb[0] = 0x8a;

    lba = sector_qemu2lun(sector_num, iscsilun);

    *(uint32_t *)&acb->task->cdb[2]  = htonl(lba >> 32);

    *(uint32_t *)&acb->task->cdb[6]  = htonl(lba & 0xffffffff);

    num_sectors = size / iscsilun->block_size;

    *(uint32_t *)&acb->task->cdb[10] = htonl(num_sectors);

    acb->task->expxferlen = size;



    if (iscsi_scsi_command_async(iscsi, iscsilun->lun, acb->task,

                                 iscsi_aio_write16_cb,

                                 &data,

                                 acb) != 0) {

        scsi_free_scsi_task(acb->task);

        g_free(acb->buf);

        qemu_aio_release(acb);

        return NULL;

    }



    iscsi_set_events(iscsilun);



    return &acb->common;

}

static void build_file_streams(void)

{

    FFServerStream *stream, *stream_next;

    int i, ret;



    /* gather all streams */

    for(stream = config.first_stream; stream; stream = stream_next) {

        AVFormatContext *infile = NULL;

        stream_next = stream->next;

        if (stream->stream_type == STREAM_TYPE_LIVE &&

            !stream->feed) {

            /* the stream comes from a file */

            /* try to open the file */

            /* open stream */

            if (stream->fmt && !strcmp(stream->fmt->name, "rtp")) {

                /* specific case : if transport stream output to RTP,

                   we use a raw transport stream reader */

                av_dict_set(&stream->in_opts, "mpeg2ts_compute_pcr", "1", 0);

            }



            if (!stream->feed_filename[0]) {

                http_log("Unspecified feed file for stream '%s'\n",

                         stream->filename);

                goto fail;

            }



            http_log("Opening feed file '%s' for stream '%s'\n",

                     stream->feed_filename, stream->filename);

            if ((ret = avformat_open_input(&infile, stream->feed_filename, stream->ifmt, &stream->in_opts)) < 0) {

                http_log("Could not open '%s': %s\n", stream->feed_filename,

                         av_err2str(ret));

                /* remove stream (no need to spend more time on it) */

            fail:

                remove_stream(stream);

            } else {

                /* find all the AVStreams inside and reference them in

                   'stream' */

                if (avformat_find_stream_info(infile, NULL) < 0) {

                    http_log("Could not find codec parameters from '%s'\n",

                             stream->feed_filename);

                    avformat_close_input(&infile);

                    goto fail;

                }

                extract_mpeg4_header(infile);



                for(i=0;i<infile->nb_streams;i++)

                    add_av_stream1(stream, infile->streams[i]->codec, 1);



                avformat_close_input(&infile);

            }

        }

    }

}

int av_interleaved_write_frame(AVFormatContext *s, AVPacket *pkt)
{
    int ret, flush = 0;
    if (pkt) {
        AVStream *st = s->streams[pkt->stream_index];
        //FIXME/XXX/HACK drop zero sized packets
        if (st->codec->codec_type == AVMEDIA_TYPE_AUDIO && pkt->size == 0)
            return 0;
        av_dlog(s, "av_interleaved_write_frame size:%d dts:%" PRId64 " pts:%" PRId64 "\n",
                pkt->size, pkt->dts, pkt->pts);
        if ((ret = compute_pkt_fields2(s, st, pkt)) < 0 && !(s->oformat->flags & AVFMT_NOTIMESTAMPS))
        if (pkt->dts == AV_NOPTS_VALUE && !(s->oformat->flags & AVFMT_NOTIMESTAMPS))
            return AVERROR(EINVAL);
    } else {
        av_dlog(s, "av_interleaved_write_frame FLUSH\n");
        flush = 1;
    }
    for (;; ) {
        AVPacket opkt;
        int ret = interleave_packet(s, &opkt, pkt, flush);
        if (ret <= 0) //FIXME cleanup needed for ret<0 ?
        ret = write_packet(s, &opkt);
        if (ret >= 0)
            s->streams[opkt.stream_index]->nb_frames++;
        av_free_packet(&opkt);
        pkt = NULL;
    }
}

static void unref_buffer(InputStream *ist, FrameBuffer *buf)

{

    av_assert0(buf->refcount);

    buf->refcount--;

    if (!buf->refcount) {

        buf->next = ist->buffer_pool;

        ist->buffer_pool = buf;

    }

}

static void loop_filter(const H264Context *h, H264SliceContext *sl, int start_x, int end_x)

{

    uint8_t *dest_y, *dest_cb, *dest_cr;

    int linesize, uvlinesize, mb_x, mb_y;

    const int end_mb_y       = sl->mb_y + FRAME_MBAFF(h);

    const int old_slice_type = sl->slice_type;

    const int pixel_shift    = h->pixel_shift;

    const int block_h        = 16 >> h->chroma_y_shift;



    if (h->postpone_filter)

        return;



    if (sl->deblocking_filter) {

        for (mb_x = start_x; mb_x < end_x; mb_x++)

            for (mb_y = end_mb_y - FRAME_MBAFF(h); mb_y <= end_mb_y; mb_y++) {

                int mb_xy, mb_type;

                mb_xy         = sl->mb_xy = mb_x + mb_y * h->mb_stride;

                sl->slice_num = h->slice_table[mb_xy];

                mb_type       = h->cur_pic.mb_type[mb_xy];

                sl->list_count = h->list_counts[mb_xy];



                if (FRAME_MBAFF(h))

                    sl->mb_mbaff               =

                    sl->mb_field_decoding_flag = !!IS_INTERLACED(mb_type);



                sl->mb_x = mb_x;

                sl->mb_y = mb_y;

                dest_y  = h->cur_pic.f->data[0] +

                          ((mb_x << pixel_shift) + mb_y * sl->linesize) * 16;

                dest_cb = h->cur_pic.f->data[1] +

                          (mb_x << pixel_shift) * (8 << CHROMA444(h)) +

                          mb_y * sl->uvlinesize * block_h;

                dest_cr = h->cur_pic.f->data[2] +

                          (mb_x << pixel_shift) * (8 << CHROMA444(h)) +

                          mb_y * sl->uvlinesize * block_h;

                // FIXME simplify above



                if (MB_FIELD(sl)) {

                    linesize   = sl->mb_linesize   = sl->linesize   * 2;

                    uvlinesize = sl->mb_uvlinesize = sl->uvlinesize * 2;

                    if (mb_y & 1) { // FIXME move out of this function?

                        dest_y  -= sl->linesize   * 15;

                        dest_cb -= sl->uvlinesize * (block_h - 1);

                        dest_cr -= sl->uvlinesize * (block_h - 1);

                    }

                } else {

                    linesize   = sl->mb_linesize   = sl->linesize;

                    uvlinesize = sl->mb_uvlinesize = sl->uvlinesize;

                }

                backup_mb_border(h, sl, dest_y, dest_cb, dest_cr, linesize,

                                 uvlinesize, 0);

                if (fill_filter_caches(h, sl, mb_type))

                    continue;

                sl->chroma_qp[0] = get_chroma_qp(h, 0, h->cur_pic.qscale_table[mb_xy]);

                sl->chroma_qp[1] = get_chroma_qp(h, 1, h->cur_pic.qscale_table[mb_xy]);



                if (FRAME_MBAFF(h)) {

                    ff_h264_filter_mb(h, sl, mb_x, mb_y, dest_y, dest_cb, dest_cr,

                                      linesize, uvlinesize);

                } else {

                    ff_h264_filter_mb_fast(h, sl, mb_x, mb_y, dest_y, dest_cb,

                                           dest_cr, linesize, uvlinesize);

                }

            }

    }

    sl->slice_type  = old_slice_type;

    sl->mb_x         = end_x;

    sl->mb_y         = end_mb_y - FRAME_MBAFF(h);

    sl->chroma_qp[0] = get_chroma_qp(h, 0, sl->qscale);

    sl->chroma_qp[1] = get_chroma_qp(h, 1, sl->qscale);

}

