static void derive_spatial_merge_candidates(HEVCContext *s, int x0, int y0,

                                            int nPbW, int nPbH,

                                            int log2_cb_size,

                                            int singleMCLFlag, int part_idx,

                                            int merge_idx,

                                            struct MvField mergecandlist[])

{

    HEVCLocalContext *lc   = &s->HEVClc;

    RefPicList *refPicList = s->ref->refPicList;

    MvField *tab_mvf       = s->ref->tab_mvf;



    const int min_pu_width = s->sps->min_pu_width;



    const int cand_bottom_left = lc->na.cand_bottom_left;

    const int cand_left        = lc->na.cand_left;

    const int cand_up_left     = lc->na.cand_up_left;

    const int cand_up          = lc->na.cand_up;

    const int cand_up_right    = lc->na.cand_up_right_sap;



    const int xA1    = x0 - 1;

    const int yA1    = y0 + nPbH - 1;

    const int xA1_pu = xA1 >> s->sps->log2_min_pu_size;

    const int yA1_pu = yA1 >> s->sps->log2_min_pu_size;



    const int xB1    = x0 + nPbW - 1;

    const int yB1    = y0 - 1;

    const int xB1_pu = xB1 >> s->sps->log2_min_pu_size;

    const int yB1_pu = yB1 >> s->sps->log2_min_pu_size;



    const int xB0    = x0 + nPbW;

    const int yB0    = y0 - 1;

    const int xB0_pu = xB0 >> s->sps->log2_min_pu_size;

    const int yB0_pu = yB0 >> s->sps->log2_min_pu_size;



    const int xA0    = x0 - 1;

    const int yA0    = y0 + nPbH;

    const int xA0_pu = xA0 >> s->sps->log2_min_pu_size;

    const int yA0_pu = yA0 >> s->sps->log2_min_pu_size;



    const int xB2    = x0 - 1;

    const int yB2    = y0 - 1;

    const int xB2_pu = xB2 >> s->sps->log2_min_pu_size;

    const int yB2_pu = yB2 >> s->sps->log2_min_pu_size;



    const int nb_refs = (s->sh.slice_type == P_SLICE) ?

                        s->sh.nb_refs[0] : FFMIN(s->sh.nb_refs[0], s->sh.nb_refs[1]);

    int check_MER   = 1;

    int check_MER_1 = 1;



    int zero_idx = 0;



    int nb_merge_cand = 0;

    int nb_orig_merge_cand = 0;



    int is_available_a0;

    int is_available_a1;

    int is_available_b0;

    int is_available_b1;

    int is_available_b2;

    int check_B0;

    int check_A0;



    //first left spatial merge candidate

    is_available_a1 = AVAILABLE(cand_left, A1);



    if (!singleMCLFlag && part_idx == 1 &&

        (lc->cu.part_mode == PART_Nx2N ||

         lc->cu.part_mode == PART_nLx2N ||

         lc->cu.part_mode == PART_nRx2N) ||

        isDiffMER(s, xA1, yA1, x0, y0)) {

        is_available_a1 = 0;

    }



    if (is_available_a1) {

        mergecandlist[0] = TAB_MVF_PU(A1);

        if (merge_idx == 0)

            return;

        nb_merge_cand++;

    }



    // above spatial merge candidate

    is_available_b1 = AVAILABLE(cand_up, B1);



    if (!singleMCLFlag && part_idx == 1 &&

        (lc->cu.part_mode == PART_2NxN ||

         lc->cu.part_mode == PART_2NxnU ||

         lc->cu.part_mode == PART_2NxnD) ||

        isDiffMER(s, xB1, yB1, x0, y0)) {

        is_available_b1 = 0;

    }



    if (is_available_a1 && is_available_b1)

        check_MER = !COMPARE_MV_REFIDX(B1, A1);



    if (is_available_b1 && check_MER)

        mergecandlist[nb_merge_cand++] = TAB_MVF_PU(B1);



    // above right spatial merge candidate

    check_MER = 1;

    check_B0  = PRED_BLOCK_AVAILABLE(B0);



    is_available_b0 = check_B0 && AVAILABLE(cand_up_right, B0);



    if (isDiffMER(s, xB0, yB0, x0, y0))

        is_available_b0 = 0;



    if (is_available_b1 && is_available_b0)

        check_MER = !COMPARE_MV_REFIDX(B0, B1);



    if (is_available_b0 && check_MER) {

        mergecandlist[nb_merge_cand] = TAB_MVF_PU(B0);

        if (merge_idx == nb_merge_cand)

            return;

        nb_merge_cand++;

    }



    // left bottom spatial merge candidate

    check_MER = 1;

    check_A0  = PRED_BLOCK_AVAILABLE(A0);



    is_available_a0 = check_A0 && AVAILABLE(cand_bottom_left, A0);



    if (isDiffMER(s, xA0, yA0, x0, y0))

        is_available_a0 = 0;



    if (is_available_a1 && is_available_a0)

        check_MER = !COMPARE_MV_REFIDX(A0, A1);



    if (is_available_a0 && check_MER) {

        mergecandlist[nb_merge_cand] = TAB_MVF_PU(A0);

        if (merge_idx == nb_merge_cand)

            return;

        nb_merge_cand++;

    }



    // above left spatial merge candidate

    check_MER = 1;



    is_available_b2 = AVAILABLE(cand_up_left, B2);



    if (isDiffMER(s, xB2, yB2, x0, y0))

        is_available_b2 = 0;



    if (is_available_a1 && is_available_b2)

        check_MER = !COMPARE_MV_REFIDX(B2, A1);



    if (is_available_b1 && is_available_b2)

        check_MER_1 = !COMPARE_MV_REFIDX(B2, B1);



    if (is_available_b2 && check_MER && check_MER_1 && nb_merge_cand != 4) {

        mergecandlist[nb_merge_cand] = TAB_MVF_PU(B2);

        if (merge_idx == nb_merge_cand)

            return;

        nb_merge_cand++;

    }



    // temporal motion vector candidate

    if (s->sh.slice_temporal_mvp_enabled_flag &&

        nb_merge_cand < s->sh.max_num_merge_cand) {

        Mv mv_l0_col, mv_l1_col;

        int available_l0 = temporal_luma_motion_vector(s, x0, y0, nPbW, nPbH,

                                                       0, &mv_l0_col, 0);

        int available_l1 = (s->sh.slice_type == B_SLICE) ?

                           temporal_luma_motion_vector(s, x0, y0, nPbW, nPbH,

                                                       0, &mv_l1_col, 1) : 0;



        if (available_l0 || available_l1) {

            mergecandlist[nb_merge_cand].is_intra     = 0;

            mergecandlist[nb_merge_cand].pred_flag[0] = available_l0;

            mergecandlist[nb_merge_cand].pred_flag[1] = available_l1;

            if (available_l0) {

                mergecandlist[nb_merge_cand].mv[0]      = mv_l0_col;

                mergecandlist[nb_merge_cand].ref_idx[0] = 0;

            }

            if (available_l1) {

                mergecandlist[nb_merge_cand].mv[1]      = mv_l1_col;

                mergecandlist[nb_merge_cand].ref_idx[1] = 0;

            }

            if (merge_idx == nb_merge_cand)

                return;

            nb_merge_cand++;

        }

    }



    nb_orig_merge_cand = nb_merge_cand;



    // combined bi-predictive merge candidates  (applies for B slices)

    if (s->sh.slice_type == B_SLICE && nb_orig_merge_cand > 1 &&

        nb_orig_merge_cand < s->sh.max_num_merge_cand) {

        int comb_idx;



        for (comb_idx = 0; nb_merge_cand < s->sh.max_num_merge_cand &&

                           comb_idx < nb_orig_merge_cand * (nb_orig_merge_cand - 1); comb_idx++) {

            int l0_cand_idx = l0_l1_cand_idx[comb_idx][0];

            int l1_cand_idx = l0_l1_cand_idx[comb_idx][1];

            MvField l0_cand = mergecandlist[l0_cand_idx];

            MvField l1_cand = mergecandlist[l1_cand_idx];



            if (l0_cand.pred_flag[0] && l1_cand.pred_flag[1] &&

                (refPicList[0].list[l0_cand.ref_idx[0]] !=

                 refPicList[1].list[l1_cand.ref_idx[1]] ||

                 AV_RN32A(&l0_cand.mv[0]) != AV_RN32A(&l1_cand.mv[1]))) {

                mergecandlist[nb_merge_cand].ref_idx[0]   = l0_cand.ref_idx[0];

                mergecandlist[nb_merge_cand].ref_idx[1]   = l1_cand.ref_idx[1];

                mergecandlist[nb_merge_cand].pred_flag[0] = 1;

                mergecandlist[nb_merge_cand].pred_flag[1] = 1;

                AV_COPY32(&mergecandlist[nb_merge_cand].mv[0], &l0_cand.mv[0]);

                AV_COPY32(&mergecandlist[nb_merge_cand].mv[1], &l1_cand.mv[1]);

                mergecandlist[nb_merge_cand].is_intra     = 0;

                if (merge_idx == nb_merge_cand)

                    return;

                nb_merge_cand++;

            }

        }

    }



    // append Zero motion vector candidates

    while (nb_merge_cand < s->sh.max_num_merge_cand) {

        mergecandlist[nb_merge_cand].pred_flag[0] = 1;

        mergecandlist[nb_merge_cand].pred_flag[1] = s->sh.slice_type == B_SLICE;

        AV_ZERO32(mergecandlist[nb_merge_cand].mv + 0);

        AV_ZERO32(mergecandlist[nb_merge_cand].mv + 1);

        mergecandlist[nb_merge_cand].is_intra     = 0;

        mergecandlist[nb_merge_cand].ref_idx[0]   = zero_idx < nb_refs ? zero_idx : 0;

        mergecandlist[nb_merge_cand].ref_idx[1]   = zero_idx < nb_refs ? zero_idx : 0;



        if (merge_idx == nb_merge_cand)

            return;

        nb_merge_cand++;

        zero_idx++;

    }

}

int spapr_populate_pci_devices(sPAPRPHBState *phb,

                               uint32_t xics_phandle,

                               void *fdt)

{

    PCIBus *bus = phb->host_state.bus;

    int bus_off, node_off = 0, devid, fn, i, n, devices;

    DeviceState *qdev;

    char nodename[256];

    struct {

        uint32_t hi;

        uint64_t addr;

        uint64_t size;

    } __attribute__((packed)) reg[PCI_NUM_REGIONS + 1],

          assigned_addresses[PCI_NUM_REGIONS];

    uint32_t bus_range[] = { cpu_to_be32(0), cpu_to_be32(0xff) };

    struct {

        uint32_t hi;

        uint64_t child;

        uint64_t parent;

        uint64_t size;

    } __attribute__((packed)) ranges[] = {

        {

            cpu_to_be32(b_ss(1)), cpu_to_be64(0),

            cpu_to_be64(phb->io_win_addr),

            cpu_to_be64(memory_region_size(&phb->iospace)),

        },

        {

            cpu_to_be32(b_ss(2)), cpu_to_be64(SPAPR_PCI_MEM_WIN_BUS_OFFSET),

            cpu_to_be64(phb->mem_win_addr),

            cpu_to_be64(memory_region_size(&phb->memwindow)),

        },

    };

    uint64_t bus_reg[] = { cpu_to_be64(phb->buid), 0 };

    uint32_t interrupt_map_mask[] = {

        cpu_to_be32(b_ddddd(-1)|b_fff(-1)), 0x0, 0x0, 0x0};

    uint32_t interrupt_map[bus->nirq][7];



    /* Start populating the FDT */

    sprintf(nodename, "pci@%" PRIx64, phb->buid);

    bus_off = fdt_add_subnode(fdt, 0, nodename);

    if (bus_off < 0) {

        return bus_off;

    }



#define _FDT(exp) \

    do { \

        int ret = (exp);                                           \

        if (ret < 0) {                                             \

            return ret;                                            \

        }                                                          \

    } while (0)



    /* Write PHB properties */

    _FDT(fdt_setprop_string(fdt, bus_off, "device_type", "pci"));

    _FDT(fdt_setprop_string(fdt, bus_off, "compatible", "IBM,Logical_PHB"));

    _FDT(fdt_setprop_cell(fdt, bus_off, "#address-cells", 0x3));

    _FDT(fdt_setprop_cell(fdt, bus_off, "#size-cells", 0x2));

    _FDT(fdt_setprop_cell(fdt, bus_off, "#interrupt-cells", 0x1));

    _FDT(fdt_setprop(fdt, bus_off, "used-by-rtas", NULL, 0));

    _FDT(fdt_setprop(fdt, bus_off, "bus-range", &bus_range, sizeof(bus_range)));

    _FDT(fdt_setprop(fdt, bus_off, "ranges", &ranges, sizeof(ranges)));

    _FDT(fdt_setprop(fdt, bus_off, "reg", &bus_reg, sizeof(bus_reg)));

    _FDT(fdt_setprop(fdt, bus_off, "interrupt-map-mask",

                     &interrupt_map_mask, sizeof(interrupt_map_mask)));



    /* Populate PCI devices and allocate IRQs */

    devices = 0;

    QTAILQ_FOREACH(qdev, &bus->qbus.children, sibling) {

        PCIDevice *dev = DO_UPCAST(PCIDevice, qdev, qdev);

        int irq_index = pci_spapr_map_irq(dev, 0);

        uint32_t *irqmap = interrupt_map[devices];

        uint8_t *config = dev->config;



        devid = dev->devfn >> 3;

        fn = dev->devfn & 7;



        sprintf(nodename, "pci@%u,%u", devid, fn);



        /* Allocate interrupt from the map */

        if (devid > bus->nirq)  {

            printf("Unexpected behaviour in spapr_populate_pci_devices,"

                    "wrong devid %u\n", devid);

            exit(-1);

        }

        irqmap[0] = cpu_to_be32(b_ddddd(devid)|b_fff(fn));

        irqmap[1] = 0;

        irqmap[2] = 0;

        irqmap[3] = 0;

        irqmap[4] = cpu_to_be32(xics_phandle);

        irqmap[5] = cpu_to_be32(phb->lsi_table[irq_index].dt_irq);

        irqmap[6] = cpu_to_be32(0x8);



        /* Add node to FDT */

        node_off = fdt_add_subnode(fdt, bus_off, nodename);

        if (node_off < 0) {

            return node_off;

        }



        _FDT(fdt_setprop_cell(fdt, node_off, "vendor-id",

                              pci_get_word(&config[PCI_VENDOR_ID])));

        _FDT(fdt_setprop_cell(fdt, node_off, "device-id",

                              pci_get_word(&config[PCI_DEVICE_ID])));

        _FDT(fdt_setprop_cell(fdt, node_off, "revision-id",

                              pci_get_byte(&config[PCI_REVISION_ID])));

        _FDT(fdt_setprop_cell(fdt, node_off, "class-code",

                              pci_get_long(&config[PCI_CLASS_REVISION]) >> 8));

        _FDT(fdt_setprop_cell(fdt, node_off, "subsystem-id",

                              pci_get_word(&config[PCI_SUBSYSTEM_ID])));

        _FDT(fdt_setprop_cell(fdt, node_off, "subsystem-vendor-id",

                              pci_get_word(&config[PCI_SUBSYSTEM_VENDOR_ID])));



        /* Config space region comes first */

        reg[0].hi = cpu_to_be32(

            b_n(0) |

            b_p(0) |

            b_t(0) |

            b_ss(0/*config*/) |

            b_bbbbbbbb(0) |

            b_ddddd(devid) |

            b_fff(fn));

        reg[0].addr = 0;

        reg[0].size = 0;



        n = 0;

        for (i = 0; i < PCI_NUM_REGIONS; ++i) {

            if (0 == dev->io_regions[i].size) {

                continue;

            }



            reg[n+1].hi = cpu_to_be32(

                b_n(0) |

                b_p(0) |

                b_t(0) |

                b_ss(regtype_to_ss(dev->io_regions[i].type)) |

                b_bbbbbbbb(0) |

                b_ddddd(devid) |

                b_fff(fn) |

                b_rrrrrrrr(bars[i]));

            reg[n+1].addr = 0;

            reg[n+1].size = cpu_to_be64(dev->io_regions[i].size);



            assigned_addresses[n].hi = cpu_to_be32(

                b_n(1) |

                b_p(0) |

                b_t(0) |

                b_ss(regtype_to_ss(dev->io_regions[i].type)) |

                b_bbbbbbbb(0) |

                b_ddddd(devid) |

                b_fff(fn) |

                b_rrrrrrrr(bars[i]));



            /*

             * Writing zeroes to assigned_addresses causes the guest kernel to

             * reassign BARs

             */

            assigned_addresses[n].addr = cpu_to_be64(dev->io_regions[i].addr);

            assigned_addresses[n].size = reg[n+1].size;



            ++n;

        }

        _FDT(fdt_setprop(fdt, node_off, "reg", reg, sizeof(reg[0])*(n+1)));

        _FDT(fdt_setprop(fdt, node_off, "assigned-addresses",

                         assigned_addresses,

                         sizeof(assigned_addresses[0])*(n)));

        _FDT(fdt_setprop_cell(fdt, node_off, "interrupts",

                              pci_get_byte(&config[PCI_INTERRUPT_PIN])));



        ++devices;

    }



    /* Write interrupt map */

    _FDT(fdt_setprop(fdt, bus_off, "interrupt-map", &interrupt_map,

                     devices * sizeof(interrupt_map[0])));



    return 0;

}

static abi_long do_ioctl_rt(const IOCTLEntry *ie, uint8_t *buf_temp,

                                int fd, int cmd, abi_long arg)

{

    const argtype *arg_type = ie->arg_type;

    const StructEntry *se;

    const argtype *field_types;

    const int *dst_offsets, *src_offsets;

    int target_size;

    void *argptr;

    abi_ulong *target_rt_dev_ptr;

    unsigned long *host_rt_dev_ptr;

    abi_long ret;

    int i;



    assert(ie->access == IOC_W);

    assert(*arg_type == TYPE_PTR);

    arg_type++;

    assert(*arg_type == TYPE_STRUCT);

    target_size = thunk_type_size(arg_type, 0);

    argptr = lock_user(VERIFY_READ, arg, target_size, 1);

    if (!argptr) {

        return -TARGET_EFAULT;

    }

    arg_type++;

    assert(*arg_type == (int)STRUCT_rtentry);

    se = struct_entries + *arg_type++;

    assert(se->convert[0] == NULL);

    /* convert struct here to be able to catch rt_dev string */

    field_types = se->field_types;

    dst_offsets = se->field_offsets[THUNK_HOST];

    src_offsets = se->field_offsets[THUNK_TARGET];

    for (i = 0; i < se->nb_fields; i++) {

        if (dst_offsets[i] == offsetof(struct rtentry, rt_dev)) {

            assert(*field_types == TYPE_PTRVOID);

            target_rt_dev_ptr = (abi_ulong *)(argptr + src_offsets[i]);

            host_rt_dev_ptr = (unsigned long *)(buf_temp + dst_offsets[i]);

            if (*target_rt_dev_ptr != 0) {

                *host_rt_dev_ptr = (unsigned long)lock_user_string(

                                                  tswapal(*target_rt_dev_ptr));

                if (!*host_rt_dev_ptr) {

                    unlock_user(argptr, arg, 0);

                    return -TARGET_EFAULT;

                }

            } else {

                *host_rt_dev_ptr = 0;

            }

            field_types++;

            continue;

        }

        field_types = thunk_convert(buf_temp + dst_offsets[i],

                                    argptr + src_offsets[i],

                                    field_types, THUNK_HOST);

    }

    unlock_user(argptr, arg, 0);

    assert(host_rt_dev_ptr);



    ret = get_errno(safe_ioctl(fd, ie->host_cmd, buf_temp));

    if (*host_rt_dev_ptr != 0) {

        unlock_user((void *)*host_rt_dev_ptr,

                    *target_rt_dev_ptr, 0);

    }

    return ret;

}

