static void flush_buffer(ByteIOContext *s)

{

    if (s->buf_ptr > s->buffer) {

        if (s->write_packet)

            s->write_packet(s->opaque, s->buffer, s->buf_ptr - s->buffer);

        if(s->checksum_ptr){

            s->checksum= s->update_checksum(s->checksum, s->checksum_ptr, s->buf_ptr - s->checksum_ptr);

            s->checksum_ptr= s->buffer;

        }

        s->pos += s->buf_ptr - s->buffer;

    }

    s->buf_ptr = s->buffer;

}

int net_init_slirp(QemuOpts *opts, const char *name, VLANState *vlan)

{

    struct slirp_config_str *config;

    const char *vhost;

    const char *vhostname;

    const char *vdhcp_start;

    const char *vnamesrv;

    const char *tftp_export;

    const char *bootfile;

    const char *smb_export;

    const char *vsmbsrv;

    const char *restrict_opt;

    char *vnet = NULL;

    int restricted = 0;

    int ret;



    vhost       = qemu_opt_get(opts, "host");

    vhostname   = qemu_opt_get(opts, "hostname");

    vdhcp_start = qemu_opt_get(opts, "dhcpstart");

    vnamesrv    = qemu_opt_get(opts, "dns");

    tftp_export = qemu_opt_get(opts, "tftp");

    bootfile    = qemu_opt_get(opts, "bootfile");

    smb_export  = qemu_opt_get(opts, "smb");

    vsmbsrv     = qemu_opt_get(opts, "smbserver");



    restrict_opt = qemu_opt_get(opts, "restrict");

    if (restrict_opt) {

        if (!strcmp(restrict_opt, "on") ||

            !strcmp(restrict_opt, "yes") || !strcmp(restrict_opt, "y")) {

            restricted = 1;

        } else if (strcmp(restrict_opt, "off") &&

            strcmp(restrict_opt, "no") && strcmp(restrict_opt, "n")) {

            error_report("invalid option: 'restrict=%s'", restrict_opt);

            return -1;

        }

    }



    if (qemu_opt_get(opts, "ip")) {

        const char *ip = qemu_opt_get(opts, "ip");

        int l = strlen(ip) + strlen("/24") + 1;



        vnet = g_malloc(l);



        /* emulate legacy ip= parameter */

        pstrcpy(vnet, l, ip);

        pstrcat(vnet, l, "/24");

    }



    if (qemu_opt_get(opts, "net")) {

        if (vnet) {

            g_free(vnet);

        }

        vnet = g_strdup(qemu_opt_get(opts, "net"));

    }



    qemu_opt_foreach(opts, net_init_slirp_configs, NULL, 0);



    ret = net_slirp_init(vlan, "user", name, restricted, vnet, vhost,

                         vhostname, tftp_export, bootfile, vdhcp_start,

                         vnamesrv, smb_export, vsmbsrv);



    while (slirp_configs) {

        config = slirp_configs;

        slirp_configs = config->next;

        g_free(config);

    }



    g_free(vnet);



    return ret;

}

static int daala_packet(AVFormatContext *s, int idx)

{

    int seg, duration = 1;

    struct ogg *ogg = s->priv_data;

    struct ogg_stream *os = ogg->streams + idx;



    /*

     * first packet handling: here we parse the duration of each packet in the

     * first page and compare the total duration to the page granule to find the

     * encoder delay and set the first timestamp

     */



    if ((!os->lastpts || os->lastpts == AV_NOPTS_VALUE) && !(os->flags & OGG_FLAG_EOS)) {

        for (seg = os->segp; seg < os->nsegs; seg++)

            if (os->segments[seg] < 255)

                duration++;



        os->lastpts = os->lastdts = daala_gptopts(s, idx, os->granule, NULL) - duration;

        if(s->streams[idx]->start_time == AV_NOPTS_VALUE) {

            s->streams[idx]->start_time = os->lastpts;

            if (s->streams[idx]->duration)

                s->streams[idx]->duration -= s->streams[idx]->start_time;

        }

    }



    /* parse packet duration */

    if (os->psize > 0)

        os->pduration = 1;



    return 0;

}

static int clv_decode_frame(AVCodecContext *avctx, void *data,

                            int *got_frame, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    CLVContext *c = avctx->priv_data;

    GetByteContext gb;

    uint32_t frame_type;

    int i, j;

    int ret;

    int mb_ret = 0;



    bytestream2_init(&gb, buf, buf_size);

    if (avctx->codec_tag == MKTAG('C','L','V','1')) {

        int skip = bytestream2_get_byte(&gb);

        bytestream2_skip(&gb, (skip + 1) * 8);

    }



    frame_type = bytestream2_get_byte(&gb);

    if ((ret = ff_reget_buffer(avctx, c->pic)) < 0)

        return ret;



    c->pic->key_frame = frame_type & 0x20 ? 1 : 0;

    c->pic->pict_type = frame_type & 0x20 ? AV_PICTURE_TYPE_I : AV_PICTURE_TYPE_P;



    if (frame_type & 0x2) {

        if (buf_size < c->mb_width * c->mb_height) {

            av_log(avctx, AV_LOG_ERROR, "Packet too small\n");

            return AVERROR_INVALIDDATA;

        }



        bytestream2_get_be32(&gb); // frame size;

        c->ac_quant        = bytestream2_get_byte(&gb);

        c->luma_dc_quant   = 32;

        c->chroma_dc_quant = 32;



        if ((ret = init_get_bits8(&c->gb, buf + bytestream2_tell(&gb),

                                  (buf_size - bytestream2_tell(&gb)))) < 0)

            return ret;



        for (i = 0; i < 3; i++)

            c->top_dc[i] = 32;

        for (i = 0; i < 4; i++)

            c->left_dc[i] = 32;



        for (j = 0; j < c->mb_height; j++) {

            for (i = 0; i < c->mb_width; i++) {

                ret = decode_mb(c, i, j);

                if (ret < 0)

                    mb_ret = ret;

            }

        }

    } else {

    }



    if ((ret = av_frame_ref(data, c->pic)) < 0)

        return ret;



    *got_frame = 1;



    return mb_ret < 0 ? mb_ret : buf_size;

}

static int read_frame(BVID_DemuxContext *vid, AVIOContext *pb, AVPacket *pkt,

                      uint8_t block_type, AVFormatContext *s)

{

    uint8_t * vidbuf_start = NULL;

    int vidbuf_nbytes = 0;

    int code;

    int bytes_copied = 0;

    int position, duration, npixels;

    unsigned int vidbuf_capacity;

    int ret = 0;

    AVStream *st;



    if (vid->video_index < 0) {

        st = avformat_new_stream(s, NULL);

        if (!st)

            return AVERROR(ENOMEM);

        vid->video_index = st->index;

        if (vid->audio_index < 0) {

            av_log_ask_for_sample(s, "No audio packet before first video "

                                  "packet. Using default video time base.\n");

        }

        avpriv_set_pts_info(st, 64, 185, vid->sample_rate);

        st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

        st->codec->codec_id   = AV_CODEC_ID_BETHSOFTVID;

        st->codec->width      = vid->width;

        st->codec->height     = vid->height;

    }

    st      = s->streams[vid->video_index];

    npixels = st->codec->width * st->codec->height;



    vidbuf_start = av_malloc(vidbuf_capacity = BUFFER_PADDING_SIZE);

    if(!vidbuf_start)

        return AVERROR(ENOMEM);



    // save the file position for the packet, include block type

    position = avio_tell(pb) - 1;



    vidbuf_start[vidbuf_nbytes++] = block_type;



    // get the current packet duration

    duration = vid->bethsoft_global_delay + avio_rl16(pb);



    // set the y offset if it exists (decoder header data should be in data section)

    if(block_type == VIDEO_YOFF_P_FRAME){

        if (avio_read(pb, &vidbuf_start[vidbuf_nbytes], 2) != 2) {

            ret = AVERROR(EIO);

            goto fail;

        }

        vidbuf_nbytes += 2;

    }



    do{

        vidbuf_start = av_fast_realloc(vidbuf_start, &vidbuf_capacity, vidbuf_nbytes + BUFFER_PADDING_SIZE);

        if(!vidbuf_start)

            return AVERROR(ENOMEM);



        code = avio_r8(pb);

        vidbuf_start[vidbuf_nbytes++] = code;



        if(code >= 0x80){ // rle sequence

            if(block_type == VIDEO_I_FRAME)

                vidbuf_start[vidbuf_nbytes++] = avio_r8(pb);

        } else if(code){ // plain sequence

            if (avio_read(pb, &vidbuf_start[vidbuf_nbytes], code) != code) {

                ret = AVERROR(EIO);

                goto fail;

            }

            vidbuf_nbytes += code;

        }

        bytes_copied += code & 0x7F;

        if(bytes_copied == npixels){ // sometimes no stop character is given, need to keep track of bytes copied

            // may contain a 0 byte even if read all pixels

            if(avio_r8(pb))

                avio_seek(pb, -1, SEEK_CUR);

            break;

        }

        if (bytes_copied > npixels) {

            ret = AVERROR_INVALIDDATA;

            goto fail;

        }

    } while(code);



    // copy data into packet

    if ((ret = av_new_packet(pkt, vidbuf_nbytes)) < 0)

        goto fail;

    memcpy(pkt->data, vidbuf_start, vidbuf_nbytes);

    av_free(vidbuf_start);



    pkt->pos = position;

    pkt->stream_index = vid->video_index;

    pkt->duration = duration;

    if (block_type == VIDEO_I_FRAME)

        pkt->flags |= AV_PKT_FLAG_KEY;



    /* if there is a new palette available, add it to packet side data */

    if (vid->palette) {

        uint8_t *pdata = av_packet_new_side_data(pkt, AV_PKT_DATA_PALETTE,

                                                 BVID_PALETTE_SIZE);

        memcpy(pdata, vid->palette, BVID_PALETTE_SIZE);

        av_freep(&vid->palette);

    }



    vid->nframes--;  // used to check if all the frames were read

    return 0;

fail:

    av_free(vidbuf_start);

    return ret;

}

