static int config_input(AVFilterLink *inlink)

{

    AVFilterContext *ctx = inlink->dst;

    PadContext *s = ctx->priv;

    const AVPixFmtDescriptor *pix_desc = av_pix_fmt_desc_get(inlink->format);

    uint8_t rgba_color[4];

    int ret, is_packed_rgba;

    double var_values[VARS_NB], res;

    char *expr;



    s->hsub = pix_desc->log2_chroma_w;

    s->vsub = pix_desc->log2_chroma_h;



    var_values[VAR_PI]    = M_PI;

    var_values[VAR_PHI]   = M_PHI;

    var_values[VAR_E]     = M_E;

    var_values[VAR_IN_W]  = var_values[VAR_IW] = inlink->w;

    var_values[VAR_IN_H]  = var_values[VAR_IH] = inlink->h;

    var_values[VAR_OUT_W] = var_values[VAR_OW] = NAN;

    var_values[VAR_OUT_H] = var_values[VAR_OH] = NAN;

    var_values[VAR_A]     = (double) inlink->w / inlink->h;

    var_values[VAR_HSUB]  = 1<<s->hsub;

    var_values[VAR_VSUB]  = 1<<s->vsub;



    /* evaluate width and height */

    if ((ret = av_expr_parse_and_eval(&res, (expr = s->w_expr),

                                      var_names, var_values,

                                      NULL, NULL, NULL, NULL, NULL, 0, ctx)) < 0)

        goto eval_fail;

    s->w = var_values[VAR_OUT_W] = var_values[VAR_OW] = res;

    if ((ret = av_expr_parse_and_eval(&res, (expr = s->h_expr),

                                      var_names, var_values,

                                      NULL, NULL, NULL, NULL, NULL, 0, ctx)) < 0)

        goto eval_fail;

    s->h = var_values[VAR_OUT_H] = var_values[VAR_OH] = res;

    /* evaluate the width again, as it may depend on the evaluated output height */

    if ((ret = av_expr_parse_and_eval(&res, (expr = s->w_expr),

                                      var_names, var_values,

                                      NULL, NULL, NULL, NULL, NULL, 0, ctx)) < 0)

        goto eval_fail;

    s->w = var_values[VAR_OUT_W] = var_values[VAR_OW] = res;



    /* evaluate x and y */

    if ((ret = av_expr_parse_and_eval(&res, (expr = s->x_expr),

                                      var_names, var_values,

                                      NULL, NULL, NULL, NULL, NULL, 0, ctx)) < 0)

        goto eval_fail;

    s->x = var_values[VAR_X] = res;

    if ((ret = av_expr_parse_and_eval(&res, (expr = s->y_expr),

                                      var_names, var_values,

                                      NULL, NULL, NULL, NULL, NULL, 0, ctx)) < 0)

        goto eval_fail;

    s->y = var_values[VAR_Y] = res;

    /* evaluate x again, as it may depend on the evaluated y value */

    if ((ret = av_expr_parse_and_eval(&res, (expr = s->x_expr),

                                      var_names, var_values,

                                      NULL, NULL, NULL, NULL, NULL, 0, ctx)) < 0)

        goto eval_fail;

    s->x = var_values[VAR_X] = res;



    /* sanity check params */

    if (s->w < 0 || s->h < 0 || s->x < 0 || s->y < 0) {

        av_log(ctx, AV_LOG_ERROR, "Negative values are not acceptable.\n");

        return AVERROR(EINVAL);

    }



    if (!s->w)

        s->w = inlink->w;

    if (!s->h)

        s->h = inlink->h;



    s->w &= ~((1 << s->hsub) - 1);

    s->h &= ~((1 << s->vsub) - 1);

    s->x &= ~((1 << s->hsub) - 1);

    s->y &= ~((1 << s->vsub) - 1);



    s->in_w = inlink->w & ~((1 << s->hsub) - 1);

    s->in_h = inlink->h & ~((1 << s->vsub) - 1);



    memcpy(rgba_color, s->color, sizeof(rgba_color));

    ff_fill_line_with_color(s->line, s->line_step, s->w, s->color,

                            inlink->format, rgba_color, &is_packed_rgba, NULL);



    av_log(ctx, AV_LOG_VERBOSE, "w:%d h:%d -> w:%d h:%d x:%d y:%d color:0x%02X%02X%02X%02X[%s]\n",

           inlink->w, inlink->h, s->w, s->h, s->x, s->y,

           s->color[0], s->color[1], s->color[2], s->color[3],

           is_packed_rgba ? "rgba" : "yuva");



    if (s->x <  0 || s->y <  0                      ||

        s->w <= 0 || s->h <= 0                      ||

        (unsigned)s->x + (unsigned)inlink->w > s->w ||

        (unsigned)s->y + (unsigned)inlink->h > s->h) {

        av_log(ctx, AV_LOG_ERROR,

               "Input area %d:%d:%d:%d not within the padded area 0:0:%d:%d or zero-sized\n",

               s->x, s->y, s->x + inlink->w, s->y + inlink->h, s->w, s->h);

        return AVERROR(EINVAL);

    }



    return 0;



eval_fail:

    av_log(NULL, AV_LOG_ERROR,

           "Error when evaluating the expression '%s'\n", expr);

    return ret;



}

static void local_mapped_file_attr(FsContext *ctx, const char *path,

                                   struct stat *stbuf)

{

    FILE *fp;

    char buf[ATTR_MAX];

    char *attr_path;



    attr_path = local_mapped_attr_path(ctx, path);

    fp = local_fopen(attr_path, "r");

    g_free(attr_path);

    if (!fp) {

        return;

    }

    memset(buf, 0, ATTR_MAX);

    while (fgets(buf, ATTR_MAX, fp)) {

        if (!strncmp(buf, "virtfs.uid", 10)) {

            stbuf->st_uid = atoi(buf+11);

        } else if (!strncmp(buf, "virtfs.gid", 10)) {

            stbuf->st_gid = atoi(buf+11);

        } else if (!strncmp(buf, "virtfs.mode", 11)) {

            stbuf->st_mode = atoi(buf+12);

        } else if (!strncmp(buf, "virtfs.rdev", 11)) {

            stbuf->st_rdev = atoi(buf+12);

        }

        memset(buf, 0, ATTR_MAX);

    }

    fclose(fp);

}

AVRational av_guess_frame_rate(AVFormatContext *format, AVStream *st, AVFrame *frame)

{

    AVRational fr = st->r_frame_rate;

    AVRational codec_fr = st->codec->framerate;

    AVRational   avg_fr = st->avg_frame_rate;



    if (avg_fr.num > 0 && avg_fr.den > 0 && fr.num > 0 && fr.den > 0 &&

        av_q2d(avg_fr) < 70 && av_q2d(fr) > 210) {

        fr = avg_fr;

    }





    if (st->codec->ticks_per_frame > 1) {

        if (   codec_fr.num > 0 && codec_fr.den > 0 && av_q2d(codec_fr) < av_q2d(fr)*0.7

            && fabs(1.0 - av_q2d(av_div_q(avg_fr, fr))) > 0.1)

            fr = codec_fr;

    }



    return fr;

}

static void apply_mid_side_stereo(ChannelElement *cpe)

{

    int w, w2, g, i;

    IndividualChannelStream *ics = &cpe->ch[0].ics;

    if (!cpe->common_window)

        return;

    for (w = 0; w < ics->num_windows; w += ics->group_len[w]) {

        for (w2 =  0; w2 < ics->group_len[w]; w2++) {

            int start = (w+w2) * 128;

            for (g = 0; g < ics->num_swb; g++) {

                if (!cpe->ms_mask[w*16 + g]) {

                    start += ics->swb_sizes[g];

                    continue;

                }

                for (i = 0; i < ics->swb_sizes[g]; i++) {

                    float L = (cpe->ch[0].coeffs[start+i] + cpe->ch[1].coeffs[start+i]) * 0.5f;

                    float R = L - cpe->ch[1].coeffs[start+i];

                    cpe->ch[0].coeffs[start+i] = L;

                    cpe->ch[1].coeffs[start+i] = R;

                }

                start += ics->swb_sizes[g];

            }

        }

    }

}

static int ea_read_header(AVFormatContext *s,

                          AVFormatParameters *ap)

{

    EaDemuxContext *ea = s->priv_data;

    AVStream *st;



    if (!process_ea_header(s))

        return AVERROR(EIO);



    if (ea->time_base.num && ea->time_base.den) {

        /* initialize the video decoder stream */

        st = av_new_stream(s, 0);

        if (!st)

            return AVERROR(ENOMEM);

        ea->video_stream_index = st->index;

        st->codec->codec_type = CODEC_TYPE_VIDEO;

        st->codec->codec_id = ea->video_codec;

        st->codec->codec_tag = 0;  /* no fourcc */

        st->codec->time_base = ea->time_base;

    }



    if (ea->audio_codec) {

        /* initialize the audio decoder stream */

        st = av_new_stream(s, 0);

        if (!st)

            return AVERROR(ENOMEM);

        av_set_pts_info(st, 33, 1, ea->sample_rate);

        st->codec->codec_type = CODEC_TYPE_AUDIO;

        st->codec->codec_id = ea->audio_codec;

        st->codec->codec_tag = 0;  /* no tag */

        st->codec->channels = ea->num_channels;

        st->codec->sample_rate = ea->sample_rate;

        st->codec->bits_per_sample = ea->bytes * 8;

        st->codec->bit_rate = st->codec->channels * st->codec->sample_rate *

            st->codec->bits_per_sample / 4;

        st->codec->block_align = st->codec->channels*st->codec->bits_per_sample;

        ea->audio_stream_index = st->index;

        ea->audio_frame_counter = 0;

    }



    return 1;

}

static int ppc_hash32_get_bat(CPUPPCState *env, struct mmu_ctx_hash32 *ctx,

                              target_ulong virtual, int rwx)

{

    target_ulong *BATlt, *BATut;

    target_ulong BEPIl, BEPIu, bl;

    int i, valid, prot;

    int ret = -1;



    LOG_BATS("%s: %cBAT v " TARGET_FMT_lx "\n", __func__,

             rwx == 2 ? 'I' : 'D', virtual);

    if (rwx == 2) {

        BATlt = env->IBAT[1];

        BATut = env->IBAT[0];

    } else {

        BATlt = env->DBAT[1];

        BATut = env->DBAT[0];

    }

    for (i = 0; i < env->nb_BATs; i++) {

        target_ulong batu = BATut[i];

        target_ulong batl = BATlt[i];



        BEPIu = batu & BATU32_BEPIU;

        BEPIl = batu & BATU32_BEPIL;

        if (unlikely(env->mmu_model == POWERPC_MMU_601)) {

            hash32_bat_601_size(env, &bl, &valid, batu, batl);

            prot = hash32_bat_601_prot(env, batu, batl);

        } else {

            hash32_bat_size(env, &bl, &valid, batu, batl);

            prot = hash32_bat_prot(env, batu, batl);

        }

        LOG_BATS("%s: %cBAT%d v " TARGET_FMT_lx " BATu " TARGET_FMT_lx

                 " BATl " TARGET_FMT_lx "\n", __func__,

                 type == ACCESS_CODE ? 'I' : 'D', i, virtual, batu, batl);

        if ((virtual & BATU32_BEPIU) == BEPIu &&

            ((virtual & BATU32_BEPIL) & ~bl) == BEPIl) {

            /* BAT matches */

            if (valid != 0) {

                /* Get physical address */

                ctx->raddr = (batl & BATL32_BRPNU) |

                    ((virtual & BATU32_BEPIL & bl) | (batl & BATL32_BRPNL)) |

                    (virtual & 0x0001F000);

                /* Compute access rights */

                ctx->prot = prot;

                ret = ppc_hash32_check_prot(ctx->prot, rwx);

                if (ret == 0) {

                    LOG_BATS("BAT %d match: r " TARGET_FMT_plx " prot=%c%c\n",

                             i, ctx->raddr, ctx->prot & PAGE_READ ? 'R' : '-',

                             ctx->prot & PAGE_WRITE ? 'W' : '-');

                }

                break;

            }

        }

    }

    if (ret < 0) {

#if defined(DEBUG_BATS)

        if (qemu_log_enabled()) {

            LOG_BATS("no BAT match for " TARGET_FMT_lx ":\n", virtual);

            for (i = 0; i < 4; i++) {

                BATu = &BATut[i];

                BATl = &BATlt[i];

                BEPIu = *BATu & BATU32_BEPIU;

                BEPIl = *BATu & BATU32_BEPIL;

                bl = (*BATu & 0x00001FFC) << 15;

                LOG_BATS("%s: %cBAT%d v " TARGET_FMT_lx " BATu " TARGET_FMT_lx

                         " BATl " TARGET_FMT_lx "\n\t" TARGET_FMT_lx " "

                         TARGET_FMT_lx " " TARGET_FMT_lx "\n",

                         __func__, type == ACCESS_CODE ? 'I' : 'D', i, virtual,

                         *BATu, *BATl, BEPIu, BEPIl, bl);

            }

        }

#endif

    }

    /* No hit */

    return ret;

}

