static int64_t ftp_seek(URLContext *h, int64_t pos, int whence)

{

    FTPContext *s = h->priv_data;

    int err;

    int64_t new_pos, fake_pos;



    av_dlog(h, "ftp protocol seek %"PRId64" %d\n", pos, whence);



    switch(whence) {

    case AVSEEK_SIZE:

        return s->filesize;

    case SEEK_SET:

        new_pos = pos;

        break;

    case SEEK_CUR:

        new_pos = s->position + pos;

        break;

    case SEEK_END:

        if (s->filesize < 0)

            return AVERROR(EIO);

        new_pos = s->filesize + pos;

        break;

    default:

        return AVERROR(EINVAL);

    }



    if (h->is_streamed)

        return AVERROR(EIO);



    if (new_pos < 0) {

        av_log(h, AV_LOG_ERROR, "Seeking to nagative position.\n");

        return AVERROR(EINVAL);

    }



    fake_pos = s->filesize != -1 ? FFMIN(new_pos, s->filesize) : new_pos;

    if (fake_pos != s->position) {

        if ((err = ftp_abort(h)) < 0)

            return err;

        s->position = fake_pos;

    }

    return new_pos;

}

struct vhost_net *vhost_net_init(NetClientState *backend, int devfd,

                                 bool force)

{

    int r;

    struct vhost_net *net = g_malloc(sizeof *net);

    if (!backend) {

        fprintf(stderr, "vhost-net requires backend to be setup\n");

        goto fail;

    }

    r = vhost_net_get_fd(backend);

    if (r < 0) {

        goto fail;

    }

    net->nc = backend;

    net->dev.backend_features = tap_has_vnet_hdr(backend) ? 0 :

        (1 << VHOST_NET_F_VIRTIO_NET_HDR);

    net->backend = r;



    net->dev.nvqs = 2;

    net->dev.vqs = net->vqs;



    r = vhost_dev_init(&net->dev, devfd, "/dev/vhost-net", force);

    if (r < 0) {

        goto fail;

    }

    if (!tap_has_vnet_hdr_len(backend,

                              sizeof(struct virtio_net_hdr_mrg_rxbuf))) {

        net->dev.features &= ~(1 << VIRTIO_NET_F_MRG_RXBUF);

    }

    if (~net->dev.features & net->dev.backend_features) {

        fprintf(stderr, "vhost lacks feature mask %" PRIu64 " for backend\n",

                (uint64_t)(~net->dev.features & net->dev.backend_features));

        vhost_dev_cleanup(&net->dev);

        goto fail;

    }



    /* Set sane init value. Override when guest acks. */

    vhost_net_ack_features(net, 0);

    return net;

fail:

    g_free(net);

    return NULL;

}

static int encode_superframe(AVCodecContext *avctx, AVPacket *avpkt,

                             const AVFrame *frame, int *got_packet_ptr)

{

    WMACodecContext *s = avctx->priv_data;

    int i, total_gain, ret, error;



    s->block_len_bits= s->frame_len_bits; //required by non variable block len

    s->block_len = 1 << s->block_len_bits;



    apply_window_and_mdct(avctx, frame);



    if (s->ms_stereo) {

        float a, b;

        int i;



        for(i = 0; i < s->block_len; i++) {

            a = s->coefs[0][i]*0.5;

            b = s->coefs[1][i]*0.5;

            s->coefs[0][i] = a + b;

            s->coefs[1][i] = a - b;

        }

    }



    if ((ret = ff_alloc_packet2(avctx, avpkt, 2 * MAX_CODED_SUPERFRAME_SIZE)))

        return ret;



    total_gain= 128;

    for(i=64; i; i>>=1){

        error = encode_frame(s, s->coefs, avpkt->data, avpkt->size,

                                 total_gain - i);

        if(error<=0)

            total_gain-= i;

    }



    while(total_gain <= 128 && error > 0)

        error = encode_frame(s, s->coefs, avpkt->data, avpkt->size, total_gain++);

    av_assert0((put_bits_count(&s->pb) & 7) == 0);

    i= avctx->block_align - (put_bits_count(&s->pb)+7)/8;

    av_assert0(i>=0);

    while(i--)

        put_bits(&s->pb, 8, 'N');



    flush_put_bits(&s->pb);

    av_assert0(put_bits_ptr(&s->pb) - s->pb.buf == avctx->block_align);



    if (frame->pts != AV_NOPTS_VALUE)

        avpkt->pts = frame->pts - ff_samples_to_time_base(avctx, avctx->delay);



    avpkt->size = avctx->block_align;

    *got_packet_ptr = 1;

    return 0;

}

static int qcow_create(const char *filename, int64_t total_size,

                      const char *backing_file, int flags)

{

    int fd, header_size, backing_filename_len, l1_size, i, shift, l2_bits;

    QCowHeader header;

    uint64_t tmp, offset;

    QCowCreateState s1, *s = &s1;



    memset(s, 0, sizeof(*s));



    fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC | O_BINARY, 0644);

    if (fd < 0)

        return -1;

    memset(&header, 0, sizeof(header));

    header.magic = cpu_to_be32(QCOW_MAGIC);

    header.version = cpu_to_be32(QCOW_VERSION);

    header.size = cpu_to_be64(total_size * 512);

    header_size = sizeof(header);

    backing_filename_len = 0;

    if (backing_file) {

        header.backing_file_offset = cpu_to_be64(header_size);

        backing_filename_len = strlen(backing_file);

        header.backing_file_size = cpu_to_be32(backing_filename_len);

        header_size += backing_filename_len;

    }

    s->cluster_bits = 12;  /* 4 KB clusters */

    s->cluster_size = 1 << s->cluster_bits;

    header.cluster_bits = cpu_to_be32(s->cluster_bits);

    header_size = (header_size + 7) & ~7;

    if (flags & BLOCK_FLAG_ENCRYPT) {

        header.crypt_method = cpu_to_be32(QCOW_CRYPT_AES);

    } else {

        header.crypt_method = cpu_to_be32(QCOW_CRYPT_NONE);

    }

    l2_bits = s->cluster_bits - 3;

    shift = s->cluster_bits + l2_bits;

    l1_size = (((total_size * 512) + (1LL << shift) - 1) >> shift);

    offset = align_offset(header_size, s->cluster_size);

    s->l1_table_offset = offset;

    header.l1_table_offset = cpu_to_be64(s->l1_table_offset);

    header.l1_size = cpu_to_be32(l1_size);

    offset += align_offset(l1_size * sizeof(uint64_t), s->cluster_size);



    s->refcount_table = qemu_mallocz(s->cluster_size);

    s->refcount_block = qemu_mallocz(s->cluster_size);



    s->refcount_table_offset = offset;

    header.refcount_table_offset = cpu_to_be64(offset);

    header.refcount_table_clusters = cpu_to_be32(1);

    offset += s->cluster_size;



    s->refcount_table[0] = cpu_to_be64(offset);

    s->refcount_block_offset = offset;

    offset += s->cluster_size;



    /* update refcounts */

    create_refcount_update(s, 0, header_size);

    create_refcount_update(s, s->l1_table_offset, l1_size * sizeof(uint64_t));

    create_refcount_update(s, s->refcount_table_offset, s->cluster_size);

    create_refcount_update(s, s->refcount_block_offset, s->cluster_size);



    /* write all the data */

    write(fd, &header, sizeof(header));

    if (backing_file) {

        write(fd, backing_file, backing_filename_len);

    }

    lseek(fd, s->l1_table_offset, SEEK_SET);

    tmp = 0;

    for(i = 0;i < l1_size; i++) {

        write(fd, &tmp, sizeof(tmp));

    }

    lseek(fd, s->refcount_table_offset, SEEK_SET);

    write(fd, s->refcount_table, s->cluster_size);



    lseek(fd, s->refcount_block_offset, SEEK_SET);

    write(fd, s->refcount_block, s->cluster_size);



    qemu_free(s->refcount_table);

    qemu_free(s->refcount_block);

    close(fd);

    return 0;

}

static void scsi_read_data(SCSIRequest *req)

{

    SCSIDiskReq *r = DO_UPCAST(SCSIDiskReq, req, req);

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, r->req.dev);

    uint32_t n;



    if (r->sector_count == (uint32_t)-1) {

        DPRINTF("Read buf_len=%zd\n", r->iov.iov_len);

        r->sector_count = 0;

        scsi_req_data(&r->req, r->iov.iov_len);

        return;

    }

    DPRINTF("Read sector_count=%d\n", r->sector_count);

    if (r->sector_count == 0) {

        scsi_command_complete(r, GOOD, NO_SENSE);

        return;

    }



    /* No data transfer may already be in progress */

    assert(r->req.aiocb == NULL);



    n = r->sector_count;

    if (n > SCSI_DMA_BUF_SIZE / 512)

        n = SCSI_DMA_BUF_SIZE / 512;



    r->iov.iov_len = n * 512;

    qemu_iovec_init_external(&r->qiov, &r->iov, 1);

    r->req.aiocb = bdrv_aio_readv(s->bs, r->sector, &r->qiov, n,

                              scsi_read_complete, r);

    if (r->req.aiocb == NULL) {

        scsi_read_complete(r, -EIO);

    }

}

