static MemTxResult address_space_write_continue(AddressSpace *as, hwaddr addr,

                                                MemTxAttrs attrs,

                                                const uint8_t *buf,

                                                int len, hwaddr addr1,

                                                hwaddr l, MemoryRegion *mr)

{

    uint8_t *ptr;

    uint64_t val;

    MemTxResult result = MEMTX_OK;

    bool release_lock = false;



    for (;;) {

        if (!memory_access_is_direct(mr, true)) {

            release_lock |= prepare_mmio_access(mr);

            l = memory_access_size(mr, l, addr1);

            /* XXX: could force current_cpu to NULL to avoid

               potential bugs */

            switch (l) {

            case 8:

                /* 64 bit write access */

                val = ldq_p(buf);

                result |= memory_region_dispatch_write(mr, addr1, val, 8,

                                                       attrs);

                break;

            case 4:

                /* 32 bit write access */

                val = (uint32_t)ldl_p(buf);

                result |= memory_region_dispatch_write(mr, addr1, val, 4,

                                                       attrs);

                break;

            case 2:

                /* 16 bit write access */

                val = lduw_p(buf);

                result |= memory_region_dispatch_write(mr, addr1, val, 2,

                                                       attrs);

                break;

            case 1:

                /* 8 bit write access */

                val = ldub_p(buf);

                result |= memory_region_dispatch_write(mr, addr1, val, 1,

                                                       attrs);

                break;

            default:

                abort();

            }

        } else {

            /* RAM case */

            ptr = qemu_map_ram_ptr(mr->ram_block, addr1);

            memcpy(ptr, buf, l);

            invalidate_and_set_dirty(mr, addr1, l);

        }



        if (release_lock) {

            qemu_mutex_unlock_iothread();

            release_lock = false;

        }



        len -= l;

        buf += l;

        addr += l;



        if (!len) {

            break;

        }



        l = len;

        mr = address_space_translate(as, addr, &addr1, &l, true);

    }



    return result;

}

static int g729_parse(AVCodecParserContext *s1, AVCodecContext *avctx,

                     const uint8_t **poutbuf, int *poutbuf_size,

                     const uint8_t *buf, int buf_size)

{

    G729ParseContext *s = s1->priv_data;

    ParseContext *pc = &s->pc;

    int next;



    if (!s->block_size) {

        switch (avctx->codec_id) {

        case AV_CODEC_ID_G729:

            /* FIXME: replace this heuristic block_size with more precise estimate */

            s->block_size = (avctx->bit_rate < 8000) ? G729D_6K4_BLOCK_SIZE : G729_8K_BLOCK_SIZE;

            s->duration   = avctx->frame_size;

            break;

        default:

            *poutbuf      = buf;

            *poutbuf_size = buf_size;

            av_log(avctx, AV_LOG_ERROR, "Invalid codec_id\n");

            return buf_size;

        }

    }



    if (!s->remaining)

        s->remaining = s->block_size;

    if (s->remaining <= buf_size) {

        next = s->remaining;

        s->remaining = 0;

    } else {

        next = END_NOT_FOUND;

        s->remaining -= buf_size;

    }



    if (ff_combine_frame(pc, next, &buf, &buf_size) < 0 || !buf_size) {

        *poutbuf      = NULL;

        *poutbuf_size = 0;

        return buf_size;

    }



    s1->duration = s->duration;



    *poutbuf      = buf;

    *poutbuf_size = buf_size;

    return next;

}

static uint64_t timerblock_read(void *opaque, target_phys_addr_t addr,

                                unsigned size)

{

    timerblock *tb = (timerblock *)opaque;

    int64_t val;

    switch (addr) {

    case 0: /* Load */

        return tb->load;

    case 4: /* Counter.  */

        if (((tb->control & 1) == 0) || (tb->count == 0)) {

            return 0;

        }

        /* Slow and ugly, but hopefully won't happen too often.  */

        val = tb->tick - qemu_get_clock_ns(vm_clock);

        val /= timerblock_scale(tb);

        if (val < 0) {

            val = 0;

        }

        return val;

    case 8: /* Control.  */

        return tb->control;

    case 12: /* Interrupt status.  */

        return tb->status;

    default:

        return 0;

    }

}

static int decode_audio_block(AC3DecodeContext *s, int blk)

{

    int fbw_channels = s->fbw_channels;

    int channel_mode = s->channel_mode;

    int i, bnd, seg, ch;

    int different_transforms;

    int downmix_output;

    int cpl_in_use;

    GetBitContext *gbc = &s->gbc;

    uint8_t bit_alloc_stages[AC3_MAX_CHANNELS];



    memset(bit_alloc_stages, 0, AC3_MAX_CHANNELS);



    /* block switch flags */

    different_transforms = 0;

    if (s->block_switch_syntax) {

        for (ch = 1; ch <= fbw_channels; ch++) {

            s->block_switch[ch] = get_bits1(gbc);

            if(ch > 1 && s->block_switch[ch] != s->block_switch[1])

                different_transforms = 1;

        }

    }



    /* dithering flags */

    if (s->dither_flag_syntax) {

        for (ch = 1; ch <= fbw_channels; ch++) {

            s->dither_flag[ch] = get_bits1(gbc);

        }

    }



    /* dynamic range */

    i = !(s->channel_mode);

    do {

        if(get_bits1(gbc)) {

            s->dynamic_range[i] = ((dynamic_range_tab[get_bits(gbc, 8)]-1.0) *

                                  s->avctx->drc_scale)+1.0;

        } else if(blk == 0) {

            s->dynamic_range[i] = 1.0f;

        }

    } while(i--);



    /* spectral extension strategy */

    if (s->eac3 && (!blk || get_bits1(gbc))) {

        if (get_bits1(gbc)) {

            av_log_missing_feature(s->avctx, "Spectral extension", 1);

            return -1;

        }

        /* TODO: parse spectral extension strategy info */

    }



    /* TODO: spectral extension coordinates */



    /* coupling strategy */

    if (s->eac3 ? s->cpl_strategy_exists[blk] : get_bits1(gbc)) {

        memset(bit_alloc_stages, 3, AC3_MAX_CHANNELS);

        if (!s->eac3)

            s->cpl_in_use[blk] = get_bits1(gbc);

        if (s->cpl_in_use[blk]) {

            /* coupling in use */

            int cpl_start_subband, cpl_end_subband;



            if (channel_mode < AC3_CHMODE_STEREO) {

                av_log(s->avctx, AV_LOG_ERROR, "coupling not allowed in mono or dual-mono\n");

                return -1;

            }



            /* check for enhanced coupling */

            if (s->eac3 && get_bits1(gbc)) {

                /* TODO: parse enhanced coupling strategy info */

                av_log_missing_feature(s->avctx, "Enhanced coupling", 1);

                return -1;

            }



            /* determine which channels are coupled */

            if (s->eac3 && s->channel_mode == AC3_CHMODE_STEREO) {

                s->channel_in_cpl[1] = 1;

                s->channel_in_cpl[2] = 1;

            } else {

                for (ch = 1; ch <= fbw_channels; ch++)

                    s->channel_in_cpl[ch] = get_bits1(gbc);

            }



            /* phase flags in use */

            if (channel_mode == AC3_CHMODE_STEREO)

                s->phase_flags_in_use = get_bits1(gbc);



            /* coupling frequency range */

            /* TODO: modify coupling end freq if spectral extension is used */

            cpl_start_subband = get_bits(gbc, 4);

            cpl_end_subband   = get_bits(gbc, 4) + 3;

            s->num_cpl_subbands = cpl_end_subband - cpl_start_subband;

            if (s->num_cpl_subbands < 0) {

                av_log(s->avctx, AV_LOG_ERROR, "invalid coupling range (%d > %d)\n",

                       cpl_start_subband, cpl_end_subband);

                return -1;

            }

            s->start_freq[CPL_CH] = cpl_start_subband * 12 + 37;

            s->end_freq[CPL_CH]   = cpl_end_subband   * 12 + 37;



           decode_band_structure(gbc, blk, s->eac3, 0,

                                 cpl_start_subband, cpl_end_subband,

                                 ff_eac3_default_cpl_band_struct,

                                 s->cpl_band_struct, &s->num_cpl_subbands,

                                 &s->num_cpl_bands, NULL);

        } else {

            /* coupling not in use */

            for (ch = 1; ch <= fbw_channels; ch++) {

                s->channel_in_cpl[ch] = 0;

                s->first_cpl_coords[ch] = 1;

            }

            s->first_cpl_leak = s->eac3;

            s->phase_flags_in_use = 0;

        }

    } else if (!s->eac3) {

        if(!blk) {

            av_log(s->avctx, AV_LOG_ERROR, "new coupling strategy must be present in block 0\n");

            return -1;

        } else {

            s->cpl_in_use[blk] = s->cpl_in_use[blk-1];

        }

    }

    cpl_in_use = s->cpl_in_use[blk];



    /* coupling coordinates */

    if (cpl_in_use) {

        int cpl_coords_exist = 0;



        for (ch = 1; ch <= fbw_channels; ch++) {

            if (s->channel_in_cpl[ch]) {

                if ((s->eac3 && s->first_cpl_coords[ch]) || get_bits1(gbc)) {

                    int master_cpl_coord, cpl_coord_exp, cpl_coord_mant;

                    s->first_cpl_coords[ch] = 0;

                    cpl_coords_exist = 1;

                    master_cpl_coord = 3 * get_bits(gbc, 2);

                    for (bnd = 0; bnd < s->num_cpl_bands; bnd++) {

                        cpl_coord_exp = get_bits(gbc, 4);

                        cpl_coord_mant = get_bits(gbc, 4);

                        if (cpl_coord_exp == 15)

                            s->cpl_coords[ch][bnd] = cpl_coord_mant << 22;

                        else

                            s->cpl_coords[ch][bnd] = (cpl_coord_mant + 16) << 21;

                        s->cpl_coords[ch][bnd] >>= (cpl_coord_exp + master_cpl_coord);

                    }

                } else if (!blk) {

                    av_log(s->avctx, AV_LOG_ERROR, "new coupling coordinates must be present in block 0\n");

                    return -1;

                }

            } else {

                /* channel not in coupling */

                s->first_cpl_coords[ch] = 1;

            }

        }

        /* phase flags */

        if (channel_mode == AC3_CHMODE_STEREO && cpl_coords_exist) {

            for (bnd = 0; bnd < s->num_cpl_bands; bnd++) {

                s->phase_flags[bnd] = s->phase_flags_in_use? get_bits1(gbc) : 0;

            }

        }

    }



    /* stereo rematrixing strategy and band structure */

    if (channel_mode == AC3_CHMODE_STEREO) {

        if ((s->eac3 && !blk) || get_bits1(gbc)) {

            s->num_rematrixing_bands = 4;

            if(cpl_in_use && s->start_freq[CPL_CH] <= 61)

                s->num_rematrixing_bands -= 1 + (s->start_freq[CPL_CH] == 37);

            for(bnd=0; bnd<s->num_rematrixing_bands; bnd++)

                s->rematrixing_flags[bnd] = get_bits1(gbc);

        } else if (!blk) {

            av_log(s->avctx, AV_LOG_ERROR, "new rematrixing strategy must be present in block 0\n");

            return -1;

        }

    }



    /* exponent strategies for each channel */

    for (ch = !cpl_in_use; ch <= s->channels; ch++) {

        if (!s->eac3)

            s->exp_strategy[blk][ch] = get_bits(gbc, 2 - (ch == s->lfe_ch));

        if(s->exp_strategy[blk][ch] != EXP_REUSE)

            bit_alloc_stages[ch] = 3;

    }



    /* channel bandwidth */

    for (ch = 1; ch <= fbw_channels; ch++) {

        s->start_freq[ch] = 0;

        if (s->exp_strategy[blk][ch] != EXP_REUSE) {

            int group_size;

            int prev = s->end_freq[ch];

            if (s->channel_in_cpl[ch])

                s->end_freq[ch] = s->start_freq[CPL_CH];

            else {

                int bandwidth_code = get_bits(gbc, 6);

                if (bandwidth_code > 60) {

                    av_log(s->avctx, AV_LOG_ERROR, "bandwidth code = %d > 60\n", bandwidth_code);

                    return -1;

                }

                s->end_freq[ch] = bandwidth_code * 3 + 73;

            }

            group_size = 3 << (s->exp_strategy[blk][ch] - 1);

            s->num_exp_groups[ch] = (s->end_freq[ch]+group_size-4) / group_size;

            if(blk > 0 && s->end_freq[ch] != prev)

                memset(bit_alloc_stages, 3, AC3_MAX_CHANNELS);

        }

    }

    if (cpl_in_use && s->exp_strategy[blk][CPL_CH] != EXP_REUSE) {

        s->num_exp_groups[CPL_CH] = (s->end_freq[CPL_CH] - s->start_freq[CPL_CH]) /

                                    (3 << (s->exp_strategy[blk][CPL_CH] - 1));

    }



    /* decode exponents for each channel */

    for (ch = !cpl_in_use; ch <= s->channels; ch++) {

        if (s->exp_strategy[blk][ch] != EXP_REUSE) {

            s->dexps[ch][0] = get_bits(gbc, 4) << !ch;

            if (decode_exponents(gbc, s->exp_strategy[blk][ch],

                                 s->num_exp_groups[ch], s->dexps[ch][0],

                                 &s->dexps[ch][s->start_freq[ch]+!!ch])) {

                av_log(s->avctx, AV_LOG_ERROR, "exponent out-of-range\n");

                return -1;

            }

            if(ch != CPL_CH && ch != s->lfe_ch)

                skip_bits(gbc, 2); /* skip gainrng */

        }

    }



    /* bit allocation information */

    if (s->bit_allocation_syntax) {

        if (get_bits1(gbc)) {

            s->bit_alloc_params.slow_decay = ff_ac3_slow_decay_tab[get_bits(gbc, 2)] >> s->bit_alloc_params.sr_shift;

            s->bit_alloc_params.fast_decay = ff_ac3_fast_decay_tab[get_bits(gbc, 2)] >> s->bit_alloc_params.sr_shift;

            s->bit_alloc_params.slow_gain  = ff_ac3_slow_gain_tab[get_bits(gbc, 2)];

            s->bit_alloc_params.db_per_bit = ff_ac3_db_per_bit_tab[get_bits(gbc, 2)];

            s->bit_alloc_params.floor  = ff_ac3_floor_tab[get_bits(gbc, 3)];

            for(ch=!cpl_in_use; ch<=s->channels; ch++)

                bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

        } else if (!blk) {

            av_log(s->avctx, AV_LOG_ERROR, "new bit allocation info must be present in block 0\n");

            return -1;

        }

    }



    /* signal-to-noise ratio offsets and fast gains (signal-to-mask ratios) */

    if(!s->eac3 || !blk){

        if(s->snr_offset_strategy && get_bits1(gbc)) {

            int snr = 0;

            int csnr;

            csnr = (get_bits(gbc, 6) - 15) << 4;

            for (i = ch = !cpl_in_use; ch <= s->channels; ch++) {

                /* snr offset */

                if (ch == i || s->snr_offset_strategy == 2)

                    snr = (csnr + get_bits(gbc, 4)) << 2;

                /* run at least last bit allocation stage if snr offset changes */

                if(blk && s->snr_offset[ch] != snr) {

                    bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 1);

                }

                s->snr_offset[ch] = snr;



                /* fast gain (normal AC-3 only) */

                if (!s->eac3) {

                    int prev = s->fast_gain[ch];

                    s->fast_gain[ch] = ff_ac3_fast_gain_tab[get_bits(gbc, 3)];

                    /* run last 2 bit allocation stages if fast gain changes */

                    if(blk && prev != s->fast_gain[ch])

                        bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

                }

            }

        } else if (!s->eac3 && !blk) {

            av_log(s->avctx, AV_LOG_ERROR, "new snr offsets must be present in block 0\n");

            return -1;

        }

    }



    /* fast gain (E-AC-3 only) */

    if (s->fast_gain_syntax && get_bits1(gbc)) {

        for (ch = !cpl_in_use; ch <= s->channels; ch++) {

            int prev = s->fast_gain[ch];

            s->fast_gain[ch] = ff_ac3_fast_gain_tab[get_bits(gbc, 3)];

            /* run last 2 bit allocation stages if fast gain changes */

            if(blk && prev != s->fast_gain[ch])

                bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

        }

    } else if (s->eac3 && !blk) {

        for (ch = !cpl_in_use; ch <= s->channels; ch++)

            s->fast_gain[ch] = ff_ac3_fast_gain_tab[4];

    }



    /* E-AC-3 to AC-3 converter SNR offset */

    if (s->frame_type == EAC3_FRAME_TYPE_INDEPENDENT && get_bits1(gbc)) {

        skip_bits(gbc, 10); // skip converter snr offset

    }



    /* coupling leak information */

    if (cpl_in_use) {

        if (s->first_cpl_leak || get_bits1(gbc)) {

            int fl = get_bits(gbc, 3);

            int sl = get_bits(gbc, 3);

            /* run last 2 bit allocation stages for coupling channel if

               coupling leak changes */

            if(blk && (fl != s->bit_alloc_params.cpl_fast_leak ||

                       sl != s->bit_alloc_params.cpl_slow_leak)) {

                bit_alloc_stages[CPL_CH] = FFMAX(bit_alloc_stages[CPL_CH], 2);

            }

            s->bit_alloc_params.cpl_fast_leak = fl;

            s->bit_alloc_params.cpl_slow_leak = sl;

        } else if (!s->eac3 && !blk) {

            av_log(s->avctx, AV_LOG_ERROR, "new coupling leak info must be present in block 0\n");

            return -1;

        }

        s->first_cpl_leak = 0;

    }



    /* delta bit allocation information */

    if (s->dba_syntax && get_bits1(gbc)) {

        /* delta bit allocation exists (strategy) */

        for (ch = !cpl_in_use; ch <= fbw_channels; ch++) {

            s->dba_mode[ch] = get_bits(gbc, 2);

            if (s->dba_mode[ch] == DBA_RESERVED) {

                av_log(s->avctx, AV_LOG_ERROR, "delta bit allocation strategy reserved\n");

                return -1;

            }

            bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

        }

        /* channel delta offset, len and bit allocation */

        for (ch = !cpl_in_use; ch <= fbw_channels; ch++) {

            if (s->dba_mode[ch] == DBA_NEW) {

                s->dba_nsegs[ch] = get_bits(gbc, 3);

                for (seg = 0; seg <= s->dba_nsegs[ch]; seg++) {

                    s->dba_offsets[ch][seg] = get_bits(gbc, 5);

                    s->dba_lengths[ch][seg] = get_bits(gbc, 4);

                    s->dba_values[ch][seg] = get_bits(gbc, 3);

                }

                /* run last 2 bit allocation stages if new dba values */

                bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

            }

        }

    } else if(blk == 0) {

        for(ch=0; ch<=s->channels; ch++) {

            s->dba_mode[ch] = DBA_NONE;

        }

    }



    /* Bit allocation */

    for(ch=!cpl_in_use; ch<=s->channels; ch++) {

        if(bit_alloc_stages[ch] > 2) {

            /* Exponent mapping into PSD and PSD integration */

            ff_ac3_bit_alloc_calc_psd(s->dexps[ch],

                                      s->start_freq[ch], s->end_freq[ch],

                                      s->psd[ch], s->band_psd[ch]);

        }

        if(bit_alloc_stages[ch] > 1) {

            /* Compute excitation function, Compute masking curve, and

               Apply delta bit allocation */

            ff_ac3_bit_alloc_calc_mask(&s->bit_alloc_params, s->band_psd[ch],

                                       s->start_freq[ch], s->end_freq[ch],

                                       s->fast_gain[ch], (ch == s->lfe_ch),

                                       s->dba_mode[ch], s->dba_nsegs[ch],

                                       s->dba_offsets[ch], s->dba_lengths[ch],

                                       s->dba_values[ch], s->mask[ch]);

        }

        if(bit_alloc_stages[ch] > 0) {

            /* Compute bit allocation */

            const uint8_t *bap_tab = s->channel_uses_aht[ch] ?

                                     ff_eac3_hebap_tab : ff_ac3_bap_tab;

            ff_ac3_bit_alloc_calc_bap(s->mask[ch], s->psd[ch],

                                      s->start_freq[ch], s->end_freq[ch],

                                      s->snr_offset[ch],

                                      s->bit_alloc_params.floor,

                                      bap_tab, s->bap[ch]);

        }

    }



    /* unused dummy data */

    if (s->skip_syntax && get_bits1(gbc)) {

        int skipl = get_bits(gbc, 9);

        while(skipl--)

            skip_bits(gbc, 8);

    }



    /* unpack the transform coefficients

       this also uncouples channels if coupling is in use. */

    decode_transform_coeffs(s, blk);



    /* TODO: generate enhanced coupling coordinates and uncouple */



    /* TODO: apply spectral extension */



    /* recover coefficients if rematrixing is in use */

    if(s->channel_mode == AC3_CHMODE_STEREO)

        do_rematrixing(s);



    /* apply scaling to coefficients (headroom, dynrng) */

    for(ch=1; ch<=s->channels; ch++) {

        float gain = s->mul_bias / 4194304.0f;

        if(s->channel_mode == AC3_CHMODE_DUALMONO) {

            gain *= s->dynamic_range[ch-1];

        } else {

            gain *= s->dynamic_range[0];

        }

        s->dsp.int32_to_float_fmul_scalar(s->transform_coeffs[ch], s->fixed_coeffs[ch], gain, 256);

    }



    /* downmix and MDCT. order depends on whether block switching is used for

       any channel in this block. this is because coefficients for the long

       and short transforms cannot be mixed. */

    downmix_output = s->channels != s->out_channels &&

                     !((s->output_mode & AC3_OUTPUT_LFEON) &&

                     s->fbw_channels == s->out_channels);

    if(different_transforms) {

        /* the delay samples have already been downmixed, so we upmix the delay

           samples in order to reconstruct all channels before downmixing. */

        if(s->downmixed) {

            s->downmixed = 0;

            ac3_upmix_delay(s);

        }



        do_imdct(s, s->channels);



        if(downmix_output) {

            s->dsp.ac3_downmix(s->output, s->downmix_coeffs, s->out_channels, s->fbw_channels, 256);

        }

    } else {

        if(downmix_output) {

            s->dsp.ac3_downmix(s->transform_coeffs+1, s->downmix_coeffs, s->out_channels, s->fbw_channels, 256);

        }



        if(downmix_output && !s->downmixed) {

            s->downmixed = 1;

            s->dsp.ac3_downmix(s->delay, s->downmix_coeffs, s->out_channels, s->fbw_channels, 128);

        }



        do_imdct(s, s->out_channels);

    }



    return 0;

}

setup_return(CPUARMState *env, struct target_sigaction *ka,

	     abi_ulong *rc, abi_ulong frame_addr, int usig, abi_ulong rc_addr)

{

	abi_ulong handler = ka->_sa_handler;

	abi_ulong retcode;

	int thumb = handler & 1;

	uint32_t cpsr = cpsr_read(env);



	cpsr &= ~CPSR_IT;

	if (thumb) {

		cpsr |= CPSR_T;

	} else {

		cpsr &= ~CPSR_T;

	}



	if (ka->sa_flags & TARGET_SA_RESTORER) {

		retcode = ka->sa_restorer;

	} else {

		unsigned int idx = thumb;



		if (ka->sa_flags & TARGET_SA_SIGINFO)

			idx += 2;



        __put_user(retcodes[idx], rc);



		retcode = rc_addr + thumb;

	}



	env->regs[0] = usig;

	env->regs[13] = frame_addr;

	env->regs[14] = retcode;

	env->regs[15] = handler & (thumb ? ~1 : ~3);

        cpsr_write(env, cpsr, 0xffffffff, CPSRWriteByInstr);

}

static void tcg_exec_all(void)

{

    int r;



    /* Account partial waits to QEMU_CLOCK_VIRTUAL.  */

    qemu_clock_warp(QEMU_CLOCK_VIRTUAL);



    if (next_cpu == NULL) {

        next_cpu = first_cpu;

    }

    for (; next_cpu != NULL && !exit_request; next_cpu = CPU_NEXT(next_cpu)) {

        CPUState *cpu = next_cpu;



        qemu_clock_enable(QEMU_CLOCK_VIRTUAL,

                          (cpu->singlestep_enabled & SSTEP_NOTIMER) == 0);



        if (cpu_can_run(cpu)) {

            r = tcg_cpu_exec(cpu);

            if (r == EXCP_DEBUG) {

                cpu_handle_guest_debug(cpu);

                break;

            }

        } else if (cpu->stop || cpu->stopped) {

            break;

        }

    }



    /* Pairs with smp_wmb in qemu_cpu_kick.  */

    atomic_mb_set(&exit_request, 0);

}

static int get_keycode(const char *key)

{

    const KeyDef *p;

    char *endp;

    int ret;



    for(p = key_defs; p->name != NULL; p++) {

        if (!strcmp(key, p->name))

            return p->keycode;

    }

    if (strstart(key, "0x", NULL)) {

        ret = strtoul(key, &endp, 0);

        if (*endp == '\0' && ret >= 0x01 && ret <= 0xff)

            return ret;

    }

    return -1;

}

static void tricore_testboard_init(MachineState *machine, int board_id)

{

    TriCoreCPU *cpu;

    CPUTriCoreState *env;



    MemoryRegion *sysmem = get_system_memory();

    MemoryRegion *ext_cram = g_new(MemoryRegion, 1);

    MemoryRegion *ext_dram = g_new(MemoryRegion, 1);

    MemoryRegion *int_cram = g_new(MemoryRegion, 1);

    MemoryRegion *int_dram = g_new(MemoryRegion, 1);

    MemoryRegion *pcp_data = g_new(MemoryRegion, 1);

    MemoryRegion *pcp_text = g_new(MemoryRegion, 1);



    if (!machine->cpu_model) {

        machine->cpu_model = "tc1796";

    }

    cpu = cpu_tricore_init(machine->cpu_model);

    env = &cpu->env;

    if (!cpu) {

        error_report("Unable to find CPU definition");

        exit(1);

    }

    memory_region_init_ram(ext_cram, NULL, "powerlink_ext_c.ram", 2*1024*1024, &error_abort);

    vmstate_register_ram_global(ext_cram);

    memory_region_init_ram(ext_dram, NULL, "powerlink_ext_d.ram", 4*1024*1024, &error_abort);

    vmstate_register_ram_global(ext_dram);

    memory_region_init_ram(int_cram, NULL, "powerlink_int_c.ram", 48*1024, &error_abort);

    vmstate_register_ram_global(int_cram);

    memory_region_init_ram(int_dram, NULL, "powerlink_int_d.ram", 48*1024, &error_abort);

    vmstate_register_ram_global(int_dram);

    memory_region_init_ram(pcp_data, NULL, "powerlink_pcp_data.ram", 16*1024, &error_abort);

    vmstate_register_ram_global(pcp_data);

    memory_region_init_ram(pcp_text, NULL, "powerlink_pcp_text.ram", 32*1024, &error_abort);

    vmstate_register_ram_global(pcp_text);



    memory_region_add_subregion(sysmem, 0x80000000, ext_cram);

    memory_region_add_subregion(sysmem, 0xa1000000, ext_dram);

    memory_region_add_subregion(sysmem, 0xd4000000, int_cram);

    memory_region_add_subregion(sysmem, 0xd0000000, int_dram);

    memory_region_add_subregion(sysmem, 0xf0050000, pcp_data);

    memory_region_add_subregion(sysmem, 0xf0060000, pcp_text);



    tricoretb_binfo.ram_size = machine->ram_size;

    tricoretb_binfo.kernel_filename = machine->kernel_filename;



    if (machine->kernel_filename) {

        tricore_load_kernel(env);

    }

}

static uint64_t pxa2xx_cm_read(void *opaque, hwaddr addr,

                               unsigned size)

{

    PXA2xxState *s = (PXA2xxState *) opaque;



    switch (addr) {

    case CCCR:

    case CKEN:

    case OSCC:

        return s->cm_regs[addr >> 2];



    case CCSR:

        return s->cm_regs[CCCR >> 2] | (3 << 28);



    default:

        printf("%s: Bad register " REG_FMT "\n", __FUNCTION__, addr);

        break;

    }

    return 0;

}

static int mxf_write_header_metadata_sets(AVFormatContext *s)

{

    AVStream *st;

    MXFStreamContext *sc = NULL;

    int i;



    mxf_write_preface(s);

    mxf_write_identification(s);

    mxf_write_content_storage(s);



    for (i = 0; i < s->nb_streams; i++) {

        st = s->streams[i];

        sc = av_mallocz(sizeof(MXFStreamContext));

        if (!sc)

            return AVERROR(ENOMEM);

        st->priv_data = sc;

        // set pts information

        if (st->codec->codec_type == CODEC_TYPE_VIDEO)

            av_set_pts_info(st, 64, 1, st->codec->time_base.den);

        else if (st->codec->codec_type == CODEC_TYPE_AUDIO)

            av_set_pts_info(st, 64, 1, st->codec->sample_rate);

    }



    mxf_build_structural_metadata(s, MaterialPackage);

    mxf_build_structural_metadata(s, SourcePackage);

    return 0;

}

int av_opencl_buffer_write_image(cl_mem dst_cl_buf, size_t cl_buffer_size, int dst_cl_offset,

                                                    uint8_t **src_data, int *plane_size, int plane_num)

{

    int i, buffer_size = 0;

    uint8_t *temp;

    cl_int status;

    void *mapped;

    if ((unsigned int)plane_num > 8) {

        return AVERROR(EINVAL);

    }

    for (i = 0;i < plane_num;i++) {

        buffer_size += plane_size[i];

    }

    if (buffer_size > cl_buffer_size) {

        av_log(&openclutils, AV_LOG_ERROR, "Cannot write image to OpenCL buffer: buffer too small\n");

        return AVERROR(EINVAL);

    }

    mapped = clEnqueueMapBuffer(gpu_env.command_queue, dst_cl_buf,

                                      CL_TRUE,CL_MAP_WRITE, 0, buffer_size + dst_cl_offset,

                                      0, NULL, NULL, &status);

    if (status != CL_SUCCESS) {

        av_log(&openclutils, AV_LOG_ERROR, "Could not map OpenCL buffer: %s\n", opencl_errstr(status));

        return AVERROR_EXTERNAL;

    }

    temp = mapped;

    temp += dst_cl_offset;

    for (i = 0; i < plane_num; i++) {

        memcpy(temp, src_data[i], plane_size[i]);

        temp += plane_size[i];

    }

    status = clEnqueueUnmapMemObject(gpu_env.command_queue, dst_cl_buf, mapped, 0, NULL, NULL);

    if (status != CL_SUCCESS) {

        av_log(&openclutils, AV_LOG_ERROR, "Could not unmap OpenCL buffer: %s\n", opencl_errstr(status));

        return AVERROR_EXTERNAL;

    }

    return 0;

}

int ff_get_wav_header(AVIOContext *pb, AVCodecContext *codec, int size)

{

    int id;



    id = avio_rl16(pb);

    codec->codec_type = AVMEDIA_TYPE_AUDIO;

    codec->channels = avio_rl16(pb);

    codec->sample_rate = avio_rl32(pb);

    codec->bit_rate = avio_rl32(pb) * 8;

    codec->block_align = avio_rl16(pb);

    if (size == 14) {  /* We're dealing with plain vanilla WAVEFORMAT */

        codec->bits_per_coded_sample = 8;

    }else

        codec->bits_per_coded_sample = avio_rl16(pb);

    if (id == 0xFFFE) {

        codec->codec_tag = 0;

    } else {

        codec->codec_tag = id;

        codec->codec_id = ff_wav_codec_get_id(id, codec->bits_per_coded_sample);

    }

    if (size >= 18) {  /* We're obviously dealing with WAVEFORMATEX */

        int cbSize = avio_rl16(pb); /* cbSize */

        size -= 18;

        cbSize = FFMIN(size, cbSize);

        if (cbSize >= 22 && id == 0xfffe) { /* WAVEFORMATEXTENSIBLE */

            ff_asf_guid subformat;

            codec->bits_per_coded_sample = avio_rl16(pb);

            codec->channel_layout = avio_rl32(pb); /* dwChannelMask */

            ff_get_guid(pb, &subformat);

            if (!memcmp(subformat + 4, (const uint8_t[]){FF_MEDIASUBTYPE_BASE_GUID}, 12)) {

                codec->codec_tag = AV_RL32(subformat);

                codec->codec_id = ff_wav_codec_get_id(codec->codec_tag, codec->bits_per_coded_sample);

            } else {

                codec->codec_id = ff_codec_guid_get_id(ff_codec_wav_guids, subformat);

                if (!codec->codec_id)

                    av_log(codec, AV_LOG_WARNING, "unknown subformat:"FF_PRI_GUID"\n", FF_ARG_GUID(subformat));

            }

            cbSize -= 22;

            size -= 22;

        }

        codec->extradata_size = cbSize;

        if (cbSize > 0) {

            av_free(codec->extradata);

            codec->extradata = av_mallocz(codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

            if (!codec->extradata)

                return AVERROR(ENOMEM);

            avio_read(pb, codec->extradata, codec->extradata_size);

            size -= cbSize;

        }



        /* It is possible for the chunk to contain garbage at the end */

        if (size > 0)

            avio_skip(pb, size);

    }

    if (codec->codec_id == CODEC_ID_AAC_LATM) {

        /* channels and sample_rate values are those prior to applying SBR and/or PS */

        codec->channels    = 0;

        codec->sample_rate = 0;

    }

    /* override bits_per_coded_sample for G.726 */

    if (codec->codec_id == CODEC_ID_ADPCM_G726)

        codec->bits_per_coded_sample = codec->bit_rate / codec->sample_rate;



    return 0;

}

static int r3d_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    R3DContext *r3d = s->priv_data;

    Atom atom;

    int err = 0;



    while (!err) {

        if (read_atom(s, &atom) < 0) {

            err = -1;

            break;

        }

        switch (atom.tag) {

        case MKTAG('R','E','D','V'):

            if (s->streams[0]->discard == AVDISCARD_ALL)

                goto skip;

            if (!(err = r3d_read_redv(s, pkt, &atom)))

                return 0;

            break;

        case MKTAG('R','E','D','A'):

            if (!r3d->audio_channels)

                return -1;

            if (s->streams[1]->discard == AVDISCARD_ALL)

                goto skip;

            if (!(err = r3d_read_reda(s, pkt, &atom)))

                return 0;

            break;

        default:

        skip:

            avio_skip(s->pb, atom.size-8);

        }

    }

    return err;

}

