void cpu_ppc_reset (void *opaque)

{

    CPUPPCState *env;

    target_ulong msr;



    env = opaque;

    msr = (target_ulong)0;

#if defined(TARGET_PPC64)

    msr |= (target_ulong)0 << MSR_HV; /* Should be 1... */

#endif

    msr |= (target_ulong)0 << MSR_AP; /* TO BE CHECKED */

    msr |= (target_ulong)0 << MSR_SA; /* TO BE CHECKED */

    msr |= (target_ulong)1 << MSR_EP;

#if defined (DO_SINGLE_STEP) && 0

    /* Single step trace mode */

    msr |= (target_ulong)1 << MSR_SE;

    msr |= (target_ulong)1 << MSR_BE;

#endif

#if defined(CONFIG_USER_ONLY)

    msr |= (target_ulong)1 << MSR_FP; /* Allow floating point usage */

    msr |= (target_ulong)1 << MSR_PR;

#else

    env->nip = env->hreset_vector | env->excp_prefix;

    if (env->mmu_model != POWERPC_MMU_REAL_4xx)

        ppc_tlb_invalidate_all(env);

#endif

    env->msr = msr;

    hreg_compute_hflags(env);

    env->reserve = -1;

    /* Be sure no exception or interrupt is pending */

    env->pending_interrupts = 0;

    env->exception_index = POWERPC_EXCP_NONE;

    env->error_code = 0;

    /* Flush all TLBs */

    tlb_flush(env, 1);

}

static int mov_create_timecode_track(AVFormatContext *s, int index, int src_index, const char *tcstr)

{

    int ret;

    MOVMuxContext *mov  = s->priv_data;

    MOVTrack *track     = &mov->tracks[index];

    AVStream *src_st    = s->streams[src_index];

    AVTimecode tc;

    AVPacket pkt    = {.stream_index = index, .flags = AV_PKT_FLAG_KEY, .size = 4};

    AVRational rate = find_fps(s, src_st);



    /* compute the frame number */

    ret = av_timecode_init_from_string(&tc, rate, tcstr, s);

    if (ret < 0)

        return ret;



    /* tmcd track based on video stream */

    track->mode      = mov->mode;

    track->tag       = MKTAG('t','m','c','d');

    track->src_track = src_index;

    track->timescale = mov->tracks[src_index].timescale;

    if (tc.flags & AV_TIMECODE_FLAG_DROPFRAME)

        track->timecode_flags |= MOV_TIMECODE_FLAG_DROPFRAME;



    /* set st to src_st for metadata access*/

    track->st = src_st;



    /* encode context: tmcd data stream */

    track->enc = avcodec_alloc_context3(NULL);



    track->enc->codec_type = AVMEDIA_TYPE_DATA;

    track->enc->codec_tag  = track->tag;

    track->enc->time_base  = av_inv_q(rate);



    /* the tmcd track just contains one packet with the frame number */

    pkt.data = av_malloc(pkt.size);



    AV_WB32(pkt.data, tc.start);

    ret = ff_mov_write_packet(s, &pkt);

    av_free(pkt.data);

    return ret;

}

static int rv40_decode_intra_types(RV34DecContext *r, GetBitContext *gb, int8_t *dst)

{

    MpegEncContext *s = &r->s;

    int i, j, k, v;

    int A, B, C;

    int pattern;

    int8_t *ptr;



    for(i = 0; i < 4; i++, dst += r->intra_types_stride){

        if(!i && s->first_slice_line){

            pattern = get_vlc2(gb, aic_top_vlc.table, AIC_TOP_BITS, 1);

            dst[0] = (pattern >> 2) & 2;

            dst[1] = (pattern >> 1) & 2;

            dst[2] =  pattern       & 2;

            dst[3] = (pattern << 1) & 2;

            continue;

        }

        ptr = dst;

        for(j = 0; j < 4; j++){

            /* Coefficients are read using VLC chosen by the prediction pattern

             * The first one (used for retrieving a pair of coefficients) is

             * constructed from the top, top right and left coefficients

             * The second one (used for retrieving only one coefficient) is

             * top + 10 * left.

             */

            A = ptr[-r->intra_types_stride + 1]; // it won't be used for the last coefficient in a row

            B = ptr[-r->intra_types_stride];

            C = ptr[-1];

            pattern = A + (B << 4) + (C << 8);

            for(k = 0; k < MODE2_PATTERNS_NUM; k++)

                if(pattern == rv40_aic_table_index[k])

                    break;

            if(j < 3 && k < MODE2_PATTERNS_NUM){ //pattern is found, decoding 2 coefficients

                v = get_vlc2(gb, aic_mode2_vlc[k].table, AIC_MODE2_BITS, 2);

                *ptr++ = v/9;

                *ptr++ = v%9;

                j++;

            }else{

                if(B != -1 && C != -1)

                    v = get_vlc2(gb, aic_mode1_vlc[B + C*10].table, AIC_MODE1_BITS, 1);

                else{ // tricky decoding

                    v = 0;

                    switch(C){

                    case -1: // code 0 -> 1, 1 -> 0

                        if(B < 2)

                            v = get_bits1(gb) ^ 1;

                        break;

                    case  0:

                    case  2: // code 0 -> 2, 1 -> 0

                        v = (get_bits1(gb) ^ 1) << 1;

                        break;

                    }

                }

                *ptr++ = v;

            }

        }

    }

    return 0;

}

void virtio_queue_set_align(VirtIODevice *vdev, int n, int align)

{

    BusState *qbus = qdev_get_parent_bus(DEVICE(vdev));

    VirtioBusClass *k = VIRTIO_BUS_GET_CLASS(qbus);



    /* virtio-1 compliant devices cannot change the alignment */

    if (virtio_vdev_has_feature(vdev, VIRTIO_F_VERSION_1)) {

        error_report("tried to modify queue alignment for virtio-1 device");

        return;

    }

    /* Check that the transport told us it was going to do this

     * (so a buggy transport will immediately assert rather than

     * silently failing to migrate this state)

     */

    assert(k->has_variable_vring_alignment);



    vdev->vq[n].vring.align = align;

    virtio_queue_update_rings(vdev, n);

}

static int update_wrap_reference(AVFormatContext *s, AVStream *st, int stream_index, AVPacket *pkt)

{

    int64_t ref = pkt->dts;



    if (ref == AV_NOPTS_VALUE)

        ref = pkt->pts;

    if (ref == AV_NOPTS_VALUE)

        return 0;

    ref &= (1LL<<st->pts_wrap_bits)-1;



    if (s->correct_ts_overflow && st->pts_wrap_bits < 63 &&

        st->pts_wrap_reference == AV_NOPTS_VALUE) {

        int i;



        // reference time stamp should be 60 s before first time stamp

        int64_t pts_wrap_reference = ref - av_rescale(60, st->time_base.den, st->time_base.num);

        // if first time stamp is not more than 1/8 and 60s before the wrap point, subtract rather than add wrap offset

        int pts_wrap_behavior = (ref < (1LL<<st->pts_wrap_bits) - (1LL<<st->pts_wrap_bits-3)) ||

            (ref < (1LL<<st->pts_wrap_bits) - av_rescale(60, st->time_base.den, st->time_base.num)) ?

            AV_PTS_WRAP_ADD_OFFSET : AV_PTS_WRAP_SUB_OFFSET;



        AVProgram *first_program = av_find_program_from_stream(s, NULL, stream_index);



        if (!first_program) {

            int default_stream_index = av_find_default_stream_index(s);

            if (s->streams[default_stream_index]->pts_wrap_reference == AV_NOPTS_VALUE) {

                for (i=0; i<s->nb_streams; i++) {

                    s->streams[i]->pts_wrap_reference = pts_wrap_reference;

                    s->streams[i]->pts_wrap_behavior = pts_wrap_behavior;

                }

            }

            else {

                st->pts_wrap_reference = s->streams[default_stream_index]->pts_wrap_reference;

                st->pts_wrap_behavior = s->streams[default_stream_index]->pts_wrap_behavior;

            }

        }

        else {

            AVProgram *program = first_program;

            while (program) {

                if (program->pts_wrap_reference != AV_NOPTS_VALUE) {

                    pts_wrap_reference = program->pts_wrap_reference;

                    pts_wrap_behavior = program->pts_wrap_behavior;

                    break;

                }

                program = av_find_program_from_stream(s, program, stream_index);

            }



            // update every program with differing pts_wrap_reference

            program = first_program;

            while(program) {

                if (program->pts_wrap_reference != pts_wrap_reference) {

                    for (i=0; i<program->nb_stream_indexes; i++) {

                        s->streams[program->stream_index[i]]->pts_wrap_reference = pts_wrap_reference;

                        s->streams[program->stream_index[i]]->pts_wrap_behavior = pts_wrap_behavior;

                    }



                    program->pts_wrap_reference = pts_wrap_reference;

                    program->pts_wrap_behavior = pts_wrap_behavior;

                }

                program = av_find_program_from_stream(s, program, stream_index);

            }

        }

        return 1;

    }

    return 0;

}

static void action_command(EEPRO100State *s)

{

    for (;;) {

        bool bit_el;

        bool bit_s;

        bool bit_i;

        bool bit_nc;

        uint16_t ok_status = STATUS_OK;

        s->cb_address = s->cu_base + s->cu_offset;

        read_cb(s);

        bit_el = ((s->tx.command & COMMAND_EL) != 0);

        bit_s = ((s->tx.command & COMMAND_S) != 0);

        bit_i = ((s->tx.command & COMMAND_I) != 0);

        bit_nc = ((s->tx.command & COMMAND_NC) != 0);

#if 0

        bool bit_sf = ((s->tx.command & COMMAND_SF) != 0);

#endif

        s->cu_offset = s->tx.link;

        TRACE(OTHER,

              logout("val=(cu start), status=0x%04x, command=0x%04x, link=0x%08x\n",

                     s->tx.status, s->tx.command, s->tx.link));

        switch (s->tx.command & COMMAND_CMD) {

        case CmdNOp:

            /* Do nothing. */

            break;

        case CmdIASetup:

            cpu_physical_memory_read(s->cb_address + 8, &s->conf.macaddr.a[0], 6);

            TRACE(OTHER, logout("macaddr: %s\n", nic_dump(&s->conf.macaddr.a[0], 6)));

            break;

        case CmdConfigure:

            cpu_physical_memory_read(s->cb_address + 8, &s->configuration[0],

                                     sizeof(s->configuration));

            TRACE(OTHER, logout("configuration: %s\n", nic_dump(&s->configuration[0], 16)));

            break;

        case CmdMulticastList:

            set_multicast_list(s);

            break;

        case CmdTx:

            if (bit_nc) {

                missing("CmdTx: NC = 0");

                ok_status = 0;

                break;

            }

            tx_command(s);

            break;

        case CmdTDR:

            TRACE(OTHER, logout("load microcode\n"));

            /* Starting with offset 8, the command contains

             * 64 dwords microcode which we just ignore here. */

            break;

        case CmdDiagnose:

            TRACE(OTHER, logout("diagnose\n"));

            /* Make sure error flag is not set. */

            s->tx.status = 0;

            break;

        default:

            missing("undefined command");

            ok_status = 0;

            break;

        }

        /* Write new status. */

        stw_phys(s->cb_address, s->tx.status | ok_status | STATUS_C);

        if (bit_i) {

            /* CU completed action. */

            eepro100_cx_interrupt(s);

        }

        if (bit_el) {

            /* CU becomes idle. Terminate command loop. */

            set_cu_state(s, cu_idle);

            eepro100_cna_interrupt(s);

            break;

        } else if (bit_s) {

            /* CU becomes suspended. Terminate command loop. */

            set_cu_state(s, cu_suspended);

            eepro100_cna_interrupt(s);

            break;

        } else {

            /* More entries in list. */

            TRACE(OTHER, logout("CU list with at least one more entry\n"));

        }

    }

    TRACE(OTHER, logout("CU list empty\n"));

    /* List is empty. Now CU is idle or suspended. */

}

