static av_cold int mp3lame_encode_init(AVCodecContext *avctx)

{

    LAMEContext *s = avctx->priv_data;

    int ret;



    s->avctx = avctx;



    /* initialize LAME and get defaults */

    if (!(s->gfp = lame_init()))

        return AVERROR(ENOMEM);



    lame_set_num_channels(s->gfp, avctx->channels);

    lame_set_mode(s->gfp, avctx->channels > 1 ? s->joint_stereo ? JOINT_STEREO : STEREO : MONO);



    /* sample rate */

    lame_set_in_samplerate (s->gfp, avctx->sample_rate);

    lame_set_out_samplerate(s->gfp, avctx->sample_rate);



    /* algorithmic quality */

    if (avctx->compression_level == FF_COMPRESSION_DEFAULT)

        lame_set_quality(s->gfp, 5);

    else

        lame_set_quality(s->gfp, avctx->compression_level);



    /* rate control */

    if (avctx->flags & CODEC_FLAG_QSCALE) { // VBR

        lame_set_VBR(s->gfp, vbr_default);

        lame_set_VBR_quality(s->gfp, avctx->global_quality / (float)FF_QP2LAMBDA);

    } else {

        if (avctx->bit_rate) {

            if (s->abr) {                   // ABR

                lame_set_VBR(s->gfp, vbr_abr);

                lame_set_VBR_mean_bitrate_kbps(s->gfp, avctx->bit_rate / 1000);

            } else                          // CBR

                lame_set_brate(s->gfp, avctx->bit_rate / 1000);

        }

    }



    /* do not get a Xing VBR header frame from LAME */

    lame_set_bWriteVbrTag(s->gfp,0);



    /* bit reservoir usage */

    lame_set_disable_reservoir(s->gfp, !s->reservoir);



    /* set specified parameters */

    if (lame_init_params(s->gfp) < 0) {

        ret = -1;

        goto error;

    }



    /* get encoder delay */

    avctx->delay = lame_get_encoder_delay(s->gfp) + 528 + 1;

    ff_af_queue_init(avctx, &s->afq);



    avctx->frame_size  = lame_get_framesize(s->gfp);



    /* allocate float sample buffers */

    if (avctx->sample_fmt == AV_SAMPLE_FMT_FLTP) {

        int ch;

        for (ch = 0; ch < avctx->channels; ch++) {

            s->samples_flt[ch] = av_malloc(avctx->frame_size *

                                           sizeof(*s->samples_flt[ch]));

            if (!s->samples_flt[ch]) {

                ret = AVERROR(ENOMEM);

                goto error;

            }

        }

    }



    ret = realloc_buffer(s);

    if (ret < 0)

        goto error;



    avpriv_float_dsp_init(&s->fdsp, avctx->flags & CODEC_FLAG_BITEXACT);



    return 0;

error:

    mp3lame_encode_close(avctx);

    return ret;

}

static int scsi_write_data(SCSIDevice *d, uint32_t tag)

{

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, d);

    SCSIDiskReq *r;



    DPRINTF("Write data tag=0x%x\n", tag);

    r = scsi_find_request(s, tag);

    if (!r) {

        BADF("Bad write tag 0x%x\n", tag);

        scsi_command_complete(r, CHECK_CONDITION, HARDWARE_ERROR);

        return 1;

    }



    /* No data transfer may already be in progress */

    assert(r->req.aiocb == NULL);



    scsi_write_request(r);



    return 0;

}

void replay_account_executed_instructions(void)

{

    if (replay_mode == REPLAY_MODE_PLAY) {

        replay_mutex_lock();

        if (replay_state.instructions_count > 0) {

            int count = (int)(replay_get_current_step()

                              - replay_state.current_step);

            replay_state.instructions_count -= count;

            replay_state.current_step += count;

            if (replay_state.instructions_count == 0) {

                assert(replay_data_kind == EVENT_INSTRUCTION);

                replay_finish_event();

                /* Wake up iothread. This is required because

                   timers will not expire until clock counters

                   will be read from the log. */

                qemu_notify_event();

            }

        }

        replay_mutex_unlock();

    }

}

void qemu_co_rwlock_unlock(CoRwlock *lock)

{

    assert(qemu_in_coroutine());

    if (lock->writer) {

        lock->writer = false;

        while (!qemu_co_queue_empty(&lock->queue)) {

            /*

             * Wakeup every body. This will include some

             * writers too.

             */

            qemu_co_queue_next(&lock->queue);

        }

    } else {

        lock->reader--;

        assert(lock->reader >= 0);

        /* Wakeup only one waiting writer */

        if (!lock->reader) {

            qemu_co_queue_next(&lock->queue);

        }

    }

}

