int pcnet_common_init(DeviceState *dev, PCNetState *s, NetClientInfo *info)

{

    int i;

    uint16_t checksum;



    s->poll_timer = timer_new_ns(QEMU_CLOCK_VIRTUAL, pcnet_poll_timer, s);



    qemu_macaddr_default_if_unset(&s->conf.macaddr);

    s->nic = qemu_new_nic(info, &s->conf, object_get_typename(OBJECT(dev)), dev->id, s);

    qemu_format_nic_info_str(qemu_get_queue(s->nic), s->conf.macaddr.a);



    /* Initialize the PROM */



    /*

      Datasheet: http://pdfdata.datasheetsite.com/web/24528/AM79C970A.pdf

      page 95

    */

    memcpy(s->prom, s->conf.macaddr.a, 6);

    /* Reserved Location: must be 00h */

    s->prom[6] = s->prom[7] = 0x00;

    /* Reserved Location: must be 00h */

    s->prom[8] = 0x00;

    /* Hardware ID: must be 11h if compatibility to AMD drivers is desired */

    s->prom[9] = 0x11;

    /* User programmable space, init with 0 */

    s->prom[10] = s->prom[11] = 0x00;

    /* LSByte of two-byte checksum, which is the sum of bytes 00h-0Bh

       and bytes 0Eh and 0Fh, must therefore be initialized with 0! */

    s->prom[12] = s->prom[13] = 0x00;

    /* Must be ASCII W (57h) if compatibility to AMD

       driver software is desired */

    s->prom[14] = s->prom[15] = 0x57;



    for (i = 0, checksum = 0; i < 16; i++) {

        checksum += s->prom[i];

    }

    *(uint16_t *)&s->prom[12] = cpu_to_le16(checksum);



    s->lnkst = 0x40; /* initial link state: up */



    return 0;

}

static int query_memdev(Object *obj, void *opaque)

{

    MemdevList **list = opaque;

    Error *err = NULL;



    if (object_dynamic_cast(obj, TYPE_MEMORY_BACKEND)) {

        MemdevList *m = g_malloc0(sizeof(*m));



        m->value = g_malloc0(sizeof(*m->value));



        m->value->size = object_property_get_int(obj, "size",

                                                 &err);

        if (err) {

            goto error;

        }



        m->value->merge = object_property_get_bool(obj, "merge",

                                                   &err);

        if (err) {

            goto error;

        }



        m->value->dump = object_property_get_bool(obj, "dump",

                                                  &err);

        if (err) {

            goto error;

        }



        m->value->prealloc = object_property_get_bool(obj,

                                                      "prealloc", &err);

        if (err) {

            goto error;

        }



        m->value->policy = object_property_get_enum(obj,

                                                    "policy",

                                                    HostMemPolicy_lookup,

                                                    &err);

        if (err) {

            goto error;

        }



        object_property_get_uint16List(obj, "host-nodes",

                                       &m->value->host_nodes, &err);

        if (err) {

            goto error;

        }



        m->next = *list;

        *list = m;

    }



    return 0;

error:

    return -1;

}

static int decode_iccp_chunk(PNGDecContext *s, int length, AVFrame *f)

{

    int ret, cnt = 0;

    uint8_t *data, profile_name[82];

    AVBPrint bp;

    AVFrameSideData *sd;



    while ((profile_name[cnt++] = bytestream2_get_byte(&s->gb)) && cnt < 81);

    if (cnt > 80) {

        av_log(s->avctx, AV_LOG_ERROR, "iCCP with invalid name!\n");

        return AVERROR_INVALIDDATA;

    }



    length = FFMAX(length - cnt, 0);



    if (bytestream2_get_byte(&s->gb) != 0) {

        av_log(s->avctx, AV_LOG_ERROR, "iCCP with invalid compression!\n");

        return AVERROR_INVALIDDATA;

    }



    length = FFMAX(length - 1, 0);



    if ((ret = decode_zbuf(&bp, s->gb.buffer, s->gb.buffer + length)) < 0)

        return ret;



    av_bprint_finalize(&bp, (char **)&data);





    sd = av_frame_new_side_data(f, AV_FRAME_DATA_ICC_PROFILE, bp.len);

    if (!sd) {

        av_free(data);


    }



    av_dict_set(&sd->metadata, "name", profile_name, 0);

    memcpy(sd->data, data, bp.len);

    av_free(data);



    /* ICC compressed data and CRC */

    bytestream2_skip(&s->gb, length + 4);



    return 0;

}

uint64_t helper_fres(CPUPPCState *env, uint64_t arg)

{

    CPU_DoubleU farg;

    float32 f32;



    farg.ll = arg;



    if (unlikely(float64_is_signaling_nan(farg.d))) {

        /* sNaN reciprocal */

        fload_invalid_op_excp(env, POWERPC_EXCP_FP_VXSNAN);

    }

    farg.d = float64_div(float64_one, farg.d, &env->fp_status);

    f32 = float64_to_float32(farg.d, &env->fp_status);

    farg.d = float32_to_float64(f32, &env->fp_status);



    return farg.ll;

}

