static void xhci_port_write(void *ptr, hwaddr reg,

                            uint64_t val, unsigned size)

{

    XHCIPort *port = ptr;

    uint32_t portsc, notify;



    trace_usb_xhci_port_write(port->portnr, reg, val);



    switch (reg) {

    case 0x00: /* PORTSC */

        /* write-1-to-start bits */

        if (val & PORTSC_PR) {

            xhci_port_reset(port);

            break;

        }



        portsc = port->portsc;

        notify = 0;

        /* write-1-to-clear bits*/

        portsc &= ~(val & (PORTSC_CSC|PORTSC_PEC|PORTSC_WRC|PORTSC_OCC|

                           PORTSC_PRC|PORTSC_PLC|PORTSC_CEC));

        if (val & PORTSC_LWS) {

            /* overwrite PLS only when LWS=1 */

            uint32_t old_pls = get_field(port->portsc, PORTSC_PLS);

            uint32_t new_pls = get_field(val, PORTSC_PLS);

            switch (new_pls) {

            case PLS_U0:

                if (old_pls != PLS_U0) {

                    set_field(&portsc, new_pls, PORTSC_PLS);

                    trace_usb_xhci_port_link(port->portnr, new_pls);

                    notify = PORTSC_PLC;

                }

                break;

            case PLS_U3:

                if (old_pls < PLS_U3) {

                    set_field(&portsc, new_pls, PORTSC_PLS);

                    trace_usb_xhci_port_link(port->portnr, new_pls);

                }

                break;

            case PLS_RESUME:

                /* windows does this for some reason, don't spam stderr */

                break;

            default:

                fprintf(stderr, "%s: ignore pls write (old %d, new %d)\n",

                        __func__, old_pls, new_pls);

                break;

            }

        }

        /* read/write bits */

        portsc &= ~(PORTSC_PP|PORTSC_WCE|PORTSC_WDE|PORTSC_WOE);

        portsc |= (val & (PORTSC_PP|PORTSC_WCE|PORTSC_WDE|PORTSC_WOE));

        port->portsc = portsc;

        if (notify) {

            xhci_port_notify(port, notify);

        }

        break;

    case 0x04: /* PORTPMSC */

    case 0x08: /* PORTLI */

    default:

        trace_usb_xhci_unimplemented("port write", reg);

    }

}

static int pci_unin_map_irq(PCIDevice *pci_dev, int irq_num)

{

    int retval;

    int devfn = pci_dev->devfn & 0x00FFFFFF;



    retval = (((devfn >> 11) & 0x1F) + irq_num) & 3;



    return retval;

}

static int check_refcounts_l2(BlockDriverState *bs, BdrvCheckResult *res,

                              void **refcount_table,

                              int64_t *refcount_table_size, int64_t l2_offset,

                              int flags)

{

    BDRVQcow2State *s = bs->opaque;

    uint64_t *l2_table, l2_entry;

    uint64_t next_contiguous_offset = 0;

    int i, l2_size, nb_csectors, ret;



    /* Read L2 table from disk */

    l2_size = s->l2_size * sizeof(uint64_t);

    l2_table = g_malloc(l2_size);



    ret = bdrv_pread(bs->file, l2_offset, l2_table, l2_size);

    if (ret < 0) {

        fprintf(stderr, "ERROR: I/O error in check_refcounts_l2\n");

        res->check_errors++;

        goto fail;

    }



    /* Do the actual checks */

    for(i = 0; i < s->l2_size; i++) {

        l2_entry = be64_to_cpu(l2_table[i]);



        switch (qcow2_get_cluster_type(l2_entry)) {

        case QCOW2_CLUSTER_COMPRESSED:

            /* Compressed clusters don't have QCOW_OFLAG_COPIED */

            if (l2_entry & QCOW_OFLAG_COPIED) {

                fprintf(stderr, "ERROR: cluster %" PRId64 ": "

                    "copied flag must never be set for compressed "

                    "clusters\n", l2_entry >> s->cluster_bits);

                l2_entry &= ~QCOW_OFLAG_COPIED;

                res->corruptions++;

            }



            /* Mark cluster as used */

            nb_csectors = ((l2_entry >> s->csize_shift) &

                           s->csize_mask) + 1;

            l2_entry &= s->cluster_offset_mask;

            ret = inc_refcounts(bs, res, refcount_table, refcount_table_size,

                                l2_entry & ~511, nb_csectors * 512);

            if (ret < 0) {

                goto fail;

            }



            if (flags & CHECK_FRAG_INFO) {

                res->bfi.allocated_clusters++;

                res->bfi.compressed_clusters++;



                /* Compressed clusters are fragmented by nature.  Since they

                 * take up sub-sector space but we only have sector granularity

                 * I/O we need to re-read the same sectors even for adjacent

                 * compressed clusters.

                 */

                res->bfi.fragmented_clusters++;

            }

            break;



        case QCOW2_CLUSTER_ZERO:

            if ((l2_entry & L2E_OFFSET_MASK) == 0) {

                break;

            }

            /* fall through */



        case QCOW2_CLUSTER_NORMAL:

        {

            uint64_t offset = l2_entry & L2E_OFFSET_MASK;



            if (flags & CHECK_FRAG_INFO) {

                res->bfi.allocated_clusters++;

                if (next_contiguous_offset &&

                    offset != next_contiguous_offset) {

                    res->bfi.fragmented_clusters++;

                }

                next_contiguous_offset = offset + s->cluster_size;

            }



            /* Mark cluster as used */

            ret = inc_refcounts(bs, res, refcount_table, refcount_table_size,

                                offset, s->cluster_size);

            if (ret < 0) {

                goto fail;

            }



            /* Correct offsets are cluster aligned */

            if (offset_into_cluster(s, offset)) {

                fprintf(stderr, "ERROR offset=%" PRIx64 ": Cluster is not "

                    "properly aligned; L2 entry corrupted.\n", offset);

                res->corruptions++;

            }

            break;

        }



        case QCOW2_CLUSTER_UNALLOCATED:

            break;



        default:

            abort();

        }

    }



    g_free(l2_table);

    return 0;



fail:

    g_free(l2_table);

    return ret;

}

static int opus_packet(AVFormatContext *avf, int idx)

{

    struct ogg *ogg              = avf->priv_data;

    struct ogg_stream *os        = &ogg->streams[idx];

    AVStream *st                 = avf->streams[idx];

    struct oggopus_private *priv = os->private;

    uint8_t *packet              = os->buf + os->pstart;



    if (!os->psize)

        return AVERROR_INVALIDDATA;



    if ((!os->lastpts || os->lastpts == AV_NOPTS_VALUE) && !(os->flags & OGG_FLAG_EOS)) {

        int seg, d;

        int duration;

        uint8_t *last_pkt  = os->buf + os->pstart;

        uint8_t *next_pkt  = last_pkt;



        duration = 0;

        seg = os->segp;

        d = opus_duration(last_pkt, os->psize);

        if (d < 0) {

            os->pflags |= AV_PKT_FLAG_CORRUPT;

            return 0;

        }

        duration += d;

        last_pkt = next_pkt =  next_pkt + os->psize;

        for (; seg < os->nsegs; seg++) {

            if (os->segments[seg] < 255) {

                int d = opus_duration(last_pkt, os->segments[seg]);

                if (d < 0) {

                    duration = os->granule;

                    break;

                }

                duration += d;

                last_pkt  = next_pkt + os->segments[seg];

            }

            next_pkt += os->segments[seg];

        }

        os->lastpts                 =

        os->lastdts                 = os->granule - duration;

    }



    os->pduration = opus_duration(packet, os->psize);

    if (os->lastpts != AV_NOPTS_VALUE) {

        if (st->start_time == AV_NOPTS_VALUE)

            st->start_time = os->lastpts;

        priv->cur_dts = os->lastdts = os->lastpts -= priv->pre_skip;

    }



    priv->cur_dts += os->pduration;

    if ((os->flags & OGG_FLAG_EOS)) {

        int64_t skip = priv->cur_dts - os->granule + priv->pre_skip;

        skip = FFMIN(skip, os->pduration);

        if (skip > 0) {

            os->pduration = skip < os->pduration ? os->pduration - skip : 1;

            os->end_trimming = skip;

            av_log(avf, AV_LOG_DEBUG,

                   "Last packet was truncated to %d due to end trimming.\n",

                   os->pduration);

        }

    }



    return 0;

}

static int nsv_read_chunk(AVFormatContext *s, int fill_header)

{

    NSVContext *nsv = s->priv_data;

    AVIOContext *pb = s->pb;

    AVStream *st[2] = {NULL, NULL};

    NSVStream *nst;

    AVPacket *pkt;

    int i, err = 0;

    uint8_t auxcount; /* number of aux metadata, also 4 bits of vsize */

    uint32_t vsize;

    uint16_t asize;

    uint16_t auxsize;



    av_dlog(s, "%s(%d)\n", __FUNCTION__, fill_header);



    if (nsv->ahead[0].data || nsv->ahead[1].data)

        return 0; //-1; /* hey! eat what you've in your plate first! */



null_chunk_retry:

    if (avio_feof(pb))

        return -1;



    for (i = 0; i < NSV_MAX_RESYNC_TRIES && nsv->state < NSV_FOUND_NSVS && !err; i++)

        err = nsv_resync(s);

    if (err < 0)

        return err;

    if (nsv->state == NSV_FOUND_NSVS)

        err = nsv_parse_NSVs_header(s);

    if (err < 0)

        return err;

    if (nsv->state != NSV_HAS_READ_NSVS && nsv->state != NSV_FOUND_BEEF)

        return -1;



    auxcount = avio_r8(pb);

    vsize = avio_rl16(pb);

    asize = avio_rl16(pb);

    vsize = (vsize << 4) | (auxcount >> 4);

    auxcount &= 0x0f;

    av_dlog(s, "NSV CHUNK %d aux, %u bytes video, %d bytes audio\n", auxcount, vsize, asize);

    /* skip aux stuff */

    for (i = 0; i < auxcount; i++) {

        uint32_t av_unused auxtag;

        auxsize = avio_rl16(pb);

        auxtag = avio_rl32(pb);

        av_dlog(s, "NSV aux data: '%c%c%c%c', %d bytes\n",

              (auxtag & 0x0ff),

              ((auxtag >> 8) & 0x0ff),

              ((auxtag >> 16) & 0x0ff),

              ((auxtag >> 24) & 0x0ff),

              auxsize);

        avio_skip(pb, auxsize);

        vsize -= auxsize + sizeof(uint16_t) + sizeof(uint32_t); /* that's becoming braindead */

    }



    if (avio_feof(pb))

        return -1;

    if (!vsize && !asize) {

        nsv->state = NSV_UNSYNC;

        goto null_chunk_retry;

    }



    /* map back streams to v,a */

    if (s->nb_streams > 0)

        st[s->streams[0]->id] = s->streams[0];

    if (s->nb_streams > 1)

        st[s->streams[1]->id] = s->streams[1];



    if (vsize && st[NSV_ST_VIDEO]) {

        int ret;

        nst = st[NSV_ST_VIDEO]->priv_data;

        pkt = &nsv->ahead[NSV_ST_VIDEO];

        if ((ret = av_get_packet(pb, pkt, vsize)) < 0)

            return ret;

        pkt->stream_index = st[NSV_ST_VIDEO]->index;//NSV_ST_VIDEO;

        pkt->dts = nst->frame_offset;

        pkt->flags |= nsv->state == NSV_HAS_READ_NSVS ? AV_PKT_FLAG_KEY : 0; /* keyframe only likely on a sync frame */

        for (i = 0; i < FFMIN(8, vsize); i++)

            av_dlog(s, "NSV video: [%d] = %02x\n", i, pkt->data[i]);

    }

    if(st[NSV_ST_VIDEO])

        ((NSVStream*)st[NSV_ST_VIDEO]->priv_data)->frame_offset++;



    if (asize && st[NSV_ST_AUDIO]) {

        nst = st[NSV_ST_AUDIO]->priv_data;

        pkt = &nsv->ahead[NSV_ST_AUDIO];

        /* read raw audio specific header on the first audio chunk... */

        /* on ALL audio chunks ?? seems so! */

        if (asize && st[NSV_ST_AUDIO]->codec->codec_tag == MKTAG('P', 'C', 'M', ' ')/* && fill_header*/) {

            uint8_t bps;

            uint8_t channels;

            uint16_t samplerate;

            bps = avio_r8(pb);

            channels = avio_r8(pb);

            samplerate = avio_rl16(pb);

            asize-=4;

            av_dlog(s, "NSV RAWAUDIO: bps %d, nchan %d, srate %d\n", bps, channels, samplerate);

            if (fill_header) {

                st[NSV_ST_AUDIO]->need_parsing = AVSTREAM_PARSE_NONE; /* we know everything */

                if (bps != 16) {

                    av_dlog(s, "NSV AUDIO bit/sample != 16 (%d)!!!\n", bps);

                }

                if(channels)

                    bps /= channels; // ???

                else

                    av_log(s, AV_LOG_WARNING, "Channels is 0\n");

                if (bps == 8)

                    st[NSV_ST_AUDIO]->codec->codec_id = AV_CODEC_ID_PCM_U8;

                samplerate /= 4;/* UGH ??? XXX */

                channels = 1;

                st[NSV_ST_AUDIO]->codec->channels = channels;

                st[NSV_ST_AUDIO]->codec->sample_rate = samplerate;

                av_dlog(s, "NSV RAWAUDIO: bps %d, nchan %d, srate %d\n", bps, channels, samplerate);

            }

        }

        av_get_packet(pb, pkt, asize);

        pkt->stream_index = st[NSV_ST_AUDIO]->index;//NSV_ST_AUDIO;

        pkt->flags |= nsv->state == NSV_HAS_READ_NSVS ? AV_PKT_FLAG_KEY : 0; /* keyframe only likely on a sync frame */

        if( nsv->state == NSV_HAS_READ_NSVS && st[NSV_ST_VIDEO] ) {

            /* on a nsvs frame we have new information on a/v sync */

            pkt->dts = (((NSVStream*)st[NSV_ST_VIDEO]->priv_data)->frame_offset-1);

            pkt->dts *= (int64_t)1000        * nsv->framerate.den;

            pkt->dts += (int64_t)nsv->avsync * nsv->framerate.num;

            av_dlog(s, "NSV AUDIO: sync:%d, dts:%"PRId64, nsv->avsync, pkt->dts);

        }

        nst->frame_offset++;

    }



    nsv->state = NSV_UNSYNC;

    return 0;

}

static void virtio_pci_common_write(void *opaque, hwaddr addr,

                                    uint64_t val, unsigned size)

{

    VirtIOPCIProxy *proxy = opaque;

    VirtIODevice *vdev = virtio_bus_get_device(&proxy->bus);



    switch (addr) {

    case VIRTIO_PCI_COMMON_DFSELECT:

        proxy->dfselect = val;

        break;

    case VIRTIO_PCI_COMMON_GFSELECT:

        proxy->gfselect = val;

        break;

    case VIRTIO_PCI_COMMON_GF:

        if (proxy->gfselect <= ARRAY_SIZE(proxy->guest_features)) {

            proxy->guest_features[proxy->gfselect] = val;

            virtio_set_features(vdev,

                                (((uint64_t)proxy->guest_features[1]) << 32) |

                                proxy->guest_features[0]);

        }

        break;

    case VIRTIO_PCI_COMMON_MSIX:

        msix_vector_unuse(&proxy->pci_dev, vdev->config_vector);

        /* Make it possible for guest to discover an error took place. */

        if (msix_vector_use(&proxy->pci_dev, val) < 0) {

            val = VIRTIO_NO_VECTOR;

        }

        vdev->config_vector = val;

        break;

    case VIRTIO_PCI_COMMON_STATUS:

        if (!(val & VIRTIO_CONFIG_S_DRIVER_OK)) {

            virtio_pci_stop_ioeventfd(proxy);

        }



        virtio_set_status(vdev, val & 0xFF);



        if (val & VIRTIO_CONFIG_S_DRIVER_OK) {

            virtio_pci_start_ioeventfd(proxy);

        }



        if (vdev->status == 0) {

            virtio_reset(vdev);

            msix_unuse_all_vectors(&proxy->pci_dev);

        }



        break;

    case VIRTIO_PCI_COMMON_Q_SELECT:

        if (val < VIRTIO_QUEUE_MAX) {

            vdev->queue_sel = val;

        }

        break;

    case VIRTIO_PCI_COMMON_Q_SIZE:

        proxy->vqs[vdev->queue_sel].num = val;

        break;

    case VIRTIO_PCI_COMMON_Q_MSIX:

        msix_vector_unuse(&proxy->pci_dev,

                          virtio_queue_vector(vdev, vdev->queue_sel));

        /* Make it possible for guest to discover an error took place. */

        if (msix_vector_use(&proxy->pci_dev, val) < 0) {

            val = VIRTIO_NO_VECTOR;

        }

        virtio_queue_set_vector(vdev, vdev->queue_sel, val);

        break;

    case VIRTIO_PCI_COMMON_Q_ENABLE:

        /* TODO: need a way to put num back on reset. */

        virtio_queue_set_num(vdev, vdev->queue_sel,

                             proxy->vqs[vdev->queue_sel].num);

        virtio_queue_set_rings(vdev, vdev->queue_sel,

                       ((uint64_t)proxy->vqs[vdev->queue_sel].desc[1]) << 32 |

                       proxy->vqs[vdev->queue_sel].desc[0],

                       ((uint64_t)proxy->vqs[vdev->queue_sel].avail[1]) << 32 |

                       proxy->vqs[vdev->queue_sel].avail[0],

                       ((uint64_t)proxy->vqs[vdev->queue_sel].used[1]) << 32 |

                       proxy->vqs[vdev->queue_sel].used[0]);

        break;

    case VIRTIO_PCI_COMMON_Q_DESCLO:

        proxy->vqs[vdev->queue_sel].desc[0] = val;

        break;

    case VIRTIO_PCI_COMMON_Q_DESCHI:

        proxy->vqs[vdev->queue_sel].desc[1] = val;

        break;

    case VIRTIO_PCI_COMMON_Q_AVAILLO:

        proxy->vqs[vdev->queue_sel].avail[0] = val;

        break;

    case VIRTIO_PCI_COMMON_Q_AVAILHI:

        proxy->vqs[vdev->queue_sel].avail[1] = val;

        break;

    case VIRTIO_PCI_COMMON_Q_USEDLO:

        proxy->vqs[vdev->queue_sel].used[0] = val;

        break;

    case VIRTIO_PCI_COMMON_Q_USEDHI:

        proxy->vqs[vdev->queue_sel].used[1] = val;

        break;

    default:

        break;

    }

}

void tcp_start_outgoing_migration(MigrationState *s,

                                  const char *host_port,

                                  Error **errp)

{

    Error *err = NULL;

    SocketAddress *saddr = tcp_build_address(host_port, &err);

    if (!err) {

        socket_start_outgoing_migration(s, saddr, &err);

    }

    error_propagate(errp, err);

}

static int ast2400_rambits(AspeedSDMCState *s)

{

    switch (s->ram_size >> 20) {

    case 64:

        return ASPEED_SDMC_DRAM_64MB;

    case 128:

        return ASPEED_SDMC_DRAM_128MB;

    case 256:

        return ASPEED_SDMC_DRAM_256MB;

    case 512:

        return ASPEED_SDMC_DRAM_512MB;

    default:

        break;

    }



    /* use a common default */

    error_report("warning: Invalid RAM size 0x%" PRIx64

                 ". Using default 256M", s->ram_size);

    s->ram_size = 256 << 20;

    return ASPEED_SDMC_DRAM_256MB;

}

static int decode_slice(MpegEncContext *s){

    const int part_mask= s->partitioned_frame ? (ER_AC_END|ER_AC_ERROR) : 0x7F;

    const int mb_size= 16>>s->avctx->lowres;

    int ret;



    s->last_resync_gb= s->gb;

    s->first_slice_line= 1;



    s->resync_mb_x= s->mb_x;

    s->resync_mb_y= s->mb_y;



    ff_set_qscale(s, s->qscale);



    if (s->avctx->hwaccel) {

        const uint8_t *start= s->gb.buffer + get_bits_count(&s->gb)/8;

        const uint8_t *end  = ff_h263_find_resync_marker(start + 1, s->gb.buffer_end);

        skip_bits_long(&s->gb, 8*(end - start));

        return s->avctx->hwaccel->decode_slice(s->avctx, start, end - start);

    }



    if(s->partitioned_frame){

        const int qscale= s->qscale;



        if(CONFIG_MPEG4_DECODER && s->codec_id==AV_CODEC_ID_MPEG4){

            if ((ret = ff_mpeg4_decode_partitions(s)) < 0)

                return ret;

        }



        /* restore variables which were modified */

        s->first_slice_line=1;

        s->mb_x= s->resync_mb_x;

        s->mb_y= s->resync_mb_y;

        ff_set_qscale(s, qscale);

    }



    for(; s->mb_y < s->mb_height; s->mb_y++) {

        /* per-row end of slice checks */

        if(s->msmpeg4_version){

            if(s->resync_mb_y + s->slice_height == s->mb_y){

                ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x-1, s->mb_y, ER_MB_END);



                return 0;

            }

        }



        if(s->msmpeg4_version==1){

            s->last_dc[0]=

            s->last_dc[1]=

            s->last_dc[2]= 128;

        }



        ff_init_block_index(s);

        for(; s->mb_x < s->mb_width; s->mb_x++) {

            int ret;



            ff_update_block_index(s);



            if(s->resync_mb_x == s->mb_x && s->resync_mb_y+1 == s->mb_y){

                s->first_slice_line=0;

            }



            /* DCT & quantize */



            s->mv_dir = MV_DIR_FORWARD;

            s->mv_type = MV_TYPE_16X16;

//            s->mb_skipped = 0;

            av_dlog(s, "%d %d %06X\n",

                    ret, get_bits_count(&s->gb), show_bits(&s->gb, 24));

            ret= s->decode_mb(s, s->block);



            if (s->pict_type!=AV_PICTURE_TYPE_B)

                ff_h263_update_motion_val(s);



            if(ret<0){

                const int xy= s->mb_x + s->mb_y*s->mb_stride;

                if(ret==SLICE_END){

                    ff_MPV_decode_mb(s, s->block);

                    if(s->loop_filter)

                        ff_h263_loop_filter(s);



                    ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, ER_MB_END&part_mask);



                    s->padding_bug_score--;



                    if(++s->mb_x >= s->mb_width){

                        s->mb_x=0;

                        ff_draw_horiz_band(s, s->mb_y*mb_size, mb_size);

                        ff_MPV_report_decode_progress(s);

                        s->mb_y++;

                    }

                    return 0;

                }else if(ret==SLICE_NOEND){

                    av_log(s->avctx, AV_LOG_ERROR, "Slice mismatch at MB: %d\n", xy);

                    ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x+1, s->mb_y, ER_MB_END&part_mask);

                    return AVERROR_INVALIDDATA;

                }

                av_log(s->avctx, AV_LOG_ERROR, "Error at MB: %d\n", xy);

                ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, ER_MB_ERROR&part_mask);



                return AVERROR_INVALIDDATA;

            }



            ff_MPV_decode_mb(s, s->block);

            if(s->loop_filter)

                ff_h263_loop_filter(s);

        }



        ff_draw_horiz_band(s, s->mb_y*mb_size, mb_size);

        ff_MPV_report_decode_progress(s);



        s->mb_x= 0;

    }



    assert(s->mb_x==0 && s->mb_y==s->mb_height);



    if(s->codec_id==AV_CODEC_ID_MPEG4

       && (s->workaround_bugs&FF_BUG_AUTODETECT)

       && get_bits_left(&s->gb) >= 48

       && show_bits(&s->gb, 24)==0x4010

       && !s->data_partitioning)

        s->padding_bug_score+=32;



    /* try to detect the padding bug */

    if(      s->codec_id==AV_CODEC_ID_MPEG4

       &&   (s->workaround_bugs&FF_BUG_AUTODETECT)

       &&    get_bits_left(&s->gb) >=0

       &&    get_bits_left(&s->gb) < 137

//       &&   !s->resync_marker

       &&   !s->data_partitioning){



        const int bits_count= get_bits_count(&s->gb);

        const int bits_left = s->gb.size_in_bits - bits_count;



        if(bits_left==0){

            s->padding_bug_score+=16;

        } else if(bits_left != 1){

            int v= show_bits(&s->gb, 8);

            v|= 0x7F >> (7-(bits_count&7));



            if(v==0x7F && bits_left<=8)

                s->padding_bug_score--;

            else if(v==0x7F && ((get_bits_count(&s->gb)+8)&8) && bits_left<=16)

                s->padding_bug_score+= 4;

            else

                s->padding_bug_score++;

        }

    }



    if(s->workaround_bugs&FF_BUG_AUTODETECT){

        if(s->padding_bug_score > -2 && !s->data_partitioning /*&& (s->divx_version>=0 || !s->resync_marker)*/)

            s->workaround_bugs |=  FF_BUG_NO_PADDING;

        else

            s->workaround_bugs &= ~FF_BUG_NO_PADDING;

    }



    // handle formats which don't have unique end markers

    if(s->msmpeg4_version || (s->workaround_bugs&FF_BUG_NO_PADDING)){ //FIXME perhaps solve this more cleanly

        int left= get_bits_left(&s->gb);

        int max_extra=7;



        /* no markers in M$ crap */

        if(s->msmpeg4_version && s->pict_type==AV_PICTURE_TYPE_I)

            max_extra+= 17;



        /* buggy padding but the frame should still end approximately at the bitstream end */

        if((s->workaround_bugs&FF_BUG_NO_PADDING) && (s->err_recognition&(AV_EF_BUFFER|AV_EF_AGGRESSIVE)))

            max_extra+= 48;

        else if((s->workaround_bugs&FF_BUG_NO_PADDING))

            max_extra+= 256*256*256*64;



        if(left>max_extra){

            av_log(s->avctx, AV_LOG_ERROR, "discarding %d junk bits at end, next would be %X\n", left, show_bits(&s->gb, 24));

        }

        else if(left<0){

            av_log(s->avctx, AV_LOG_ERROR, "overreading %d bits\n", -left);

        }else

            ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x-1, s->mb_y, ER_MB_END);



        return 0;

    }



    av_log(s->avctx, AV_LOG_ERROR, "slice end not reached but screenspace end (%d left %06X, score= %d)\n",

            get_bits_left(&s->gb),

            show_bits(&s->gb, 24), s->padding_bug_score);



    ff_er_add_slice(s, s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y, ER_MB_END&part_mask);



    return AVERROR_INVALIDDATA;

}

static void get_fcb_param(FCBParam *optim, int16_t *impulse_resp,

                          int16_t *buf, int pulse_cnt, int pitch_lag)

{

    FCBParam param;

    int16_t impulse_r[SUBFRAME_LEN];

    int16_t temp_corr[SUBFRAME_LEN];

    int16_t impulse_corr[SUBFRAME_LEN];



    int ccr1[SUBFRAME_LEN];

    int ccr2[SUBFRAME_LEN];

    int amp, err, max, max_amp_index, min, scale, i, j, k, l;



    int64_t temp;



    /* Update impulse response */

    memcpy(impulse_r, impulse_resp, sizeof(int16_t) * SUBFRAME_LEN);

    param.dirac_train = 0;

    if (pitch_lag < SUBFRAME_LEN - 2) {

        param.dirac_train = 1;

        gen_dirac_train(impulse_r, pitch_lag);

    }



    for (i = 0; i < SUBFRAME_LEN; i++)

        temp_corr[i] = impulse_r[i] >> 1;



    /* Compute impulse response autocorrelation */

    temp = dot_product(temp_corr, temp_corr, SUBFRAME_LEN);



    scale = normalize_bits_int32(temp);

    impulse_corr[0] = av_clipl_int32((temp << scale) + (1 << 15)) >> 16;



    for (i = 1; i < SUBFRAME_LEN; i++) {

        temp = dot_product(temp_corr + i, temp_corr, SUBFRAME_LEN - i);

        impulse_corr[i] = av_clipl_int32((temp << scale) + (1 << 15)) >> 16;

    }



    /* Compute crosscorrelation of impulse response with residual signal */

    scale -= 4;

    for (i = 0; i < SUBFRAME_LEN; i++){

        temp = dot_product(buf + i, impulse_r, SUBFRAME_LEN - i);

        if (scale < 0)

            ccr1[i] = temp >> -scale;

        else

            ccr1[i] = av_clipl_int32(temp << scale);

    }



    /* Search loop */

    for (i = 0; i < GRID_SIZE; i++) {

        /* Maximize the crosscorrelation */

        max = 0;

        for (j = i; j < SUBFRAME_LEN; j += GRID_SIZE) {

            temp = FFABS(ccr1[j]);

            if (temp >= max) {

                max = temp;

                param.pulse_pos[0] = j;

            }

        }



        /* Quantize the gain (max crosscorrelation/impulse_corr[0]) */

        amp = max;

        min = 1 << 30;

        max_amp_index = GAIN_LEVELS - 2;

        for (j = max_amp_index; j >= 2; j--) {

            temp = av_clipl_int32((int64_t)fixed_cb_gain[j] *

                                  impulse_corr[0] << 1);

            temp = FFABS(temp - amp);

            if (temp < min) {

                min = temp;

                max_amp_index = j;

            }

        }



        max_amp_index--;

        /* Select additional gain values */

        for (j = 1; j < 5; j++) {

            for (k = i; k < SUBFRAME_LEN; k += GRID_SIZE) {

                temp_corr[k] = 0;

                ccr2[k]      = ccr1[k];

            }

            param.amp_index = max_amp_index + j - 2;

            amp = fixed_cb_gain[param.amp_index];



            param.pulse_sign[0] = (ccr2[param.pulse_pos[0]] < 0) ? -amp : amp;

            temp_corr[param.pulse_pos[0]] = 1;



            for (k = 1; k < pulse_cnt; k++) {

                max = -1 << 30;

                for (l = i; l < SUBFRAME_LEN; l += GRID_SIZE) {

                    if (temp_corr[l])

                        continue;

                    temp = impulse_corr[FFABS(l - param.pulse_pos[k - 1])];

                    temp = av_clipl_int32((int64_t)temp *

                                          param.pulse_sign[k - 1] << 1);

                    ccr2[l] -= temp;

                    temp = FFABS(ccr2[l]);

                    if (temp > max) {

                        max = temp;

                        param.pulse_pos[k] = l;

                    }

                }



                param.pulse_sign[k] = (ccr2[param.pulse_pos[k]] < 0) ?

                                      -amp : amp;

                temp_corr[param.pulse_pos[k]] = 1;

            }



            /* Create the error vector */

            memset(temp_corr, 0, sizeof(int16_t) * SUBFRAME_LEN);



            for (k = 0; k < pulse_cnt; k++)

                temp_corr[param.pulse_pos[k]] = param.pulse_sign[k];



            for (k = SUBFRAME_LEN - 1; k >= 0; k--) {

                temp = 0;

                for (l = 0; l <= k; l++) {

                    int prod = av_clipl_int32((int64_t)temp_corr[l] *

                                              impulse_r[k - l] << 1);

                    temp     = av_clipl_int32(temp + prod);

                }

                temp_corr[k] = temp << 2 >> 16;

            }



            /* Compute square of error */

            err = 0;

            for (k = 0; k < SUBFRAME_LEN; k++) {

                int64_t prod;

                prod = av_clipl_int32((int64_t)buf[k] * temp_corr[k] << 1);

                err  = av_clipl_int32(err - prod);

                prod = av_clipl_int32((int64_t)temp_corr[k] * temp_corr[k]);

                err  = av_clipl_int32(err + prod);

            }



            /* Minimize */

            if (err < optim->min_err) {

                optim->min_err     = err;

                optim->grid_index  = i;

                optim->amp_index   = param.amp_index;

                optim->dirac_train = param.dirac_train;



                for (k = 0; k < pulse_cnt; k++) {

                    optim->pulse_sign[k] = param.pulse_sign[k];

                    optim->pulse_pos[k]  = param.pulse_pos[k];

                }

            }

        }

    }

}

static ssize_t proxy_readlink(FsContext *fs_ctx, V9fsPath *fs_path,

                              char *buf, size_t bufsz)

{

    int retval;

    retval = v9fs_request(fs_ctx->private, T_READLINK, buf, "sd",

                          fs_path, bufsz);

    if (retval < 0) {

        errno = -retval;

        return -1;

    }

    return strlen(buf);

}

static void gt64120_writel (void *opaque, target_phys_addr_t addr,

                            uint32_t val)

{

    GT64120State *s = opaque;

    uint32_t saddr;



#ifdef TARGET_WORDS_BIGENDIAN

    val = bswap32(val);

#endif



    saddr = (addr & 0xfff) >> 2;

    switch (saddr) {



    /* CPU Configuration */

    case GT_CPU:

        s->regs[GT_CPU] = val;

        break;

    case GT_MULTI:

	/* Read-only register as only one GT64xxx is present on the CPU bus */

        break;



    /* CPU Address Decode */

    case GT_PCI0IOLD:

        s->regs[GT_PCI0IOLD]    = val & 0x00007fff;

        s->regs[GT_PCI0IOREMAP] = val & 0x000007ff;

        gt64120_pci_mapping(s);

        break;

    case GT_PCI0M0LD:

        s->regs[GT_PCI0M0LD]    = val & 0x00007fff;

        s->regs[GT_PCI0M0REMAP] = val & 0x000007ff;

        break;

    case GT_PCI0M1LD:

        s->regs[GT_PCI0M1LD]    = val & 0x00007fff;

        s->regs[GT_PCI0M1REMAP] = val & 0x000007ff;

        break;

    case GT_PCI1IOLD:

        s->regs[GT_PCI1IOLD]    = val & 0x00007fff;

        s->regs[GT_PCI1IOREMAP] = val & 0x000007ff;

        break;

    case GT_PCI1M0LD:

        s->regs[GT_PCI1M0LD]    = val & 0x00007fff;

        s->regs[GT_PCI1M0REMAP] = val & 0x000007ff;

        break;

    case GT_PCI1M1LD:

        s->regs[GT_PCI1M1LD]    = val & 0x00007fff;

        s->regs[GT_PCI1M1REMAP] = val & 0x000007ff;

        break;

    case GT_PCI0IOHD:

        s->regs[saddr] = val & 0x0000007f;

        gt64120_pci_mapping(s);

        break;

    case GT_PCI0M0HD:

    case GT_PCI0M1HD:

    case GT_PCI1IOHD:

    case GT_PCI1M0HD:

    case GT_PCI1M1HD:

        s->regs[saddr] = val & 0x0000007f;

        break;

    case GT_ISD:

        s->regs[saddr] = val & 0x00007fff;

        gt64120_isd_mapping(s);

        break;



    case GT_PCI0IOREMAP:

    case GT_PCI0M0REMAP:

    case GT_PCI0M1REMAP:

    case GT_PCI1IOREMAP:

    case GT_PCI1M0REMAP:

    case GT_PCI1M1REMAP:

        s->regs[saddr] = val & 0x000007ff;

        break;



    /* CPU Error Report */

    case GT_CPUERR_ADDRLO:

    case GT_CPUERR_ADDRHI:

    case GT_CPUERR_DATALO:

    case GT_CPUERR_DATAHI:

    case GT_CPUERR_PARITY:

	/* Read-only registers, do nothing */

        break;



    /* CPU Sync Barrier */

    case GT_PCI0SYNC:

    case GT_PCI1SYNC:

	/* Read-only registers, do nothing */

        break;



    /* SDRAM and Device Address Decode */

    case GT_SCS0LD:

    case GT_SCS0HD:

    case GT_SCS1LD:

    case GT_SCS1HD:

    case GT_SCS2LD:

    case GT_SCS2HD:

    case GT_SCS3LD:

    case GT_SCS3HD:

    case GT_CS0LD:

    case GT_CS0HD:

    case GT_CS1LD:

    case GT_CS1HD:

    case GT_CS2LD:

    case GT_CS2HD:

    case GT_CS3LD:

    case GT_CS3HD:

    case GT_BOOTLD:

    case GT_BOOTHD:

    case GT_ADERR:

    /* SDRAM Configuration */

    case GT_SDRAM_CFG:

    case GT_SDRAM_OPMODE:

    case GT_SDRAM_BM:

    case GT_SDRAM_ADDRDECODE:

        /* Accept and ignore SDRAM interleave configuration */

        s->regs[saddr] = val;

        break;



    /* Device Parameters */

    case GT_DEV_B0:

    case GT_DEV_B1:

    case GT_DEV_B2:

    case GT_DEV_B3:

    case GT_DEV_BOOT:

        /* Not implemented */

        dprintf ("Unimplemented device register offset 0x%x\n", saddr << 2);

        break;



    /* ECC */

    case GT_ECC_ERRDATALO:

    case GT_ECC_ERRDATAHI:

    case GT_ECC_MEM:

    case GT_ECC_CALC:

    case GT_ECC_ERRADDR:

        /* Read-only registers, do nothing */

        break;



    /* DMA Record */

    case GT_DMA0_CNT:

    case GT_DMA1_CNT:

    case GT_DMA2_CNT:

    case GT_DMA3_CNT:

    case GT_DMA0_SA:

    case GT_DMA1_SA:

    case GT_DMA2_SA:

    case GT_DMA3_SA:

    case GT_DMA0_DA:

    case GT_DMA1_DA:

    case GT_DMA2_DA:

    case GT_DMA3_DA:

    case GT_DMA0_NEXT:

    case GT_DMA1_NEXT:

    case GT_DMA2_NEXT:

    case GT_DMA3_NEXT:

    case GT_DMA0_CUR:

    case GT_DMA1_CUR:

    case GT_DMA2_CUR:

    case GT_DMA3_CUR:

        /* Not implemented */

        dprintf ("Unimplemented DMA register offset 0x%x\n", saddr << 2);

        break;



    /* DMA Channel Control */

    case GT_DMA0_CTRL:

    case GT_DMA1_CTRL:

    case GT_DMA2_CTRL:

    case GT_DMA3_CTRL:

        /* Not implemented */

        dprintf ("Unimplemented DMA register offset 0x%x\n", saddr << 2);

        break;



    /* DMA Arbiter */

    case GT_DMA_ARB:

        /* Not implemented */

        dprintf ("Unimplemented DMA register offset 0x%x\n", saddr << 2);

        break;



    /* Timer/Counter */

    case GT_TC0:

    case GT_TC1:

    case GT_TC2:

    case GT_TC3:

    case GT_TC_CONTROL:

        /* Not implemented */

        dprintf ("Unimplemented timer register offset 0x%x\n", saddr << 2);

        break;



    /* PCI Internal */

    case GT_PCI0_CMD:

    case GT_PCI1_CMD:

        s->regs[saddr] = val & 0x0401fc0f;

        break;

    case GT_PCI0_TOR:

    case GT_PCI0_BS_SCS10:

    case GT_PCI0_BS_SCS32:

    case GT_PCI0_BS_CS20:

    case GT_PCI0_BS_CS3BT:

    case GT_PCI1_IACK:

    case GT_PCI0_IACK:

    case GT_PCI0_BARE:

    case GT_PCI0_PREFMBR:

    case GT_PCI0_SCS10_BAR:

    case GT_PCI0_SCS32_BAR:

    case GT_PCI0_CS20_BAR:

    case GT_PCI0_CS3BT_BAR:

    case GT_PCI0_SSCS10_BAR:

    case GT_PCI0_SSCS32_BAR:

    case GT_PCI0_SCS3BT_BAR:

    case GT_PCI1_TOR:

    case GT_PCI1_BS_SCS10:

    case GT_PCI1_BS_SCS32:

    case GT_PCI1_BS_CS20:

    case GT_PCI1_BS_CS3BT:

    case GT_PCI1_BARE:

    case GT_PCI1_PREFMBR:

    case GT_PCI1_SCS10_BAR:

    case GT_PCI1_SCS32_BAR:

    case GT_PCI1_CS20_BAR:

    case GT_PCI1_CS3BT_BAR:

    case GT_PCI1_SSCS10_BAR:

    case GT_PCI1_SSCS32_BAR:

    case GT_PCI1_SCS3BT_BAR:

    case GT_PCI1_CFGADDR:

    case GT_PCI1_CFGDATA:

        /* not implemented */

        break;

    case GT_PCI0_CFGADDR:

        s->pci->config_reg = val & 0x80fffffc;

        break;

    case GT_PCI0_CFGDATA:

        if (s->pci->config_reg & (1u << 31))

            pci_host_data_writel(s->pci, 0, val);

        break;



    /* Interrupts */

    case GT_INTRCAUSE:

        /* not really implemented */

        s->regs[saddr] = ~(~(s->regs[saddr]) | ~(val & 0xfffffffe));

        s->regs[saddr] |= !!(s->regs[saddr] & 0xfffffffe);

        dprintf("INTRCAUSE %x\n", val);

        break;

    case GT_INTRMASK:

        s->regs[saddr] = val & 0x3c3ffffe;

        dprintf("INTRMASK %x\n", val);

        break;

    case GT_PCI0_ICMASK:

        s->regs[saddr] = val & 0x03fffffe;

        dprintf("ICMASK %x\n", val);

        break;

    case GT_PCI0_SERR0MASK:

        s->regs[saddr] = val & 0x0000003f;

        dprintf("SERR0MASK %x\n", val);

        break;



    /* Reserved when only PCI_0 is configured. */

    case GT_HINTRCAUSE:

    case GT_CPU_INTSEL:

    case GT_PCI0_INTSEL:

    case GT_HINTRMASK:

    case GT_PCI0_HICMASK:

    case GT_PCI1_SERR1MASK:

        /* not implemented */

        break;



    /* SDRAM Parameters */

    case GT_SDRAM_B0:

    case GT_SDRAM_B1:

    case GT_SDRAM_B2:

    case GT_SDRAM_B3:

        /* We don't simulate electrical parameters of the SDRAM.

           Accept, but ignore the values. */

        s->regs[saddr] = val;

        break;



    default:

        dprintf ("Bad register offset 0x%x\n", (int)addr);

        break;

    }

}

