static int vp9_decode_update_thread_context(AVCodecContext *dst, const AVCodecContext *src)

{

    int i, res;

    VP9Context *s = dst->priv_data, *ssrc = src->priv_data;



    // FIXME scalability, size, etc.



    for (i = 0; i < 2; i++) {

        if (s->frames[i].tf.f->data[0])

            vp9_unref_frame(dst, &s->frames[i]);

        if (ssrc->frames[i].tf.f->data[0]) {

            if ((res = vp9_ref_frame(dst, &s->frames[i], &ssrc->frames[i])) < 0)

                return res;

        }

    }

    for (i = 0; i < 8; i++) {

        if (s->refs[i].f->data[0])

            ff_thread_release_buffer(dst, &s->refs[i]);

        if (ssrc->next_refs[i].f->data[0]) {

            if ((res = ff_thread_ref_frame(&s->refs[i], &ssrc->next_refs[i])) < 0)

                return res;

        }

    }



    s->invisible = ssrc->invisible;

    s->keyframe = ssrc->keyframe;

    s->uses_2pass = ssrc->uses_2pass;

    memcpy(&s->prob_ctx, &ssrc->prob_ctx, sizeof(s->prob_ctx));

    memcpy(&s->lf_delta, &ssrc->lf_delta, sizeof(s->lf_delta));

    if (ssrc->segmentation.enabled) {

        memcpy(&s->segmentation.feat, &ssrc->segmentation.feat,

               sizeof(s->segmentation.feat));

    }



    return 0;

}

static void test_hash_speed(const void *opaque)

{

    size_t chunk_size = (size_t)opaque;

    uint8_t *in = NULL, *out = NULL;

    size_t out_len = 0;

    double total = 0.0;

    struct iovec iov;

    int ret;



    in = g_new0(uint8_t, chunk_size);

    memset(in, g_test_rand_int(), chunk_size);



    iov.iov_base = (char *)in;

    iov.iov_len = chunk_size;



    g_test_timer_start();

    do {

        ret = qcrypto_hash_bytesv(QCRYPTO_HASH_ALG_SHA256,

                                  &iov, 1, &out, &out_len,

                                  NULL);

        g_assert(ret == 0);



        total += chunk_size;

    } while (g_test_timer_elapsed() < 5.0);



    total /= 1024 * 1024; /* to MB */

    g_print("sha256: ");

    g_print("Testing chunk_size %ld bytes ", chunk_size);

    g_print("done: %.2f MB in %.2f secs: ", total, g_test_timer_last());

    g_print("%.2f MB/sec\n", total / g_test_timer_last());



    g_free(out);

    g_free(in);

}

static int vhost_kernel_memslots_limit(struct vhost_dev *dev)

{

    int limit = 64;

    char *s;



    if (g_file_get_contents("/sys/module/vhost/parameters/max_mem_regions",

                            &s, NULL, NULL)) {

        uint64_t val = g_ascii_strtoull(s, NULL, 10);

        if (!((val == G_MAXUINT64 || !val) && errno)) {


            return val;

        }

        error_report("ignoring invalid max_mem_regions value in vhost module:"

                     " %s", s);

    }


    return limit;

}

static inline int h263_mv4_search(MpegEncContext *s, int mx, int my, int shift)

{

    MotionEstContext * const c= &s->me;

    const int size= 1;

    const int h=8;

    int block;

    int P[10][2];

    int dmin_sum=0, mx4_sum=0, my4_sum=0;

    int same=1;

    const int stride= c->stride;

    uint8_t *mv_penalty= c->current_mv_penalty;



    init_mv4_ref(c);



    for(block=0; block<4; block++){

        int mx4, my4;

        int pred_x4, pred_y4;

        int dmin4;

        static const int off[4]= {2, 1, 1, -1};

        const int mot_stride = s->b8_stride;

        const int mot_xy = s->block_index[block];



        P_LEFT[0] = s->current_picture.motion_val[0][mot_xy - 1][0];

        P_LEFT[1] = s->current_picture.motion_val[0][mot_xy - 1][1];



        if(P_LEFT[0]       > (c->xmax<<shift)) P_LEFT[0]       = (c->xmax<<shift);



        /* special case for first line */

        if (s->first_slice_line && block<2) {

            c->pred_x= pred_x4= P_LEFT[0];

            c->pred_y= pred_y4= P_LEFT[1];

        } else {

            P_TOP[0]      = s->current_picture.motion_val[0][mot_xy - mot_stride             ][0];

            P_TOP[1]      = s->current_picture.motion_val[0][mot_xy - mot_stride             ][1];

            P_TOPRIGHT[0] = s->current_picture.motion_val[0][mot_xy - mot_stride + off[block]][0];

            P_TOPRIGHT[1] = s->current_picture.motion_val[0][mot_xy - mot_stride + off[block]][1];

            if(P_TOP[1]      > (c->ymax<<shift)) P_TOP[1]     = (c->ymax<<shift);

            if(P_TOPRIGHT[0] < (c->xmin<<shift)) P_TOPRIGHT[0]= (c->xmin<<shift);

            if(P_TOPRIGHT[0] > (c->xmax<<shift)) P_TOPRIGHT[0]= (c->xmax<<shift);

            if(P_TOPRIGHT[1] > (c->ymax<<shift)) P_TOPRIGHT[1]= (c->ymax<<shift);



            P_MEDIAN[0]= mid_pred(P_LEFT[0], P_TOP[0], P_TOPRIGHT[0]);

            P_MEDIAN[1]= mid_pred(P_LEFT[1], P_TOP[1], P_TOPRIGHT[1]);



            c->pred_x= pred_x4 = P_MEDIAN[0];

            c->pred_y= pred_y4 = P_MEDIAN[1];

        }

        P_MV1[0]= mx;

        P_MV1[1]= my;



        dmin4 = epzs_motion_search4(s, &mx4, &my4, P, block, block, s->p_mv_table, (1<<16)>>shift);



        dmin4= c->sub_motion_search(s, &mx4, &my4, dmin4, block, block, size, h);



        if(s->dsp.me_sub_cmp[0] != s->dsp.mb_cmp[0]){

            int dxy;

            const int offset= ((block&1) + (block>>1)*stride)*8;

            uint8_t *dest_y = c->scratchpad + offset;

            if(s->quarter_sample){

                uint8_t *ref= c->ref[block][0] + (mx4>>2) + (my4>>2)*stride;

                dxy = ((my4 & 3) << 2) | (mx4 & 3);



                if(s->no_rounding)

                    s->dsp.put_no_rnd_qpel_pixels_tab[1][dxy](dest_y   , ref    , stride);

                else

                    s->dsp.put_qpel_pixels_tab       [1][dxy](dest_y   , ref    , stride);

            }else{

                uint8_t *ref= c->ref[block][0] + (mx4>>1) + (my4>>1)*stride;

                dxy = ((my4 & 1) << 1) | (mx4 & 1);



                if(s->no_rounding)

                    s->hdsp.put_no_rnd_pixels_tab[1][dxy](dest_y    , ref    , stride, h);

                else

                    s->hdsp.put_pixels_tab       [1][dxy](dest_y    , ref    , stride, h);

            }

            dmin_sum+= (mv_penalty[mx4-pred_x4] + mv_penalty[my4-pred_y4])*c->mb_penalty_factor;

        }else

            dmin_sum+= dmin4;



        if(s->quarter_sample){

            mx4_sum+= mx4/2;

            my4_sum+= my4/2;

        }else{

            mx4_sum+= mx4;

            my4_sum+= my4;

        }



        s->current_picture.motion_val[0][s->block_index[block]][0] = mx4;

        s->current_picture.motion_val[0][s->block_index[block]][1] = my4;



        if(mx4 != mx || my4 != my) same=0;

    }



    if(same)

        return INT_MAX;



    if(s->dsp.me_sub_cmp[0] != s->dsp.mb_cmp[0]){

        dmin_sum += s->dsp.mb_cmp[0](s, s->new_picture.f.data[0] + s->mb_x*16 + s->mb_y*16*stride, c->scratchpad, stride, 16);

    }



    if(c->avctx->mb_cmp&FF_CMP_CHROMA){

        int dxy;

        int mx, my;

        int offset;



        mx= ff_h263_round_chroma(mx4_sum);

        my= ff_h263_round_chroma(my4_sum);

        dxy = ((my & 1) << 1) | (mx & 1);



        offset= (s->mb_x*8 + (mx>>1)) + (s->mb_y*8 + (my>>1))*s->uvlinesize;



        if(s->no_rounding){

            s->hdsp.put_no_rnd_pixels_tab[1][dxy](c->scratchpad    , s->last_picture.f.data[1] + offset, s->uvlinesize, 8);

            s->hdsp.put_no_rnd_pixels_tab[1][dxy](c->scratchpad + 8, s->last_picture.f.data[2] + offset, s->uvlinesize, 8);

        }else{

            s->hdsp.put_pixels_tab       [1][dxy](c->scratchpad    , s->last_picture.f.data[1] + offset, s->uvlinesize, 8);

            s->hdsp.put_pixels_tab       [1][dxy](c->scratchpad + 8, s->last_picture.f.data[2] + offset, s->uvlinesize, 8);

        }



        dmin_sum += s->dsp.mb_cmp[1](s, s->new_picture.f.data[1] + s->mb_x*8 + s->mb_y*8*s->uvlinesize, c->scratchpad  , s->uvlinesize, 8);

        dmin_sum += s->dsp.mb_cmp[1](s, s->new_picture.f.data[2] + s->mb_x*8 + s->mb_y*8*s->uvlinesize, c->scratchpad+8, s->uvlinesize, 8);

    }



    c->pred_x= mx;

    c->pred_y= my;



    switch(c->avctx->mb_cmp&0xFF){

    /*case FF_CMP_SSE:

        return dmin_sum+ 32*s->qscale*s->qscale;*/

    case FF_CMP_RD:

        return dmin_sum;

    default:

        return dmin_sum+ 11*c->mb_penalty_factor;

    }

}

static inline void powerpc_excp(CPUState *env, int excp_model, int excp)

{

    target_ulong msr, new_msr, vector;

    int srr0, srr1, asrr0, asrr1;

    int lpes0, lpes1, lev;



    if (0) {

        /* XXX: find a suitable condition to enable the hypervisor mode */

        lpes0 = (env->spr[SPR_LPCR] >> 1) & 1;

        lpes1 = (env->spr[SPR_LPCR] >> 2) & 1;

    } else {

        /* Those values ensure we won't enter the hypervisor mode */

        lpes0 = 0;

        lpes1 = 1;

    }



    qemu_log_mask(CPU_LOG_INT, "Raise exception at " TARGET_FMT_lx

                  " => %08x (%02x)\n", env->nip, excp, env->error_code);



    /* new srr1 value excluding must-be-zero bits */

    msr = env->msr & ~0x783f0000ULL;



    /* new interrupt handler msr */

    new_msr = env->msr & ((target_ulong)1 << MSR_ME);



    /* target registers */

    srr0 = SPR_SRR0;

    srr1 = SPR_SRR1;

    asrr0 = -1;

    asrr1 = -1;



    switch (excp) {

    case POWERPC_EXCP_NONE:

        /* Should never happen */

        return;

    case POWERPC_EXCP_CRITICAL:    /* Critical input                         */

        switch (excp_model) {

        case POWERPC_EXCP_40x:

            srr0 = SPR_40x_SRR2;

            srr1 = SPR_40x_SRR3;

            break;

        case POWERPC_EXCP_BOOKE:

            srr0 = SPR_BOOKE_CSRR0;

            srr1 = SPR_BOOKE_CSRR1;

            break;

        case POWERPC_EXCP_G2:

            break;

        default:

            goto excp_invalid;

        }

        goto store_next;

    case POWERPC_EXCP_MCHECK:    /* Machine check exception                  */

        if (msr_me == 0) {

            /* Machine check exception is not enabled.

             * Enter checkstop state.

             */

            if (qemu_log_enabled()) {

                qemu_log("Machine check while not allowed. "

                        "Entering checkstop state\n");

            } else {

                fprintf(stderr, "Machine check while not allowed. "

                        "Entering checkstop state\n");

            }

            env->halted = 1;

            env->interrupt_request |= CPU_INTERRUPT_EXITTB;

        }

        if (0) {

            /* XXX: find a suitable condition to enable the hypervisor mode */

            new_msr |= (target_ulong)MSR_HVB;

        }



        /* machine check exceptions don't have ME set */

        new_msr &= ~((target_ulong)1 << MSR_ME);



        /* XXX: should also have something loaded in DAR / DSISR */

        switch (excp_model) {

        case POWERPC_EXCP_40x:

            srr0 = SPR_40x_SRR2;

            srr1 = SPR_40x_SRR3;

            break;

        case POWERPC_EXCP_BOOKE:

            srr0 = SPR_BOOKE_MCSRR0;

            srr1 = SPR_BOOKE_MCSRR1;

            asrr0 = SPR_BOOKE_CSRR0;

            asrr1 = SPR_BOOKE_CSRR1;

            break;

        default:

            break;

        }

        goto store_next;

    case POWERPC_EXCP_DSI:       /* Data storage exception                   */

        LOG_EXCP("DSI exception: DSISR=" TARGET_FMT_lx" DAR=" TARGET_FMT_lx

                 "\n", env->spr[SPR_DSISR], env->spr[SPR_DAR]);

        if (lpes1 == 0)

            new_msr |= (target_ulong)MSR_HVB;

        goto store_next;

    case POWERPC_EXCP_ISI:       /* Instruction storage exception            */

        LOG_EXCP("ISI exception: msr=" TARGET_FMT_lx ", nip=" TARGET_FMT_lx

                 "\n", msr, env->nip);

        if (lpes1 == 0)

            new_msr |= (target_ulong)MSR_HVB;

        msr |= env->error_code;

        goto store_next;

    case POWERPC_EXCP_EXTERNAL:  /* External input                           */

        if (lpes0 == 1)

            new_msr |= (target_ulong)MSR_HVB;

        goto store_next;

    case POWERPC_EXCP_ALIGN:     /* Alignment exception                      */

        if (lpes1 == 0)

            new_msr |= (target_ulong)MSR_HVB;

        /* XXX: this is false */

        /* Get rS/rD and rA from faulting opcode */

        env->spr[SPR_DSISR] |= (ldl_code((env->nip - 4)) & 0x03FF0000) >> 16;

        goto store_current;

    case POWERPC_EXCP_PROGRAM:   /* Program exception                        */

        switch (env->error_code & ~0xF) {

        case POWERPC_EXCP_FP:

            if ((msr_fe0 == 0 && msr_fe1 == 0) || msr_fp == 0) {

                LOG_EXCP("Ignore floating point exception\n");

                env->exception_index = POWERPC_EXCP_NONE;

                env->error_code = 0;

                return;

            }

            if (lpes1 == 0)

                new_msr |= (target_ulong)MSR_HVB;

            msr |= 0x00100000;

            if (msr_fe0 == msr_fe1)

                goto store_next;

            msr |= 0x00010000;

            break;

        case POWERPC_EXCP_INVAL:

            LOG_EXCP("Invalid instruction at " TARGET_FMT_lx "\n", env->nip);

            if (lpes1 == 0)

                new_msr |= (target_ulong)MSR_HVB;

            msr |= 0x00080000;

            break;

        case POWERPC_EXCP_PRIV:

            if (lpes1 == 0)

                new_msr |= (target_ulong)MSR_HVB;

            msr |= 0x00040000;

            break;

        case POWERPC_EXCP_TRAP:

            if (lpes1 == 0)

                new_msr |= (target_ulong)MSR_HVB;

            msr |= 0x00020000;

            break;

        default:

            /* Should never occur */

            cpu_abort(env, "Invalid program exception %d. Aborting\n",

                      env->error_code);

            break;

        }

        goto store_current;

    case POWERPC_EXCP_FPU:       /* Floating-point unavailable exception     */

        if (lpes1 == 0)

            new_msr |= (target_ulong)MSR_HVB;

        goto store_current;

    case POWERPC_EXCP_SYSCALL:   /* System call exception                    */

        /* NOTE: this is a temporary hack to support graphics OSI

           calls from the MOL driver */

        /* XXX: To be removed */

        if (env->gpr[3] == 0x113724fa && env->gpr[4] == 0x77810f9b &&

            env->osi_call) {

            if (env->osi_call(env) != 0) {

                env->exception_index = POWERPC_EXCP_NONE;

                env->error_code = 0;

                return;

            }

        }

        dump_syscall(env);

        lev = env->error_code;

        if (lev == 1 || (lpes0 == 0 && lpes1 == 0))

            new_msr |= (target_ulong)MSR_HVB;

        goto store_next;

    case POWERPC_EXCP_APU:       /* Auxiliary processor unavailable          */

        goto store_current;

    case POWERPC_EXCP_DECR:      /* Decrementer exception                    */

        if (lpes1 == 0)

            new_msr |= (target_ulong)MSR_HVB;

        goto store_next;

    case POWERPC_EXCP_FIT:       /* Fixed-interval timer interrupt           */

        /* FIT on 4xx */

        LOG_EXCP("FIT exception\n");

        goto store_next;

    case POWERPC_EXCP_WDT:       /* Watchdog timer interrupt                 */

        LOG_EXCP("WDT exception\n");

        switch (excp_model) {

        case POWERPC_EXCP_BOOKE:

            srr0 = SPR_BOOKE_CSRR0;

            srr1 = SPR_BOOKE_CSRR1;

            break;

        default:

            break;

        }

        goto store_next;

    case POWERPC_EXCP_DTLB:      /* Data TLB error                           */

        goto store_next;

    case POWERPC_EXCP_ITLB:      /* Instruction TLB error                    */

        goto store_next;

    case POWERPC_EXCP_DEBUG:     /* Debug interrupt                          */

        switch (excp_model) {

        case POWERPC_EXCP_BOOKE:

            srr0 = SPR_BOOKE_DSRR0;

            srr1 = SPR_BOOKE_DSRR1;

            asrr0 = SPR_BOOKE_CSRR0;

            asrr1 = SPR_BOOKE_CSRR1;

            break;

        default:

            break;

        }

        /* XXX: TODO */

        cpu_abort(env, "Debug exception is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_SPEU:      /* SPE/embedded floating-point unavailable  */

        goto store_current;

    case POWERPC_EXCP_EFPDI:     /* Embedded floating-point data interrupt   */

        /* XXX: TODO */

        cpu_abort(env, "Embedded floating point data exception "

                  "is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_EFPRI:     /* Embedded floating-point round interrupt  */

        /* XXX: TODO */

        cpu_abort(env, "Embedded floating point round exception "

                  "is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_EPERFM:    /* Embedded performance monitor interrupt   */

        /* XXX: TODO */

        cpu_abort(env,

                  "Performance counter exception is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_DOORI:     /* Embedded doorbell interrupt              */

        /* XXX: TODO */

        cpu_abort(env,

                  "Embedded doorbell interrupt is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_DOORCI:    /* Embedded doorbell critical interrupt     */

        switch (excp_model) {

        case POWERPC_EXCP_BOOKE:

            srr0 = SPR_BOOKE_CSRR0;

            srr1 = SPR_BOOKE_CSRR1;

            break;

        default:

            break;

        }

        /* XXX: TODO */

        cpu_abort(env, "Embedded doorbell critical interrupt "

                  "is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_RESET:     /* System reset exception                   */

        if (msr_pow) {

            /* indicate that we resumed from power save mode */

            msr |= 0x10000;

        } else {

            new_msr &= ~((target_ulong)1 << MSR_ME);

        }



        if (0) {

            /* XXX: find a suitable condition to enable the hypervisor mode */

            new_msr |= (target_ulong)MSR_HVB;

        }

        goto store_next;

    case POWERPC_EXCP_DSEG:      /* Data segment exception                   */

        if (lpes1 == 0)

            new_msr |= (target_ulong)MSR_HVB;

        goto store_next;

    case POWERPC_EXCP_ISEG:      /* Instruction segment exception            */

        if (lpes1 == 0)

            new_msr |= (target_ulong)MSR_HVB;

        goto store_next;

    case POWERPC_EXCP_HDECR:     /* Hypervisor decrementer exception         */

        srr0 = SPR_HSRR0;

        srr1 = SPR_HSRR1;

        new_msr |= (target_ulong)MSR_HVB;

        new_msr |= env->msr & ((target_ulong)1 << MSR_RI);

        goto store_next;

    case POWERPC_EXCP_TRACE:     /* Trace exception                          */

        if (lpes1 == 0)

            new_msr |= (target_ulong)MSR_HVB;

        goto store_next;

    case POWERPC_EXCP_HDSI:      /* Hypervisor data storage exception        */

        srr0 = SPR_HSRR0;

        srr1 = SPR_HSRR1;

        new_msr |= (target_ulong)MSR_HVB;

        new_msr |= env->msr & ((target_ulong)1 << MSR_RI);

        goto store_next;

    case POWERPC_EXCP_HISI:      /* Hypervisor instruction storage exception */

        srr0 = SPR_HSRR0;

        srr1 = SPR_HSRR1;

        new_msr |= (target_ulong)MSR_HVB;

        new_msr |= env->msr & ((target_ulong)1 << MSR_RI);

        goto store_next;

    case POWERPC_EXCP_HDSEG:     /* Hypervisor data segment exception        */

        srr0 = SPR_HSRR0;

        srr1 = SPR_HSRR1;

        new_msr |= (target_ulong)MSR_HVB;

        new_msr |= env->msr & ((target_ulong)1 << MSR_RI);

        goto store_next;

    case POWERPC_EXCP_HISEG:     /* Hypervisor instruction segment exception */

        srr0 = SPR_HSRR0;

        srr1 = SPR_HSRR1;

        new_msr |= (target_ulong)MSR_HVB;

        new_msr |= env->msr & ((target_ulong)1 << MSR_RI);

        goto store_next;

    case POWERPC_EXCP_VPU:       /* Vector unavailable exception             */

        if (lpes1 == 0)

            new_msr |= (target_ulong)MSR_HVB;

        goto store_current;

    case POWERPC_EXCP_PIT:       /* Programmable interval timer interrupt    */

        LOG_EXCP("PIT exception\n");

        goto store_next;

    case POWERPC_EXCP_IO:        /* IO error exception                       */

        /* XXX: TODO */

        cpu_abort(env, "601 IO error exception is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_RUNM:      /* Run mode exception                       */

        /* XXX: TODO */

        cpu_abort(env, "601 run mode exception is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_EMUL:      /* Emulation trap exception                 */

        /* XXX: TODO */

        cpu_abort(env, "602 emulation trap exception "

                  "is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_IFTLB:     /* Instruction fetch TLB error              */

        if (lpes1 == 0) /* XXX: check this */

            new_msr |= (target_ulong)MSR_HVB;

        switch (excp_model) {

        case POWERPC_EXCP_602:

        case POWERPC_EXCP_603:

        case POWERPC_EXCP_603E:

        case POWERPC_EXCP_G2:

            goto tlb_miss_tgpr;

        case POWERPC_EXCP_7x5:

            goto tlb_miss;

        case POWERPC_EXCP_74xx:

            goto tlb_miss_74xx;

        default:

            cpu_abort(env, "Invalid instruction TLB miss exception\n");

            break;

        }

        break;

    case POWERPC_EXCP_DLTLB:     /* Data load TLB miss                       */

        if (lpes1 == 0) /* XXX: check this */

            new_msr |= (target_ulong)MSR_HVB;

        switch (excp_model) {

        case POWERPC_EXCP_602:

        case POWERPC_EXCP_603:

        case POWERPC_EXCP_603E:

        case POWERPC_EXCP_G2:

            goto tlb_miss_tgpr;

        case POWERPC_EXCP_7x5:

            goto tlb_miss;

        case POWERPC_EXCP_74xx:

            goto tlb_miss_74xx;

        default:

            cpu_abort(env, "Invalid data load TLB miss exception\n");

            break;

        }

        break;

    case POWERPC_EXCP_DSTLB:     /* Data store TLB miss                      */

        if (lpes1 == 0) /* XXX: check this */

            new_msr |= (target_ulong)MSR_HVB;

        switch (excp_model) {

        case POWERPC_EXCP_602:

        case POWERPC_EXCP_603:

        case POWERPC_EXCP_603E:

        case POWERPC_EXCP_G2:

        tlb_miss_tgpr:

            /* Swap temporary saved registers with GPRs */

            if (!(new_msr & ((target_ulong)1 << MSR_TGPR))) {

                new_msr |= (target_ulong)1 << MSR_TGPR;

                hreg_swap_gpr_tgpr(env);

            }

            goto tlb_miss;

        case POWERPC_EXCP_7x5:

        tlb_miss:

#if defined (DEBUG_SOFTWARE_TLB)

            if (qemu_log_enabled()) {

                const char *es;

                target_ulong *miss, *cmp;

                int en;

                if (excp == POWERPC_EXCP_IFTLB) {

                    es = "I";

                    en = 'I';

                    miss = &env->spr[SPR_IMISS];

                    cmp = &env->spr[SPR_ICMP];

                } else {

                    if (excp == POWERPC_EXCP_DLTLB)

                        es = "DL";

                    else

                        es = "DS";

                    en = 'D';

                    miss = &env->spr[SPR_DMISS];

                    cmp = &env->spr[SPR_DCMP];

                }

                qemu_log("6xx %sTLB miss: %cM " TARGET_FMT_lx " %cC "

                         TARGET_FMT_lx " H1 " TARGET_FMT_lx " H2 "

                         TARGET_FMT_lx " %08x\n", es, en, *miss, en, *cmp,

                         env->spr[SPR_HASH1], env->spr[SPR_HASH2],

                         env->error_code);

            }

#endif

            msr |= env->crf[0] << 28;

            msr |= env->error_code; /* key, D/I, S/L bits */

            /* Set way using a LRU mechanism */

            msr |= ((env->last_way + 1) & (env->nb_ways - 1)) << 17;

            break;

        case POWERPC_EXCP_74xx:

        tlb_miss_74xx:

#if defined (DEBUG_SOFTWARE_TLB)

            if (qemu_log_enabled()) {

                const char *es;

                target_ulong *miss, *cmp;

                int en;

                if (excp == POWERPC_EXCP_IFTLB) {

                    es = "I";

                    en = 'I';

                    miss = &env->spr[SPR_TLBMISS];

                    cmp = &env->spr[SPR_PTEHI];

                } else {

                    if (excp == POWERPC_EXCP_DLTLB)

                        es = "DL";

                    else

                        es = "DS";

                    en = 'D';

                    miss = &env->spr[SPR_TLBMISS];

                    cmp = &env->spr[SPR_PTEHI];

                }

                qemu_log("74xx %sTLB miss: %cM " TARGET_FMT_lx " %cC "

                         TARGET_FMT_lx " %08x\n", es, en, *miss, en, *cmp,

                         env->error_code);

            }

#endif

            msr |= env->error_code; /* key bit */

            break;

        default:

            cpu_abort(env, "Invalid data store TLB miss exception\n");

            break;

        }

        goto store_next;

    case POWERPC_EXCP_FPA:       /* Floating-point assist exception          */

        /* XXX: TODO */

        cpu_abort(env, "Floating point assist exception "

                  "is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_DABR:      /* Data address breakpoint                  */

        /* XXX: TODO */

        cpu_abort(env, "DABR exception is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_IABR:      /* Instruction address breakpoint           */

        /* XXX: TODO */

        cpu_abort(env, "IABR exception is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_SMI:       /* System management interrupt              */

        /* XXX: TODO */

        cpu_abort(env, "SMI exception is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_THERM:     /* Thermal interrupt                        */

        /* XXX: TODO */

        cpu_abort(env, "Thermal management exception "

                  "is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_PERFM:     /* Embedded performance monitor interrupt   */

        if (lpes1 == 0)

            new_msr |= (target_ulong)MSR_HVB;

        /* XXX: TODO */

        cpu_abort(env,

                  "Performance counter exception is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_VPUA:      /* Vector assist exception                  */

        /* XXX: TODO */

        cpu_abort(env, "VPU assist exception is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_SOFTP:     /* Soft patch exception                     */

        /* XXX: TODO */

        cpu_abort(env,

                  "970 soft-patch exception is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_MAINT:     /* Maintenance exception                    */

        /* XXX: TODO */

        cpu_abort(env,

                  "970 maintenance exception is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_MEXTBR:    /* Maskable external breakpoint             */

        /* XXX: TODO */

        cpu_abort(env, "Maskable external exception "

                  "is not implemented yet !\n");

        goto store_next;

    case POWERPC_EXCP_NMEXTBR:   /* Non maskable external breakpoint         */

        /* XXX: TODO */

        cpu_abort(env, "Non maskable external exception "

                  "is not implemented yet !\n");

        goto store_next;

    default:

    excp_invalid:

        cpu_abort(env, "Invalid PowerPC exception %d. Aborting\n", excp);

        break;

    store_current:

        /* save current instruction location */

        env->spr[srr0] = env->nip - 4;

        break;

    store_next:

        /* save next instruction location */

        env->spr[srr0] = env->nip;

        break;

    }

    /* Save MSR */

    env->spr[srr1] = msr;

    /* If any alternate SRR register are defined, duplicate saved values */

    if (asrr0 != -1)

        env->spr[asrr0] = env->spr[srr0];

    if (asrr1 != -1)

        env->spr[asrr1] = env->spr[srr1];

    /* If we disactivated any translation, flush TLBs */

    if (new_msr & ((1 << MSR_IR) | (1 << MSR_DR)))

        tlb_flush(env, 1);



    if (msr_ile) {

        new_msr |= (target_ulong)1 << MSR_LE;

    }



    /* Jump to handler */

    vector = env->excp_vectors[excp];

    if (vector == (target_ulong)-1ULL) {

        cpu_abort(env, "Raised an exception without defined vector %d\n",

                  excp);

    }

    vector |= env->excp_prefix;

#if defined(TARGET_PPC64)

    if (excp_model == POWERPC_EXCP_BOOKE) {

        if (!msr_icm) {

            vector = (uint32_t)vector;

        } else {

            new_msr |= (target_ulong)1 << MSR_CM;

        }

    } else {

        if (!msr_isf && !(env->mmu_model & POWERPC_MMU_64)) {

            vector = (uint32_t)vector;

        } else {

            new_msr |= (target_ulong)1 << MSR_SF;

        }

    }

#endif

    /* XXX: we don't use hreg_store_msr here as already have treated

     *      any special case that could occur. Just store MSR and update hflags

     */

    env->msr = new_msr & env->msr_mask;

    hreg_compute_hflags(env);

    env->nip = vector;

    /* Reset exception state */

    env->exception_index = POWERPC_EXCP_NONE;

    env->error_code = 0;



    if (env->mmu_model == POWERPC_MMU_BOOKE) {

        /* XXX: The BookE changes address space when switching modes,

                we should probably implement that as different MMU indexes,

                but for the moment we do it the slow way and flush all.  */

        tlb_flush(env, 1);

    }

}

static bool coroutine_fn wait_serialising_requests(BdrvTrackedRequest *self)

{

    BlockDriverState *bs = self->bs;

    BdrvTrackedRequest *req;

    bool retry;

    bool waited = false;



    if (!bs->serialising_in_flight) {

        return false;

    }



    do {

        retry = false;

        QLIST_FOREACH(req, &bs->tracked_requests, list) {

            if (req == self || (!req->serialising && !self->serialising)) {

                continue;

            }

            if (tracked_request_overlaps(req, self->overlap_offset,

                                         self->overlap_bytes))

            {

                /* Hitting this means there was a reentrant request, for

                 * example, a block driver issuing nested requests.  This must

                 * never happen since it means deadlock.

                 */

                assert(qemu_coroutine_self() != req->co);



                /* If the request is already (indirectly) waiting for us, or

                 * will wait for us as soon as it wakes up, then just go on

                 * (instead of producing a deadlock in the former case). */

                if (!req->waiting_for) {

                    self->waiting_for = req;

                    qemu_co_queue_wait(&req->wait_queue);

                    self->waiting_for = NULL;

                    retry = true;

                    waited = true;

                    break;

                }

            }

        }

    } while (retry);



    return waited;

}

static int usb_device_init(USBDevice *dev)

{

    USBDeviceClass *klass = USB_DEVICE_GET_CLASS(dev);

    if (klass->init) {

        return klass->init(dev);

    }

    return 0;

}

static int url_alloc_for_protocol(URLContext **puc, struct URLProtocol *up,

                                  const char *filename, int flags,

                                  const AVIOInterruptCB *int_cb)

{

    URLContext *uc;

    int err;



#if CONFIG_NETWORK

    if (up->flags & URL_PROTOCOL_FLAG_NETWORK && !ff_network_init())

        return AVERROR(EIO);

#endif

    uc = av_mallocz(sizeof(URLContext) + strlen(filename) + 1);

    if (!uc) {

        err = AVERROR(ENOMEM);

        goto fail;

    }

    uc->av_class = &ffurl_context_class;

    uc->filename = (char *)&uc[1];

    strcpy(uc->filename, filename);

    uc->prot            = up;

    uc->flags           = flags;

    uc->is_streamed     = 0; /* default = not streamed */

    uc->max_packet_size = 0; /* default: stream file */

    if (up->priv_data_size) {

        uc->priv_data = av_mallocz(up->priv_data_size);

        if (!uc->priv_data) {

            err = AVERROR(ENOMEM);

            goto fail;

        }

        if (up->priv_data_class) {

            *(const AVClass **)uc->priv_data = up->priv_data_class;

            av_opt_set_defaults(uc->priv_data);

        }

    }

    if (int_cb)

        uc->interrupt_callback = *int_cb;



    *puc = uc;

    return 0;

fail:

    *puc = NULL;

    if (uc)

        av_freep(&uc->priv_data);

    av_freep(&uc);

#if CONFIG_NETWORK

    if (up->flags & URL_PROTOCOL_FLAG_NETWORK)

        ff_network_close();

#endif

    return err;

}

static int rv10_decode_packet(AVCodecContext *avctx, const uint8_t *buf,

                              int buf_size, int buf_size2)

{

    RVDecContext *rv = avctx->priv_data;

    MpegEncContext *s = &rv->m;

    int mb_count, mb_pos, left, start_mb_x, active_bits_size, ret;



    active_bits_size = buf_size * 8;

    init_get_bits(&s->gb, buf, FFMAX(buf_size, buf_size2) * 8);

    if (s->codec_id == AV_CODEC_ID_RV10)

        mb_count = rv10_decode_picture_header(s);

    else

        mb_count = rv20_decode_picture_header(rv);

    if (mb_count < 0) {

        av_log(s->avctx, AV_LOG_ERROR, "HEADER ERROR\n");

        return AVERROR_INVALIDDATA;

    }



    if (s->mb_x >= s->mb_width ||

        s->mb_y >= s->mb_height) {

        av_log(s->avctx, AV_LOG_ERROR, "POS ERROR %d %d\n", s->mb_x, s->mb_y);

        return AVERROR_INVALIDDATA;

    }

    mb_pos = s->mb_y * s->mb_width + s->mb_x;

    left   = s->mb_width * s->mb_height - mb_pos;

    if (mb_count > left) {

        av_log(s->avctx, AV_LOG_ERROR, "COUNT ERROR\n");

        return AVERROR_INVALIDDATA;

    }



    if ((s->mb_x == 0 && s->mb_y == 0) || s->current_picture_ptr == NULL) {

        // FIXME write parser so we always have complete frames?

        if (s->current_picture_ptr) {

            ff_er_frame_end(&s->er);

            ff_mpv_frame_end(s);

            s->mb_x = s->mb_y = s->resync_mb_x = s->resync_mb_y = 0;

        }

        if ((ret = ff_mpv_frame_start(s, avctx)) < 0)

            return ret;

        ff_mpeg_er_frame_start(s);

    } else {

        if (s->current_picture_ptr->f->pict_type != s->pict_type) {

            av_log(s->avctx, AV_LOG_ERROR, "Slice type mismatch\n");

            return AVERROR_INVALIDDATA;

        }

    }



    av_dlog(avctx, "qscale=%d\n", s->qscale);



    /* default quantization values */

    if (s->codec_id == AV_CODEC_ID_RV10) {

        if (s->mb_y == 0)

            s->first_slice_line = 1;

    } else {

        s->first_slice_line = 1;

        s->resync_mb_x      = s->mb_x;

    }

    start_mb_x     = s->mb_x;

    s->resync_mb_y = s->mb_y;

    if (s->h263_aic) {

        s->y_dc_scale_table =

        s->c_dc_scale_table = ff_aic_dc_scale_table;

    } else {

        s->y_dc_scale_table =

        s->c_dc_scale_table = ff_mpeg1_dc_scale_table;

    }



    if (s->modified_quant)

        s->chroma_qscale_table = ff_h263_chroma_qscale_table;



    ff_set_qscale(s, s->qscale);



    s->rv10_first_dc_coded[0] = 0;

    s->rv10_first_dc_coded[1] = 0;

    s->rv10_first_dc_coded[2] = 0;

    s->block_wrap[0] =

    s->block_wrap[1] =

    s->block_wrap[2] =

    s->block_wrap[3] = s->b8_stride;

    s->block_wrap[4] =

    s->block_wrap[5] = s->mb_stride;

    ff_init_block_index(s);



    /* decode each macroblock */

    for (s->mb_num_left = mb_count; s->mb_num_left > 0; s->mb_num_left--) {

        int ret;

        ff_update_block_index(s);

        av_dlog(avctx, "**mb x=%d y=%d\n", s->mb_x, s->mb_y);



        s->mv_dir  = MV_DIR_FORWARD;

        s->mv_type = MV_TYPE_16X16;

        ret = ff_h263_decode_mb(s, s->block);



        // Repeat the slice end check from ff_h263_decode_mb with our active

        // bitstream size

        if (ret != SLICE_ERROR) {

            int v = show_bits(&s->gb, 16);



            if (get_bits_count(&s->gb) + 16 > active_bits_size)

                v >>= get_bits_count(&s->gb) + 16 - active_bits_size;



            if (!v)

                ret = SLICE_END;

        }

        if (ret != SLICE_ERROR && active_bits_size < get_bits_count(&s->gb) &&

            8 * buf_size2 >= get_bits_count(&s->gb)) {

            active_bits_size = buf_size2 * 8;

            av_log(avctx, AV_LOG_DEBUG, "update size from %d to %d\n",

                   8 * buf_size, active_bits_size);

            ret = SLICE_OK;

        }



        if (ret == SLICE_ERROR || active_bits_size < get_bits_count(&s->gb)) {

            av_log(s->avctx, AV_LOG_ERROR, "ERROR at MB %d %d\n", s->mb_x,

                   s->mb_y);

            return AVERROR_INVALIDDATA;

        }

        if (s->pict_type != AV_PICTURE_TYPE_B)

            ff_h263_update_motion_val(s);

        ff_mpv_decode_mb(s, s->block);

        if (s->loop_filter)

            ff_h263_loop_filter(s);



        if (++s->mb_x == s->mb_width) {

            s->mb_x = 0;

            s->mb_y++;

            ff_init_block_index(s);

        }

        if (s->mb_x == s->resync_mb_x)

            s->first_slice_line = 0;

        if (ret == SLICE_END)

            break;

    }



    ff_er_add_slice(&s->er, start_mb_x, s->resync_mb_y, s->mb_x - 1, s->mb_y,

                    ER_MB_END);



    return active_bits_size;

}

int bdrv_ioctl(BlockDriverState *bs, unsigned long int req, void *buf)

{

    BdrvIoctlCoData data = {

        .bs = bs,

        .req = req,

        .buf = buf,

        .ret = -EINPROGRESS,

    };



    if (qemu_in_coroutine()) {

        /* Fast-path if already in coroutine context */

        bdrv_co_ioctl_entry(&data);

    } else {

        Coroutine *co = qemu_coroutine_create(bdrv_co_ioctl_entry);



        qemu_coroutine_enter(co, &data);

        while (data.ret == -EINPROGRESS) {

            aio_poll(bdrv_get_aio_context(bs), true);

        }

    }

    return data.ret;

}

static void pxa2xx_timer_write(void *opaque, target_phys_addr_t offset,

                uint32_t value)

{

    int i, tm = 0;

    PXA2xxTimerInfo *s = (PXA2xxTimerInfo *) opaque;



    switch (offset) {

    case OSMR3:  tm ++;

    case OSMR2:  tm ++;

    case OSMR1:  tm ++;

    case OSMR0:

        s->timer[tm].value = value;

        pxa2xx_timer_update(s, qemu_get_clock(vm_clock));

        break;

    case OSMR11: tm ++;

    case OSMR10: tm ++;

    case OSMR9:  tm ++;

    case OSMR8:  tm ++;

    case OSMR7:  tm ++;

    case OSMR6:  tm ++;

    case OSMR5:  tm ++;

    case OSMR4:

        if (!pxa2xx_timer_has_tm4(s))

            goto badreg;

        s->tm4[tm].tm.value = value;

        pxa2xx_timer_update4(s, qemu_get_clock(vm_clock), tm);

        break;

    case OSCR:

        s->oldclock = s->clock;

        s->lastload = qemu_get_clock(vm_clock);

        s->clock = value;

        pxa2xx_timer_update(s, s->lastload);

        break;

    case OSCR11: tm ++;

    case OSCR10: tm ++;

    case OSCR9:  tm ++;

    case OSCR8:  tm ++;

    case OSCR7:  tm ++;

    case OSCR6:  tm ++;

    case OSCR5:  tm ++;

    case OSCR4:

        if (!pxa2xx_timer_has_tm4(s))

            goto badreg;

        s->tm4[tm].oldclock = s->tm4[tm].clock;

        s->tm4[tm].lastload = qemu_get_clock(vm_clock);

        s->tm4[tm].clock = value;

        pxa2xx_timer_update4(s, s->tm4[tm].lastload, tm);

        break;

    case OIER:

        s->irq_enabled = value & 0xfff;

        break;

    case OSSR:	/* Status register */

        s->events &= ~value;

        for (i = 0; i < 4; i ++, value >>= 1) {

            if (s->timer[i].level && (value & 1)) {

                s->timer[i].level = 0;

                qemu_irq_lower(s->timer[i].irq);

            }

        }

        if (pxa2xx_timer_has_tm4(s)) {

            for (i = 0; i < 8; i ++, value >>= 1)

                if (s->tm4[i].tm.level && (value & 1))

                    s->tm4[i].tm.level = 0;

            if (!(s->events & 0xff0))

                qemu_irq_lower(s->tm4->tm.irq);

        }

        break;

    case OWER:	/* XXX: Reset on OSMR3 match? */

        s->reset3 = value;

        break;

    case OMCR7:  tm ++;

    case OMCR6:  tm ++;

    case OMCR5:  tm ++;

    case OMCR4:

        if (!pxa2xx_timer_has_tm4(s))

            goto badreg;

        s->tm4[tm].control = value & 0x0ff;

        /* XXX Stop if running (shouldn't happen) */

        if ((value & (1 << 7)) || tm == 0)

            s->tm4[tm].freq = pxa2xx_timer4_freq[value & 7];

        else {

            s->tm4[tm].freq = 0;

            pxa2xx_timer_update4(s, qemu_get_clock(vm_clock), tm);

        }

        break;

    case OMCR11: tm ++;

    case OMCR10: tm ++;

    case OMCR9:  tm ++;

    case OMCR8:  tm += 4;

        if (!pxa2xx_timer_has_tm4(s))

            goto badreg;

        s->tm4[tm].control = value & 0x3ff;

        /* XXX Stop if running (shouldn't happen) */

        if ((value & (1 << 7)) || !(tm & 1))

            s->tm4[tm].freq =

                    pxa2xx_timer4_freq[(value & (1 << 8)) ?  0 : (value & 7)];

        else {

            s->tm4[tm].freq = 0;

            pxa2xx_timer_update4(s, qemu_get_clock(vm_clock), tm);

        }

        break;

    default:

    badreg:

        hw_error("pxa2xx_timer_write: Bad offset " REG_FMT "\n", offset);

    }

}

static void mipsnet_ioport_write(void *opaque, hwaddr addr,

                                 uint64_t val, unsigned int size)

{

    MIPSnetState *s = opaque;



    addr &= 0x3f;

    trace_mipsnet_write(addr, val);

    switch (addr) {

    case MIPSNET_TX_DATA_COUNT:

	s->tx_count = (val <= MAX_ETH_FRAME_SIZE) ? val : 0;

        s->tx_written = 0;

        break;

    case MIPSNET_INT_CTL:

        if (val & MIPSNET_INTCTL_TXDONE) {

            s->intctl &= ~MIPSNET_INTCTL_TXDONE;

        } else if (val & MIPSNET_INTCTL_RXDONE) {

            s->intctl &= ~MIPSNET_INTCTL_RXDONE;

        } else if (val & MIPSNET_INTCTL_TESTBIT) {

            mipsnet_reset(s);

            s->intctl |= MIPSNET_INTCTL_TESTBIT;

        } else if (!val) {

            /* ACK testbit interrupt, flag was cleared on read. */

        }

        s->busy = !!s->intctl;

        mipsnet_update_irq(s);

        if (mipsnet_can_receive(s->nic->ncs)) {

            qemu_flush_queued_packets(qemu_get_queue(s->nic));

        }

        break;

    case MIPSNET_TX_DATA_BUFFER:

        s->tx_buffer[s->tx_written++] = val;

        if (s->tx_written == s->tx_count) {

            /* Send buffer. */

            trace_mipsnet_send(s->tx_count);

            qemu_send_packet(qemu_get_queue(s->nic), s->tx_buffer, s->tx_count);

            s->tx_count = s->tx_written = 0;

            s->intctl |= MIPSNET_INTCTL_TXDONE;

            s->busy = 1;

            mipsnet_update_irq(s);

        }

        break;

    /* Read-only registers */

    case MIPSNET_DEV_ID:

    case MIPSNET_BUSY:

    case MIPSNET_RX_DATA_COUNT:

    case MIPSNET_INTERRUPT_INFO:

    case MIPSNET_RX_DATA_BUFFER:

    default:

        break;

    }

}

void ioinst_handle_stcrw(S390CPU *cpu, uint32_t ipb, uintptr_t ra)

{

    CRW crw;

    uint64_t addr;

    int cc;

    CPUS390XState *env = &cpu->env;

    uint8_t ar;



    addr = decode_basedisp_s(env, ipb, &ar);

    if (addr & 3) {

        s390_program_interrupt(env, PGM_SPECIFICATION, 4, ra);

        return;

    }



    cc = css_do_stcrw(&crw);

    /* 0 - crw stored, 1 - zeroes stored */



    if (s390_cpu_virt_mem_write(cpu, addr, ar, &crw, sizeof(crw)) == 0) {

        setcc(cpu, cc);

    } else if (cc == 0) {

        /* Write failed: requeue CRW since STCRW is a suppressing instruction */

        css_undo_stcrw(&crw);

    }

}

static void migrate_put_status(QDict *qdict, const char *name,

                               uint64_t trans, uint64_t rem, uint64_t total)

{

    QObject *obj;



    obj = qobject_from_jsonf("{ 'transferred': %" PRId64 ", "

                               "'remaining': %" PRId64 ", "

                               "'total': %" PRId64 " }", trans, rem, total);

    assert(obj != NULL);



    qdict_put_obj(qdict, name, obj);

}

static int parse_pixel_format(AVCodecContext *avctx)

{

    DDSContext *ctx = avctx->priv_data;

    GetByteContext *gbc = &ctx->gbc;

    char buf[32];

    uint32_t flags, fourcc, gimp_tag;

    enum DDSDXGIFormat dxgi;

    int size, bpp, r, g, b, a;

    int alpha_exponent, ycocg_classic, ycocg_scaled, normal_map, array;



    /* Alternative DDS implementations use reserved1 as custom header. */

    bytestream2_skip(gbc, 4 * 3);

    gimp_tag = bytestream2_get_le32(gbc);

    alpha_exponent = gimp_tag == MKTAG('A', 'E', 'X', 'P');

    ycocg_classic  = gimp_tag == MKTAG('Y', 'C', 'G', '1');

    ycocg_scaled   = gimp_tag == MKTAG('Y', 'C', 'G', '2');

    bytestream2_skip(gbc, 4 * 7);



    /* Now the real DDPF starts. */

    size = bytestream2_get_le32(gbc);

    if (size != 32) {

        av_log(avctx, AV_LOG_ERROR, "Invalid pixel format header %d.\n", size);

        return AVERROR_INVALIDDATA;

    }

    flags = bytestream2_get_le32(gbc);

    ctx->compressed = flags & DDPF_FOURCC;

    ctx->paletted   = flags & DDPF_PALETTE;

    normal_map      = flags & DDPF_NORMALMAP;

    fourcc = bytestream2_get_le32(gbc);



    if (ctx->compressed && ctx->paletted) {

        av_log(avctx, AV_LOG_WARNING,

               "Disabling invalid palette flag for compressed dds.\n");

        ctx->paletted = 0;

    }



    bpp = bytestream2_get_le32(gbc); // rgbbitcount

    r   = bytestream2_get_le32(gbc); // rbitmask

    g   = bytestream2_get_le32(gbc); // gbitmask

    b   = bytestream2_get_le32(gbc); // bbitmask

    a   = bytestream2_get_le32(gbc); // abitmask



    bytestream2_skip(gbc, 4); // caps

    bytestream2_skip(gbc, 4); // caps2

    bytestream2_skip(gbc, 4); // caps3

    bytestream2_skip(gbc, 4); // caps4

    bytestream2_skip(gbc, 4); // reserved2



    av_get_codec_tag_string(buf, sizeof(buf), fourcc);

    av_log(avctx, AV_LOG_VERBOSE, "fourcc %s bpp %d "

           "r 0x%x g 0x%x b 0x%x a 0x%x\n", buf, bpp, r, g, b, a);

    if (gimp_tag) {

        av_get_codec_tag_string(buf, sizeof(buf), gimp_tag);

        av_log(avctx, AV_LOG_VERBOSE, "and GIMP-DDS tag %s\n", buf);

    }



    if (ctx->compressed)

        avctx->pix_fmt = AV_PIX_FMT_RGBA;



    if (ctx->compressed) {

        switch (fourcc) {

        case MKTAG('D', 'X', 'T', '1'):

            ctx->tex_ratio = 8;

            ctx->tex_funct = ctx->texdsp.dxt1a_block;

            break;

        case MKTAG('D', 'X', 'T', '2'):

            ctx->tex_ratio = 16;

            ctx->tex_funct = ctx->texdsp.dxt2_block;

            break;

        case MKTAG('D', 'X', 'T', '3'):

            ctx->tex_ratio = 16;

            ctx->tex_funct = ctx->texdsp.dxt3_block;

            break;

        case MKTAG('D', 'X', 'T', '4'):

            ctx->tex_ratio = 16;

            ctx->tex_funct = ctx->texdsp.dxt4_block;

            break;

        case MKTAG('D', 'X', 'T', '5'):

            ctx->tex_ratio = 16;

            if (ycocg_scaled)

                ctx->tex_funct = ctx->texdsp.dxt5ys_block;

            else if (ycocg_classic)

                ctx->tex_funct = ctx->texdsp.dxt5y_block;

            else

                ctx->tex_funct = ctx->texdsp.dxt5_block;

            break;

        case MKTAG('R', 'X', 'G', 'B'):

            ctx->tex_ratio = 16;

            ctx->tex_funct = ctx->texdsp.dxt5_block;

            /* This format may be considered as a normal map,

             * but it is handled differently in a separate postproc. */

            ctx->postproc = DDS_SWIZZLE_RXGB;

            normal_map = 0;

            break;

        case MKTAG('A', 'T', 'I', '1'):

        case MKTAG('B', 'C', '4', 'U'):

            ctx->tex_ratio = 8;

            ctx->tex_funct = ctx->texdsp.rgtc1u_block;

            break;

        case MKTAG('B', 'C', '4', 'S'):

            ctx->tex_ratio = 8;

            ctx->tex_funct = ctx->texdsp.rgtc1s_block;

            break;

        case MKTAG('A', 'T', 'I', '2'):

            /* RGT2 variant with swapped R and G (3Dc)*/

            ctx->tex_ratio = 16;

            ctx->tex_funct = ctx->texdsp.dxn3dc_block;

            break;

        case MKTAG('B', 'C', '5', 'U'):

            ctx->tex_ratio = 16;

            ctx->tex_funct = ctx->texdsp.rgtc2u_block;

            break;

        case MKTAG('B', 'C', '5', 'S'):

            ctx->tex_ratio = 16;

            ctx->tex_funct = ctx->texdsp.rgtc2s_block;

            break;

        case MKTAG('U', 'Y', 'V', 'Y'):

            ctx->compressed = 0;

            avctx->pix_fmt = AV_PIX_FMT_UYVY422;

            break;

        case MKTAG('Y', 'U', 'Y', '2'):

            ctx->compressed = 0;

            avctx->pix_fmt = AV_PIX_FMT_YUYV422;

            break;

        case MKTAG('P', '8', ' ', ' '):

            /* ATI Palette8, same as normal palette */

            ctx->compressed = 0;

            ctx->paletted   = 1;

            avctx->pix_fmt  = AV_PIX_FMT_PAL8;

            break;

        case MKTAG('D', 'X', '1', '0'):

            /* DirectX 10 extra header */

            dxgi = bytestream2_get_le32(gbc);

            bytestream2_skip(gbc, 4); // resourceDimension

            bytestream2_skip(gbc, 4); // miscFlag

            array = bytestream2_get_le32(gbc);

            bytestream2_skip(gbc, 4); // miscFlag2



            if (array != 0)

                av_log(avctx, AV_LOG_VERBOSE,

                       "Found array of size %d (ignored).\n", array);



            /* Only BC[1-5] are actually compressed. */

            ctx->compressed = (dxgi >= 70) && (dxgi <= 84);



            av_log(avctx, AV_LOG_VERBOSE, "DXGI format %d.\n", dxgi);

            switch (dxgi) {

            /* RGB types. */

            case DXGI_FORMAT_R16G16B16A16_TYPELESS:

            case DXGI_FORMAT_R16G16B16A16_FLOAT:

            case DXGI_FORMAT_R16G16B16A16_UNORM:

            case DXGI_FORMAT_R16G16B16A16_UINT:

            case DXGI_FORMAT_R16G16B16A16_SNORM:

            case DXGI_FORMAT_R16G16B16A16_SINT:

                avctx->pix_fmt = AV_PIX_FMT_BGRA64;

                break;

            case DXGI_FORMAT_R8G8B8A8_UNORM_SRGB:

                avctx->colorspace = AVCOL_SPC_RGB;

            case DXGI_FORMAT_R8G8B8A8_TYPELESS:

            case DXGI_FORMAT_R8G8B8A8_UNORM:

            case DXGI_FORMAT_R8G8B8A8_UINT:

            case DXGI_FORMAT_R8G8B8A8_SNORM:

            case DXGI_FORMAT_R8G8B8A8_SINT:

                avctx->pix_fmt = AV_PIX_FMT_BGRA;

                break;

            case DXGI_FORMAT_B8G8R8A8_UNORM_SRGB:

                avctx->colorspace = AVCOL_SPC_RGB;

            case DXGI_FORMAT_B8G8R8A8_TYPELESS:

            case DXGI_FORMAT_B8G8R8A8_UNORM:

                avctx->pix_fmt = AV_PIX_FMT_RGBA;

                break;

            case DXGI_FORMAT_B8G8R8X8_UNORM_SRGB:

                avctx->colorspace = AVCOL_SPC_RGB;

            case DXGI_FORMAT_B8G8R8X8_TYPELESS:

            case DXGI_FORMAT_B8G8R8X8_UNORM:

                avctx->pix_fmt = AV_PIX_FMT_RGBA; // opaque

                break;

            case DXGI_FORMAT_B5G6R5_UNORM:

                avctx->pix_fmt = AV_PIX_FMT_RGB565LE;

                break;

            /* Texture types. */

            case DXGI_FORMAT_BC1_UNORM_SRGB:

                avctx->colorspace = AVCOL_SPC_RGB;

            case DXGI_FORMAT_BC1_TYPELESS:

            case DXGI_FORMAT_BC1_UNORM:

                ctx->tex_ratio = 8;

                ctx->tex_funct = ctx->texdsp.dxt1a_block;

                break;

            case DXGI_FORMAT_BC2_UNORM_SRGB:

                avctx->colorspace = AVCOL_SPC_RGB;

            case DXGI_FORMAT_BC2_TYPELESS:

            case DXGI_FORMAT_BC2_UNORM:

                ctx->tex_ratio = 16;

                ctx->tex_funct = ctx->texdsp.dxt3_block;

                break;

            case DXGI_FORMAT_BC3_UNORM_SRGB:

                avctx->colorspace = AVCOL_SPC_RGB;

            case DXGI_FORMAT_BC3_TYPELESS:

            case DXGI_FORMAT_BC3_UNORM:

                ctx->tex_ratio = 16;

                ctx->tex_funct = ctx->texdsp.dxt5_block;

                break;

            case DXGI_FORMAT_BC4_TYPELESS:

            case DXGI_FORMAT_BC4_UNORM:

                ctx->tex_ratio = 8;

                ctx->tex_funct = ctx->texdsp.rgtc1u_block;

                break;

            case DXGI_FORMAT_BC4_SNORM:

                ctx->tex_ratio = 8;

                ctx->tex_funct = ctx->texdsp.rgtc1s_block;

                break;

            case DXGI_FORMAT_BC5_TYPELESS:

            case DXGI_FORMAT_BC5_UNORM:

                ctx->tex_ratio = 16;

                ctx->tex_funct = ctx->texdsp.rgtc2u_block;

                break;

            case DXGI_FORMAT_BC5_SNORM:

                ctx->tex_ratio = 16;

                ctx->tex_funct = ctx->texdsp.rgtc2s_block;

                break;

            default:

                av_log(avctx, AV_LOG_ERROR,

                       "Unsupported DXGI format %d.\n", dxgi);

                return AVERROR_INVALIDDATA;

            }

            break;

        default:

            av_log(avctx, AV_LOG_ERROR, "Unsupported %s fourcc.\n", buf);

            return AVERROR_INVALIDDATA;

        }

    } else if (ctx->paletted) {

        if (bpp == 8) {

            avctx->pix_fmt = AV_PIX_FMT_PAL8;

        } else {

            av_log(avctx, AV_LOG_ERROR, "Unsupported palette bpp %d.\n", bpp);

            return AVERROR_INVALIDDATA;

        }

    } else {

        /*  8 bpp */

        if (bpp == 8 && r == 0xff && g == 0 && b == 0 && a == 0)

            avctx->pix_fmt = AV_PIX_FMT_GRAY8;

        else if (bpp == 8 && r == 0 && g == 0 && b == 0 && a == 0xff)

            avctx->pix_fmt = AV_PIX_FMT_GRAY8;

        /* 16 bpp */

        else if (bpp == 16 && r == 0xff && g == 0 && b == 0 && a == 0xff00)

            avctx->pix_fmt = AV_PIX_FMT_YA8;

        else if (bpp == 16 && r == 0xffff && g == 0 && b == 0 && a == 0)

            avctx->pix_fmt = AV_PIX_FMT_GRAY16LE;

        else if (bpp == 16 && r == 0x7c00 && g == 0x3e0 && b == 0x1f && a == 0)

            avctx->pix_fmt = AV_PIX_FMT_RGB555LE;

        else if (bpp == 16 && r == 0x7c00 && g == 0x3e0 && b == 0x1f && a == 0x8000)

            avctx->pix_fmt = AV_PIX_FMT_RGB555LE; // alpha ignored

        else if (bpp == 16 && r == 0xf800 && g == 0x7e0 && b == 0x1f && a == 0)

            avctx->pix_fmt = AV_PIX_FMT_RGB565LE;

        /* 24 bpp */

        else if (bpp == 24 && r == 0xff0000 && g == 0xff00 && b == 0xff && a == 0)

            avctx->pix_fmt = AV_PIX_FMT_BGR24;

        /* 32 bpp */

        else if (bpp == 32 && r == 0xff0000 && g == 0xff00 && b == 0xff && a == 0)

            avctx->pix_fmt = AV_PIX_FMT_BGRA; // opaque

        else if (bpp == 32 && r == 0xff && g == 0xff00 && b == 0xff0000 && a == 0)

            avctx->pix_fmt = AV_PIX_FMT_RGBA; // opaque

        else if (bpp == 32 && r == 0xff0000 && g == 0xff00 && b == 0xff && a == 0xff000000)

            avctx->pix_fmt = AV_PIX_FMT_BGRA;

        else if (bpp == 32 && r == 0xff && g == 0xff00 && b == 0xff0000 && a == 0xff000000)

            avctx->pix_fmt = AV_PIX_FMT_RGBA;

        /* give up */

        else {

            av_log(avctx, AV_LOG_ERROR, "Unknown pixel format "

                   "[bpp %d r 0x%x g 0x%x b 0x%x a 0x%x].\n", bpp, r, g, b, a);

            return AVERROR_INVALIDDATA;

        }

    }



    /* Set any remaining post-proc that should happen before frame is ready. */

    if (alpha_exponent)

        ctx->postproc = DDS_ALPHA_EXP;

    else if (normal_map)

        ctx->postproc = DDS_NORMAL_MAP;

    else if (ycocg_classic && !ctx->compressed)

        ctx->postproc = DDS_RAW_YCOCG;

    else if (avctx->pix_fmt == AV_PIX_FMT_YA8)

        ctx->postproc = DDS_SWAP_ALPHA;



    /* ATI/NVidia variants sometimes add swizzling in bpp. */

    switch (bpp) {

    case MKTAG('A', '2', 'X', 'Y'):

        ctx->postproc = DDS_SWIZZLE_A2XY;

        break;

    case MKTAG('x', 'G', 'B', 'R'):

        ctx->postproc = DDS_SWIZZLE_XGBR;

        break;

    case MKTAG('x', 'R', 'B', 'G'):

        ctx->postproc = DDS_SWIZZLE_XRBG;

        break;

    case MKTAG('R', 'B', 'x', 'G'):

        ctx->postproc = DDS_SWIZZLE_RBXG;

        break;

    case MKTAG('R', 'G', 'x', 'B'):

        ctx->postproc = DDS_SWIZZLE_RGXB;

        break;

    case MKTAG('R', 'x', 'B', 'G'):

        ctx->postproc = DDS_SWIZZLE_RXBG;

        break;

    case MKTAG('x', 'G', 'x', 'R'):

        ctx->postproc = DDS_SWIZZLE_XGXR;

        break;

    case MKTAG('A', '2', 'D', '5'):

        ctx->postproc = DDS_NORMAL_MAP;

        break;

    }



    return 0;

}

static int svc_decode_frame(AVCodecContext *avctx, void *data,

                            int *got_frame, AVPacket *avpkt)

{

    SVCContext *s = avctx->priv_data;

    SBufferInfo info = { 0 };

    uint8_t* ptrs[3];

    int linesize[3];

    AVFrame *avframe = data;

    DECODING_STATE state;



    state = (*s->decoder)->DecodeFrame2(s->decoder, avpkt->data, avpkt->size, ptrs, &info);

    if (state != dsErrorFree) {

        av_log(avctx, AV_LOG_ERROR, "DecodeFrame2 failed\n");

        return AVERROR_UNKNOWN;

    }

    if (info.iBufferStatus != 1) {

        av_log(avctx, AV_LOG_DEBUG, "No frame produced\n");

        return avpkt->size;

    }



    ff_set_dimensions(avctx, info.UsrData.sSystemBuffer.iWidth, info.UsrData.sSystemBuffer.iHeight);

    // The decoder doesn't (currently) support decoding into a user

    // provided buffer, so do a copy instead.

    if (ff_get_buffer(avctx, avframe, 0) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Unable to allocate buffer\n");

        return AVERROR(ENOMEM);

    }



    linesize[0] = info.UsrData.sSystemBuffer.iStride[0];

    linesize[1] = linesize[2] = info.UsrData.sSystemBuffer.iStride[1];

    av_image_copy(avframe->data, avframe->linesize, (const uint8_t **) ptrs, linesize, avctx->pix_fmt, avctx->width, avctx->height);



    avframe->pts     = avpkt->pts;

    avframe->pkt_dts = avpkt->dts;

#if FF_API_PKT_PTS

FF_DISABLE_DEPRECATION_WARNINGS

    avframe->pkt_pts = avpkt->pts;

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    *got_frame = 1;

    return avpkt->size;

}

PCIBus *pci_apb_init(target_phys_addr_t special_base,

                     target_phys_addr_t mem_base,

                     qemu_irq *ivec_irqs, PCIBus **bus2, PCIBus **bus3,

                     qemu_irq **pbm_irqs)

{

    DeviceState *dev;

    SysBusDevice *s;

    APBState *d;

    PCIDevice *pci_dev;

    PCIBridge *br;



    /* Ultrasparc PBM main bus */

    dev = qdev_create(NULL, "pbm");

    qdev_init_nofail(dev);

    s = sysbus_from_qdev(dev);

    /* apb_config */

    sysbus_mmio_map(s, 0, special_base);

    /* PCI configuration space */

    sysbus_mmio_map(s, 1, special_base + 0x1000000ULL);

    /* pci_ioport */

    sysbus_mmio_map(s, 2, special_base + 0x2000000ULL);

    d = FROM_SYSBUS(APBState, s);



    memory_region_init(&d->pci_mmio, "pci-mmio", 0x100000000ULL);

    memory_region_add_subregion(get_system_memory(), mem_base, &d->pci_mmio);



    d->bus = pci_register_bus(&d->busdev.qdev, "pci",

                              pci_apb_set_irq, pci_pbm_map_irq, d,

                              &d->pci_mmio,

                              get_system_io(),

                              0, 32);



    *pbm_irqs = d->pbm_irqs;

    d->ivec_irqs = ivec_irqs;



    pci_create_simple(d->bus, 0, "pbm-pci");



    /* APB secondary busses */

    pci_dev = pci_create_multifunction(d->bus, PCI_DEVFN(1, 0), true,

                                   "pbm-bridge");

    br = DO_UPCAST(PCIBridge, dev, pci_dev);

    pci_bridge_map_irq(br, "Advanced PCI Bus secondary bridge 1",

                       pci_apb_map_irq);

    qdev_init_nofail(&pci_dev->qdev);

    *bus2 = pci_bridge_get_sec_bus(br);



    pci_dev = pci_create_multifunction(d->bus, PCI_DEVFN(1, 1), true,

                                   "pbm-bridge");

    br = DO_UPCAST(PCIBridge, dev, pci_dev);

    pci_bridge_map_irq(br, "Advanced PCI Bus secondary bridge 2",

                       pci_apb_map_irq);

    qdev_init_nofail(&pci_dev->qdev);

    *bus3 = pci_bridge_get_sec_bus(br);



    return d->bus;

}

static int coroutine_fn bdrv_co_do_copy_on_readv(BlockDriverState *bs,

        int64_t sector_num, int nb_sectors, QEMUIOVector *qiov)

{

    /* Perform I/O through a temporary buffer so that users who scribble over

     * their read buffer while the operation is in progress do not end up

     * modifying the image file.  This is critical for zero-copy guest I/O

     * where anything might happen inside guest memory.

     */

    void *bounce_buffer;



    BlockDriver *drv = bs->drv;

    struct iovec iov;

    QEMUIOVector bounce_qiov;

    int64_t cluster_sector_num;

    int cluster_nb_sectors;

    size_t skip_bytes;

    int ret;



    /* Cover entire cluster so no additional backing file I/O is required when

     * allocating cluster in the image file.

     */

    bdrv_round_to_clusters(bs, sector_num, nb_sectors,

                           &cluster_sector_num, &cluster_nb_sectors);



    trace_bdrv_co_do_copy_on_readv(bs, sector_num, nb_sectors,

                                   cluster_sector_num, cluster_nb_sectors);



    iov.iov_len = cluster_nb_sectors * BDRV_SECTOR_SIZE;

    iov.iov_base = bounce_buffer = qemu_try_blockalign(bs, iov.iov_len);

    if (bounce_buffer == NULL) {

        ret = -ENOMEM;

        goto err;

    }



    qemu_iovec_init_external(&bounce_qiov, &iov, 1);



    ret = drv->bdrv_co_readv(bs, cluster_sector_num, cluster_nb_sectors,

                             &bounce_qiov);

    if (ret < 0) {

        goto err;

    }



    if (drv->bdrv_co_write_zeroes &&

        buffer_is_zero(bounce_buffer, iov.iov_len)) {

        ret = bdrv_co_do_write_zeroes(bs, cluster_sector_num,

                                      cluster_nb_sectors, 0);

    } else {

        /* This does not change the data on the disk, it is not necessary

         * to flush even in cache=writethrough mode.

         */

        ret = drv->bdrv_co_writev(bs, cluster_sector_num, cluster_nb_sectors,

                                  &bounce_qiov);

    }



    if (ret < 0) {

        /* It might be okay to ignore write errors for guest requests.  If this

         * is a deliberate copy-on-read then we don't want to ignore the error.

         * Simply report it in all cases.

         */

        goto err;

    }



    skip_bytes = (sector_num - cluster_sector_num) * BDRV_SECTOR_SIZE;

    qemu_iovec_from_buf(qiov, 0, bounce_buffer + skip_bytes,

                        nb_sectors * BDRV_SECTOR_SIZE);



err:

    qemu_vfree(bounce_buffer);

    return ret;

}

