static GArray *nvdimm_build_device_structure(void)

{

    GSList *device_list = nvdimm_get_plugged_device_list();

    GArray *structures = g_array_new(false, true /* clear */, 1);



    for (; device_list; device_list = device_list->next) {

        DeviceState *dev = device_list->data;



        /* build System Physical Address Range Structure. */

        nvdimm_build_structure_spa(structures, dev);



        /*

         * build Memory Device to System Physical Address Range Mapping

         * Structure.

         */

        nvdimm_build_structure_memdev(structures, dev);



        /* build NVDIMM Control Region Structure. */

        nvdimm_build_structure_dcr(structures, dev);

    }

    g_slist_free(device_list);



    return structures;

}

static void pflash_timer (void *opaque)

{

    pflash_t *pfl = opaque;



    DPRINTF("%s: command %02x done\n", __func__, pfl->cmd);

    /* Reset flash */

    pfl->status ^= 0x80;

    if (pfl->bypass) {

        pfl->wcycle = 2;

    } else {

        memory_region_rom_device_set_readable(&pfl->mem, true);

        pfl->wcycle = 0;

    }

    pfl->cmd = 0;

}

void  helper_evaluate_flags_mcp(void)

{

	uint32_t src;

	uint32_t dst;

	uint32_t res;

	uint32_t flags = 0;



	src = env->cc_src;

	dst = env->cc_dest;

	res = env->cc_result;



	if ((res & 0x80000000L) != 0L)

	{

		flags |= N_FLAG;

		if (((src & 0x80000000L) == 0L)

		    && ((dst & 0x80000000L) == 0L))

		{

			flags |= V_FLAG;

		}

		else if (((src & 0x80000000L) != 0L) &&

			 ((dst & 0x80000000L) != 0L))

		{

			flags |= R_FLAG;

		}

	}

	else

	{

		if (res == 0L)

			flags |= Z_FLAG;

		if (((src & 0x80000000L) != 0L)

		    && ((dst & 0x80000000L) != 0L))

			flags |= V_FLAG;

		if ((dst & 0x80000000L) != 0L

		    || (src & 0x80000000L) != 0L)

			flags |= R_FLAG;

	}



	evaluate_flags_writeback(flags);

}

static void gen_store_exclusive(DisasContext *s, int rd, int rt, int rt2,

                                TCGv_i64 inaddr, int size, int is_pair)

{

    /* if (env->exclusive_addr == addr && env->exclusive_val == [addr]

     *     && (!is_pair || env->exclusive_high == [addr + datasize])) {

     *     [addr] = {Rt};

     *     if (is_pair) {

     *         [addr + datasize] = {Rt2};

     *     }

     *     {Rd} = 0;

     * } else {

     *     {Rd} = 1;

     * }

     * env->exclusive_addr = -1;

     */

    int fail_label = gen_new_label();

    int done_label = gen_new_label();

    TCGv_i64 addr = tcg_temp_local_new_i64();

    TCGv_i64 tmp;



    /* Copy input into a local temp so it is not trashed when the

     * basic block ends at the branch insn.

     */

    tcg_gen_mov_i64(addr, inaddr);

    tcg_gen_brcond_i64(TCG_COND_NE, addr, cpu_exclusive_addr, fail_label);



    tmp = tcg_temp_new_i64();

    tcg_gen_qemu_ld_i64(tmp, addr, get_mem_index(s), MO_TE + size);

    tcg_gen_brcond_i64(TCG_COND_NE, tmp, cpu_exclusive_val, fail_label);

    tcg_temp_free_i64(tmp);



    if (is_pair) {

        TCGv_i64 addrhi = tcg_temp_new_i64();

        TCGv_i64 tmphi = tcg_temp_new_i64();



        tcg_gen_addi_i64(addrhi, addr, 1 << size);

        tcg_gen_qemu_ld_i64(tmphi, addrhi, get_mem_index(s), MO_TE + size);

        tcg_gen_brcond_i64(TCG_COND_NE, tmphi, cpu_exclusive_high, fail_label);



        tcg_temp_free_i64(tmphi);

        tcg_temp_free_i64(addrhi);

    }



    /* We seem to still have the exclusive monitor, so do the store */

    tcg_gen_qemu_st_i64(cpu_reg(s, rt), addr, get_mem_index(s), MO_TE + size);

    if (is_pair) {

        TCGv_i64 addrhi = tcg_temp_new_i64();



        tcg_gen_addi_i64(addrhi, addr, 1 << size);

        tcg_gen_qemu_st_i64(cpu_reg(s, rt2), addrhi,

                            get_mem_index(s), MO_TE + size);

        tcg_temp_free_i64(addrhi);

    }



    tcg_temp_free_i64(addr);



    tcg_gen_movi_i64(cpu_reg(s, rd), 0);

    tcg_gen_br(done_label);

    gen_set_label(fail_label);

    tcg_gen_movi_i64(cpu_reg(s, rd), 1);

    gen_set_label(done_label);

    tcg_gen_movi_i64(cpu_exclusive_addr, -1);



}

