static void tgq_decode_mb(TgqContext *s, int mb_y, int mb_x, const uint8_t **bs, const uint8_t *buf_end){

    int mode;

    int i;

    int8_t dc[6];



    mode = bytestream_get_byte(bs);

    if (mode>buf_end-*bs) {

        av_log(s->avctx, AV_LOG_ERROR, "truncated macroblock\n");

        return;

    }



    if (mode>12) {

        GetBitContext gb;

        init_get_bits(&gb, *bs, mode*8);

        for(i=0; i<6; i++)

            tgq_decode_block(s, s->block[i], &gb);

        tgq_idct_put_mb(s, s->block, mb_x, mb_y);

    }else{

        if (mode==3) {

            memset(dc, (*bs)[0], 4);

            dc[4] = (*bs)[1];

            dc[5] = (*bs)[2];

        }else if (mode==6) {

            memcpy(dc, *bs, 6);

        }else if (mode==12) {

            for(i=0; i<6; i++)

                dc[i] = (*bs)[i*2];

        }else{

            av_log(s->avctx, AV_LOG_ERROR, "unsupported mb mode %i\n", mode);

        }

        tgq_idct_put_mb_dconly(s, mb_x, mb_y, dc);

    }

    *bs += mode;

}

void ff_prores_idct(DCTELEM *block, const int16_t *qmat)

{

    int i;



    for (i = 0; i < 64; i++)

        block[i] *= qmat[i];



    for (i = 0; i < 8; i++)

        idctRowCondDC_10(block + i*8);



    for (i = 0; i < 64; i++)

        block[i] >>= 2;



    for (i = 0; i < 8; i++)

        idctSparseCol_10(block + i);

}

int bdrv_write(BlockDriverState *bs, int64_t sector_num,
               const uint8_t *buf, int nb_sectors)
{
    BlockDriver *drv = bs->drv;
    if (!bs->drv)
        return -ENOMEDIUM;
    if (bs->read_only)
        return -EACCES;
    if (drv->bdrv_pwrite) {
        int ret, len, count = 0;
        len = nb_sectors * 512;
        do {
            ret = drv->bdrv_pwrite(bs, sector_num * 512, buf, len - count);
            if (ret < 0) {
                printf("bdrv_write ret=%d\n", ret);
                return ret;
            }
            count += ret;
            buf += ret;
        } while (count != len);
        bs->wr_bytes += (unsigned) len;
        bs->wr_ops ++;
        return 0;
    }
    return drv->bdrv_write(bs, sector_num, buf, nb_sectors);
}

