        memcpy(&ioreq->req, RING_GET_REQUEST(&blkdev->rings.native, rc),

               sizeof(ioreq->req));

        break;

    case BLKIF_PROTOCOL_X86_32:

        blkif_get_x86_32_req(&ioreq->req,

                             RING_GET_REQUEST(&blkdev->rings.x86_32_part, rc));

