static void assign_storage(SCLPDevice *sclp, SCCB *sccb)

{

    MemoryRegion *mr = NULL;

    uint64_t this_subregion_size;

    AssignStorage *assign_info = (AssignStorage *) sccb;

    sclpMemoryHotplugDev *mhd = get_sclp_memory_hotplug_dev();

    assert(mhd);

    ram_addr_t assign_addr = (assign_info->rn - 1) * mhd->rzm;

    MemoryRegion *sysmem = get_system_memory();



    if ((assign_addr % MEM_SECTION_SIZE == 0) &&

        (assign_addr >= mhd->padded_ram_size)) {

        /* Re-use existing memory region if found */

        mr = memory_region_find(sysmem, assign_addr, 1).mr;

        memory_region_unref(mr);

        if (!mr) {



            MemoryRegion *standby_ram = g_new(MemoryRegion, 1);



            /* offset to align to standby_subregion_size for allocation */

            ram_addr_t offset = assign_addr -

                                (assign_addr - mhd->padded_ram_size)

                                % mhd->standby_subregion_size;



            /* strlen("standby.ram") + 4 (Max of KVM_MEMORY_SLOTS) +  NULL */

            char id[16];

            snprintf(id, 16, "standby.ram%d",

                     (int)((offset - mhd->padded_ram_size) /

                     mhd->standby_subregion_size) + 1);



            /* Allocate a subregion of the calculated standby_subregion_size */

            if (offset + mhd->standby_subregion_size >

                mhd->padded_ram_size + mhd->standby_mem_size) {

                this_subregion_size = mhd->padded_ram_size +

                  mhd->standby_mem_size - offset;

            } else {

                this_subregion_size = mhd->standby_subregion_size;

            }



            memory_region_init_ram(standby_ram, NULL, id, this_subregion_size, &error_abort);

            /* This is a hack to make memory hotunplug work again. Once we have

             * subdevices, we have to unparent them when unassigning memory,

             * instead of doing it via the ref count of the MemoryRegion. */

            object_ref(OBJECT(standby_ram));

            object_unparent(OBJECT(standby_ram));

            vmstate_register_ram_global(standby_ram);

            memory_region_add_subregion(sysmem, offset, standby_ram);

        }

        /* The specified subregion is no longer in standby */

        mhd->standby_state_map[(assign_addr - mhd->padded_ram_size)

                               / MEM_SECTION_SIZE] = 1;

    }

    sccb->h.response_code = cpu_to_be16(SCLP_RC_NORMAL_COMPLETION);

}

static void dump_aml_files(test_data *data)

{

    AcpiSdtTable *sdt;

    GError *error = NULL;

    gint fd;

    ssize_t ret;

    int i;



    for (i = 0; i < data->ssdt_tables->len; ++i) {

        sdt = &g_array_index(data->ssdt_tables, AcpiSdtTable, i);

        g_assert(sdt->aml);



        fd = g_file_open_tmp("aml-XXXXXX", &sdt->aml_file, &error);

        g_assert_no_error(error);



        ret = qemu_write_full(fd, sdt, sizeof(AcpiTableHeader));

        g_assert(ret == sizeof(AcpiTableHeader));

        ret = qemu_write_full(fd, sdt->aml, sdt->aml_len);

        g_assert(ret == sdt->aml_len);



        close(fd);

    }

}

void ff_er_frame_end(MpegEncContext *s){

    int i, mb_x, mb_y, error, error_type, dc_error, mv_error, ac_error;

    int distance;

    int threshold_part[4]= {100,100,100};

    int threshold= 50;

    int is_intra_likely;

    int size = s->b8_stride * 2 * s->mb_height;

    Picture *pic= s->current_picture_ptr;



    if(!s->error_recognition || s->error_count==0 || s->avctx->lowres ||

       s->avctx->hwaccel ||

       s->avctx->codec->capabilities&CODEC_CAP_HWACCEL_VDPAU ||


       s->error_count==3*s->mb_width*(s->avctx->skip_top + s->avctx->skip_bottom)) return;



    if(s->current_picture.motion_val[0] == NULL){

        av_log(s->avctx, AV_LOG_ERROR, "Warning MVs not available\n");



        for(i=0; i<2; i++){

            pic->ref_index[i]= av_mallocz(size * sizeof(uint8_t));

            pic->motion_val_base[i]= av_mallocz((size+4) * 2 * sizeof(uint16_t));

            pic->motion_val[i]= pic->motion_val_base[i]+4;

        }

        pic->motion_subsample_log2= 3;

        s->current_picture= *s->current_picture_ptr;

    }



    for(i=0; i<2; i++){

        if(pic->ref_index[i])

            memset(pic->ref_index[i], 0, size * sizeof(uint8_t));

    }



    if(s->avctx->debug&FF_DEBUG_ER){

        for(mb_y=0; mb_y<s->mb_height; mb_y++){

            for(mb_x=0; mb_x<s->mb_width; mb_x++){

                int status= s->error_status_table[mb_x + mb_y*s->mb_stride];



                av_log(s->avctx, AV_LOG_DEBUG, "%2X ", status);

            }

            av_log(s->avctx, AV_LOG_DEBUG, "\n");

        }

    }



#if 1

    /* handle overlapping slices */

    for(error_type=1; error_type<=3; error_type++){

        int end_ok=0;



        for(i=s->mb_num-1; i>=0; i--){

            const int mb_xy= s->mb_index2xy[i];

            int error= s->error_status_table[mb_xy];



            if(error&(1<<error_type))

                end_ok=1;

            if(error&(8<<error_type))

                end_ok=1;



            if(!end_ok)

                s->error_status_table[mb_xy]|= 1<<error_type;



            if(error&VP_START)

                end_ok=0;

        }

    }

#endif

#if 1

    /* handle slices with partitions of different length */

    if(s->partitioned_frame){

        int end_ok=0;



        for(i=s->mb_num-1; i>=0; i--){

            const int mb_xy= s->mb_index2xy[i];

            int error= s->error_status_table[mb_xy];



            if(error&AC_END)

                end_ok=0;

            if((error&MV_END) || (error&DC_END) || (error&AC_ERROR))

                end_ok=1;



            if(!end_ok)

                s->error_status_table[mb_xy]|= AC_ERROR;



            if(error&VP_START)

                end_ok=0;

        }

    }

#endif

    /* handle missing slices */

    if(s->error_recognition>=4){

        int end_ok=1;



        for(i=s->mb_num-2; i>=s->mb_width+100; i--){ //FIXME +100 hack

            const int mb_xy= s->mb_index2xy[i];

            int error1= s->error_status_table[mb_xy  ];

            int error2= s->error_status_table[s->mb_index2xy[i+1]];



            if(error1&VP_START)

                end_ok=1;



            if(   error2==(VP_START|DC_ERROR|AC_ERROR|MV_ERROR|AC_END|DC_END|MV_END)

               && error1!=(VP_START|DC_ERROR|AC_ERROR|MV_ERROR|AC_END|DC_END|MV_END)

               && ((error1&AC_END) || (error1&DC_END) || (error1&MV_END))){ //end & uninit

                end_ok=0;

            }



            if(!end_ok)

                s->error_status_table[mb_xy]|= DC_ERROR|AC_ERROR|MV_ERROR;

        }

    }



#if 1

    /* backward mark errors */

    distance=9999999;

    for(error_type=1; error_type<=3; error_type++){

        for(i=s->mb_num-1; i>=0; i--){

            const int mb_xy= s->mb_index2xy[i];

            int error= s->error_status_table[mb_xy];



            if(!s->mbskip_table[mb_xy]) //FIXME partition specific

                distance++;

            if(error&(1<<error_type))

                distance= 0;



            if(s->partitioned_frame){

                if(distance < threshold_part[error_type-1])

                    s->error_status_table[mb_xy]|= 1<<error_type;

            }else{

                if(distance < threshold)

                    s->error_status_table[mb_xy]|= 1<<error_type;

            }



            if(error&VP_START)

                distance= 9999999;

        }

    }

#endif



    /* forward mark errors */

    error=0;

    for(i=0; i<s->mb_num; i++){

        const int mb_xy= s->mb_index2xy[i];

        int old_error= s->error_status_table[mb_xy];



        if(old_error&VP_START)

            error= old_error& (DC_ERROR|AC_ERROR|MV_ERROR);

        else{

            error|= old_error& (DC_ERROR|AC_ERROR|MV_ERROR);

            s->error_status_table[mb_xy]|= error;

        }

    }

#if 1

    /* handle not partitioned case */

    if(!s->partitioned_frame){

        for(i=0; i<s->mb_num; i++){

            const int mb_xy= s->mb_index2xy[i];

            error= s->error_status_table[mb_xy];

            if(error&(AC_ERROR|DC_ERROR|MV_ERROR))

                error|= AC_ERROR|DC_ERROR|MV_ERROR;

            s->error_status_table[mb_xy]= error;

        }

    }

#endif



    dc_error= ac_error= mv_error=0;

    for(i=0; i<s->mb_num; i++){

        const int mb_xy= s->mb_index2xy[i];

        error= s->error_status_table[mb_xy];

        if(error&DC_ERROR) dc_error ++;

        if(error&AC_ERROR) ac_error ++;

        if(error&MV_ERROR) mv_error ++;

    }

    av_log(s->avctx, AV_LOG_INFO, "concealing %d DC, %d AC, %d MV errors\n", dc_error, ac_error, mv_error);



    is_intra_likely= is_intra_more_likely(s);



    /* set unknown mb-type to most likely */

    for(i=0; i<s->mb_num; i++){

        const int mb_xy= s->mb_index2xy[i];

        error= s->error_status_table[mb_xy];

        if(!((error&DC_ERROR) && (error&MV_ERROR)))

            continue;



        if(is_intra_likely)

            s->current_picture.mb_type[mb_xy]= MB_TYPE_INTRA4x4;

        else

            s->current_picture.mb_type[mb_xy]= MB_TYPE_16x16 | MB_TYPE_L0;

    }



    // change inter to intra blocks if no reference frames are available

    if (!s->last_picture.data[0] && !s->next_picture.data[0])

        for(i=0; i<s->mb_num; i++){

            const int mb_xy= s->mb_index2xy[i];

            if(!IS_INTRA(s->current_picture.mb_type[mb_xy]))

                s->current_picture.mb_type[mb_xy]= MB_TYPE_INTRA4x4;

        }



    /* handle inter blocks with damaged AC */

    for(mb_y=0; mb_y<s->mb_height; mb_y++){

        for(mb_x=0; mb_x<s->mb_width; mb_x++){

            const int mb_xy= mb_x + mb_y * s->mb_stride;

            const int mb_type= s->current_picture.mb_type[mb_xy];

            int dir = !s->last_picture.data[0];

            error= s->error_status_table[mb_xy];



            if(IS_INTRA(mb_type)) continue; //intra

            if(error&MV_ERROR) continue;              //inter with damaged MV

            if(!(error&AC_ERROR)) continue;           //undamaged inter



            s->mv_dir = dir ? MV_DIR_BACKWARD : MV_DIR_FORWARD;

            s->mb_intra=0;

            s->mb_skipped=0;

            if(IS_8X8(mb_type)){

                int mb_index= mb_x*2 + mb_y*2*s->b8_stride;

                int j;

                s->mv_type = MV_TYPE_8X8;

                for(j=0; j<4; j++){

                    s->mv[0][j][0] = s->current_picture.motion_val[dir][ mb_index + (j&1) + (j>>1)*s->b8_stride ][0];

                    s->mv[0][j][1] = s->current_picture.motion_val[dir][ mb_index + (j&1) + (j>>1)*s->b8_stride ][1];

                }

            }else{

                s->mv_type = MV_TYPE_16X16;

                s->mv[0][0][0] = s->current_picture.motion_val[dir][ mb_x*2 + mb_y*2*s->b8_stride ][0];

                s->mv[0][0][1] = s->current_picture.motion_val[dir][ mb_x*2 + mb_y*2*s->b8_stride ][1];

            }



            s->dsp.clear_blocks(s->block[0]);



            s->mb_x= mb_x;

            s->mb_y= mb_y;

            decode_mb(s);

        }

    }



    /* guess MVs */

    if(s->pict_type==FF_B_TYPE){

        for(mb_y=0; mb_y<s->mb_height; mb_y++){

            for(mb_x=0; mb_x<s->mb_width; mb_x++){

                int xy= mb_x*2 + mb_y*2*s->b8_stride;

                const int mb_xy= mb_x + mb_y * s->mb_stride;

                const int mb_type= s->current_picture.mb_type[mb_xy];

                error= s->error_status_table[mb_xy];



                if(IS_INTRA(mb_type)) continue;

                if(!(error&MV_ERROR)) continue;           //inter with undamaged MV

                if(!(error&AC_ERROR)) continue;           //undamaged inter



                s->mv_dir = MV_DIR_FORWARD|MV_DIR_BACKWARD;

                if(!s->last_picture.data[0]) s->mv_dir &= ~MV_DIR_FORWARD;

                if(!s->next_picture.data[0]) s->mv_dir &= ~MV_DIR_BACKWARD;

                s->mb_intra=0;

                s->mv_type = MV_TYPE_16X16;

                s->mb_skipped=0;



                if(s->pp_time){

                    int time_pp= s->pp_time;

                    int time_pb= s->pb_time;



                    s->mv[0][0][0] = s->next_picture.motion_val[0][xy][0]*time_pb/time_pp;

                    s->mv[0][0][1] = s->next_picture.motion_val[0][xy][1]*time_pb/time_pp;

                    s->mv[1][0][0] = s->next_picture.motion_val[0][xy][0]*(time_pb - time_pp)/time_pp;

                    s->mv[1][0][1] = s->next_picture.motion_val[0][xy][1]*(time_pb - time_pp)/time_pp;

                }else{

                    s->mv[0][0][0]= 0;

                    s->mv[0][0][1]= 0;

                    s->mv[1][0][0]= 0;

                    s->mv[1][0][1]= 0;

                }



                s->dsp.clear_blocks(s->block[0]);

                s->mb_x= mb_x;

                s->mb_y= mb_y;

                decode_mb(s);

            }

        }

    }else

        guess_mv(s);



    /* the filters below are not XvMC compatible, skip them */

    if(CONFIG_MPEG_XVMC_DECODER && s->avctx->xvmc_acceleration)

        goto ec_clean;

    /* fill DC for inter blocks */

    for(mb_y=0; mb_y<s->mb_height; mb_y++){

        for(mb_x=0; mb_x<s->mb_width; mb_x++){

            int dc, dcu, dcv, y, n;

            int16_t *dc_ptr;

            uint8_t *dest_y, *dest_cb, *dest_cr;

            const int mb_xy= mb_x + mb_y * s->mb_stride;

            const int mb_type= s->current_picture.mb_type[mb_xy];



            error= s->error_status_table[mb_xy];



            if(IS_INTRA(mb_type) && s->partitioned_frame) continue;

//            if(error&MV_ERROR) continue; //inter data damaged FIXME is this good?



            dest_y = s->current_picture.data[0] + mb_x*16 + mb_y*16*s->linesize;

            dest_cb= s->current_picture.data[1] + mb_x*8  + mb_y*8 *s->uvlinesize;

            dest_cr= s->current_picture.data[2] + mb_x*8  + mb_y*8 *s->uvlinesize;



            dc_ptr= &s->dc_val[0][mb_x*2 + mb_y*2*s->b8_stride];

            for(n=0; n<4; n++){

                dc=0;

                for(y=0; y<8; y++){

                    int x;

                    for(x=0; x<8; x++){

                       dc+= dest_y[x + (n&1)*8 + (y + (n>>1)*8)*s->linesize];

                    }

                }

                dc_ptr[(n&1) + (n>>1)*s->b8_stride]= (dc+4)>>3;

            }



            dcu=dcv=0;

            for(y=0; y<8; y++){

                int x;

                for(x=0; x<8; x++){

                    dcu+=dest_cb[x + y*(s->uvlinesize)];

                    dcv+=dest_cr[x + y*(s->uvlinesize)];

                }

            }

            s->dc_val[1][mb_x + mb_y*s->mb_stride]= (dcu+4)>>3;

            s->dc_val[2][mb_x + mb_y*s->mb_stride]= (dcv+4)>>3;

        }

    }

#if 1

    /* guess DC for damaged blocks */

    guess_dc(s, s->dc_val[0], s->mb_width*2, s->mb_height*2, s->b8_stride, 1);

    guess_dc(s, s->dc_val[1], s->mb_width  , s->mb_height  , s->mb_stride, 0);

    guess_dc(s, s->dc_val[2], s->mb_width  , s->mb_height  , s->mb_stride, 0);

#endif

    /* filter luma DC */

    filter181(s->dc_val[0], s->mb_width*2, s->mb_height*2, s->b8_stride);



#if 1

    /* render DC only intra */

    for(mb_y=0; mb_y<s->mb_height; mb_y++){

        for(mb_x=0; mb_x<s->mb_width; mb_x++){

            uint8_t *dest_y, *dest_cb, *dest_cr;

            const int mb_xy= mb_x + mb_y * s->mb_stride;

            const int mb_type= s->current_picture.mb_type[mb_xy];



            error= s->error_status_table[mb_xy];



            if(IS_INTER(mb_type)) continue;

            if(!(error&AC_ERROR)) continue;              //undamaged



            dest_y = s->current_picture.data[0] + mb_x*16 + mb_y*16*s->linesize;

            dest_cb= s->current_picture.data[1] + mb_x*8  + mb_y*8 *s->uvlinesize;

            dest_cr= s->current_picture.data[2] + mb_x*8  + mb_y*8 *s->uvlinesize;



            put_dc(s, dest_y, dest_cb, dest_cr, mb_x, mb_y);

        }

    }

#endif



    if(s->avctx->error_concealment&FF_EC_DEBLOCK){

        /* filter horizontal block boundaries */

        h_block_filter(s, s->current_picture.data[0], s->mb_width*2, s->mb_height*2, s->linesize  , 1);

        h_block_filter(s, s->current_picture.data[1], s->mb_width  , s->mb_height  , s->uvlinesize, 0);

        h_block_filter(s, s->current_picture.data[2], s->mb_width  , s->mb_height  , s->uvlinesize, 0);



        /* filter vertical block boundaries */

        v_block_filter(s, s->current_picture.data[0], s->mb_width*2, s->mb_height*2, s->linesize  , 1);

        v_block_filter(s, s->current_picture.data[1], s->mb_width  , s->mb_height  , s->uvlinesize, 0);

        v_block_filter(s, s->current_picture.data[2], s->mb_width  , s->mb_height  , s->uvlinesize, 0);

    }



ec_clean:

    /* clean a few tables */

    for(i=0; i<s->mb_num; i++){

        const int mb_xy= s->mb_index2xy[i];

        int error= s->error_status_table[mb_xy];



        if(s->pict_type!=FF_B_TYPE && (error&(DC_ERROR|MV_ERROR|AC_ERROR))){

            s->mbskip_table[mb_xy]=0;

        }

        s->mbintra_table[mb_xy]=1;

    }

}

static int matroska_deliver_packet(MatroskaDemuxContext *matroska,

                                   AVPacket *pkt)

{

    if (matroska->num_packets > 0) {

        memcpy(pkt, matroska->packets[0], sizeof(AVPacket));

        av_free(matroska->packets[0]);

        if (matroska->num_packets > 1) {

            memmove(&matroska->packets[0], &matroska->packets[1],

                    (matroska->num_packets - 1) * sizeof(AVPacket *));

            matroska->packets =

                av_realloc(matroska->packets, (matroska->num_packets - 1) *

                           sizeof(AVPacket *));

        } else {

            av_freep(&matroska->packets);

        }

        matroska->num_packets--;

        return 0;

    }



    return -1;

}

static int vc1_parse_init(AVCodecParserContext *s)

{

    VC1ParseContext *vpc = s->priv_data;

    vpc->v.s.slice_context_count = 1;

    return 0;

}

static int decode_simple_internal(AVCodecContext *avctx, AVFrame *frame)

{

    AVCodecInternal   *avci = avctx->internal;

    DecodeSimpleContext *ds = &avci->ds;

    AVPacket           *pkt = ds->in_pkt;

    // copy to ensure we do not change pkt

    AVPacket tmp;

    int got_frame, actual_got_frame, did_split;

    int ret;



    if (!pkt->data && !avci->draining) {

        av_packet_unref(pkt);

        ret = ff_decode_get_packet(avctx, pkt);

        if (ret < 0 && ret != AVERROR_EOF)

            return ret;

    }



    // Some codecs (at least wma lossless) will crash when feeding drain packets

    // after EOF was signaled.

    if (avci->draining_done)

        return AVERROR_EOF;



    if (!pkt->data &&

        !(avctx->codec->capabilities & AV_CODEC_CAP_DELAY ||

          avctx->active_thread_type & FF_THREAD_FRAME))

        return AVERROR_EOF;



    tmp = *pkt;

#if FF_API_MERGE_SD

FF_DISABLE_DEPRECATION_WARNINGS

    did_split = av_packet_split_side_data(&tmp);



    if (did_split) {

        ret = extract_packet_props(avctx->internal, &tmp);

        if (ret < 0)

            return ret;



        ret = apply_param_change(avctx, &tmp);

        if (ret < 0)

            return ret;

    }

FF_ENABLE_DEPRECATION_WARNINGS

#endif



    got_frame = 0;



    if (HAVE_THREADS && avctx->active_thread_type & FF_THREAD_FRAME) {

        ret = ff_thread_decode_frame(avctx, frame, &got_frame, &tmp);

    } else {

        ret = avctx->codec->decode(avctx, frame, &got_frame, &tmp);



        if (avctx->codec->type == AVMEDIA_TYPE_VIDEO) {

            if (!(avctx->codec->caps_internal & FF_CODEC_CAP_SETS_PKT_DTS))

                frame->pkt_dts = pkt->dts;

            if(!avctx->has_b_frames)

                frame->pkt_pos = pkt->pos;

            //FIXME these should be under if(!avctx->has_b_frames)

            /* get_buffer is supposed to set frame parameters */

            if (!(avctx->codec->capabilities & AV_CODEC_CAP_DR1)) {

                if (!frame->sample_aspect_ratio.num)  frame->sample_aspect_ratio = avctx->sample_aspect_ratio;

                if (!frame->width)                    frame->width               = avctx->width;

                if (!frame->height)                   frame->height              = avctx->height;

                if (frame->format == AV_PIX_FMT_NONE) frame->format              = avctx->pix_fmt;

            }

        } else if (avctx->codec->type == AVMEDIA_TYPE_AUDIO) {

            frame->pkt_dts = pkt->dts;

        }

    }

    emms_c();

    actual_got_frame = got_frame;



    if (avctx->codec->type == AVMEDIA_TYPE_VIDEO) {

        if (frame->flags & AV_FRAME_FLAG_DISCARD)

            got_frame = 0;

        if (got_frame)

            frame->best_effort_timestamp = guess_correct_pts(avctx,

                                                             frame->pts,

                                                             frame->pkt_dts);

    } else if (avctx->codec->type == AVMEDIA_TYPE_AUDIO) {

        uint8_t *side;

        int side_size;

        uint32_t discard_padding = 0;

        uint8_t skip_reason = 0;

        uint8_t discard_reason = 0;



        if (ret >= 0 && got_frame) {

            frame->best_effort_timestamp = guess_correct_pts(avctx,

                                                             frame->pts,

                                                             frame->pkt_dts);

            if (frame->format == AV_SAMPLE_FMT_NONE)

                frame->format = avctx->sample_fmt;

            if (!frame->channel_layout)

                frame->channel_layout = avctx->channel_layout;

            if (!frame->channels)

                frame->channels = avctx->channels;

            if (!frame->sample_rate)

                frame->sample_rate = avctx->sample_rate;

        }



        side= av_packet_get_side_data(pkt, AV_PKT_DATA_SKIP_SAMPLES, &side_size);

        if(side && side_size>=10) {

            avctx->internal->skip_samples = AV_RL32(side) * avctx->internal->skip_samples_multiplier;

            discard_padding = AV_RL32(side + 4);

            av_log(avctx, AV_LOG_DEBUG, "skip %d / discard %d samples due to side data\n",

                   avctx->internal->skip_samples, (int)discard_padding);

            skip_reason = AV_RL8(side + 8);

            discard_reason = AV_RL8(side + 9);

        }



        if ((frame->flags & AV_FRAME_FLAG_DISCARD) && got_frame &&

            !(avctx->flags2 & AV_CODEC_FLAG2_SKIP_MANUAL)) {

            avctx->internal->skip_samples = FFMAX(0, avctx->internal->skip_samples - frame->nb_samples);

            got_frame = 0;

        }



        if (avctx->internal->skip_samples > 0 && got_frame &&

            !(avctx->flags2 & AV_CODEC_FLAG2_SKIP_MANUAL)) {

            if(frame->nb_samples <= avctx->internal->skip_samples){

                got_frame = 0;

                avctx->internal->skip_samples -= frame->nb_samples;

                av_log(avctx, AV_LOG_DEBUG, "skip whole frame, skip left: %d\n",

                       avctx->internal->skip_samples);

            } else {

                av_samples_copy(frame->extended_data, frame->extended_data, 0, avctx->internal->skip_samples,

                                frame->nb_samples - avctx->internal->skip_samples, avctx->channels, frame->format);

                if(avctx->pkt_timebase.num && avctx->sample_rate) {

                    int64_t diff_ts = av_rescale_q(avctx->internal->skip_samples,

                                                   (AVRational){1, avctx->sample_rate},

                                                   avctx->pkt_timebase);

                    if(frame->pts!=AV_NOPTS_VALUE)

                        frame->pts += diff_ts;

#if FF_API_PKT_PTS

FF_DISABLE_DEPRECATION_WARNINGS

                    if(frame->pkt_pts!=AV_NOPTS_VALUE)

                        frame->pkt_pts += diff_ts;

FF_ENABLE_DEPRECATION_WARNINGS

#endif

                    if(frame->pkt_dts!=AV_NOPTS_VALUE)

                        frame->pkt_dts += diff_ts;

                    if (frame->pkt_duration >= diff_ts)

                        frame->pkt_duration -= diff_ts;

                } else {

                    av_log(avctx, AV_LOG_WARNING, "Could not update timestamps for skipped samples.\n");

                }

                av_log(avctx, AV_LOG_DEBUG, "skip %d/%d samples\n",

                       avctx->internal->skip_samples, frame->nb_samples);

                frame->nb_samples -= avctx->internal->skip_samples;

                avctx->internal->skip_samples = 0;

            }

        }



        if (discard_padding > 0 && discard_padding <= frame->nb_samples && got_frame &&

            !(avctx->flags2 & AV_CODEC_FLAG2_SKIP_MANUAL)) {

            if (discard_padding == frame->nb_samples) {

                got_frame = 0;

            } else {

                if(avctx->pkt_timebase.num && avctx->sample_rate) {

                    int64_t diff_ts = av_rescale_q(frame->nb_samples - discard_padding,

                                                   (AVRational){1, avctx->sample_rate},

                                                   avctx->pkt_timebase);

                    frame->pkt_duration = diff_ts;

                } else {

                    av_log(avctx, AV_LOG_WARNING, "Could not update timestamps for discarded samples.\n");

                }

                av_log(avctx, AV_LOG_DEBUG, "discard %d/%d samples\n",

                       (int)discard_padding, frame->nb_samples);

                frame->nb_samples -= discard_padding;

            }

        }



        if ((avctx->flags2 & AV_CODEC_FLAG2_SKIP_MANUAL) && got_frame) {

            AVFrameSideData *fside = av_frame_new_side_data(frame, AV_FRAME_DATA_SKIP_SAMPLES, 10);

            if (fside) {

                AV_WL32(fside->data, avctx->internal->skip_samples);

                AV_WL32(fside->data + 4, discard_padding);

                AV_WL8(fside->data + 8, skip_reason);

                AV_WL8(fside->data + 9, discard_reason);

                avctx->internal->skip_samples = 0;

            }

        }

    }

#if FF_API_MERGE_SD

    if (did_split) {

        av_packet_free_side_data(&tmp);

        if(ret == tmp.size)

            ret = pkt->size;

    }

#endif



    if (avctx->codec->type == AVMEDIA_TYPE_AUDIO &&

        !avci->showed_multi_packet_warning &&

        ret >= 0 && ret != pkt->size && !(avctx->codec->capabilities & AV_CODEC_CAP_SUBFRAMES)) {

        av_log(avctx, AV_LOG_WARNING, "Multiple frames in a packet.\n");

        avci->showed_multi_packet_warning = 1;

    }



    if (!got_frame)

        av_frame_unref(frame);



    if (ret >= 0 && avctx->codec->type == AVMEDIA_TYPE_VIDEO && !(avctx->flags & AV_CODEC_FLAG_TRUNCATED))

        ret = pkt->size;



#if FF_API_AVCTX_TIMEBASE

    if (avctx->framerate.num > 0 && avctx->framerate.den > 0)

        avctx->time_base = av_inv_q(av_mul_q(avctx->framerate, (AVRational){avctx->ticks_per_frame, 1}));

#endif



    /* do not stop draining when actual_got_frame != 0 or ret < 0 */

    /* got_frame == 0 but actual_got_frame != 0 when frame is discarded */

    if (avctx->internal->draining && !actual_got_frame) {

        if (ret < 0) {

            /* prevent infinite loop if a decoder wrongly always return error on draining */

            /* reasonable nb_errors_max = maximum b frames + thread count */

            int nb_errors_max = 20 + (HAVE_THREADS && avctx->active_thread_type & FF_THREAD_FRAME ?

                                avctx->thread_count : 1);



            if (avci->nb_draining_errors++ >= nb_errors_max) {

                av_log(avctx, AV_LOG_ERROR, "Too many errors when draining, this is a bug. "

                       "Stop draining and force EOF.\n");

                avci->draining_done = 1;

                ret = AVERROR_BUG;

            }

        } else {

            avci->draining_done = 1;

        }

    }



    avci->compat_decode_consumed += ret;



    if (ret >= pkt->size || ret < 0) {

        av_packet_unref(pkt);

    } else {

        int consumed = ret;



        pkt->data                += consumed;

        pkt->size                -= consumed;

        avci->last_pkt_props->size -= consumed; // See extract_packet_props() comment.

        pkt->pts                  = AV_NOPTS_VALUE;

        pkt->dts                  = AV_NOPTS_VALUE;

        avci->last_pkt_props->pts = AV_NOPTS_VALUE;

        avci->last_pkt_props->dts = AV_NOPTS_VALUE;

    }



    if (got_frame)

        av_assert0(frame->buf[0]);



    return ret < 0 ? ret : 0;

}

static void sd_erase(SDState *sd)

{

    int i, start, end;

    if (!sd->erase_start || !sd->erase_end) {

        sd->card_status |= ERASE_SEQ_ERROR;

        return;

    }



    start = sd->erase_start >>

            (HWBLOCK_SHIFT + SECTOR_SHIFT + WPGROUP_SHIFT);

    end = sd->erase_end >>

            (HWBLOCK_SHIFT + SECTOR_SHIFT + WPGROUP_SHIFT);

    sd->erase_start = 0;

    sd->erase_end = 0;

    sd->csd[14] |= 0x40;



    for (i = start; i <= end; i ++)

        if (sd->wp_groups[i])

            sd->card_status |= WP_ERASE_SKIP;

}

static void tcg_init_vcpu(void *_env)

{

    CPUState *env = _env;

    /* share a single thread for all cpus with TCG */

    if (!tcg_cpu_thread) {

        env->thread = qemu_mallocz(sizeof(QemuThread));

        env->halt_cond = qemu_mallocz(sizeof(QemuCond));

        qemu_cond_init(env->halt_cond);

        qemu_thread_create(env->thread, tcg_cpu_thread_fn, env);

        while (env->created == 0)

            qemu_cond_timedwait(&qemu_cpu_cond, &qemu_global_mutex, 100);

        tcg_cpu_thread = env->thread;

        tcg_halt_cond = env->halt_cond;

    } else {

        env->thread = tcg_cpu_thread;

        env->halt_cond = tcg_halt_cond;

    }

}

static int nbd_negotiate_handle_list(NBDClient *client, uint32_t length,

                                     Error **errp)

{

    NBDExport *exp;



    if (length) {

        if (nbd_drop(client->ioc, length, errp) < 0) {

            return -EIO;

        }

        return nbd_negotiate_send_rep_err(client->ioc,

                                          NBD_REP_ERR_INVALID, NBD_OPT_LIST,

                                          errp,

                                          "OPT_LIST should not have length");

    }



    /* For each export, send a NBD_REP_SERVER reply. */

    QTAILQ_FOREACH(exp, &exports, next) {

        if (nbd_negotiate_send_rep_list(client->ioc, exp, errp)) {

            return -EINVAL;

        }

    }

    /* Finish with a NBD_REP_ACK. */

    return nbd_negotiate_send_rep(client->ioc, NBD_REP_ACK, NBD_OPT_LIST, errp);

}

