void qmp_dump_guest_memory(bool paging, const char *file, bool has_begin,

                           int64_t begin, bool has_length, int64_t length,

                           Error **errp)

{

    const char *p;

    int fd = -1;

    DumpState *s;

    int ret;



    if (has_begin && !has_length) {

        error_set(errp, QERR_MISSING_PARAMETER, "length");

        return;

    }

    if (!has_begin && has_length) {

        error_set(errp, QERR_MISSING_PARAMETER, "begin");

        return;

    }



#if !defined(WIN32)

    if (strstart(file, "fd:", &p)) {

        fd = monitor_get_fd(cur_mon, p, errp);

        if (fd == -1) {

            return;

        }

    }

#endif



    if  (strstart(file, "file:", &p)) {

        fd = qemu_open(p, O_WRONLY | O_CREAT | O_TRUNC | O_BINARY, S_IRUSR);

        if (fd < 0) {

            error_setg_file_open(errp, errno, p);

            return;

        }

    }



    if (fd == -1) {

        error_set(errp, QERR_INVALID_PARAMETER, "protocol");

        return;

    }



    s = g_malloc0(sizeof(DumpState));



    ret = dump_init(s, fd, paging, has_begin, begin, length, errp);

    if (ret < 0) {

        g_free(s);

        return;

    }



    if (create_vmcore(s) < 0 && !error_is_set(s->errp)) {

        error_set(errp, QERR_IO_ERROR);

    }



    g_free(s);

}

static bool spapr_drc_needed(void *opaque)

{

    sPAPRDRConnector *drc = (sPAPRDRConnector *)opaque;

    sPAPRDRConnectorClass *drck = SPAPR_DR_CONNECTOR_GET_CLASS(drc);



    /* If no dev is plugged in there is no need to migrate the DRC state */

    if (!drc->dev) {

        return false;

    }



    /*

     * We need to migrate the state if it's not equal to the expected

     * long-term state, which is the same as the coldplugged initial

     * state */

    return (drc->state != drck->ready_state);

}

int qcow2_snapshot_delete(BlockDriverState *bs,

                          const char *snapshot_id,

                          const char *name,

                          Error **errp)

{

    BDRVQcowState *s = bs->opaque;

    QCowSnapshot sn;

    int snapshot_index, ret;



    /* Search the snapshot */

    snapshot_index = find_snapshot_by_id_and_name(bs, snapshot_id, name);

    if (snapshot_index < 0) {

        error_setg(errp, "Can't find the snapshot");

        return -ENOENT;

    }

    sn = s->snapshots[snapshot_index];



    /* Remove it from the snapshot list */

    memmove(s->snapshots + snapshot_index,

            s->snapshots + snapshot_index + 1,

            (s->nb_snapshots - snapshot_index - 1) * sizeof(sn));

    s->nb_snapshots--;

    ret = qcow2_write_snapshots(bs);

    if (ret < 0) {

        error_setg(errp, "Failed to remove snapshot from snapshot list");

        return ret;

    }



    /*

     * The snapshot is now unused, clean up. If we fail after this point, we

     * won't recover but just leak clusters.

     */

    g_free(sn.id_str);

    g_free(sn.name);



    /*

     * Now decrease the refcounts of clusters referenced by the snapshot and

     * free the L1 table.

     */

    ret = qcow2_update_snapshot_refcount(bs, sn.l1_table_offset,

                                         sn.l1_size, -1);

    if (ret < 0) {

        error_setg(errp, "Failed to free the cluster and L1 table");

        return ret;

    }

    qcow2_free_clusters(bs, sn.l1_table_offset, sn.l1_size * sizeof(uint64_t),

                        QCOW2_DISCARD_SNAPSHOT);



    /* must update the copied flag on the current cluster offsets */

    ret = qcow2_update_snapshot_refcount(bs, s->l1_table_offset, s->l1_size, 0);

    if (ret < 0) {

        error_setg(errp, "Failed to update snapshot status in disk");

        return ret;

    }



#ifdef DEBUG_ALLOC

    {

        BdrvCheckResult result = {0};

        qcow2_check_refcounts(bs, &result, 0);

    }

#endif

    return 0;

}

int ff_raw_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    AVStream *st;

    enum CodecID id;



    st = av_new_stream(s, 0);

    if (!st)

        return AVERROR(ENOMEM);



        id = s->iformat->value;

        if (id == CODEC_ID_RAWVIDEO) {

            st->codec->codec_type = AVMEDIA_TYPE_VIDEO;

        } else {

            st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        }

        st->codec->codec_id = id;



        switch(st->codec->codec_type) {

        case AVMEDIA_TYPE_AUDIO: {

            RawAudioDemuxerContext *s1 = s->priv_data;



#if FF_API_FORMAT_PARAMETERS

            if (ap->sample_rate)

                st->codec->sample_rate = ap->sample_rate;

            if (ap->channels)

                st->codec->channels    = ap->channels;

            else st->codec->channels   = 1;

#endif



            if (s1->sample_rate)

                st->codec->sample_rate = s1->sample_rate;

            if (s1->channels)

                st->codec->channels    = s1->channels;



            st->codec->bits_per_coded_sample = av_get_bits_per_sample(st->codec->codec_id);

            assert(st->codec->bits_per_coded_sample > 0);

            st->codec->block_align = st->codec->bits_per_coded_sample*st->codec->channels/8;

            av_set_pts_info(st, 64, 1, st->codec->sample_rate);

            break;

            }

        case AVMEDIA_TYPE_VIDEO: {

            FFRawVideoDemuxerContext *s1 = s->priv_data;

            int width = 0, height = 0, ret;

            enum PixelFormat pix_fmt;



            if(ap->time_base.num)

                av_set_pts_info(st, 64, ap->time_base.num, ap->time_base.den);

            else

                av_set_pts_info(st, 64, 1, 25);

            if (s1->video_size && (ret = av_parse_video_size(&width, &height, s1->video_size)) < 0) {

                av_log(s, AV_LOG_ERROR, "Couldn't parse video size.\n");

                goto fail;

            }

            if ((pix_fmt = av_get_pix_fmt(s1->pixel_format)) == PIX_FMT_NONE) {

                av_log(s, AV_LOG_ERROR, "No such pixel format: %s.\n", s1->pixel_format);

                ret = AVERROR(EINVAL);

                goto fail;

            }

#if FF_API_FORMAT_PARAMETERS

            if (ap->width > 0)

                width = ap->width;

            if (ap->height > 0)

                height = ap->height;

            if (ap->pix_fmt)

                pix_fmt = ap->pix_fmt;

#endif

            st->codec->width  = width;

            st->codec->height = height;

            st->codec->pix_fmt = pix_fmt;

fail:

            av_freep(&s1->video_size);

            av_freep(&s1->pixel_format);

            return ret;

            }

        default:

            return -1;

        }

    return 0;

}

