static int ogg_packet(AVFormatContext *s, int *str, int *dstart, int *dsize,

                      int64_t *fpos)

{

    struct ogg *ogg = s->priv_data;

    int idx, i, ret;

    struct ogg_stream *os;

    int complete = 0;

    int segp = 0, psize = 0;



    av_dlog(s, "ogg_packet: curidx=%i\n", ogg->curidx);



    do{

        idx = ogg->curidx;



        while (idx < 0){

            ret = ogg_read_page(s, &idx);

            if (ret < 0)

                return ret;

        }



        os = ogg->streams + idx;



        av_dlog(s, "ogg_packet: idx=%d pstart=%d psize=%d segp=%d nsegs=%d\n",

                idx, os->pstart, os->psize, os->segp, os->nsegs);



        if (!os->codec){

            if (os->header < 0){

                os->codec = ogg_find_codec (os->buf, os->bufpos);

                if (!os->codec){

                    av_log(s, AV_LOG_WARNING, "Codec not found\n");

                    os->header = 0;

                    return 0;

                }

            }else{

                return 0;

            }

        }



        segp = os->segp;

        psize = os->psize;



        while (os->segp < os->nsegs){

            int ss = os->segments[os->segp++];

            os->psize += ss;

            if (ss < 255){

                complete = 1;

                break;

            }

        }



        if (!complete && os->segp == os->nsegs){

            ogg->curidx = -1;

            os->incomplete = 1;

        }

    }while (!complete);





    if (os->granule == -1)

        av_log(s, AV_LOG_WARNING, "Page at %"PRId64" is missing granule\n", os->page_pos);



    ogg->curidx = idx;

    os->incomplete = 0;



    if (os->header) {

        os->header = os->codec->header (s, idx);

        if (!os->header){

            os->segp = segp;

            os->psize = psize;



            // We have reached the first non-header packet in this stream.

            // Unfortunately more header packets may still follow for others,

            // but if we continue with header parsing we may lose data packets.

            ogg->headers = 1;



            // Update the header state for all streams and

            // compute the data_offset.

            if (!s->data_offset)

                s->data_offset = os->sync_pos;

            for (i = 0; i < ogg->nstreams; i++) {

                struct ogg_stream *cur_os = ogg->streams + i;



                // if we have a partial non-header packet, its start is

                // obviously at or after the data start

                if (cur_os->incomplete)

                    s->data_offset = FFMIN(s->data_offset, cur_os->sync_pos);

            }

        }else{

            os->pstart += os->psize;

            os->psize = 0;

        }

    } else {

        os->pflags = 0;

        os->pduration = 0;

        if (os->codec && os->codec->packet)

            os->codec->packet (s, idx);

        if (str)

            *str = idx;

        if (dstart)

            *dstart = os->pstart;

        if (dsize)

            *dsize = os->psize;

        if (fpos)

            *fpos = os->sync_pos;

        os->pstart += os->psize;

        os->psize = 0;

        if(os->pstart == os->bufpos)

            os->bufpos = os->pstart = 0;

        os->sync_pos = os->page_pos;

    }



    // determine whether there are more complete packets in this page

    // if not, the page's granule will apply to this packet

    os->page_end = 1;

    for (i = os->segp; i < os->nsegs; i++)

        if (os->segments[i] < 255) {

            os->page_end = 0;

            break;

        }



    if (os->segp == os->nsegs)

        ogg->curidx = -1;



    return 0;

}

static void migration_bitmap_sync(void)

{

    RAMBlock *block;

    uint64_t num_dirty_pages_init = migration_dirty_pages;

    MigrationState *s = migrate_get_current();

    int64_t end_time;

    int64_t bytes_xfer_now;



    bitmap_sync_count++;



    if (!bytes_xfer_prev) {

        bytes_xfer_prev = ram_bytes_transferred();

    }



    if (!start_time) {

        start_time = qemu_clock_get_ms(QEMU_CLOCK_REALTIME);

    }



    trace_migration_bitmap_sync_start();

    address_space_sync_dirty_bitmap(&address_space_memory);




    rcu_read_lock();

    QLIST_FOREACH_RCU(block, &ram_list.blocks, next) {

        migration_bitmap_sync_range(block->mr->ram_addr, block->used_length);

    }

    rcu_read_unlock();




    trace_migration_bitmap_sync_end(migration_dirty_pages

                                    - num_dirty_pages_init);

    num_dirty_pages_period += migration_dirty_pages - num_dirty_pages_init;

    end_time = qemu_clock_get_ms(QEMU_CLOCK_REALTIME);



    /* more than 1 second = 1000 millisecons */

    if (end_time > start_time + 1000) {

        if (migrate_auto_converge()) {

            /* The following detection logic can be refined later. For now:

               Check to see if the dirtied bytes is 50% more than the approx.

               amount of bytes that just got transferred since the last time we

               were in this routine. If that happens >N times (for now N==4)

               we turn on the throttle down logic */

            bytes_xfer_now = ram_bytes_transferred();

            if (s->dirty_pages_rate &&

               (num_dirty_pages_period * TARGET_PAGE_SIZE >

                   (bytes_xfer_now - bytes_xfer_prev)/2) &&

               (dirty_rate_high_cnt++ > 4)) {

                    trace_migration_throttle();

                    mig_throttle_on = true;

                    dirty_rate_high_cnt = 0;

             }

             bytes_xfer_prev = bytes_xfer_now;

        } else {

             mig_throttle_on = false;

        }

        if (migrate_use_xbzrle()) {

            if (iterations_prev != acct_info.iterations) {

                acct_info.xbzrle_cache_miss_rate =

                   (double)(acct_info.xbzrle_cache_miss -

                            xbzrle_cache_miss_prev) /

                   (acct_info.iterations - iterations_prev);

            }

            iterations_prev = acct_info.iterations;

            xbzrle_cache_miss_prev = acct_info.xbzrle_cache_miss;

        }

        s->dirty_pages_rate = num_dirty_pages_period * 1000

            / (end_time - start_time);

        s->dirty_bytes_rate = s->dirty_pages_rate * TARGET_PAGE_SIZE;

        start_time = end_time;

        num_dirty_pages_period = 0;

    }

    s->dirty_sync_count = bitmap_sync_count;

}

