        gen_set_label(l2);

        gen_eob(s);

    }

}

static int check_shm_size(IVShmemState *s, int fd) {

    /* check that the guest isn't going to try and map more memory than the

     * the object has allocated return -1 to indicate error */



    struct stat buf;



    fstat(fd, &buf);



    if (s->ivshmem_size > buf.st_size) {

        fprintf(stderr,

                "IVSHMEM ERROR: Requested memory size greater"

                " than shared object size (%" PRIu64 " > %" PRIu64")\n",

                s->ivshmem_size, (uint64_t)buf.st_size);

        return -1;

    } else {

        return 0;

    }

}

e1000e_rss_get_hash_type(E1000ECore *core, struct NetRxPkt *pkt)

{

    bool isip4, isip6, isudp, istcp;



    assert(e1000e_rss_enabled(core));



    net_rx_pkt_get_protocols(pkt, &isip4, &isip6, &isudp, &istcp);



    if (isip4) {

        bool fragment = net_rx_pkt_get_ip4_info(pkt)->fragment;



        trace_e1000e_rx_rss_ip4(fragment, istcp, core->mac[MRQC],

                                E1000_MRQC_EN_TCPIPV4(core->mac[MRQC]),

                                E1000_MRQC_EN_IPV4(core->mac[MRQC]));



        if (!fragment && istcp && E1000_MRQC_EN_TCPIPV4(core->mac[MRQC])) {

            return E1000_MRQ_RSS_TYPE_IPV4TCP;

        }



        if (E1000_MRQC_EN_IPV4(core->mac[MRQC])) {

            return E1000_MRQ_RSS_TYPE_IPV4;

        }

    } else if (isip6) {

        eth_ip6_hdr_info *ip6info = net_rx_pkt_get_ip6_info(pkt);



        bool ex_dis = core->mac[RFCTL] & E1000_RFCTL_IPV6_EX_DIS;

        bool new_ex_dis = core->mac[RFCTL] & E1000_RFCTL_NEW_IPV6_EXT_DIS;



        trace_e1000e_rx_rss_ip6(core->mac[RFCTL],

                                ex_dis, new_ex_dis, istcp,

                                ip6info->has_ext_hdrs,

                                ip6info->rss_ex_dst_valid,

                                ip6info->rss_ex_src_valid,

                                core->mac[MRQC],

                                E1000_MRQC_EN_TCPIPV6(core->mac[MRQC]),

                                E1000_MRQC_EN_IPV6EX(core->mac[MRQC]),

                                E1000_MRQC_EN_IPV6(core->mac[MRQC]));



        if ((!ex_dis || !ip6info->has_ext_hdrs) &&

            (!new_ex_dis || !(ip6info->rss_ex_dst_valid ||

                              ip6info->rss_ex_src_valid))) {



            if (istcp && !ip6info->fragment &&

                E1000_MRQC_EN_TCPIPV6(core->mac[MRQC])) {

                return E1000_MRQ_RSS_TYPE_IPV6TCP;

            }



            if (E1000_MRQC_EN_IPV6EX(core->mac[MRQC])) {

                return E1000_MRQ_RSS_TYPE_IPV6EX;

            }



        }



        if (E1000_MRQC_EN_IPV6(core->mac[MRQC])) {

            return E1000_MRQ_RSS_TYPE_IPV6;

        }



    }



    return E1000_MRQ_RSS_TYPE_NONE;

}

static void select_input_picture(MpegEncContext *s){

    int i;



    for(i=1; i<MAX_PICTURE_COUNT; i++)

        s->reordered_input_picture[i-1]= s->reordered_input_picture[i];

    s->reordered_input_picture[MAX_PICTURE_COUNT-1]= NULL;



    /* set next picture type & ordering */

    if(s->reordered_input_picture[0]==NULL && s->input_picture[0]){

        if(/*s->picture_in_gop_number >= s->gop_size ||*/ s->next_picture_ptr==NULL || s->intra_only){

            s->reordered_input_picture[0]= s->input_picture[0];

            s->reordered_input_picture[0]->pict_type= I_TYPE;

            s->reordered_input_picture[0]->coded_picture_number= s->coded_picture_number++;

        }else{

            int b_frames;



            if(s->avctx->frame_skip_threshold || s->avctx->frame_skip_factor){

                if(skip_check(s, s->input_picture[0], s->next_picture_ptr)){

//av_log(NULL, AV_LOG_DEBUG, "skip %p %Ld\n", s->input_picture[0]->data[0], s->input_picture[0]->pts);



                    if(s->input_picture[0]->type == FF_BUFFER_TYPE_SHARED){

                        for(i=0; i<4; i++)

                            s->input_picture[0]->data[i]= NULL;

                        s->input_picture[0]->type= 0;            

                    }else{

                        assert(   s->input_picture[0]->type==FF_BUFFER_TYPE_USER 

                               || s->input_picture[0]->type==FF_BUFFER_TYPE_INTERNAL);



                        s->avctx->release_buffer(s->avctx, (AVFrame*)s->input_picture[0]);

                    }



                    goto no_output_pic;

                }

            }



            if(s->flags&CODEC_FLAG_PASS2){

                for(i=0; i<s->max_b_frames+1; i++){

                    int pict_num= s->input_picture[0]->display_picture_number + i;



                    if(pict_num >= s->rc_context.num_entries) 

                        break;

                    if(!s->input_picture[i]){

                        s->rc_context.entry[pict_num-1].new_pict_type = P_TYPE;

                        break;

                    }



                    s->input_picture[i]->pict_type= 

                        s->rc_context.entry[pict_num].new_pict_type;

                }

            }



            if(s->avctx->b_frame_strategy==0){

                b_frames= s->max_b_frames;

                while(b_frames && !s->input_picture[b_frames]) b_frames--;

            }else if(s->avctx->b_frame_strategy==1){

                for(i=1; i<s->max_b_frames+1; i++){

                    if(s->input_picture[i] && s->input_picture[i]->b_frame_score==0){

                        s->input_picture[i]->b_frame_score= 

                            get_intra_count(s, s->input_picture[i  ]->data[0], 

                                               s->input_picture[i-1]->data[0], s->linesize) + 1;

                    }

                }

                for(i=0; i<s->max_b_frames+1; i++){

                    if(s->input_picture[i]==NULL || s->input_picture[i]->b_frame_score - 1 > s->mb_num/40) break;

                }



                b_frames= FFMAX(0, i-1);



                /* reset scores */

                for(i=0; i<b_frames+1; i++){

                    s->input_picture[i]->b_frame_score=0;

                }

            }else{

                av_log(s->avctx, AV_LOG_ERROR, "illegal b frame strategy\n");

                b_frames=0;

            }



            emms_c();

//static int b_count=0;

//b_count+= b_frames;

//av_log(s->avctx, AV_LOG_DEBUG, "b_frames: %d\n", b_count);



            for(i= b_frames - 1; i>=0; i--){

                int type= s->input_picture[i]->pict_type;

                if(type && type != B_TYPE)

                    b_frames= i;

            }

            if(s->input_picture[b_frames]->pict_type == B_TYPE && b_frames == s->max_b_frames){

                av_log(s->avctx, AV_LOG_ERROR, "warning, too many b frames in a row\n");

            }



            if(s->picture_in_gop_number + b_frames >= s->gop_size){

              if((s->flags2 & CODEC_FLAG2_STRICT_GOP) && s->gop_size > s->picture_in_gop_number){

                    b_frames= s->gop_size - s->picture_in_gop_number - 1;

              }else{

                if(s->flags & CODEC_FLAG_CLOSED_GOP)

                    b_frames=0;

                s->input_picture[b_frames]->pict_type= I_TYPE;

              }

            }



            if(   (s->flags & CODEC_FLAG_CLOSED_GOP)

               && b_frames

               && s->input_picture[b_frames]->pict_type== I_TYPE)

                b_frames--;



            s->reordered_input_picture[0]= s->input_picture[b_frames];

            if(s->reordered_input_picture[0]->pict_type != I_TYPE)

                s->reordered_input_picture[0]->pict_type= P_TYPE;

            s->reordered_input_picture[0]->coded_picture_number= s->coded_picture_number++;

            for(i=0; i<b_frames; i++){

                s->reordered_input_picture[i+1]= s->input_picture[i];

                s->reordered_input_picture[i+1]->pict_type= B_TYPE;

                s->reordered_input_picture[i+1]->coded_picture_number= s->coded_picture_number++;

            }

        }

    }

no_output_pic:

    if(s->reordered_input_picture[0]){

        s->reordered_input_picture[0]->reference= s->reordered_input_picture[0]->pict_type!=B_TYPE ? 3 : 0;



        copy_picture(&s->new_picture, s->reordered_input_picture[0]);



        if(s->reordered_input_picture[0]->type == FF_BUFFER_TYPE_SHARED){

            // input is a shared pix, so we can't modifiy it -> alloc a new one & ensure that the shared one is reuseable



            int i= ff_find_unused_picture(s, 0);

            Picture *pic= &s->picture[i];



            /* mark us unused / free shared pic */

            for(i=0; i<4; i++)

                s->reordered_input_picture[0]->data[i]= NULL;

            s->reordered_input_picture[0]->type= 0;



            pic->reference              = s->reordered_input_picture[0]->reference;



            alloc_picture(s, pic, 0);



            copy_picture_attributes(s, (AVFrame*)pic, (AVFrame*)s->reordered_input_picture[0]);



            s->current_picture_ptr= pic;

        }else{

            // input is not a shared pix -> reuse buffer for current_pix



            assert(   s->reordered_input_picture[0]->type==FF_BUFFER_TYPE_USER 

                   || s->reordered_input_picture[0]->type==FF_BUFFER_TYPE_INTERNAL);



            s->current_picture_ptr= s->reordered_input_picture[0];

            for(i=0; i<4; i++){

                s->new_picture.data[i]+=16;

            }

        }

        copy_picture(&s->current_picture, s->current_picture_ptr);



        s->picture_number= s->new_picture.display_picture_number;

//printf("dpn:%d\n", s->picture_number);

    }else{

       memset(&s->new_picture, 0, sizeof(Picture));

    }

}

static inline uint32_t lduw_phys_internal(target_phys_addr_t addr,

                                          enum device_endian endian)

{

    uint8_t *ptr;

    uint64_t val;

    MemoryRegionSection *section;



    section = phys_page_find(addr >> TARGET_PAGE_BITS);



    if (!(memory_region_is_ram(section->mr) ||

          memory_region_is_romd(section->mr))) {

        /* I/O case */

        addr = memory_region_section_addr(section, addr);

        val = io_mem_read(section->mr, addr, 2);

#if defined(TARGET_WORDS_BIGENDIAN)

        if (endian == DEVICE_LITTLE_ENDIAN) {

            val = bswap16(val);

        }

#else

        if (endian == DEVICE_BIG_ENDIAN) {

            val = bswap16(val);

        }

#endif

    } else {

        /* RAM case */

        ptr = qemu_get_ram_ptr((memory_region_get_ram_addr(section->mr)

                                & TARGET_PAGE_MASK)

                               + memory_region_section_addr(section, addr));

        switch (endian) {

        case DEVICE_LITTLE_ENDIAN:

            val = lduw_le_p(ptr);

            break;

        case DEVICE_BIG_ENDIAN:

            val = lduw_be_p(ptr);

            break;

        default:

            val = lduw_p(ptr);

            break;

        }

    }

    return val;

}

static inline void xchg_mb_border(H264Context *h, uint8_t *src_y, uint8_t *src_cb, uint8_t *src_cr, int linesize, int uvlinesize, int xchg, int simple){

    MpegEncContext * const s = &h->s;

    int temp8, i;

    uint64_t temp64;

    int deblock_left;

    int deblock_top;

    int mb_xy;

    int step    = 1;

    int offset  = 1;

    int uvoffset= 1;

    int top_idx = 1;



    if(!simple && FRAME_MBAFF){

        if(s->mb_y&1){

            offset  = MB_MBAFF ? 1 : 17;

            uvoffset= MB_MBAFF ? 1 : 9;

        }else{

            offset  =

            uvoffset=

            top_idx = MB_MBAFF ? 0 : 1;

        }

        step= MB_MBAFF ? 2 : 1;

    }



    if(h->deblocking_filter == 2) {

        mb_xy = h->mb_xy;

        deblock_left = h->slice_table[mb_xy] == h->slice_table[mb_xy - 1];

        deblock_top  = h->slice_table[mb_xy] == h->slice_table[h->top_mb_xy];

    } else {

        deblock_left = (s->mb_x > 0);

        deblock_top =  (s->mb_y > !!MB_FIELD);

    }



    src_y  -=   linesize + 1;

    src_cb -= uvlinesize + 1;

    src_cr -= uvlinesize + 1;



#define XCHG(a,b,t,xchg)\

t= a;\

if(xchg)\

    a= b;\

b= t;



    if(deblock_left){

        for(i = !deblock_top; i<16; i++){

            XCHG(h->left_border[offset+i*step], src_y [i*  linesize], temp8, xchg);

        }

        XCHG(h->left_border[offset+i*step], src_y [i*  linesize], temp8, 1);

    }



    if(deblock_top){

        XCHG(*(uint64_t*)(h->top_borders[top_idx][s->mb_x]+0), *(uint64_t*)(src_y +1), temp64, xchg);

        XCHG(*(uint64_t*)(h->top_borders[top_idx][s->mb_x]+8), *(uint64_t*)(src_y +9), temp64, 1);

        if(s->mb_x+1 < s->mb_width){

            XCHG(*(uint64_t*)(h->top_borders[top_idx][s->mb_x+1]), *(uint64_t*)(src_y +17), temp64, 1);

        }

    }



    if(simple || !CONFIG_GRAY || !(s->flags&CODEC_FLAG_GRAY)){

        if(deblock_left){

            for(i = !deblock_top; i<8; i++){

                XCHG(h->left_border[uvoffset+34   +i*step], src_cb[i*uvlinesize], temp8, xchg);

                XCHG(h->left_border[uvoffset+34+18+i*step], src_cr[i*uvlinesize], temp8, xchg);

            }

            XCHG(h->left_border[uvoffset+34   +i*step], src_cb[i*uvlinesize], temp8, 1);

            XCHG(h->left_border[uvoffset+34+18+i*step], src_cr[i*uvlinesize], temp8, 1);

        }

        if(deblock_top){

            XCHG(*(uint64_t*)(h->top_borders[top_idx][s->mb_x]+16), *(uint64_t*)(src_cb+1), temp64, 1);

            XCHG(*(uint64_t*)(h->top_borders[top_idx][s->mb_x]+24), *(uint64_t*)(src_cr+1), temp64, 1);

        }

    }

}

static void rv34_pred_4x4_block(RV34DecContext *r, uint8_t *dst, int stride, int itype, int up, int left, int down, int right)

{

    uint8_t *prev = dst - stride + 4;

    uint32_t topleft;



    if(!up && !left)

        itype = DC_128_PRED;

    else if(!up){

        if(itype == VERT_PRED) itype = HOR_PRED;

        if(itype == DC_PRED)   itype = LEFT_DC_PRED;

    }else if(!left){

        if(itype == HOR_PRED)  itype = VERT_PRED;

        if(itype == DC_PRED)   itype = TOP_DC_PRED;

        if(itype == DIAG_DOWN_LEFT_PRED) itype = DIAG_DOWN_LEFT_PRED_RV40_NODOWN;

    }

    if(!down){

        if(itype == DIAG_DOWN_LEFT_PRED) itype = DIAG_DOWN_LEFT_PRED_RV40_NODOWN;

        if(itype == HOR_UP_PRED) itype = HOR_UP_PRED_RV40_NODOWN;

        if(itype == VERT_LEFT_PRED) itype = VERT_LEFT_PRED_RV40_NODOWN;

    }

    if(!right && up){

        topleft = dst[-stride + 3] * 0x01010101;

        prev = (uint8_t*)&topleft;

    }

    r->h.pred4x4[itype](dst, prev, stride);

}

static av_cold int MP3lame_encode_init(AVCodecContext *avctx)

{

    Mp3AudioContext *s = avctx->priv_data;



    if (avctx->channels > 2)

        return -1;



    s->stereo = avctx->channels > 1 ? 1 : 0;



    if ((s->gfp = lame_init()) == NULL)

        goto err;

    lame_set_in_samplerate(s->gfp, avctx->sample_rate);

    lame_set_out_samplerate(s->gfp, avctx->sample_rate);

    lame_set_num_channels(s->gfp, avctx->channels);

    if(avctx->compression_level == FF_COMPRESSION_DEFAULT) {

        lame_set_quality(s->gfp, 5);

    } else {

        lame_set_quality(s->gfp, avctx->compression_level);

    }

    lame_set_mode(s->gfp, s->stereo ? JOINT_STEREO : MONO);

    lame_set_brate(s->gfp, avctx->bit_rate/1000);

    if(avctx->flags & CODEC_FLAG_QSCALE) {

        lame_set_brate(s->gfp, 0);

        lame_set_VBR(s->gfp, vbr_default);

        lame_set_VBR_quality(s->gfp, avctx->global_quality/(float)FF_QP2LAMBDA);

    }

    lame_set_bWriteVbrTag(s->gfp,0);

    lame_set_disable_reservoir(s->gfp, avctx->flags2 & CODEC_FLAG2_BIT_RESERVOIR ? 0 : 1);

    if (lame_init_params(s->gfp) < 0)

        goto err_close;



    avctx->frame_size = lame_get_framesize(s->gfp);



    avctx->coded_frame= avcodec_alloc_frame();

    avctx->coded_frame->key_frame= 1;



    return 0;



err_close:

    lame_close(s->gfp);

err:

    return -1;

}

int av_strerror(int errnum, char *errbuf, size_t errbuf_size)

{

    int ret = 0;

    const char *errstr = NULL;



    switch (errnum) {

    case AVERROR_EOF:               errstr = "End of file"; break;

    case AVERROR_INVALIDDATA:       errstr = "Invalid data found when processing input"; break;

    case AVERROR_NUMEXPECTED:       errstr = "Number syntax expected in filename"; break;

    case AVERROR_PATCHWELCOME:      errstr = "Not yet implemented in FFmpeg, patches welcome"; break;

    }



    if (errstr) {

        av_strlcpy(errbuf, errstr, errbuf_size);

    } else {

#if HAVE_STRERROR_R

        ret = strerror_r(AVUNERROR(errnum), errbuf, errbuf_size);

#endif

        if (!HAVE_STRERROR_R || ret < 0)

            snprintf(errbuf, errbuf_size, "Error number %d occurred", errnum);

    }



    return ret;

}

