static int udp_write(URLContext *h, const uint8_t *buf, int size)

{

    UDPContext *s = h->priv_data;

    int ret;



#if HAVE_PTHREAD_CANCEL

    if (s->fifo) {

        uint8_t tmp[4];



        pthread_mutex_lock(&s->mutex);



        /*

          Return error if last tx failed.

          Here we can't know on which packet error was, but it needs to know that error exists.

        */

        if (s->circular_buffer_error<0) {

            int err=s->circular_buffer_error;

            s->circular_buffer_error=0;

            pthread_mutex_unlock(&s->mutex);

            return err;

        }



        if(av_fifo_space(s->fifo) < size + 4) {

            /* What about a partial packet tx ? */

            pthread_mutex_unlock(&s->mutex);

            return AVERROR(ENOMEM);

        }

        AV_WL32(tmp, size);

        av_fifo_generic_write(s->fifo, tmp, 4, NULL); /* size of packet */

        av_fifo_generic_write(s->fifo, (uint8_t *)buf, size, NULL); /* the data */

        pthread_cond_signal(&s->cond);

        pthread_mutex_unlock(&s->mutex);

        return size;

    }

#endif

    if (!(h->flags & AVIO_FLAG_NONBLOCK)) {

        ret = ff_network_wait_fd(s->udp_fd, 1);

        if (ret < 0)

            return ret;

    }



    if (!s->is_connected) {

        ret = sendto (s->udp_fd, buf, size, 0,

                      (struct sockaddr *) &s->dest_addr,

                      s->dest_addr_len);

    } else

        ret = send(s->udp_fd, buf, size, 0);



    return ret < 0 ? ff_neterrno() : ret;

}

static void compute_frame_duration(int *pnum, int *pden, AVStream *st,

                                   AVCodecParserContext *pc, AVPacket *pkt)

{

    int frame_size;



    *pnum = 0;

    *pden = 0;

    switch(st->codec->codec_type) {

    case AVMEDIA_TYPE_VIDEO:

        if (st->r_frame_rate.num) {

            *pnum = st->r_frame_rate.den;

            *pden = st->r_frame_rate.num;

        } else if(st->time_base.num*1000LL > st->time_base.den) {

            *pnum = st->time_base.num;

            *pden = st->time_base.den;

        }else if(st->codec->time_base.num*1000LL > st->codec->time_base.den){

            *pnum = st->codec->time_base.num;

            *pden = st->codec->time_base.den;

            if (pc && pc->repeat_pict) {

                *pnum = (*pnum) * (1 + pc->repeat_pict);

            }

            //If this codec can be interlaced or progressive then we need a parser to compute duration of a packet

            //Thus if we have no parser in such case leave duration undefined.

            if(st->codec->ticks_per_frame>1 && !pc){

                *pnum = *pden = 0;

            }

        }

        break;

    case AVMEDIA_TYPE_AUDIO:

        frame_size = get_audio_frame_size(st->codec, pkt->size, 0);

        if (frame_size <= 0 || st->codec->sample_rate <= 0)

            break;

        *pnum = frame_size;

        *pden = st->codec->sample_rate;

        break;

    default:

        break;

    }

}

static int ram_save_live(Monitor *mon, QEMUFile *f, int stage, void *opaque)

{

    ram_addr_t addr;

    uint64_t bytes_transferred_last;

    double bwidth = 0;

    uint64_t expected_time = 0;



    if (stage < 0) {

        cpu_physical_memory_set_dirty_tracking(0);

        return 0;

    }



    if (cpu_physical_sync_dirty_bitmap(0, TARGET_PHYS_ADDR_MAX) != 0) {

        qemu_file_set_error(f);

        return 0;

    }



    if (stage == 1) {

        bytes_transferred = 0;



        /* Make sure all dirty bits are set */

        for (addr = 0; addr < last_ram_offset; addr += TARGET_PAGE_SIZE) {

            if (!cpu_physical_memory_get_dirty(addr, MIGRATION_DIRTY_FLAG))

                cpu_physical_memory_set_dirty(addr);

        }



        /* Enable dirty memory tracking */

        cpu_physical_memory_set_dirty_tracking(1);



        qemu_put_be64(f, last_ram_offset | RAM_SAVE_FLAG_MEM_SIZE);

    }



    bytes_transferred_last = bytes_transferred;

    bwidth = qemu_get_clock_ns(rt_clock);



    while (!qemu_file_rate_limit(f)) {

        int ret;



        ret = ram_save_block(f);

        bytes_transferred += ret * TARGET_PAGE_SIZE;

        if (ret == 0) /* no more blocks */

            break;

    }



    bwidth = qemu_get_clock_ns(rt_clock) - bwidth;

    bwidth = (bytes_transferred - bytes_transferred_last) / bwidth;



    /* if we haven't transferred anything this round, force expected_time to a

     * a very high value, but without crashing */

    if (bwidth == 0)

        bwidth = 0.000001;



    /* try transferring iterative blocks of memory */

    if (stage == 3) {

        /* flush all remaining blocks regardless of rate limiting */

        while (ram_save_block(f) != 0) {

            bytes_transferred += TARGET_PAGE_SIZE;

        }

        cpu_physical_memory_set_dirty_tracking(0);

    }



    qemu_put_be64(f, RAM_SAVE_FLAG_EOS);



    expected_time = ram_save_remaining() * TARGET_PAGE_SIZE / bwidth;



    return (stage == 2) && (expected_time <= migrate_max_downtime());

}

static int zerocodec_decode_frame(AVCodecContext *avctx, void *data,

                                  int *data_size, AVPacket *avpkt)

{

    ZeroCodecContext *zc = avctx->priv_data;

    AVFrame *pic         = avctx->coded_frame;

    AVFrame *prev_pic    = &zc->previous_frame;

    z_stream *zstream    = &zc->zstream;

    uint8_t *prev, *dst;

    int i, j, zret;



    pic->reference = 3;



    if (avctx->get_buffer(avctx, pic) < 0) {

        av_log(avctx, AV_LOG_ERROR, "Could not allocate buffer.\n");

        return AVERROR(ENOMEM);

    }



    zret = inflateReset(zstream);



    if (zret != Z_OK) {

        av_log(avctx, AV_LOG_ERROR, "Could not reset inflate: %d\n", zret);

        return AVERROR(EINVAL);

    }



    zstream->next_in  = avpkt->data;

    zstream->avail_in = avpkt->size;



    prev = prev_pic->data[0];

    dst  = pic->data[0];



    /**

     * ZeroCodec has very simple interframe compression. If a value

     * is the same as the previous frame, set it to 0.

     */



    if (avpkt->flags & AV_PKT_FLAG_KEY) {



        pic->key_frame = 1;

        pic->pict_type = AV_PICTURE_TYPE_I;



        for (i = 0; i < avctx->height; i++) {



            zstream->next_out  = dst;

            zstream->avail_out = avctx->width << 1;



            zret = inflate(zstream, Z_SYNC_FLUSH);



            if (zret != Z_OK && zret != Z_STREAM_END) {

                av_log(avctx, AV_LOG_ERROR,

                       "Inflate failed with return code: %d\n", zret);

                return AVERROR(EINVAL);

            }



            dst += pic->linesize[0];

        }

    } else {



        pic->key_frame = 0;

        pic->pict_type = AV_PICTURE_TYPE_P;



        for (i = 0; i < avctx->height; i++) {



            zstream->next_out  = dst;

            zstream->avail_out = avctx->width << 1;



            zret = inflate(zstream, Z_SYNC_FLUSH);



            if (zret != Z_OK && zret != Z_STREAM_END) {

                av_log(avctx, AV_LOG_ERROR,

                       "Inflate failed with return code: %d\n", zret);

                return AVERROR(EINVAL);

            }



            for (j = 0; j < avctx->width << 1; j++)

                dst[j] += prev[j] & -!dst[j];



            prev += prev_pic->linesize[0];

            dst  += pic->linesize[0];

        }

    }



    /* Release the previous buffer if need be */

    if (prev_pic->data[0])

        avctx->release_buffer(avctx, prev_pic);



    /* Store the previouse frame for use later */

    *prev_pic = *pic;



    *data_size       = sizeof(AVFrame);

    *(AVFrame *)data = *pic;



    return avpkt->size;

}

static void g364fb_screen_dump(void *opaque, const char *filename, bool cswitch,

                               Error **errp)

{

    G364State *s = opaque;

    int ret, y, x;

    uint8_t index;

    uint8_t *data_buffer;

    FILE *f;



    qemu_flush_coalesced_mmio_buffer();



    if (s->depth != 8) {

        error_setg(errp, "g364: unknown guest depth %d", s->depth);

        return;

    }



    f = fopen(filename, "wb");

    if (!f) {

        error_setg(errp, "failed to open file '%s': %s", filename,

                   strerror(errno));

        return;

    }



    if (s->ctla & CTLA_FORCE_BLANK) {

        /* blank screen */

        ret = fprintf(f, "P4\n%d %d\n", s->width, s->height);

        if (ret < 0) {

            goto write_err;

        }

        for (y = 0; y < s->height; y++)

            for (x = 0; x < s->width; x++) {

                ret = fputc(0, f);

                if (ret == EOF) {

                    goto write_err;

                }

            }

    } else {

        data_buffer = s->vram + s->top_of_screen;

        ret = fprintf(f, "P6\n%d %d\n%d\n", s->width, s->height, 255);

        if (ret < 0) {

            goto write_err;

        }

        for (y = 0; y < s->height; y++)

            for (x = 0; x < s->width; x++, data_buffer++) {

                index = *data_buffer;

                ret = fputc(s->color_palette[index][0], f);

                if (ret == EOF) {

                    goto write_err;

                }

                ret = fputc(s->color_palette[index][1], f);

                if (ret == EOF) {

                    goto write_err;

                }

                ret = fputc(s->color_palette[index][2], f);

                if (ret == EOF) {

                    goto write_err;

                }

        }

    }



out:

    fclose(f);

    return;



write_err:

    error_setg(errp, "failed to write to file '%s': %s", filename,

               strerror(errno));

    unlink(filename);

    goto out;

}

float64 helper_fsmuld(CPUSPARCState *env, float32 src1, float32 src2)

{

    float64 ret;

    clear_float_exceptions(env);

    ret = float64_mul(float32_to_float64(src1, &env->fp_status),

                      float32_to_float64(src2, &env->fp_status),

                      &env->fp_status);

