static int init_video_param(AVCodecContext *avctx, QSVEncContext *q)

{

    float quant;

    int ret;



    ret = ff_qsv_codec_id_to_mfx(avctx->codec_id);

    if (ret < 0)

        return AVERROR_BUG;

    q->param.mfx.CodecId = ret;



    q->width_align = avctx->codec_id == AV_CODEC_ID_HEVC ? 32 : 16;



    if (avctx->level > 0)

        q->param.mfx.CodecLevel = avctx->level;



    q->param.mfx.CodecProfile       = q->profile;

    q->param.mfx.TargetUsage        = q->preset;

    q->param.mfx.GopPicSize         = FFMAX(0, avctx->gop_size);

    q->param.mfx.GopRefDist         = FFMAX(-1, avctx->max_b_frames) + 1;

    q->param.mfx.GopOptFlag         = avctx->flags & AV_CODEC_FLAG_CLOSED_GOP ?

                                      MFX_GOP_CLOSED : 0;

    q->param.mfx.IdrInterval        = q->idr_interval;

    q->param.mfx.NumSlice           = avctx->slices;

    q->param.mfx.NumRefFrame        = FFMAX(0, avctx->refs);

    q->param.mfx.EncodedOrder       = 0;

    q->param.mfx.BufferSizeInKB     = 0;



    q->param.mfx.FrameInfo.FourCC         = MFX_FOURCC_NV12;

    q->param.mfx.FrameInfo.Width          = FFALIGN(avctx->width, q->width_align);

    q->param.mfx.FrameInfo.Height         = FFALIGN(avctx->height, 32);

    q->param.mfx.FrameInfo.CropX          = 0;

    q->param.mfx.FrameInfo.CropY          = 0;

    q->param.mfx.FrameInfo.CropW          = avctx->width;

    q->param.mfx.FrameInfo.CropH          = avctx->height;

    q->param.mfx.FrameInfo.AspectRatioW   = avctx->sample_aspect_ratio.num;

    q->param.mfx.FrameInfo.AspectRatioH   = avctx->sample_aspect_ratio.den;

    q->param.mfx.FrameInfo.PicStruct      = MFX_PICSTRUCT_PROGRESSIVE;

    q->param.mfx.FrameInfo.ChromaFormat   = MFX_CHROMAFORMAT_YUV420;

    q->param.mfx.FrameInfo.BitDepthLuma   = 8;

    q->param.mfx.FrameInfo.BitDepthChroma = 8;



    if (avctx->framerate.den > 0 && avctx->framerate.num > 0) {

        q->param.mfx.FrameInfo.FrameRateExtN = avctx->framerate.num;

        q->param.mfx.FrameInfo.FrameRateExtD = avctx->framerate.den;

    } else {

        q->param.mfx.FrameInfo.FrameRateExtN  = avctx->time_base.den;

        q->param.mfx.FrameInfo.FrameRateExtD  = avctx->time_base.num;

    }



    ret = select_rc_mode(avctx, q);

    if (ret < 0)

        return ret;



    switch (q->param.mfx.RateControlMethod) {

    case MFX_RATECONTROL_CBR:

    case MFX_RATECONTROL_VBR:

#if QSV_HAVE_VCM

    case MFX_RATECONTROL_VCM:

#endif

        q->param.mfx.InitialDelayInKB = avctx->rc_initial_buffer_occupancy / 1000;

        q->param.mfx.TargetKbps       = avctx->bit_rate / 1000;

        q->param.mfx.MaxKbps          = avctx->rc_max_rate / 1000;

        break;

    case MFX_RATECONTROL_CQP:

        quant = avctx->global_quality / FF_QP2LAMBDA;



        q->param.mfx.QPI = av_clip(quant * fabs(avctx->i_quant_factor) + avctx->i_quant_offset, 0, 51);

        q->param.mfx.QPP = av_clip(quant, 0, 51);

        q->param.mfx.QPB = av_clip(quant * fabs(avctx->b_quant_factor) + avctx->b_quant_offset, 0, 51);



        break;

    case MFX_RATECONTROL_AVBR:

        q->param.mfx.TargetKbps  = avctx->bit_rate / 1000;

        q->param.mfx.Convergence = q->avbr_convergence;

        q->param.mfx.Accuracy    = q->avbr_accuracy;

        break;

#if QSV_HAVE_LA

    case MFX_RATECONTROL_LA:

        q->param.mfx.TargetKbps  = avctx->bit_rate / 1000;

        q->extco2.LookAheadDepth = q->la_depth;

        break;

#if QSV_HAVE_ICQ

    case MFX_RATECONTROL_LA_ICQ:

        q->extco2.LookAheadDepth = q->la_depth;

    case MFX_RATECONTROL_ICQ:

        q->param.mfx.ICQQuality  = avctx->global_quality;

        break;

#endif

#endif

    }



    // the HEVC encoder plugin currently fails if coding options

    // are provided

    if (avctx->codec_id != AV_CODEC_ID_HEVC) {

        q->extco.Header.BufferId      = MFX_EXTBUFF_CODING_OPTION;

        q->extco.Header.BufferSz      = sizeof(q->extco);

        q->extco.CAVLC                = avctx->coder_type == FF_CODER_TYPE_VLC ?

                                        MFX_CODINGOPTION_ON : MFX_CODINGOPTION_UNKNOWN;



        if (q->rdo >= 0)

            q->extco.RateDistortionOpt = q->rdo > 0 ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;



        if (avctx->codec_id == AV_CODEC_ID_H264) {

            if (avctx->strict_std_compliance != FF_COMPLIANCE_NORMAL)

                q->extco.NalHrdConformance = avctx->strict_std_compliance > FF_COMPLIANCE_NORMAL ?

                                             MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;



            if (q->single_sei_nal_unit >= 0)

                q->extco.SingleSeiNalUnit = q->single_sei_nal_unit ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;

            if (q->recovery_point_sei >= 0)

                q->extco.RecoveryPointSEI = q->recovery_point_sei ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;

            q->extco.MaxDecFrameBuffering = q->max_dec_frame_buffering;

        }



        q->extparam_internal[q->nb_extparam_internal++] = (mfxExtBuffer *)&q->extco;



#if QSV_HAVE_CO2

        if (avctx->codec_id == AV_CODEC_ID_H264) {

            q->extco2.Header.BufferId     = MFX_EXTBUFF_CODING_OPTION2;

            q->extco2.Header.BufferSz     = sizeof(q->extco2);



            if (q->int_ref_type >= 0)

                q->extco2.IntRefType = q->int_ref_type;

            if (q->int_ref_cycle_size >= 0)

                q->extco2.IntRefCycleSize = q->int_ref_cycle_size;

            if (q->int_ref_qp_delta != INT16_MIN)

                q->extco2.IntRefQPDelta = q->int_ref_qp_delta;



            if (q->bitrate_limit >= 0)

                q->extco2.BitrateLimit = q->bitrate_limit ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;

            if (q->mbbrc >= 0)

                q->extco2.MBBRC = q->mbbrc ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;

            if (q->extbrc >= 0)

                q->extco2.ExtBRC = q->extbrc ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;



            if (q->max_frame_size >= 0)

                q->extco2.MaxFrameSize = q->max_frame_size;

#if QSV_HAVE_MAX_SLICE_SIZE

            if (q->max_slice_size >= 0)

                q->extco2.MaxSliceSize = q->max_slice_size;

#endif



#if QSV_HAVE_TRELLIS

            q->extco2.Trellis = q->trellis;

#endif



#if QSV_HAVE_BREF_TYPE

            if (avctx->b_frame_strategy >= 0)

                q->extco2.BRefType = avctx->b_frame_strategy ? MFX_B_REF_PYRAMID : MFX_B_REF_OFF;

            if (q->adaptive_i >= 0)

                q->extco2.AdaptiveI = q->adaptive_i ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;

            if (q->adaptive_b >= 0)

                q->extco2.AdaptiveB = q->adaptive_b ? MFX_CODINGOPTION_ON : MFX_CODINGOPTION_OFF;

#endif



            q->extparam_internal[q->nb_extparam_internal++] = (mfxExtBuffer *)&q->extco2;

        }

#endif

    }



    if (!rc_supported(q)) {

        av_log(avctx, AV_LOG_ERROR,

               "Selected ratecontrol mode is not supported by the QSV "

               "runtime. Choose a different mode.\n");

        return AVERROR(ENOSYS);

    }



    return 0;

}

static inline AIOReq *alloc_aio_req(BDRVSheepdogState *s, SheepdogAIOCB *acb,

                                    uint64_t oid, unsigned int data_len,

                                    uint64_t offset, uint8_t flags,

                                    uint64_t base_oid, unsigned int iov_offset)

{

    AIOReq *aio_req;



    aio_req = g_malloc(sizeof(*aio_req));

    aio_req->aiocb = acb;

    aio_req->iov_offset = iov_offset;

    aio_req->oid = oid;

    aio_req->base_oid = base_oid;

    aio_req->offset = offset;

    aio_req->data_len = data_len;

    aio_req->flags = flags;

    aio_req->id = s->aioreq_seq_num++;



    acb->nr_pending++;

    return aio_req;

}

static void ff_acelp_interpolatef_mips(float *out, const float *in,

                           const float *filter_coeffs, int precision,

                           int frac_pos, int filter_length, int length)

{

    int n, i;

    int prec = precision * 4;

    int fc_offset = precision - frac_pos;

    float in_val_p, in_val_m, fc_val_p, fc_val_m;



    for (n = 0; n < length; n++) {

        /**

        * four pointers are defined in order to minimize number of

        * computations done in inner loop

        */

        const float *p_in_p = &in[n];

        const float *p_in_m = &in[n-1];

        const float *p_filter_coeffs_p = &filter_coeffs[frac_pos];

        const float *p_filter_coeffs_m = filter_coeffs + fc_offset;

        float v = 0;



        for (i = 0; i < filter_length;i++) {

            __asm__ volatile (

                "lwc1   %[in_val_p],           0(%[p_in_p])                    \n\t"

                "lwc1   %[fc_val_p],           0(%[p_filter_coeffs_p])         \n\t"

                "lwc1   %[in_val_m],           0(%[p_in_m])                    \n\t"

                "lwc1   %[fc_val_m],           0(%[p_filter_coeffs_m])         \n\t"

                "addiu  %[p_in_p],             %[p_in_p],              4       \n\t"

                "madd.s %[v],%[v],             %[in_val_p],%[fc_val_p]         \n\t"

                "addiu  %[p_in_m],             %[p_in_m],              -4      \n\t"

                "addu   %[p_filter_coeffs_p],  %[p_filter_coeffs_p],   %[prec] \n\t"

                "addu   %[p_filter_coeffs_m],  %[p_filter_coeffs_m],   %[prec] \n\t"

                "madd.s %[v],%[v],%[in_val_m], %[fc_val_m]                     \n\t"



                : [v] "=&f" (v),[p_in_p] "+r" (p_in_p), [p_in_m] "+r" (p_in_m),

                  [p_filter_coeffs_p] "+r" (p_filter_coeffs_p),

                  [in_val_p] "=&f" (in_val_p), [in_val_m] "=&f" (in_val_m),

                  [fc_val_p] "=&f" (fc_val_p), [fc_val_m] "=&f" (fc_val_m),

                  [p_filter_coeffs_m] "+r" (p_filter_coeffs_m)

                : [prec] "r" (prec)

                : "memory"

            );

        }

        out[n] = v;

    }

}

static int mpegts_push_data(MpegTSFilter *filter,

                            const uint8_t *buf, int buf_size, int is_start,

                            int64_t pos)

{

    PESContext *pes = filter->u.pes_filter.opaque;

    MpegTSContext *ts = pes->ts;

    const uint8_t *p;

    int len, code;



    if(!ts->pkt)

        return 0;



    if (is_start) {

        if (pes->state == MPEGTS_PAYLOAD && pes->data_index > 0) {

            new_pes_packet(pes, ts->pkt);

            ts->stop_parse = 1;

        }

        pes->state = MPEGTS_HEADER;

        pes->data_index = 0;

        pes->ts_packet_pos = pos;

    }

    p = buf;

    while (buf_size > 0) {

        switch(pes->state) {

        case MPEGTS_HEADER:

            len = PES_START_SIZE - pes->data_index;

            if (len > buf_size)

                len = buf_size;

            memcpy(pes->header + pes->data_index, p, len);

            pes->data_index += len;

            p += len;

            buf_size -= len;

            if (pes->data_index == PES_START_SIZE) {

                /* we got all the PES or section header. We can now

                   decide */

                if (pes->header[0] == 0x00 && pes->header[1] == 0x00 &&

                    pes->header[2] == 0x01) {

                    /* it must be an mpeg2 PES stream */

                    code = pes->header[3] | 0x100;

                    av_dlog(pes->stream, "pid=%x pes_code=%#x\n", pes->pid, code);



                    if ((pes->st && pes->st->discard == AVDISCARD_ALL) ||

                        code == 0x1be) /* padding_stream */

                        goto skip;



                    /* stream not present in PMT */

                    if (!pes->st) {

                        pes->st = av_new_stream(ts->stream, pes->pid);

                        if (!pes->st)

                            return AVERROR(ENOMEM);

                        mpegts_set_stream_info(pes->st, pes, 0, 0);

                    }



                    pes->total_size = AV_RB16(pes->header + 4);

                    /* NOTE: a zero total size means the PES size is

                       unbounded */

                    if (!pes->total_size)

                        pes->total_size = MAX_PES_PAYLOAD;



                    /* allocate pes buffer */

                    pes->buffer = av_malloc(pes->total_size+FF_INPUT_BUFFER_PADDING_SIZE);

                    if (!pes->buffer)

                        return AVERROR(ENOMEM);



                    if (code != 0x1bc && code != 0x1bf && /* program_stream_map, private_stream_2 */

                        code != 0x1f0 && code != 0x1f1 && /* ECM, EMM */

                        code != 0x1ff && code != 0x1f2 && /* program_stream_directory, DSMCC_stream */

                        code != 0x1f8) {                  /* ITU-T Rec. H.222.1 type E stream */

                        pes->state = MPEGTS_PESHEADER;

                        if (pes->st->codec->codec_id == CODEC_ID_NONE) {

                            av_dlog(pes->stream, "pid=%x stream_type=%x probing\n",

                                    pes->pid, pes->stream_type);

                            pes->st->codec->codec_id = CODEC_ID_PROBE;

                        }

                    } else {

                        pes->state = MPEGTS_PAYLOAD;

                        pes->data_index = 0;

                    }

                } else {

                    /* otherwise, it should be a table */

                    /* skip packet */

                skip:

                    pes->state = MPEGTS_SKIP;

                    continue;

                }

            }

            break;

            /**********************************************/

            /* PES packing parsing */

        case MPEGTS_PESHEADER:

            len = PES_HEADER_SIZE - pes->data_index;

            if (len < 0)

                return -1;

            if (len > buf_size)

                len = buf_size;

            memcpy(pes->header + pes->data_index, p, len);

            pes->data_index += len;

            p += len;

            buf_size -= len;

            if (pes->data_index == PES_HEADER_SIZE) {

                pes->pes_header_size = pes->header[8] + 9;

                pes->state = MPEGTS_PESHEADER_FILL;

            }

            break;

        case MPEGTS_PESHEADER_FILL:

            len = pes->pes_header_size - pes->data_index;

            if (len < 0)

                return -1;

            if (len > buf_size)

                len = buf_size;

            memcpy(pes->header + pes->data_index, p, len);

            pes->data_index += len;

            p += len;

            buf_size -= len;

            if (pes->data_index == pes->pes_header_size) {

                const uint8_t *r;

                unsigned int flags, pes_ext, skip;



                flags = pes->header[7];

                r = pes->header + 9;

                pes->pts = AV_NOPTS_VALUE;

                pes->dts = AV_NOPTS_VALUE;

                if ((flags & 0xc0) == 0x80) {

                    pes->dts = pes->pts = ff_parse_pes_pts(r);

                    r += 5;

                } else if ((flags & 0xc0) == 0xc0) {

                    pes->pts = ff_parse_pes_pts(r);

                    r += 5;

                    pes->dts = ff_parse_pes_pts(r);

                    r += 5;

                }

                pes->extended_stream_id = -1;

                if (flags & 0x01) { /* PES extension */

                    pes_ext = *r++;

                    /* Skip PES private data, program packet sequence counter and P-STD buffer */

                    skip = (pes_ext >> 4) & 0xb;

                    skip += skip & 0x9;

                    r += skip;

                    if ((pes_ext & 0x41) == 0x01 &&

                        (r + 2) <= (pes->header + pes->pes_header_size)) {

                        /* PES extension 2 */

                        if ((r[0] & 0x7f) > 0 && (r[1] & 0x80) == 0)

                            pes->extended_stream_id = r[1];

                    }

                }



                /* we got the full header. We parse it and get the payload */

                pes->state = MPEGTS_PAYLOAD;

                pes->data_index = 0;

            }

            break;

        case MPEGTS_PAYLOAD:

            if (buf_size > 0 && pes->buffer) {

                if (pes->data_index > 0 && pes->data_index+buf_size > pes->total_size) {

                    new_pes_packet(pes, ts->pkt);

                    pes->total_size = MAX_PES_PAYLOAD;

                    pes->buffer = av_malloc(pes->total_size+FF_INPUT_BUFFER_PADDING_SIZE);

                    if (!pes->buffer)

                        return AVERROR(ENOMEM);

                    ts->stop_parse = 1;

                } else if (pes->data_index == 0 && buf_size > pes->total_size) {

                    // pes packet size is < ts size packet and pes data is padded with 0xff

                    // not sure if this is legal in ts but see issue #2392

                    buf_size = pes->total_size;

                    pes->flags |= AV_PKT_FLAG_CORRUPT;

                }

                memcpy(pes->buffer+pes->data_index, p, buf_size);

                pes->data_index += buf_size;

            }

            buf_size = 0;

            /* emit complete packets with known packet size

             * decreases demuxer delay for infrequent packets like subtitles from

             * a couple of seconds to milliseconds for properly muxed files.

             * total_size is the number of bytes following pes_packet_length

             * in the pes header, i.e. not counting the first 6 bytes */

            if (!ts->stop_parse && pes->total_size < MAX_PES_PAYLOAD &&

                pes->pes_header_size + pes->data_index == pes->total_size + 6) {

                ts->stop_parse = 1;

                new_pes_packet(pes, ts->pkt);

            }

            break;

        case MPEGTS_SKIP:

            buf_size = 0;

            break;

        }

    }



    return 0;

}

static void mov_build_index(MOVContext *mov, AVStream *st)

{

    MOVStreamContext *sc = st->priv_data;

    int64_t current_offset;

    int64_t current_dts = 0;

    unsigned int stts_index = 0;

    unsigned int stsc_index = 0;

    unsigned int stss_index = 0;

    unsigned int stps_index = 0;

    unsigned int i, j;

    uint64_t stream_size = 0;



    /* adjust first dts according to edit list */

    if (sc->time_offset && mov->time_scale > 0) {

        if (sc->time_offset < 0)

            sc->time_offset = av_rescale(sc->time_offset, sc->time_scale, mov->time_scale);

        current_dts = -sc->time_offset;

        if (sc->ctts_data && sc->stts_data && sc->stts_data[0].duration &&

            sc->ctts_data[0].duration / sc->stts_data[0].duration > 16) {

            /* more than 16 frames delay, dts are likely wrong

               this happens with files created by iMovie */

            sc->wrong_dts = 1;

            st->internal->avctx->has_b_frames = 1;

        }

    }



    /* only use old uncompressed audio chunk demuxing when stts specifies it */

    if (!(st->codecpar->codec_type == AVMEDIA_TYPE_AUDIO &&

          sc->stts_count == 1 && sc->stts_data[0].duration == 1)) {

        unsigned int current_sample = 0;

        unsigned int stts_sample = 0;

        unsigned int sample_size;

        unsigned int distance = 0;

        unsigned int rap_group_index = 0;

        unsigned int rap_group_sample = 0;

        int rap_group_present = sc->rap_group_count && sc->rap_group;

        int key_off = (sc->keyframes && sc->keyframes[0] > 0) || (sc->stps_data && sc->stps_data[0] > 0);



        current_dts -= sc->dts_shift;



        if (!sc->sample_count)

            return;

        if (sc->sample_count >= UINT_MAX / sizeof(*st->index_entries) - st->nb_index_entries)

            return;

        if (av_reallocp_array(&st->index_entries,

                              st->nb_index_entries + sc->sample_count,

                              sizeof(*st->index_entries)) < 0) {

            st->nb_index_entries = 0;

            return;

        }

        st->index_entries_allocated_size = (st->nb_index_entries + sc->sample_count) * sizeof(*st->index_entries);



        for (i = 0; i < sc->chunk_count; i++) {

            current_offset = sc->chunk_offsets[i];

            while (mov_stsc_index_valid(stsc_index, sc->stsc_count) &&

                i + 1 == sc->stsc_data[stsc_index + 1].first)

                stsc_index++;

            for (j = 0; j < sc->stsc_data[stsc_index].count; j++) {

                int keyframe = 0;

                if (current_sample >= sc->sample_count) {

                    av_log(mov->fc, AV_LOG_ERROR, "wrong sample count\n");

                    return;

                }



                if (!sc->keyframe_absent && (!sc->keyframe_count || current_sample+key_off == sc->keyframes[stss_index])) {

                    keyframe = 1;

                    if (stss_index + 1 < sc->keyframe_count)

                        stss_index++;

                } else if (sc->stps_count && current_sample+key_off == sc->stps_data[stps_index]) {

                    keyframe = 1;

                    if (stps_index + 1 < sc->stps_count)

                        stps_index++;

                }

                if (rap_group_present && rap_group_index < sc->rap_group_count) {

                    if (sc->rap_group[rap_group_index].index > 0)

                        keyframe = 1;

                    if (++rap_group_sample == sc->rap_group[rap_group_index].count) {

                        rap_group_sample = 0;

                        rap_group_index++;

                    }

                }

                if (keyframe)

                    distance = 0;

                sample_size = sc->sample_size > 0 ? sc->sample_size : sc->sample_sizes[current_sample];

                if (sc->pseudo_stream_id == -1 ||

                   sc->stsc_data[stsc_index].id - 1 == sc->pseudo_stream_id) {

                    AVIndexEntry *e = &st->index_entries[st->nb_index_entries++];

                    e->pos = current_offset;

                    e->timestamp = current_dts;

                    e->size = sample_size;

                    e->min_distance = distance;

                    e->flags = keyframe ? AVINDEX_KEYFRAME : 0;

                    av_log(mov->fc, AV_LOG_TRACE, "AVIndex stream %d, sample %d, offset %"PRIx64", dts %"PRId64", "

                            "size %d, distance %d, keyframe %d\n", st->index, current_sample,

                            current_offset, current_dts, sample_size, distance, keyframe);

                }



                current_offset += sample_size;

                stream_size += sample_size;

                current_dts += sc->stts_data[stts_index].duration;

                distance++;

                stts_sample++;

                current_sample++;

                if (stts_index + 1 < sc->stts_count && stts_sample == sc->stts_data[stts_index].count) {

                    stts_sample = 0;

                    stts_index++;

                }

            }

        }

        if (st->duration > 0)

            st->codecpar->bit_rate = stream_size*8*sc->time_scale/st->duration;

    } else {

        unsigned chunk_samples, total = 0;



        // compute total chunk count

        for (i = 0; i < sc->stsc_count; i++) {

            unsigned count, chunk_count;



            chunk_samples = sc->stsc_data[i].count;

            if (i != sc->stsc_count - 1 &&

                sc->samples_per_frame && chunk_samples % sc->samples_per_frame) {

                av_log(mov->fc, AV_LOG_ERROR, "error unaligned chunk\n");

                return;

            }



            if (sc->samples_per_frame >= 160) { // gsm

                count = chunk_samples / sc->samples_per_frame;

            } else if (sc->samples_per_frame > 1) {

                unsigned samples = (1024/sc->samples_per_frame)*sc->samples_per_frame;

                count = (chunk_samples+samples-1) / samples;

            } else {

                count = (chunk_samples+1023) / 1024;

            }



            if (mov_stsc_index_valid(i, sc->stsc_count))

                chunk_count = sc->stsc_data[i+1].first - sc->stsc_data[i].first;

            else

                chunk_count = sc->chunk_count - (sc->stsc_data[i].first - 1);

            total += chunk_count * count;

        }



        av_log(mov->fc, AV_LOG_TRACE, "chunk count %d\n", total);

        if (total >= UINT_MAX / sizeof(*st->index_entries) - st->nb_index_entries)

            return;

        if (av_reallocp_array(&st->index_entries,

                              st->nb_index_entries + total,

                              sizeof(*st->index_entries)) < 0) {

            st->nb_index_entries = 0;

            return;

        }

        st->index_entries_allocated_size = (st->nb_index_entries + total) * sizeof(*st->index_entries);



        // populate index

        for (i = 0; i < sc->chunk_count; i++) {

            current_offset = sc->chunk_offsets[i];

            if (mov_stsc_index_valid(stsc_index, sc->stsc_count) &&

                i + 1 == sc->stsc_data[stsc_index + 1].first)

                stsc_index++;

            chunk_samples = sc->stsc_data[stsc_index].count;



            while (chunk_samples > 0) {

                AVIndexEntry *e;

                unsigned size, samples;



                if (sc->samples_per_frame > 1 && !sc->bytes_per_frame) {

                    avpriv_request_sample(mov->fc,

                           "Zero bytes per frame, but %d samples per frame",

                           sc->samples_per_frame);

                    return;

                }



                if (sc->samples_per_frame >= 160) { // gsm

                    samples = sc->samples_per_frame;

                    size = sc->bytes_per_frame;

                } else {

                    if (sc->samples_per_frame > 1) {

                        samples = FFMIN((1024 / sc->samples_per_frame)*

                                        sc->samples_per_frame, chunk_samples);

                        size = (samples / sc->samples_per_frame) * sc->bytes_per_frame;

                    } else {

                        samples = FFMIN(1024, chunk_samples);

                        size = samples * sc->sample_size;

                    }

                }



                if (st->nb_index_entries >= total) {

                    av_log(mov->fc, AV_LOG_ERROR, "wrong chunk count %d\n", total);

                    return;

                }

                e = &st->index_entries[st->nb_index_entries++];

                e->pos = current_offset;

                e->timestamp = current_dts;

                e->size = size;

                e->min_distance = 0;

                e->flags = AVINDEX_KEYFRAME;

                av_log(mov->fc, AV_LOG_TRACE, "AVIndex stream %d, chunk %d, offset %"PRIx64", dts %"PRId64", "

                        "size %d, duration %d\n", st->index, i, current_offset, current_dts,

                        size, samples);



                current_offset += size;

                current_dts += samples;

                chunk_samples -= samples;

            }

        }

    }

}

static int32_t scsi_target_send_command(SCSIRequest *req, uint8_t *buf)

{

    SCSITargetReq *r = DO_UPCAST(SCSITargetReq, req, req);



    switch (buf[0]) {

    case REPORT_LUNS:

        if (!scsi_target_emulate_report_luns(r)) {

            goto illegal_request;

        }

        break;

    case INQUIRY:

        if (!scsi_target_emulate_inquiry(r)) {

            goto illegal_request;

        }

        break;

    case REQUEST_SENSE:

        scsi_target_alloc_buf(&r->req, scsi_sense_len(req));

        r->len = scsi_device_get_sense(r->req.dev, r->buf,

                                       MIN(req->cmd.xfer, r->buf_len),

                                       (req->cmd.buf[1] & 1) == 0);

        if (r->req.dev->sense_is_ua) {

            scsi_device_unit_attention_reported(req->dev);

            r->req.dev->sense_len = 0;

            r->req.dev->sense_is_ua = false;

        }

        break;

    case TEST_UNIT_READY:

        break;

    default:

        scsi_req_build_sense(req, SENSE_CODE(LUN_NOT_SUPPORTED));

        scsi_req_complete(req, CHECK_CONDITION);

        return 0;

    illegal_request:

        scsi_req_build_sense(req, SENSE_CODE(INVALID_FIELD));

        scsi_req_complete(req, CHECK_CONDITION);

        return 0;

    }



    if (!r->len) {

        scsi_req_complete(req, GOOD);

    }

    return r->len;

}

static inline int onenand_load_spare(OneNANDState *s, int sec, int secn,

                void *dest)

{

    uint8_t buf[512];



    if (s->bdrv_cur) {

        if (bdrv_read(s->bdrv_cur, s->secs_cur + (sec >> 5), buf, 1) < 0)

            return 1;

        memcpy(dest, buf + ((sec & 31) << 4), secn << 4);

    } else if (sec + secn > s->secs_cur)

        return 1;

    else

        memcpy(dest, s->current + (s->secs_cur << 9) + (sec << 4), secn << 4);



    return 0;

}

