int pci_drive_hot_add(Monitor *mon, const QDict *qdict, DriveInfo *dinfo)

{

    int dom, pci_bus;

    unsigned slot;

    PCIDevice *dev;

    const char *pci_addr = qdict_get_str(qdict, "pci_addr");



    switch (dinfo->type) {

    case IF_SCSI:

        if (pci_read_devaddr(mon, pci_addr, &dom, &pci_bus, &slot)) {

            goto err;

        }

        dev = pci_find_device(pci_find_root_bus(dom), pci_bus,

                              PCI_DEVFN(slot, 0));

        if (!dev) {

            monitor_printf(mon, "no pci device with address %s\n", pci_addr);

            goto err;

        }

        if (scsi_hot_add(mon, &dev->qdev, dinfo, 1) != 0) {

            goto err;

        }

        break;

    default:

        monitor_printf(mon, "Can't hot-add drive to type %d\n", dinfo->type);

        goto err;

    }



    return 0;

err:

    return -1;

}

static int read_ir(AVFilterLink *link, AVFrame *frame)

{

    AVFilterContext *ctx = link->dst;

    AudioFIRContext *s = ctx->priv;

    int nb_taps, max_nb_taps;



    av_audio_fifo_write(s->fifo[1], (void **)frame->extended_data,

                        frame->nb_samples);

    av_frame_free(&frame);



    nb_taps = av_audio_fifo_size(s->fifo[1]);

    max_nb_taps = MAX_IR_DURATION * ctx->outputs[0]->sample_rate;

    if (nb_taps > max_nb_taps) {

        av_log(ctx, AV_LOG_ERROR, "Too big number of coefficients: %d > %d.\n", nb_taps, max_nb_taps);

        return AVERROR(EINVAL);

    }



    return 0;

}

void cpu_loop(CPUSH4State *env)

{

    CPUState *cs = CPU(sh_env_get_cpu(env));

    int trapnr, ret;

    target_siginfo_t info;



    while (1) {

        cpu_exec_start(cs);

        trapnr = cpu_sh4_exec(cs);

        cpu_exec_end(cs);



        switch (trapnr) {

        case 0x160:

            env->pc += 2;

            ret = do_syscall(env,

                             env->gregs[3],

                             env->gregs[4],

                             env->gregs[5],

                             env->gregs[6],

                             env->gregs[7],

                             env->gregs[0],

                             env->gregs[1],

                             0, 0);

            env->gregs[0] = ret;

            break;

        case EXCP_INTERRUPT:

            /* just indicate that signals should be handled asap */

            break;

        case EXCP_DEBUG:

            {

                int sig;



                sig = gdb_handlesig(cs, TARGET_SIGTRAP);

                if (sig)

                  {

                    info.si_signo = sig;

                    info.si_errno = 0;

                    info.si_code = TARGET_TRAP_BRKPT;

                    queue_signal(env, info.si_signo, &info);

                  }

            }

            break;

	case 0xa0:

	case 0xc0:

            info.si_signo = TARGET_SIGSEGV;

            info.si_errno = 0;

            info.si_code = TARGET_SEGV_MAPERR;

            info._sifields._sigfault._addr = env->tea;

            queue_signal(env, info.si_signo, &info);

	    break;



        default:

            printf ("Unhandled trap: 0x%x\n", trapnr);

            cpu_dump_state(cs, stderr, fprintf, 0);

            exit(EXIT_FAILURE);

        }

        process_pending_signals (env);

    }

}

