static int kvm_arch_set_tsc_khz(CPUState *cs)

{

    X86CPU *cpu = X86_CPU(cs);

    CPUX86State *env = &cpu->env;

    int r;



    if (!env->tsc_khz) {

        return 0;

    }



    r = kvm_check_extension(cs->kvm_state, KVM_CAP_TSC_CONTROL) ?

        kvm_vcpu_ioctl(cs, KVM_SET_TSC_KHZ, env->tsc_khz) :

        -ENOTSUP;

    if (r < 0) {

        /* When KVM_SET_TSC_KHZ fails, it's an error only if the current

         * TSC frequency doesn't match the one we want.

         */

        int cur_freq = kvm_check_extension(cs->kvm_state, KVM_CAP_GET_TSC_KHZ) ?

                       kvm_vcpu_ioctl(cs, KVM_GET_TSC_KHZ) :

                       -ENOTSUP;

        if (cur_freq <= 0 || cur_freq != env->tsc_khz) {

            error_report("warning: TSC frequency mismatch between "

                         "VM (%" PRId64 " kHz) and host (%d kHz), "

                         "and TSC scaling unavailable",

                         env->tsc_khz, cur_freq);

            return r;

        }

    }



    return 0;

}

int ff_frame_thread_encoder_init(AVCodecContext *avctx, AVDictionary *options){

    int i=0;

    ThreadContext *c;





    if(   !(avctx->thread_type & FF_THREAD_FRAME)

       || !(avctx->codec->capabilities & CODEC_CAP_INTRA_ONLY))

        return 0;



    if(   !avctx->thread_count

       && avctx->codec_id == AV_CODEC_ID_MJPEG

       && !(avctx->flags & CODEC_FLAG_QSCALE)) {

        av_log(avctx, AV_LOG_DEBUG,

               "Forcing thread count to 1 for MJPEG encoding, use -thread_type slice "

               "or a constant quantizer if you want to use multiple cpu cores\n");

        avctx->thread_count = 1;

    }

    if(   avctx->thread_count > 1

       && avctx->codec_id == AV_CODEC_ID_MJPEG

       && !(avctx->flags & CODEC_FLAG_QSCALE))

        av_log(avctx, AV_LOG_WARNING,

               "MJPEG CBR encoding works badly with frame multi-threading, consider "

               "using -threads 1, -thread_type slice or a constant quantizer.\n");

    if(!avctx->thread_count) {

        avctx->thread_count = av_cpu_count();

        avctx->thread_count = FFMIN(avctx->thread_count, MAX_THREADS);

    }



    if(avctx->thread_count <= 1)

        return 0;



    if (avctx->codec_id == AV_CODEC_ID_HUFFYUV ||

        avctx->codec_id == AV_CODEC_ID_FFVHUFF) {

        // huffyuv doesnt support these with multiple frame threads currently

        if (avctx->context_model > 0 || (avctx->flags & CODEC_FLAG_PASS1))

            return 0;

    }



    if(avctx->thread_count > MAX_THREADS)

        return AVERROR(EINVAL);



    av_assert0(!avctx->internal->frame_thread_encoder);

    c = avctx->internal->frame_thread_encoder = av_mallocz(sizeof(ThreadContext));

    if(!c)

        return AVERROR(ENOMEM);



    c->parent_avctx = avctx;



    c->task_fifo = av_fifo_alloc(sizeof(Task) * BUFFER_SIZE);

    if(!c->task_fifo)

        goto fail;



    pthread_mutex_init(&c->task_fifo_mutex, NULL);

    pthread_mutex_init(&c->finished_task_mutex, NULL);

    pthread_mutex_init(&c->buffer_mutex, NULL);

    pthread_cond_init(&c->task_fifo_cond, NULL);

    pthread_cond_init(&c->finished_task_cond, NULL);



    for(i=0; i<avctx->thread_count ; i++){

        AVDictionary *tmp = NULL;

        void *tmpv;

        AVCodecContext *thread_avctx = avcodec_alloc_context3(avctx->codec);

        if(!thread_avctx)

            goto fail;

        tmpv = thread_avctx->priv_data;

        *thread_avctx = *avctx;

        thread_avctx->priv_data = tmpv;

        thread_avctx->internal = NULL;

        memcpy(thread_avctx->priv_data, avctx->priv_data, avctx->codec->priv_data_size);

        thread_avctx->thread_count = 1;

        thread_avctx->active_thread_type &= ~FF_THREAD_FRAME;



        av_dict_copy(&tmp, options, 0);

        av_dict_set(&tmp, "threads", "1", 0);

        if(avcodec_open2(thread_avctx, avctx->codec, &tmp) < 0) {

            av_dict_free(&tmp);

            goto fail;

        }

        av_dict_free(&tmp);

        av_assert0(!thread_avctx->internal->frame_thread_encoder);

        thread_avctx->internal->frame_thread_encoder = c;

        if(pthread_create(&c->worker[i], NULL, worker, thread_avctx)) {

            goto fail;

        }

    }



    avctx->active_thread_type = FF_THREAD_FRAME;



    return 0;

fail:

    avctx->thread_count = i;

    av_log(avctx, AV_LOG_ERROR, "ff_frame_thread_encoder_init failed\n");

    ff_frame_thread_encoder_free(avctx);

    return -1;

}

static void intra_predict_mad_cow_dc_0l0_8x8_msa(uint8_t *src, int32_t stride)

{

    uint8_t lp_cnt;

    uint32_t src0 = 0;

    uint64_t out0, out1;



    for (lp_cnt = 0; lp_cnt < 4; lp_cnt++) {

        src0 += src[(4 + lp_cnt) * stride - 1];

    }



    src0 = (src0 + 2) >> 2;



    out0 = 0x8080808080808080;

    out1 = src0 * 0x0101010101010101;



    for (lp_cnt = 4; lp_cnt--;) {

        SD(out0, src);

        SD(out1, src + stride * 4);

        src += stride;

    }

}

static void srt_to_ass(AVCodecContext *avctx, AVBPrint *dst,

                       const char *in, int x1, int y1, int x2, int y2)

{

    if (x1 >= 0 && y1 >= 0) {

        /* XXX: here we rescale coordinate assuming they are in DVD resolution

         * (720x480) since we don't have anything better */



        if (x2 >= 0 && y2 >= 0 && (x2 != x1 || y2 != y1) && x2 >= x1 && y2 >= y1) {

            /* text rectangle defined, write the text at the center of the rectangle */

            const int cx = x1 + (x2 - x1)/2;

            const int cy = y1 + (y2 - y1)/2;

            const int scaled_x = cx * (int64_t)ASS_DEFAULT_PLAYRESX / 720;

            const int scaled_y = cy * (int64_t)ASS_DEFAULT_PLAYRESY / 480;

            av_bprintf(dst, "{\\an5}{\\pos(%d,%d)}", scaled_x, scaled_y);

        } else {

            /* only the top left corner, assume the text starts in that corner */

            const int scaled_x = x1 * (int64_t)ASS_DEFAULT_PLAYRESX / 720;

            const int scaled_y = y1 * (int64_t)ASS_DEFAULT_PLAYRESY / 480;

            av_bprintf(dst, "{\\an1}{\\pos(%d,%d)}", scaled_x, scaled_y);

        }

    }



    ff_htmlmarkup_to_ass(avctx, dst, in);

}

static int msvideo1_decode_frame(AVCodecContext *avctx,

                                void *data, int *got_frame,

                                AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    Msvideo1Context *s = avctx->priv_data;

    int ret;



    s->buf = buf;

    s->size = buf_size;



    if ((ret = ff_reget_buffer(avctx, s->frame)) < 0)

        return ret;



    if (s->mode_8bit) {

        const uint8_t *pal = av_packet_get_side_data(avpkt, AV_PKT_DATA_PALETTE, NULL);



        if (pal) {

            memcpy(s->pal, pal, AVPALETTE_SIZE);

            s->frame->palette_has_changed = 1;

        }

    }



    if (s->mode_8bit)

        msvideo1_decode_8bit(s);

    else

        msvideo1_decode_16bit(s);



    if ((ret = av_frame_ref(data, s->frame)) < 0)

        return ret;



    *got_frame      = 1;



    /* report that the buffer was completely consumed */

    return buf_size;

}

pvscsi_realizefn(PCIDevice *pci_dev, Error **errp)

{

    PVSCSIState *s = PVSCSI(pci_dev);



    trace_pvscsi_state("init");



    /* PCI subsystem ID, subsystem vendor ID, revision */

    if (PVSCSI_USE_OLD_PCI_CONFIGURATION(s)) {

        pci_set_word(pci_dev->config + PCI_SUBSYSTEM_ID, 0x1000);

    } else {

        pci_set_word(pci_dev->config + PCI_SUBSYSTEM_VENDOR_ID,

                     PCI_VENDOR_ID_VMWARE);

        pci_set_word(pci_dev->config + PCI_SUBSYSTEM_ID,

                     PCI_DEVICE_ID_VMWARE_PVSCSI);

        pci_config_set_revision(pci_dev->config, 0x2);

    }



    /* PCI latency timer = 255 */

    pci_dev->config[PCI_LATENCY_TIMER] = 0xff;



    /* Interrupt pin A */

    pci_config_set_interrupt_pin(pci_dev->config, 1);



    memory_region_init_io(&s->io_space, OBJECT(s), &pvscsi_ops, s,

                          "pvscsi-io", PVSCSI_MEM_SPACE_SIZE);

    pci_register_bar(pci_dev, 0, PCI_BASE_ADDRESS_SPACE_MEMORY, &s->io_space);



    pvscsi_init_msi(s);



    if (pci_is_express(pci_dev) && pci_bus_is_express(pci_dev->bus)) {

        pcie_endpoint_cap_init(pci_dev, PVSCSI_EXP_EP_OFFSET);

    }



    s->completion_worker = qemu_bh_new(pvscsi_process_completion_queue, s);



    scsi_bus_new(&s->bus, sizeof(s->bus), DEVICE(pci_dev),

                 &pvscsi_scsi_info, NULL);

    /* override default SCSI bus hotplug-handler, with pvscsi's one */

    qbus_set_hotplug_handler(BUS(&s->bus), DEVICE(s), &error_abort);

    pvscsi_reset_state(s);

}

