setup_sigcontext(struct target_sigcontext *sc, struct target_fpstate *fpstate,

		 CPUX86State *env, unsigned long mask)

{

	int err = 0;



	err |= __put_user(env->segs[R_GS], (unsigned int *)&sc->gs);

	err |= __put_user(env->segs[R_FS], (unsigned int *)&sc->fs);

	err |= __put_user(env->segs[R_ES], (unsigned int *)&sc->es);

	err |= __put_user(env->segs[R_DS], (unsigned int *)&sc->ds);

	err |= __put_user(env->regs[R_EDI], &sc->edi);

	err |= __put_user(env->regs[R_ESI], &sc->esi);

	err |= __put_user(env->regs[R_EBP], &sc->ebp);

	err |= __put_user(env->regs[R_ESP], &sc->esp);

	err |= __put_user(env->regs[R_EBX], &sc->ebx);

	err |= __put_user(env->regs[R_EDX], &sc->edx);

	err |= __put_user(env->regs[R_ECX], &sc->ecx);

	err |= __put_user(env->regs[R_EAX], &sc->eax);

	err |= __put_user(env->exception_index, &sc->trapno);

	err |= __put_user(env->error_code, &sc->err);

	err |= __put_user(env->eip, &sc->eip);

	err |= __put_user(env->segs[R_CS], (unsigned int *)&sc->cs);

	err |= __put_user(env->eflags, &sc->eflags);

	err |= __put_user(env->regs[R_ESP], &sc->esp_at_signal);

	err |= __put_user(env->segs[R_SS], (unsigned int *)&sc->ss);

#if 0

	tmp = save_i387(fpstate);

	if (tmp < 0)

	  err = 1;

	else

	  err |= __put_user(tmp ? fpstate : NULL, &sc->fpstate);

#else

        err |= __put_user(0, &sc->fpstate);

#endif

	/* non-iBCS2 extensions.. */

	err |= __put_user(mask, &sc->oldmask);

	err |= __put_user(/*current->thread.cr2*/ 0, &sc->cr2);

	return err;

}

static void esp_command_complete(SCSIBus *bus, int reason, uint32_t tag,

                                 uint32_t arg)

{

    ESPState *s = DO_UPCAST(ESPState, busdev.qdev, bus->qbus.parent);



    if (reason == SCSI_REASON_DONE) {

        DPRINTF("SCSI Command complete\n");

        if (s->ti_size != 0)

            DPRINTF("SCSI command completed unexpectedly\n");

        s->ti_size = 0;

        s->dma_left = 0;

        s->async_len = 0;

        if (arg)

            DPRINTF("Command failed\n");

        s->sense = arg;

        s->rregs[ESP_RSTAT] = STAT_ST;

        esp_dma_done(s);

        s->current_dev = NULL;

    } else {

        DPRINTF("transfer %d/%d\n", s->dma_left, s->ti_size);

        s->async_len = arg;

        s->async_buf = s->current_dev->info->get_buf(s->current_dev, 0);

        if (s->dma_left) {

            esp_do_dma(s);

        } else if (s->dma_counter != 0 && s->ti_size <= 0) {

            /* If this was the last part of a DMA transfer then the

               completion interrupt is deferred to here.  */

            esp_dma_done(s);

        }

    }

}

static inline CopyRet receive_frame(AVCodecContext *avctx,

                                    void *data, int *data_size,

                                    uint8_t second_field)

{

    BC_STATUS ret;

    BC_DTS_PROC_OUT output = {

        .PicInfo.width  = avctx->width,

        .PicInfo.height = avctx->height,

    };

    CHDContext *priv = avctx->priv_data;

    HANDLE dev       = priv->dev;



    *data_size = 0;



    // Request decoded data from the driver

    ret = DtsProcOutputNoCopy(dev, OUTPUT_PROC_TIMEOUT, &output);

    if (ret == BC_STS_FMT_CHANGE) {

        av_log(avctx, AV_LOG_VERBOSE, "CrystalHD: Initial format change\n");

        avctx->width  = output.PicInfo.width;

        avctx->height = output.PicInfo.height;

        return RET_COPY_AGAIN;

    } else if (ret == BC_STS_SUCCESS) {

        int copy_ret = -1;

        if (output.PoutFlags & BC_POUT_FLAGS_PIB_VALID) {

            if (priv->last_picture == -1) {

                /*

                 * Init to one less, so that the incrementing code doesn't

                 * need to be special-cased.

                 */

                priv->last_picture = output.PicInfo.picture_number - 1;

            }



            if (avctx->codec->id == CODEC_ID_MPEG4 &&

                output.PicInfo.timeStamp == 0) {

                av_log(avctx, AV_LOG_VERBOSE,

                       "CrystalHD: Not returning packed frame twice.\n");

                priv->last_picture++;

                DtsReleaseOutputBuffs(dev, NULL, FALSE);

                return RET_COPY_AGAIN;

            }



            print_frame_info(priv, &output);



            if (priv->last_picture + 1 < output.PicInfo.picture_number) {

                av_log(avctx, AV_LOG_WARNING,

                       "CrystalHD: Picture Number discontinuity\n");

                /*

                 * Have we lost frames? If so, we need to shrink the

                 * pipeline length appropriately.

                 *

                 * XXX: I have no idea what the semantics of this situation

                 * are so I don't even know if we've lost frames or which

                 * ones.

                 *

                 * In any case, only warn the first time.

                 */

               priv->last_picture = output.PicInfo.picture_number - 1;

            }



            copy_ret = copy_frame(avctx, &output, data, data_size, second_field);

            if (*data_size > 0) {

                avctx->has_b_frames--;

                priv->last_picture++;

                av_log(avctx, AV_LOG_VERBOSE, "CrystalHD: Pipeline length: %u\n",

                       avctx->has_b_frames);

            }

        } else {

            /*

             * An invalid frame has been consumed.

             */

            av_log(avctx, AV_LOG_ERROR, "CrystalHD: ProcOutput succeeded with "

                                        "invalid PIB\n");

            avctx->has_b_frames--;

            copy_ret = RET_OK;

        }

        DtsReleaseOutputBuffs(dev, NULL, FALSE);



        return copy_ret;

    } else if (ret == BC_STS_BUSY) {

        return RET_COPY_AGAIN;

    } else {

        av_log(avctx, AV_LOG_ERROR, "CrystalHD: ProcOutput failed %d\n", ret);

        return RET_ERROR;

    }

}

static int encode_frame(AVCodecContext *avctx, QSVEncContext *q,

                        const AVFrame *frame)

{

    AVPacket new_pkt = { 0 };

    mfxBitstream *bs;



    mfxFrameSurface1 *surf = NULL;

    mfxSyncPoint sync      = NULL;

    int ret;



    if (frame) {

        ret = submit_frame(q, frame, &surf);

        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "Error submitting the frame for encoding.\n");

            return ret;

        }

    }



    ret = av_new_packet(&new_pkt, q->packet_size);

    if (ret < 0) {

        av_log(avctx, AV_LOG_ERROR, "Error allocating the output packet\n");

        return ret;

    }



    bs = av_mallocz(sizeof(*bs));

    if (!bs) {

        av_packet_unref(&new_pkt);

        return AVERROR(ENOMEM);

    }

    bs->Data      = new_pkt.data;

    bs->MaxLength = new_pkt.size;



    do {

        ret = MFXVideoENCODE_EncodeFrameAsync(q->session, NULL, surf, bs, &sync);

        if (ret == MFX_WRN_DEVICE_BUSY)

            av_usleep(1);

    } while (ret > 0);



    if (ret < 0) {

        av_packet_unref(&new_pkt);

        av_freep(&bs);

        return (ret == MFX_ERR_MORE_DATA) ? 0 : ff_qsv_error(ret);

    }



    if (ret == MFX_WRN_INCOMPATIBLE_VIDEO_PARAM && frame->interlaced_frame)

        print_interlace_msg(avctx, q);



    if (sync) {

        av_fifo_generic_write(q->async_fifo, &new_pkt, sizeof(new_pkt), NULL);

        av_fifo_generic_write(q->async_fifo, &sync,    sizeof(sync),    NULL);

        av_fifo_generic_write(q->async_fifo, &bs,      sizeof(bs),    NULL);

    } else {

        av_packet_unref(&new_pkt);

        av_freep(&bs);

    }



    return 0;

}

