static void cadence_timer_sync(CadenceTimerState *s)

{

    int i;

    int64_t r, x;

    int64_t interval = ((s->reg_count & COUNTER_CTRL_INT) ?

            (int64_t)s->reg_interval + 1 : 0x10000ULL) << 16;

    uint64_t old_time = s->cpu_time;



    s->cpu_time = qemu_clock_get_ns(QEMU_CLOCK_VIRTUAL);

    DB_PRINT("cpu time: %lld ns\n", (long long)old_time);



    if (!s->cpu_time_valid || old_time == s->cpu_time) {

        s->cpu_time_valid = 1;

        return;

    }



    r = (int64_t)cadence_timer_get_steps(s, s->cpu_time - old_time);

    x = (int64_t)s->reg_value + ((s->reg_count & COUNTER_CTRL_DEC) ? -r : r);



    for (i = 0; i < 3; ++i) {

        int64_t m = (int64_t)s->reg_match[i] << 16;

        if (m > interval) {

            continue;

        }

        /* check to see if match event has occurred. check m +/- interval

         * to account for match events in wrap around cases */

        if (is_between(m, s->reg_value, x) ||

            is_between(m + interval, s->reg_value, x) ||

            is_between(m - interval, s->reg_value, x)) {

            s->reg_intr |= (2 << i);

        }

    }

    while (x < 0) {

        x += interval;

    }

    s->reg_value = (uint32_t)(x % interval);



    if (s->reg_value != x) {

        s->reg_intr |= (s->reg_count & COUNTER_CTRL_INT) ?

            COUNTER_INTR_IV : COUNTER_INTR_OV;

    }

    cadence_timer_update(s);

}

static void tcg_out_brcond_i64(TCGContext *s, TCGCond cond, TCGReg arg1,

                               int32_t arg2, int const_arg2, int label)

{

    /* For 64-bit signed comparisons vs zero, we can avoid the compare.  */

    if (arg2 == 0 && !is_unsigned_cond(cond)) {

        TCGLabel *l = &s->labels[label];

        int off16;



        if (l->has_value) {

            off16 = INSN_OFF16(tcg_pcrel_diff(s, l->u.value_ptr));

        } else {

            /* Make sure to preserve destinations during retranslation.  */

            off16 = *s->code_ptr & INSN_OFF16(-1);

            tcg_out_reloc(s, s->code_ptr, R_SPARC_WDISP16, label, 0);

        }

        tcg_out32(s, INSN_OP(0) | INSN_OP2(3) | BPR_PT | INSN_RS1(arg1)

                  | INSN_COND(tcg_cond_to_rcond[cond]) | off16);

    } else {

        tcg_out_cmp(s, arg1, arg2, const_arg2);

        tcg_out_bpcc(s, tcg_cond_to_bcond[cond], BPCC_XCC | BPCC_PT, label);

    }

    tcg_out_nop(s);

}

int pci_bridge_initfn(PCIDevice *dev)

{

    PCIBus *parent = dev->bus;

    PCIBridge *br = DO_UPCAST(PCIBridge, dev, dev);

    PCIBus *sec_bus = &br->sec_bus;



    pci_set_word(dev->config + PCI_STATUS,

                 PCI_STATUS_66MHZ | PCI_STATUS_FAST_BACK);

    pci_config_set_class(dev->config, PCI_CLASS_BRIDGE_PCI);

    dev->config[PCI_HEADER_TYPE] =

        (dev->config[PCI_HEADER_TYPE] & PCI_HEADER_TYPE_MULTI_FUNCTION) |

        PCI_HEADER_TYPE_BRIDGE;

    pci_set_word(dev->config + PCI_SEC_STATUS,

                 PCI_STATUS_66MHZ | PCI_STATUS_FAST_BACK);



    qbus_create_inplace(&sec_bus->qbus, &pci_bus_info, &dev->qdev,

                        br->bus_name);

    sec_bus->parent_dev = dev;

    sec_bus->map_irq = br->map_irq;

    sec_bus->address_space_mem = &br->address_space_mem;

    memory_region_init(&br->address_space_mem, "pci_bridge_pci", INT64_MAX);

    sec_bus->address_space_io = &br->address_space_io;

    memory_region_init(&br->address_space_io, "pci_bridge_io", 65536);

    pci_bridge_region_init(br);

    QLIST_INIT(&sec_bus->child);

    QLIST_INSERT_HEAD(&parent->child, sec_bus, sibling);

    return 0;

}

static void clear_sdr_rep(IPMIBmcSim *ibs,

                          uint8_t *cmd, unsigned int cmd_len,

                          uint8_t *rsp, unsigned int *rsp_len,

                          unsigned int max_rsp_len)

{

    IPMI_CHECK_CMD_LEN(8);

    IPMI_CHECK_RESERVATION(2, ibs->sdr.reservation);

    if (cmd[4] != 'C' || cmd[5] != 'L' || cmd[6] != 'R') {

        rsp[2] = IPMI_CC_INVALID_DATA_FIELD;

        return;

    }

    if (cmd[7] == 0xaa) {

        ibs->sdr.next_free = 0;

        ibs->sdr.overflow = 0;

        set_timestamp(ibs, ibs->sdr.last_clear);

        IPMI_ADD_RSP_DATA(1); /* Erasure complete */

        sdr_inc_reservation(&ibs->sdr);

    } else if (cmd[7] == 0) {

        IPMI_ADD_RSP_DATA(1); /* Erasure complete */

    } else {

        rsp[2] = IPMI_CC_INVALID_DATA_FIELD;

        return;

    }

}

static inline void RENAME(initFilter)(int16_t *dstFilter, int16_t *filterPos, int *filterSize, int xInc,

				      int srcW, int dstW, int filterAlign, int one)

{

	int i;

	double filter[8000];

#ifdef HAVE_MMX

	asm volatile("emms\n\t"::: "memory"); //FIXME this shouldnt be required but it IS (even for non mmx versions)

#endif



	if(ABS(xInc - 0x10000) <10) // unscaled

	{

		int i;

		*filterSize= (1 +(filterAlign-1)) & (~(filterAlign-1)); // 1 or 4 normaly

		for(i=0; i<dstW*(*filterSize); i++) filter[i]=0;



		for(i=0; i<dstW; i++)

		{

			filter[i*(*filterSize)]=1;

			filterPos[i]=i;

		}



	}

	else if(xInc <= (1<<16) || sws_flags==SWS_FAST_BILINEAR) // upscale

	{

		int i;

		int xDstInSrc;

		if(sws_flags==SWS_BICUBIC) *filterSize= 4;

		else			   *filterSize= 2;

//		printf("%d %d %d\n", filterSize, srcW, dstW);

		*filterSize= (*filterSize +(filterAlign-1)) & (~(filterAlign-1));



		xDstInSrc= xInc/2 - 0x8000;

		for(i=0; i<dstW; i++)

		{

			int xx= (xDstInSrc>>16) - (*filterSize>>1) + 1;

			int j;



			filterPos[i]= xx;

			if(sws_flags == SWS_BICUBIC)

			{

				double d= ABS(((xx+1)<<16) - xDstInSrc)/(double)(1<<16);

				double y1,y2,y3,y4;

				double A= -0.75;

					// Equation is from VirtualDub

				y1 = (        +     A*d -       2.0*A*d*d +       A*d*d*d);

				y2 = (+ 1.0             -     (A+3.0)*d*d + (A+2.0)*d*d*d);

				y3 = (        -     A*d + (2.0*A+3.0)*d*d - (A+2.0)*d*d*d);

				y4 = (                  +           A*d*d -       A*d*d*d);



//				printf("%d %d %d \n", coeff, (int)d, xDstInSrc);

				filter[i*(*filterSize) + 0]= y1;

				filter[i*(*filterSize) + 1]= y2;

				filter[i*(*filterSize) + 2]= y3;

				filter[i*(*filterSize) + 3]= y4;

//				printf("%1.3f %d, %d, %d, %d\n",d , y1, y2, y3, y4);

			}

			else

			{

				for(j=0; j<*filterSize; j++)

				{

					double d= ABS((xx<<16) - xDstInSrc)/(double)(1<<16);

					double coeff= 1.0 - d;

					if(coeff<0) coeff=0;

	//				printf("%d %d %d \n", coeff, (int)d, xDstInSrc);

					filter[i*(*filterSize) + j]= coeff;

					xx++;

				}

			}

			xDstInSrc+= xInc;

		}

	}

	else // downscale

	{

		int xDstInSrc;

		if(sws_flags==SWS_BICUBIC) *filterSize= (int)ceil(1 + 4.0*srcW / (double)dstW);

		else			   *filterSize= (int)ceil(1 + 2.0*srcW / (double)dstW);

//		printf("%d %d %d\n", *filterSize, srcW, dstW);

		*filterSize= (*filterSize +(filterAlign-1)) & (~(filterAlign-1));



		xDstInSrc= xInc/2 - 0x8000;

		for(i=0; i<dstW; i++)

		{

			int xx= (int)((double)xDstInSrc/(double)(1<<16) - ((*filterSize)-1)*0.5 + 0.5);

			int j;



			filterPos[i]= xx;

			for(j=0; j<*filterSize; j++)

			{

				double d= ABS((xx<<16) - xDstInSrc)/(double)xInc;

				double coeff;

				if(sws_flags == SWS_BICUBIC)

				{

					double A= -0.75;

//					d*=2;

					// Equation is from VirtualDub

					if(d<1.0)

						coeff = (1.0 - (A+3.0)*d*d + (A+2.0)*d*d*d);

					else if(d<2.0)

						coeff = (-4.0*A + 8.0*A*d - 5.0*A*d*d + A*d*d*d);

					else

						coeff=0.0;

				}

				else

				{

					coeff= 1.0 - d;

					if(coeff<0) coeff=0;

				}

//				if(filterAlign==1) printf("%d %d %d \n", coeff, (int)d, xDstInSrc);

				filter[i*(*filterSize) + j]= coeff;

				xx++;

			}

			xDstInSrc+= xInc;

		}

	}



	//fix borders

	for(i=0; i<dstW; i++)

	{

		int j;

		if(filterPos[i] < 0)

		{

			// Move filter coeffs left to compensate for filterPos

			for(j=1; j<*filterSize; j++)

			{

				int left= MAX(j + filterPos[i], 0);

				filter[i*(*filterSize) + left] += filter[i*(*filterSize) + j];

				filter[i*(*filterSize) + j]=0;

			}

			filterPos[i]= 0;

		}



		if(filterPos[i] + (*filterSize) > srcW)

		{

			int shift= filterPos[i] + (*filterSize) - srcW;

			// Move filter coeffs right to compensate for filterPos

			for(j=(*filterSize)-2; j>=0; j--)

			{

				int right= MIN(j + shift, (*filterSize)-1);

				filter[i*(*filterSize) +right] += filter[i*(*filterSize) +j];

				filter[i*(*filterSize) +j]=0;

			}

			filterPos[i]= srcW - (*filterSize);

		}

	}



	//FIXME try to align filterpos if possible / try to shift filterpos to put zeros at the end

	// and skip these than later



	//Normalize

	for(i=0; i<dstW; i++)

	{

		int j;

		double sum=0;

		double scale= one;

		for(j=0; j<*filterSize; j++)

		{

			sum+= filter[i*(*filterSize) + j];

		}

		scale/= sum;

		for(j=0; j<*filterSize; j++)

		{

			dstFilter[i*(*filterSize) + j]= (int)(filter[i*(*filterSize) + j]*scale);

		}

	}

}

static CharDriverState *qmp_chardev_open_file(const char *id,

                                              ChardevBackend *backend,

                                              ChardevReturn *ret,

                                              Error **errp)

{

    ChardevFile *file = backend->u.file;

    ChardevCommon *common = qapi_ChardevFile_base(file);

    HANDLE out;



    if (file->has_in) {

        error_setg(errp, "input file not supported");

        return NULL;

    }



    out = CreateFile(file->out, GENERIC_WRITE, FILE_SHARE_READ, NULL,

                     OPEN_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);

    if (out == INVALID_HANDLE_VALUE) {

        error_setg(errp, "open %s failed", file->out);

        return NULL;

    }

    return qemu_chr_open_win_file(out, common, errp);

}

