    int ret;
    uint16_t chunk_id;
    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0)
        return ret;
    chunk_id = AV_RL16(avpkt->data + 4);
    if (chunk_id == HNM4_CHUNK_ID_PL) {
        hnm_update_palette(avctx, avpkt->data, avpkt->size);
        frame->palette_has_changed = 1;
