static int vnc_zlib_stop(VncState *vs)

{

    z_streamp zstream = &vs->zlib_stream;

    int previous_out;



    // switch back to normal output/zlib buffers

    vs->zlib = vs->output;

    vs->output = vs->zlib_tmp;



    // compress the zlib buffer



    // initialize the stream

    // XXX need one stream per session

    if (zstream->opaque != vs) {

        int err;



        VNC_DEBUG("VNC: initializing zlib stream\n");

        VNC_DEBUG("VNC: opaque = %p | vs = %p\n", zstream->opaque, vs);

        zstream->zalloc = vnc_zlib_zalloc;

        zstream->zfree = vnc_zlib_zfree;



        err = deflateInit2(zstream, vs->tight_compression, Z_DEFLATED, MAX_WBITS,

                           MAX_MEM_LEVEL, Z_DEFAULT_STRATEGY);



        if (err != Z_OK) {

            fprintf(stderr, "VNC: error initializing zlib\n");

            return -1;

        }



        vs->zlib_level = vs->tight_compression;

        zstream->opaque = vs;

    }



    if (vs->tight_compression != vs->zlib_level) {

        if (deflateParams(zstream, vs->tight_compression,

                          Z_DEFAULT_STRATEGY) != Z_OK) {

            return -1;

        }

        vs->zlib_level = vs->tight_compression;

    }



    // reserve memory in output buffer

    buffer_reserve(&vs->output, vs->zlib.offset + 64);



    // set pointers

    zstream->next_in = vs->zlib.buffer;

    zstream->avail_in = vs->zlib.offset;

    zstream->next_out = vs->output.buffer + vs->output.offset;

    zstream->avail_out = vs->output.capacity - vs->output.offset;

    zstream->data_type = Z_BINARY;

    previous_out = zstream->total_out;



    // start encoding

    if (deflate(zstream, Z_SYNC_FLUSH) != Z_OK) {

        fprintf(stderr, "VNC: error during zlib compression\n");

        return -1;

    }



    vs->output.offset = vs->output.capacity - zstream->avail_out;

    return zstream->total_out - previous_out;

}

static int ivi_decode_blocks(GetBitContext *gb, IVIBandDesc *band, IVITile *tile,
                             AVCodecContext *avctx)
{
    int         mbn, blk, num_blocks, num_coeffs, blk_size, scan_pos, run, val,
                pos, is_intra, mc_type = 0, mv_x, mv_y, col_mask;
    uint8_t     col_flags[8];
    int32_t     prev_dc, trvec[64];
    uint32_t    cbp, sym, lo, hi, quant, buf_offs, q;
    IVIMbInfo   *mb;
    RVMapDesc   *rvmap = band->rv_map;
    void (*mc_with_delta_func)(int16_t *buf, const int16_t *ref_buf, uint32_t pitch, int mc_type);
    void (*mc_no_delta_func)  (int16_t *buf, const int16_t *ref_buf, uint32_t pitch, int mc_type);
    const uint16_t  *base_tab;
    const uint8_t   *scale_tab;
    prev_dc = 0; /* init intra prediction for the DC coefficient */
    blk_size   = band->blk_size;
    col_mask   = blk_size - 1; /* column mask for tracking non-zero coeffs */
    num_blocks = (band->mb_size != blk_size) ? 4 : 1; /* number of blocks per mb */
    num_coeffs = blk_size * blk_size;
    if (blk_size == 8) {
        mc_with_delta_func = ff_ivi_mc_8x8_delta;
        mc_no_delta_func   = ff_ivi_mc_8x8_no_delta;
    } else {
        mc_with_delta_func = ff_ivi_mc_4x4_delta;
        mc_no_delta_func   = ff_ivi_mc_4x4_no_delta;
    for (mbn = 0, mb = tile->mbs; mbn < tile->num_MBs; mb++, mbn++) {
        is_intra = !mb->type;
        cbp      = mb->cbp;
        buf_offs = mb->buf_offs;
        quant = av_clip(band->glob_quant + mb->q_delta, 0, 23);
        base_tab  = is_intra ? band->intra_base  : band->inter_base;
        scale_tab = is_intra ? band->intra_scale : band->inter_scale;
        if (scale_tab)
            quant = scale_tab[quant];
        if (!is_intra) {
            mv_x = mb->mv_x;
            mv_y = mb->mv_y;
            if (band->is_halfpel) {
                mc_type = ((mv_y & 1) << 1) | (mv_x & 1);
                mv_x >>= 1;
                mv_y >>= 1; /* convert halfpel vectors into fullpel ones */
            if (mb->type) {
                int dmv_x, dmv_y, cx, cy;
                dmv_x = mb->mv_x >> band->is_halfpel;
                dmv_y = mb->mv_y >> band->is_halfpel;
                cx    = mb->mv_x &  band->is_halfpel;
                cy    = mb->mv_y &  band->is_halfpel;
                if (   mb->xpos + dmv_x < 0
                    || mb->xpos + dmv_x + band->mb_size + cx > band->pitch
                    || mb->ypos + dmv_y < 0
                    || mb->ypos + dmv_y + band->mb_size + cy > band->aheight) {
        for (blk = 0; blk < num_blocks; blk++) {
            /* adjust block position in the buffer according to its number */
            if (blk & 1) {
                buf_offs += blk_size;
            } else if (blk == 2) {
                buf_offs -= blk_size;
                buf_offs += blk_size * band->pitch;
            if (cbp & 1) { /* block coded ? */
                scan_pos = -1;
                memset(trvec, 0, num_coeffs*sizeof(trvec[0])); /* zero transform vector */
                memset(col_flags, 0, sizeof(col_flags));      /* zero column flags */
                while (scan_pos <= num_coeffs) {
                    sym = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1);
                    if (sym == rvmap->eob_sym)
                        break; /* End of block */
                    if (sym == rvmap->esc_sym) { /* Escape - run/val explicitly coded using 3 vlc codes */
                        run = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1) + 1;
                        lo  = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1);
                        hi  = get_vlc2(gb, band->blk_vlc.tab->table, IVI_VLC_BITS, 1);
                        val = IVI_TOSIGNED((hi << 6) | lo); /* merge them and convert into signed val */
                    } else {
                        if (sym >= 256U) {
                            av_log(avctx, AV_LOG_ERROR, "Invalid sym encountered: %d.\n", sym);
                            return -1;
                        run = rvmap->runtab[sym];
                        val = rvmap->valtab[sym];
                    /* de-zigzag and dequantize */
                    scan_pos += run;
                    if (scan_pos >= num_coeffs)
                        break;
                    pos = band->scan[scan_pos];
                    if (!val)
                        av_dlog(avctx, "Val = 0 encountered!\n");
                    q = (base_tab[pos] * quant) >> 9;
                    if (q > 1)
                        val = val * q + FFSIGN(val) * (((q ^ 1) - 1) >> 1);
                    trvec[pos] = val;
                    col_flags[pos & col_mask] |= !!val; /* track columns containing non-zero coeffs */
                }// while
                if (scan_pos >= num_coeffs && sym != rvmap->eob_sym)
                    return -1; /* corrupt block data */
                /* undoing DC coeff prediction for intra-blocks */
                if (is_intra && band->is_2d_trans) {
                    prev_dc      += trvec[0];
                    trvec[0]      = prev_dc;
                    col_flags[0] |= !!prev_dc;
                /* apply inverse transform */
                band->inv_transform(trvec, band->buf + buf_offs,
                                    band->pitch, col_flags);
                /* apply motion compensation */
                if (!is_intra)
                    mc_with_delta_func(band->buf + buf_offs,
                                       band->ref_buf + buf_offs + mv_y * band->pitch + mv_x,
                                       band->pitch, mc_type);
            } else {
                /* block not coded */
                /* for intra blocks apply the dc slant transform */
                /* for inter - perform the motion compensation without delta */
                if (is_intra && band->dc_transform) {
                    band->dc_transform(&prev_dc, band->buf + buf_offs,
                                       band->pitch, blk_size);
                } else
                    mc_no_delta_func(band->buf + buf_offs,
                                     band->ref_buf + buf_offs + mv_y * band->pitch + mv_x,
                                     band->pitch, mc_type);
            cbp >>= 1;
        }// for blk
    }// for mbn
    align_get_bits(gb);
    return 0;

static int skip_data_stream_element(AACContext *ac, GetBitContext *gb)

{

    int byte_align = get_bits1(gb);

    int count = get_bits(gb, 8);

    if (count == 255)

        count += get_bits(gb, 8);

    if (byte_align)

        align_get_bits(gb);



    if (get_bits_left(gb) < 8 * count) {

        av_log(ac->avctx, AV_LOG_ERROR, overread_err);

        return -1;

    }

    skip_bits_long(gb, 8 * count);

    return 0;

}

static int filter_frame(AVFilterLink *inlink, AVFrame *inbuf)

{

    AudioPhaserContext *s = inlink->dst->priv;

    AVFilterLink *outlink = inlink->dst->outputs[0];

    AVFrame *outbuf;



    if (av_frame_is_writable(inbuf)) {

        outbuf = inbuf;

    } else {

        outbuf = ff_get_audio_buffer(inlink, inbuf->nb_samples);

        if (!outbuf)

            return AVERROR(ENOMEM);

        av_frame_copy_props(outbuf, inbuf);

    }



    s->phaser(s, inbuf->extended_data, outbuf->extended_data,

              outbuf->nb_samples, outbuf->channels);



    if (inbuf != outbuf)

        av_frame_free(&inbuf);



    return ff_filter_frame(outlink, outbuf);

}

static AVStream *find_stream(void *log, AVFormatContext *avf, const char *spec)

{

    int i, ret, already = 0, stream_id = -1;

    char type_char, dummy;

    AVStream *found = NULL;

    enum AVMediaType type;



    ret = sscanf(spec, "d%[av]%d%c", &type_char, &stream_id, &dummy);

    if (ret >= 1 && ret <= 2) {

        type = type_char == 'v' ? AVMEDIA_TYPE_VIDEO : AVMEDIA_TYPE_AUDIO;

        ret = av_find_best_stream(avf, type, stream_id, -1, NULL, 0);

        if (ret < 0) {

            av_log(log, AV_LOG_ERROR, "No %s stream with index '%d' found\n",

                   av_get_media_type_string(type), stream_id);

            return NULL;

        }

        return avf->streams[ret];

    }

    for (i = 0; i < avf->nb_streams; i++) {

        ret = avformat_match_stream_specifier(avf, avf->streams[i], spec);

        if (ret < 0) {

            av_log(log, AV_LOG_ERROR,

                   "Invalid stream specifier \"%s\"\n", spec);

            return NULL;

        }

        if (!ret)

            continue;

        if (avf->streams[i]->discard != AVDISCARD_ALL) {

            already++;

            continue;

        }

        if (found) {

            av_log(log, AV_LOG_WARNING,

                   "Ambiguous stream specifier \"%s\", using #%d\n", spec, i);

            break;

        }

        found = avf->streams[i];

    }

    if (!found) {

        av_log(log, AV_LOG_WARNING, "Stream specifier \"%s\" %s\n", spec,

               already ? "matched only already used streams" :

                         "did not match any stream");

        return NULL;

    }

    if (found->codec->codec_type != AVMEDIA_TYPE_VIDEO &&

        found->codec->codec_type != AVMEDIA_TYPE_AUDIO) {

        av_log(log, AV_LOG_ERROR, "Stream specifier \"%s\" matched a %s stream,"

               "currently unsupported by libavfilter\n", spec,

               av_get_media_type_string(found->codec->codec_type));

        return NULL;

    }

    return found;

}

static void check_rgb2yuv(void)

{

    declare_func(void, uint8_t *dst[3], ptrdiff_t dst_stride[3],

                 int16_t *src[3], ptrdiff_t src_stride,

                 int w, int h, const int16_t coeff[3][3][8],

                 const int16_t off[8]);

    ColorSpaceDSPContext dsp;

    int odepth, fmt, n;

    LOCAL_ALIGNED_32(int16_t, src_y, [W * H * 2]);

    LOCAL_ALIGNED_32(int16_t, src_u, [W * H * 2]);

    LOCAL_ALIGNED_32(int16_t, src_v, [W * H * 2]);

    int16_t *src[3] = { src_y, src_u, src_v };

    LOCAL_ALIGNED_32(uint8_t, dst0_y, [W * H]);

    LOCAL_ALIGNED_32(uint8_t, dst0_u, [W * H]);

    LOCAL_ALIGNED_32(uint8_t, dst0_v, [W * H]);

    LOCAL_ALIGNED_32(uint8_t, dst1_y, [W * H]);

    LOCAL_ALIGNED_32(uint8_t, dst1_u, [W * H]);

    LOCAL_ALIGNED_32(uint8_t, dst1_v, [W * H]);

    uint8_t *dst0[3] = { dst0_y, dst0_u, dst0_v }, *dst1[3] = { dst1_y, dst1_u, dst1_v };

    LOCAL_ALIGNED_32(int16_t, offset, [8]);

    LOCAL_ALIGNED_32(int16_t, coeff_buf, [3 * 3 * 8]);

    int16_t (*coeff)[3][8] = (int16_t(*)[3][8]) coeff_buf;



    ff_colorspacedsp_init(&dsp);

    for (n = 0; n < 8; n++) {

        offset[n] = 16;



        // these somewhat resemble bt601/smpte170m coefficients

        coeff[0][0][n] = lrint(0.3 * (1 << 14));

        coeff[0][1][n] = lrint(0.6 * (1 << 14));

        coeff[0][2][n] = lrint(0.1 * (1 << 14));

        coeff[1][0][n] = lrint(-0.15 * (1 << 14));

        coeff[1][1][n] = lrint(-0.35 * (1 << 14));

        coeff[1][2][n] = lrint(0.5 * (1 << 14));

        coeff[2][0][n] = lrint(0.5 * (1 << 14));

        coeff[2][1][n] = lrint(-0.42 * (1 << 14));

        coeff[2][2][n] = lrint(-0.08 * (1 << 14));

    }

    for (odepth = 0; odepth < 3; odepth++) {

        for (fmt = 0; fmt < 3; fmt++) {

            if (check_func(dsp.rgb2yuv[odepth][fmt],

                           "ff_colorspacedsp_rgb2yuv_%sp%d",

                           format_string[fmt], odepth * 2 + 8)) {

                int ss_w = !!fmt, ss_h = fmt == 2;

                int y_dst_stride = W << !!odepth;

                int uv_dst_stride = y_dst_stride >> ss_w;



                randomize_buffers();

                call_ref(dst0, (ptrdiff_t[3]) { y_dst_stride, uv_dst_stride, uv_dst_stride },

                         src, W, W, H, coeff, offset);

                call_new(dst1, (ptrdiff_t[3]) { y_dst_stride, uv_dst_stride, uv_dst_stride },

                         src, W, W, H, coeff, offset);

                if (memcmp(dst0[0], dst1[0], H * y_dst_stride) ||

                    memcmp(dst0[1], dst1[1], H * uv_dst_stride >> ss_h) ||

                    memcmp(dst0[2], dst1[2], H * uv_dst_stride >> ss_h)) {

                    fail();

                }

            }

        }

    }



    report("rgb2yuv");

}

flac_header (AVFormatContext * s, int idx)

{

    struct ogg *ogg = s->priv_data;

    struct ogg_stream *os = ogg->streams + idx;

    AVStream *st = s->streams[idx];

    GetBitContext gb;

    FLACStreaminfo si;

    int mdt;



    if (os->buf[os->pstart] == 0xff)

        return 0;



    init_get_bits(&gb, os->buf + os->pstart, os->psize*8);

    skip_bits1(&gb); /* metadata_last */

    mdt = get_bits(&gb, 7);



    if (mdt == OGG_FLAC_METADATA_TYPE_STREAMINFO) {

        uint8_t *streaminfo_start = os->buf + os->pstart + 5 + 4 + 4 + 4;

        skip_bits_long(&gb, 4*8); /* "FLAC" */

        if(get_bits(&gb, 8) != 1) /* unsupported major version */

            return -1;

        skip_bits_long(&gb, 8 + 16); /* minor version + header count */

        skip_bits_long(&gb, 4*8); /* "fLaC" */



        /* METADATA_BLOCK_HEADER */

        if (get_bits_long(&gb, 32) != FLAC_STREAMINFO_SIZE)

            return -1;



        avpriv_flac_parse_streaminfo(st->codec, &si, streaminfo_start);



        st->codec->codec_type = AVMEDIA_TYPE_AUDIO;

        st->codec->codec_id = AV_CODEC_ID_FLAC;

        st->need_parsing = AVSTREAM_PARSE_HEADERS;



        ff_alloc_extradata(st->codec, FLAC_STREAMINFO_SIZE);

        memcpy(st->codec->extradata, streaminfo_start, st->codec->extradata_size);



        avpriv_set_pts_info(st, 64, 1, st->codec->sample_rate);

    } else if (mdt == FLAC_METADATA_TYPE_VORBIS_COMMENT) {

        ff_vorbis_comment (s, &st->metadata, os->buf + os->pstart + 4, os->psize - 4);

    }



    return 1;

}

void acpi_memory_plug_cb(ACPIREGS *ar, qemu_irq irq, MemHotplugState *mem_st,

                         DeviceState *dev, Error **errp)

{

    MemStatus *mdev;



    mdev = acpi_memory_slot_status(mem_st, dev, errp);

    if (!mdev) {

        return;

    }



    mdev->dimm = dev;

    mdev->is_enabled = true;

    mdev->is_inserting = true;



    /* do ACPI magic */

    acpi_send_gpe_event(ar, irq, ACPI_MEMORY_HOTPLUG_STATUS);

    return;

}

static int decode_i_picture_header(VC9Context *v)

{

  int pqindex, status = 0, ac_pred, condover;



    /* Prolog common to all frametypes should be done in caller */

    //BF = Buffer Fullness

    if (v->profile <= PROFILE_MAIN && get_bits(&v->gb, 7))

    {

        av_log(v, AV_LOG_DEBUG, "I BufferFullness not 0\n");

    }



    /* Quantizer stuff */

    pqindex = get_bits(&v->gb, 5);

    if (v->quantizer_mode == QUANT_FRAME_IMPLICIT)

        v->pq = pquant_table[0][pqindex];

    else

    {

        v->pq = pquant_table[v->quantizer_mode-1][pqindex];

    }

    if (pqindex < 9) v->halfpq = get_bits(&v->gb, 1);

    if (v->quantizer_mode == QUANT_FRAME_EXPLICIT)

        v->pquantizer = get_bits(&v->gb, 1);

    av_log(v->avctx, AV_LOG_DEBUG, "I frame: QP=%i (+%i/2)\n",

           v->pq, v->halfpq);

#if HAS_ADVANCED_PROFILE

    if (v->profile <= PROFILE_MAIN)

#endif

    {

        if (v->extended_mv) v->mvrange = get_prefix(&v->gb, 0, 3);

        if (v->multires) v->respic = get_bits(&v->gb, 2);

    }

#if HAS_ADVANCED_PROFILE

    else

    {

        ac_pred = get_bits(&v->gb, 1);

        if (v->postprocflag) v->postproc = get_bits(&v->gb, 1);

        /* 7.1.1.34 + 8.5.2 */

        if (v->overlap && v->pq<9)

        {

            condover = get_bits(&v->gb, 1);

            if (condover)

            {

                condover = 2+get_bits(&v->gb, 1);

                if (condover == 3)

                    status = bitplane_decoding(v->over_flags_plane,

                                                   v->width_mb, v->height_mb, v);

            }

        }

    }

#endif



    /* Epilog should be done in caller */

    return status;

}

static int vtd_page_walk(VTDContextEntry *ce, uint64_t start, uint64_t end,

                         vtd_page_walk_hook hook_fn, void *private)

{

    dma_addr_t addr = vtd_get_slpt_base_from_context(ce);

    uint32_t level = vtd_get_level_from_context_entry(ce);



    if (!vtd_iova_range_check(start, ce)) {

        return -VTD_FR_ADDR_BEYOND_MGAW;

    }



    if (!vtd_iova_range_check(end, ce)) {

        /* Fix end so that it reaches the maximum */

        end = vtd_iova_limit(ce);

    }



    return vtd_page_walk_level(addr, start, end, hook_fn, private,

                               level, true, true, false);

}

