static int kmvc_decode_inter_8x8(KmvcContext * ctx, const uint8_t * src, int src_size, int w, int h)

{

    BitBuf bb;

    int res, val;

    int i, j;

    int bx, by;

    int l0x, l1x, l0y, l1y;

    int mx, my;

    const uint8_t *src_end = src + src_size;



    kmvc_init_getbits(bb, src);



    for (by = 0; by < h; by += 8)

        for (bx = 0; bx < w; bx += 8) {

            kmvc_getbit(bb, src, src_end, res);

            if (!res) {

                kmvc_getbit(bb, src, src_end, res);

                if (!res) {     // fill whole 8x8 block

                    if (src >= src_end) {

                        av_log(ctx->avctx, AV_LOG_ERROR, "Data overrun\n");

                        return AVERROR_INVALIDDATA;

                    }

                    val = *src++;

                    for (i = 0; i < 64; i++)

                        BLK(ctx->cur, bx + (i & 0x7), by + (i >> 3)) = val;

                } else {        // copy block from previous frame

                    for (i = 0; i < 64; i++)

                        BLK(ctx->cur, bx + (i & 0x7), by + (i >> 3)) =

                            BLK(ctx->prev, bx + (i & 0x7), by + (i >> 3));

                }

            } else {            // handle four 4x4 subblocks

                for (i = 0; i < 4; i++) {

                    l0x = bx + (i & 1) * 4;

                    l0y = by + (i & 2) * 2;

                    kmvc_getbit(bb, src, src_end, res);

                    if (!res) {

                        kmvc_getbit(bb, src, src_end, res);

                        if (!res) {     // fill whole 4x4 block

                            if (src >= src_end) {

                                av_log(ctx->avctx, AV_LOG_ERROR, "Data overrun\n");

                                return AVERROR_INVALIDDATA;

                            }

                            val = *src++;

                            for (j = 0; j < 16; j++)

                                BLK(ctx->cur, l0x + (j & 3), l0y + (j >> 2)) = val;

                        } else {        // copy block

                            if (src >= src_end) {

                                av_log(ctx->avctx, AV_LOG_ERROR, "Data overrun\n");

                                return AVERROR_INVALIDDATA;

                            }

                            val = *src++;

                            mx = (val & 0xF) - 8;

                            my = (val >> 4) - 8;

                            for (j = 0; j < 16; j++)

                                BLK(ctx->cur, l0x + (j & 3), l0y + (j >> 2)) =

                                    BLK(ctx->prev, l0x + (j & 3) + mx, l0y + (j >> 2) + my);

                        }

                    } else {    // descend to 2x2 sub-sub-blocks

                        for (j = 0; j < 4; j++) {

                            l1x = l0x + (j & 1) * 2;

                            l1y = l0y + (j & 2);

                            kmvc_getbit(bb, src, src_end, res);

                            if (!res) {

                                kmvc_getbit(bb, src, src_end, res);

                                if (!res) {     // fill whole 2x2 block

                                    if (src >= src_end) {

                                        av_log(ctx->avctx, AV_LOG_ERROR, "Data overrun\n");

                                        return AVERROR_INVALIDDATA;

                                    }

                                    val = *src++;

                                    BLK(ctx->cur, l1x, l1y) = val;

                                    BLK(ctx->cur, l1x + 1, l1y) = val;

                                    BLK(ctx->cur, l1x, l1y + 1) = val;

                                    BLK(ctx->cur, l1x + 1, l1y + 1) = val;

                                } else {        // copy block

                                    if (src >= src_end) {

                                        av_log(ctx->avctx, AV_LOG_ERROR, "Data overrun\n");

                                        return AVERROR_INVALIDDATA;

                                    }

                                    val = *src++;

                                    mx = (val & 0xF) - 8;

                                    my = (val >> 4) - 8;

                                    BLK(ctx->cur, l1x, l1y) = BLK(ctx->prev, l1x + mx, l1y + my);

                                    BLK(ctx->cur, l1x + 1, l1y) =

                                        BLK(ctx->prev, l1x + 1 + mx, l1y + my);

                                    BLK(ctx->cur, l1x, l1y + 1) =

                                        BLK(ctx->prev, l1x + mx, l1y + 1 + my);

                                    BLK(ctx->cur, l1x + 1, l1y + 1) =

                                        BLK(ctx->prev, l1x + 1 + mx, l1y + 1 + my);

                                }

                            } else {    // read values for block

                                BLK(ctx->cur, l1x, l1y) = *src++;

                                BLK(ctx->cur, l1x + 1, l1y) = *src++;

                                BLK(ctx->cur, l1x, l1y + 1) = *src++;

                                BLK(ctx->cur, l1x + 1, l1y + 1) = *src++;

                            }

                        }

                    }

                }

            }

        }



    return 0;

}

static int amr_nb_decode_frame(AVCodecContext *avctx, void *data,

                               int *data_size, AVPacket *avpkt)

{

    const uint8_t *buf = avpkt->data;

    int buf_size       = avpkt->size;

    AMRContext *s      = avctx->priv_data;

    static const uint8_t block_size[16] = { 12, 13, 15, 17, 19, 20, 26, 31, 5, 0, 0, 0, 0, 0, 0, 0 };

    enum Mode dec_mode;

    int packet_size;



    av_dlog(avctx, "amr_decode_frame buf=%p buf_size=%d frame_count=%d!!\n",

            buf, buf_size, avctx->frame_number);



    dec_mode    = (buf[0] >> 3) & 0x000F;

    packet_size = block_size[dec_mode] + 1;



    if (packet_size > buf_size) {

        av_log(avctx, AV_LOG_ERROR, "amr frame too short (%u, should be %u)\n",

               buf_size, packet_size);

        return AVERROR_INVALIDDATA;

    }



    av_dlog(avctx, "packet_size=%d buf= 0x%X %X %X %X\n",

              packet_size, buf[0], buf[1], buf[2], buf[3]);

    /* call decoder */

    Decoder_Interface_Decode(s->dec_state, buf, data, 0);

    *data_size = 160 * 2;



    return packet_size;

}

static void avc_h_loop_filter_chroma422_mbaff_msa(uint8_t *src,

                                                  int32_t stride,

                                                  int32_t alpha_in,

                                                  int32_t beta_in,

                                                  int8_t *tc0)

{

    int32_t col, tc_val;

    int16_t out0, out1;

    v16u8 alpha, beta, res;



    alpha = (v16u8) __msa_fill_b(alpha_in);

    beta = (v16u8) __msa_fill_b(beta_in);



    for (col = 0; col < 4; col++) {

        tc_val = (tc0[col] - 1) + 1;



        if (tc_val <= 0) {

            src += 4 * stride;

            continue;

        }



        AVC_LPF_H_2BYTE_CHROMA_422(src, stride, tc_val, alpha, beta, res);



        out0 = __msa_copy_s_h((v8i16) res, 0);

        out1 = __msa_copy_s_h((v8i16) res, 1);



        STORE_HWORD((src - 1), out0);

        src += stride;

        STORE_HWORD((src - 1), out1);

        src += stride;

    }

}

static void copy_cell(Indeo3DecodeContext *ctx, Plane *plane, Cell *cell)

{

    int     h, w, mv_x, mv_y, offset, offset_dst;

    uint8_t *src, *dst;



    /* setup output and reference pointers */

    offset_dst  = (cell->ypos << 2) * plane->pitch + (cell->xpos << 2);

    dst         = plane->pixels[ctx->buf_sel] + offset_dst;

    mv_y        = cell->mv_ptr[0];

    mv_x        = cell->mv_ptr[1];

    offset      = offset_dst + mv_y * plane->pitch + mv_x;

    src         = plane->pixels[ctx->buf_sel ^ 1] + offset;



    h = cell->height << 2;



    for (w = cell->width; w > 0;) {

        /* copy using 16xH blocks */

        if (!((cell->xpos << 2) & 15) && w >= 4) {

            for (; w >= 4; src += 16, dst += 16, w -= 4)

                ctx->dsp.put_no_rnd_pixels_tab[0][0](dst, src, plane->pitch, h);

        }



        /* copy using 8xH blocks */

        if (!((cell->xpos << 2) & 7) && w >= 2) {

            ctx->dsp.put_no_rnd_pixels_tab[1][0](dst, src, plane->pitch, h);

            w -= 2;

            src += 8;

            dst += 8;

        }



        if (w >= 1) {

            ctx->dsp.put_no_rnd_pixels_tab[2][0](dst, src, plane->pitch, h);

            w--;

            src += 4;

            dst += 4;

        }

    }

}

