}

static void gen_rlwimi(DisasContext *ctx)

{

    uint32_t mb, me, sh;



    mb = MB(ctx->opcode);

    me = ME(ctx->opcode);

    sh = SH(ctx->opcode);

    if (likely(sh == (31-me) && mb <= me)) {

        tcg_gen_deposit_tl(cpu_gpr[rA(ctx->opcode)], cpu_gpr[rA(ctx->opcode)],

                           cpu_gpr[rS(ctx->opcode)], sh, me - mb + 1);

    } else {

        target_ulong mask;

        TCGv t1;

        TCGv t0 = tcg_temp_new();

#if defined(TARGET_PPC64)

        tcg_gen_deposit_i64(t0, cpu_gpr[rS(ctx->opcode)],

            cpu_gpr[rS(ctx->opcode)], 32, 32);

        tcg_gen_rotli_i64(t0, t0, sh);

#else

        tcg_gen_rotli_i32(t0, cpu_gpr[rS(ctx->opcode)], sh);

#endif

#if defined(TARGET_PPC64)

        mb += 32;

        me += 32;

#endif

        mask = MASK(mb, me);

        t1 = tcg_temp_new();

        tcg_gen_andi_tl(t0, t0, mask);

        tcg_gen_andi_tl(t1, cpu_gpr[rA(ctx->opcode)], ~mask);

        tcg_gen_or_tl(cpu_gpr[rA(ctx->opcode)], t0, t1);

        tcg_temp_free(t0);

        tcg_temp_free(t1);

    }

    if (unlikely(Rc(ctx->opcode) != 0))

        gen_set_Rc0(ctx, cpu_gpr[rA(ctx->opcode)]);

}

static int av_seek_frame_generic(AVFormatContext *s, 

                                 int stream_index, int64_t timestamp)

{

    int index;

    AVStream *st;

    AVIndexEntry *ie;



    if (!s->index_built) {

        if (is_raw_stream(s)) {

            av_build_index_raw(s);

        } else {

            return -1;

        }

        s->index_built = 1;

    }



    if (stream_index < 0)

        stream_index = 0;

    st = s->streams[stream_index];

    index = index_search_timestamp(st->index_entries, st->nb_index_entries,

                                   timestamp);

    if (index < 0)

        return -1;



    /* now we have found the index, we can seek */

    ie = &st->index_entries[index];

    av_read_frame_flush(s);

    url_fseek(&s->pb, ie->pos, SEEK_SET);

    st->cur_dts = ie->timestamp;

    return 0;

}

static int mxf_read_index_table_segment(void *arg, AVIOContext *pb, int tag, int size, UID uid)

{

    MXFIndexTableSegment *segment = arg;

    switch(tag) {

    case 0x3F05:

        segment->edit_unit_byte_count = avio_rb32(pb);

        av_dlog(NULL, "EditUnitByteCount %d\n", segment->edit_unit_byte_count);

        break;

    case 0x3F06:

        segment->index_sid = avio_rb32(pb);

        av_dlog(NULL, "IndexSID %d\n", segment->index_sid);

        break;

    case 0x3F07:

        segment->body_sid = avio_rb32(pb);

        av_dlog(NULL, "BodySID %d\n", segment->body_sid);

        break;

    case 0x3F08:

        segment->slice_count = avio_r8(pb);

        av_dlog(NULL, "SliceCount %d\n", segment->slice_count);

        break;

    case 0x3F09:

        av_dlog(NULL, "DeltaEntryArray found\n");

        return mxf_read_delta_entry_array(pb, segment);

    case 0x3F0A:

        av_dlog(NULL, "IndexEntryArray found\n");

        return mxf_read_index_entry_array(pb, segment);

    case 0x3F0B:

        segment->index_edit_rate.num = avio_rb32(pb);

        segment->index_edit_rate.den = avio_rb32(pb);

        av_dlog(NULL, "IndexEditRate %d/%d\n", segment->index_edit_rate.num,

                segment->index_edit_rate.den);

        break;

    case 0x3F0C:

        segment->index_start_position = avio_rb64(pb);

        av_dlog(NULL, "IndexStartPosition %"PRId64"\n", segment->index_start_position);

        break;

    case 0x3F0D:

        segment->index_duration = avio_rb64(pb);

        av_dlog(NULL, "IndexDuration %"PRId64"\n", segment->index_duration);

        break;

    }

    return 0;

}

static ssize_t test_block_write_func(QCryptoBlock *block,

                                     void *opaque,

                                     size_t offset,

                                     const uint8_t *buf,

                                     size_t buflen,

                                     Error **errp)

{

    Buffer *header = opaque;



    g_assert_cmpint(buflen + offset, <=, header->capacity);



    memcpy(header->buffer + offset, buf, buflen);

    header->offset = offset + buflen;



    return buflen;

}

static ssize_t block_crypto_read_func(QCryptoBlock *block,

                                      size_t offset,

                                      uint8_t *buf,

                                      size_t buflen,

                                      Error **errp,

                                      void *opaque)

{

