av_cold int swri_rematrix_init_x86(struct SwrContext *s){

#if HAVE_YASM

    int mm_flags = av_get_cpu_flags();

    int nb_in  = av_get_channel_layout_nb_channels(s->in_ch_layout);

    int nb_out = av_get_channel_layout_nb_channels(s->out_ch_layout);

    int num    = nb_in * nb_out;

    int i,j;



    s->mix_1_1_simd = NULL;

    s->mix_2_1_simd = NULL;



    if (s->midbuf.fmt == AV_SAMPLE_FMT_S16P){

        if(EXTERNAL_MMX(mm_flags)) {

            s->mix_1_1_simd = ff_mix_1_1_a_int16_mmx;

            s->mix_2_1_simd = ff_mix_2_1_a_int16_mmx;

        }

        if(EXTERNAL_SSE2(mm_flags)) {

            s->mix_1_1_simd = ff_mix_1_1_a_int16_sse2;

            s->mix_2_1_simd = ff_mix_2_1_a_int16_sse2;

        }

        s->native_simd_matrix = av_mallocz_array(num,  2 * sizeof(int16_t));

        s->native_simd_one    = av_mallocz(2 * sizeof(int16_t));

        if (!s->native_simd_matrix || !s->native_simd_one)

            return AVERROR(ENOMEM);



        for(i=0; i<nb_out; i++){

            int sh = 0;

            for(j=0; j<nb_in; j++)

                sh = FFMAX(sh, FFABS(((int*)s->native_matrix)[i * nb_in + j]));

            sh = FFMAX(av_log2(sh) - 14, 0);

            for(j=0; j<nb_in; j++) {

                ((int16_t*)s->native_simd_matrix)[2*(i * nb_in + j)+1] = 15 - sh;

                ((int16_t*)s->native_simd_matrix)[2*(i * nb_in + j)] =

                    ((((int*)s->native_matrix)[i * nb_in + j]) + (1<<sh>>1)) >> sh;

            }

        }

        ((int16_t*)s->native_simd_one)[1] = 14;

        ((int16_t*)s->native_simd_one)[0] = 16384;

    } else if(s->midbuf.fmt == AV_SAMPLE_FMT_FLTP){

        if(EXTERNAL_SSE(mm_flags)) {

            s->mix_1_1_simd = ff_mix_1_1_a_float_sse;

            s->mix_2_1_simd = ff_mix_2_1_a_float_sse;

        }

        if(EXTERNAL_AVX(mm_flags)) {

            s->mix_1_1_simd = ff_mix_1_1_a_float_avx;

            s->mix_2_1_simd = ff_mix_2_1_a_float_avx;

        }

        s->native_simd_matrix = av_mallocz_array(num, sizeof(float));

        s->native_simd_one = av_mallocz(sizeof(float));

        if (!s->native_simd_matrix || !s->native_simd_one)

            return AVERROR(ENOMEM);

        memcpy(s->native_simd_matrix, s->native_matrix, num * sizeof(float));

        memcpy(s->native_simd_one, s->native_one, sizeof(float));

    }

#endif



    return 0;

}

static int av_transcode(AVFormatContext **output_files,

                        int nb_output_files,

                        AVFormatContext **input_files,

                        int nb_input_files,

                        AVStreamMap *stream_maps, int nb_stream_maps)

{

    int ret = 0, i, j, k, n, nb_istreams = 0, nb_ostreams = 0;

    AVFormatContext *is, *os;

    AVCodecContext *codec, *icodec;

    AVOutputStream *ost, **ost_table = NULL;

    AVInputStream *ist, **ist_table = NULL;

    AVInputFile *file_table;

    char error[1024];

    int key;

    int want_sdp = 1;

    uint8_t no_packet[MAX_FILES]={0};

    int no_packet_count=0;



    file_table= av_mallocz(nb_input_files * sizeof(AVInputFile));

    if (!file_table)

        goto fail;



    /* input stream init */

    j = 0;

    for(i=0;i<nb_input_files;i++) {

        is = input_files[i];

        file_table[i].ist_index = j;

        file_table[i].nb_streams = is->nb_streams;

        j += is->nb_streams;

    }

    nb_istreams = j;



    ist_table = av_mallocz(nb_istreams * sizeof(AVInputStream *));

    if (!ist_table)

        goto fail;



    for(i=0;i<nb_istreams;i++) {

        ist = av_mallocz(sizeof(AVInputStream));

        if (!ist)

            goto fail;

        ist_table[i] = ist;

    }

    j = 0;

    for(i=0;i<nb_input_files;i++) {

        is = input_files[i];

        for(k=0;k<is->nb_streams;k++) {

            ist = ist_table[j++];

            ist->st = is->streams[k];

            ist->file_index = i;

            ist->index = k;

            ist->discard = 1; /* the stream is discarded by default

                                 (changed later) */



            if (rate_emu) {

                ist->start = av_gettime();

            }

        }

    }



    /* output stream init */

    nb_ostreams = 0;

    for(i=0;i<nb_output_files;i++) {

        os = output_files[i];

        if (!os->nb_streams) {

            dump_format(output_files[i], i, output_files[i]->filename, 1);

            fprintf(stderr, "Output file #%d does not contain any stream\n", i);

            av_exit(1);

        }

        nb_ostreams += os->nb_streams;

    }

    if (nb_stream_maps > 0 && nb_stream_maps != nb_ostreams) {

        fprintf(stderr, "Number of stream maps must match number of output streams\n");

        av_exit(1);

    }



    /* Sanity check the mapping args -- do the input files & streams exist? */

    for(i=0;i<nb_stream_maps;i++) {

        int fi = stream_maps[i].file_index;

        int si = stream_maps[i].stream_index;



        if (fi < 0 || fi > nb_input_files - 1 ||

            si < 0 || si > file_table[fi].nb_streams - 1) {

            fprintf(stderr,"Could not find input stream #%d.%d\n", fi, si);

            av_exit(1);

        }

        fi = stream_maps[i].sync_file_index;

        si = stream_maps[i].sync_stream_index;

        if (fi < 0 || fi > nb_input_files - 1 ||

            si < 0 || si > file_table[fi].nb_streams - 1) {

            fprintf(stderr,"Could not find sync stream #%d.%d\n", fi, si);

            av_exit(1);

        }

    }



    ost_table = av_mallocz(sizeof(AVOutputStream *) * nb_ostreams);

    if (!ost_table)

        goto fail;

    for(i=0;i<nb_ostreams;i++) {

        ost = av_mallocz(sizeof(AVOutputStream));

        if (!ost)

            goto fail;

        ost_table[i] = ost;

    }



    n = 0;

    for(k=0;k<nb_output_files;k++) {

        os = output_files[k];

        for(i=0;i<os->nb_streams;i++,n++) {

            int found;

            ost = ost_table[n];

            ost->file_index = k;

            ost->index = i;

            ost->st = os->streams[i];

            if (nb_stream_maps > 0) {

                ost->source_index = file_table[stream_maps[n].file_index].ist_index +

                    stream_maps[n].stream_index;



                /* Sanity check that the stream types match */

                if (ist_table[ost->source_index]->st->codec->codec_type != ost->st->codec->codec_type) {

                    int i= ost->file_index;

                    dump_format(output_files[i], i, output_files[i]->filename, 1);

                    fprintf(stderr, "Codec type mismatch for mapping #%d.%d -> #%d.%d\n",

                        stream_maps[n].file_index, stream_maps[n].stream_index,

                        ost->file_index, ost->index);

                    av_exit(1);

                }



            } else {

                int best_nb_frames=-1;

                    /* get corresponding input stream index : we select the first one with the right type */

                    found = 0;

                    for(j=0;j<nb_istreams;j++) {

                        int skip=0;

                        ist = ist_table[j];

                        if(opt_programid){

                            int pi,si;

                            AVFormatContext *f= input_files[ ist->file_index ];

                            skip=1;

                            for(pi=0; pi<f->nb_programs; pi++){

                                AVProgram *p= f->programs[pi];

                                if(p->id == opt_programid)

                                    for(si=0; si<p->nb_stream_indexes; si++){

                                        if(f->streams[ p->stream_index[si] ] == ist->st)

                                            skip=0;

                                    }

                            }

                        }

                        if (ist->discard && ist->st->discard != AVDISCARD_ALL && !skip &&

                            ist->st->codec->codec_type == ost->st->codec->codec_type) {

                            if(best_nb_frames < ist->st->codec_info_nb_frames){

                                best_nb_frames= ist->st->codec_info_nb_frames;

                                ost->source_index = j;

                                found = 1;

                            }

                        }

                    }



                if (!found) {

                    if(! opt_programid) {

                        /* try again and reuse existing stream */

                        for(j=0;j<nb_istreams;j++) {

                            ist = ist_table[j];

                            if (   ist->st->codec->codec_type == ost->st->codec->codec_type

                                && ist->st->discard != AVDISCARD_ALL) {

                                ost->source_index = j;

                                found = 1;

                            }

                        }

                    }

                    if (!found) {

                        int i= ost->file_index;

                        dump_format(output_files[i], i, output_files[i]->filename, 1);

                        fprintf(stderr, "Could not find input stream matching output stream #%d.%d\n",

                                ost->file_index, ost->index);

                        av_exit(1);

                    }

                }

            }

            ist = ist_table[ost->source_index];

            ist->discard = 0;

            ost->sync_ist = (nb_stream_maps > 0) ?

                ist_table[file_table[stream_maps[n].sync_file_index].ist_index +

                         stream_maps[n].sync_stream_index] : ist;

        }

    }



    /* for each output stream, we compute the right encoding parameters */

    for(i=0;i<nb_ostreams;i++) {

        AVMetadataTag *t = NULL;

        ost = ost_table[i];

        os = output_files[ost->file_index];

        ist = ist_table[ost->source_index];



        codec = ost->st->codec;

        icodec = ist->st->codec;



        while ((t = av_metadata_get(ist->st->metadata, "", t, AV_METADATA_IGNORE_SUFFIX))) {

            av_metadata_set2(&ost->st->metadata, t->key, t->value, AV_METADATA_DONT_OVERWRITE);

        }



        ost->st->disposition = ist->st->disposition;

        codec->bits_per_raw_sample= icodec->bits_per_raw_sample;

        codec->chroma_sample_location = icodec->chroma_sample_location;



        if (ost->st->stream_copy) {

            /* if stream_copy is selected, no need to decode or encode */

            codec->codec_id = icodec->codec_id;

            codec->codec_type = icodec->codec_type;



            if(!codec->codec_tag){

                if(   !os->oformat->codec_tag

                   || av_codec_get_id (os->oformat->codec_tag, icodec->codec_tag) == codec->codec_id

                   || av_codec_get_tag(os->oformat->codec_tag, icodec->codec_id) <= 0)

                    codec->codec_tag = icodec->codec_tag;

            }



            codec->bit_rate = icodec->bit_rate;

            codec->extradata= icodec->extradata;

            codec->extradata_size= icodec->extradata_size;

            if(av_q2d(icodec->time_base)*icodec->ticks_per_frame > av_q2d(ist->st->time_base) && av_q2d(ist->st->time_base) < 1.0/1000){

                codec->time_base = icodec->time_base;

                codec->time_base.num *= icodec->ticks_per_frame;

            }else

                codec->time_base = ist->st->time_base;

            switch(codec->codec_type) {

            case AVMEDIA_TYPE_AUDIO:

                if(audio_volume != 256) {

                    fprintf(stderr,"-acodec copy and -vol are incompatible (frames are not decoded)\n");

                    av_exit(1);

                }

                codec->channel_layout = icodec->channel_layout;

                codec->sample_rate = icodec->sample_rate;

                codec->channels = icodec->channels;

                codec->frame_size = icodec->frame_size;

                codec->block_align= icodec->block_align;

                if(codec->block_align == 1 && codec->codec_id == CODEC_ID_MP3)

                    codec->block_align= 0;

                if(codec->codec_id == CODEC_ID_AC3)

                    codec->block_align= 0;

                break;

            case AVMEDIA_TYPE_VIDEO:

                codec->pix_fmt = icodec->pix_fmt;

                codec->width = icodec->width;

                codec->height = icodec->height;

                codec->has_b_frames = icodec->has_b_frames;

                break;

            case AVMEDIA_TYPE_SUBTITLE:

                codec->width = icodec->width;

                codec->height = icodec->height;

                break;

            default:

                abort();

            }

        } else {

            switch(codec->codec_type) {

            case AVMEDIA_TYPE_AUDIO:

                ost->fifo= av_fifo_alloc(1024);

                if(!ost->fifo)

                    goto fail;

                ost->reformat_pair = MAKE_SFMT_PAIR(SAMPLE_FMT_NONE,SAMPLE_FMT_NONE);

                ost->audio_resample = codec->sample_rate != icodec->sample_rate || audio_sync_method > 1;

                icodec->request_channels = codec->channels;

                ist->decoding_needed = 1;

                ost->encoding_needed = 1;

                break;

            case AVMEDIA_TYPE_VIDEO:

                if (ost->st->codec->pix_fmt == PIX_FMT_NONE) {

                    fprintf(stderr, "Video pixel format is unknown, stream cannot be encoded\n");

                    av_exit(1);

                }

                ost->video_crop = ((frame_leftBand + frame_rightBand + frame_topBand + frame_bottomBand) != 0);

                ost->video_pad = ((frame_padleft + frame_padright + frame_padtop + frame_padbottom) != 0);

                ost->video_resample = ((codec->width != icodec->width -

                                (frame_leftBand + frame_rightBand) +

                                (frame_padleft + frame_padright)) ||

                        (codec->height != icodec->height -

                                (frame_topBand  + frame_bottomBand) +

                                (frame_padtop + frame_padbottom)) ||

                        (codec->pix_fmt != icodec->pix_fmt));

                if (ost->video_crop) {

                    ost->topBand    = ost->original_topBand    = frame_topBand;

                    ost->bottomBand = ost->original_bottomBand = frame_bottomBand;

                    ost->leftBand   = ost->original_leftBand   = frame_leftBand;

                    ost->rightBand  = ost->original_rightBand  = frame_rightBand;

                }

                if (ost->video_pad) {

                    ost->padtop = frame_padtop;

                    ost->padleft = frame_padleft;

                    ost->padbottom = frame_padbottom;

                    ost->padright = frame_padright;

                    if (!ost->video_resample) {

                        avcodec_get_frame_defaults(&ost->pict_tmp);

                        if(avpicture_alloc((AVPicture*)&ost->pict_tmp, codec->pix_fmt,

                                         codec->width, codec->height))

                            goto fail;

                    }

                }

                if (ost->video_resample) {

                    avcodec_get_frame_defaults(&ost->pict_tmp);

                    if(avpicture_alloc((AVPicture*)&ost->pict_tmp, codec->pix_fmt,

                                         codec->width, codec->height)) {

                        fprintf(stderr, "Cannot allocate temp picture, check pix fmt\n");

                        av_exit(1);

                    }

                    sws_flags = av_get_int(sws_opts, "sws_flags", NULL);

                    ost->img_resample_ctx = sws_getContext(

                            icodec->width - (frame_leftBand + frame_rightBand),

                            icodec->height - (frame_topBand + frame_bottomBand),

                            icodec->pix_fmt,

                            codec->width - (frame_padleft + frame_padright),

                            codec->height - (frame_padtop + frame_padbottom),

                            codec->pix_fmt,

                            sws_flags, NULL, NULL, NULL);

                    if (ost->img_resample_ctx == NULL) {

                        fprintf(stderr, "Cannot get resampling context\n");

                        av_exit(1);

                    }



#if !CONFIG_AVFILTER

                    ost->original_height = icodec->height;

                    ost->original_width  = icodec->width;

#endif

                    codec->bits_per_raw_sample= 0;

                }

                ost->resample_height = icodec->height - (frame_topBand  + frame_bottomBand);

                ost->resample_width  = icodec->width  - (frame_leftBand + frame_rightBand);

                ost->resample_pix_fmt= icodec->pix_fmt;

                ost->encoding_needed = 1;

                ist->decoding_needed = 1;



#if CONFIG_AVFILTER

                if (configure_filters(ist, ost)) {

                    fprintf(stderr, "Error opening filters!\n");

                    exit(1);

                }

#endif

                break;

            case AVMEDIA_TYPE_SUBTITLE:

                ost->encoding_needed = 1;

                ist->decoding_needed = 1;

                break;

            default:

                abort();

                break;

            }

            /* two pass mode */

            if (ost->encoding_needed &&

                (codec->flags & (CODEC_FLAG_PASS1 | CODEC_FLAG_PASS2))) {

                char logfilename[1024];

                FILE *f;



                snprintf(logfilename, sizeof(logfilename), "%s-%d.log",

                         pass_logfilename_prefix ? pass_logfilename_prefix : DEFAULT_PASS_LOGFILENAME_PREFIX,

                         i);

                if (codec->flags & CODEC_FLAG_PASS1) {

                    f = fopen(logfilename, "w");

                    if (!f) {

                        fprintf(stderr, "Cannot write log file '%s' for pass-1 encoding: %s\n", logfilename, strerror(errno));

                        av_exit(1);

                    }

                    ost->logfile = f;

                } else {

                    char  *logbuffer;

                    size_t logbuffer_size;

                    if (read_file(logfilename, &logbuffer, &logbuffer_size) < 0) {

                        fprintf(stderr, "Error reading log file '%s' for pass-2 encoding\n", logfilename);

                        av_exit(1);

                    }

                    codec->stats_in = logbuffer;

                }

            }

        }

        if(codec->codec_type == AVMEDIA_TYPE_VIDEO){

            int size= codec->width * codec->height;

            bit_buffer_size= FFMAX(bit_buffer_size, 6*size + 200);

        }

    }



    if (!bit_buffer)

        bit_buffer = av_malloc(bit_buffer_size);

    if (!bit_buffer) {

        fprintf(stderr, "Cannot allocate %d bytes output buffer\n",

                bit_buffer_size);

        ret = AVERROR(ENOMEM);

        goto fail;

    }



    /* open each encoder */

    for(i=0;i<nb_ostreams;i++) {

        ost = ost_table[i];

        if (ost->encoding_needed) {

            AVCodec *codec = output_codecs[i];

            if (!codec)

                codec = avcodec_find_encoder(ost->st->codec->codec_id);

            if (!codec) {

                snprintf(error, sizeof(error), "Encoder (codec id %d) not found for output stream #%d.%d",

                         ost->st->codec->codec_id, ost->file_index, ost->index);

                ret = AVERROR(EINVAL);

                goto dump_format;

            }

            if (avcodec_open(ost->st->codec, codec) < 0) {

                snprintf(error, sizeof(error), "Error while opening encoder for output stream #%d.%d - maybe incorrect parameters such as bit_rate, rate, width or height",

                        ost->file_index, ost->index);

                ret = AVERROR(EINVAL);

                goto dump_format;

            }

            extra_size += ost->st->codec->extradata_size;

        }

    }



    /* open each decoder */

    for(i=0;i<nb_istreams;i++) {

        ist = ist_table[i];

        if (ist->decoding_needed) {

            AVCodec *codec = input_codecs[i];

            if (!codec)

                codec = avcodec_find_decoder(ist->st->codec->codec_id);

            if (!codec) {

                snprintf(error, sizeof(error), "Decoder (codec id %d) not found for input stream #%d.%d",

                        ist->st->codec->codec_id, ist->file_index, ist->index);

                ret = AVERROR(EINVAL);

                goto dump_format;

            }

            if (avcodec_open(ist->st->codec, codec) < 0) {

                snprintf(error, sizeof(error), "Error while opening decoder for input stream #%d.%d",

                        ist->file_index, ist->index);

                ret = AVERROR(EINVAL);

                goto dump_format;

            }

            //if (ist->st->codec->codec_type == AVMEDIA_TYPE_VIDEO)

            //    ist->st->codec->flags |= CODEC_FLAG_REPEAT_FIELD;

        }

    }



    /* init pts */

    for(i=0;i<nb_istreams;i++) {

        AVStream *st;

        ist = ist_table[i];

        st= ist->st;

        ist->pts = st->avg_frame_rate.num ? - st->codec->has_b_frames*AV_TIME_BASE / av_q2d(st->avg_frame_rate) : 0;

        ist->next_pts = AV_NOPTS_VALUE;

        ist->is_start = 1;

    }



    /* set meta data information from input file if required */

    for (i=0;i<nb_meta_data_maps;i++) {

        AVFormatContext *out_file;

        AVFormatContext *in_file;

        AVMetadataTag *mtag;



        int out_file_index = meta_data_maps[i].out_file;

        int in_file_index = meta_data_maps[i].in_file;

        if (out_file_index < 0 || out_file_index >= nb_output_files) {

            snprintf(error, sizeof(error), "Invalid output file index %d map_meta_data(%d,%d)",

                     out_file_index, out_file_index, in_file_index);

            ret = AVERROR(EINVAL);

            goto dump_format;

        }

        if (in_file_index < 0 || in_file_index >= nb_input_files) {

            snprintf(error, sizeof(error), "Invalid input file index %d map_meta_data(%d,%d)",

                     in_file_index, out_file_index, in_file_index);

            ret = AVERROR(EINVAL);

            goto dump_format;

        }



        out_file = output_files[out_file_index];

        in_file = input_files[in_file_index];





        mtag=NULL;

        while((mtag=av_metadata_get(in_file->metadata, "", mtag, AV_METADATA_IGNORE_SUFFIX)))

            av_metadata_set2(&out_file->metadata, mtag->key, mtag->value, AV_METADATA_DONT_OVERWRITE);

        av_metadata_conv(out_file, out_file->oformat->metadata_conv,

                                    in_file->iformat->metadata_conv);

    }



    /* copy chapters from the first input file that has them*/

    for (i = 0; i < nb_input_files; i++) {

        if (!input_files[i]->nb_chapters)

            continue;



        for (j = 0; j < nb_output_files; j++)

            if ((ret = copy_chapters(i, j)) < 0)

                goto dump_format;

    }



    /* open files and write file headers */

    for(i=0;i<nb_output_files;i++) {

        os = output_files[i];

        if (av_write_header(os) < 0) {

            snprintf(error, sizeof(error), "Could not write header for output file #%d (incorrect codec parameters ?)", i);

            ret = AVERROR(EINVAL);

            goto dump_format;

        }

        if (strcmp(output_files[i]->oformat->name, "rtp")) {

            want_sdp = 0;

        }

    }



 dump_format:

    /* dump the file output parameters - cannot be done before in case

       of stream copy */

    for(i=0;i<nb_output_files;i++) {

        dump_format(output_files[i], i, output_files[i]->filename, 1);

    }



    /* dump the stream mapping */

    if (verbose >= 0) {

        fprintf(stderr, "Stream mapping:\n");

        for(i=0;i<nb_ostreams;i++) {

            ost = ost_table[i];

            fprintf(stderr, "  Stream #%d.%d -> #%d.%d",

                    ist_table[ost->source_index]->file_index,

                    ist_table[ost->source_index]->index,

                    ost->file_index,

                    ost->index);

            if (ost->sync_ist != ist_table[ost->source_index])

                fprintf(stderr, " [sync #%d.%d]",

                        ost->sync_ist->file_index,

                        ost->sync_ist->index);

            fprintf(stderr, "\n");

        }

    }



    if (ret) {

        fprintf(stderr, "%s\n", error);

        goto fail;

    }



    if (want_sdp) {

        print_sdp(output_files, nb_output_files);

    }



    if (!using_stdin && verbose >= 0) {

        fprintf(stderr, "Press [q] to stop encoding\n");

        url_set_interrupt_cb(decode_interrupt_cb);

    }

    term_init();



    timer_start = av_gettime();



    for(; received_sigterm == 0;) {

        int file_index, ist_index;

        AVPacket pkt;

        double ipts_min;

        double opts_min;



    redo:

        ipts_min= 1e100;

        opts_min= 1e100;

        /* if 'q' pressed, exits */

        if (!using_stdin) {

            if (q_pressed)

                break;

            /* read_key() returns 0 on EOF */

            key = read_key();

            if (key == 'q')

                break;

        }



        /* select the stream that we must read now by looking at the

           smallest output pts */

        file_index = -1;

        for(i=0;i<nb_ostreams;i++) {

            double ipts, opts;

            ost = ost_table[i];

            os = output_files[ost->file_index];

            ist = ist_table[ost->source_index];

            if(ist->is_past_recording_time || no_packet[ist->file_index])

                continue;

                opts = ost->st->pts.val * av_q2d(ost->st->time_base);

            ipts = (double)ist->pts;

            if (!file_table[ist->file_index].eof_reached){

                if(ipts < ipts_min) {

                    ipts_min = ipts;

                    if(input_sync ) file_index = ist->file_index;

                }

                if(opts < opts_min) {

                    opts_min = opts;

                    if(!input_sync) file_index = ist->file_index;

                }

            }

            if(ost->frame_number >= max_frames[ost->st->codec->codec_type]){

                file_index= -1;

                break;

            }

        }

        /* if none, if is finished */

        if (file_index < 0) {

            if(no_packet_count){

                no_packet_count=0;

                memset(no_packet, 0, sizeof(no_packet));

                usleep(10000);

                continue;

            }

            break;

        }



        /* finish if limit size exhausted */

        if (limit_filesize != 0 && limit_filesize < url_ftell(output_files[0]->pb))

            break;



        /* read a frame from it and output it in the fifo */

        is = input_files[file_index];

        ret= av_read_frame(is, &pkt);

        if(ret == AVERROR(EAGAIN)){

            no_packet[file_index]=1;

            no_packet_count++;

            continue;

        }

        if (ret < 0) {

            file_table[file_index].eof_reached = 1;

            if (opt_shortest)

                break;

            else

                continue;

        }



        no_packet_count=0;

        memset(no_packet, 0, sizeof(no_packet));



        if (do_pkt_dump) {

            av_pkt_dump_log(NULL, AV_LOG_DEBUG, &pkt, do_hex_dump);

        }

        /* the following test is needed in case new streams appear

           dynamically in stream : we ignore them */

        if (pkt.stream_index >= file_table[file_index].nb_streams)

            goto discard_packet;

        ist_index = file_table[file_index].ist_index + pkt.stream_index;

        ist = ist_table[ist_index];

        if (ist->discard)

            goto discard_packet;



        if (pkt.dts != AV_NOPTS_VALUE)

            pkt.dts += av_rescale_q(input_files_ts_offset[ist->file_index], AV_TIME_BASE_Q, ist->st->time_base);

        if (pkt.pts != AV_NOPTS_VALUE)

            pkt.pts += av_rescale_q(input_files_ts_offset[ist->file_index], AV_TIME_BASE_Q, ist->st->time_base);



        if(input_files_ts_scale[file_index][pkt.stream_index]){

            if(pkt.pts != AV_NOPTS_VALUE)

                pkt.pts *= input_files_ts_scale[file_index][pkt.stream_index];

            if(pkt.dts != AV_NOPTS_VALUE)

                pkt.dts *= input_files_ts_scale[file_index][pkt.stream_index];

        }



//        fprintf(stderr, "next:%"PRId64" dts:%"PRId64" off:%"PRId64" %d\n", ist->next_pts, pkt.dts, input_files_ts_offset[ist->file_index], ist->st->codec->codec_type);

        if (pkt.dts != AV_NOPTS_VALUE && ist->next_pts != AV_NOPTS_VALUE

            && (is->iformat->flags & AVFMT_TS_DISCONT)) {

            int64_t pkt_dts= av_rescale_q(pkt.dts, ist->st->time_base, AV_TIME_BASE_Q);

            int64_t delta= pkt_dts - ist->next_pts;

            if((FFABS(delta) > 1LL*dts_delta_threshold*AV_TIME_BASE || pkt_dts+1<ist->pts)&& !copy_ts){

                input_files_ts_offset[ist->file_index]-= delta;

                if (verbose > 2)

                    fprintf(stderr, "timestamp discontinuity %"PRId64", new offset= %"PRId64"\n", delta, input_files_ts_offset[ist->file_index]);

                pkt.dts-= av_rescale_q(delta, AV_TIME_BASE_Q, ist->st->time_base);

                if(pkt.pts != AV_NOPTS_VALUE)

                    pkt.pts-= av_rescale_q(delta, AV_TIME_BASE_Q, ist->st->time_base);

            }

        }



        /* finish if recording time exhausted */

        if (recording_time != INT64_MAX &&

            av_compare_ts(pkt.pts, ist->st->time_base, recording_time + start_time, (AVRational){1, 1000000}) >= 0) {

            ist->is_past_recording_time = 1;

            goto discard_packet;

        }



        //fprintf(stderr,"read #%d.%d size=%d\n", ist->file_index, ist->index, pkt.size);

        if (output_packet(ist, ist_index, ost_table, nb_ostreams, &pkt) < 0) {



            if (verbose >= 0)

                fprintf(stderr, "Error while decoding stream #%d.%d\n",

                        ist->file_index, ist->index);

            if (exit_on_error)

                av_exit(1);

            av_free_packet(&pkt);

            goto redo;

        }



    discard_packet:

        av_free_packet(&pkt);



        /* dump report by using the output first video and audio streams */

        print_report(output_files, ost_table, nb_ostreams, 0);

    }



    /* at the end of stream, we must flush the decoder buffers */

    for(i=0;i<nb_istreams;i++) {

        ist = ist_table[i];

        if (ist->decoding_needed) {

            output_packet(ist, i, ost_table, nb_ostreams, NULL);

        }

    }



    term_exit();



    /* write the trailer if needed and close file */

    for(i=0;i<nb_output_files;i++) {

        os = output_files[i];

        av_write_trailer(os);

    }



    /* dump report by using the first video and audio streams */

    print_report(output_files, ost_table, nb_ostreams, 1);



    /* close each encoder */

    for(i=0;i<nb_ostreams;i++) {

        ost = ost_table[i];

        if (ost->encoding_needed) {

            av_freep(&ost->st->codec->stats_in);

            avcodec_close(ost->st->codec);

        }

    }



    /* close each decoder */

    for(i=0;i<nb_istreams;i++) {

        ist = ist_table[i];

        if (ist->decoding_needed) {

            avcodec_close(ist->st->codec);

        }

    }

#if CONFIG_AVFILTER

    if (filt_graph_all) {

        avfilter_graph_destroy(filt_graph_all);

        av_freep(&filt_graph_all);

    }

#endif



    /* finished ! */

    ret = 0;



 fail:

    av_freep(&bit_buffer);

    av_free(file_table);



    if (ist_table) {

        for(i=0;i<nb_istreams;i++) {

            ist = ist_table[i];

            av_free(ist);

        }

        av_free(ist_table);

    }

    if (ost_table) {

        for(i=0;i<nb_ostreams;i++) {

            ost = ost_table[i];

            if (ost) {

                if (ost->logfile) {

                    fclose(ost->logfile);

                    ost->logfile = NULL;

                }

                av_fifo_free(ost->fifo); /* works even if fifo is not

                                             initialized but set to zero */

                av_free(ost->pict_tmp.data[0]);

                if (ost->video_resample)

                    sws_freeContext(ost->img_resample_ctx);

                if (ost->resample)

                    audio_resample_close(ost->resample);

                if (ost->reformat_ctx)

                    av_audio_convert_free(ost->reformat_ctx);

                av_free(ost);

            }

        }

        av_free(ost_table);

    }

    return ret;

}

static int mpegts_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    AVStream *st = s->streams[pkt->stream_index];

    int size= pkt->size;

    uint8_t *buf= pkt->data;

    MpegTSWriteStream *ts_st = st->priv_data;

    int len, max_payload_size;

    const uint8_t *access_unit_index = NULL;



    if (st->codec->codec_type == CODEC_TYPE_SUBTITLE) {

        /* for subtitle, a single PES packet must be generated */

        mpegts_write_pes(s, st, buf, size, pkt->pts, AV_NOPTS_VALUE);

        return 0;

    }



    if (st->codec->codec_id == CODEC_ID_DIRAC) {

        /* for Dirac, a single PES packet must be generated */

        mpegts_write_pes(s, st, buf, size, pkt->pts, pkt->dts);

        return 0;

    }

    max_payload_size = DEFAULT_PES_PAYLOAD_SIZE;

    if (st->codec->codec_id == CODEC_ID_MPEG2VIDEO ||

        st->codec->codec_id == CODEC_ID_MPEG1VIDEO) {

        const uint8_t *p = pkt->data;

        const uint8_t *end = pkt->data+pkt->size;

        uint32_t state = -1;

        while (p < end) {

            p = ff_find_start_code(p, end, &state);

            if (state == PICTURE_START_CODE) {

                access_unit_index = p - 4;

                break;

            }

        }

    } else if (st->codec->codec_type == CODEC_TYPE_AUDIO) {

        access_unit_index = pkt->data;

    }



    if (!access_unit_index) {

        av_log(s, AV_LOG_ERROR, "error, could not find access unit start\n");

        return -1;

    }



    while (size > 0) {

        len = max_payload_size - ts_st->payload_index;

        if (len > size)

            len = size;

        memcpy(ts_st->payload + ts_st->payload_index, buf, len);

        buf += len;

        size -= len;

        ts_st->payload_index += len;

        if (access_unit_index && access_unit_index < buf &&

            ts_st->payload_pts == AV_NOPTS_VALUE &&

            ts_st->payload_dts == AV_NOPTS_VALUE) {

            ts_st->payload_dts = pkt->dts;

            ts_st->payload_pts = pkt->pts;

        }

        if (ts_st->payload_index >= max_payload_size) {

            mpegts_write_pes(s, st, ts_st->payload, ts_st->payload_index,

                             ts_st->payload_pts, ts_st->payload_dts);

            ts_st->payload_pts = AV_NOPTS_VALUE;

            ts_st->payload_dts = AV_NOPTS_VALUE;

            ts_st->payload_index = 0;

            access_unit_index = NULL; // unset access unit to avoid setting pts/dts again

        }

    }

    return 0;

}

static av_cold int frei0r_init(AVFilterContext *ctx,

                               const char *dl_name, int type)

{

    Frei0rContext *frei0r = ctx->priv;

    f0r_init_f            f0r_init;

    f0r_get_plugin_info_f f0r_get_plugin_info;

    f0r_plugin_info_t *pi;

    char *path;

    int ret = 0;



    /* see: http://frei0r.dyne.org/codedoc/html/group__pluglocations.html */

    if ((path = av_strdup(getenv("FREI0R_PATH")))) {

#ifdef _WIN32

        const char *separator = ";";

#else

        const char *separator = ":";

#endif

        char *p, *ptr = NULL;

        for (p = path; p = av_strtok(p, separator, &ptr); p = NULL) {

            /* add additional trailing slash in case it is missing */

            char *p1 = av_asprintf("%s/", p);

            if (!p1) {

                av_free(path);

                return AVERROR(ENOMEM);

            }

            ret = load_path(ctx, &frei0r->dl_handle, p1, dl_name);

            av_free(p1);

            if (ret < 0) {

                av_free(path);

                return ret;

            }

            if (frei0r->dl_handle)

                break;

        }

        av_free(path);

    }

    if (!frei0r->dl_handle && (path = getenv("HOME"))) {

        char *prefix = av_asprintf("%s/.frei0r-1/lib/", path);

        if (!prefix)

            return AVERROR(ENOMEM);

        ret = load_path(ctx, &frei0r->dl_handle, prefix, dl_name);

        av_free(prefix);

        if (ret < 0)

            return ret;

    }

    if (!frei0r->dl_handle) {

        ret = load_path(ctx, &frei0r->dl_handle, "/usr/local/lib/frei0r-1/", dl_name);

        if (ret < 0)

            return ret;

    }

    if (!frei0r->dl_handle) {

        ret = load_path(ctx, &frei0r->dl_handle, "/usr/lib/frei0r-1/", dl_name);

        if (ret < 0)

            return ret;

    }

    if (!frei0r->dl_handle) {

        av_log(ctx, AV_LOG_ERROR, "Could not find module '%s'\n", dl_name);

        return AVERROR(EINVAL);

    }



    if (!(f0r_init                = load_sym(ctx, "f0r_init"           )) ||

        !(f0r_get_plugin_info     = load_sym(ctx, "f0r_get_plugin_info")) ||

        !(frei0r->get_param_info  = load_sym(ctx, "f0r_get_param_info" )) ||

        !(frei0r->get_param_value = load_sym(ctx, "f0r_get_param_value")) ||

        !(frei0r->set_param_value = load_sym(ctx, "f0r_set_param_value")) ||

        !(frei0r->update          = load_sym(ctx, "f0r_update"         )) ||

        !(frei0r->construct       = load_sym(ctx, "f0r_construct"      )) ||

        !(frei0r->destruct        = load_sym(ctx, "f0r_destruct"       )) ||

        !(frei0r->deinit          = load_sym(ctx, "f0r_deinit"         )))

        return AVERROR(EINVAL);



    if (f0r_init() < 0) {

        av_log(ctx, AV_LOG_ERROR, "Could not init the frei0r module\n");

        return AVERROR(EINVAL);

    }



    f0r_get_plugin_info(&frei0r->plugin_info);

    pi = &frei0r->plugin_info;

    if (pi->plugin_type != type) {

        av_log(ctx, AV_LOG_ERROR,

               "Invalid type '%s' for the plugin\n",

               pi->plugin_type == F0R_PLUGIN_TYPE_FILTER ? "filter" :

               pi->plugin_type == F0R_PLUGIN_TYPE_SOURCE ? "source" :

               pi->plugin_type == F0R_PLUGIN_TYPE_MIXER2 ? "mixer2" :

               pi->plugin_type == F0R_PLUGIN_TYPE_MIXER3 ? "mixer3" : "unknown");

        return AVERROR(EINVAL);

    }



    av_log(ctx, AV_LOG_VERBOSE,

           "name:%s author:'%s' explanation:'%s' color_model:%s "

           "frei0r_version:%d version:%d.%d num_params:%d\n",

           pi->name, pi->author, pi->explanation,

           pi->color_model == F0R_COLOR_MODEL_BGRA8888 ? "bgra8888" :

           pi->color_model == F0R_COLOR_MODEL_RGBA8888 ? "rgba8888" :

           pi->color_model == F0R_COLOR_MODEL_PACKED32 ? "packed32" : "unknown",

           pi->frei0r_version, pi->major_version, pi->minor_version, pi->num_params);



    return 0;

}

uint32_t HELPER(tprot)(CPUS390XState *env, uint64_t a1, uint64_t a2)

{

    S390CPU *cpu = s390_env_get_cpu(env);

    CPUState *cs = CPU(cpu);



    /*

     * TODO: we currently don't handle all access protection types

     * (including access-list and key-controlled) as well as AR mode.

     */

    if (!s390_cpu_virt_mem_check_write(cpu, a1, 0, 1)) {

        /* Fetching permitted; storing permitted */

        return 0;

    }

    switch (env->int_pgm_code) {

    case PGM_PROTECTION:

        /* Fetching permitted; storing not permitted */

        cs->exception_index = 0;

        return 1;

    case PGM_ADDRESSING:

        /* Fetching not permitted; storing not permitted */

        cs->exception_index = 0;

        return 2;

    case PGM_ASCE_TYPE:

    case PGM_REG_FIRST_TRANS:

    case PGM_REG_SEC_TRANS:

    case PGM_REG_THIRD_TRANS:

    case PGM_SEGMENT_TRANS:

    case PGM_PAGE_TRANS:

    case PGM_ALET_SPEC:

    case PGM_ALEN_SPEC:

    case PGM_ALE_SEQ:

    case PGM_ASTE_VALID:

    case PGM_ASTE_SEQ:

    case PGM_EXT_AUTH:

        /* Translation not available */

        cs->exception_index = 0;

        return 3;

    }

    /* any other exception is forwarded to the guest */

    s390_cpu_virt_mem_handle_exc(cpu, GETPC());

    return 0;

}

static int adb_kbd_poll(ADBDevice *d, uint8_t *obuf)

{

    KBDState *s = ADB_KEYBOARD(d);

    int keycode;

    int olen;



    olen = 0;

    if (s->count == 0) {

        return 0;

    }

    keycode = s->data[s->rptr];

    s->rptr++;

    if (s->rptr == sizeof(s->data)) {

        s->rptr = 0;

    }

    s->count--;

    /*

     * The power key is the only two byte value key, so it is a special case.

     * Since 0x7f is not a used keycode for ADB we overload it to indicate the

     * power button when we're storing keycodes in our internal buffer, and

     * expand it out to two bytes when we send to the guest.

     */

    if (keycode == 0x7f) {

        obuf[0] = 0x7f;

        obuf[1] = 0x7f;

        olen = 2;

    } else {

        obuf[0] = keycode;

        /* NOTE: the power key key-up is the two byte sequence 0xff 0xff;

         * otherwise we could in theory send a second keycode in the second

         * byte, but choose not to bother.

         */

        obuf[1] = 0xff;

        olen = 2;

    }



    return olen;

}

static inline int wv_unpack_stereo(WavpackFrameContext *s, GetBitContext *gb,

                                   void *dst_l, void *dst_r, const int type)

{

    int i, j, count = 0;

    int last, t;

    int A, B, L, L2, R, R2;

    int pos                 = s->pos;

    uint32_t crc            = s->sc.crc;

    uint32_t crc_extra_bits = s->extra_sc.crc;

    int16_t *dst16_l        = dst_l;

    int16_t *dst16_r        = dst_r;

    int32_t *dst32_l        = dst_l;

    int32_t *dst32_r        = dst_r;

    float *dstfl_l          = dst_l;

    float *dstfl_r          = dst_r;



    s->one = s->zero = s->zeroes = 0;

    do {

        L = wv_get_value(s, gb, 0, &last);

        if (last)

            break;

        R = wv_get_value(s, gb, 1, &last);

        if (last)

            break;

        for (i = 0; i < s->terms; i++) {

            t = s->decorr[i].value;

            if (t > 0) {

                if (t > 8) {

                    if (t & 1) {

                        A = 2U * s->decorr[i].samplesA[0] - s->decorr[i].samplesA[1];

                        B = 2U * s->decorr[i].samplesB[0] - s->decorr[i].samplesB[1];

                    } else {

                        A = (int)(3U * s->decorr[i].samplesA[0] - s->decorr[i].samplesA[1]) >> 1;

                        B = (int)(3U * s->decorr[i].samplesB[0] - s->decorr[i].samplesB[1]) >> 1;

                    }

                    s->decorr[i].samplesA[1] = s->decorr[i].samplesA[0];

                    s->decorr[i].samplesB[1] = s->decorr[i].samplesB[0];

                    j                        = 0;

                } else {

                    A = s->decorr[i].samplesA[pos];

                    B = s->decorr[i].samplesB[pos];

                    j = (pos + t) & 7;

                }

                if (type != AV_SAMPLE_FMT_S16P) {

                    L2 = L + ((s->decorr[i].weightA * (int64_t)A + 512) >> 10);

                    R2 = R + ((s->decorr[i].weightB * (int64_t)B + 512) >> 10);

                } else {

                    L2 = L + ((int)(s->decorr[i].weightA * (unsigned)A + 512) >> 10);

                    R2 = R + ((int)(s->decorr[i].weightB * (unsigned)B + 512) >> 10);

                }

                if (A && L)

                    s->decorr[i].weightA -= ((((L ^ A) >> 30) & 2) - 1) * s->decorr[i].delta;

                if (B && R)

                    s->decorr[i].weightB -= ((((R ^ B) >> 30) & 2) - 1) * s->decorr[i].delta;

                s->decorr[i].samplesA[j] = L = L2;

                s->decorr[i].samplesB[j] = R = R2;

            } else if (t == -1) {

                if (type != AV_SAMPLE_FMT_S16P)

                    L2 = L + ((s->decorr[i].weightA * (int64_t)s->decorr[i].samplesA[0] + 512) >> 10);

                else

                    L2 = L + ((int)(s->decorr[i].weightA * (unsigned)s->decorr[i].samplesA[0] + 512) >> 10);

                UPDATE_WEIGHT_CLIP(s->decorr[i].weightA, s->decorr[i].delta, s->decorr[i].samplesA[0], L);

                L = L2;

                if (type != AV_SAMPLE_FMT_S16P)

                    R2 = R + ((s->decorr[i].weightB * (int64_t)L2 + 512) >> 10);

                else

                    R2 = R + ((int)(s->decorr[i].weightB * (unsigned)L2 + 512) >> 10);

                UPDATE_WEIGHT_CLIP(s->decorr[i].weightB, s->decorr[i].delta, L2, R);

                R                        = R2;

                s->decorr[i].samplesA[0] = R;

            } else {

                if (type != AV_SAMPLE_FMT_S16P)

                    R2 = R + ((s->decorr[i].weightB * (int64_t)s->decorr[i].samplesB[0] + 512) >> 10);

                else

                    R2 = R + ((int)(s->decorr[i].weightB * (unsigned)s->decorr[i].samplesB[0] + 512) >> 10);

                UPDATE_WEIGHT_CLIP(s->decorr[i].weightB, s->decorr[i].delta, s->decorr[i].samplesB[0], R);

                R = R2;



                if (t == -3) {

                    R2                       = s->decorr[i].samplesA[0];

                    s->decorr[i].samplesA[0] = R;

                }



                if (type != AV_SAMPLE_FMT_S16P)

                    L2 = L + ((s->decorr[i].weightA * (int64_t)R2 + 512) >> 10);

                else

                    L2 = L + ((int)(s->decorr[i].weightA * (unsigned)R2 + 512) >> 10);

                UPDATE_WEIGHT_CLIP(s->decorr[i].weightA, s->decorr[i].delta, R2, L);

                L                        = L2;

                s->decorr[i].samplesB[0] = L;

            }

        }



        if (type == AV_SAMPLE_FMT_S16P) {

            if (FFABS(L) + (unsigned)FFABS(R) > (1<<19)) {

                av_log(s->avctx, AV_LOG_ERROR, "sample %d %d too large\n", L, R);

                return AVERROR_INVALIDDATA;

            }

        }



        pos = (pos + 1) & 7;

        if (s->joint)

            L += (unsigned)(R -= (unsigned)(L >> 1));

        crc = (crc * 3 + L) * 3 + R;



        if (type == AV_SAMPLE_FMT_FLTP) {

            *dstfl_l++ = wv_get_value_float(s, &crc_extra_bits, L);

            *dstfl_r++ = wv_get_value_float(s, &crc_extra_bits, R);

        } else if (type == AV_SAMPLE_FMT_S32P) {

            *dst32_l++ = wv_get_value_integer(s, &crc_extra_bits, L);

            *dst32_r++ = wv_get_value_integer(s, &crc_extra_bits, R);

        } else {

            *dst16_l++ = wv_get_value_integer(s, &crc_extra_bits, L);

            *dst16_r++ = wv_get_value_integer(s, &crc_extra_bits, R);

        }

        count++;

    } while (!last && count < s->samples);



    wv_reset_saved_context(s);



    if (last && count < s->samples) {

        int size = av_get_bytes_per_sample(type);

        memset((uint8_t*)dst_l + count*size, 0, (s->samples-count)*size);

        memset((uint8_t*)dst_r + count*size, 0, (s->samples-count)*size);

    }



    if ((s->avctx->err_recognition & AV_EF_CRCCHECK) &&

        wv_check_crc(s, crc, crc_extra_bits))

        return AVERROR_INVALIDDATA;



    return 0;

}

static void qxl_create_guest_primary(PCIQXLDevice *qxl, int loadvm,

                                     qxl_async_io async)

{

    QXLDevSurfaceCreate surface;

    QXLSurfaceCreate *sc = &qxl->guest_primary.surface;

    int size;

    int requested_height = le32_to_cpu(sc->height);

    int requested_stride = le32_to_cpu(sc->stride);



    size = abs(requested_stride) * requested_height;

    if (size > qxl->vgamem_size) {

        qxl_set_guest_bug(qxl, "%s: requested primary larger then framebuffer"

                               " size", __func__);

        return;

    }



    if (qxl->mode == QXL_MODE_NATIVE) {

        qxl_set_guest_bug(qxl, "%s: nop since already in QXL_MODE_NATIVE",

                      __func__);

    }

    qxl_exit_vga_mode(qxl);



    surface.format     = le32_to_cpu(sc->format);

    surface.height     = le32_to_cpu(sc->height);

    surface.mem        = le64_to_cpu(sc->mem);

    surface.position   = le32_to_cpu(sc->position);

    surface.stride     = le32_to_cpu(sc->stride);

    surface.width      = le32_to_cpu(sc->width);

    surface.type       = le32_to_cpu(sc->type);

    surface.flags      = le32_to_cpu(sc->flags);

    trace_qxl_create_guest_primary(qxl->id, sc->width, sc->height, sc->mem,

                                   sc->format, sc->position);

    trace_qxl_create_guest_primary_rest(qxl->id, sc->stride, sc->type,

                                        sc->flags);



    if ((surface.stride & 0x3) != 0) {

        qxl_set_guest_bug(qxl, "primary surface stride = %d %% 4 != 0",

                          surface.stride);

        return;

    }



    surface.mouse_mode = true;

    surface.group_id   = MEMSLOT_GROUP_GUEST;

    if (loadvm) {

        surface.flags |= QXL_SURF_FLAG_KEEP_DATA;

    }



    qxl->mode = QXL_MODE_NATIVE;

    qxl->cmdflags = 0;

    qemu_spice_create_primary_surface(&qxl->ssd, 0, &surface, async);



    if (async == QXL_SYNC) {

        qxl_create_guest_primary_complete(qxl);

    }

}

static inline int signed_shift(int i, int shift) {

    if (shift > 0)

        return i << shift;

    return i >> -shift;

}

static void pmsav7_write(CPUARMState *env, const ARMCPRegInfo *ri,

                         uint64_t value)

{

    ARMCPU *cpu = arm_env_get_cpu(env);

    uint32_t *u32p = *(uint32_t **)raw_ptr(env, ri);



    if (!u32p) {

        return;

    }



    u32p += env->pmsav7.rnr;

    tlb_flush(CPU(cpu)); /* Mappings may have changed - purge! */

    *u32p = value;

}

void qemu_opts_del(QemuOpts *opts)

{

    QemuOpt *opt;



    for (;;) {

        opt = TAILQ_FIRST(&opts->head);

        if (opt == NULL)

            break;

        qemu_opt_del(opt);

    }

    TAILQ_REMOVE(&opts->list->head, opts, next);

    qemu_free(opts);

}

static int raw_pwrite(BlockDriverState *bs, int64_t offset,

                      const uint8_t *buf, int count)

{

    BDRVRawState *s = bs->opaque;

    int size, ret, shift, sum;



    sum = 0;



    if (s->aligned_buf != NULL) {



        if (offset & 0x1ff) {

            /* align offset on a 512 bytes boundary */

            shift = offset & 0x1ff;

            ret = raw_pread_aligned(bs, offset - shift, s->aligned_buf, 512);

            if (ret < 0)

                return ret;



            size = 512 - shift;

            if (size > count)

                size = count;

            memcpy(s->aligned_buf + shift, buf, size);



            ret = raw_pwrite_aligned(bs, offset - shift, s->aligned_buf, 512);

            if (ret < 0)

                return ret;



            buf += size;

            offset += size;

            count -= size;

            sum += size;



            if (count == 0)

                return sum;

        }

        if (count & 0x1ff || (uintptr_t) buf & 0x1ff) {



            while ((size = (count & ~0x1ff)) != 0) {



                if (size > ALIGNED_BUFFER_SIZE)

                    size = ALIGNED_BUFFER_SIZE;



                memcpy(s->aligned_buf, buf, size);



                ret = raw_pwrite_aligned(bs, offset, s->aligned_buf, size);

                if (ret < 0)

                    return ret;



                buf += ret;

                offset += ret;

                count -= ret;

                sum += ret;

            }

            /* here, count < 512 because (count & ~0x1ff) == 0 */

            if (count) {

                ret = raw_pread_aligned(bs, offset, s->aligned_buf, 512);

                if (ret < 0)

                    return ret;

                 memcpy(s->aligned_buf, buf, count);



                 ret = raw_pwrite_aligned(bs, offset, s->aligned_buf, 512);

                 if (ret < 0)

                     return ret;

                 if (count < ret)

                     ret = count;



                 sum += ret;

            }

            return sum;

        }

    }

    return raw_pwrite_aligned(bs, offset, buf, count) + sum;

}

void acpi_pcihp_device_unplug_cb(HotplugHandler *hotplug_dev, AcpiPciHpState *s,

                                 DeviceState *dev, Error **errp)

{

    PCIDevice *pdev = PCI_DEVICE(dev);

    int slot = PCI_SLOT(pdev->devfn);

    int bsel = acpi_pcihp_get_bsel(pdev->bus);

    if (bsel < 0) {

        error_setg(errp, "Unsupported bus. Bus doesn't have property '"

                   ACPI_PCIHP_PROP_BSEL "' set");

        return;

    }



    s->acpi_pcihp_pci_status[bsel].down |= (1U << slot);

    acpi_send_event(DEVICE(hotplug_dev), ACPI_PCI_HOTPLUG_STATUS);

}

int bdrv_debug_resume(BlockDriverState *bs, const char *tag)

{

    while (bs && (!bs->drv || !bs->drv->bdrv_debug_resume)) {

        bs = bs->file;

    }



    if (bs && bs->drv && bs->drv->bdrv_debug_resume) {

        return bs->drv->bdrv_debug_resume(bs, tag);

    }



    return -ENOTSUP;

}

static int r3d_read_redv(AVFormatContext *s, AVPacket *pkt, Atom *atom)

{

    AVStream *st = s->streams[0];

    int tmp, tmp2;

    uint64_t pos = url_ftell(s->pb);

    unsigned dts;



    dts = get_be32(s->pb);



    tmp = get_be32(s->pb);

    dprintf(s, "frame num %d\n", tmp);



    tmp  = get_byte(s->pb); // major version

    tmp2 = get_byte(s->pb); // minor version

    dprintf(s, "version %d.%d\n", tmp, tmp2);



    tmp = get_be16(s->pb); // unknown

    dprintf(s, "unknown %d\n", tmp);



    if (tmp > 4) {

        tmp = get_be16(s->pb); // unknown

        dprintf(s, "unknown %d\n", tmp);



        tmp = get_be16(s->pb); // unknown

        dprintf(s, "unknown %d\n", tmp);



        tmp = get_be32(s->pb);

        dprintf(s, "width %d\n", tmp);

        tmp = get_be32(s->pb);

        dprintf(s, "height %d\n", tmp);



        tmp = get_be32(s->pb);

        dprintf(s, "metadata len %d\n", tmp);

    }

    tmp = atom->size - 8 - (url_ftell(s->pb) - pos);

    if (tmp < 0)

        return -1;



    if (av_get_packet(s->pb, pkt, tmp) != tmp) {

        av_log(s, AV_LOG_ERROR, "error reading video packet\n");

        return -1;

    }



    pkt->stream_index = 0;

    pkt->dts = dts;

    if (st->codec->time_base.den)

        pkt->duration = (uint64_t)st->time_base.den*

            st->codec->time_base.num/st->codec->time_base.den;

    dprintf(s, "pkt dts %lld duration %d\n", pkt->dts, pkt->duration);



    return 0;

}

static uint64_t mpc8544_guts_read(void *opaque, target_phys_addr_t addr,

                                  unsigned size)

{

    uint32_t value = 0;

    CPUPPCState *env = cpu_single_env;



    addr &= MPC8544_GUTS_MMIO_SIZE - 1;

    switch (addr) {

    case MPC8544_GUTS_ADDR_PVR:

        value = env->spr[SPR_PVR];

        break;

    case MPC8544_GUTS_ADDR_SVR:

        value = env->spr[SPR_E500_SVR];

        break;

    default:

        fprintf(stderr, "guts: Unknown register read: %x\n", (int)addr);

        break;

    }



    return value;

}

int bdrv_set_read_only(BlockDriverState *bs, bool read_only, Error **errp)

{

    /* Do not set read_only if copy_on_read is enabled */

    if (bs->copy_on_read && read_only) {

        error_setg(errp, "Can't set node '%s' to r/o with copy-on-read enabled",

                   bdrv_get_device_or_node_name(bs));

        return -EINVAL;

    }



    /* Do not clear read_only if it is prohibited */

    if (!read_only && !(bs->open_flags & BDRV_O_ALLOW_RDWR)) {

        error_setg(errp, "Node '%s' is read only",

                   bdrv_get_device_or_node_name(bs));

        return -EPERM;

    }



    bs->read_only = read_only;

    return 0;

}

int qemu_savevm_state_begin(Monitor *mon, QEMUFile *f, int blk_enable,

                            int shared)

{

    SaveStateEntry *se;

    int ret;



    QTAILQ_FOREACH(se, &savevm_handlers, entry) {

        if(se->set_params == NULL) {

            continue;

	}

	se->set_params(blk_enable, shared, se->opaque);

    }



    qemu_put_be32(f, QEMU_VM_FILE_MAGIC);

    qemu_put_be32(f, QEMU_VM_FILE_VERSION);



    QTAILQ_FOREACH(se, &savevm_handlers, entry) {

        int len;



        if (se->save_live_state == NULL)

            continue;



        /* Section type */

        qemu_put_byte(f, QEMU_VM_SECTION_START);

        qemu_put_be32(f, se->section_id);



        /* ID string */

        len = strlen(se->idstr);

        qemu_put_byte(f, len);

        qemu_put_buffer(f, (uint8_t *)se->idstr, len);



        qemu_put_be32(f, se->instance_id);

        qemu_put_be32(f, se->version_id);



        ret = se->save_live_state(mon, f, QEMU_VM_SECTION_START, se->opaque);

        if (ret < 0) {

            qemu_savevm_state_cancel(mon, f);

            return ret;

        }

    }

    ret = qemu_file_get_error(f);

    if (ret != 0) {

        qemu_savevm_state_cancel(mon, f);

    }



    return ret;



}

static void gen_conditional_jump(DisasContext * ctx,

				 target_ulong ift, target_ulong ifnott)

{

    int l1;

    TCGv sr;



    l1 = gen_new_label();

    sr = tcg_temp_new();

    tcg_gen_andi_i32(sr, cpu_sr, SR_T);

    tcg_gen_brcondi_i32(TCG_COND_NE, sr, 0, l1);

    gen_goto_tb(ctx, 0, ifnott);

    gen_set_label(l1);

    gen_goto_tb(ctx, 1, ift);

}

static int wav_write_trailer(AVFormatContext *s)

{

    AVIOContext *pb  = s->pb;

    WAVMuxContext    *wav = s->priv_data;

    int64_t file_size, data_size;

    int64_t number_of_samples = 0;

    int rf64 = 0;



    avio_flush(pb);



    if (s->pb->seekable) {

        if (wav->write_peak != 2) {

            ff_end_tag(pb, wav->data);

            avio_flush(pb);

        }



        if (wav->write_peak && wav->peak_output) {

            peak_write_chunk(s);

            avio_flush(pb);

        }



        /* update file size */

        file_size = avio_tell(pb);

        data_size = file_size - wav->data;

        if (wav->rf64 == RF64_ALWAYS || (wav->rf64 == RF64_AUTO && file_size - 8 > UINT32_MAX)) {

            rf64 = 1;

        } else {

            avio_seek(pb, 4, SEEK_SET);

            avio_wl32(pb, (uint32_t)(file_size - 8));

            avio_seek(pb, file_size, SEEK_SET);



            avio_flush(pb);

        }



        number_of_samples = av_rescale(wav->maxpts - wav->minpts + wav->last_duration,

                                       s->streams[0]->codec->sample_rate * (int64_t)s->streams[0]->time_base.num,

                                       s->streams[0]->time_base.den);



        if(s->streams[0]->codec->codec_tag != 0x01) {

            /* Update num_samps in fact chunk */

            avio_seek(pb, wav->fact_pos, SEEK_SET);

            if (rf64 || (wav->rf64 == RF64_AUTO && number_of_samples > UINT32_MAX)) {

                rf64 = 1;

                avio_wl32(pb, -1);

            } else {

                avio_wl32(pb, number_of_samples);

                avio_seek(pb, file_size, SEEK_SET);

                avio_flush(pb);

            }

        }



        if (rf64) {

            /* overwrite RIFF with RF64 */

            avio_seek(pb, 0, SEEK_SET);

            ffio_wfourcc(pb, "RF64");

            avio_wl32(pb, -1);



            /* write ds64 chunk (overwrite JUNK if rf64 == RF64_AUTO) */

            avio_seek(pb, wav->ds64 - 8, SEEK_SET);

            ffio_wfourcc(pb, "ds64");

            avio_wl32(pb, 28);                  /* ds64 chunk size */

            avio_wl64(pb, file_size - 8);       /* RF64 chunk size */

            avio_wl64(pb, data_size);           /* data chunk size */

            avio_wl64(pb, number_of_samples);   /* fact chunk number of samples */

            avio_wl32(pb, 0);                   /* number of table entries for non-'data' chunks */



            /* write -1 in data chunk size */

            avio_seek(pb, wav->data - 4, SEEK_SET);

            avio_wl32(pb, -1);



            avio_seek(pb, file_size, SEEK_SET);

            avio_flush(pb);

        }

    }



    if (wav->write_peak)

        peak_free_buffers(s);



    return 0;

}

av_cold int swr_init(struct SwrContext *s){

    int ret;



    clear_context(s);



    if(s-> in_sample_fmt >= AV_SAMPLE_FMT_NB){

        av_log(s, AV_LOG_ERROR, "Requested input sample format %d is invalid\n", s->in_sample_fmt);

        return AVERROR(EINVAL);

    }

    if(s->out_sample_fmt >= AV_SAMPLE_FMT_NB){

        av_log(s, AV_LOG_ERROR, "Requested output sample format %d is invalid\n", s->out_sample_fmt);

        return AVERROR(EINVAL);

    }



    s->out.ch_count  = s-> user_out_ch_count;

    s-> in.ch_count  = s->  user_in_ch_count;

    s->used_ch_count = s->user_used_ch_count;



    s-> in_ch_layout = s-> user_in_ch_layout;

    s->out_ch_layout = s->user_out_ch_layout;



    if(av_get_channel_layout_nb_channels(s-> in_ch_layout) > SWR_CH_MAX) {

        av_log(s, AV_LOG_WARNING, "Input channel layout 0x%"PRIx64" is invalid or unsupported.\n", s-> in_ch_layout);

        s->in_ch_layout = 0;

    }



    if(av_get_channel_layout_nb_channels(s->out_ch_layout) > SWR_CH_MAX) {

        av_log(s, AV_LOG_WARNING, "Output channel layout 0x%"PRIx64" is invalid or unsupported.\n", s->out_ch_layout);

        s->out_ch_layout = 0;

    }



    switch(s->engine){

#if CONFIG_LIBSOXR

        case SWR_ENGINE_SOXR: s->resampler = &swri_soxr_resampler; break;

#endif

        case SWR_ENGINE_SWR : s->resampler = &swri_resampler; break;

        default:

            av_log(s, AV_LOG_ERROR, "Requested resampling engine is unavailable\n");

            return AVERROR(EINVAL);

    }



    if(!s->used_ch_count)

        s->used_ch_count= s->in.ch_count;



    if(s->used_ch_count && s-> in_ch_layout && s->used_ch_count != av_get_channel_layout_nb_channels(s-> in_ch_layout)){

        av_log(s, AV_LOG_WARNING, "Input channel layout has a different number of channels than the number of used channels, ignoring layout\n");

        s-> in_ch_layout= 0;

    }



    if(!s-> in_ch_layout)

        s-> in_ch_layout= av_get_default_channel_layout(s->used_ch_count);

    if(!s->out_ch_layout)

        s->out_ch_layout= av_get_default_channel_layout(s->out.ch_count);



    s->rematrix= s->out_ch_layout  !=s->in_ch_layout || s->rematrix_volume!=1.0 ||

                 s->rematrix_custom;



    if(s->int_sample_fmt == AV_SAMPLE_FMT_NONE){

        if(av_get_planar_sample_fmt(s->in_sample_fmt) <= AV_SAMPLE_FMT_S16P){

            s->int_sample_fmt= AV_SAMPLE_FMT_S16P;

        }else if(   av_get_planar_sample_fmt(s-> in_sample_fmt) == AV_SAMPLE_FMT_S32P

                 && av_get_planar_sample_fmt(s->out_sample_fmt) == AV_SAMPLE_FMT_S32P

                 && !s->rematrix

                 && s->engine != SWR_ENGINE_SOXR){

            s->int_sample_fmt= AV_SAMPLE_FMT_S32P;

        }else if(av_get_planar_sample_fmt(s->in_sample_fmt) <= AV_SAMPLE_FMT_FLTP){

            s->int_sample_fmt= AV_SAMPLE_FMT_FLTP;

        }else{

            av_log(s, AV_LOG_DEBUG, "Using double precision mode\n");

            s->int_sample_fmt= AV_SAMPLE_FMT_DBLP;

        }

    }



    if(   s->int_sample_fmt != AV_SAMPLE_FMT_S16P

        &&s->int_sample_fmt != AV_SAMPLE_FMT_S32P

        &&s->int_sample_fmt != AV_SAMPLE_FMT_FLTP

        &&s->int_sample_fmt != AV_SAMPLE_FMT_DBLP){

        av_log(s, AV_LOG_ERROR, "Requested sample format %s is not supported internally, S16/S32/FLT/DBL is supported\n", av_get_sample_fmt_name(s->int_sample_fmt));

        return AVERROR(EINVAL);

    }



    set_audiodata_fmt(&s-> in, s-> in_sample_fmt);

    set_audiodata_fmt(&s->out, s->out_sample_fmt);



    if (s->firstpts_in_samples != AV_NOPTS_VALUE) {

        if (!s->async && s->min_compensation >= FLT_MAX/2)

            s->async = 1;

        s->firstpts =

        s->outpts   = s->firstpts_in_samples * s->out_sample_rate;

    } else

        s->firstpts = AV_NOPTS_VALUE;



    if (s->async) {

        if (s->min_compensation >= FLT_MAX/2)

            s->min_compensation = 0.001;

        if (s->async > 1.0001) {

            s->max_soft_compensation = s->async / (double) s->in_sample_rate;

        }

    }



    if (s->out_sample_rate!=s->in_sample_rate || (s->flags & SWR_FLAG_RESAMPLE)){

        s->resample = s->resampler->init(s->resample, s->out_sample_rate, s->in_sample_rate, s->filter_size, s->phase_shift, s->linear_interp, s->cutoff, s->int_sample_fmt, s->filter_type, s->kaiser_beta, s->precision, s->cheby);

    }else

        s->resampler->free(&s->resample);

    if(    s->int_sample_fmt != AV_SAMPLE_FMT_S16P

        && s->int_sample_fmt != AV_SAMPLE_FMT_S32P

        && s->int_sample_fmt != AV_SAMPLE_FMT_FLTP

        && s->int_sample_fmt != AV_SAMPLE_FMT_DBLP

        && s->resample){

        av_log(s, AV_LOG_ERROR, "Resampling only supported with internal s16/s32/flt/dbl\n");

        return -1;

    }



#define RSC 1 //FIXME finetune

    if(!s-> in.ch_count)

        s-> in.ch_count= av_get_channel_layout_nb_channels(s-> in_ch_layout);

    if(!s->used_ch_count)

        s->used_ch_count= s->in.ch_count;

    if(!s->out.ch_count)

        s->out.ch_count= av_get_channel_layout_nb_channels(s->out_ch_layout);



    if(!s-> in.ch_count){

        av_assert0(!s->in_ch_layout);

        av_log(s, AV_LOG_ERROR, "Input channel count and layout are unset\n");

        return -1;

    }



    if ((!s->out_ch_layout || !s->in_ch_layout) && s->used_ch_count != s->out.ch_count && !s->rematrix_custom) {

        char l1[1024], l2[1024];

        av_get_channel_layout_string(l1, sizeof(l1), s-> in.ch_count, s-> in_ch_layout);

        av_get_channel_layout_string(l2, sizeof(l2), s->out.ch_count, s->out_ch_layout);

        av_log(s, AV_LOG_ERROR, "Rematrix is needed between %s and %s "

               "but there is not enough information to do it\n", l1, l2);

        return -1;

    }



av_assert0(s->used_ch_count);

av_assert0(s->out.ch_count);

    s->resample_first= RSC*s->out.ch_count/s->in.ch_count - RSC < s->out_sample_rate/(float)s-> in_sample_rate - 1.0;



    s->in_buffer= s->in;

    s->silence  = s->in;

    s->drop_temp= s->out;



    if(!s->resample && !s->rematrix && !s->channel_map && !s->dither.method){

        s->full_convert = swri_audio_convert_alloc(s->out_sample_fmt,

                                                   s-> in_sample_fmt, s-> in.ch_count, NULL, 0);

        return 0;

    }



    s->in_convert = swri_audio_convert_alloc(s->int_sample_fmt,

                                             s-> in_sample_fmt, s->used_ch_count, s->channel_map, 0);

    s->out_convert= swri_audio_convert_alloc(s->out_sample_fmt,

                                             s->int_sample_fmt, s->out.ch_count, NULL, 0);



    if (!s->in_convert || !s->out_convert)

        return AVERROR(ENOMEM);



    s->postin= s->in;

    s->preout= s->out;

    s->midbuf= s->in;



    if(s->channel_map){

        s->postin.ch_count=

        s->midbuf.ch_count= s->used_ch_count;

        if(s->resample)

            s->in_buffer.ch_count= s->used_ch_count;

    }

    if(!s->resample_first){

        s->midbuf.ch_count= s->out.ch_count;

        if(s->resample)

            s->in_buffer.ch_count = s->out.ch_count;

    }



    set_audiodata_fmt(&s->postin, s->int_sample_fmt);

    set_audiodata_fmt(&s->midbuf, s->int_sample_fmt);

    set_audiodata_fmt(&s->preout, s->int_sample_fmt);



    if(s->resample){

        set_audiodata_fmt(&s->in_buffer, s->int_sample_fmt);

    }



    if ((ret = swri_dither_init(s, s->out_sample_fmt, s->int_sample_fmt)) < 0)

        return ret;



    if(s->rematrix || s->dither.method)

        return swri_rematrix_init(s);



    return 0;

}

static void remove_port(VirtIOSerial *vser, uint32_t port_id)

{

    VirtIOSerialPort *port;

    unsigned int i;



    i = port_id / 32;

    vser->ports_map[i] &= ~(1U << (port_id % 32));



    port = find_port_by_id(vser, port_id);

    /*

     * This function is only called from qdev's unplug callback; if we

     * get a NULL port here, we're in trouble.

     */

    assert(port);



    /* Flush out any unconsumed buffers first */

    discard_vq_data(port->ovq, VIRTIO_DEVICE(port->vser));



    send_control_event(vser, port->id, VIRTIO_CONSOLE_PORT_REMOVE, 1);

}

void rgb16tobgr32(const uint8_t *src, uint8_t *dst, unsigned int src_size)

{

	const uint16_t *end;

	uint8_t *d = (uint8_t *)dst;

	const uint16_t *s = (uint16_t *)src;

	end = s + src_size/2;

	while(s < end)

	{

		register uint16_t bgr;

		bgr = *s++;

		*d++ = (bgr&0xF800)>>8;

		*d++ = (bgr&0x7E0)>>3;

		*d++ = (bgr&0x1F)<<3;

		*d++ = 0;

	}

}

static int decode_audio_block(AC3DecodeContext *s, int blk)

{

    int fbw_channels = s->fbw_channels;

    int channel_mode = s->channel_mode;

    int i, bnd, seg, ch, ret;

    int different_transforms;

    int downmix_output;

    int cpl_in_use;

    GetBitContext *gbc = &s->gbc;

    uint8_t bit_alloc_stages[AC3_MAX_CHANNELS] = { 0 };



    /* block switch flags */

    different_transforms = 0;

    if (s->block_switch_syntax) {

        for (ch = 1; ch <= fbw_channels; ch++) {

            s->block_switch[ch] = get_bits1(gbc);

            if (ch > 1 && s->block_switch[ch] != s->block_switch[1])

                different_transforms = 1;

        }

    }



    /* dithering flags */

    if (s->dither_flag_syntax) {

        for (ch = 1; ch <= fbw_channels; ch++) {

            s->dither_flag[ch] = get_bits1(gbc);

        }

    }



    /* dynamic range */

    i = !s->channel_mode;

    do {

        if (get_bits1(gbc)) {

            /* Allow asymmetric application of DRC when drc_scale > 1.

               Amplification of quiet sounds is enhanced */

            int range_bits = get_bits(gbc, 8);

            INTFLOAT range = AC3_RANGE(range_bits);

            if (range_bits <= 127 || s->drc_scale <= 1.0)

                s->dynamic_range[i] = AC3_DYNAMIC_RANGE(range);

            else

                s->dynamic_range[i] = range;

        } else if (blk == 0) {

            s->dynamic_range[i] = AC3_DYNAMIC_RANGE1;

        }

    } while (i--);



    /* spectral extension strategy */

    if (s->eac3 && (!blk || get_bits1(gbc))) {

        s->spx_in_use = get_bits1(gbc);

        if (s->spx_in_use) {

            if ((ret = spx_strategy(s, blk)) < 0)

                return ret;

        }

    }

    if (!s->eac3 || !s->spx_in_use) {

        s->spx_in_use = 0;

        for (ch = 1; ch <= fbw_channels; ch++) {

            s->channel_uses_spx[ch] = 0;

            s->first_spx_coords[ch] = 1;

        }

    }



    /* spectral extension coordinates */

    if (s->spx_in_use)

        spx_coordinates(s);



    /* coupling strategy */

    if (s->eac3 ? s->cpl_strategy_exists[blk] : get_bits1(gbc)) {

        if ((ret = coupling_strategy(s, blk, bit_alloc_stages)) < 0)

            return ret;

    } else if (!s->eac3) {

        if (!blk) {

            av_log(s->avctx, AV_LOG_ERROR, "new coupling strategy must "

                   "be present in block 0\n");

            return AVERROR_INVALIDDATA;

        } else {

            s->cpl_in_use[blk] = s->cpl_in_use[blk-1];

        }

    }

    cpl_in_use = s->cpl_in_use[blk];



    /* coupling coordinates */

    if (cpl_in_use) {

        if ((ret = coupling_coordinates(s, blk)) < 0)

            return ret;

    }



    /* stereo rematrixing strategy and band structure */

    if (channel_mode == AC3_CHMODE_STEREO) {

        if ((s->eac3 && !blk) || get_bits1(gbc)) {

            s->num_rematrixing_bands = 4;

            if (cpl_in_use && s->start_freq[CPL_CH] <= 61) {

                s->num_rematrixing_bands -= 1 + (s->start_freq[CPL_CH] == 37);

            } else if (s->spx_in_use && s->spx_src_start_freq <= 61) {

                s->num_rematrixing_bands--;

            }

            for (bnd = 0; bnd < s->num_rematrixing_bands; bnd++)

                s->rematrixing_flags[bnd] = get_bits1(gbc);

        } else if (!blk) {

            av_log(s->avctx, AV_LOG_WARNING, "Warning: "

                   "new rematrixing strategy not present in block 0\n");

            s->num_rematrixing_bands = 0;

        }

    }



    /* exponent strategies for each channel */

    for (ch = !cpl_in_use; ch <= s->channels; ch++) {

        if (!s->eac3)

            s->exp_strategy[blk][ch] = get_bits(gbc, 2 - (ch == s->lfe_ch));

        if (s->exp_strategy[blk][ch] != EXP_REUSE)

            bit_alloc_stages[ch] = 3;

    }



    /* channel bandwidth */

    for (ch = 1; ch <= fbw_channels; ch++) {

        s->start_freq[ch] = 0;

        if (s->exp_strategy[blk][ch] != EXP_REUSE) {

            int group_size;

            int prev = s->end_freq[ch];

            if (s->channel_in_cpl[ch])

                s->end_freq[ch] = s->start_freq[CPL_CH];

            else if (s->channel_uses_spx[ch])

                s->end_freq[ch] = s->spx_src_start_freq;

            else {

                int bandwidth_code = get_bits(gbc, 6);

                if (bandwidth_code > 60) {

                    av_log(s->avctx, AV_LOG_ERROR, "bandwidth code = %d > 60\n", bandwidth_code);

                    return AVERROR_INVALIDDATA;

                }

                s->end_freq[ch] = bandwidth_code * 3 + 73;

            }

            group_size = 3 << (s->exp_strategy[blk][ch] - 1);

            s->num_exp_groups[ch] = (s->end_freq[ch] + group_size-4) / group_size;

            if (blk > 0 && s->end_freq[ch] != prev)

                memset(bit_alloc_stages, 3, AC3_MAX_CHANNELS);

        }

    }

    if (cpl_in_use && s->exp_strategy[blk][CPL_CH] != EXP_REUSE) {

        s->num_exp_groups[CPL_CH] = (s->end_freq[CPL_CH] - s->start_freq[CPL_CH]) /

                                    (3 << (s->exp_strategy[blk][CPL_CH] - 1));

    }



    /* decode exponents for each channel */

    for (ch = !cpl_in_use; ch <= s->channels; ch++) {

        if (s->exp_strategy[blk][ch] != EXP_REUSE) {

            s->dexps[ch][0] = get_bits(gbc, 4) << !ch;

            if (decode_exponents(s, gbc, s->exp_strategy[blk][ch],

                                 s->num_exp_groups[ch], s->dexps[ch][0],

                                 &s->dexps[ch][s->start_freq[ch]+!!ch])) {

                return AVERROR_INVALIDDATA;

            }

            if (ch != CPL_CH && ch != s->lfe_ch)

                skip_bits(gbc, 2); /* skip gainrng */

        }

    }



    /* bit allocation information */

    if (s->bit_allocation_syntax) {

        if (get_bits1(gbc)) {

            s->bit_alloc_params.slow_decay = ff_ac3_slow_decay_tab[get_bits(gbc, 2)] >> s->bit_alloc_params.sr_shift;

            s->bit_alloc_params.fast_decay = ff_ac3_fast_decay_tab[get_bits(gbc, 2)] >> s->bit_alloc_params.sr_shift;

            s->bit_alloc_params.slow_gain  = ff_ac3_slow_gain_tab[get_bits(gbc, 2)];

            s->bit_alloc_params.db_per_bit = ff_ac3_db_per_bit_tab[get_bits(gbc, 2)];

            s->bit_alloc_params.floor  = ff_ac3_floor_tab[get_bits(gbc, 3)];

            for (ch = !cpl_in_use; ch <= s->channels; ch++)

                bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

        } else if (!blk) {

            av_log(s->avctx, AV_LOG_ERROR, "new bit allocation info must "

                   "be present in block 0\n");

            return AVERROR_INVALIDDATA;

        }

    }



    /* signal-to-noise ratio offsets and fast gains (signal-to-mask ratios) */

    if (!s->eac3 || !blk) {

        if (s->snr_offset_strategy && get_bits1(gbc)) {

            int snr = 0;

            int csnr;

            csnr = (get_bits(gbc, 6) - 15) << 4;

            for (i = ch = !cpl_in_use; ch <= s->channels; ch++) {

                /* snr offset */

                if (ch == i || s->snr_offset_strategy == 2)

                    snr = (csnr + get_bits(gbc, 4)) << 2;

                /* run at least last bit allocation stage if snr offset changes */

                if (blk && s->snr_offset[ch] != snr) {

                    bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 1);

                }

                s->snr_offset[ch] = snr;



                /* fast gain (normal AC-3 only) */

                if (!s->eac3) {

                    int prev = s->fast_gain[ch];

                    s->fast_gain[ch] = ff_ac3_fast_gain_tab[get_bits(gbc, 3)];

                    /* run last 2 bit allocation stages if fast gain changes */

                    if (blk && prev != s->fast_gain[ch])

                        bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

                }

            }

        } else if (!s->eac3 && !blk) {

            av_log(s->avctx, AV_LOG_ERROR, "new snr offsets must be present in block 0\n");

            return AVERROR_INVALIDDATA;

        }

    }



    /* fast gain (E-AC-3 only) */

    if (s->fast_gain_syntax && get_bits1(gbc)) {

        for (ch = !cpl_in_use; ch <= s->channels; ch++) {

            int prev = s->fast_gain[ch];

            s->fast_gain[ch] = ff_ac3_fast_gain_tab[get_bits(gbc, 3)];

            /* run last 2 bit allocation stages if fast gain changes */

            if (blk && prev != s->fast_gain[ch])

                bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

        }

    } else if (s->eac3 && !blk) {

        for (ch = !cpl_in_use; ch <= s->channels; ch++)

            s->fast_gain[ch] = ff_ac3_fast_gain_tab[4];

    }



    /* E-AC-3 to AC-3 converter SNR offset */

    if (s->frame_type == EAC3_FRAME_TYPE_INDEPENDENT && get_bits1(gbc)) {

        skip_bits(gbc, 10); // skip converter snr offset

    }



    /* coupling leak information */

    if (cpl_in_use) {

        if (s->first_cpl_leak || get_bits1(gbc)) {

            int fl = get_bits(gbc, 3);

            int sl = get_bits(gbc, 3);

            /* run last 2 bit allocation stages for coupling channel if

               coupling leak changes */

            if (blk && (fl != s->bit_alloc_params.cpl_fast_leak ||

                sl != s->bit_alloc_params.cpl_slow_leak)) {

                bit_alloc_stages[CPL_CH] = FFMAX(bit_alloc_stages[CPL_CH], 2);

            }

            s->bit_alloc_params.cpl_fast_leak = fl;

            s->bit_alloc_params.cpl_slow_leak = sl;

        } else if (!s->eac3 && !blk) {

            av_log(s->avctx, AV_LOG_ERROR, "new coupling leak info must "

                   "be present in block 0\n");

            return AVERROR_INVALIDDATA;

        }

        s->first_cpl_leak = 0;

    }



    /* delta bit allocation information */

    if (s->dba_syntax && get_bits1(gbc)) {

        /* delta bit allocation exists (strategy) */

        for (ch = !cpl_in_use; ch <= fbw_channels; ch++) {

            s->dba_mode[ch] = get_bits(gbc, 2);

            if (s->dba_mode[ch] == DBA_RESERVED) {

                av_log(s->avctx, AV_LOG_ERROR, "delta bit allocation strategy reserved\n");

                return AVERROR_INVALIDDATA;

            }

            bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

        }

        /* channel delta offset, len and bit allocation */

        for (ch = !cpl_in_use; ch <= fbw_channels; ch++) {

            if (s->dba_mode[ch] == DBA_NEW) {

                s->dba_nsegs[ch] = get_bits(gbc, 3) + 1;

                for (seg = 0; seg < s->dba_nsegs[ch]; seg++) {

                    s->dba_offsets[ch][seg] = get_bits(gbc, 5);

                    s->dba_lengths[ch][seg] = get_bits(gbc, 4);

                    s->dba_values[ch][seg]  = get_bits(gbc, 3);

                }

                /* run last 2 bit allocation stages if new dba values */

                bit_alloc_stages[ch] = FFMAX(bit_alloc_stages[ch], 2);

            }

        }

    } else if (blk == 0) {

        for (ch = 0; ch <= s->channels; ch++) {

            s->dba_mode[ch] = DBA_NONE;

        }

    }



    /* Bit allocation */

    for (ch = !cpl_in_use; ch <= s->channels; ch++) {

        if (bit_alloc_stages[ch] > 2) {

            /* Exponent mapping into PSD and PSD integration */

            ff_ac3_bit_alloc_calc_psd(s->dexps[ch],

                                      s->start_freq[ch], s->end_freq[ch],

                                      s->psd[ch], s->band_psd[ch]);

        }

        if (bit_alloc_stages[ch] > 1) {

            /* Compute excitation function, Compute masking curve, and

               Apply delta bit allocation */

            if (ff_ac3_bit_alloc_calc_mask(&s->bit_alloc_params, s->band_psd[ch],

                                           s->start_freq[ch],  s->end_freq[ch],

                                           s->fast_gain[ch],   (ch == s->lfe_ch),

                                           s->dba_mode[ch],    s->dba_nsegs[ch],

                                           s->dba_offsets[ch], s->dba_lengths[ch],

                                           s->dba_values[ch],  s->mask[ch])) {

                av_log(s->avctx, AV_LOG_ERROR, "error in bit allocation\n");

                return AVERROR_INVALIDDATA;

            }

        }

        if (bit_alloc_stages[ch] > 0) {

            /* Compute bit allocation */

            const uint8_t *bap_tab = s->channel_uses_aht[ch] ?

                                     ff_eac3_hebap_tab : ff_ac3_bap_tab;

            s->ac3dsp.bit_alloc_calc_bap(s->mask[ch], s->psd[ch],

                                      s->start_freq[ch], s->end_freq[ch],

                                      s->snr_offset[ch],

                                      s->bit_alloc_params.floor,

                                      bap_tab, s->bap[ch]);

        }

    }



    /* unused dummy data */

    if (s->skip_syntax && get_bits1(gbc)) {

        int skipl = get_bits(gbc, 9);

        skip_bits_long(gbc, 8 * skipl);

    }



    /* unpack the transform coefficients

       this also uncouples channels if coupling is in use. */

    decode_transform_coeffs(s, blk);



    /* TODO: generate enhanced coupling coordinates and uncouple */



    /* recover coefficients if rematrixing is in use */

    if (s->channel_mode == AC3_CHMODE_STEREO)

        do_rematrixing(s);



    /* apply scaling to coefficients (headroom, dynrng) */

    for (ch = 1; ch <= s->channels; ch++) {

        int audio_channel = 0;

        INTFLOAT gain;

        if (s->channel_mode == AC3_CHMODE_DUALMONO)

            audio_channel = 2-ch;

        if (s->heavy_compression && s->compression_exists[audio_channel])

            gain = s->heavy_dynamic_range[audio_channel];

        else

            gain = s->dynamic_range[audio_channel];



#if USE_FIXED

        scale_coefs(s->transform_coeffs[ch], s->fixed_coeffs[ch], gain, 256);

#else

        if (s->target_level != 0)

          gain = gain * s->level_gain[audio_channel];

        gain *= 1.0 / 4194304.0f;

        s->fmt_conv.int32_to_float_fmul_scalar(s->transform_coeffs[ch],

                                               s->fixed_coeffs[ch], gain, 256);

#endif

    }



    /* apply spectral extension to high frequency bins */

    if (CONFIG_EAC3_DECODER && s->spx_in_use) {

        ff_eac3_apply_spectral_extension(s);

    }



    /* downmix and MDCT. order depends on whether block switching is used for

       any channel in this block. this is because coefficients for the long

       and short transforms cannot be mixed. */

    downmix_output = s->channels != s->out_channels &&

                     !((s->output_mode & AC3_OUTPUT_LFEON) &&

                     s->fbw_channels == s->out_channels);

    if (different_transforms) {

        /* the delay samples have already been downmixed, so we upmix the delay

           samples in order to reconstruct all channels before downmixing. */

        if (s->downmixed) {

            s->downmixed = 0;

            ac3_upmix_delay(s);

        }



        do_imdct(s, s->channels);



        if (downmix_output) {

#if USE_FIXED

            ac3_downmix_c_fixed16(s->outptr, s->downmix_coeffs,

                              s->out_channels, s->fbw_channels, 256);

#else

            ff_ac3dsp_downmix(&s->ac3dsp, s->outptr, s->downmix_coeffs,

                              s->out_channels, s->fbw_channels, 256);

#endif

        }

    } else {

        if (downmix_output) {

            AC3_RENAME(ff_ac3dsp_downmix)(&s->ac3dsp, s->xcfptr + 1, s->downmix_coeffs,

                                          s->out_channels, s->fbw_channels, 256);

        }



        if (downmix_output && !s->downmixed) {

            s->downmixed = 1;

            AC3_RENAME(ff_ac3dsp_downmix)(&s->ac3dsp, s->dlyptr, s->downmix_coeffs,

                                          s->out_channels, s->fbw_channels, 128);

        }



        do_imdct(s, s->out_channels);

    }



    return 0;

}

static void write_header(AVFormatContext *s)

{

    double min_buffer_time = 1.0;

    avio_printf(s->pb, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");

    avio_printf(s->pb, "<MPD\n");

    avio_printf(s->pb, "  xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n");

    avio_printf(s->pb, "  xmlns=\"urn:mpeg:DASH:schema:MPD:2011\"\n");

    avio_printf(s->pb, "  xsi:schemaLocation=\"urn:mpeg:DASH:schema:MPD:2011\"\n");

    avio_printf(s->pb, "  type=\"static\"\n");

    avio_printf(s->pb, "  mediaPresentationDuration=\"PT%gS\"\n",

                get_duration(s));

