int ioinst_handle_tsch(S390CPU *cpu, uint64_t reg1, uint32_t ipb)

{

    CPUS390XState *env = &cpu->env;

    int cssid, ssid, schid, m;

    SubchDev *sch;

    IRB irb;

    uint64_t addr;

    int cc, irb_len;

    uint8_t ar;



    if (ioinst_disassemble_sch_ident(reg1, &m, &cssid, &ssid, &schid)) {

        program_interrupt(env, PGM_OPERAND, 2);

        return -EIO;

    }

    trace_ioinst_sch_id("tsch", cssid, ssid, schid);

    addr = decode_basedisp_s(env, ipb, &ar);

    if (addr & 3) {

        program_interrupt(env, PGM_SPECIFICATION, 2);

        return -EIO;

    }



    sch = css_find_subch(m, cssid, ssid, schid);

    if (sch && css_subch_visible(sch)) {

        cc = css_do_tsch_get_irb(sch, &irb, &irb_len);

    } else {

        cc = 3;

    }

    /* 0 - status pending, 1 - not status pending, 3 - not operational */

    if (cc != 3) {

        if (s390_cpu_virt_mem_write(cpu, addr, ar, &irb, irb_len) != 0) {

            return -EFAULT;

        }

        css_do_tsch_update_subch(sch);

    } else {

        irb_len = sizeof(irb) - sizeof(irb.emw);

        /* Access exceptions have a higher priority than cc3 */

        if (s390_cpu_virt_mem_check_write(cpu, addr, ar, irb_len) != 0) {

            return -EFAULT;

        }

    }



    setcc(cpu, cc);

    return 0;

}

static int lag_decode_arith_plane(LagarithContext *l, uint8_t *dst,

                                  int width, int height, int stride,

                                  const uint8_t *src, int src_size)

{

    int i = 0;

    int read = 0;

    uint32_t length;

    uint32_t offset = 1;

    int esc_count;

    GetBitContext gb;

    lag_rac rac;

    const uint8_t *src_end = src + src_size;



    rac.avctx = l->avctx;

    l->zeros = 0;



    if(src_size < 2)

        return AVERROR_INVALIDDATA;



    esc_count = src[0];

    if (esc_count < 4) {

        length = width * height;

        if(src_size < 5)

            return AVERROR_INVALIDDATA;

        if (esc_count && AV_RL32(src + 1) < length) {

            length = AV_RL32(src + 1);

            offset += 4;

        }



        init_get_bits8(&gb, src + offset, src_size - offset);



        if (lag_read_prob_header(&rac, &gb) < 0)

            return -1;



        ff_lag_rac_init(&rac, &gb, length - stride);



        for (i = 0; i < height; i++)

            read += lag_decode_line(l, &rac, dst + (i * stride), width,

                                    stride, esc_count);



        if (read > length)

            av_log(l->avctx, AV_LOG_WARNING,

                   "Output more bytes than length (%d of %d)\n", read,

                   length);

    } else if (esc_count < 8) {

        esc_count -= 4;

        src ++;

        src_size --;

        if (esc_count > 0) {

            /* Zero run coding only, no range coding. */

            for (i = 0; i < height; i++) {

                int res = lag_decode_zero_run_line(l, dst + (i * stride), src,

                                                   src_end, width, esc_count);

                if (res < 0)

                    return res;

                src += res;

            }

        } else {

            if (src_size < width * height)

                return AVERROR_INVALIDDATA; // buffer not big enough

            /* Plane is stored uncompressed */

            for (i = 0; i < height; i++) {

                memcpy(dst + (i * stride), src, width);

                src += width;

            }

        }

    } else if (esc_count == 0xff) {

        /* Plane is a solid run of given value */

        for (i = 0; i < height; i++)

            memset(dst + i * stride, src[1], width);

        /* Do not apply prediction.

           Note: memset to 0 above, setting first value to src[1]

           and applying prediction gives the same result. */

        return 0;

    } else {

        av_log(l->avctx, AV_LOG_ERROR,

               "Invalid zero run escape code! (%#x)\n", esc_count);

        return -1;

    }



    if (l->avctx->pix_fmt != AV_PIX_FMT_YUV422P) {

        for (i = 0; i < height; i++) {

            lag_pred_line(l, dst, width, stride, i);

            dst += stride;

        }

    } else {

        for (i = 0; i < height; i++) {

            lag_pred_line_yuy2(l, dst, width, stride, i,

                               width == l->avctx->width);

            dst += stride;

        }

    }



    return 0;

}

static ssize_t v9fs_synth_pwritev(FsContext *ctx, V9fsFidOpenState *fs,

                                  const struct iovec *iov,

                                  int iovcnt, off_t offset)

{

    int i, count = 0, wcount;

    V9fsSynthOpenState *synth_open = fs->private;

    V9fsSynthNode *node = synth_open->node;

    if (!node->attr->write) {

        errno = EPERM;

        return -1;

    }

    for (i = 0; i < iovcnt; i++) {

        wcount = node->attr->write(iov[i].iov_base, iov[i].iov_len,

                                   offset, node->private);

        offset += wcount;

        count  += wcount;

        /* If we wrote less than requested. we are done */

        if (wcount < iov[i].iov_len) {

            break;

        }

    }

    return count;

}

