unsigned ff_dxva2_get_surface_index(const AVCodecContext *avctx,

                                    const AVDXVAContext *ctx,

                                    const AVFrame *frame)

{

    void *surface = get_surface(frame);

    unsigned i;



    for (i = 0; i < DXVA_CONTEXT_COUNT(avctx, ctx); i++) {

#if CONFIG_D3D11VA

        if (avctx->pix_fmt == AV_PIX_FMT_D3D11VA_VLD && ctx->d3d11va.surface[i] == surface)

        {

            D3D11_VIDEO_DECODER_OUTPUT_VIEW_DESC viewDesc;

            ID3D11VideoDecoderOutputView_GetDesc(ctx->d3d11va.surface[i], &viewDesc);

            return viewDesc.Texture2D.ArraySlice;

        }

#endif

#if CONFIG_DXVA2

        if (avctx->pix_fmt == AV_PIX_FMT_DXVA2_VLD && ctx->dxva2.surface[i] == surface)

            return i;

#endif

    }



    assert(0);

    return 0;

}

uint32_t HELPER(mul32)(CPUOpenRISCState *env,

                       uint32_t ra, uint32_t rb)

{

    uint64_t result;

    uint32_t high, cy;



    OpenRISCCPU *cpu = openrisc_env_get_cpu(env);



    result = (uint64_t)ra * rb;

    /* regisiers in or32 is 32bit, so 32 is NOT a magic number.

       or64 is not handled in this function, and not implement yet,

       TARGET_LONG_BITS for or64 is 64, it will break this function,

       so, we didn't use TARGET_LONG_BITS here.  */

    high = result >> 32;

    cy = result >> (32 - 1);



    if ((cy & 0x1) == 0x0) {

        if (high == 0x0) {

            return result;

        }

    }



    if ((cy & 0x1) == 0x1) {

        if (high == 0xffffffff) {

            return result;

        }

    }



    cpu->env.sr |= (SR_OV | SR_CY);

    if (cpu->env.sr & SR_OVE) {

        raise_exception(cpu, EXCP_RANGE);

    }



    return result;

}

static int roq_dpcm_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                                 const AVFrame *frame, int *got_packet_ptr)

{

    int i, stereo, data_size, ret;

    const int16_t *in = frame ? (const int16_t *)frame->data[0] : NULL;

    uint8_t *out;

    ROQDPCMContext *context = avctx->priv_data;



    stereo = (avctx->channels == 2);



    if (!in && context->input_frames >= 8)

        return 0;



    if (in && context->input_frames < 8) {

        memcpy(&context->frame_buffer[context->buffered_samples * avctx->channels],

               in, avctx->frame_size * avctx->channels * sizeof(*in));

        context->buffered_samples += avctx->frame_size;

        if (context->input_frames == 0)

            context->first_pts = frame->pts;

        if (context->input_frames < 7) {

            context->input_frames++;

            return 0;




        in = context->frame_buffer;




    if (stereo) {

        context->lastSample[0] &= 0xFF00;

        context->lastSample[1] &= 0xFF00;




    if (context->input_frames == 7 || !in)

        data_size = avctx->channels * context->buffered_samples;

    else

        data_size = avctx->channels * avctx->frame_size;



    if ((ret = ff_alloc_packet2(avctx, avpkt, ROQ_HEADER_SIZE + data_size)))

        return ret;

    out = avpkt->data;



    bytestream_put_byte(&out, stereo ? 0x21 : 0x20);

    bytestream_put_byte(&out, 0x10);

    bytestream_put_le32(&out, data_size);



    if (stereo) {

        bytestream_put_byte(&out, (context->lastSample[1])>>8);

        bytestream_put_byte(&out, (context->lastSample[0])>>8);

    } else

        bytestream_put_le16(&out, context->lastSample[0]);



    /* Write the actual samples */

    for (i = 0; i < data_size; i++)

        *out++ = dpcm_predict(&context->lastSample[i & 1], *in++);



    avpkt->pts      = context->input_frames <= 7 ? context->first_pts : frame->pts;

    avpkt->duration = data_size / avctx->channels;



    context->input_frames++;

    if (!in)

        context->input_frames = FFMAX(context->input_frames, 8);



    *got_packet_ptr = 1;

    return 0;

static int find_optimal_param(uint32_t sum, int n)

{

    int k, k_opt;

    uint32_t nbits[MAX_RICE_PARAM+1];



    k_opt = 0;

    nbits[0] = UINT32_MAX;

    for(k=0; k<=MAX_RICE_PARAM; k++) {

        nbits[k] = rice_encode_count(sum, n, k);

        if(nbits[k] < nbits[k_opt]) {

            k_opt = k;

        }

    }

    return k_opt;

}

