                    fprintf(stderr, "illegal vlc code in ESC2 level=%d\n", level);

                else if((i>62 && i<192) || i>192+63)

                    fprintf(stderr, "run overflow in ESC2 i=%d run=%d level=%d\n", i, run, level);

#endif

                }

            } else {

                /* first escape */

#if MIN_CACHE_BITS < 22

                LAST_SKIP_BITS(re, &s->gb, 1);

                UPDATE_CACHE(re, &s->gb);

#else

                SKIP_BITS(re, &s->gb, 1);

#endif

                GET_RL_VLC(level, run, re, &s->gb, rl_vlc, TEX_VLC_BITS, 2);

                i+= run;

                level = level + rl->max_level[run>>7][(run-1)&63] * qmul;//FIXME opt indexing

                level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

                LAST_SKIP_BITS(re, &s->gb, 1);

#ifdef ERROR_DETAILS

                if(run==66)

                    fprintf(stderr, "illegal vlc code in ESC1 level=%d\n", level);

                else if((i>62 && i<192) || i>192+63)

                    fprintf(stderr, "run overflow in ESC1 i=%d run=%d level=%d\n", i, run, level);

#endif

            }

        } else {

            i+= run;

            level = (level ^ SHOW_SBITS(re, &s->gb, 1)) - SHOW_SBITS(re, &s->gb, 1);

            LAST_SKIP_BITS(re, &s->gb, 1);

#ifdef ERROR_DETAILS

                if(run==66)

                    fprintf(stderr, "illegal vlc code level=%d\n", level);

                else if((i>62 && i<192) || i>192+63)

                    fprintf(stderr, "run overflow i=%d run=%d level=%d\n", i, run, level);

#endif

        }

        if (i > 62){

            i-= 192;

            if(i&(~63)){

                if(i+192 == 64 && level/qmul==-1){

                    fprintf(stderr, "ignoring overflow at %d %d\n", s->mb_x, s->mb_y);

                    break;

                }else{

                    fprintf(stderr, "ac-tex damaged at %d %d\n", s->mb_x, s->mb_y);

                    return -1;

                }

            }



            block[scan_table[i]] = level;

            break;

        }



        block[scan_table[i]] = level;

    }

    CLOSE_READER(re, &s->gb);

  }

 not_coded:

    if (s->mb_intra) {

        mpeg4_pred_ac(s, block, n, dc_pred_dir);

        if (s->ac_pred) {

            i = 63; /* XXX: not optimal */

        }

    }

    if(s->msmpeg4_version==4 && i>0) i=63; //FIXME/XXX optimize

    s->block_last_index[n] = i;



    return 0;

}

static void revert_acfilter(WmallDecodeCtx *s, int tile_size)

{

    int ich, pred, i, j;

    int16_t *filter_coeffs = s->acfilter_coeffs;

    int scaling            = s->acfilter_scaling;

    int order              = s->acfilter_order;



    for (ich = 0; ich < s->num_channels; ich++) {

        int *prevvalues = s->acfilter_prevvalues[ich];

        for (i = 0; i < order; i++) {

            pred = 0;

            for (j = 0; j < order; j++) {

                if (i <= j)

                    pred += filter_coeffs[j] * prevvalues[j - i];

                else

                    pred += s->channel_residues[ich][i - j - 1] * filter_coeffs[j];

            }

            pred >>= scaling;

            s->channel_residues[ich][i] += pred;

        }

        for (i = order; i < tile_size; i++) {

            pred = 0;

            for (j = 0; j < order; j++)

                pred += s->channel_residues[ich][i - j - 1] * filter_coeffs[j];

            pred >>= scaling;

            s->channel_residues[ich][i] += pred;

        }

        for (j = 0; j < order; j++)

            prevvalues[j] = s->channel_residues[ich][tile_size - j - 1];

    }

}

