gen_intermediate_code_internal(CPUState *env, TranslationBlock *tb,

                               int search_pc)

{

	uint16_t *gen_opc_end;

   	uint32_t pc_start;

	unsigned int insn_len;

	int j, lj;

	struct DisasContext *dc = &ctx;

	uint32_t next_page_start;



	pc_start = tb->pc;

	dc->env = env;

	dc->tb = tb;



	gen_opc_end = gen_opc_buf + OPC_MAX_SIZE;



	dc->is_jmp = DISAS_NEXT;

	dc->pc = pc_start;

	dc->singlestep_enabled = env->singlestep_enabled;

	dc->flagx_live = 0;

	dc->flags_x = 0;

	next_page_start = (pc_start & TARGET_PAGE_MASK) + TARGET_PAGE_SIZE;

	lj = -1;

	do

	{

		check_breakpoint(env, dc);

		if (dc->is_jmp == DISAS_JUMP)

			goto done;



		if (search_pc) {

			j = gen_opc_ptr - gen_opc_buf;

			if (lj < j) {

				lj++;

				while (lj < j)

					gen_opc_instr_start[lj++] = 0;

			}

			gen_opc_pc[lj] = dc->pc;

			gen_opc_instr_start[lj] = 1;

		}



		insn_len = cris_decoder(dc);

		STATS(gen_op_exec_insn());

		dc->pc += insn_len;

		if (!dc->flagx_live

		    || (dc->flagx_live &&

			!(dc->cc_op == CC_OP_FLAGS && dc->flags_x))) {

			gen_movl_T0_preg[PR_CCS]();

			gen_op_andl_T0_im(~X_FLAG);

			gen_movl_preg_T0[PR_CCS]();

			dc->flagx_live = 1;

			dc->flags_x = 0;

		}



		/* Check for delayed branches here. If we do it before

		   actually genereating any host code, the simulator will just

		   loop doing nothing for on this program location.  */

		if (dc->delayed_branch) {

			dc->delayed_branch--;

			if (dc->delayed_branch == 0)

			{

				if (dc->bcc == CC_A) {

					gen_op_jmp1 ();

					dc->is_jmp = DISAS_UPDATE;

				}

				else {

					/* Conditional jmp.  */

					gen_op_cc_jmp (dc->delayed_pc, dc->pc);

					dc->is_jmp = DISAS_UPDATE;

				}

			}

		}



		if (env->singlestep_enabled)

			break;

	} while (!dc->is_jmp && gen_opc_ptr < gen_opc_end

		 && dc->pc < next_page_start);



	if (!dc->is_jmp) {

		gen_op_movl_T0_im((long)dc->pc);

		gen_op_movl_pc_T0();

	}



	cris_evaluate_flags (dc);

  done:

	if (__builtin_expect(env->singlestep_enabled, 0)) {

		gen_op_debug();

	} else {

		switch(dc->is_jmp) {

			case DISAS_NEXT:

				gen_goto_tb(dc, 1, dc->pc);

				break;

			default:

			case DISAS_JUMP:

			case DISAS_UPDATE:

				/* indicate that the hash table must be used

				   to find the next TB */

				tcg_gen_exit_tb(0);

				break;

			case DISAS_TB_JUMP:

				/* nothing more to generate */

				break;

		}

	}

	*gen_opc_ptr = INDEX_op_end;

	if (search_pc) {

		j = gen_opc_ptr - gen_opc_buf;

		lj++;

		while (lj <= j)

			gen_opc_instr_start[lj++] = 0;

	} else {

		tb->size = dc->pc - pc_start;

	}



#ifdef DEBUG_DISAS

	if (loglevel & CPU_LOG_TB_IN_ASM) {

		fprintf(logfile, "--------------\n");

		fprintf(logfile, "IN: %s\n", lookup_symbol(pc_start));

		target_disas(logfile, pc_start, dc->pc + 4 - pc_start, 0);

		fprintf(logfile, "\n");

	}

#endif

	return 0;

}

static inline void RENAME(yuvPlanartoyuy2)(const uint8_t *ysrc, const uint8_t *usrc, const uint8_t *vsrc, uint8_t *dst,

	unsigned int width, unsigned int height,

	int lumStride, int chromStride, int dstStride, int vertLumPerChroma)

{

	unsigned y;

	const unsigned chromWidth= width>>1;

	for(y=0; y<height; y++)

	{

#ifdef HAVE_MMX

//FIXME handle 2 lines a once (fewer prefetch, reuse some chrom, but very likely limited by mem anyway)

		asm volatile(

			"xor %%"REG_a", %%"REG_a"	\n\t"

			".balign 16			\n\t"

			"1:				\n\t"

			PREFETCH" 32(%1, %%"REG_a", 2)	\n\t"

			PREFETCH" 32(%2, %%"REG_a")	\n\t"

			PREFETCH" 32(%3, %%"REG_a")	\n\t"

			"movq (%2, %%"REG_a"), %%mm0	\n\t" // U(0)

			"movq %%mm0, %%mm2		\n\t" // U(0)

			"movq (%3, %%"REG_a"), %%mm1	\n\t" // V(0)

			"punpcklbw %%mm1, %%mm0		\n\t" // UVUV UVUV(0)

			"punpckhbw %%mm1, %%mm2		\n\t" // UVUV UVUV(8)



			"movq (%1, %%"REG_a",2), %%mm3	\n\t" // Y(0)

			"movq 8(%1, %%"REG_a",2), %%mm5	\n\t" // Y(8)

			"movq %%mm3, %%mm4		\n\t" // Y(0)

			"movq %%mm5, %%mm6		\n\t" // Y(8)

			"punpcklbw %%mm0, %%mm3		\n\t" // YUYV YUYV(0)

			"punpckhbw %%mm0, %%mm4		\n\t" // YUYV YUYV(4)

			"punpcklbw %%mm2, %%mm5		\n\t" // YUYV YUYV(8)

			"punpckhbw %%mm2, %%mm6		\n\t" // YUYV YUYV(12)



			MOVNTQ" %%mm3, (%0, %%"REG_a", 4)\n\t"

			MOVNTQ" %%mm4, 8(%0, %%"REG_a", 4)\n\t"

			MOVNTQ" %%mm5, 16(%0, %%"REG_a", 4)\n\t"

			MOVNTQ" %%mm6, 24(%0, %%"REG_a", 4)\n\t"



			"add $8, %%"REG_a"		\n\t"

			"cmp %4, %%"REG_a"		\n\t"

			" jb 1b				\n\t"

			::"r"(dst), "r"(ysrc), "r"(usrc), "r"(vsrc), "g" ((long)chromWidth)

			: "%"REG_a

		);

#else



#if defined ARCH_ALPHA && defined HAVE_MVI

#define pl2yuy2(n)					\

	y1 = yc[n];					\

	y2 = yc2[n];					\

	u = uc[n];					\

	v = vc[n];					\

	asm("unpkbw %1, %0" : "=r"(y1) : "r"(y1));	\

	asm("unpkbw %1, %0" : "=r"(y2) : "r"(y2));	\

	asm("unpkbl %1, %0" : "=r"(u) : "r"(u));	\

	asm("unpkbl %1, %0" : "=r"(v) : "r"(v));	\

	yuv1 = (u << 8) + (v << 24);			\

	yuv2 = yuv1 + y2;				\

	yuv1 += y1;					\

	qdst[n] = yuv1;					\

	qdst2[n] = yuv2;



		int i;

		uint64_t *qdst = (uint64_t *) dst;

		uint64_t *qdst2 = (uint64_t *) (dst + dstStride);

		const uint32_t *yc = (uint32_t *) ysrc;

		const uint32_t *yc2 = (uint32_t *) (ysrc + lumStride);

		const uint16_t *uc = (uint16_t*) usrc, *vc = (uint16_t*) vsrc;

		for(i = 0; i < chromWidth; i += 8){

			uint64_t y1, y2, yuv1, yuv2;

			uint64_t u, v;

			/* Prefetch */

			asm("ldq $31,64(%0)" :: "r"(yc));

			asm("ldq $31,64(%0)" :: "r"(yc2));

			asm("ldq $31,64(%0)" :: "r"(uc));

			asm("ldq $31,64(%0)" :: "r"(vc));



			pl2yuy2(0);

			pl2yuy2(1);

			pl2yuy2(2);

			pl2yuy2(3);



			yc += 4;

			yc2 += 4;

			uc += 4;

			vc += 4;

			qdst += 4;

			qdst2 += 4;

		}

		y++;

		ysrc += lumStride;

		dst += dstStride;



#elif __WORDSIZE >= 64

		int i;

		uint64_t *ldst = (uint64_t *) dst;

		const uint8_t *yc = ysrc, *uc = usrc, *vc = vsrc;

		for(i = 0; i < chromWidth; i += 2){

			uint64_t k, l;

			k = yc[0] + (uc[0] << 8) +

			    (yc[1] << 16) + (vc[0] << 24);

			l = yc[2] + (uc[1] << 8) +

			    (yc[3] << 16) + (vc[1] << 24);

			*ldst++ = k + (l << 32);

			yc += 4;

			uc += 2;

			vc += 2;

		}



#else

		int i, *idst = (int32_t *) dst;

		const uint8_t *yc = ysrc, *uc = usrc, *vc = vsrc;

		for(i = 0; i < chromWidth; i++){

#ifdef WORDS_BIGENDIAN

			*idst++ = (yc[0] << 24)+ (uc[0] << 16) +

			    (yc[1] << 8) + (vc[0] << 0);

#else

			*idst++ = yc[0] + (uc[0] << 8) +

			    (yc[1] << 16) + (vc[0] << 24);

#endif

			yc += 2;

			uc++;

			vc++;

		}

#endif

#endif

		if((y&(vertLumPerChroma-1))==(vertLumPerChroma-1) )

		{

			usrc += chromStride;

			vsrc += chromStride;

		}

		ysrc += lumStride;

		dst += dstStride;

	}

#ifdef HAVE_MMX

asm(    EMMS" \n\t"

        SFENCE" \n\t"

        :::"memory");

#endif

}

static void vc1_inv_trans_4x4_dc_c(uint8_t *dest, int linesize, DCTELEM *block)

{

    int i;

    int dc = block[0];

    const uint8_t *cm;

    dc = (17 * dc +  4) >> 3;

    dc = (17 * dc + 64) >> 7;

    cm = ff_cropTbl + MAX_NEG_CROP + dc;

    for(i = 0; i < 4; i++){

        dest[0] = cm[dest[0]];

        dest[1] = cm[dest[1]];

        dest[2] = cm[dest[2]];

        dest[3] = cm[dest[3]];

        dest += linesize;

    }

}

static void read_sbr_noise(SpectralBandReplication *sbr, GetBitContext *gb,

                           SBRData *ch_data, int ch)

{

    int i, j;

    VLC_TYPE (*t_huff)[2], (*f_huff)[2];

    int t_lav, f_lav;

    int delta = (ch == 1 && sbr->bs_coupling == 1) + 1;



    if (sbr->bs_coupling && ch) {

        t_huff = vlc_sbr[T_HUFFMAN_NOISE_BAL_3_0DB].table;

        t_lav  = vlc_sbr_lav[T_HUFFMAN_NOISE_BAL_3_0DB];

        f_huff = vlc_sbr[F_HUFFMAN_ENV_BAL_3_0DB].table;

        f_lav  = vlc_sbr_lav[F_HUFFMAN_ENV_BAL_3_0DB];

    } else {

        t_huff = vlc_sbr[T_HUFFMAN_NOISE_3_0DB].table;

        t_lav  = vlc_sbr_lav[T_HUFFMAN_NOISE_3_0DB];

        f_huff = vlc_sbr[F_HUFFMAN_ENV_3_0DB].table;

        f_lav  = vlc_sbr_lav[F_HUFFMAN_ENV_3_0DB];

    }



#if USE_FIXED

    for (i = 0; i < ch_data->bs_num_noise; i++) {

        if (ch_data->bs_df_noise[i]) {

            for (j = 0; j < sbr->n_q; j++)

                ch_data->noise_facs[i + 1][j].mant = ch_data->noise_facs[i][j].mant + delta * (get_vlc2(gb, t_huff, 9, 2) - t_lav);

        } else {

            ch_data->noise_facs[i + 1][0].mant = delta * get_bits(gb, 5); // bs_noise_start_value_balance or bs_noise_start_value_level

            for (j = 1; j < sbr->n_q; j++)

                ch_data->noise_facs[i + 1][j].mant = ch_data->noise_facs[i + 1][j - 1].mant + delta * (get_vlc2(gb, f_huff, 9, 3) - f_lav);

        }

    }

#else

    for (i = 0; i < ch_data->bs_num_noise; i++) {

        if (ch_data->bs_df_noise[i]) {

            for (j = 0; j < sbr->n_q; j++)

                ch_data->noise_facs[i + 1][j] = ch_data->noise_facs[i][j] + delta * (get_vlc2(gb, t_huff, 9, 2) - t_lav);

        } else {

            ch_data->noise_facs[i + 1][0] = delta * get_bits(gb, 5); // bs_noise_start_value_balance or bs_noise_start_value_level

            for (j = 1; j < sbr->n_q; j++)

                ch_data->noise_facs[i + 1][j] = ch_data->noise_facs[i + 1][j - 1] + delta * (get_vlc2(gb, f_huff, 9, 3) - f_lav);

        }

    }

#endif /* USE_FIXED */



    //assign 0th elements of noise_facs from last elements

    memcpy(ch_data->noise_facs[0], ch_data->noise_facs[ch_data->bs_num_noise],

           sizeof(ch_data->noise_facs[0]));

}

