static int rtsp_read_packet(AVFormatContext *s,

                            AVPacket *pkt)

{

    RTSPState *rt = s->priv_data;

    RTSPStream *rtsp_st;

    int ret, len;

    uint8_t buf[RTP_MAX_PACKET_LENGTH];



    /* get next frames from the same RTP packet */

    if (rt->cur_rtp) {

        ret = rtp_parse_packet(rt->cur_rtp, pkt, NULL, 0);

        if (ret == 0) {

            rt->cur_rtp = NULL;

            return 0;

        } else if (ret == 1) {

            return 0;

        } else {

            rt->cur_rtp = NULL;

        }

    }



    /* read next RTP packet */

 redo:

    switch(rt->protocol) {

    default:

    case RTSP_PROTOCOL_RTP_TCP:

        len = tcp_read_packet(s, &rtsp_st, buf, sizeof(buf));

        break;

    case RTSP_PROTOCOL_RTP_UDP:

    case RTSP_PROTOCOL_RTP_UDP_MULTICAST:

        len = udp_read_packet(s, &rtsp_st, buf, sizeof(buf));

        if (rtsp_st->rtp_ctx)

            rtp_check_and_send_back_rr(rtsp_st->rtp_ctx, len);

        break;

    }

    if (len < 0)

        return AVERROR_IO;

    ret = rtp_parse_packet(rtsp_st->rtp_ctx, pkt, buf, len);

    if (ret < 0)

        goto redo;

    if (ret == 1) {

        /* more packets may follow, so we save the RTP context */

        rt->cur_rtp = rtsp_st->rtp_ctx;

    }

    return 0;

}

static void omap_rfbi_transfer_start(struct omap_dss_s *s)

{

    void *data;

    hwaddr len;

    hwaddr data_addr;

    int pitch;

    static void *bounce_buffer;

    static hwaddr bounce_len;



    if (!s->rfbi.enable || s->rfbi.busy)

        return;



    if (s->rfbi.control & (1 << 1)) {				/* BYPASS */

        /* TODO: in non-Bypass mode we probably need to just assert the

         * DRQ and wait for DMA to write the pixels.  */

        fprintf(stderr, "%s: Bypass mode unimplemented\n", __FUNCTION__);

        return;

    }



    if (!(s->dispc.control & (1 << 11)))			/* RFBIMODE */

        return;

    /* TODO: check that LCD output is enabled in DISPC.  */



    s->rfbi.busy = 1;



    len = s->rfbi.pixels * 2;



    data_addr = s->dispc.l[0].addr[0];

    data = cpu_physical_memory_map(data_addr, &len, 0);

    if (data && len != s->rfbi.pixels * 2) {

        cpu_physical_memory_unmap(data, len, 0, 0);

        data = NULL;

        len = s->rfbi.pixels * 2;

    }

    if (!data) {

        if (len > bounce_len) {

            bounce_buffer = g_realloc(bounce_buffer, len);

        }

        data = bounce_buffer;

        cpu_physical_memory_read(data_addr, data, len);

    }



    /* TODO bpp */

    s->rfbi.pixels = 0;



    /* TODO: negative values */

    pitch = s->dispc.l[0].nx + (s->dispc.l[0].rowinc - 1) / 2;



    if ((s->rfbi.control & (1 << 2)) && s->rfbi.chip[0])

        s->rfbi.chip[0]->block(s->rfbi.chip[0]->opaque, 1, data, len, pitch);

    if ((s->rfbi.control & (1 << 3)) && s->rfbi.chip[1])

        s->rfbi.chip[1]->block(s->rfbi.chip[1]->opaque, 1, data, len, pitch);



    if (data != bounce_buffer) {

        cpu_physical_memory_unmap(data, len, 0, len);

    }



    omap_rfbi_transfer_stop(s);



    /* TODO */

    s->dispc.irqst |= 1;					/* FRAMEDONE */

    omap_dispc_interrupt_update(s);

}

