static CharDriverState* create_eventfd_chr_device(void * opaque, EventNotifier *n,

                                                  int vector)

{

    /* create a event character device based on the passed eventfd */

    IVShmemState *s = opaque;

    CharDriverState * chr;

    int eventfd = event_notifier_get_fd(n);



    chr = qemu_chr_open_eventfd(eventfd);



    if (chr == NULL) {

        fprintf(stderr, "creating eventfd for eventfd %d failed\n", eventfd);

        exit(-1);

    }




    /* if MSI is supported we need multiple interrupts */

    if (ivshmem_has_feature(s, IVSHMEM_MSI)) {

        s->eventfd_table[vector].pdev = &s->dev;

        s->eventfd_table[vector].vector = vector;



        qemu_chr_add_handlers(chr, ivshmem_can_receive, fake_irqfd,

                      ivshmem_event, &s->eventfd_table[vector]);

    } else {

        qemu_chr_add_handlers(chr, ivshmem_can_receive, ivshmem_receive,

                      ivshmem_event, s);

    }



    return chr;



}

static void xics_realize(DeviceState *dev, Error **errp)

{

    XICSState *icp = XICS(dev);

    Error *error = NULL;

    int i;



    if (!icp->nr_servers) {

        error_setg(errp, "Number of servers needs to be greater 0");

        return;

    }



    /* Registration of global state belongs into realize */

    spapr_rtas_register("ibm,set-xive", rtas_set_xive);

    spapr_rtas_register("ibm,get-xive", rtas_get_xive);

    spapr_rtas_register("ibm,int-off", rtas_int_off);

    spapr_rtas_register("ibm,int-on", rtas_int_on);



    spapr_register_hypercall(H_CPPR, h_cppr);

    spapr_register_hypercall(H_IPI, h_ipi);

    spapr_register_hypercall(H_XIRR, h_xirr);

    spapr_register_hypercall(H_XIRR_X, h_xirr_x);

    spapr_register_hypercall(H_EOI, h_eoi);

    spapr_register_hypercall(H_IPOLL, h_ipoll);



    object_property_set_bool(OBJECT(icp->ics), true, "realized", &error);

    if (error) {

        error_propagate(errp, error);

        return;

    }



    for (i = 0; i < icp->nr_servers; i++) {

        object_property_set_bool(OBJECT(&icp->ss[i]), true, "realized", &error);

        if (error) {

            error_propagate(errp, error);

            return;

        }

    }

}

int nbd_trip(BlockDriverState *bs, int csock, off_t size,

             uint64_t dev_offset, uint32_t nbdflags,

             uint8_t *data)

{

    struct nbd_request request;

    struct nbd_reply reply;

    int ret;



    TRACE("Reading request.");



    if (nbd_receive_request(csock, &request) == -1)

        return -1;



    if (request.len > NBD_BUFFER_SIZE) {

        LOG("len (%u) is larger than max len (%u)",

            request.len, NBD_BUFFER_SIZE);

        errno = EINVAL;

        return -1;

    }



    if ((request.from + request.len) < request.from) {

        LOG("integer overflow detected! "

            "you're probably being attacked");

        errno = EINVAL;

        return -1;

    }



    if ((request.from + request.len) > size) {

            LOG("From: %" PRIu64 ", Len: %u, Size: %" PRIu64

            ", Offset: %" PRIu64 "\n",

                    request.from, request.len, (uint64_t)size, dev_offset);

        LOG("requested operation past EOF--bad client?");

        errno = EINVAL;

        return -1;

    }



    TRACE("Decoding type");



    reply.handle = request.handle;

    reply.error = 0;



    switch (request.type & NBD_CMD_MASK_COMMAND) {

    case NBD_CMD_READ:

        TRACE("Request type is READ");



        ret = bdrv_read(bs, (request.from + dev_offset) / 512,

                        data, request.len / 512);

        if (ret < 0) {

            LOG("reading from file failed");

            reply.error = -ret;

            request.len = 0;

        }



        TRACE("Read %u byte(s)", request.len);

        if (nbd_do_send_reply(csock, &reply, data, request.len) < 0)

            return -1;

        break;

    case NBD_CMD_WRITE:

        TRACE("Request type is WRITE");



        TRACE("Reading %u byte(s)", request.len);



        if (read_sync(csock, data, request.len) != request.len) {

            LOG("reading from socket failed");

            errno = EINVAL;

            return -1;

        }



        if (nbdflags & NBD_FLAG_READ_ONLY) {

            TRACE("Server is read-only, return error");

            reply.error = 1;

        } else {

            TRACE("Writing to device");



            ret = bdrv_write(bs, (request.from + dev_offset) / 512,

                             data, request.len / 512);

            if (ret < 0) {

                LOG("writing to file failed");

                reply.error = -ret;

                request.len = 0;

            }



            if (request.type & NBD_CMD_FLAG_FUA) {

                ret = bdrv_flush(bs);

                if (ret < 0) {

                    LOG("flush failed");

                    reply.error = -ret;

                }

            }

        }



        if (nbd_do_send_reply(csock, &reply, NULL, 0) < 0)

            return -1;

        break;

    case NBD_CMD_DISC:

        TRACE("Request type is DISCONNECT");

        errno = 0;

        return 1;

    case NBD_CMD_FLUSH:

        TRACE("Request type is FLUSH");



        ret = bdrv_flush(bs);

        if (ret < 0) {

            LOG("flush failed");

            reply.error = -ret;

        }



        if (nbd_do_send_reply(csock, &reply, NULL, 0) < 0)

            return -1;

        break;

    case NBD_CMD_TRIM:

        TRACE("Request type is TRIM");

        ret = bdrv_discard(bs, (request.from + dev_offset) / 512,

                           request.len / 512);

        if (ret < 0) {

            LOG("discard failed");

            reply.error = -ret;

        }

        if (nbd_do_send_reply(csock, &reply, NULL, 0) < 0)

            return -1;

        break;

    default:

        LOG("invalid request type (%u) received", request.type);

        errno = EINVAL;

        return -1;

    }



    TRACE("Request/Reply complete");



    return 0;

}

static int resample(SwrContext *s, AudioData *out_param, int out_count,

                             const AudioData * in_param, int in_count){

    AudioData in, out, tmp;

    int ret_sum=0;

    int border=0;



    av_assert1(s->in_buffer.ch_count == in_param->ch_count);

    av_assert1(s->in_buffer.planar   == in_param->planar);

    av_assert1(s->in_buffer.fmt      == in_param->fmt);



    tmp=out=*out_param;

    in =  *in_param;



    do{

        int ret, size, consumed;

        if(!s->resample_in_constraint && s->in_buffer_count){

            buf_set(&tmp, &s->in_buffer, s->in_buffer_index);

            ret= s->resampler->multiple_resample(s->resample, &out, out_count, &tmp, s->in_buffer_count, &consumed);

            out_count -= ret;

            ret_sum += ret;

            buf_set(&out, &out, ret);

            s->in_buffer_count -= consumed;

            s->in_buffer_index += consumed;



            if(!in_count)

                break;

            if(s->in_buffer_count <= border){

                buf_set(&in, &in, -s->in_buffer_count);

                in_count += s->in_buffer_count;

                s->in_buffer_count=0;

                s->in_buffer_index=0;

                border = 0;

            }

        }



        if((s->flushed || in_count) && !s->in_buffer_count){

            s->in_buffer_index=0;

            ret= s->resampler->multiple_resample(s->resample, &out, out_count, &in, in_count, &consumed);

            out_count -= ret;

            ret_sum += ret;

            buf_set(&out, &out, ret);

            in_count -= consumed;

            buf_set(&in, &in, consumed);

        }



        //TODO is this check sane considering the advanced copy avoidance below

        size= s->in_buffer_index + s->in_buffer_count + in_count;

        if(   size > s->in_buffer.count

           && s->in_buffer_count + in_count <= s->in_buffer_index){

            buf_set(&tmp, &s->in_buffer, s->in_buffer_index);

            copy(&s->in_buffer, &tmp, s->in_buffer_count);

            s->in_buffer_index=0;

        }else

            if((ret=swri_realloc_audio(&s->in_buffer, size)) < 0)

                return ret;



        if(in_count){

            int count= in_count;

            if(s->in_buffer_count && s->in_buffer_count+2 < count && out_count) count= s->in_buffer_count+2;



            buf_set(&tmp, &s->in_buffer, s->in_buffer_index + s->in_buffer_count);

            copy(&tmp, &in, /*in_*/count);

            s->in_buffer_count += count;

            in_count -= count;

            border += count;

            buf_set(&in, &in, count);

            s->resample_in_constraint= 0;

            if(s->in_buffer_count != count || in_count)

                continue;

        }

        break;

    }while(1);



    s->resample_in_constraint= !!out_count;



    return ret_sum;

}

static bool msi_is_masked(const PCIDevice *dev, unsigned int vector)

{

    uint16_t flags = pci_get_word(dev->config + msi_flags_off(dev));

    uint32_t mask;

    assert(vector < PCI_MSI_VECTORS_MAX);



    if (!(flags & PCI_MSI_FLAGS_MASKBIT)) {

        return false;

    }



    mask = pci_get_long(dev->config +

                        msi_mask_off(dev, flags & PCI_MSI_FLAGS_64BIT));

    return mask & (1U << vector);

}

static void ehci_opreg_write(void *ptr, hwaddr addr,

                             uint64_t val, unsigned size)

{

    EHCIState *s = ptr;

    uint32_t *mmio = s->opreg + (addr >> 2);

    uint32_t old = *mmio;

    int i;



    trace_usb_ehci_opreg_write(addr + s->opregbase, addr2str(addr), val);



    switch (addr) {

    case USBCMD:

        if (val & USBCMD_HCRESET) {

            ehci_reset(s);

            val = s->usbcmd;

            break;

        }



        /* not supporting dynamic frame list size at the moment */

        if ((val & USBCMD_FLS) && !(s->usbcmd & USBCMD_FLS)) {

            fprintf(stderr, "attempt to set frame list size -- value %d\n",

                    (int)val & USBCMD_FLS);

            val &= ~USBCMD_FLS;

        }



        if (val & USBCMD_IAAD) {

            /*

             * Process IAAD immediately, otherwise the Linux IAAD watchdog may

             * trigger and re-use a qh without us seeing the unlink.

             */

            s->async_stepdown = 0;

            qemu_bh_schedule(s->async_bh);

            trace_usb_ehci_doorbell_ring();

        }



        if (((USBCMD_RUNSTOP | USBCMD_PSE | USBCMD_ASE) & val) !=

            ((USBCMD_RUNSTOP | USBCMD_PSE | USBCMD_ASE) & s->usbcmd)) {

            if (s->pstate == EST_INACTIVE) {

                SET_LAST_RUN_CLOCK(s);

            }

            s->usbcmd = val; /* Set usbcmd for ehci_update_halt() */

            ehci_update_halt(s);

            s->async_stepdown = 0;

            qemu_bh_schedule(s->async_bh);

        }

        break;



    case USBSTS:

        val &= USBSTS_RO_MASK;              // bits 6 through 31 are RO

        ehci_clear_usbsts(s, val);          // bits 0 through 5 are R/WC

        val = s->usbsts;

        ehci_update_irq(s);

        break;



    case USBINTR:

        val &= USBINTR_MASK;

        if (ehci_enabled(s) && (USBSTS_FLR & val)) {

            qemu_bh_schedule(s->async_bh);

        }

        break;



    case FRINDEX:

        val &= 0x00003ff8; /* frindex is 14bits and always a multiple of 8 */

        break;



    case CONFIGFLAG:

        val &= 0x1;

        if (val) {

            for(i = 0; i < NB_PORTS; i++)

                handle_port_owner_write(s, i, 0);

        }

        break;



    case PERIODICLISTBASE:

        if (ehci_periodic_enabled(s)) {

            fprintf(stderr,

              "ehci: PERIODIC list base register set while periodic schedule\n"

              "      is enabled and HC is enabled\n");

        }

        break;



    case ASYNCLISTADDR:

        if (ehci_async_enabled(s)) {

            fprintf(stderr,

              "ehci: ASYNC list address register set while async schedule\n"

              "      is enabled and HC is enabled\n");

        }

        break;

    }



    *mmio = val;

    trace_usb_ehci_opreg_change(addr + s->opregbase, addr2str(addr),

                                *mmio, old);

}

static void vfio_bar_quirk_teardown(VFIOPCIDevice *vdev, int nr)

{

    VFIOBAR *bar = &vdev->bars[nr];



    while (!QLIST_EMPTY(&bar->quirks)) {

        VFIOQuirk *quirk = QLIST_FIRST(&bar->quirks);

        memory_region_del_subregion(&bar->region.mem, &quirk->mem);

        object_unparent(OBJECT(&quirk->mem));

        QLIST_REMOVE(quirk, next);

        g_free(quirk);

    }

}

static int blkdebug_open(BlockDriverState *bs, QDict *options, int flags,

                         Error **errp)

{

    BDRVBlkdebugState *s = bs->opaque;

    QemuOpts *opts;

    Error *local_err = NULL;

    const char *config;

    uint64_t align;

    int ret;



    opts = qemu_opts_create(&runtime_opts, NULL, 0, &error_abort);

    qemu_opts_absorb_qdict(opts, options, &local_err);

    if (error_is_set(&local_err)) {

        error_propagate(errp, local_err);

        ret = -EINVAL;

        goto fail;

    }



    /* Read rules from config file or command line options */

    config = qemu_opt_get(opts, "config");

    ret = read_config(s, config, options, errp);

    if (ret) {

        goto fail;

    }



    /* Set initial state */

    s->state = 1;



    /* Open the backing file */

    ret = bdrv_open_image(&bs->file, qemu_opt_get(opts, "x-image"), options, "image",

                          flags, true, false, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        goto fail;

    }



    /* Set request alignment */

    align = qemu_opt_get_size(opts, "align", bs->request_alignment);

    if (align > 0 && align < INT_MAX && !(align & (align - 1))) {

        bs->request_alignment = align;

    } else {

        error_setg(errp, "Invalid alignment");

        ret = -EINVAL;

        goto fail;

    }



    ret = 0;

fail:

    qemu_opts_del(opts);

    return ret;

}

void qemu_aio_init(void)

{

    struct sigaction act;



    aio_initialized = 1;



    sigfillset(&act.sa_mask);

    act.sa_flags = 0; /* do not restart syscalls to interrupt select() */

    act.sa_handler = aio_signal_handler;

    sigaction(aio_sig_num, &act, NULL);



#if defined(__GLIBC__) && defined(__linux__)

    {

        /* XXX: aio thread exit seems to hang on RedHat 9 and this init

           seems to fix the problem. */

        struct aioinit ai;

        memset(&ai, 0, sizeof(ai));

        ai.aio_threads = 1;

        ai.aio_num = 1;

        ai.aio_idle_time = 365 * 100000;

        aio_init(&ai);

    }

#endif

}

static void zynq_init(MachineState *machine)

{

    ram_addr_t ram_size = machine->ram_size;

    const char *cpu_model = machine->cpu_model;

    const char *kernel_filename = machine->kernel_filename;

    const char *kernel_cmdline = machine->kernel_cmdline;

    const char *initrd_filename = machine->initrd_filename;

    ObjectClass *cpu_oc;

    ARMCPU *cpu;

    MemoryRegion *address_space_mem = get_system_memory();

    MemoryRegion *ext_ram = g_new(MemoryRegion, 1);

    MemoryRegion *ocm_ram = g_new(MemoryRegion, 1);

    DeviceState *dev;

    SysBusDevice *busdev;

    qemu_irq pic[64];

    Error *err = NULL;

    int n;



    if (!cpu_model) {

        cpu_model = "cortex-a9";

    }

    cpu_oc = cpu_class_by_name(TYPE_ARM_CPU, cpu_model);



    cpu = ARM_CPU(object_new(object_class_get_name(cpu_oc)));



    /* By default A9 CPUs have EL3 enabled.  This board does not

     * currently support EL3 so the CPU EL3 property is disabled before

     * realization.

     */

    if (object_property_find(OBJECT(cpu), "has_el3", NULL)) {

        object_property_set_bool(OBJECT(cpu), false, "has_el3", &err);

        if (err) {

            error_report_err(err);

            exit(1);

        }

    }



    object_property_set_int(OBJECT(cpu), ZYNQ_BOARD_MIDR, "midr", &err);

    if (err) {

        error_report_err(err);

        exit(1);

    }



    object_property_set_int(OBJECT(cpu), MPCORE_PERIPHBASE, "reset-cbar", &err);

    if (err) {

        error_report_err(err);

        exit(1);

    }

    object_property_set_bool(OBJECT(cpu), true, "realized", &err);

    if (err) {

        error_report_err(err);

        exit(1);

    }



    /* max 2GB ram */

    if (ram_size > 0x80000000) {

        ram_size = 0x80000000;

    }



    /* DDR remapped to address zero.  */

    memory_region_allocate_system_memory(ext_ram, NULL, "zynq.ext_ram",

                                         ram_size);

    memory_region_add_subregion(address_space_mem, 0, ext_ram);



    /* 256K of on-chip memory */

    memory_region_init_ram(ocm_ram, NULL, "zynq.ocm_ram", 256 << 10,

                           &error_abort);

    vmstate_register_ram_global(ocm_ram);

    memory_region_add_subregion(address_space_mem, 0xFFFC0000, ocm_ram);



    DriveInfo *dinfo = drive_get(IF_PFLASH, 0, 0);



    /* AMD */

    pflash_cfi02_register(0xe2000000, NULL, "zynq.pflash", FLASH_SIZE,

                          dinfo ? blk_by_legacy_dinfo(dinfo) : NULL,

                          FLASH_SECTOR_SIZE,

                          FLASH_SIZE/FLASH_SECTOR_SIZE, 1,

                          1, 0x0066, 0x0022, 0x0000, 0x0000, 0x0555, 0x2aa,

                              0);



    dev = qdev_create(NULL, "xilinx,zynq_slcr");

    qdev_init_nofail(dev);

    sysbus_mmio_map(SYS_BUS_DEVICE(dev), 0, 0xF8000000);



    dev = qdev_create(NULL, "a9mpcore_priv");

    qdev_prop_set_uint32(dev, "num-cpu", 1);

    qdev_init_nofail(dev);

    busdev = SYS_BUS_DEVICE(dev);

    sysbus_mmio_map(busdev, 0, MPCORE_PERIPHBASE);

    sysbus_connect_irq(busdev, 0,

                       qdev_get_gpio_in(DEVICE(cpu), ARM_CPU_IRQ));



    for (n = 0; n < 64; n++) {

        pic[n] = qdev_get_gpio_in(dev, n);

    }



    zynq_init_spi_flashes(0xE0006000, pic[58-IRQ_OFFSET], false);

    zynq_init_spi_flashes(0xE0007000, pic[81-IRQ_OFFSET], false);

    zynq_init_spi_flashes(0xE000D000, pic[51-IRQ_OFFSET], true);



    sysbus_create_simple("xlnx,ps7-usb", 0xE0002000, pic[53-IRQ_OFFSET]);

    sysbus_create_simple("xlnx,ps7-usb", 0xE0003000, pic[76-IRQ_OFFSET]);



    sysbus_create_simple("cadence_uart", 0xE0000000, pic[59-IRQ_OFFSET]);

    sysbus_create_simple("cadence_uart", 0xE0001000, pic[82-IRQ_OFFSET]);



    sysbus_create_varargs("cadence_ttc", 0xF8001000,

            pic[42-IRQ_OFFSET], pic[43-IRQ_OFFSET], pic[44-IRQ_OFFSET], NULL);

    sysbus_create_varargs("cadence_ttc", 0xF8002000,

            pic[69-IRQ_OFFSET], pic[70-IRQ_OFFSET], pic[71-IRQ_OFFSET], NULL);



    gem_init(&nd_table[0], 0xE000B000, pic[54-IRQ_OFFSET]);

    gem_init(&nd_table[1], 0xE000C000, pic[77-IRQ_OFFSET]);



    dev = qdev_create(NULL, "generic-sdhci");

    qdev_init_nofail(dev);

    sysbus_mmio_map(SYS_BUS_DEVICE(dev), 0, 0xE0100000);

    sysbus_connect_irq(SYS_BUS_DEVICE(dev), 0, pic[56-IRQ_OFFSET]);



    dev = qdev_create(NULL, "generic-sdhci");

    qdev_init_nofail(dev);

    sysbus_mmio_map(SYS_BUS_DEVICE(dev), 0, 0xE0101000);

    sysbus_connect_irq(SYS_BUS_DEVICE(dev), 0, pic[79-IRQ_OFFSET]);



    dev = qdev_create(NULL, "pl330");

    qdev_prop_set_uint8(dev, "num_chnls",  8);

    qdev_prop_set_uint8(dev, "num_periph_req",  4);

    qdev_prop_set_uint8(dev, "num_events",  16);



    qdev_prop_set_uint8(dev, "data_width",  64);

    qdev_prop_set_uint8(dev, "wr_cap",  8);

    qdev_prop_set_uint8(dev, "wr_q_dep",  16);

    qdev_prop_set_uint8(dev, "rd_cap",  8);

    qdev_prop_set_uint8(dev, "rd_q_dep",  16);

    qdev_prop_set_uint16(dev, "data_buffer_dep",  256);



    qdev_init_nofail(dev);

    busdev = SYS_BUS_DEVICE(dev);

    sysbus_mmio_map(busdev, 0, 0xF8003000);

    sysbus_connect_irq(busdev, 0, pic[45-IRQ_OFFSET]); /* abort irq line */

    for (n = 0; n < 8; ++n) { /* event irqs */

        sysbus_connect_irq(busdev, n + 1, pic[dma_irqs[n] - IRQ_OFFSET]);

    }



    zynq_binfo.ram_size = ram_size;

    zynq_binfo.kernel_filename = kernel_filename;

    zynq_binfo.kernel_cmdline = kernel_cmdline;

    zynq_binfo.initrd_filename = initrd_filename;

    zynq_binfo.nb_cpus = 1;

    zynq_binfo.board_id = 0xd32;

    zynq_binfo.loader_start = 0;

    arm_load_kernel(ARM_CPU(first_cpu), &zynq_binfo);

}

static void spapr_phb_realize(DeviceState *dev, Error **errp)

{

    sPAPRMachineState *spapr = SPAPR_MACHINE(qdev_get_machine());

    SysBusDevice *s = SYS_BUS_DEVICE(dev);

    sPAPRPHBState *sphb = SPAPR_PCI_HOST_BRIDGE(s);

    PCIHostState *phb = PCI_HOST_BRIDGE(s);

    sPAPRPHBClass *info = SPAPR_PCI_HOST_BRIDGE_GET_CLASS(s);

    char *namebuf;

    int i;

    PCIBus *bus;

    uint64_t msi_window_size = 4096;



    if (sphb->index != (uint32_t)-1) {

        hwaddr windows_base;



        if ((sphb->buid != (uint64_t)-1) || (sphb->dma_liobn != (uint32_t)-1)

            || (sphb->mem_win_addr != (hwaddr)-1)

            || (sphb->io_win_addr != (hwaddr)-1)) {

            error_setg(errp, "Either \"index\" or other parameters must"

                       " be specified for PAPR PHB, not both");

            return;

        }



        if (sphb->index > SPAPR_PCI_MAX_INDEX) {

            error_setg(errp, "\"index\" for PAPR PHB is too large (max %u)",

                       SPAPR_PCI_MAX_INDEX);

            return;

        }



        sphb->buid = SPAPR_PCI_BASE_BUID + sphb->index;

        sphb->dma_liobn = SPAPR_PCI_LIOBN(sphb->index, 0);



        windows_base = SPAPR_PCI_WINDOW_BASE

            + sphb->index * SPAPR_PCI_WINDOW_SPACING;

        sphb->mem_win_addr = windows_base + SPAPR_PCI_MMIO_WIN_OFF;

        sphb->io_win_addr = windows_base + SPAPR_PCI_IO_WIN_OFF;

    }



    if (sphb->buid == (uint64_t)-1) {

        error_setg(errp, "BUID not specified for PHB");

        return;

    }



    if (sphb->dma_liobn == (uint32_t)-1) {

        error_setg(errp, "LIOBN not specified for PHB");

        return;

    }



    if (sphb->mem_win_addr == (hwaddr)-1) {

        error_setg(errp, "Memory window address not specified for PHB");

        return;

    }



    if (sphb->io_win_addr == (hwaddr)-1) {

        error_setg(errp, "IO window address not specified for PHB");

        return;

    }



    if (spapr_pci_find_phb(spapr, sphb->buid)) {

        error_setg(errp, "PCI host bridges must have unique BUIDs");

        return;

    }



    sphb->dtbusname = g_strdup_printf("pci@%" PRIx64, sphb->buid);



    namebuf = alloca(strlen(sphb->dtbusname) + 32);



    /* Initialize memory regions */

    sprintf(namebuf, "%s.mmio", sphb->dtbusname);

    memory_region_init(&sphb->memspace, OBJECT(sphb), namebuf, UINT64_MAX);



    sprintf(namebuf, "%s.mmio-alias", sphb->dtbusname);

    memory_region_init_alias(&sphb->memwindow, OBJECT(sphb),

                             namebuf, &sphb->memspace,

                             SPAPR_PCI_MEM_WIN_BUS_OFFSET, sphb->mem_win_size);

    memory_region_add_subregion(get_system_memory(), sphb->mem_win_addr,

                                &sphb->memwindow);



    /* Initialize IO regions */

    sprintf(namebuf, "%s.io", sphb->dtbusname);

    memory_region_init(&sphb->iospace, OBJECT(sphb),

                       namebuf, SPAPR_PCI_IO_WIN_SIZE);



    sprintf(namebuf, "%s.io-alias", sphb->dtbusname);

    memory_region_init_alias(&sphb->iowindow, OBJECT(sphb), namebuf,

                             &sphb->iospace, 0, SPAPR_PCI_IO_WIN_SIZE);

    memory_region_add_subregion(get_system_memory(), sphb->io_win_addr,

                                &sphb->iowindow);



    bus = pci_register_bus(dev, NULL,

                           pci_spapr_set_irq, pci_spapr_map_irq, sphb,

                           &sphb->memspace, &sphb->iospace,

                           PCI_DEVFN(0, 0), PCI_NUM_PINS, TYPE_PCI_BUS);

    phb->bus = bus;

    qbus_set_hotplug_handler(BUS(phb->bus), DEVICE(sphb), NULL);



    /*

     * Initialize PHB address space.

     * By default there will be at least one subregion for default

     * 32bit DMA window.

     * Later the guest might want to create another DMA window

     * which will become another memory subregion.

     */

    sprintf(namebuf, "%s.iommu-root", sphb->dtbusname);



    memory_region_init(&sphb->iommu_root, OBJECT(sphb),

                       namebuf, UINT64_MAX);

    address_space_init(&sphb->iommu_as, &sphb->iommu_root,

                       sphb->dtbusname);



    /*

     * As MSI/MSIX interrupts trigger by writing at MSI/MSIX vectors,

     * we need to allocate some memory to catch those writes coming

     * from msi_notify()/msix_notify().

     * As MSIMessage:addr is going to be the same and MSIMessage:data

     * is going to be a VIRQ number, 4 bytes of the MSI MR will only

     * be used.

     *

     * For KVM we want to ensure that this memory is a full page so that

     * our memory slot is of page size granularity.

     */

#ifdef CONFIG_KVM

    if (kvm_enabled()) {

        msi_window_size = getpagesize();

    }

#endif



    memory_region_init_io(&sphb->msiwindow, NULL, &spapr_msi_ops, spapr,

                          "msi", msi_window_size);

    memory_region_add_subregion(&sphb->iommu_root, SPAPR_PCI_MSI_WINDOW,

                                &sphb->msiwindow);



    pci_setup_iommu(bus, spapr_pci_dma_iommu, sphb);



    pci_bus_set_route_irq_fn(bus, spapr_route_intx_pin_to_irq);



    QLIST_INSERT_HEAD(&spapr->phbs, sphb, list);



    /* Initialize the LSI table */

    for (i = 0; i < PCI_NUM_PINS; i++) {

        uint32_t irq;



        irq = xics_alloc_block(spapr->icp, 0, 1, true, false);

        if (!irq) {

            error_setg(errp, "spapr_allocate_lsi failed");

            return;

        }



        sphb->lsi_table[i].irq = irq;

    }



    /* allocate connectors for child PCI devices */

    if (sphb->dr_enabled) {

        for (i = 0; i < PCI_SLOT_MAX * 8; i++) {

            spapr_dr_connector_new(OBJECT(phb),

                                   SPAPR_DR_CONNECTOR_TYPE_PCI,

                                   (sphb->index << 16) | i);

        }

    }



    if (!info->finish_realize) {

        error_setg(errp, "finish_realize not defined");

        return;

    }



    info->finish_realize(sphb, errp);



    sphb->msi = g_hash_table_new_full(g_int_hash, g_int_equal, g_free, g_free);

}

static int msrle_decode_8_16_24_32(AVCodecContext *avctx, AVPicture *pic,

                                   int depth, GetByteContext *gb)

{

    uint8_t *output, *output_end;

    int p1, p2, line=avctx->height - 1, pos=0, i;

    uint16_t pix16;

    uint32_t pix32;

    unsigned int width= FFABS(pic->linesize[0]) / (depth >> 3);



    output     = pic->data[0] + (avctx->height - 1) * pic->linesize[0];

    output_end = pic->data[0] +  avctx->height      * pic->linesize[0];

    while (bytestream2_get_bytes_left(gb) > 0) {

        p1 = bytestream2_get_byteu(gb);

        if(p1 == 0) { //Escape code

            p2 = bytestream2_get_byte(gb);

            if(p2 == 0) { //End-of-line

                if (--line < 0) {

                    if (bytestream2_get_be16(gb) == 1) { // end-of-picture

                        return 0;

                    } else {

                        av_log(avctx, AV_LOG_ERROR,

                               "Next line is beyond picture bounds (%d bytes left)\n",

                               bytestream2_get_bytes_left(gb));

                        return AVERROR_INVALIDDATA;

                    }

                }

                output = pic->data[0] + line * pic->linesize[0];

                pos = 0;

                continue;

            } else if(p2 == 1) { //End-of-picture

                return 0;

            } else if(p2 == 2) { //Skip

                p1 = bytestream2_get_byte(gb);

                p2 = bytestream2_get_byte(gb);

                line -= p2;

                pos += p1;

                if (line < 0 || pos >= width){

                    av_log(avctx, AV_LOG_ERROR, "Skip beyond picture bounds\n");

                    return -1;

                }

                output = pic->data[0] + line * pic->linesize[0] + pos * (depth >> 3);

                continue;

            }

            // Copy data

            if ((pic->linesize[0] > 0 && output + p2 * (depth >> 3) > output_end) ||

                (pic->linesize[0] < 0 && output + p2 * (depth >> 3) < output_end)) {

                bytestream2_skip(gb, 2 * (depth >> 3));

                continue;

            } else if (bytestream2_get_bytes_left(gb) < p2 * (depth >> 3)) {

                av_log(avctx, AV_LOG_ERROR, "bytestream overrun\n");

                return AVERROR_INVALIDDATA;

            }



            if ((depth == 8) || (depth == 24)) {

                for(i = 0; i < p2 * (depth >> 3); i++) {

                    *output++ = bytestream2_get_byteu(gb);

                }

                // RLE8 copy is actually padded - and runs are not!

                if(depth == 8 && (p2 & 1)) {

                    bytestream2_skip(gb, 1);

                }

            } else if (depth == 16) {

                for(i = 0; i < p2; i++) {

                    *(uint16_t*)output = bytestream2_get_le16u(gb);

                    output += 2;

                }

            } else if (depth == 32) {

                for(i = 0; i < p2; i++) {

                    *(uint32_t*)output = bytestream2_get_le32u(gb);

                    output += 4;

                }

            }

            pos += p2;

        } else { //run of pixels

            uint8_t pix[3]; //original pixel

            if ((pic->linesize[0] > 0 && output + p1 * (depth >> 3) > output_end) ||

                (pic->linesize[0] < 0 && output + p1 * (depth >> 3) < output_end))

                continue;



            switch(depth){

            case  8:

                pix[0] = bytestream2_get_byte(gb);

                for(i = 0; i < p1; i++)

                        *output++ = pix[0];

                break;

            case 16:

                pix16  = bytestream2_get_le16(gb);

                for(i = 0; i < p1; i++) {

                        *(uint16_t*)output = pix16;

                        output += 2;

                }

                break;

            case 24:

                pix[0] = bytestream2_get_byte(gb);

                pix[1] = bytestream2_get_byte(gb);

                pix[2] = bytestream2_get_byte(gb);

                for(i = 0; i < p1; i++) {

                        *output++ = pix[0];

                        *output++ = pix[1];

                        *output++ = pix[2];

                }

                break;

            case 32:

                pix32  = bytestream2_get_le32(gb);

                for(i = 0; i < p1; i++) {

                        *(uint32_t*)output = pix32;

                        output += 4;

                }

                break;

            }

            pos += p1;

        }

    }



    av_log(avctx, AV_LOG_WARNING, "MS RLE warning: no end-of-picture code\n");

    return 0;

}

static void RENAME(SwScale_YV12slice)(unsigned char* srcptr[],int stride[], int srcSliceY ,

			     int srcSliceH, uint8_t* dstptr[], int dststride, int dstbpp,

			     int srcW, int srcH, int dstW, int dstH){





unsigned int lumXInc= (srcW << 16) / dstW;

unsigned int lumYInc= (srcH << 16) / dstH;

unsigned int chrXInc;

unsigned int chrYInc;



static int dstY;



// used to detect a size change

static int oldDstW= -1;

static int oldSrcW= -1;

static int oldDstH= -1;

static int oldSrcH= -1;

static int oldFlags=-1;



static int lastInLumBuf;

static int lastInChrBuf;



int chrDstW, chrDstH;



static int lumBufIndex=0;

static int chrBufIndex=0;



static int firstTime=1;



int widthAlign= dstbpp==12 ? 16 : 8;

if(((dstW + widthAlign-1)&(~(widthAlign-1))) > dststride)

{

	dstW&= ~(widthAlign-1);

	if(firstTime)

		fprintf(stderr, "SwScaler: Warning: dstStride is not a multiple of %d!\n"

				"SwScaler: ->lowering width to compensate, new width=%d\n"

				"SwScaler: ->cannot do aligned memory acesses anymore\n",

				widthAlign, dstW);

}



//printf("%d %d %d %d\n", srcW, srcH, dstW, dstH);

//printf("%d %d %d %d\n", lumXInc, lumYInc, srcSliceY, srcSliceH);



#ifdef HAVE_MMX2

canMMX2BeUsed= (lumXInc <= 0x10000 && (dstW&31)==0 && (srcW&15)==0) ? 1 : 0;

if(!canMMX2BeUsed && lumXInc <= 0x10000 && (srcW&15)==0 && sws_flags==SWS_FAST_BILINEAR)

{

	if(firstTime) //FIXME only if verbose ?

		fprintf(stderr, "SwScaler: output Width is not a multiple of 32 -> no MMX2 scaler\n");

}

#endif



if(firstTime)

{

#if defined (DITHER1XBPP) && defined (HAVE_MMX)

	char *dither= " dithered";

#else

	char *dither= "";

#endif

	if(sws_flags==SWS_FAST_BILINEAR)

		fprintf(stderr, "SwScaler: FAST_BILINEAR scaler ");

	else if(sws_flags==SWS_BILINEAR)

		fprintf(stderr, "SwScaler: BILINEAR scaler ");

	else if(sws_flags==SWS_BICUBIC)

		fprintf(stderr, "SwScaler: BICUBIC scaler ");

	else

		fprintf(stderr, "SwScaler: ehh flags invalid?! ");



	if(dstbpp==15)

		fprintf(stderr, "with%s BGR15 output ", dither);

	else if(dstbpp==16)

		fprintf(stderr, "with%s BGR16 output ", dither);

	else if(dstbpp==24)

		fprintf(stderr, "with BGR24 output ");

	else if(dstbpp==32)

		fprintf(stderr, "with BGR32 output ");

	else if(dstbpp==12)

		fprintf(stderr, "with YV12 output ");

	else

		fprintf(stderr, "without output ");



#ifdef HAVE_MMX2

		fprintf(stderr, "using MMX2\n");

#elif defined (HAVE_3DNOW)

		fprintf(stderr, "using 3DNOW\n");

#elif defined (HAVE_MMX)

		fprintf(stderr, "using MMX\n");

#elif defined (ARCH_X86)

		fprintf(stderr, "using X86 ASM2\n");

#else

		fprintf(stderr, "using C\n");

#endif

}





// match pixel 0 of the src to pixel 0 of dst and match pixel n-2 of src to pixel n-2 of dst

// n-2 is the last chrominance sample available

// this is not perfect, but noone shuld notice the difference, the more correct variant

// would be like the vertical one, but that would require some special code for the

// first and last pixel

if(sws_flags==SWS_FAST_BILINEAR)

{

	if(canMMX2BeUsed) 	lumXInc+= 20;

	else			lumXInc = ((srcW-2)<<16)/(dstW-2) - 20;

}



if(fullUVIpol && !(dstbpp==12)) 	chrXInc= lumXInc>>1, chrDstW= dstW;

else					chrXInc= lumXInc,    chrDstW= dstW>>1;



if(dstbpp==12)	chrYInc= lumYInc,    chrDstH= dstH>>1;

else		chrYInc= lumYInc>>1, chrDstH= dstH;



  // force calculation of the horizontal interpolation of the first line



  if(srcSliceY ==0){

//	printf("dstW %d, srcw %d, mmx2 %d\n", dstW, srcW, canMMX2BeUsed);

	lumBufIndex=0;

	chrBufIndex=0;

	dstY=0;



	//precalculate horizontal scaler filter coefficients

	if(oldDstW!=dstW || oldSrcW!=srcW || oldFlags!=sws_flags)

	{

#ifdef HAVE_MMX

		const int filterAlign=4;

#else

		const int filterAlign=1;

#endif

		oldDstW= dstW; oldSrcW= srcW; oldFlags= sws_flags;



		if(sws_flags != SWS_FAST_BILINEAR)

		{

			RENAME(initFilter)(hLumFilter, hLumFilterPos, &hLumFilterSize, lumXInc,

					   srcW   , dstW   , filterAlign, 1<<14);

			RENAME(initFilter)(hChrFilter, hChrFilterPos, &hChrFilterSize, chrXInc,

					   srcW>>1, chrDstW, filterAlign, 1<<14);

		}



#ifdef HAVE_MMX2

// cant downscale !!!

		if(canMMX2BeUsed && sws_flags == SWS_FAST_BILINEAR)

		{

			initMMX2HScaler(dstW   , lumXInc, funnyYCode);

			initMMX2HScaler(chrDstW, chrXInc, funnyUVCode);

		}

#endif

	} // Init Horizontal stuff



	if(oldDstH!=dstH || oldSrcH!=srcH || oldFlags!=sws_flags)

	{

		int i;

		oldDstH= dstH; oldSrcH= srcH; oldFlags= sws_flags; //FIXME swsflags conflict with x check



		// deallocate pixbufs

		for(i=0; i<vLumBufSize; i++) free(lumPixBuf[i]);

		for(i=0; i<vChrBufSize; i++) free(chrPixBuf[i]);



		RENAME(initFilter)(vLumFilter, vLumFilterPos, &vLumFilterSize, lumYInc,

				srcH   , dstH,    1, (1<<12)-4);

		RENAME(initFilter)(vChrFilter, vChrFilterPos, &vChrFilterSize, chrYInc,

				srcH>>1, chrDstH, 1, (1<<12)-4);



		// Calculate Buffer Sizes so that they wont run out while handling these damn slices

		vLumBufSize= vLumFilterSize; vChrBufSize= vChrFilterSize;

		for(i=0; i<dstH; i++)

		{

			int chrI= i*chrDstH / dstH;

			int nextSlice= MAX(vLumFilterPos[i   ] + vLumFilterSize - 1,

					 ((vChrFilterPos[chrI] + vChrFilterSize - 1)<<1));

			nextSlice&= ~1; // Slices start at even boundaries

			if(vLumFilterPos[i   ] + vLumBufSize < nextSlice)

				vLumBufSize= nextSlice - vLumFilterPos[i   ];

			if(vChrFilterPos[chrI] + vChrBufSize < (nextSlice>>1))

				vChrBufSize= (nextSlice>>1) - vChrFilterPos[chrI];

		}



		// allocate pixbufs (we use dynamic allocation because otherwise we would need to

		// allocate several megabytes to handle all possible cases)

		for(i=0; i<vLumBufSize; i++)

			lumPixBuf[i]= lumPixBuf[i+vLumBufSize]= (uint16_t*)memalign(8, 4000);

		for(i=0; i<vChrBufSize; i++)

			chrPixBuf[i]= chrPixBuf[i+vChrBufSize]= (uint16_t*)memalign(8, 8000);



		//try to avoid drawing green stuff between the right end and the stride end

		for(i=0; i<vLumBufSize; i++) memset(lumPixBuf[i], 0, 4000);

		for(i=0; i<vChrBufSize; i++) memset(chrPixBuf[i], 64, 8000);



#ifdef HAVE_MMX

		// pack filter data for mmx code

		for(i=0; i<vLumFilterSize*dstH; i++)

			lumMmxFilter[4*i]=lumMmxFilter[4*i+1]=lumMmxFilter[4*i+2]=lumMmxFilter[4*i+3]=

				vLumFilter[i];



		for(i=0; i<vChrFilterSize*chrDstH; i++)

			chrMmxFilter[4*i]=chrMmxFilter[4*i+1]=chrMmxFilter[4*i+2]=chrMmxFilter[4*i+3]=

				vChrFilter[i];

#endif

	}



	lastInLumBuf= -1;

	lastInChrBuf= -1;

  } // if(firstLine)



	for(;dstY < dstH; dstY++){

		unsigned char *dest =dstptr[0]+dststride*dstY;

		unsigned char *uDest=dstptr[1]+(dststride>>1)*(dstY>>1);

		unsigned char *vDest=dstptr[2]+(dststride>>1)*(dstY>>1);

		const int chrDstY= dstbpp==12 ? (dstY>>1) : dstY;



		const int firstLumSrcY= vLumFilterPos[dstY]; //First line needed as input

		const int firstChrSrcY= vChrFilterPos[chrDstY]; //First line needed as input

		const int lastLumSrcY= firstLumSrcY + vLumFilterSize -1; // Last line needed as input

		const int lastChrSrcY= firstChrSrcY + vChrFilterSize -1; // Last line needed as input



		if(sws_flags == SWS_FAST_BILINEAR)

		{

			//handle holes

			if(firstLumSrcY > lastInLumBuf) lastInLumBuf= firstLumSrcY-1;

			if(firstChrSrcY > lastInChrBuf) lastInChrBuf= firstChrSrcY-1;

		}



		ASSERT(firstLumSrcY >= lastInLumBuf - vLumBufSize + 1)

		ASSERT(firstChrSrcY >= lastInChrBuf - vChrBufSize + 1)



		// Do we have enough lines in this slice to output the dstY line

		if(lastLumSrcY < srcSliceY + srcSliceH && lastChrSrcY < ((srcSliceY + srcSliceH)>>1))

		{

			//Do horizontal scaling

			while(lastInLumBuf < lastLumSrcY)

			{

				uint8_t *src= srcptr[0]+(lastInLumBuf + 1 - srcSliceY)*stride[0];

				lumBufIndex++;

				ASSERT(lumBufIndex < 2*vLumBufSize)

				ASSERT(lastInLumBuf + 1 - srcSliceY < srcSliceH)

				ASSERT(lastInLumBuf + 1 - srcSliceY >= 0)

//				printf("%d %d\n", lumBufIndex, vLumBufSize);

				RENAME(hyscale)(lumPixBuf[ lumBufIndex ], dstW, src, srcW, lumXInc);

				lastInLumBuf++;

			}

			while(lastInChrBuf < lastChrSrcY)

			{

				uint8_t *src1= srcptr[1]+(lastInChrBuf + 1 - (srcSliceY>>1))*stride[1];

				uint8_t *src2= srcptr[2]+(lastInChrBuf + 1 - (srcSliceY>>1))*stride[2];

				chrBufIndex++;

				ASSERT(chrBufIndex < 2*vChrBufSize)

				ASSERT(lastInChrBuf + 1 - (srcSliceY>>1) < (srcSliceH>>1))

				ASSERT(lastInChrBuf + 1 - (srcSliceY>>1) >= 0)

				RENAME(hcscale)(chrPixBuf[ chrBufIndex ], chrDstW, src1, src2, srcW>>1, chrXInc);

				lastInChrBuf++;

			}

			//wrap buf index around to stay inside the ring buffer

			if(lumBufIndex >= vLumBufSize ) lumBufIndex-= vLumBufSize;

			if(chrBufIndex >= vChrBufSize ) chrBufIndex-= vChrBufSize;

		}

		else // not enough lines left in this slice -> load the rest in the buffer

		{

/*		printf("%d %d Last:%d %d LastInBuf:%d %d Index:%d %d Y:%d FSize: %d %d BSize: %d %d\n",

			firstChrSrcY,firstLumSrcY,lastChrSrcY,lastLumSrcY,

			lastInChrBuf,lastInLumBuf,chrBufIndex,lumBufIndex,dstY,vChrFilterSize,vLumFilterSize,

			vChrBufSize, vLumBufSize);

*/

			//Do horizontal scaling

			while(lastInLumBuf+1 < srcSliceY + srcSliceH)

			{

				uint8_t *src= srcptr[0]+(lastInLumBuf + 1 - srcSliceY)*stride[0];

				lumBufIndex++;

				ASSERT(lumBufIndex < 2*vLumBufSize)

				ASSERT(lastInLumBuf + 1 - srcSliceY < srcSliceH)

				ASSERT(lastInLumBuf + 1 - srcSliceY >= 0)

				RENAME(hyscale)(lumPixBuf[ lumBufIndex ], dstW, src, srcW, lumXInc);

				lastInLumBuf++;

			}

			while(lastInChrBuf+1 < ((srcSliceY + srcSliceH)>>1))

			{

				uint8_t *src1= srcptr[1]+(lastInChrBuf + 1 - (srcSliceY>>1))*stride[1];

				uint8_t *src2= srcptr[2]+(lastInChrBuf + 1 - (srcSliceY>>1))*stride[2];

				chrBufIndex++;

				ASSERT(chrBufIndex < 2*vChrBufSize)

				ASSERT(lastInChrBuf + 1 - (srcSliceY>>1) < (srcSliceH>>1))

				ASSERT(lastInChrBuf + 1 - (srcSliceY>>1) >= 0)

				RENAME(hcscale)(chrPixBuf[ chrBufIndex ], chrDstW, src1, src2, srcW>>1, chrXInc);

				lastInChrBuf++;

			}

			//wrap buf index around to stay inside the ring buffer

			if(lumBufIndex >= vLumBufSize ) lumBufIndex-= vLumBufSize;

			if(chrBufIndex >= vChrBufSize ) chrBufIndex-= vChrBufSize;

			break; //we cant output a dstY line so lets try with the next slice

		}



#ifdef HAVE_MMX

		b5Dither= dither8[dstY&1];

		g6Dither= dither4[dstY&1];

		g5Dither= dither8[dstY&1];

		r5Dither= dither8[(dstY+1)&1];

#endif



		if(dstbpp==12) //YV12

		{

			if(dstY&1) uDest=vDest= NULL; //FIXME split functions in lumi / chromi

			if(vLumFilterSize == 1 && vChrFilterSize == 1) // Unscaled YV12

			{

				int16_t *lumBuf = lumPixBuf[0];

				int16_t *chrBuf= chrPixBuf[0];

				RENAME(yuv2yuv1)(lumBuf, chrBuf, dest, uDest, vDest, dstW);

			}

			else //General YV12

			{

				int16_t **lumSrcPtr= lumPixBuf + lumBufIndex + firstLumSrcY - lastInLumBuf + vLumBufSize;

				int16_t **chrSrcPtr= chrPixBuf + chrBufIndex + firstChrSrcY - lastInChrBuf + vChrBufSize;

				RENAME(yuv2yuvX)(

					vLumFilter+dstY*vLumFilterSize     , lumSrcPtr, vLumFilterSize,

					vChrFilter+(dstY>>1)*vChrFilterSize, chrSrcPtr, vChrFilterSize,

					dest, uDest, vDest, dstW,

					lumMmxFilter+dstY*vLumFilterSize*4, chrMmxFilter+(dstY>>1)*vChrFilterSize*4);

			}

		}

		else

		{

			int16_t **lumSrcPtr= lumPixBuf + lumBufIndex + firstLumSrcY - lastInLumBuf + vLumBufSize;

			int16_t **chrSrcPtr= chrPixBuf + chrBufIndex + firstChrSrcY - lastInChrBuf + vChrBufSize;



			ASSERT(lumSrcPtr + vLumFilterSize - 1 < lumPixBuf + vLumBufSize*2);

			ASSERT(chrSrcPtr + vChrFilterSize - 1 < chrPixBuf + vChrBufSize*2);

			if(vLumFilterSize == 1 && vChrFilterSize == 2) //Unscaled RGB

			{

				int chrAlpha= vChrFilter[2*dstY+1];



				RENAME(yuv2rgb1)(*lumSrcPtr, *chrSrcPtr, *(chrSrcPtr+1),

						 dest, dstW, chrAlpha, dstbpp);

			}

			else if(vLumFilterSize == 2 && vChrFilterSize == 2) //BiLinear Upscale RGB

			{

				int lumAlpha= vLumFilter[2*dstY+1];

				int chrAlpha= vChrFilter[2*dstY+1];



				RENAME(yuv2rgb2)(*lumSrcPtr, *(lumSrcPtr+1), *chrSrcPtr, *(chrSrcPtr+1),

						 dest, dstW, lumAlpha, chrAlpha, dstbpp);

			}

			else //General RGB

			{

				RENAME(yuv2rgbX)(

					vLumFilter+dstY*vLumFilterSize, lumSrcPtr, vLumFilterSize,

					vChrFilter+dstY*vChrFilterSize, chrSrcPtr, vChrFilterSize,

					dest, dstW, dstbpp,

					lumMmxFilter+dstY*vLumFilterSize*4, chrMmxFilter+dstY*vChrFilterSize*4);

			}

		}

	}



#ifdef HAVE_MMX

	__asm __volatile(SFENCE:::"memory");

	__asm __volatile(EMMS:::"memory");

#endif

	firstTime=0;

}

void ff_mpeg1_encode_picture_header(MpegEncContext *s, int picture_number)

{

    AVFrameSideData *side_data;

    mpeg1_encode_sequence_header(s);



    /* mpeg1 picture header */

    put_header(s, PICTURE_START_CODE);

    /* temporal reference */



    // RAL: s->picture_number instead of s->fake_picture_number

    put_bits(&s->pb, 10,

             (s->picture_number - s->gop_picture_number) & 0x3ff);

    put_bits(&s->pb, 3, s->pict_type);



    s->vbv_delay_ptr = s->pb.buf + put_bits_count(&s->pb) / 8;

    put_bits(&s->pb, 16, 0xFFFF);               /* vbv_delay */



    // RAL: Forward f_code also needed for B-frames

    if (s->pict_type == AV_PICTURE_TYPE_P ||

        s->pict_type == AV_PICTURE_TYPE_B) {

        put_bits(&s->pb, 1, 0);                 /* half pel coordinates */

        if (s->codec_id == AV_CODEC_ID_MPEG1VIDEO)

            put_bits(&s->pb, 3, s->f_code);     /* forward_f_code */

        else

            put_bits(&s->pb, 3, 7);             /* forward_f_code */

    }



    // RAL: Backward f_code necessary for B-frames

    if (s->pict_type == AV_PICTURE_TYPE_B) {

        put_bits(&s->pb, 1, 0);                 /* half pel coordinates */

        if (s->codec_id == AV_CODEC_ID_MPEG1VIDEO)

            put_bits(&s->pb, 3, s->b_code);     /* backward_f_code */

        else

            put_bits(&s->pb, 3, 7);             /* backward_f_code */

    }



    put_bits(&s->pb, 1, 0);                     /* extra bit picture */



    s->frame_pred_frame_dct = 1;

    if (s->codec_id == AV_CODEC_ID_MPEG2VIDEO) {

        put_header(s, EXT_START_CODE);

        put_bits(&s->pb, 4, 8);                 /* pic ext */

        if (s->pict_type == AV_PICTURE_TYPE_P ||

            s->pict_type == AV_PICTURE_TYPE_B) {

            put_bits(&s->pb, 4, s->f_code);

            put_bits(&s->pb, 4, s->f_code);

        } else {

            put_bits(&s->pb, 8, 255);

        }

        if (s->pict_type == AV_PICTURE_TYPE_B) {

            put_bits(&s->pb, 4, s->b_code);

            put_bits(&s->pb, 4, s->b_code);

        } else {

            put_bits(&s->pb, 8, 255);

        }

        put_bits(&s->pb, 2, s->intra_dc_precision);



        assert(s->picture_structure == PICT_FRAME);

        put_bits(&s->pb, 2, s->picture_structure);

        if (s->progressive_sequence)

            put_bits(&s->pb, 1, 0);             /* no repeat */

        else

            put_bits(&s->pb, 1, s->current_picture_ptr->f.top_field_first);

        /* XXX: optimize the generation of this flag with entropy measures */

        s->frame_pred_frame_dct = s->progressive_sequence;



        put_bits(&s->pb, 1, s->frame_pred_frame_dct);

        put_bits(&s->pb, 1, s->concealment_motion_vectors);

        put_bits(&s->pb, 1, s->q_scale_type);

        put_bits(&s->pb, 1, s->intra_vlc_format);

        put_bits(&s->pb, 1, s->alternate_scan);

        put_bits(&s->pb, 1, s->repeat_first_field);

        s->progressive_frame = s->progressive_sequence;

        /* chroma_420_type */

        put_bits(&s->pb, 1, s->chroma_format ==

                            CHROMA_420 ? s->progressive_frame : 0);

        put_bits(&s->pb, 1, s->progressive_frame);

        put_bits(&s->pb, 1, 0);                 /* composite_display_flag */

    }

    if (s->scan_offset) {

        int i;



        put_header(s, USER_START_CODE);

        for (i = 0; i < sizeof(svcd_scan_offset_placeholder); i++)

            put_bits(&s->pb, 8, svcd_scan_offset_placeholder[i]);

    }

    side_data = av_frame_get_side_data(&s->current_picture_ptr->f,

                                       AV_FRAME_DATA_STEREO3D);

    if (side_data) {

        AVStereo3D *stereo = (AVStereo3D *)side_data->data;

        uint8_t fpa_type;



        switch (stereo->type) {

        case AV_STEREO3D_SIDEBYSIDE:

            fpa_type = 0x03;

            break;

        case AV_STEREO3D_TOPBOTTOM:

            fpa_type = 0x04;

            break;

        case AV_STEREO3D_2D:

            fpa_type = 0x08;

            break;

        case AV_STEREO3D_SIDEBYSIDE_QUINCUNX:

            fpa_type = 0x23;

            break;

        default:

            fpa_type = 0;

            break;

        }



        if (fpa_type != 0) {

            put_header(s, USER_START_CODE);

            put_bits(&s->pb, 8, 'J');   // S3D_video_format_signaling_identifier

            put_bits(&s->pb, 8, 'P');

            put_bits(&s->pb, 8, '3');

            put_bits(&s->pb, 8, 'D');

            put_bits(&s->pb, 8, 0x03);  // S3D_video_format_length



            put_bits(&s->pb, 1, 1);     // reserved_bit

            put_bits(&s->pb, 7, fpa_type); // S3D_video_format_type

            put_bits(&s->pb, 8, 0x04);  // reserved_data[0]

            put_bits(&s->pb, 8, 0xFF);  // reserved_data[1]

        }

    }



    s->mb_y = 0;

    ff_mpeg1_encode_slice_header(s);

}

