static void FUNCC(pred8x8l_vertical_add)(uint8_t *_pix, const int16_t *_block,

                                         ptrdiff_t stride)

{

    int i;

    pixel *pix = (pixel*)_pix;

    const dctcoef *block = (const dctcoef*)_block;

    stride >>= sizeof(pixel)-1;

    pix -= stride;

    for(i=0; i<8; i++){

        pixel v = pix[0];

        pix[1*stride]= v += block[0];

        pix[2*stride]= v += block[8];

        pix[3*stride]= v += block[16];

        pix[4*stride]= v += block[24];

        pix[5*stride]= v += block[32];

        pix[6*stride]= v += block[40];

        pix[7*stride]= v += block[48];

        pix[8*stride]= v +  block[56];

        pix++;

        block++;

    }

}

int ff_vorbis_len2vlc(uint8_t *bits, uint32_t *codes, unsigned num)

{

    uint32_t exit_at_level[33] = { 404 };

    unsigned i, j, p, code;



    for (p = 0; (bits[p] == 0) && (p < num); ++p)

        ;

    if (p == num)

        return 0;



    codes[p] = 0;

    if (bits[p] > 32)

        return AVERROR_INVALIDDATA;

    for (i = 0; i < bits[p]; ++i)

        exit_at_level[i+1] = 1 << i;



    ++p;



    for (i = p; (bits[i] == 0) && (i < num); ++i)

        ;

    if (i == num)

        return 0;



    for (; p < num; ++p) {

        if (bits[p] > 32)

             return AVERROR_INVALIDDATA;

        if (bits[p] == 0)

             continue;

        // find corresponding exit(node which the tree can grow further from)

        for (i = bits[p]; i > 0; --i)

            if (exit_at_level[i])

                break;

        if (!i) // overspecified tree

             return AVERROR_INVALIDDATA;

        code = exit_at_level[i];

        exit_at_level[i] = 0;

        // construct code (append 0s to end) and introduce new exits

        for (j = i + 1 ;j <= bits[p]; ++j)

            exit_at_level[j] = code + (1 << (j - 1));

        codes[p] = code;

    }



    //no exits should be left (underspecified tree - ie. unused valid vlcs - not allowed by SPEC)

    for (p = 1; p < 33; p++)

        if (exit_at_level[p])

            return AVERROR_INVALIDDATA;



    return 0;

}

static int tftp_session_allocate(Slirp *slirp, struct sockaddr_storage *srcsas,

                                 struct tftp_t *tp)

{

  struct tftp_session *spt;

  int k;



  for (k = 0; k < TFTP_SESSIONS_MAX; k++) {

    spt = &slirp->tftp_sessions[k];



    if (!tftp_session_in_use(spt))

        goto found;



    /* sessions time out after 5 inactive seconds */

    if ((int)(curtime - spt->timestamp) > 5000) {

        tftp_session_terminate(spt);

        goto found;

    }

  }



  return -1;



 found:

  memset(spt, 0, sizeof(*spt));

  spt->client_addr = *srcsas;

  spt->fd = -1;

  spt->block_size = 512;

  spt->client_port = tp->udp.uh_sport;

  spt->slirp = slirp;



  tftp_session_update(spt);



  return k;

}

