static void implicit_weight_table(const H264Context *h, H264SliceContext *sl, int field)

{

    int ref0, ref1, i, cur_poc, ref_start, ref_count0, ref_count1;



    for (i = 0; i < 2; i++) {

        sl->luma_weight_flag[i]   = 0;

        sl->chroma_weight_flag[i] = 0;

    }



    if (field < 0) {

        if (h->picture_structure == PICT_FRAME) {

            cur_poc = h->cur_pic_ptr->poc;

        } else {

            cur_poc = h->cur_pic_ptr->field_poc[h->picture_structure - 1];

        }

        if (sl->ref_count[0] == 1 && sl->ref_count[1] == 1 && !FRAME_MBAFF(h) &&

            sl->ref_list[0][0].poc + sl->ref_list[1][0].poc == 2 * cur_poc) {

            sl->use_weight        = 0;

            sl->use_weight_chroma = 0;

            return;

        }

        ref_start  = 0;

        ref_count0 = sl->ref_count[0];

        ref_count1 = sl->ref_count[1];

    } else {

        cur_poc    = h->cur_pic_ptr->field_poc[field];

        ref_start  = 16;

        ref_count0 = 16 + 2 * sl->ref_count[0];

        ref_count1 = 16 + 2 * sl->ref_count[1];

    }



    sl->use_weight               = 2;

    sl->use_weight_chroma        = 2;

    sl->luma_log2_weight_denom   = 5;

    sl->chroma_log2_weight_denom = 5;



    for (ref0 = ref_start; ref0 < ref_count0; ref0++) {

        int poc0 = sl->ref_list[0][ref0].poc;

        for (ref1 = ref_start; ref1 < ref_count1; ref1++) {

            int w = 32;

            if (!sl->ref_list[0][ref0].parent->long_ref && !sl->ref_list[1][ref1].parent->long_ref) {

                int poc1 = sl->ref_list[1][ref1].poc;

                int td   = av_clip_int8(poc1 - poc0);

                if (td) {

                    int tb = av_clip_int8(cur_poc - poc0);

                    int tx = (16384 + (FFABS(td) >> 1)) / td;

                    int dist_scale_factor = (tb * tx + 32) >> 8;

                    if (dist_scale_factor >= -64 && dist_scale_factor <= 128)

                        w = 64 - dist_scale_factor;

                }

            }

            if (field < 0) {

                sl->implicit_weight[ref0][ref1][0] =

                sl->implicit_weight[ref0][ref1][1] = w;

            } else {

                sl->implicit_weight[ref0][ref1][field] = w;

            }

        }

    }

}

int inet_connect_opts(QemuOpts *opts)

{

    struct addrinfo ai,*res,*e;

    const char *addr;

    const char *port;

    char uaddr[INET6_ADDRSTRLEN+1];

    char uport[33];

    int sock,rc;



    memset(&ai,0, sizeof(ai));

    ai.ai_flags = AI_CANONNAME | AI_ADDRCONFIG;

    ai.ai_family = PF_UNSPEC;

    ai.ai_socktype = SOCK_STREAM;



    addr = qemu_opt_get(opts, "host");

    port = qemu_opt_get(opts, "port");

    if (addr == NULL || port == NULL) {

        fprintf(stderr, "inet_connect: host and/or port not specified\n");

        return -1;

    }



    if (qemu_opt_get_bool(opts, "ipv4", 0))

        ai.ai_family = PF_INET;

    if (qemu_opt_get_bool(opts, "ipv6", 0))

        ai.ai_family = PF_INET6;



    /* lookup */

    if (0 != (rc = getaddrinfo(addr, port, &ai, &res))) {

        fprintf(stderr,"getaddrinfo(%s,%s): %s\n", addr, port,

                gai_strerror(rc));

	return -1;

    }

    if (sockets_debug)

        inet_print_addrinfo(__FUNCTION__, res);



    for (e = res; e != NULL; e = e->ai_next) {

        if (getnameinfo((struct sockaddr*)e->ai_addr,e->ai_addrlen,

                            uaddr,INET6_ADDRSTRLEN,uport,32,

                            NI_NUMERICHOST | NI_NUMERICSERV) != 0) {

            fprintf(stderr,"%s: getnameinfo: oops\n", __FUNCTION__);

            continue;

        }

        sock = socket(e->ai_family, e->ai_socktype, e->ai_protocol);

        if (sock < 0) {

            fprintf(stderr,"%s: socket(%s): %s\n", __FUNCTION__,

            inet_strfamily(e->ai_family), strerror(errno));

            continue;

        }

        setsockopt(sock,SOL_SOCKET,SO_REUSEADDR,(void*)&on,sizeof(on));



        /* connect to peer */

        if (connect(sock,e->ai_addr,e->ai_addrlen) < 0) {

            if (sockets_debug || NULL == e->ai_next)

                fprintf(stderr, "%s: connect(%s,%s,%s,%s): %s\n", __FUNCTION__,

                        inet_strfamily(e->ai_family),

                        e->ai_canonname, uaddr, uport, strerror(errno));

            closesocket(sock);

            continue;

        }

        if (sockets_debug)

            fprintf(stderr, "%s: connect(%s,%s,%s,%s): OK\n", __FUNCTION__,

                    inet_strfamily(e->ai_family),

                    e->ai_canonname, uaddr, uport);

        freeaddrinfo(res);

        return sock;

    }

    freeaddrinfo(res);

    return -1;

}

