AVBufferRef *av_buffer_pool_get(AVBufferPool *pool)

{

    AVBufferRef *ret;

    BufferPoolEntry *buf;



    /* check whether the pool is empty */

    buf = get_pool(pool);

    if (!buf)

        return pool_alloc_buffer(pool);



    /* keep the first entry, return the rest of the list to the pool */

    add_to_pool(buf->next);

    buf->next = NULL;



    ret = av_buffer_create(buf->data, pool->size, pool_release_buffer,

                           buf, 0);

    if (!ret) {

        add_to_pool(buf);

        return NULL;

    }

    avpriv_atomic_int_add_and_fetch(&pool->refcount, 1);



    return ret;

}

static void QEMU_NORETURN force_sig(int target_sig)

{

    CPUState *cpu = thread_cpu;

    CPUArchState *env = cpu->env_ptr;

    TaskState *ts = (TaskState *)cpu->opaque;

    int host_sig, core_dumped = 0;

    struct sigaction act;



    host_sig = target_to_host_signal(target_sig);

    trace_user_force_sig(env, target_sig, host_sig);

    gdb_signalled(env, target_sig);



    /* dump core if supported by target binary format */

    if (core_dump_signal(target_sig) && (ts->bprm->core_dump != NULL)) {

        stop_all_tasks();

        core_dumped =

            ((*ts->bprm->core_dump)(target_sig, env) == 0);

    }

    if (core_dumped) {

        /* we already dumped the core of target process, we don't want

         * a coredump of qemu itself */

        struct rlimit nodump;

        getrlimit(RLIMIT_CORE, &nodump);

        nodump.rlim_cur=0;

        setrlimit(RLIMIT_CORE, &nodump);

        (void) fprintf(stderr, "qemu: uncaught target signal %d (%s) - %s\n",

            target_sig, strsignal(host_sig), "core dumped" );

    }



    /* The proper exit code for dying from an uncaught signal is

     * -<signal>.  The kernel doesn't allow exit() or _exit() to pass

     * a negative value.  To get the proper exit code we need to

     * actually die from an uncaught signal.  Here the default signal

     * handler is installed, we send ourself a signal and we wait for

     * it to arrive. */

    sigfillset(&act.sa_mask);

    act.sa_handler = SIG_DFL;

    act.sa_flags = 0;

    sigaction(host_sig, &act, NULL);



    /* For some reason raise(host_sig) doesn't send the signal when

     * statically linked on x86-64. */

    kill(getpid(), host_sig);



    /* Make sure the signal isn't masked (just reuse the mask inside

    of act) */

    sigdelset(&act.sa_mask, host_sig);

    sigsuspend(&act.sa_mask);



    /* unreachable */

    abort();

}

static int scale_vector(int16_t *dst, const int16_t *vector, int length)

{

    int bits, max = 0;

    int i;



    for (i = 0; i < length; i++)

        max |= FFABS(vector[i]);



    bits  = normalize_bits(max, 15);



    if (bits == 15)

        for (i = 0; i < length; i++)

            dst[i] = vector[i] * 0x7fff >> 3;

    else

        for (i = 0; i < length; i++)

            dst[i] = vector[i] << bits >> 3;



    return bits - 3;

}

static int virtio_ccw_hcall_notify(const uint64_t *args)

{

    uint64_t subch_id = args[0];

    uint64_t queue = args[1];

    SubchDev *sch;

    int cssid, ssid, schid, m;



    if (ioinst_disassemble_sch_ident(subch_id, &m, &cssid, &ssid, &schid)) {

        return -EINVAL;

    }

    sch = css_find_subch(m, cssid, ssid, schid);

    if (!sch || !css_subch_visible(sch)) {

        return -EINVAL;

    }

    if (queue >= VIRTIO_PCI_QUEUE_MAX) {

        return -EINVAL;

    }

    virtio_queue_notify(virtio_ccw_get_vdev(sch), queue);

    return 0;



}

void prepare_grab(void)

{

    int has_video, has_audio, i, j;

    AVFormatContext *oc;

    AVFormatContext *ic;

    AVFormatParameters ap1, *ap = &ap1;



    /* see if audio/video inputs are needed */

    has_video = 0;

    has_audio = 0;

    memset(ap, 0, sizeof(*ap));

    for(j=0;j<nb_output_files;j++) {

        oc = output_files[j];

        for(i=0;i<oc->nb_streams;i++) {

            AVCodecContext *enc = &oc->streams[i]->codec;

            switch(enc->codec_type) {

            case CODEC_TYPE_AUDIO:

                if (enc->sample_rate > ap->sample_rate)

                    ap->sample_rate = enc->sample_rate;

                if (enc->channels > ap->channels)

                    ap->channels = enc->channels;

                has_audio = 1;

                break;

            case CODEC_TYPE_VIDEO:

                if (enc->width > ap->width)

                    ap->width = enc->width;

                if (enc->height > ap->height)

                    ap->height = enc->height;

                if (enc->frame_rate > ap->frame_rate)

                    ap->frame_rate = enc->frame_rate;

                has_video = 1;

                break;

            default:

                abort();

            }

        }

    }



    if (has_video == 0 && has_audio == 0) {

        fprintf(stderr, "Output file must have at least one audio or video stream\n");

        exit(1);

    }



    if (has_video) {

        AVInputFormat *fmt1;

        fmt1 = av_find_input_format("video_grab_device");

        if (av_open_input_file(&ic, "", fmt1, 0, ap) < 0) {

            fprintf(stderr, "Could not find video grab device\n");

            exit(1);

        }

        /* by now video grab has one stream */

        ic->streams[0]->r_frame_rate = ap->frame_rate;

        input_files[nb_input_files] = ic;

        dump_format(ic, nb_input_files, v4l_device, 0);

        nb_input_files++;

    }

    if (has_audio) {

        AVInputFormat *fmt1;

        fmt1 = av_find_input_format("audio_device");

        if (av_open_input_file(&ic, "", fmt1, 0, ap) < 0) {

            fprintf(stderr, "Could not find audio grab device\n");

            exit(1);

        }

        input_files[nb_input_files] = ic;

        dump_format(ic, nb_input_files, audio_device, 0);

        nb_input_files++;

    }

}

static void ipvideo_decode_opcodes(IpvideoContext *s)

{

    int x, y;

    unsigned char opcode;

    int ret;

    static int frame = 0;

    GetBitContext gb;



    debug_interplay("------------------ frame %d\n", frame);

    frame++;



    /* this is PAL8, so make the palette available */

    memcpy(s->current_frame.data[1], s->avctx->palctrl->palette, PALETTE_COUNT * 4);



    s->stride = s->current_frame.linesize[0];

    s->stream_ptr = s->buf + 14;  /* data starts 14 bytes in */

    s->stream_end = s->buf + s->size;

    s->line_inc = s->stride - 8;

    s->upper_motion_limit_offset = (s->avctx->height - 8) * s->stride

        + s->avctx->width - 8;



    init_get_bits(&gb, s->decoding_map, s->decoding_map_size * 8);

    for (y = 0; y < (s->stride * s->avctx->height); y += s->stride * 8) {

        for (x = y; x < y + s->avctx->width; x += 8) {

            opcode = get_bits(&gb, 4);



            debug_interplay("  block @ (%3d, %3d): encoding 0x%X, data ptr @ %p\n",

                            x - y, y / s->stride, opcode, s->stream_ptr);



            s->pixel_ptr = s->current_frame.data[0] + x;

            ret = ipvideo_decode_block[opcode](s);

            if (ret != 0) {

                av_log(s->avctx, AV_LOG_ERROR, " Interplay video: decode problem on frame %d, @ block (%d, %d)\n",

                       frame, x - y, y / s->stride);

                return;

            }

        }

    }

    if (s->stream_end - s->stream_ptr > 1) {

        av_log(s->avctx, AV_LOG_ERROR, " Interplay video: decode finished with %td bytes left over\n",

               s->stream_end - s->stream_ptr);

    }

}

